\begin{proof}[{\bf Proof of Proposition \ref{s2}}] 
Let $x:=bS^{\sigma}-\bar{x}$. Since $x>0$, there exists $ \alpha_n\in (0,1)$ such that  $bS^{\sigma}\alpha_n^{\sigma}=\bar{x}$.  Define  $K_c,N,H$ by 
 \begin{align}
 N&=(\alpha_n+\epsilon)S,\quad pK_c=\epsilon S, \quad H=0
 \end{align}
where $\epsilon >0$ such that $\alpha_n+2\epsilon=1$ (so that $N+pK_c=S$). Precisely, $\epsilon=\frac{1}{2} \Big(1-\big(\frac{\bar{x}}{bS^{\sigma}}\big)^{\frac{1}{\sigma}} \Big)$.
With such $N,K_c$, we have $bN^{\sigma}>\bar{x}$, and hence, we can verify that
\begin{align}
g(K_c,N,H)&=\Big[A_c+{a}\Big(\big(b^{\frac{1}{\sigma}}\frac{S}{2}+\frac{\bar{x}^{\frac{1}{\sigma}}}{2}\big)^{\sigma}-\bar{x}\Big)\Big]\frac{1}{p^{\alpha}}  \Big(\frac{S}{2}-\frac{\bar{x}^{\frac{1}{\sigma}}}{2b^{\frac{1}{\sigma}}}\Big)^{\alpha}
\end{align}
$g(K_c,N,H)$ is increasing in $a$ and $b$. It will be higher than $F(S)$ when $a$ and $b$ are high enough because $F(S)$ does not depend on $(a,b)$. 

\end{proof}


\begin{proof}[{\bf Proof of Proposition \ref{G0}}]
We need an intermediate step.

\begin{claim}\label{G1}Assume that $a\bar{x}>A_c$. 
Denote 
 $N_1\equiv (\bar{x}/b)^{1/\sigma}$, $x_1\equiv \big(\frac{\alpha +\sigma}{\sigma} -\frac{\alpha }{\sigma}\frac{a\bar{x}-A_c}{a\bar{x}}\big)N_1$ and $$G_1(x)=\max\{\big(A_c+a(bN^{\sigma}-\bar{x})\big)K_{c}^{\alpha}: K_c,N\geq 0, pK_c+N\leq x,bN^{\sigma}\geq \bar{x} \}.$$
 We have that $x_1\geq N_1$.   
 The function $G_1$ is well-defined on the interval $[N_1,\infty)$, and $G_1(N_1)=0$. On the  interval $(N_1,\infty)$,  the function $G_1$ is strictly increasing,  continuously differentiable and $G_1'(x)>\frac{\alpha A x^{\alpha-1}}{p^{\alpha}}.$  $G_1(x)-A_cx^{\alpha}/p^{\alpha}$  is strictly increasing in $x$ and there exists a unique $x_2$ such that $G_{1}(x_2)=A_cx_2^{\alpha}/p^{\alpha}$. Moreover, $bx_2^{\sigma}-\bar{x}>0$.

\end{claim}





\begin{proof}[Proof of Claim \ref{G1}]

If $x\leq N_1$, then condition $bN^{\sigma}\geq \bar{x}$ implies that $N\geq N_1\geq x\geq N$. Then $x=N$, $pK_c=x-N=0$ and hence $G_1(x)=0$. 

Consider the case $x>N_1$.  Let $(K_c,N)$ be an optimal point. It is clear that $K_c>0$ and $N<x$.

If $N\leq N_1$, then $N= N_1$, $G_1(x)=A_cK_c^{\alpha}=A_c(x-N)^{\alpha}/p^{\alpha}=A_c(x-N_1)^{\alpha}/p^{\alpha}$ and 
$G_1'(x)=\alpha A_c(x-N_1)^{\alpha-1}/p^{\alpha}>\alpha A_cx^{\alpha-1}/p^{\alpha}$.

If $N\in (N_1,x)$ at optimal,  we write FOCs
\begin{align}
\sigma ab N^{\sigma-1}K_c^{\alpha}&=\lambda\\
\big(A_c+a(bN^{\sigma}-\bar{x})\big)\alpha K_{c}^{\alpha-1}&=p\lambda =p \sigma ab N^{\sigma-1}K_c^{\alpha}.
\end{align}
It follows that  $\big(A_c+a(bN^{\sigma}-\bar{x})\big)\alpha  = \sigma ab N^{\sigma-1}pK_c$ or equivalently
\begin{align}%\label{def-kc}\sigma ab \frac{pK_c}{x-pK_c}+\frac{\alpha (a\bar{x}-A_c)}{(x-pK_c)^{\sigma}}-\alpha ab=0\\
\label{def-N}\sigma ab \frac{x-N}{N}+\frac{\alpha (a\bar{x}-A_c)}{N^{\sigma}}-\alpha ab=0.
\end{align}
The left hand side (LHS) is strictly decreasing in $N$ because $a\bar{x}-A_c>0$. When $N=x$, the LHS equals $\frac{\alpha (a\bar{x}-A_c)}{x^{\sigma}}-\alpha ab<0$ because $x>N_1$.
When $N=N_1$, the LHS equals 
\begin{align}
 LHS(N_1)\equiv \sigma ab \frac{x-N_1}{N_1}+\frac{\alpha (a\bar{x}-A_c)}{(N_1)^{\sigma}}-\alpha ab.
\end{align}
Observe that $LHS(N_1)\geq 0$ if and only if 
$$x\geq x_1\equiv \frac{\alpha +\sigma}{\sigma} N_1-\frac{\alpha }{\sigma}N_1\frac{a\bar{x}-A_c}{a\bar{x}}= N_1+\frac{\alpha (N_1)^{1-\sigma}}{\sigma ab} \Big(\alpha ab (N_1)^{\sigma}-a\bar{x}+A_c\Big).$$

Therefore, we get that:
\begin{enumerate}

\item If $x\leq x_1$, then $N=N_1$ and $G_1(x)=A_c(x-N_1)^{\alpha}/p^{\alpha}$. In this case, we have
$$G_1'(x)=\frac{\alpha A_c(x-N_1)^{\alpha-1}}{p^{\alpha}}>
\frac{\alpha A x^{\alpha-1}}{p^{\alpha}}$$
because $N_1>0$ and $\alpha-1<0$.


\item 
If $x>x_1$, then the equation (\ref{def-N}) has a unique $N_x$ in the interval $(N_1,x)$. The optimal point $(K_c,N)$ is given by $N=N_x$ and $pK_c+N=S$. Moreover, when $x$ increases,  we have $N_x$, $x-N_x$ and $\frac{x-N_x}{N_x}$ increase. 

We have $G_1(x)=\big(A_c+a(bN^{\sigma}-\bar{x})\big)K_{c}^{\alpha}$ where $N$ is uniquely given by (\ref{def-N}) and $pK_c=S-N$. By computing directly or using the envelop theorem, we have
\begin{align}
G_1'(x)=\big(A_c+a(bN^{\sigma}-\bar{x})\big)\alpha K_{c}^{\alpha-1}>\frac{\alpha A x^{\alpha-1}}{p^{\alpha}}
\end{align}
because $bN^{\sigma}-\bar{x}>0$ and $pK_c<S$.

\item When $x$ tends to $x_1$, we have $N_x$ tends to $N_1$ and therefore $G_1'(x)=\big(A_c+a(bN^{\sigma}-\bar{x})\big)\alpha K_{c}^{\alpha-1}$ tends to $\frac{\alpha A_c(x-N_1)^{\alpha-1}}{p^{\alpha}}>\frac{\alpha A_cx^{\alpha-1}}{p^{\alpha}}$ because $\alpha<1$.
\end{enumerate}
To sum up, the function $G_1$ is continuously differentiable and $G_1'(x)>\frac{\alpha A x^{\alpha-1}}{p^{\alpha}}.$

\end{proof}

We now prove Proposition \ref{G0}. Observe that
\begin{align}
G_0(S)&\equiv \ma_{K_{c}, N, H}\Big\{G_1(x)+wA_hH^{\alpha_h}: x+H\leq S; x, H\geq 0 \Big\}.
\end{align}

Let $(x_g,H_g)$ be an optimal point. Since $G_1$ is differentiable,  we have the FOC $$G_1'(x_g)-\alpha_hwA_h(S-x_g)^{\alpha_h-1}=0.$$

Let $(x,S-x)$ be the unique pair such that $A_c(\frac{x}{p})^{\alpha}+wA_hH^{\alpha_h}=F(S)$. Then, we have $\frac{\alpha A x^{\alpha-1}}{p^{\alpha}}-\alpha_hwA_h(S-x)^{\alpha_h-1}=0$.

Since $G_1'(x_g)>\frac{\alpha A (x_g)^{\alpha-1}}{p^{\alpha}}$, we have $0>\frac{\alpha A (x_g)^{\alpha-1}}{p^{\alpha}}-\alpha_hwA_h(S-x_g)^{\alpha_h-1}$. Therefore, we have $x_g>x$ and hence $H_g<H$. It follows that 
\begin{align}
G_0'(S)&=\alpha_hwA_hH_g^{\alpha_h-1}>\alpha_hwA_hH_g^{\alpha_h-1}=F'(S).
\end{align}
So, $G_0(S)-F(S)$ is strictly increasing.



When $S$ is small enough, $G_0(S)-F(S)$ is negative. When $S$ is high enough, $G_0(S)-F(S)$ is positive (see, for example, point (ii) of Proposition \ref{s2}). So, there exists a unique $S^*$ such that $G_0(S^*)-F(S^*)=0$.

According to (\ref{GF}) and $G(S)\geq G_0(S)$ $\forall S$, we have $G(S)- F(S)=0$ $ \forall S\leq S^*$, and $G(S)- F(S)>0$ $ \forall S> S^*$. 


\end{proof}

\subsection{Dynamic analysis}
\label{appendix-proof}
\begin{proof}[{\bf Proof of Proposition \ref{basic}}] Since the function $G(\cdot)$ is continuous, strictly increasing, we can use the standard argument in dynamic programming  \citep*{amir96} 
to prove that the optimal path $(S_t)_t$ is monotonic. %Moreover,  since $G(\cdot)$  satisfies conditions in Proposition A\ref{no_zero} in Appendix \ref{general},  $S_t$ does not converge to zero.

We now prove that $S_t$ does not converge to zero. First,  following \citet*{kamiroy07}, we  have Euler condition in the form of  inequality \begin{eqnarray}\label{euler1} 
 \beta u'(c_{t+1})D^-f(S_{t+1}) \geq u'(c_t)\geq \beta u'(c_{t+1})D^+f(S_{t+1}).
\end{eqnarray}
where the  Dini derivatives of function $f$ are defined by $D^+f(x)=\limsupp_{\epsilon \downarrow 0}\frac{f(x+\epsilon)-f(x)}{\epsilon}$ and $D^-f(x)=\liminff_{\epsilon \downarrow 0}\frac{f(x)-f(x-\epsilon)}{\epsilon}$.

Suppose that $\lim_{t\to \infty}S_t=0$. According to budget constraints and the fact that $G(0)=0$, we have $\lim_{t\to \infty}c_t=0$. Since $\limm_{t\rightarrow +\infty}S_t=0$, there exists $t_0$ such that $\beta D^+G(S_{t+1})>1$ for every $t\geq t_0$. Consequently, $u'(c_t)\geq u'(c_{t+1})$ and hence $c_t\leq c_{t+1}$ for every $t\geq t_0$. This leads to a contradiction to the fact that $\limm_{t\rightarrow +\infty}c_t=0$.
\end{proof}

\begin{proof}[{\bf Proof of Lemma \ref{FS}}]
(1) If $x<x^*$, then $F(x)<F(x^*)=x^*$. If $x>x^*$, then $\frac{F(x)}{x}\leq \frac{F(x^*)}{x^*}=1$ since $F$ is concave.


(2) It is obvious that $S_t\leq x_t \forall t$. We prove 
 $x_t\leq \bar{S}$ $\forall t$ by induction argument. First, we see that $x_0\leq \bar{S}.$ Second, assume that $x_s\leq \bar{S}$ $\forall s\leq t$. If $X_0\leq x^*$, then  $x_t\leq \bar{S}=x^*$, then $x_{t+1}=F(x_t)\leq F(x^*)=x^*= \bar{S}$. If $X_0> x^*$,  then $x_t\leq \bar{S}=X_0$ and hence $x_{t+1}=F(x_t)=F(x_0)\leq x_1\leq \bar{S}$.

\end{proof}

\begin{proof}[{\bf Proof of Proposition \ref{poverty2}}]
%The proof is similar to that of Proposition \ref{dynamics1}.
 We will prove, by induction argument, that $b\bar{x}_t^{\sigma}\leq \bar{x}$ and $S_t\leq x_1$ $\forall t\geq 1$. 

When $t=1$. We have $N_1\leq S_1\leq X_0\leq x_1$, So, $bN_1^{\sigma}\leq b\bar{S}_1^{\sigma}\leq \bar{x}$. 

Assume that $b\bar{x}_t^{\sigma}\leq \bar{x}$ and $S_t\leq x_1$ $\forall t\leq T$. This implies that $N_T=0$, because otherwise we can reduce $N_T$ and augment $K_{c,T}$ in order to get a higher utility, which is a contradiction.

Since $N_T=0$, we have that $G(S_T)=F(S_T)$. Since $S_T\leq x_1$, we have $F(S_T)\leq F(x^*)=x^*$.

Hence, $S_{T+1}\leq G(S_T)\leq x^*$ and therefore $b\bar{x}_{T+1}^{\sigma}\leq bS_{T+1}^{\sigma} \leq b(x^*)^{\sigma}\leq \bar{x}$. We have finished our proof.

\end{proof}



\begin{proof}[{\bf Proof of Proposition \ref{dynamic-newtech}}]
We need intermediate steps.


\begin{lemma}\label{s4} Assume that $\alpha+\sigma\geq 1$. For any solution $K_c, N, H$ of the problem $(G_S)$, there exists the following limits
\begin{align}\label{ratio}
\limm_{S\rightarrow \infty}\theta_c=\frac{\alpha}{\alpha +\sigma }, \limm_{S\rightarrow \infty}\theta_n=\frac{\sigma}{\alpha +\sigma }, \limm_{S\rightarrow \infty}\theta_h=0.
\end{align}
