\theta_c=\frac{\alpha }{\sigma}\theta_n + \frac{\alpha \theta_n^{1-\sigma}(A_c-a\bar{x})}{ab\sigma S^{\sigma}}\\
%\frac{\theta_c}{\theta_n}=\frac{\alpha }{\sigma} + \frac{\alpha (A_c-a\bar{x})}{ab\sigma (S\theta_n)^{\sigma}}\\
\label{cn1}\text{or equivalently }\frac{S\theta_c}{S\theta_n}=\frac{\alpha}{\sigma} + \frac{\alpha (A_c-a\bar{x})}{\sigma ab (S\theta_n)^{\sigma}}.
\end{align}
From this, we get $\lim_{S\rightarrow \infty}(\frac{\sigma\theta_c}{\alpha\theta_n}-1)\theta_n^{\sigma}=0 $. By combining this with the fact that  $\sigma \leq 1$, we obtain $\lim_{S\rightarrow \infty}(\theta_c-\frac{\alpha }{\sigma}\theta_n)=0 $.



Notice that $b(S\theta_n)^{\sigma}>N$ for $S$ high enough.


We will prove that when $S$ tends to infinity, $S\theta_h$ is bounded from above, and hence $\lim_{S\rightarrow \infty}\theta_h=0$. To do so, we firstly prove that $\liminf_{S\rightarrow \infty}\frac{(S\theta_c)^{\alpha}}{(S\theta_n)^{1-\sigma}}>0$. Indeed, according to (\ref{cn1}), we have 
\begin{align}
\frac{(S\theta_c)^{\alpha}}{(S\theta_n)^{1-\sigma}}=
(S\theta_n)^{\alpha+\sigma-1} \Big(\frac{\alpha}{\sigma} + \frac{\alpha (A_c-a\bar{x})}{\sigma ab (S\theta_n)^{\sigma}}\Big)^{\alpha}
\end{align}
Suppose that there is a sequence $(S_k)$ tends to infinity such that $\lim_{k\rightarrow \infty}\frac{(S_k\theta_c)^{\alpha}}{(S_k\theta_n)^{1-\sigma}}=0$. Notice that 
\begin{align*}
\frac{(S\theta_c)^{\alpha}}{(S\theta_n)^{1-\sigma}}=
\frac{1}{(S\theta_n)^{(1-\sigma)(1-\alpha)}} \Big(\frac{\alpha}{\sigma ab}\big[A_c + a(b(S\theta_n)^{\sigma}-\bar{x})\big]\Big)^{\alpha}\geq 
\frac{1}{(S\theta_n)^{(1-\sigma)(1-\alpha)}} \Big(\frac{\alpha}{\sigma ab}A_c\Big)^{\alpha}
\end{align*} for any $S$ high enough,
which implies that  $\lim_{k\rightarrow \infty}S_k\theta_n=\infty$. However, this will follow that 
\begin{align}
\frac{(S_k\theta_c)^{\alpha}}{(S_k\theta_n)^{1-\sigma}}=
