%&=\frac{ \alpha_h w A_h p^{\alpha} }{\alpha^{\alpha} (\sigma ab )^{1-\alpha}} \theta_n^{(1-\alpha)(1-\sigma)} \frac{S^{\alpha_h-\alpha}}{(S^{\sigma})^{1-\alpha}\big(A_c+a(bS^{\sigma}\theta_n^{\sigma}-\bar{x})\big)^{\alpha}}.
%&=\frac{ \alpha_h w A_h p^{\alpha} }{\alpha^{\alpha} (\sigma ab )^{1-\alpha}} \theta_n^{(1-\alpha)(1-\sigma)} \frac{1}{S^{\sigma+\alpha-\alpha_h}\big(\frac{A_c-a\bar{x}}{S^{\sigma}}+ab\theta_n^{\sigma}\big)^{\alpha}}
%\end{align}
