\begin{lemma}\label{DGS}
Assume that $a\bar{x}-A_c\geq 0$. We have 
\begin{align}\label{DGbound}
D^+G(S)=\limsupp_{\epsilon \downarrow 0}\dfrac{G(S+\epsilon)-G(S)}{\epsilon}\geq \min\Big(F'(S^*),\Gamma(a,b,\bar{x})\Big)\\
\text{where } \Gamma(a,b,\bar{x}) \equiv \frac{\big(\frac{\alpha A_c}{p\sigma }\big)^{\alpha}
 \bar{x}^{\frac{-(1-\alpha) (1-\sigma)}{\sigma}}  a^{1-\alpha}b^{\frac{1-\alpha}{\sigma}}  
}{\Big(1+\frac{\alpha}{\sigma} + \Big(\frac{\alpha_h w A_h (p\sigma )^\alpha}{\sigma(\alpha A_c)^\alpha} \Big)^{\frac{1}{1-\alpha_h}} \frac{1}{a^{\frac{1-\alpha}{1-\alpha_h}}b^{\frac{\alpha_h-\alpha}{\sigma(1-\alpha_h)}}}\Big)^{\alpha}}
\end{align}
By consequence, when $a$ and $b$ are high enough and $\alpha_h+\frac{1}{\alpha}\geq 2$, we have $\beta D^+G(S)>1$ $\forall S>0$.
\end{lemma}

\begin{proof}[Proof of Lemma \ref{DGS}]{\bf Part 1}. We prove (\ref{DGbound}).  Let $S>S^*$. Consider the function 
\begin{subequations}
\begin{align}
(G_0): \quad G_0(S)&\equiv \ma_{K_{c}, N, H}\Big\{\big(A_c+a(bN^{\sigma}-\bar{x})\big)K_{c}^{\alpha}+wA_hH^{\alpha_h}\Big\}\\
\text{subject to: }&pK_c+N+H\leq S, \quad bN^{\sigma}\geq \bar{x} \text{ and } K_{c}, N, H\geq 0.
\end{align}
\end{subequations}
When $S>S^*$, we have $G(S)=G_0(S)$ and $bN^{\sigma}> \bar{x}$ at optimal. We will quantify $G_0'(S)$.   

Let $\lambda$ be the multiplier associated to the constraint $pK_c+N+H\leq S$, we have FOCs
\begin{align}
(abN^{\sigma}-(a\bar{x}-A_c)) \alpha K_c^{\alpha-1}&=p \lambda\\
ab\sigma N^{\sigma-1} K_c^{\alpha}&=\lambda\\
\alpha_h w A_h H^{\alpha_h-1}&=\lambda.
\end{align}


FOCs imply that $\alpha (abN^{\sigma}-(a\bar{x}-A_c)) =p ab\sigma N^{\sigma-1} K_c$ and hence
\begin{align}
\frac{\alpha}{\sigma}N\geq pK_c&=\frac{\alpha}{\sigma}N \Big(1-\frac{a\bar{x}-A_c}{abN^{\sigma}} \Big)>N\frac{\alpha A_c}{\sigma a\bar{x}}
\end{align}
because $a\bar{x}-A_c\geq 0$ and $bN^{\sigma}\geq \bar{x}$.


Since $ab\sigma N^{\sigma-1} K_c^{\alpha}=\alpha_h w A_h H^{\alpha_h-1}$, we  have 
\begin{align}
\frac{H^{1-\alpha_h}}{N^{1-\alpha_h}}&=\frac{\alpha_h w A_h}{ab\sigma}N^{1-\sigma-(1-\alpha_h)}K_c^{-\alpha}\\
&\leq \frac{\alpha_h w A_h}{ab\sigma}N^{1-\sigma-(1-\alpha_h)}\Big(N\frac{\alpha A_c}{p\sigma a\bar{x}}\Big)^{-\alpha}=\frac{\alpha_h w A_h}{ab\sigma}\Big(\frac{p\sigma a\bar{x}}{\alpha A_c}\Big)^{\alpha}N^{-(\alpha+\sigma-\alpha_h)}\\
&\leq \frac{\alpha_h w A_h}{ab\sigma}\Big(\frac{p\sigma a\bar{x}}{\alpha A_c}\Big)^{\alpha}(\frac{\bar{x}}{b})^{-\frac{\alpha+\sigma-\alpha_h}{\sigma}}=\frac{\alpha_h w A_h (p\sigma )^\alpha}{\sigma(\alpha A_c)^\alpha}  \frac{1}{a^{1-\alpha}b^{\frac{\alpha_h-\alpha}{\sigma}}}
\end{align}
Thus, we get that
\begin{align}
H \leq N\Big(\frac{\alpha_h w A_h (p\sigma )^\alpha}{\sigma(\alpha A_c)^\alpha} \Big)^{\frac{1}{1-\alpha_h}} \frac{1}{a^{\frac{1-\alpha}{1-\alpha_h}}b^{\frac{\alpha_h-\alpha}{\sigma(1-\alpha_h)}}}
\end{align}

Since $S=N+pK_c+H$, we have
\begin{align}
S\leq N+N\frac{\alpha}{\sigma} + N\Big(\frac{\alpha_h w A_h (p\sigma )^\alpha}{\sigma(\alpha A_c)^\alpha} \Big)^{\frac{1}{1-\alpha_h}} \frac{1}{a^{\frac{1-\alpha}{1-\alpha_h}}b^{\frac{\alpha_h-\alpha}{\sigma(1-\alpha_h)}}}
\end{align}
which implies that 
\begin{align}
N\Big(1+\frac{\alpha}{\sigma} + \Big(\frac{\alpha_h w A_h (p\sigma )^\alpha}{\sigma(\alpha A_c)^\alpha} \Big)^{\frac{1}{1-\alpha_h}} \frac{1}{a^{\frac{1-\alpha}{1-\alpha_h}}b^{\frac{\alpha_h-\alpha}{\sigma(1-\alpha_h)}}}\Big)\geq S \geq \Big(\frac{\bar{x}}{b}\Big)^{\frac{1}{\sigma}}
\end{align}


Denote $d\equiv a\bar{x}-A_c\geq 0$.  We have
\begin{subequations}
\begin{align*}
G_0(S)&= (abN^{\sigma}-d)K_{c}^{\alpha}+wA_hH^{\alpha_h}\\
G_0'(S)&= (abN^{\sigma}-d)\alpha K_{c}^{\alpha-1}K_{c}'(S)+ \sigma abN^{\sigma-1}K_{c}^{\alpha} N'(S) +\alpha_h wA_hH^{\alpha_h-1} H'(S)\\
&=\sigma abN^{\sigma-1}K_{c}^{\alpha} 
\end{align*}
\end{subequations}
because $pK_{c}'(S)+N'(S)+H'(S)=1$.


By combining this with $K_c\geq \frac{\alpha A_c}{p\sigma a \bar{x}}N$ and $\sigma<1$, we have
\begin{align}
G_0'(S)&=abN^{\sigma-1}K_{c}^{\alpha} \geq abN^{\sigma+\alpha-1}\Big(\frac{\alpha A_c}{p\sigma a \bar{x}}\Big)^{\alpha}\\
&\geq \Big(\frac{\alpha A_c}{p\sigma  \bar{x}}\Big)^{\alpha} a^{1-\alpha}b   \Big(\frac{\bar{x}}{b}\Big)^{\frac{\sigma+\alpha-1}{\sigma}}\frac{1}{\Big(1+\frac{\alpha}{\sigma} + \Big(\frac{\alpha_h w A_h (p\sigma )^\alpha}{\sigma(\alpha A_c)^\alpha} \Big)^{\frac{1}{1-\alpha_h}} \frac{1}{a^{\frac{1-\alpha}{1-\alpha_h}}b^{\frac{\alpha_h-\alpha}{\sigma(1-\alpha_h)}}}\Big)^{\alpha}}\\
&=
 \frac{\big(\frac{\alpha A_c}{p\sigma }\big)^{\alpha}
 \bar{x}^{\frac{-(1-\alpha) (1-\sigma)}{\sigma}}  a^{1-\alpha}b^{\frac{1-\alpha}{\sigma}}  
}{\Big(1+\frac{\alpha}{\sigma} + \Big(\frac{\alpha_h w A_h (p\sigma )^\alpha}{\sigma(\alpha A_c)^\alpha} \Big)^{\frac{1}{1-\alpha_h}} \frac{1}{a^{\frac{1-\alpha}{1-\alpha_h}}b^{\frac{\alpha_h-\alpha}{\sigma(1-\alpha_h)}}}\Big)^{\alpha}}\equiv \Gamma(a,b,\bar{x})
\end{align}



At point $S^*$, the right Dini derivative $D^+G(S^*)$ of $G$ is 
\begin{align}
D^+G(S^*)=\limsupp_{\epsilon \downarrow 0}\dfrac{G(S^*+\epsilon)-G(S^*)}{\epsilon}\geq \limsupp_{\epsilon \downarrow 0}\dfrac{F(S^*+\epsilon)-F(S^*)}{\epsilon}=F'(S^*).
\end{align}

When $S<S^*$, we have $G(S)=F(S)$ and hence $G'(S)=F'(S)\geq F'(S^*)$ because $F'$ is decreasing.

{\bf Part 2}. We prove that, when $a$ and $b$ are high enough and $\alpha_h+\frac{1}{\alpha}\geq 2$, we have $\beta D^+G(S)>1$ $\forall S>0$.

Observe that $\Gamma(a,b,\bar{x})$ is increasing in $a$ and $\beta \Gamma(a,b,\bar{x})>1 $ when $a$ is high enough.

When $\alpha_h+\frac{1}{\alpha}\geq 2$, we have $\frac{1-\alpha}{\sigma}+ \frac{\alpha_h-\alpha}{\sigma(1-\alpha_h)}\geq 0$ and therefore $\Gamma(a,b,\bar{x})$ is strictly increasing in $b$. In this case, it is easy to see that $\beta \Gamma(a,b,\bar{x})>1 $ when $b$ is high enough.

We now prove that $\beta F'(S^*)>1$ when $a$ or $b$ is high enough.  As in proof of point (ii) of Proposition \ref{s2}, we have that: If $bS^{\sigma}> \bar{x}$, then
\begin{align}\label{intermediate1}
G(S)\geq \Big[A_c+{a}\Big(\big(b^{\frac{1}{\sigma}}\frac{S}{2}+\frac{\bar{x}^{\frac{1}{\sigma}}}{2}\big)^{\sigma}-\bar{x}\Big)\Big]\frac{1}{p^{\alpha}}  \Big(\frac{S}{2}-\frac{\bar{x}^{\frac{1}{\sigma}}}{2b^{\frac{1}{\sigma}}}\Big)^{\alpha}>0
\end{align}

At point $S^*$ which depends on $a$ and $b$, we have $F(S^*)=G(S^*)$ and hence
\begin{align*}
\Big[A_c+{a}\Big(\big(b^{\frac{1}{\sigma}}\frac{S^*}{2}+\frac{\bar{x}^{\frac{1}{\sigma}}}{2}\big)^{\sigma}-\bar{x}\Big)\Big]\frac{1}{p^{\alpha}}  \Big(\frac{S^*}{2}-\frac{\bar{x}^{\frac{1}{\sigma}}}{2b^{\frac{1}{\sigma}}}\Big)^{\alpha}\leq F(S^*)\leq \max(A_c(S^*)^{\alpha},w_hA_hS^{\alpha_h}).
\end{align*}
We prove that $S^*$ tends to zero when $a$ or $b$ goes to infinity. Indeed, let, for example, $b$ tend to infinity. If $\liminf_{b\rightarrow \infty}S^*>0$, by using the property $\alpha+\sigma\geq 1>\max(\alpha,\alpha_h)$, we get that
\begin{align*}
\Big[A_c+{a}\Big(\big(b^{\frac{1}{\sigma}}\frac{S^*}{2}+\frac{\bar{x}^{\frac{1}{\sigma}}}{2}\big)^{\sigma}-\bar{x}\Big)\Big]\frac{1}{p^{\alpha}}  \Big(\frac{S^*}{2}-\frac{\bar{x}^{\frac{1}{\sigma}}}{2b^{\frac{1}{\sigma}}}\Big)^{\alpha}> \max(A_c(S^*)^{\alpha},w_hA_hS^{\alpha_h}).
\end{align*}
where $b$ is high enough,  a contradiction.

So, when $a$ or $b$ is high enough, $S^*$ is low enough and hence $\beta F'(S^*)>1$ since $F'(0)=\infty$.

\end{proof}

We are now ready to prove Proposition \ref{dynamic-newtech}. According to Lemma \ref{DGS}, we have $\beta D^+G(S)>1$ $\forall S>0$ when $a$ and $b$ are high enough.  According to Proposition 4.6 in  \citet*{kamiroy07}, we have that $\limm_{t\rightarrow \infty}S_t=\infty$. According to Lemma \ref{s4}, we obtain point 2 of Proposition \ref{dynamic-newtech}.


\end{proof}


\begin{proof}[{\bf Proof of Proposition \ref{drs}}]
 We observe that 
\begin{align*}
G(S)&\leq (A_c+abS^{\sigma})\frac{1}{p^{\alpha}} S^{\alpha}+wA_hS^{\alpha_h}
\leq \begin{cases}
 \frac{A_c+ab}{p^{\alpha}}+wA_h \text{ if } S\leq 1\\
 \Big(\frac{A_c+ab}{p^{\alpha}}+wA_h\Big) S^{\max(\alpha+\sigma, \alpha_h)}  \text{ if } S\geq 1.
\end{cases}
\end{align*}
By using $\max(\alpha+\sigma, \alpha_h)<1$, it is easy to prove that $S_t$ is bounded from above. Since $S_t$ is monotonic, it must converge to a finite value, say $S_d$. So, we have that $\beta D^-G(S_d)\geq 1\geq \beta D^+G(S_d)$, where the  Dini derivatives of a function $f$ are defined by $D^+f(x)=\limsupp_{\epsilon \downarrow 0}\frac{f(x+\epsilon)-f(x)}{\epsilon}$ and $D^-f(x)=\liminff_{\epsilon \downarrow 0}\frac{f(x)-f(x-\epsilon)}{\epsilon}$ (see, for instance, \cite{kamiroy07}). 

%\begin{eqnarray}\label{euler1} 
 %\beta u'(c_{t+1})D^-f(S_{t+1}) \geq u'(c_t)\geq \beta u'(c_{t+1})D^+f(S_{t+1}).
%\end{eqnarray}
%where the  Dini derivatives of function $f$ are defined by $D^+f(x)=\limsupp_{\epsilon \downarrow 0}\frac{f(x+\epsilon)-f(x)}{\epsilon}$ and $D^-f(x)=\liminff_{\epsilon \downarrow 0}\frac{f(x)-f(x-\epsilon)}{\epsilon}$. 

We consider three cases:

\begin{enumerate}
\item 
If $S_d<S^*$, then $G$ is differentiable at $S_d$ and $\beta G'(S_d)=1=\beta F'(S_b)$ which in turn implies that $S_d=S_b$.
\item 
If $S_d>S^*$, then $G$ is differentiable at $S_d$ and $\beta F'(S_b)=1=\beta G'(S_d)>\beta F'(S_d)$ which in turn implies that $S_d>S_b$ (because $F'(S)$ is decreasing).
\item 

If $S_d=S^*$, then we have 
$\beta F'(S_d)=\beta D^-G(S_d)\geq 1\geq \beta D^+G(S_d)\geq \beta F'(S_d).$ So, $S=S^*=S_b$.

\end{enumerate}
Suming up three cases, we have that $S_d\geq S_b$ in any case. Since $X_0<S_b$, we have $S_1<S_b\leq S$. Hence $S_t$ is increasing in $t$. Moreover, when $a$ and $b$ are high enough, we have $S_b>S^*$. In this case, we have $S_d>S^*$. According to the three cases mentioned above, we must have $S_d>S_b$. 

%We also notice that $S_d$ is increasing in $w,A_h$
\end{proof}


