with  $q=p-p^\prime$ and $\epsilon$ the $V$ polarization vector.
The form factors are not all independent:  $A_3$ is given by
\be
A_3(q^2) =\frac {m_{B_q} + m_V }{ 2 m_V}  A_1(q^2) - \frac{m_{B_q} -
m_V }{2 m_V}  A_2(q^2)  
\ee
with $A_3(0) = A_0(0)$.  $T_1(0) = T_2(0)$ follows from the  identity 
$\displaystyle
\sigma_{\mu \nu} \gamma_5 = - \frac{i }{2}  \epsilon_{\mu \nu \alpha \beta} \sigma^{\alpha \beta}$
(with $\epsilon_{0 1 2 3}=+1$).

In our analysis we use the  determination  in \cite{Bharucha:2015bzk} based on light-cone QCD sum rules (see also  \cite{Gubernari:2023puw}).  Defining the "conformal" variable 
\be
z(t)=\frac{\sqrt{t_+-t}-\sqrt{t_+-t_0}}{\sqrt{t_+-t}+\sqrt{t_+-t_0}} \,   \label{zvar}
\ee
with $t_\pm=(m_{B_q} \pm m_V)^2$ and $t_0=t_+ \left(1-\sqrt{1-\frac{t_-}{t_+}}\right)$,
a  generic form factor $F_i$ is written as the sum of the first three terms of the $z-$expansion
\be
F_i(q^2)=\frac{1}{1-\frac{q^2}{m_{R,i}^2}}\sum_{k=0}^{2}\alpha_k^i \left[z(q^2)-z(0) \right]^k \,\, , \label{z-exp}
\ee
 with parameters $\alpha_k^i$ and   $m_{R,i}$.   The value of  $m_{R,i}$ is close to the mass of the lightest t-channel resonance involved in the various terms in  \eqref{a1}, \eqref{t1}. 
 The parameters  are determined for  $V,\,A_1,\,A_0,\,A_{12}$ and $T_1,\,T_2$, $T_{23}$ in \cite{Bharucha:2015bzk}, defining
\bea
A_{12}(q^2)&=& \frac{(m_{B_q}+m_V)^2(m_{B_q}^2-m_V^2-q^2)A_1(q^2)-\lambda(m_{B_q}^2,m_V^2,q^2)A_2(q^2)}{16m_{B_q} m_V^2(m_{B_q}+m_V)}\nn \\
T_{23}(q^2)&=& 
 \frac{(m_{B_q}^2-m_V^2)(m_{B_q}^2+3m_V^2-q^2)T_2(q^2)-\lambda(m_{B_q}^2,m_V^2,q^2)T_3(q^2)}{8m_{B_q} m_V^2(m_{B_q}-m_V)}\,\,  .
 \eea
