\nn
\\
A_{\parallel L,R}(q^2)  & =& - N(q^2) \sqrt{2}(m_B^2 - m_{K^*}^2) \bigg[ \left[ (C_9^{\rm eff} - C_9^{{\rm eff}\prime}) \mp (C_{10}^{\rm eff}- C_{10}^{{\rm eff}\prime}) \right] 
\frac{A_1(q^2)}{m_B-m_{K^*}}
\nonumber\\
&+&\frac{2 (m_b-m_s)}{q^2} (C_7^{\rm eff} - C_7^{{\rm eff}\prime}) T_2(q^2)
