 \left[ (C_9^{\rm eff} - C_9^{{\rm eff}\prime}) \mp (C_{10}^{\rm eff} - C_{10}^{{\rm eff}\prime}) \right]
\\
 &\times & 
\bigg[ (m_B^2 - m_{K^*}^2 - q^2) ( m_B + m_{K^*}) A_1(q^2) 
 -\lambda_H \frac{A_2(q^2)}{m_B + m_{K^*}}
\bigg] 
\nonumber\\
&+& {2  (m_b-m_s)}(C_7^{\rm eff}- C_7^{{\rm eff}\prime}) \bigg[
