-\frac{\lambda_H}{m_B^2 - m_{K^*}^2} T_3(q^2) \bigg]
\bigg\},\nn \\
 A_{t \, L,R}(q^2)  &=&- \frac{N(q^2)}{\sqrt{q^2}}\lambda_H^{1/2}  \big[ (C_9^{\rm eff} - C_9^{{\rm eff}\prime})  \mp (C_{10}^{\rm eff} - C_{10}^{{\rm eff}\prime})  \Big] A_0(q^2) .\nn 
