% \end{equation}
Then, the following holds for the second-order derivatives of $\airy$ in physical space:
\begin{equation}\label{eq:secondOrderDerivatives}
\begin{split}
    \left[
    \begin{array}{cc}
         \frac{\partial^2 \airy}{\partial x^2}&  \frac{\partial^2 \airy}{\partial x\partial y}\\
         \frac{\partial^2 \airy}{\partial x\partial y} & \frac{\partial^2 \airy}{\partial y^2}
    \end{array}
    \right]
    &=
    \mappingJacobianInvT
    \lb
    \begin{array}{cc}
         \frac{\partial^2 \airyRef}{\partial \xi^2}&  \frac{\partial^2 \airyRef}{\partial \xi\partial \eta}\\
         \frac{\partial^2 \airyRef}{\partial \xi\partial \eta} & \frac{\partial^2 \airyRef}{\partial \eta^2}
    \end{array}
    \rb
    \mappingJacobianInv
    \\%\nonumber
    &+
    \lb
    \begin{array}{cc}
         \frac{\partial^2\xi}{\partial x^2}\frac{\partial\airyRef}{\partial\xi} + \frac{\partial^2\eta}{\partial x^2} \frac{\partial\airyRef}{\partial\eta} & \frac{\partial^2\xi}{\partial x \partial y}\frac{\partial\airyRef}{\partial\xi} + \frac{\partial^2\eta}{\partial x \partial y} \frac{\partial\airyRef}{\partial\eta}\\
         \frac{\partial^2\xi}{\partial x \partial y}\frac{\partial\airyRef}{\partial\xi} + \frac{\partial^2\eta}{\partial x \partial y} \frac{\partial\airyRef}{\partial\eta} & \frac{\partial^2\xi}{\partial y^2}\frac{\partial\airyRef}{\partial\xi} + \frac{\partial^2\eta}{\partial y^2} \frac{\partial\airyRef}{\partial\eta} 
    \end{array}
    \rb
\end{split}
\end{equation}
