    \begin{tabular}{lcc}
        \toprule
                & Horizontal  & Vertical \\
        \midrule
        \rule{0pt}{20pt}
        Top     & \multicolumn{2}{c}{$\int_{0}^{L} \left|\traction_i\right|^2\,dx$} \\
        \rule{0pt}{20pt}
        Bottom  & \multicolumn{2}{c}{$\int_{0}^{L} \left|\traction_i\right|^2\,dx$} \\
        \rule{0pt}{20pt}
        Right   & $\lp\int_{0}^{H_L} \traction_{x}\,dy -Q\rp^2$   & $\lp\int_{0}^{H_L} \traction_{y}\,dy -P\rp^2$ \\
        \bottomrule
    \end{tabular}
    \caption{Parabolic-shaped cantilever: quantities to be minimized for a weak enforcement of the boundary conditions.}
