	\subsection{Tranmission Performance}
	\label{subsec: perf}
	%\textbf{Definition of STP:} 
	Given a wireless link, the signal can be successfully received and decoded only when the received SINR at the receiver exceeds a given threshold. For the reference link from the PA $p_i$ to the user $u_i$, let $\gamma_0$ be the SINR threshold at $u_i$. The \textit{successful transmission probability (STP)} of the reference link, denoted by $\mathcal{P}_{s}$, is given by $\mathbb{P}\left(\gamma_u^i > \gamma_0 \right)$. Referring to \cref{Eq-gamma-u0,Eq-Power,Eq-Interference}, $\mathcal{P}_{s}$ can be evaluated by~\cref{pro1}.

	\begin{proposition} Given $R = \sum_{k \in \mathcal{K}/\{i\}} r_k$ and $r_k = ((x_u^k - x_u^i)^2 + (kd - y_u^i)^2 + h^2 ) ^{-1}$, the STP $\mathcal{P}_{s}$ can be evaluated by the Cumulative Distribution Function (CDF) of $R$, i.e.,
		\vspace{-0.3cm}

		{\small
			\begin{align*}
				&\mathcal{P}_{s}=F_{R} \left(z\right),\text{where } z= \frac{((id-y_u^i)^2 + h^2)^{-1}}{\gamma_0} - \frac{\sigma^2}{P_t}.
		\end{align*}}
		\label{pro1}
	\end{proposition}
	\vspace{-0.5cm}
	\noindent \textit{Proof.} The proof is provided in Appendix~\ref{proof_pro1}. \hfill $\blacksquare$

	Referring to \cref{pro1}, the calculation of $\mathcal{P}_{s}$ needs to further find $F_{R} \left(z\right)$. Recall that each PA's location is align with its served user and all users are independently distributed, and hence $F_{R} \left(z\right)$ can be derived accordingly. Thus, we have the theoretical model of $\mathcal{P}_{s}$ as given in \cref{the1}. 

	%can be calculated. 
	\begin{theorem} %Given %the waveguide with settings $L,K$, and $(2K+1)d=D$, and 
		The STP $\mathcal{P}_{s}$ of the link from $p_i$ to $u_i$ is given by
		\vspace{-0.9cm}

		{\small
			\begin{align*}
				& \mathcal{P}_{s} = \frac{1}{2} - \frac{1}{\pi} \left(\frac{1}{L}\right)^{2K} \int_0^{\infty} \mathrm{Im}\left(  
				\underbrace{\int_{-\frac{L}{2}}^{\frac{L}{2}} \dots \int_{-\frac{L}{2}}^{\frac{L}{2}}}_{2K} e^{jt A} \underbrace{\mathbf{d} \dots \mathbf{d}x_u^k}_{k \in \mathcal{K}/\{i\}} 
				\right) \frac{\mathbf{d}t}{t},\\
				%&\text{where }%C\approx0.577215 \text{ and } 
				&\text{where }A=\frac{\sigma^2}{\eta P_t}+\sum_{k \in \mathcal{K}/\{i\}}(\hat{r}_k ) ^{-1}-\frac{(\hat{r}_0)^{-1}}{\eta \gamma_0},\hat{r}_0=(id-y_u^i)^2 + h^2,\\
				&\hat{r}_k=(x_u^k - x_u^i)^2 + (kd - y_u^i)^2 + h^2, \mathrm {\mathrm{Im}}(\cdot) \text{ is the imaginary part}.
			\end{align*}%
		}%
		\label{the1}
	\end{theorem}
	\vspace{-0.5cm}
	\noindent \textit{Proof.} The proof is provided in Appendix~\ref{proof_the1}. \hfill $\blacksquare$

