\begin{proposition}
\label{P3.4}
Let $f_{1},f_{2}:X\to\R_\infty$ be convex, $\bx\in\dom f_{1}\cap\dom f_2$, and $0\in\sd f_1(\bx)+\sd f_2(\bx)$.
Then the pair $\{f_{1},f_{2}\}$ is uniformly lower semicontinuous on $X$.
\end{proposition}
\begin{proof}
Let $x_{1}^{\ast }\in \partial f_{1}(\bar{x})$,
$x_{2}^{\ast }\in \partial f_{2}(\bar{x})$ and $x_{1}^{\ast }+x_{2}^{\ast}=0$.
Then
\begin{gather*}
f_1(x)\ge f_1(\bar x)+\langle x_1^*,x-\bar x\rangle
\qdtx{for all}
x\in X,\\
f_2(u)\ge f_2(\bar x)+\langle x_2^*,u-\bar x\rangle
\qdtx{for all}
u\in X,
\end{gather*}
and consequently,
\begin{gather*}
f_1(x)+f_2(u)\ge f_1(\bar x)+f_2(\bar x)+\langle x_1^*,x-u\rangle
\qdtx{for all}
x,u\in X.
\end{gather*}
Hence,
\begin{equation*}
\Lambda_X (\{f_{1},f_{2}\})=\liminf_{\substack{\left\Vert x-u\right\Vert\rightarrow0}}(f_1(x)+f_2(u))\ge f_{1}(\bar{x})+f_{2}(\bar{x})\ge\inf(f_{1}+f_{2}),
\end{equation*}
i.e., $\{f_{1},f_{2}\}$ is uniformly lower semicontinuous on $X$.
\qed
\end{proof}
