\begin{lemma}
\label{reduction}
Let $X$ be separable, $f_{t}$ $(t\in T)$ be \lsc.
%and denote $f:=\sup_{t\in T}f_{t}$.
If $T$ is uncountable, then there exists a countable subset $D\subset T$ such that
{$\sup_{t\in T}f_{t}=\sup_{t\in D}f_{t}$}.
\end{lemma}

\begin{proof}
Let $T$ be uncountable.
Fix
an arbitrary rational number $r$.
Denote $f:=\sup_{t\in T}f_{t}$, $U:=\{x\in X\mid f(x)>r\}$ and $U_t:=\{x\in X\mid f_t(x)>r\}$ $(t\in T)$.
If $f(x)>r$
for some $x\in X$, then there is a $t\in T$ such that $f_t(x)>r$.
Hence,
%$$\{x\in X\mid f(x)>r\}
%\subset \bigcup_{t\in T}\{x\in X\mid f_t(x)>r\}.$$
{$U\subset\bigcup_{t\in T}U_t$}.
For each $t\in T$, the set
%$\{x\in X\mid f_t(x)>r\}$
{$U_t$}.
is open since $f_t$ is \lsc, while the (open, hence, separable) set
%$\{x\in X\mid f(x)>r\}$
{$U$}
endowed with the induced metric topology of $X$ is Lindel\"{o}f
(i.e., from any open cover of $U$ we
can extract a countable subcover \cite{Mun00}).
