\begin{corollary}
\label{C5}
Let $\bx\in X$ be a solution of problem \eqref{problemp}, and Slater condition \eqref{Sl} hold.
%Then
\begin{enumerate}
\item
\label{C5.1}
There exists a solution $(\lambda_{1},\lambda _{2},\ldots )\in \ell_{+}^{1}$, $\lambda _{\infty }\in\R_+$ of problem \eqref{problemd}, i.e.,
\begin{gather}
\label{C5-1}
f_0(\bx)=\inf\Big(f_0
+
%\overline{\sum_{k\ge1}}
{\overline{\sum_{k\in\N}}}
\la_k f_k
+\lambda _{\infty }f_{\infty}\Big).
\end{gather}
Moreover, for any solution of problem \eqref{problemd}, the infimum in \eqref{C5-1} is attained at $\bx$, and the complementary slackness conditions hold:
\begin{gather}
\label{C5-2}
\lambda_{k}f_{k}(\bx)=0\quad (k\in\N\cup \{\infty\}).
\end{gather}
\item
\label{C5.2}
For any $m=0,1,\ldots$,
there exists a solution $(\lambda_{1},\lambda _{2},\ldots )\in \ell_{+}^{\infty}$ of problem \eqref{problemdmas}, i.e.,
\begin{gather}
\label{C5-3}
f_0(\bx)=\inf\Big(f_{0}+\sum_{k=1}^m\lambda _{k}f_{k}+
\sum_{k=m+1}^{+\infty}\lambda _{k}f_{k}^+\Big).
\end{gather}
Moreover, for any solution of problem \eqref{problemdmas}, the infimum in \eqref{C5-3} is attained at $\bx$, and the (partial) complementary slackness conditions hold:
\begin{gather}
\label{C5-4}
\lambda_{k}f_{k}(\bx)=0\quad (k=1,\ldots,m).
\end{gather}
\end{enumerate}
\end{corollary}
\begin{proof}
The first parts of both assertions are direct consequences of representations \eqref{T4-2} in Theorem \ref{tmain}.
Since $\bx\in X$ is a solution of problem \eqref{problemp}, we have $f_k(\bx)\le0$ for all $k\in\N$, and consequently, $f_\infty(\bx)\le0$.
If $(\lambda_{1},\lambda _{2},\ldots )\in \ell_{+}^{1}$, $\lambda _{\infty }\in\R_+$ is a solution of problem \eqref{problemd}, then, by \eqref{C5-1},
\begin{gather*}
f_0(\bx)\leq f_0(\bx)
+\overline{\sum_{k\in\N}}\la_k f_k(\bx)
+\lambda _{\infty }f_{\infty}(\bx),
\end{gather*}
and consequently, conditions \eqref{C5-2} are satisfied, and the infimum in \eqref{C5-1} is attained at $\bx$.
Similarly, if for some $m=0,1,\ldots$,
$(\lambda_{1},\lambda _{2},\ldots )\in \ell_{+}^{\infty}$ is a solution of problem \eqref{problemdmas}, then, by \eqref{C5-3}, taking into account that $f_{k}^+(\bx)=0$ for all $k=m+1,\ldots$,
\begin{gather*}
f_0(\bx)\leq f_0(\bx)
+\sum_{k=1}^m\lambda _{k}f_{k}(\bx),
\end{gather*}
and consequently, conditions \eqref{C5-4} are satisfied, and the infimum in \eqref{C5-3} is attained at~$\bx$.
\qed\end{proof}
