\section{Central Limit Theorems for Partial Sums of Long Memory Linear Time Series}
As explained in the introduction,
our goal is to show that the centered and scaled subordinated linear time series
$$n^{-d-1/\min(\nu,2)}\sum_{t=1}^n
(
G_n(X_t)
-
\EE[G_n(X_0)]
)
$$
has the same asymptotic behavior as
\[
\left.
\frac{\mathrm{d}}{\mathrm{d}x}
\EE[G_n(X_0+x)]
\right|_{x=0}
n^{-d-1/\min(\nu,2)}\sum_{t=1}^n
X_t
\,.
\]
To derive central limit theorems from such a result, we rely on well-known central limit theory for partial sums of long memory linear time series.
For a proof of the latter we refer to \cite[Theorem~4.6 ($\alpha = 2$) and Theorem~4.17 ($\alpha\in(1,2)$)]{beranLongMemoryProcessesProbabilistic2013}.
   \begin{theorem}[Central Limit Theorems for Partial Sums]
     \label{thm:clt_partsum}
     Let Assumptions~\ref{asu:coef} and~\ref{asu:f} hold. Then
   \begin{align*}
     n^{-d-1/\alpha}
    \sum_{t=1}^n
    X_t
    \ \stackrel{\mathrm{d}}{\longrightarrow} \
    Z_\alpha
    \qquad\text{as}\ n\to\infty\,,
  \end{align*}
  where
  \begin{align*}
      Z_\alpha
    &
    \qquad
    \text{has distribution}
    \qquad
    \begin{cases}
      \mathcal{N}(0,\sigma^2)
      &\qquad\text{if}\qquad\alpha = 2 \ \text{with $\EE[\varepsilon^2]<\infty$,}
      \\
      S\alpha S(\eta)
      &\qquad\text{if}\qquad
      \alpha\in(1,2)\,,
    \end{cases}
  \end{align*}
  with
  variance
\begin{align*}
    \sigma^2
    \ &:= \
      c_a^2\EE[\varepsilon^2]
      \frac
      {
      B(1-2d,d)}
      {d(2d+1)}
  \intertext{or scale}
  \eta
  \ &:= \
\frac{c_a}{d}
    \cdot
    \left(
    A
    \cdot
      \frac
      {\Gamma(2-\alpha)\cos(\pi\alpha/2)}
      {1-\alpha}
      \right)^{1/\alpha}
    \left(
    \int_{-\infty}^{1}
    \left(
    (1-v)^{d}_+
    -
    (-v)^d_+
    \right)^{\alpha}
    \,\mathrm{d}v
    \right)^{1/\alpha}
      \,.
  \end{align*}
   \end{theorem}
   \begin{remark}
     We define the distribution $S\alpha S(\eta)$ in the usual sense, having characteristic function $x \mapsto  \exp(-\eta^\alpha|x|^\alpha)$.
     Also, it may not be immediately obvious that the integral in the definition of $\eta$ is finite in our setting. To clarify, using Jensen's inequality and the condition $1<(1-d)\alpha<2$, we have
\begin{align*}
  &
  \int_1^\infty
  \left(
  (1+v)^d
  \ - \
  v^d
  \right)^{\alpha}
  \,\mathrm{d}v
  \ = \
  \int_1^\infty
  \left(
  d
  \int_0^1
  (v+s)^{-(1-d)}
  \,\mathrm{d}s
  \right)^{\alpha}
  \,\mathrm{d}v
  \\&
  \ \lesssim \
  \int_1^\infty
  \left(
  \int_0^1
  (v+s)^{-(1-d)\alpha}
  \,\mathrm{d}s
  \right)
  \,\mathrm{d}v
  \\&
  \ = \
  \int_0^1
  \left(
  \int_1^\infty
  (v+s)^{-(1-d)\alpha}
  \,\mathrm{d}v
  \right)
  \,\mathrm{d}s
  \\&
  \ \le \ 
  \int_1^\infty
  v^{-(1-d)\alpha}
  \,\mathrm{d}v
    \ < \
  \infty\,.
\end{align*}
Therefore,
\begin{align*}
  &
  \int_{-\infty}^1
    \left(
    (1-v)^{d}_+
    -
    (-v)^d_+
    \right)^{\alpha}
    \,\mathrm{d}v
    \ = \
    \int_0^1
    (1-v)^{d\alpha}
    \,\mathrm{d}v
    \ + \
    \int_{1}^\infty
    \left(
    (1+v)^d
    \ - \
    v^d
    \right)^\alpha
    \,\mathrm{d}v
    \ < \
    \infty\,.
\end{align*}
   \end{remark}
\section{Auxiliary Results}
In this section we collect a host of results that are subsequently used in the proofs, but may also be of independent interest.
\subsection{Martingale Difference Inequality}
We start this section by recalling---and refining---a fundamental inequality for martingale difference arrays (cf.~\cite{bahrInequalities$r$thAbsolute1965})
which is satisfied in particular by independent, centered random variables.
\begin{lemma}[Martingale Difference Inequality]
  \label{lem:bahr}
  Let $p\in[1,2]$, and $(Y_{m,i}\,, i=1, \ldots,m\,, m\in\NN )\subset L^p(\PP)$ be an
  array of random variables satisfying
\begin{align}
  \label{eq:bahr:cond:1}
  \EE
  \Bigg[
  Y_{m,\ell + 1} \, \Bigg{|} \, \sum_{i=1}^{\ell}Y_{m,i}
  \Bigg]
  \ = \
  0
  \qquad\text{for all}\ 1\le \ell \le m-1
  \ \text{and all}\  m\in\NN\,.
\end{align}
\begin{enumerate}
  \item
It holds that
\begin{align}
  \label{eq:bahr:fi}
  \EE
  \left|
  \sum_{i=1}^{m}
  Y_{m,i}
  \right|^p
  \ \le \
  2
  \sum_{i=1}^{m}
  \EE
  \left|
  Y_{m,i}
  \right|^p
  \qquad\text{for all}\ m\in\NN\,.
\end{align}
\item
If there exists a sequence $(Y_i)_{i\in\NN}\subset L^p(\PP)$ such that
  \begin{align}
    \label{eq:bahr:cond:2}
    \liminf_{m\to\infty}
    \sum_{i=1}^m
    Y_{m,i}
     =
    \sum_{i=1}^{\infty}
    Y_{i}
    \quad\text{$\PP$-almost surely, and }\quad
    \liminf_{m\to\infty}
    \sum_{i=1}^m
    \EE|
    Y_{m,i}
    |^p
    \le
    \sum_{i=1}^\infty
    \EE|
    Y_{i}
    |^p
    \,,
  \end{align}
  then
\begin{align}
  \label{eq:bahr:infty}
  \EE
  \left|
  \sum_{i=1}^{\infty}
  Y_i
  \right|^p
  \ \le \
  2 \sum_{i=1}^{\infty}
  \EE
  \left|
  Y_i
  \right|^p
  \,.
\end{align}
\end{enumerate}
  \end{lemma}
\begin{proof}
  Part (i) is exactly~\cite[Theorem~2]{bahrInequalities$r$thAbsolute1965}.
  To prove part (ii),
  we apply Fatou's lemma together with \eqref{eq:bahr:fi} and \eqref{eq:bahr:cond:2} to obtain
  \begin{align*}
  \EE
  \left|
  \sum_{i=1}^{\infty}
  Y_i
  \right|^p
    \ = \
  \EE \left(
  \liminf_{m\to\infty} \left|
  \sum_{i=1}^{m}
    Y_{m,i}
  \right|^p \right)
  \ \le \
    \liminf_{m\to\infty}
  \EE
  \left|
  \sum_{i=1}^{m}
    Y_{m,i}
  \right|^p
  & \ \le \
    \liminf_{m\to\infty}
    2
  \sum_{i=1}^{m}
  \EE
  \left|
    Y_{m,i}
  \right|^p \\
  &\le
    2
  \sum_{i=1}^{\infty}
  \EE
  \left|
  Y_i
  \right|^p
  \,
  \end{align*}
  as announced.
\end{proof}

\subsection{Regularity of Distribution Functions and their Derivatives}
For $\gamma\in (0,1)$, we define
\begin{align*}
  g_\gamma \ :\  \mathbb{R} \to (0,1], \qquad x\ \mapsto \ g_\gamma(x) \ =\  \frac{1}{(1 + |x|)^{\gamma + 1}}.
\end{align*}
For $k\in\NN$, we define the truncated time series as
\begin{align*}
  X_{t,k}
  \ := \ \sum_{j=0}^k
  a_j \varepsilon_{t-j}
  \qquad\text{and}\qquad
  \widetilde{X}_{t,k}
  \ := \
  X_t
  \ - \ X_{t,k}
  \ = \ \sum_{j=k+1}^\infty
  a_j \varepsilon_{t-j}
  \,.
\end{align*}
By convention, we write $X_{t,\infty}:=X_t$. In the following, let $f_k$ denote the density of $X_{0,k}$, and $f_{\infty}$ denote the density of $X_{0,\infty}=X_0$.
Note that
$X_{0,k}=_{d} X_{t,k}$ for all $t\in\mathbb{Z}$, due to stationarity of the sequence $(\varepsilon_t)$. 
The next lemma is needed when dealing with heavy tails ($\alpha\in(1,2)$). It's a substitute for the mean value theorem that may be applied in settings with finite fourth moments (compare \cite{koulAsymptoticsEmpiricalProcesses2001, hoAsymptoticExpansionEmpirical1996}). Also note that, as explained in the introduction, we assimilate the case $\alpha=2$ to fit in the framework of $\alpha\in(1,2)$, which is essentially done here.
\begin{lemma}
  \label{lem:f}
  Let Assumptions~\ref{asu:coef} and~\ref{asu:f} hold.
  Then there exists $k_0 \in \NN$ such that
  for all $k>k_0$ the distribution functions of $X_0$ and $X_{0,k}$
  belong to $C^2(\RR)$.
  Furthermore, for all $\gamma\in(0,\alpha-1)$ and $r\in (1,2)$ with $1+\gamma<r<\alpha$ and $1/(1-d)<r$, 
  it holds for $x,y\in \RR$ with $|x-y|\le 1$ and all $k>k_0$
  \begin{align}
    \label{lem:f:1}
    |f_{\infty}^{(1)}(x)|
    \ + \
    |f_k^{(1)}(x)|
    &
    \ \lesssim \
    g_\gamma(x)
    \,,
    \\
    \label{lem:f:2}
    |
    f_{\infty}^{(1)}(x)
    -
    f_{\infty}^{(1)}(y)
    |
    \ + \
    |
    f_k^{(1)}(x)
    -
    f_k^{(1)}(y)
    |
    &
    \ \lesssim \
    |x-y|
    \cdot
    g_\gamma(x)
    \,,
    \\
    \label{lem:f:3}
    |
    f_{\infty}^{(1)}(x)
    -
    f_k^{(1)}(x)
    |&
    \ \lesssim \
    k^{-(1-d) + 1/r}\cdot
    g_\gamma(x)
    \,,
  \end{align}
  where $\lesssim$ is $\le$ up to a constant $C_{\gamma,r}>0$ only depending on $\gamma$ and $r$.
\end{lemma}
\begin{proof}
  Under Assumption~\ref{asu:f}.(ii),
  the statement is proved in
  \cite[Lemma~4.2]{koulAsymptoticsEmpiricalProcesses2001}.
  Under Assumption~\ref{asu:f}.(i),
   a proof of a slightly different statement is found in
  \cite[Lemma~2]{giraitisCentralLimitTheorem1999}.
  Indeed, the only difference is in \eqref{lem:f:1}-\eqref{lem:f:3}, that is, \cite[Lemma~2]{giraitisCentralLimitTheorem1999} prove that
\begin{align*}
    |f_{\infty}^{(1)}(x)|
    \ + \
    |f_k^{(1)}(x)|
    &
    \ \lesssim \
    g_1(x)
    \,,
    \\
    |
    f_{\infty}^{(1)}(x)
    -
    f_{\infty}^{(1)}(y)
    |
    \ + \
    |
    f_k^{(1)}(x)
    -
    f_k^{(1)}(y)
    |
    &
    \ \lesssim \
    |x-y|
    \cdot
    g_1(x)
    \,,
    \\
    |
    f_{\infty}^{(1)}(x)
    -
    f_k^{(1)}(x)
    |&
    \ \lesssim \
    k^{2d-1}\cdot
    g_1(x)
    \,.
  \end{align*}
  Since $g_1\le g_\gamma$ for $\gamma\in(0,1)$, we immediately recover \eqref{lem:f:1} and \eqref{lem:f:2}.
  The only remaining difference is in the third inequality.
  For this, note that
  $
    k^{2d-1}
    \ \le \
    k^{-(1-d) + 1/r}
  $
  due to
  \begin{align*}
    (2d-1)
    \ + \
    (1-d) - 1/r
    \ = \
    d
    \ - \
    1/r
    \ \le \
    1
    \ - \
    \frac{2}{\alpha}
       \
       \le
    \
    0
  \end{align*}
  since
  $1/\alpha<1/r$, $d<1-1/\alpha$, and $\alpha\le 2$. Inequality \eqref{lem:f:3} follows.
\end{proof}
The next lemma is an analytic tool to deal with $g_\gamma$, which may arise after applying Lemma~\ref{lem:f}.
\begin{lemma}
  \label{lem:5.1}
  Let $\gamma\in (0,1)$. Then the following hold:
  \begin{enumerate}[label=(\roman*)]
    \item
    For all $y,z\in\mathbb{R}$,
\begin{align}
    \label{lem:5.1:1}
    g_{\gamma}
    (z+y)
    \ \lesssim \
    g_\gamma(z)
    \cdot
    (1\lor |y|)^{1+\gamma}\,.
  \end{align}
  \item
    Let $a,b\in\mathbb{R}$ with $a<b$. Then, for all $z\in\mathbb{R}$,
\begin{align}
    \label{lem:5.1:2}
    \int_a^b g_\gamma(z-w)\,\mathrm{d}w
    \ \lesssim \
    g_\gamma(z)
    \cdot
    ((b-a) \lor 1)^{1+\gamma}
    \,.
  \end{align}
  \end{enumerate}
  Here $\lesssim$ denotes inequality up to a constant $C_{\gamma}>0$ depending only on $\gamma$.
\end{lemma}
\begin{proof}
  The inequality \eqref{lem:5.1:1} follows from \cite[Lemma~5.1]{koulAsymptoticsEmpiricalProcesses2001}.
  We now prove \eqref{lem:5.1:2}.
Let $a,b\in\RR$ with $a<b$, and define
$
   u
    :=
   b-a + 1
   \ \ge \
   1
$
and
$
   \tilde{z}
    :=
   z
   -
   a+1
$.
  Then
\begin{align*}
  \int_a^b g_\gamma(z-w) \,\mathrm{d}w
  \ = \
  \int_1^{u}
  g_\gamma(\tilde{z}-w)
  \,\mathrm{d}w
  \,.
\end{align*}
Since
$g_\gamma(\widetilde z) \lesssim g_\gamma(z)$, it suffices to consider the case
  $a = 1 <b$.
Note that for all
$b>1$, we have
$
  b\ \le \ 2((b-1)\lor 1)
$, and thus it suffices to show
for all $z\in\RR$
\begin{align}
  \label{eq:result}
  \frac{1}{b^{1+\gamma}}
  \int_1^b
  g_{\gamma}(z-w)
  \,\mathrm{d}w
  \ \lesssim \
  g_\gamma(z)
  \,.
\end{align}
First, consider the case $|z|\le 1$.
Then
\begin{align*}
  \frac
  {
  |z|+1
  }
  {2}
  \ \le \
  1
  \ < \
  b
  \qquad
  \text{and hence}
  \qquad
  \frac
  {1}
  {b^{1+\gamma}}
  \ \lesssim \
  \frac
  {1}
  {(1+|z|)^{1+\gamma}}
    \ = \
    g_\gamma(z)
  \,.
\end{align*}
Since
\begin{align}
  \label{eq:result_bound}
  \int_1^b
  g_{\gamma}(z-w)
  \,\mathrm{d}w
  \ \le \
  \int_{\RR}
  g_{\gamma}(w)
  \,\mathrm{d}w
  \ < \
  \infty
  \qquad\text{for all}\  z\in\RR
  \,,
\end{align}
we get \eqref{eq:result}.
Now consider the case $|z|>1$.
We will use, without further mention,
the inequalities
$1/|z|\le 2/(1+|z|)\le 2/|z|$.
First, suppose $b\ge |z|/2$.
Then clearly,
\begin{align*}
  \frac
  {1}
  {b^{1+\gamma}}
  \ \lesssim \
  \frac
  {1}
  {(1+|z|)^{1+\gamma}}
  \qquad
\end{align*}
and by \eqref{eq:result_bound}, this implies \eqref{eq:result}.
Next, assume $z/2>b\ge 1$.
Then $z-1>z-b>0$, and
\begin{align*}
  \int_1^b
  g_\gamma(z-w)
  \,\mathrm{d}w
  \ \le \
  \int_{z-b}^{z-1}
  \frac
  {1}
  {w^{1+\gamma}}
  \,\mathrm{d}w
  &
  \ = \
  \frac
  {1}
  {\gamma}
  \left(
  \frac
  {1}
  {(z-b)^{\gamma}}
  \ - \
  \frac
  {1}
  {(z-1)^{\gamma}}
  \right)
  \\&
  \ = \
  \frac
  {1}
  {\gamma(z-b)^{\gamma}}
  \left(
  1
  \ - \
  \left(
  \frac
  {z-b}
  {z-1}
  \right)^{\gamma}
  \right)
  \,.
\end{align*}
By the fundamental theorem of calculus, we obtain
\begin{align*}
  1
  \ - \
  \left(
  \frac
  {z-b}
  {z-1}
  \right)^{\gamma}
  \ = \
  -
  \int_1^b
  \frac{\mathrm{d}}{\mathrm{d} v}
  \left(
  \left(
  \frac
  {z-v}
  {z-1}
  \right)^{\gamma}
  \right)
  \,\mathrm{d} v
  &
  \ = \
  \frac
  {\gamma}
  {(z-1)^\gamma}
  \cdot
  \int_1^b
  (z-v)^{\gamma -1}
  \,\mathrm{d}v
  \\&
  \ \le \
  \frac
  {\gamma}
  {(z-1)^{\gamma}}
  \cdot
  b
  (z-b)^{\gamma -1}
\end{align*}
since $\gamma\in(0,1)$.
Thus
\begin{align*}
\int_1^b
  g_\gamma(z-w)
  \,\mathrm{d}w
  \ \le \
  \frac
  {b}
  {(z-1)^{\gamma}(z-b)}
  \ \le \
  \frac
  {b}
  {(z-z/2)^{\gamma}(z-z/2)}
  \ \lesssim \
  \frac
  {b}
  {z^{\gamma+1}}
  \quad
  \text{by}
   \
   z/2 > b \ge 1\,.
\end{align*}
It follows \eqref{eq:result}, that is,
\begin{align}
  \frac
  {1}
  {b^{1+\gamma}}
\int_1^b
  g_\gamma(z-w)
  \,\mathrm{d}w
  \ \lesssim \
  \frac
  {1}
  {b^{\gamma}}
  \frac
  {1}
  {(1+|z|)^{1+\gamma}}
  \ \lesssim \
  \frac
  {1}
  {(1+|z|)^{1+\gamma}}
  \ = \
  g_\gamma(z)
  \,.
  \label{eq:result_bound:1}
\end{align}
Finally, consider the case $-z/2>b\ge 1$. Using the symmetry of $g_\gamma$, we write
\begin{align*}
  \int_1^b
  g_\gamma(z-w)
  \,\mathrm{d}w
  \ =\
  \int_1^b
  g_\gamma(w-z)
  \,\mathrm{d}w
  \ & \le \
  \int^{b-z}_{1-z}
  \frac
  {1}
  {w^{1+\gamma}}
  \,\mathrm{d}w
  \ = \
  \frac
  {1}
  {\gamma}
  \left(
  \frac
  {1}
  {(1-z)^{\gamma}}
  \ - \
  \frac
  {1}
  {(b-z)^{\gamma}}
  \right)
  \\&
  \ = \
  \frac
  {1}
  {\gamma(b-z)^{\gamma}}
  \left(
  \left(
  \frac
  {b-z}
  {1-z}
  \right)^{\gamma}
  \ - \
  1
  \right)
  \,.
\end{align*}
Applying the fundamental theorem of calculus again and using $\gamma \in (0,1)$, we obtain
\begin{align*}
  \left(
  \frac
  {b-z}
  {1-z}
  \right)^{\gamma}
   \ - \
  1
  \ = \
  \int_1^b
  \frac{\mathrm{d}}{\mathrm{d} v}
  \left(
  \left(
  \frac
  {v-z}
  {1-z}
  \right)^{\gamma}
  \right)
  \,\mathrm{d} v
  &
  \ = \
  \frac
  {\gamma}
  {(1-z)^{\gamma}}
  \cdot
  \int_1^b
  (v-z)^{\gamma - 1}
  \,\mathrm{d}v
  \\&
  \ \le \
  \frac
  {\gamma}
  {1-z}
  \cdot
  b
  \,.
\end{align*}
Thus,
\begin{align*}
  &
\int_1^b
  g_\gamma(z-w)
  \,\mathrm{d}w
  \\&
  \ \le \
  \frac
  {b}
  {(b-z)^{\gamma}(1-z)}
  \ \le \
  \frac
  {b}
  {(-z/2-z)^{\gamma}(-z/2-z)}
  \ \lesssim \
  \frac
  {b}
  {|z|^{\gamma+1}}
  \quad
  \text{by}
   \
  - z/2 > b \ge 1\,.
\end{align*}
As in \eqref{eq:result_bound:1},
this yields \eqref{eq:result}.
This completes the proof.
\end{proof}
\subsection{Swap Integration and Differentiation}
The next lemma asserts that all the notions constructed from $G_n$ and used in this work are well-defined. It justifies interchanging differentiation and integration, which simplifies the terms we are going to work with.
\begin{lemma}[Swap Integration and Differentiation]
  \label{lem:swap}
  Let Assumptions~\ref{asu:coef},~\ref{asu:G_n} and~\ref{asu:f} hold, and define
$
  G_{k,n}(y)
  \ := \
  \EE[G_n(X_{0,k}+y)]
  \ = \
  \int_{\mathbb{R}} G_n(x) f_k(x-y)\mathrm{d}y
  \,.
$
  Then the following statements hold:
  \begin{enumerate}[label=(\roman*)]
    \item
    $\EE|G_n(X_{0,k}+y)|^r<\infty$ for all $k\in \NN \cup \{\infty\}$,  $n\in\NN$, $y\in\RR$, and for all $r\in (0,\alpha)$.
  \item
With the notation of Lemma~\ref{lem:f},
    for all $k>k_0$ or $k=\infty$, it holds that the function $G_{k,n}$ is continuously differentiable with
  \begin{align*}
    G_{k,n}^{(1)}(y)
    \ := \
     \frac{\mathrm{d}}{\mathrm{d}y}
     G_{k,n}(y)
     \ = \
    -
    \int_{\RR}
    G_n(x)
    f^{(1)}_{k}
    (x-y)
    \,\mathrm{d}x
    \ < \ \infty
    \qquad\text{for all}\ y\in\RR\,.
  \end{align*}
  \end{enumerate}
   \end{lemma}
\begin{proof}
  We begin with part (i).
  By Assumption~\ref{asu:coef} there exists $\delta>0$ such that $(\alpha-\delta)(1-d)>1$.
  Let $\gamma_G$ as in Assumption~\ref{asu:G_n}.
  Since $r<\alpha$ and
  \begin{align}
    \label{nrtd}
  \gamma_G
  <
\gamma_0
\ \le \
\frac{d}{1-d}
  \ = \
  \frac{1}{1-d}
  \ - \
  1
  \ < \
  \alpha - 1 \le 1
  \end{align}
  by assumption, we can choose $\delta>0$ small enough such that $\alpha-\delta\geq 1$ and $r\gamma_G<\alpha-\delta$. For $y\in \RR$ it follows
 \begin{align*}
   \EE|G_n(X_{0,k}+y)|^r
    &
    \ \lesssim \
    \EE[(1+|y+X_{0,k}|)^{r\gamma_G}]
    \\&
    \ \lesssim \
    \EE[(1+|y+X_{0,k}|)^{\alpha-\delta}]
    \\&
    \ \lesssim \
    1 \ + \
    |y|^{\alpha-\delta}
    \ + \
    \EE|X_{0,k}|^{\alpha-\delta}
    \\&
    \ \lesssim \
    1 \ + \
   |y|^{\alpha-\delta}
    \ + \
    \EE|\varepsilon|^{\alpha-\delta}
    \sum_{j=0}^\infty
   |a_j|^{-(\alpha-\delta)}
    \\&
    \ \lesssim \
    1 \ + \
    |y|^{\alpha-\delta}
    \ + \
    \sum_{j=1}^\infty
    j^{-(\alpha-\delta)(1-d)}
    \ < \ \infty
    \,.
  \end{align*}
  The third inequality is due to the convexity of $x\mapsto |x|^{\alpha-\delta}$, 
  and
  the fourth inequality is due to 
  the last part of Lemma~\ref{lem:bahr}(i) 
  This concludes the proof of part (i).

  Next we prove (ii).
  Fix $y\in\RR$ and assume $y\neq y'$.
  By part (i), it follows $\EE|G_n(X_{0,k}+y)|<\infty$ for all $y\in\RR$, so that we can use linearity of the expectation to get
 \begin{align}
    \label{lem:swap:1}
    \begin{split}
    &
    \frac{
    \EE[G_n(X_{0,k}+y)]
    -
    \EE[G_n(X_{0,k}+y')]
    }{y-y'}
    \ = \
    \int_\RR
    G_n(x)
    \frac{
    f_k(x-y)
    -
    f_k(x-y')
    }{y-y'}
    \,\mathrm{d}x
    \,.
    \end{split}
  \end{align}
  If we may interchange the limit $y'\to y$ with the integral, then
 \begin{align*}
    &
   \frac{\mathrm{d} }{\mathrm{d}y}
    \EE[G_n(X_{0,k}+y)]
    \ = \
    \lim_{y'\to y}
    \frac{
    \EE[G_n(X_{0,k}+y)]
    -
    \EE[G_n(X_{0,k}+y')]
    }{y-y'}
    \\&
    \ = \
    \int_\RR
    G_n(x)
    \lim_{y'\to y}
    \frac{
    f_k(x-y)
    -
    f_k(x-y')
    }{y-y'}
    \,\mathrm{d}x
    \ = \
    -
    \int_\RR
    G_n(x)
    f^{(1)}_k(x-y)
    \,\mathrm{d}x
    \,,
  \end{align*}
  as required.
  We seek to use dominated convergence to interchange these limits, and to this end we show
  that there is a bivariate function $g$ such that $g(\cdot,y)\in L^1(\RR)$ and
  \begin{align}
    \label{lem:swap:eq:4}
\left|
    G_n(x)
    \frac{
    f_k(x-y)
    -
    f_k(x-y')
    }{y-y'}
\right|
\ \lesssim \
    g(x,y)
    \qquad\text{uniformly in $y'$ with $|y'-y|\le 1$.}
  \end{align}
  First we apply the fundamental theorem of calculus and the triangle inequality to get
    \begin{align*}
    \left|
    G_n(x)
    \frac{
    f_k(x-y)
    -
    f_k(x-y')
    }{y-y'}
    \right|
    \ \le \
    \frac{
    G_n(x)
    }
      {|y-y'|}
      \int_{(y\land y')}^{(y\lor y')}
    \left|
    f^{(1)}_k(x-s)
    \right|
    \,\mathrm{d}s
    \,.
  \end{align*}
Since $\gamma_G< \alpha-1$
    by \eqref{nrtd},
    there exists $\gamma$ with $\gamma_G<\gamma<\alpha-1\le 1$ such that from Lemma~\ref{lem:f} with $1+\gamma < (\alpha \land 2) $, and the first part of  Lemma~\ref{lem:5.1} we get
  \begin{align*}
      \int_{(y\land y')}^{(y\lor y')}
    \left|
    f^{(1)}_k(x-s)
    \right|
    \,\mathrm{d}s
    &
    \ \lesssim \
    g_{\gamma}(x)
      \int_{(y\land y')}^{(y\lor y')}
      (1\lor|s|)^{1+\gamma}
      \,\mathrm{d}s
      \\&
      \ \le \
    g_{\gamma}(x)
    |y-y'|
      (1\lor|y|\lor |y'|)^{1+\gamma}
      \\
      &
      \ \lesssim \
    g_{\gamma}(x)
    |y-y'|
    (1+|y|)^2
  \end{align*}
  since $|y-y'|\le 1$. 
  Then, with
   Assumption~\ref{asu:G_n}
  \begin{align*}
    &
    \frac{
    G_n(x)
    }
      {|y-y'|}
      \int_{(y\land y')}^{(y\lor y')}
    \left|
    f^{(1)}_k(x-s)
    \right|
    \,\mathrm{d}s
    \\&
    \ \lesssim \
    G_n(x)
    g_{\gamma}(x)
    (1+|y|)^2
    \ \lesssim \
    (1+|x|)^{\gamma_G}
    g_{\gamma}(x)
    (1+|y|)^2
    \ \lesssim \
    g_{\gamma-\gamma_G}(x)
    (1+|y|)^2
    \,.
  \end{align*}
  With $\gamma-\gamma_G>0$ and therefore
  \begin{align}
    \label{eq:lem:swap:g_bdd}
    \int_\RR
    g_{\gamma-\gamma_G}(x)
    \,\mathrm{d}x
    \ < \ \infty
    \,,
  \end{align}
    it follows \eqref{lem:swap:eq:4} with $g(x,y)=  g_{\gamma-\gamma_G}(x)
    (1+|y|)^2$.
    To complete the proof, we show that $G_{k,n}^{(1)}$ is continuous.
    To this end, let $y\in\RR$ and $(y_m)_{m\in\mathbb{N}}$ a bounded sequence with $y_m\to y$ for $m\to\infty$.
    We want to show
    \begin{align*}
      \lim_{m\to\infty}
      G_{k,n}^{(1)}(y_m)
      &
      \ = \
      \lim_{m\to\infty}
      -
      \int_{\RR}
      G_n(x)
      f_k^{(1)}(x-y_m)
      \,\mathrm{d}x
      \\&
      \ = \
      -
      \int_{\RR}
      G_n(x)
      \lim_{m\to\infty}
      f_k^{(1)}(x-y_m)
      \,\mathrm{d}x
      \\&
      \ = \
      -
      \int_{\RR}
      G_n(x)
      f_k^{(1)}(x-y)
      \,\mathrm{d}x
      \\&
      \ = \
      G_{k,n}^{(1)}(y)
      \,.
    \end{align*}
    The third equality is due to the continuity of $f_k^{(1)}$ (see Lemma~\ref{lem:f}). To show the second equality we want to apply dominated convergence. To this end, note that by~\eqref{lem:f:1} in Lemma~\ref{lem:f} and then Lemma~\ref{lem:5.1}.(i), with the choice of $\gamma$ as above,
    \begin{align*}
      \left|
      G_n(x)
      f_{k}^{(1)}(x-y_m)
      \right|
       \ \lesssim \
      (1+|x|)^{\gamma_G}
      g_{\gamma}(x)
      (1\lor |y_m|)^{1+\gamma}
      \ \lesssim \
      g_{\gamma-\gamma_G}(x)
      \,.
    \end{align*}
    Together with \eqref{eq:lem:swap:g_bdd} we may apply dominated convergence to finish the proof.
\end{proof}
Lemma~\ref{lem:swap} tells us that
\begin{align*}
  G_{k,n}(y)
  \ := \
  \EE[G_n(X_{0,k}+y)]
  \qquad\text{and}\qquad
  G_{k,n}^{(1)}(y)
  \ := \
  \frac{\mathrm{d}}{\mathrm{d}y}
  \EE[G_n(X_{0,k}+y)]
\end{align*}
are well-defined
for $k>k_0$.
The following lemma establishes a connection between consecutive values of $G_{k,n}$ and $G_{k,n}^{(1)}$.
 \begin{lemma}
   \label{lem:cond}
  Let Assumptions~\ref{asu:coef},~\ref{asu:G_n} and~\ref{asu:f} hold true.
  It holds for $j\in\{0,1\}$ and $k>k_0$
   \[
     G_{k+1,n}^{(j)}(y)
     \ = \
     \EE[G_{k,n}^{(j)}(a_{k+1}\varepsilon_{-k-1}+y)]
     \qquad
     \text{and}
      \qquad
     G_{\infty,n}^{(j)}(y)
     \ = \
     \EE[G_{k,n}^{(j)}(\widetilde{X}_{0,k}+y)]
     \,.
   \]
 \end{lemma}
 \begin{proof}
   Let $(f\ast g)(y)$ denote the convolution defined by $\int_\RR f(y-x)g(x)\,\mathrm{d}x$.
   Since $\varepsilon$ is symmetric, the density $f_\varepsilon$ is even, and its derivative $f^{(1)}_\varepsilon$ is odd.
   Consequently, $f_k$ is even and $f_k^{(1)}$ is odd
  for all $k\in\NN\cup\{\infty\}$.
   Thus, for $k>k_0$,
   \begin{align}
     \label{eq:lab1}
 G_{k+1,n}(y)
     \ = \
     \int_\RR
     G_n(x)
     f_{k+1}(x-y)
     \,\mathrm{d}x
     \ = \
     (G_n\ast f_{k+1})(y)
     \,,
   \end{align}
   and as shown in Lemma~\ref{lem:swap}
   \begin{align}
     \label{eq:lab2}
 G_{k+1,n}^{(1)}(y)
     \ = \
     \ - \
     \int_\RR
     G_n(x)
     f_{k+1}^{(1)}(x-y)
     \,\mathrm{d}x
     \ = \
    (G_n\ast f_{k+1}^{(1)})(y)
    \,.
   \end{align}
Observe that $f_{k+1} = f_k \ast f_{a_{k+1}\varepsilon_{-k-1}}$, by the independence of the innovations, and then
  \begin{align}
    \label{eq:lab3}
    f_{k+1}^{(1)} = (f_{k}\ast f_{a_{k+1}\varepsilon_{-k-1}})^{(1)}
    \ = \
    (f^{(1)}_{k}\ast f_{a_{k+1}\varepsilon_{-k-1}})
  \end{align}
  since
   $f_{a_{k+1}\varepsilon_{-k-1}}\in L^{1}(\RR)$,
   and 
   $f_{k}\in C^1(\mathbb{R})$ with bounded derivative for all $k>k_0$ by~\eqref{lem:f:1} in Lemma~\ref{lem:f}.
      Thus for $j\in\{0,1\}$, 
    \begin{align*}
    G_{k+1,n}^{(j)}(y)
    &
    \ = \
    (G_n\ast f_{k+1}^{(j)})(y)
    \\&
    \ = \
      ((G_n\ast f_{k}^{(j)})\ast f_{a_{k+1}\varepsilon_{-k-1}})(y)
    \\&
    \ = \
    (G_{k,n}^{(j)}\ast f_{a_{k+1}\varepsilon_{-k-1}})(y)
    \\&
    \ = \
    \int_\RR
      G_{k,n}^{(j)}(x)f_{a_{k+1}\varepsilon_{-k-1}}(x-y)
      \,\mathrm{d}x
      \\&
    \ = \
    \EE[G_{k,n}^{(j)}(a_k\varepsilon_{-k-1} + y)]
    \,,
  \end{align*}
  where the first and third equalities are due to \eqref{eq:lab1} and \eqref{eq:lab2}, and the second equality is due to 
  \eqref{eq:lab3} (and associativity of the convolution operator).

   Observe, finally, that $f_{\infty} = f_k \ast f_{\widetilde{X}_{0,k}}$, and that a similar argument can be written for $f_{a_{k+1}\varepsilon_{-k-1}}$ replaced by $f_{\widetilde{X}_{0,k}}$.
   Therefore the statement holds also for $k=\infty$. This completes the proof.
   \end{proof}


\section{Proof of Theorem~\ref{thm:approx}}


The proof of Theorem~\ref{thm:approx} is long. It draws on ideas from \cite{koulAsymptoticsEmpiricalProcesses2001}, where the authors conducted their analysis without the benefit of finite second moments---a difficulty we must also address.
Throughout this section, let $n\in\NN$ unless stated otherwise.
To track the deviation of the PoT statistic from its approximation, we define a centered process that isolates the remainder term after linear approximation. This term will be central in applying martingale arguments.
In the sequel, for $n\in\NN$, define
  \begin{align*}
    \mathcal{U}_n(X_t)
    \ := \
    G_n(X_t) \ -\  \EE[G_n(X_t)] \ -\  G_{\infty,n}^{(1)}(0) X_t
    \qquad\text{for}\ t\in\ZZ\,.
  \end{align*}
Note that under Assumptions~\ref{asu:coef},~\ref{asu:f} and~\ref{asu:G_n}, the term $G_{\infty,n}^{(1)}(0)$ is indeed well-defined by Lemma~\ref{lem:swap}. Hence, $\mathcal{U}_n(X_t)$ itself will be well-defined and integrable once we verify that $G_n(X_0)$ and $X_0$
are integrable. For $k\in\ZZ$, let $\mathcal{F}_k=\sigma(\varepsilon_k,\varepsilon_{k-1},\ldots)$ denote the past $\sigma$-algebra generated by the sequence $(\varepsilon_t)$ up to index $k$.
For $Y\in L^1(\PP)$, we define the
projection
  \begin{align*}
    P_k\,Y
    \ := \
    \mathbf{E}\left[Y\, | \, \mathcal{F}_k\right]
    \ - \
    \mathbf{E}\left[Y\, | \, \mathcal{F}_{k-1}\right]
    \qquad \text{for all}\ k\in \ZZ
    \,.
  \end{align*}
We proceed with a sequence of lemmas that prepare the proof of the final result.
The next lemma establishes integrability properties of the centered process $\mathcal{U}_n(X_t)$---first in its unprojected form, then after projection by $P_k$.
This integrability is needed to apply the lemma on martingale difference arrays (Lemma~\ref{lem:bahr}) later in the proof. Note that part~(ii) also provides an upper bound that contributes directly to the final result.
  \begin{lemma}
    \label{lem:2.2}
    Under Assumptions~\ref{asu:coef},~\ref{asu:G_n} and~\ref{asu:f}, for $r\in[1,\alpha)$, the following statements hold:
    \begin{enumerate}
      \item $\mathcal{U}_n(X_0)\in L^r(\PP)$.
      \item
      $
      \norm{P_k\,\mathcal{U}_n(X_0)}_{L^r(\PP)}
       \lesssim
      \norm{G_n(X_0)}_{L^r(\PP)}
      \lor
      |G_{\infty,n}^{(1)}(0)|
      <\infty
      $
      for all $k\in\mathbb{Z}$.
    \end{enumerate}
  \end{lemma}
  \begin{proof}
    We begin with part (i).
    By Assumption~\ref{asu:G_n}, the inequalities
    \begin{align*}
      \gamma_G
      \ < \
      \frac{d}{1-d}
      \ < \
      1
      \ < \
      \frac{1}{1-d}
      \,,
    \end{align*}
    which hold because of $d<1/2$ (see Assumption~\ref{asu:coef}), and the convexity of $x \mapsto |x|^r$, we obtain
    \begin{align}
      \label{eq:2.2:1}
      \EE|G_n(X_0)|^r
      \ \lesssim \
      \EE(1+|X_0|)^{r\gamma_G}
      \ \le \
      \EE(1+|X_0|)^{r}
      \ \le \
      2^{r-1}
      \left(
1
 +
      \EE|X_0|^{r}
      \right)
      \ \le \
      2
      \left(
1
 +
      \EE|X_0|^{r}
      \right)
    \end{align}
    for some $r\in[1,\alpha)$ with $\alpha\le 2$.
    To further bound $\EE[|X_0|^r]$, we apply Lemma~\ref{lem:bahr} to the array $(Y_{m,i})=(a_i \varepsilon_{-i}\,\colon \, i=0,\ldots,m\,,m\in\NN)$ and the sequence $(Y_i)=(a_i \varepsilon_{-i})_{i\ge 0}$.
       By Assumption~\ref{asu:f}, both $(Y_{m,i})$ and $(Y_i)\subset L^p(\PP)$.
       Since the innovations are independent and centered,
  condition~\eqref{eq:bahr:cond:1} is satisfied.
    Moreover, condition \eqref{eq:bahr:cond:2} is clear, so by \eqref{eq:bahr:infty} in Lemma~\ref{lem:bahr} and Assumption~\ref{asu:coef}, we get for any $\tilde r \in (r\lor (1/1-d), \alpha)$
    \begin{align}
      \EE|X_0|^{\tilde r}
      \ = \
      \EE\left|\sum_{i=0}^\infty Y_i\right|^{\tilde r}
      \ \lesssim \
      \sum_{i=0}^\infty
      \EE\left|
      Y_i
      \right|^{\tilde r}
      \ \lesssim \
      \sum_{i=1}^\infty
      i^{-(1-d)\tilde r}
      \ < \ \infty\,,
      \label{eq:2.2:2}
    \end{align}
    since we chose $\tilde r>1/(1-d)$.
    Using \eqref{eq:2.2:1}, this shows that $G_n(X_0)\in L^r(\PP)$.
    Since $X_0\in L^r(\PP)$ by \eqref{eq:2.2:2},
    the proof of part (i) is complete.
    Next we prove part (ii).
    From part (i), we know that $P_k \, \mathcal{U}_n (X_0)$ is well-defined.
  For fixed $j,k\in\mathbb{Z}$, observe that
  \begin{align*}
    P_{-k}
    \varepsilon_{-j}
    &
    \ = \
    \begin{cases}
      0\,\quad &\text{if} \ j\neq k\,,\\
      \varepsilon_{-k}\,\quad &\text{if} \ j= k\,,\\
    \end{cases}
  \end{align*}
  so, by dominated convergence, it follows that
 \begin{align*}
   P_{k}\, X_0
   \ = \
   \sum_{i=0}^\infty
   a_i
   P_{k}\,\varepsilon_{-i}
   \ = \
    \begin{cases}
      0\,\quad &\text{if} \ k>0\,,\\
      a_{-k}\varepsilon_{k}\,\quad &\text{if} \ k\le 0\,.\\
    \end{cases}
 \end{align*}
 Thus,
\begin{align}
\nonumber
  P_{k}\,\mathcal{U}_n(X_0)
  &
  \ = \
  P_{k}\,
  (G_n(X_0) \ -\  \EE[G_n(X_0)] \ -\  G_{\infty,n}^{(1)}(0)X_0)
  \\
\label{eq:PkU}
  &
  \ = \
    \EE[G_n(X_0)\, | \, \mathcal{F}_{k}]
    \ - \
    \EE[G_n(X_0)\, | \, \mathcal{F}_{k-1}]
    \ - \
    G_{\infty,n}^{(1)}(0)
    \cdot
    a_{-k}\cdot\varepsilon_{k}
    \cdot
    \ind\{k\le 0\}
    \,.
\end{align}
  Applying Jensen's inequality with $r\ge 1$, and using the properties of conditional expectation,
  we obtain
\begin{align*}
  \EE
    |\EE[G_n(X_0)\, | \, \mathcal{F}_{k}]|^r
    &
    \ \le \
    \EE|G_n(X_0)|^r
       \ < \ \infty\
       \qquad\text{as shown in part (i)}
    \,.
    \end{align*}
Combining equation~\eqref{eq:PkU} with the fact that $\varepsilon\in L^r(\PP)$ for $r<\alpha$ completes the proof.
  \end{proof}
    The next lemma provides an intermediate upper bound on the error term
    \begin{align*}
    \sum_{t=1}^n
         \left(G_n(X_t)
         \ - \
         \EE[G_n(X_0)]
         \ - \
         G_{\infty,n}^{(1)}(0)
         X_t\right) = \sum_{t=1}^{n} \mathcal{U}_n(X_t)
    \end{align*}
    from Theorem~\ref{thm:approx}(i). The bound is obtained by first decomposing the error term via projections, and then applying the martingale difference inequality (Lemma~\ref{lem:bahr}).
\begin{lemma}
  \label{lem:cond_decomp}
  Under the assumptions of Lemma~\ref{lem:2.2}, it holds that
\begin{align*}
      \mathbf{E}\left|
\sum_{t=1}^{n}
  \mathcal{U}_n(X_t)
      \right|^r
      \ \lesssim \
      \sum_{k=-\infty}^{n}
      \left(
      \sum_{t=k\lor 1}^{n}
      \norm{
      P_{k-t}\, \mathcal{U}_n(X_0)
      }_{L^r(\PP)}
      \right)^r
      \,.
  \end{align*}
\end{lemma}
At this stage it is not obvious that the right-hand side is finite, and thus that this upper bound is informative; the next step of the proof, in Lemma~\ref{lem:core_r}, turns this into an informative upper bound.
\begin{proof}
  Since the process $(X_t)$ is (strictly) stationary, we may define
  \begin{align*}
    T_n(G_n)
    \ := \ \sum_{t=1}^{n}
    \mathcal{U}_n(X_t)
    \ = \
    \sum_{t=1}^{n}
    G_n(X_t) \ -\  \EE[G_n(X_0)] \ -\  G_{\infty,n}^{(1)}(0) X_t
    \,.
  \end{align*}
Because $X_t$ is $\mathcal{F}_t$-measurable and the sequence $(\mathcal{F}_k)$ is increasing, $T_n(G_n)$ is $\mathcal{F}_n$-measurable. Then
  \begin{align*}
    P_{k}\, T_n(G_n)
    \ = \
    0
    \qquad \text{for}\ k>n
    \qquad\text{and}\qquad
    P_{k}\, \mathcal{U}_n(X_t)
    \ = \ 0
    \qquad\text{for}\ k>t
    \,.
  \end{align*}
 We can therefore write, for any $\ell<n$,
  \[
    T_n(G_n)
    \ - \
    \EE[T_n(G_n)\mid \mathcal{F}_{\ell-1}]
    \ = \
    \sum_{k=\ell}^n
    P_k\, T_n(G_n).
  \]
  Since $\cap_{k\in \mathbb{Z}} \mathcal{F}_k$ is the trivial $\sigma-$algebra, $\EE[T_n(G_n)\mid \mathcal{F}_{\ell-1}]\to \EE[T_n(G_n)]=0$ as $\ell\to-\infty$. Hence, we obtain
  \begin{align}
    \label{eq:above:md}
    T_n(G_n)
    &
    \ = \
    \sum_{k=-\infty}^n
    P_{k}\, T_n(G_n)
    \,,
  \end{align}
  and then
  \begin{align}
  \label{eq:above:pk}
  P_k\, T_n(G_n) &= \sum_{t=1}^{n} P_k \, \mathcal{U}_n(X_t) = \sum_{t=k\lor 1}^{n} P_k\, \mathcal{U}_n(X_t).
    \end{align}
We aim to apply Lemma~\ref{lem:bahr} to Equation~\eqref{eq:above:md}.
To this end, define the array
\begin{align*}
  (Y_{m,i})
  \ = \
  (P_{i+n-m}\, T_n(G_n)\,\colon\, i=1,\ldots,m\,,m\in\NN)
  \,,
\end{align*}
so that
\begin{align*}
  \sum_{i=1}^m
  Y_{m,i}
  \ = \
  \sum_{k=n-m+1}^{n}
  P_{k}\,T_n(G_n)
  \,
\end{align*}
and define the associated sequence $(Y_i)_{i\geq 1}$ by
$
  Y_i = P_{n-i+1}\, T_n(G_n)
$.
By Lemma~\ref{lem:2.2}.(ii) and identity \eqref{eq:above:pk} it holds that $(Y_{m,i}),(Y_i)\subset L^r(\PP)$.
Note that
\begin{align*}
  \sum_{i=1}^{\infty}
  Y_i
  \ = \
  \sum_{k=-\infty}^{n}
  P_k\, T_n(G_n)
  \ = \
  \lim_{m\to\infty}
  \sum_{k=n-m+1}^{n}
  P_{k}\,T_n(G_n)
  \ = \
  \lim_{m\to\infty}
  \sum_{i=1}^m
  Y_{m,i}
\end{align*}
and similarly
$
\sum_{i=1}^{\infty}
\EE|Y_i|^r
= \lim_{m\to\infty}
\sum_{i=1}^m
\EE|Y_{m,i}|^r
$.
To apply Lemma~\ref{lem:bahr}, it remains to verify condition \eqref{eq:bahr:cond:1}.
To this end, observe
  that equation \eqref{eq:above:md} represents 
  an $\mathcal{F}_\ell$-martingale difference decomposition
  in the sense that, for $\ell\in\ZZ$,
  \begin{align*}
    &
    \EE[P_{\ell+1}\,T_n(G_n)\mid \mathcal{F}_\ell]
    \ = \
    \EE[
    \EE[T_n(G_n)\mid \mathcal{F}_{\ell+1}]
    \mid
    \mathcal{F}_{\ell}
    ]
    \ - \
    \EE[T_n(G_n)\mid \mathcal{F}_{\ell}]
    \ = \ 0
    \,.
  \end{align*}
  Consequently
  \begin{align}
    \label{eq:above:1}
    \EE[Y_{m,\ell+ 1}\mid \mathcal{F}_{n - m + \ell}]
    \ = \
    0
    \qquad\text{for all}\ 1\le \ell \le m-1\,, m\in\NN\,.
  \end{align}
  Let
  $\mathcal{V}^{m}_\ell$ denote the $\sigma$-algebra
  generated by
  \begin{align*}
    \sum_{i=1}^{\ell}
    Y_{m,i}
    \ = \
    \sum_{i=1}^{\ell}
    P_{i+n-m}\,T_n(G_n)
    \ = \
    \sum_{k=n-m+1}^{n-m+\ell}
    P_k\,T_n(G_n)
    \,.
  \end{align*}
  Since the filtration $(\mathcal{F}_k)$ is increasing, all summands are $\mathcal{F}_{n - m + \ell}$-measurable.
  Therefore, $\mathcal{V}^m_\ell\subset \mathcal{F}_{n-m+\ell}$.
  Combined with
    \eqref{eq:above:1} this verifies condition \eqref{eq:bahr:cond:1}.
    We can now apply inequality \eqref{eq:bahr:infty} to obtain
    \begin{align*}
\EE
\left|
      \sum_{k=-\infty}^n P_{k} T_n(G_n)
\right|^r
      \ = \
\EE
\left|
      \sum_{i=1}^\infty Y_i
\right|^r
\ \lesssim \
      \sum_{i=1}^\infty
\EE
\left|
Y_i
\right|^r
      \ = \
      \sum_{k=-\infty}^n
\EE
\left|
      P_{k} T_n(G_n)
\right|^r
\,.
    \end{align*}
With Equation \eqref{eq:above:md} and Equation \eqref{eq:above:pk}, it follows that
  \begin{align}
    \label{eq:2}
    \begin{split}
      \EE
      \left[
      \left|T_n(G_n)\right|^r
      \right]
      &
      \ \lesssim \
      \sum_{k\le n}^{}
      \mathbf{E}\left|
      \sum_{t=k\lor 1}^{n}
      P_k\, \mathcal{U}_n(X_t)
      \,
      \right|^r
      \\
      &
      \ \le \
      \sum_{k\le n}^{}
      \left(
      \sum_{t=k\lor 1}^{n}
      \norm{
      P_{k-t}\, \mathcal{U}_n(X_0)
      }_{L^r(\PP)}
      \right)^r
      \,.
    \end{split}
  \end{align}
  The final inequality follows from the  triangle inequality for the $L^r(\PP)$ norm, using that $\norm{
      P_k\, \mathcal{U}_n(X_t)
      }_{L^r(\PP)} = \norm{
      P_{k-t}\, \mathcal{U}_n(X_0)
      }_{L^r(\PP)}$ due to stationarity.
      This completes the proof.
\end{proof}
The most delicate step now lies ahead: bounding each projection term individually. The first part of the next lemma sets the stage by identifying a suitable decomposition of the error. The core of the argument is in the second part, where we introduce auxiliary parameters $\gamma$ and $r$ to mitigate the effect of infinite second moments.
\begin{lemma}[Error Decomposition and Control]
  \label{lem:core_r}
  Let Assumptions~\ref{asu:coef},~\ref{asu:G_n} and~\ref{asu:f} hold, let $k_0$ be as defined by Lemma~\ref{lem:f}, and let $k>k_0$.
  \begin{enumerate}
    \item
    We can write
    $
    P_{-k}\,\mathcal{U}_n(X_0)
     =
    R_1
     +
    R_2
     +
    R_3
    $,
    where
  \begin{align*}
    R_1
    &\ := \
    G_{k-1,n}(X_0-X_{0,k-1})
    \ - \
    \int
    G_{k-1,n}(X_0-X_{0,k}+a_kz)
    \,\mathrm{d}\PP_\varepsilon(z)
    \\&
    \qquad\ - \
    a_k\cdot\varepsilon_{-k}
    \cdot
    G^{(1)}_{k-1,n}(X_0-X_{0,k})
    \,,
    \\
    R_2
    &\ := \
    a_k\cdot\varepsilon_{-k}
    \left(
    G_{\infty,n}^{(1)}(X_0-X_{0,k})
    \ - \
    G_{\infty,n}^{(1)}(0)
    \right)
    \,,
    \\
    R_3&\ := \
    a_k\cdot\varepsilon_{-k}
    \left(
    G_{k-1,n}^{(1)}(X_0-X_{0,k})
    \ - \
    G_{\infty,n}^{(1)}
(X_0-X_{0,k})
    \right)
    \,.
  \end{align*}
  \item
    Let $\gamma\in(0,1)$ and $r\in[1,2]$ such that
  \begin{align*}
    \gamma_G
    \ < \
    \gamma
    \ < \
\min
\left\{
    \frac{d}{1-d}
    \,,
    1
    -
    \frac{1}{r(1-d)}
    \,,
    \frac{\alpha}{r}
    -
    1
\right\}
    \qquad\text{and}\qquad
    \frac{1}{1-d}
    \ < \
    r
    \ < \
    \alpha
    \,.
  \end{align*}
    For each $j\in\{1,2,3\}$, we have
    $
    \norm{R_j}_{L^r(\PP)}
    \
 \lesssim
    \
      k^{-(1-d)(1+\gamma)}
      \cdot
      u_n^{-\gamma+\gamma_G}
    $.
    Therefore
    \begin{align}
      \label{lem:core_r:iii:final}
      \norm{
      P_{-k}\, \mathcal{U}_n(X_0)
      }_{L^r(\PP)}
      \
      \lesssim
      \
      k^{-(1-d)(1+\gamma)}
      \cdot
      u_n^{-\gamma+\gamma_G}
      \,.
    \end{align}
   \end{enumerate}
\end{lemma}
\
 \subsection{Proof of Lemma~\ref{lem:core_r}(i)}
 By definition
\begin{align*}
  &
  R_1
  \ + \
  R_2
  \ + \
  R_3
  \\&
  \ = \
    G_{k-1,n}(X_0-X_{0,k-1})
    \ - \
    \int
    G_{k-1,n}(X_0-X_{0,k}+a_kz)
    \,\mathrm{d}\PP_\varepsilon(z)
    \ - \
    a_k\cdot\varepsilon_{-k}
    \cdot
    G_{\infty,n}^{(1)}
    (0)
    \,.
\end{align*}
On the other hand, using~\eqref{eq:PkU}, we have
\begin{align*}
  P_{-k}\,\mathcal{U}_n(X_0)
  &
  \ = \
    \EE[G_n(X_0)\, | \, \mathcal{F}_{-k}]
    \ - \
    \EE[G_n(X_0)\, | \, \mathcal{F}_{-(k+1)}]
    \ - \
    a_k\cdot\varepsilon_{-k}
    \cdot
    G_{\infty,n}^{(1)}(0)
    \,.
\end{align*}
Note that $X_{0,k-1}=\sum_{j=0}^{k-1}a_j\varepsilon_{-j}$ is independent of $\mathcal{F}_{-k}$, and $X_0-X_{0,k-1}=\sum_{j=k}^{\infty}a_j\varepsilon_{-j}$ is $\mathcal{F}_{-k}$-measurable. 
Therefore,
\begin{align*}
    \EE[G_n(X_0)\, | \, \mathcal{F}_{-k}] & \ = \ \EE[G_n(X_{0,k-1}+(X_0-X_{0,k-1}))\, | \, \mathcal{F}_{-k}]
  \\&
    \ = \
    \int
    G_n(z+(X_0-X_{0,k-1}))
    \,\mathrm{d}
  \PP_{X_{0,k-1}}(z)
  \\&
  \ = \
  G_{k-1,n}(X_0-X_{0,k-1})
  \,.
\end{align*}
Similarly, by Lemma~\ref{lem:cond},
\begin{align*}
    \EE[G_n(X_0)\, | \, \mathcal{F}_{-(k+1)}]
    \ = \
  G_{k,n}(X_0-X_{0,k})
  \ = \
    \int
    G_{k-1,n}(X_0-X_{0,k}+a_kz)
    \,\mathrm{d}\PP_\varepsilon(z)
    \,.
\end{align*}
Consequently, combining the expressions gives
\begin{align*}
  & P_{-k}\,\mathcal{U}_n(X_0) \\
    & \ = \ G_{k-1,n}(X_0-X_{0,k-1})
    \ - \
    \int
    G_{k-1,n}(X_0-X_{0,k}+a_kz)
    \,\mathrm{d}\PP_\varepsilon(z)
    \ - \
    a_k\cdot\varepsilon_{-k}
    \cdot
    G_{\infty,n}^{(1)}
    (0) \\
    & \ = \  R_1
  \ + \
  R_2
  \ + \
  R_3\,,
\end{align*}
as claimed.
\subsection{Proof of Lemma~\ref{lem:core_r}(ii)}
Given the bounds on the $R_j$, the bound \eqref{lem:core_r:iii:final} follows directly from part (i). We now turn to the proof of the announced bounds on the $R_j$. Fix $k>k_0$ for the remainder of the proof.
Note that
by Assumption~\ref{asu:G_n}, and for any $\gamma$ with $\gamma_G<\gamma<d/(1-d)$, we have
\begin{align}
  \label{eq:iii:1}
  \int_\RR
  G_n(x)
  g_\gamma(x)
  \,\mathrm{d}x
  \ \lesssim \
  \int_{u_n}^{\infty}
  (1+|x|)^{-(1+\gamma-\gamma_G)}
  \,\mathrm{d}x
  \
  \asymp
  \
  u_n^{-\gamma+\gamma_G}\,.
\end{align}
Moreover, the next inequalities ensure that the conditions of Lemma~\ref{lem:f} are met:
\begin{align*}
  1
  \ + \
  \gamma
  \ < \
  1
  \ + \
  \frac{d}{1-d}
  \ = \
  \frac{1}{1-d}
  \ < \
  r
  \ < \
  \alpha
  \,.
\end{align*}
\subsubsection{Analysis of $R_1$}
Write $R_1$ as
  \begin{align}
    \label{eq:r1:0}
    \begin{split}
    R_1
    &
    \ = \
    G_{k-1,n}(X_0-X_{0,k-1})
    \ - \
    \int_\RR
    G_{k-1,n}(X_0-X_{0,k}+a_kz)
    \,\mathrm{d}\PP_\varepsilon(z)
    \\&
    \qquad
    \ - \
    a_k\cdot\varepsilon_{-k}
    \cdot
    G^{(1)}_{k-1,n}(X_0-X_{0,k})
    \\&
    \ = \
    \int_\RR
    [
    G_{k-1,n}(X_0-X_{0,k}+a_k\varepsilon_{-k})
    \ - \
    G_{k-1,n}(X_0-X_{0,k}+a_kz)
    \\&
    \qquad
    \ - \
    a_k\cdot\varepsilon_{-k}
    \cdot
    G^{(1)}_{k-1,n}(X_0-X_{0,k})]
    \,\mathrm{d}\PP_{\varepsilon}(z)
\\&
    \ = \
    \int_\RR
    \bigg[ \left(
    \int_{a_k z}^{a_k\varepsilon_{-k}}
    G_{k-1,n}^{(1)}(X_0-X_{0,k}+s)
    \,\mathrm{d}s
    \right)
    \\&
    \qquad\ - \
    a_k\cdot\varepsilon_{-k}
    \cdot
    G^{(1)}_{k-1,n}(X_0-X_{0,k})
    \ + \
    a_k\cdot z
    \cdot
    G^{(1)}_{k-1,n}(X_0-X_{0,k}) \bigg]
    \,\mathrm{d}\PP_{\varepsilon}(z)
\\&
    \ = \
    \int_\RR
    \left(
    \int_{a_k z}^{a_k\varepsilon_{-k}}
    [ G_{k-1,n}^{(1)}(X_0-X_{0,k}+s)
    \ - \
    G_{k-1,n}^{(1)}(X_0-X_{0,k}) ]
    \,\mathrm{d}s
    \right)
        \,\mathrm{d}\PP_{\varepsilon}(z)
        \,.
    \end{split}
    \end{align}
    Note that the third equality follows by applying the fundamental theorem of calculus to $G_{k-1,n}$, which is justified by
    Lemma~\ref{lem:swap}.(ii). 
    Note also that adding the term
\begin{align*}
    a_k\cdot z
    \cdot
    G^{(1)}_{k-1,n}(X_0-X_{0,k})
\end{align*}
inside the integral is valid because $\varepsilon$ is centered.
To proceed, we consider three mutually exclusive cases:
\begin{itemize}
  \item
  $
      1
      \
      \ge
      \
      (
      |a_k\varepsilon_{-k}|
      \lor
      |a_kz|
      )
  $
  \item
  $
|a_k\varepsilon_{-k}|
      \
      >
      \
\left(
      |a_kz|
      \lor
      1
\right)
  $
  \item
  $
      |a_kz|
      \
      >
      \
\left(
      |a_k\varepsilon_{-k}|
      \lor
      1
\right)
  $
\end{itemize}
These three cases exhaust all possibilities and will be treated separately in the following sections.
  \paragraph{Case $1\ge (|a_k\varepsilon_{-k}|\lor |a_k z|)$}

  Bound $R_1$ as follows:
    \begin{equation}
    \label{eq:r1:0_bound}
  |R_1|
  \ \le \
\int_\RR
\left|
    \int_{a_kz}^{a_k\varepsilon_{-k}}
\left|
    G_{k-1,n}^{(1)}(X_0-X_{0,k}+s)
    \ - \
    G_{k-1,n}^{(1)}(X_0-X_{0,k})
\right|
    \,\mathrm{d}s
\right|
        \,
    \mathrm{d}\PP_\varepsilon(z)\,.
    \end{equation}
   Let $s$ 
   lie in the interval linking $a_kz$ to $a_k\varepsilon_{-k}$, so that $|s|\le 1$.
   Let $\gamma\in(\gamma_G,1)$ be as in Lemma~\ref{lem:f}.
    We can use \eqref{lem:f:2} there 
    and~\eqref{lem:5.1:1} in Lemma~\ref{lem:5.1} to get for all $x\in\RR$
\begin{align}
  \label{eq:r1:0b}
  \begin{split}
  &
\left|
    f_{k-1}^{(1)}(x-(X_0-X_{0,k}+s))
    \ - \
    f_{k-1}^{(1)}(x-(X_0-X_{0,k}))
\right|
    \\
    &
    \ \lesssim \
     |s|
    \cdot
    g_\gamma(x-[X_0-X_{0,k}])
    \ \lesssim \
    |s|^{\gamma}
    \cdot
    g_\gamma(x)
    \cdot
    (1  +   |X_0-X_{0,k}|)^{1+\gamma}
    \,.
  \end{split}
\end{align}
Combining \eqref{eq:r1:0_bound} with
the representation of $G_{k-1,n}^{(1)}$ from
Lemma~\ref{lem:swap}.(ii) and then the bound from \eqref{eq:r1:0b}, we bound $R_1$ as
    \[
    |R_1|
    \leq
    (1  +   |X_0-X_{0,k}|)^{1+\gamma}
    \cdot
    \int_\RR
    G_n(x)
    g_\gamma(x)
    \,\mathrm{d}x
    \cdot
    \int_\RR
    \left|
    \int_{a_kz}^{a_k\varepsilon_{-k}}
    |s|^{\gamma}
    \,\mathrm{d}s
    \right|
        \,
    \mathrm{d}\PP_\varepsilon(z)
    \,.
    \]
    Finally, by~\eqref{eq:iii:1} and using $\varepsilon\in L^{1+\gamma}(\PP)$ as $1+\gamma < \alpha$, we conclude
    \begin{align}
  \label{eq:r1:2}
      \begin{split}
        |R_1|
    &
    \ \lesssim \
    (1  +   |X_0-X_{0,k}|)^{1+\gamma}
    \cdot
    u_n^{-\gamma+\gamma_G}
    \cdot
    |a_k|^{1+\gamma}
    \cdot
    \left(
    |\varepsilon_{-k}|^{1+\gamma}
    \ + \
    \EE
    |\varepsilon|^{1+\gamma}
    \right)
    \\&
    \ \lesssim \
    (1  +   |X_0-X_{0,k}|^{1+\gamma})
    \cdot
    u_n^{-\gamma+\gamma_G}
    \cdot
    |a_k|^{1+\gamma}
    \cdot
    [|\varepsilon_{-k}|^{1+\gamma} \vee 1]
    \,.
  \end{split}
\end{align}
We now show that
\begin{align}
  \label{eq:r2:x0bdd}
  \EE|X_0-X_{0,k}|^{p}
  \ \lesssim \
  k^{1-(1-d)p}
  \ \lesssim \
  1
  \qquad\text{for}\
p\in
\left(
\frac{1}{1-d}
\,,
\alpha
\right)
  \,.
\end{align}
To this end, define the array and limiting sequence
\begin{align*}
  (Y_{m,i})
  \ = \
  (a_{k+i}\varepsilon_{-(k+i)}\,,i=1,\ldots,m\,,m\in\NN)
  \qquad\text{and}\qquad
  (Y_i)
  \ = \
  (a_{k+i}\varepsilon_{-(k+i)})_{i\in\NN}
  \,.
\end{align*}
Note that \eqref{eq:bahr:cond:1} and \eqref{eq:bahr:cond:2} are satisfied for $(Y_{m,i})$ and $(Y_i)$.
Then we may write
\begin{align*}
  X_0
   -
  X_{0,k}
  \ = \
\sum_{i=k+1}^\infty
  a_i\varepsilon_{-i}
  \ = \
\sum_{i=1}^\infty
  a_{k+i}\varepsilon_{-(k+i)}
  \ = \
\sum_{i=1}^\infty
Y_i
  \,.
\end{align*}
The $\varepsilon_j$ are independent, centered and belong to $L^p(\PP)$, so applying inequality~\eqref{eq:bahr:infty}
in Lemma~\ref{lem:bahr}.(ii), we obtain
\begin{align*}
  \EE|X_0-X_{0,k}|^p
  \ \lesssim \
  \sum_{i=k+1}^\infty
  |a_i|^{p}
  \EE|\varepsilon_{-i}|^p
  \ \lesssim \
  \sum_{i=k+1}^\infty
  i^{-(1-d)p}
  \ \lesssim \
  k^{1-(1-d)p}
  \ \le \
  1
  \,
\end{align*}
where we used $|a_i|\asymp i^{-(1-d)}$ and $(1-d)p>1$. This proves \eqref{eq:r2:x0bdd}. To conclude, note that
\begin{align*}
\frac{1}{1-d}
\ < \
  (1+\gamma)r
\ < \
\left(
1
\ + \
\frac{\alpha}{r}
-
1
\right)
r
  \ = \
  \alpha
  \,.
\end{align*}
Since $X_0-X_{0,k}$ and $\varepsilon_{-k}$ are independent, and using the moment bound from~\eqref{eq:r2:x0bdd} with $p=(1+\gamma)r<\alpha$ along with $|a_i|\asymp i^{-(1-d)}$, we obtain
\begin{align*}
  \norm{
    (1  +   |X_0-X_{0,k}|)^{1+\gamma}
    \cdot
    u_n^{-\gamma+\gamma_G}
    \cdot
    |a_k|^{1+\gamma}
    \cdot
    (1\lor|\varepsilon_{-k}|)^{1+\gamma}
  }_{L^r(\PP)}
  \ \lesssim \
    u_n^{-\gamma+\gamma_G}
    \cdot
    k^{-(1-d)(1+\gamma)}
    \,.
\end{align*}
Combining this with the bound from
\eqref{eq:r1:2}, we conclude
\begin{align*}
  \norm{
  R_1
  \ind\{1\ge (|a_kz|\lor|a_k\varepsilon_{-k})\}
  }_{L^r(\PP)}
  \ \lesssim \
    k^{-(1-d)(1+\gamma)}
    u_n^{-\gamma+\gamma_G}
    \qquad
    \text{for $k>k_0+1$}\,.
\end{align*}
\paragraph{Case $|a_k\varepsilon_{-k}|>(1\lor |a_k z|)$}
We now estimate $R_1$ restricted to the event $
|a_k\varepsilon_{-k}|>(1\lor |a_k z|)
$.
To do so, we note that on this event $|\varepsilon_{-k}| > |z|$ and we split the integrand in \eqref{eq:r1:0}, obtaining
\begin{align}
  \label{eq:r1:3}
  \begin{split}
  &
  |R_1\ind\{
|a_k\varepsilon_{-k}|>(1\lor |a_k z|)
  \}|
  \\&
  \ \le \
  \ind\{|a_k\varepsilon_{-k}|>1\}
\left|
  \int_\RR
  \left(
  \int_{a_k z}^{a_k \varepsilon_{-k}}
  G_{k-1,n}^{(1)}(X_0-X_{0,k}+s)
    \ind\{|\varepsilon_{-k}|>|z|\}
  \,\mathrm{d}s
  \right)
  \mathrm{d}\PP_\varepsilon(z)
  \right|
  \\&
  \ + \
  \ind\{|a_k\varepsilon_{-k}|>1\}
\left|
  \int_\RR
  \left(
  \int_{a_k z}^{a_k \varepsilon_{-k}}
  G_{k-1,n}^{(1)}(X_0-X_{0,k})
    \ind\{|\varepsilon_{-k}|>|z|\}
  \,\mathrm{d}s
  \right)
  \mathrm{d}\PP_\varepsilon(z)
  \right|
  \,,
  \end{split}
\end{align}
and bound each term separately.
To bound the first term in \eqref{eq:r1:3}, we note that necessarily $|s|<|a_k \varepsilon_{-k}|$ and we use successively Lemma~\ref{lem:swap}.(ii), the bound $|f_{k-1}^{(1)}(x)|\lesssim g_{\gamma}(x)$ (from Lemma~\ref{lem:f}), inequality~\eqref{lem:5.1:2} from Lemma~\ref{lem:5.1}, inequality~\eqref{lem:5.1:1} from Lemma~\ref{lem:5.1}, and~\eqref{eq:iii:1}, resulting in
\begin{align*}
  &
  \ind\{|a_k\varepsilon_{-k}|>1\}
\left|
  \int_\RR
  \left(
  \int_{a_k z}^{a_k \varepsilon_{-k}}
  G_{k-1,n}^{(1)}(X_0-X_{0,k}+s)
    \ind\{|\varepsilon_{-k}|>|z|\}
  \,\mathrm{d}s
  \right)
  \mathrm{d}\PP_\varepsilon(z)
  \right| \\
  &
\ \le \
  \ind\{|a_k\varepsilon_{-k}|>1\}
  \int_{|s|\le |a_k \varepsilon_{-k}|}
  \left(
  \int_\RR
  G_n(x)
  |
  f_{k-1}^{(1)}
  (x-(X_0-X_{0,k}+s))
  |
  \,\mathrm{d}x
  \right)
  \,\mathrm{d}s \\
  &
  \ \lesssim \
  \ind\{|a_k\varepsilon_{-k}|>1\}
  \int_\RR
  G_n(x)
  \left(
  \int_{|s|\le |a_k \varepsilon_{-k}|}
  g_{\gamma}((x-(X_0-X_{0,k}))- s)
  \,\mathrm{d}s
  \right)
  \,\mathrm{d}x \\
  &
  \ \lesssim \
  |a_k\varepsilon_{-k}|^{1+\gamma}
  \int_{\RR}
  G_n(x)
  g_{\gamma}(x-(X_0-X_{0,k}))
  \,\mathrm{d}x \\
  &
  \ \lesssim \
  |a_k\varepsilon_{-k}|^{1+\gamma}
  (1+ |X_0-X_{0,k}|^{1+\gamma})
  \int_{\RR}
  G_n(x) g_{\gamma}(x)
  \,\mathrm{d}x \\
  &
  \ \lesssim \
  |a_k \varepsilon_{-k}|^{1+\gamma}
  (1+ |X_0-X_{0,k}|^{1+\gamma})
  \cdot
  u_n^{-\gamma+\gamma_G}
  \,.
\end{align*}
We now similarly estimate the second term in \eqref{eq:r1:3} using that $G_{k-1,n}^{(1)}(X_0-X_{0,k})$ is constant in $s$ 
and we obtain
\begin{align*}
  &
  \ind\{|a_k\varepsilon_{-k}|>1\}
\left|
  \int_\RR
  \left(
  \int_{a_k z}^{a_k \varepsilon_{-k}}
  G_{k-1,n}^{(1)}(X_0-X_{0,k})
    \ind\{|\varepsilon_{-k}|>|z|\}
  \,\mathrm{d}s
  \right)
  \mathrm{d}\PP_\varepsilon(z)
  \right|
\\
    &
\ \le \
  \ind\{|a_k\varepsilon_{-k}|>1\}
  \int_{|s|\le |a_k \varepsilon_{-k}|}
  \left(
  \int_\RR
  G_n(x)
  |
  f_{k-1}^{(1)}
  (x-(X_0-X_{0,k}))
  |
  \,\mathrm{d}x
  \right)
  \,\mathrm{d}s
    \\
  &
  \ \lesssim \
  \ind\{|a_k\varepsilon_{-k}|>1\}
  |a_k \varepsilon_{-k}|
  \int_\RR
  G_n(x)
  g_{\gamma}(x-(X_0-X_{0,k}))
  \,\mathrm{d}x
  \\
  &
  \ \lesssim \
  |a_k \varepsilon_{-k}|^{1+\gamma}
  (1+ |X_0-X_{0,k}|^{1+\gamma})
  \cdot
    u_n^{-\gamma+\gamma_G}
  \,,
\end{align*}
where, in the last step, we also used that $
|a_k\varepsilon_{-k}|
\le
|a_k\varepsilon_{-k}|^{1+\gamma}
$ due to $|a_k\varepsilon_{-k}|>1$.
Combining the bounds for both terms and applying the moment bound from \eqref{eq:r2:x0bdd} and $|a_k| \sim k^{-(1-d)}$, we obtain
\begin{align*}
  \norm{R_1\ind\{
  |a_k\varepsilon_{-k}|> (1\lor|a_k z| )
  \}}_{L^r(\PP)}
  \ \lesssim \
  k^{-(1+\gamma)(1-d)}u_n^{-\gamma+\gamma_G}
\,.
\end{align*}
\paragraph{Case $|a_kz|>(1\lor |a_k\varepsilon_{-k}|)$}
As in the previous case we split the integrand in \eqref{eq:r1:0}:
\begin{align}
  \label{eq:r1:6}
  \begin{split}
  &
  |R_1\ind\{
|a_kz|>(1\lor |a_k \varepsilon_{-k}|)
  \}|
  \\&
  \ \le \
\left|
  \int_\RR
  \ind\{|a_kz|>1\}
  \left(
  \int_{a_k z}^{a_k \varepsilon_{-k}}
  G_{k-1,n}^{(1)}(X_0-X_{0,k}+s)
    \ind\{|z|>|\varepsilon_{-k}|\}
  \,\mathrm{d}s
  \right)
  \mathrm{d}\PP_\varepsilon(z)
  \right|
  \\&
  \ + \
\left|
  \int_\RR
  \ind\{|a_kz|>1\}
  \left(
  \int_{a_k z}^{a_k \varepsilon_{-k}}
  G_{k-1,n}^{(1)}(X_0-X_{0,k})
    \ind\{|z|>|\varepsilon_{-k}|\}
  \,\mathrm{d}s
  \right)
  \mathrm{d}\PP_\varepsilon(z)
  \right|
  \,.
  \end{split}
\end{align}
We now bound the first term in \eqref{eq:r1:6}. The argument proceeds as in the previous case: we apply Lemma~\ref{lem:swap}.(ii) and estimate the integrals using the smoothness and decay properties of the derivative of the density $f^{(1)}_{k-1}$. We find:
\begin{align*}
  &
\left|
  \int_\RR
  \ind\{|a_kz|>1\}
  \left(
  \int_{a_k z}^{a_k \varepsilon_{-k}}
  G_{k-1,n}^{(1)}(X_0-X_{0,k}+s)
    \ind\{|z|>|\varepsilon_{-k}|\}
  \,\mathrm{d}s
  \right)
  \mathrm{d}\PP_\varepsilon(z)
  \right|
\\
  &
\ \le \
  \int_{\RR}
  \ind\{|a_kz|>1\}
  \left(
  \int_\RR
  \left(
  \int_{|s|\le |a_k z|}
  G_n(x)
  |
  f_{k-1}^{(1)}
  (x-(X_0-X_{0,k}+s))
  |
  \,\mathrm{d}s
  \right)
  \,\mathrm{d}x
  \right)
  \,\mathrm{d}\PP_{\varepsilon}(z)
    \\
  &
  \ \lesssim \
  \int_{\RR}
  G_n(x)
  \left(
  \int_\RR
  \ind\{|a_kz|>1\}
  \left(
  \int_{|s|\le |a_k z|}
  g_{\gamma}((x-(X_0-X_{0,k}))-s)
  \,\mathrm{d}s
  \right)
  \,\mathrm{d}\PP_{\varepsilon}(z)
  \right)
  \,\mathrm{d}x
  \\&
  \ \lesssim \
  \left(
  \int_{\RR}
  G_n(x)
  g_{\gamma}(x-(X_0-X_{0,k}))
  \,\mathrm{d}x
  \right)
  \left(
  \int_{\RR}
  |a_kz|^{1+\gamma}
  \,\mathrm{d}\PP_{\varepsilon}(z)
  \right)
  \\&
  \ \lesssim \
  |a_k|^{1+\gamma}
  \EE|\varepsilon|^{1+\gamma}
  (1+ |X_0-X_{0,k}|)^{1+\gamma}
  \int_{\RR}
  G_n(x)
  g_{\gamma}(x)
  \,\mathrm{d}x
  \\&
  \ \lesssim \
  |a_k|^{1+\gamma}
  (1+ |X_0-X_{0,k}|)^{1+\gamma}
  u_n^{-\gamma+\gamma_G}
  \,.
\end{align*}
We now bound the second term in \eqref{eq:r1:6}, where $G_{k-1,n}^{(1)}(X_0-X_{0,k})$ is constant in $s$:
\begin{align*}
  &
\left|
  \int_\RR
  \ind\{|a_kz|>1\}
  \left(
  \int_{a_k z}^{a_k \varepsilon_{-k}}
  G_{k-1,n}^{(1)}(X_0-X_{0,k})
    \ind\{|z|>|\varepsilon_{-k}|\}
  \,\mathrm{d}s
  \right)
  \mathrm{d}\PP_\varepsilon(z)
  \right|
\\
    &
\ \le \
  \int_{\RR}
  \ind\{|a_kz|>1\}
  \left(
  \int_{|s|\le |a_k z|}
  \left(
  \int_\RR
  G_n(x)
  |
  f_{k-1}^{(1)}
  (x-(X_0-X_{0,k}))
  |
  \,\mathrm{d}x
  \right)
  \,\mathrm{d}s
  \right)
  \mathrm{d}\PP_\varepsilon(z)
    \\
  &
  \ \lesssim \
  \left(
  \int_{|a_kz|>1}
  |a_k z|
  \mathrm{d}\PP_\varepsilon(z)
  \right)
  \left(
  \int_\RR
  G_n(x)
  g_{\gamma}(x-(X_0-X_{0,k}))
  \,\mathrm{d}x
  \right)
  \\
  &
  \ \lesssim \
  \left(
  \int_{|a_kz|>1}
  |a_k z|^{1+\gamma}
  \mathrm{d}\PP_\varepsilon(z)
  \right)
  (1+ |X_0-X_{0,k}|)^{1+\gamma}
  \left(
  \int_\RR
  G_n(x)
  g_{\gamma}(x)
  \,\mathrm{d}x
  \right)
  \\&
  \ \lesssim \
  |a_k|^{1+\gamma}
  (1+ |X_0-X_{0,k}|)^{1+\gamma}
  u_n^{-\gamma+\gamma_G}
      \,.
\end{align*}
Combining both bounds with the moment bound \eqref{eq:r2:x0bdd}, we conclude analogously to the previous case that
\begin{align*}
  \norm{R_1\ind\{
  |a_kz|> (1\lor|a_k \varepsilon_{-k}| )
  \}}_{L^r(\PP)}
  \ \lesssim \
  k^{-(1+\gamma)(1-d)}u_n^{-\gamma+\gamma_G}
\,.
\end{align*}
This completes the proof of the control of $R_1$.
\subsubsection{Analysis of $R_2$}
We begin with the estimate
\begin{align}
  \label{eq:r2:11}
  \begin{split}
  &
      |
      f_{\infty}^{(1)}(x-(X_0-X_{0,k}))
      \ - \
      f_{\infty}^{(1)}(x)
      |
      \\&
      \ \le \
      |
      f_{\infty}^{(1)}(x-(X_0-X_{0,k}))
      \ - \
      f_{\infty}^{(1)}(x)
      |
      \cdot
    \ind\{|X_0 - X_{0,k}|\le 1\}
      \\&
      + \
      \left(
      |
      f_{\infty}^{(1)}(x-(X_0-X_{0,k}))
      |
      \ + \
      |
      f_{\infty}^{(1)}(x)
      |
      \right)
    \ind\{|X_0 - X_{0,k}|> 1\}
    \,.
  \end{split}
\end{align}
Note that by inequality \eqref{lem:f:2} from Lemma~\ref{lem:f}, we have
\begin{align}
  \label{eq:r2:12}
  \begin{split}
  &
      |
      f_{\infty}^{(1)}(x-(X_0-X_{0,k}))
      \ - \
      f_{\infty}^{(1)}(x)
      |
      \cdot
    \ind\{|X_0 - X_{0,k}|\le 1\}
    \\&
    \ \lesssim \
      |X_0-X_{0,k}|
      \cdot
      g_\gamma(x)
      \,.
  \end{split}
      \intertext{
  Moreover, using~\eqref{lem:f:1} from Lemma~\ref{lem:f} and~\eqref{lem:5.1:1} from Lemma~\ref{lem:5.1}, it follows that
      }
      \label{eq:r2:13}
      \begin{split}
      &
      \left(
      |
      f_{\infty}^{(1)}(x-(X_0-X_{0,k}))
      |
      \ + \
      |
      f_{\infty}^{(1)}(x)
      |
      \right)
    \ind\{|X_0 - X_{0,k}|> 1\}
    \\&
            \ \lesssim \
            \left(
      g_\gamma
      (x-(X_0-X_{0,k})) + g_\gamma
      (x)
            \right)
    \ind\{|X_0 - X_{0,k}|> 1\}
    \\&
    \ \lesssim \
      g_\gamma(x)
      \cdot
      |X_0-X_{0,k}|^{1+\gamma}
      \,.
      \end{split}
\end{align}
Therefore, combining inequalities \eqref{eq:r2:11}-\eqref{eq:r2:13}, we get
\begin{align}
  \label{eq:r2:14}
      |
      f_{\infty}^{(1)}(x-(X_0-X_{0,k}))
      \ - \
      f_{\infty}^{(1)}(x)
      |
      \ \lesssim \
      g_{\gamma}(x)
      \left(
      |X_0-X_{0,k}|
      \lor
      |X_0-X_{0,k}|^{1+\gamma}
      \right).
\end{align}
Applying successively Lemma~\ref{lem:swap}.(ii), inequality \eqref{eq:r2:14}, and~\eqref{eq:iii:1}, we obtain
    \begin{align}
      \label{eq:r2:15}
      \begin{split}
      &
      |
      G_{\infty,n}^{(1)}(X_0-X_{0,k})
      \ - \
      G_{\infty,n}^{(1)}(0)
      |
      \\
      &
      \ \le \
      \int_{\RR}
      G_n(x)
      \cdot
       |
      f_{\infty}^{(1)}(x-(X_0-X_{0,k}))
      \ - \
      f_{\infty}^{(1)}(x)
      |
      \,\mathrm{d}x
      \\&
      \ \lesssim \
      \left(
      |X_0-X_{0,k}|
      \lor
      |X_0-X_{0,k}|^{1+\gamma}
      \right)
      \int_{\RR}
      G_n(x)
      g_\gamma(x)
      \,\mathrm{d}x
      \\&
      \ \lesssim \
      \left(
      |X_0-X_{0,k}|
      \lor
      |X_0-X_{0,k}|^{1+\gamma}
      \right)
      u_n^{-\gamma + \gamma_G}
      \,.
      \end{split}
    \end{align}
    From the definition of $R_2$, together with the independence of $X_0-X_{0,k}$ and $\varepsilon_{-k}$, and inequality \eqref{eq:r2:15}, we find
\begin{align}
  \label{eq:r2:155}
  \norm{R_2}_{L^r(\PP)}
  &
  \ \lesssim \
  k^{-(1-d)}
  \left(
  \norm{
      X_0-X_{0,k}
  }_{L^r(\PP)}
  \ + \
  \norm{
      |X_0-X_{0,k}|^{1+\gamma}
  }_{L^r(\PP)}
  \right)
  u_n^{-\gamma+\gamma_G}
  \,,
\end{align}
since $|a_k|\asymp k^{-(1-d)}$, and $\varepsilon\in L^r(\PP)$ for $r<\alpha$.
We now apply estimate~\eqref{eq:r2:x0bdd} for both $p=r$ and $p=r(1+\gamma)$.
Since 
$1/(1-d)<r<r(1+\gamma)<\alpha$ by the condition in Lemma \eqref{lem:core_r}(ii),
it follows
\begin{align}
  \label{eq:r2:16}
  \begin{split}
  \norm{
      X_0-X_{0,k}
  }_{L^r(\PP)}
  \ + \
  \norm{
      |X_0-X_{0,k}|^{1+\gamma}
  }_{L^r(\PP)}
  &
  \ \lesssim \
  k^{1/r-(1-d)}
  \ + \
  k^{1/r-(1-d)(1+\gamma)}
  \\&
  \ \lesssim \
  k^{1/r-(1-d)}
  \,.
  \end{split}
\end{align}
Note finally that
\begin{align*}
  \frac{1}{r}
  -
  2(1-d)
  &
  \ = \
  -
  (1-d)
  \left(
  1
  -
  \frac{1}{r(1-d)}
  \right)
  \ - \
  (1-d)
  \\&
  \ \le \
  -
  (1-d)
  \gamma
    \ - \
  (1-d)
  \\&
  \ = \
  -(1-d)(1+\gamma)
  \,.
\end{align*}
Combining this inequality with inequalities \eqref{eq:r2:155} and \eqref{eq:r2:16}, we obtain
\begin{equation}
  \label{eq:r2:main_result}
  \norm{R_2}_{L^r(\PP)}
  \ \lesssim \
  k^{1/r-2(1-d)}
  u_n^{-\gamma+\gamma_G}
  \ \lesssim \
  k^{
  -(1+\gamma)(1-d)
  }
  u_n^{-\gamma+\gamma_G}
  \,.
\end{equation}
This completes the proof of the control of $R_2$.
\subsubsection{Analysis of $R_3$}
    Using inequality \eqref{lem:f:3} from Lemma~\ref{lem:f} and inequality~\eqref{lem:5.1:1} from Lemma~\ref{lem:5.1}, we obtain
\begin{align}
  \label{eq:r3:3}
  \begin{split}
      |f_{\infty}^{(1)}(x-(X_0-X_{0,k}))
      \ - \
      f_{k-1}^{(1)}(x-(X_0-X_{0,k}))| &\lesssim \
      k^{-(1-d)+1/r}
      g_\gamma(x-(X_0-X_{0,k})) \\
      & \lesssim \ k^{-(1-d)+1/r} g_\gamma(x) (1\lor|X_0-X_{0,k}|)^{1+\gamma}
  \end{split}
\end{align}
    Applying Lemma~\ref{lem:swap}.(ii) together with inequality \eqref{eq:r3:3} and then~\eqref{eq:iii:1}, we obtain
    \begin{align}
      \label{eq:r3:main}
      \begin{split}
      &
      \left|
    G_{k-1,n}^{(1)}(X_0-X_{0,k})
    \ - \
    G_{\infty,n}^{(1)}
(X_0-X_{0,k})
      \right|
      \\&
      \ \lesssim \
      \int_\RR
      G_n(x)
      |
      f_{\infty}^{(1)}(x-(X_0-X_{0,k}))
      \ - \
      f_{k-1}^{(1)}(x-(X_0-X_{0,k}))
      |
      \,\mathrm{d}x
      \\&
      \ \lesssim \
      k^{-(1-d)+1/r}
      \left(
      1
      \lor
      |X_0-X_{0,k}|^{1+\gamma}
      \right)
      u_n^{-\gamma+\gamma_G}
      \,.
      \end{split}
    \end{align}
    Using the independence of $X_0-X_{0,k}$ and $\varepsilon_{-k}\stackrel{d}{=} \varepsilon \in L^r(\PP)$, together with inequality \eqref{eq:r3:main} and the fact that $|X_0-X_{0,k}|^{1+\gamma} \in L^r(\PP)$ by \eqref{eq:r2:x0bdd}, we obtain
    \begin{align*}
    \norm{
    R_3
    }_{L^r(\PP)}
    &
    \ \lesssim \
    |a_k|
      u_n^{-\gamma+\gamma_G}
      k^{-(1-d)+1/r}
      \left(
      1
      +
      \norm{|X_0-X_{0,k}|^{1+\gamma}}_{L^r(\PP)}
      \right)
    \,.
    \end{align*}
    Since $|a_k|\asymp k^{-(1-d)}$, 
    we conclude, using the same argument as in \eqref{eq:r2:main_result}, that
    \[
    \norm{
    R_3
    }_{L^r(\PP)}
    \ \lesssim \
    k^{-2(1-d)+1/r}
      u_n^{-\gamma+\gamma_G}
    \ \lesssim \
    k^{-(1-d)(1+\gamma)}
      u_n^{-\gamma+\gamma_G}
      \,.
    \]
  This completes the proof of the control of $R_3$, and therefore the proof of Lemma~\ref{lem:core_r}.(ii).

  \qed

  We have bounded the individual summands in Lemma~\ref{lem:cond_decomp}. To advance the proof
  and finally show Equation \eqref{lem:core_r:iii:final}, we now require the following lemma, which controls the rate of divergence of a convolution-type sum that arises from applying the individual bounds.
  \begin{lemma}
  \label{lem:analytic}
  Let $\gamma,r \in\RR$ satisfy
    the assumptions of Lemma~\ref{lem:core_r}(ii).
  Then for all $n\in \NN$, we have
  \begin{align*}
    \sum_{k = -\infty}^{n}
      \left(
      \sum_{t=k\lor 1}^{n}
      \left(
      1
      \land
      (t-k)
      ^{-(1-d)(1+\gamma)}
      \right)
      \right)^r
      \ \lesssim\
      n^{r+1-(1-d)(1+\gamma)r}
      \,,
    \end{align*}
    where $\lesssim$ denotes inequality up to a constant $C_{\gamma,\alpha,d}>0$, depending only on $\gamma$, $\alpha$, and $d$. We adopt the convention $1/0=\infty$.
\end{lemma}
\begin{remark}
  The above lemma actually holds with the relaxed conditions
  \begin{align*}
    0
    \ < \
    \gamma
    \ < \
    \frac{d}{1-d}
    \qquad\text{and}\qquad
    \frac{1}{1-d}
    \ < \
    r
    \,.
  \end{align*}
\end{remark}
\begin{proof}
    The sum in question can be decomposed and reindexed as
    \begin{align*}
    & \sum_{k = -\infty}^{0}
      \left(
      \sum_{t=1}^{n}
      (t-k)
      ^{-(1-d)(1+\gamma)}
      \right)^r
      \ + \
    \sum_{k = 1}^{n}
      \left(
      1
      \ + \
      \sum_{t= k+1}^{n}
      (t-k)
      ^{-(1-d)(1+\gamma)}
      \right)^r
      \\&
      \ = \
    \sum_{k = 0}^{\infty}
      \left(
      \sum_{t=k+1}^{n+k}
      t
      ^{-(1-d)(1+\gamma)}
      \right)^r
      \ + \
    \sum_{k = 1}^{n}
      \left(
      1
      \ + \
      \sum_{t= 1}^{n-k}
      t
      ^{-(1-d)(1+\gamma)}
      \right)^r
\\&
\ = \
\left(
      \sum_{t=1}^{n}
      t
      ^{-(1-d)(1+\gamma)}
      \right)^r
\ +\
    \sum_{k = n+1}^{\infty}
      \left(
      \sum_{t=k+1}^{n+k}
      t
      ^{-(1-d)(1+\gamma)}
      \right)^r
      \\&
      \ + \
    \sum_{k = 1}^{n}
    \left(
      \left(
      1
      \ + \
      \sum_{t= 1}^{n-k}
      t
      ^{-(1-d)(1+\gamma)}
      \right)^r
      \ + \
\left(
      \sum_{t=k+1}^{n+k}
      t
      ^{-(1-d)(1+\gamma)}
      \right)^r
    \right)
      \,.
    \end{align*}
    The first and second terms correspond to $k=0$ and $k>n$, respectively, in the first double sum of the previous equation.
    The third term arises from a combination of the remaining terms
    $k\in\{1,\ldots,n\}$ in the first double sum and all terms in the second double sum
    of the previous equation.
    From the assumptions on $\gamma$ and $r$, we observe that
  \begin{align*}
    (1-d)(1+\gamma) < 1
    \qquad\text{and}\qquad
    r(1-d)(1+\gamma) >1
    \,.
  \end{align*}
    We begin by estimating the first term in the decomposition above.
    Since $(1-d)(1+\gamma)<1$, we have
    \begin{align}
    \label{eq:analytic:10}
\left(
      \sum_{t=1}^{n}
      t
      ^{-(1-d)(1+\gamma)}
      \right)^r
      \ \lesssim \
      n^{r-(1-d)(1+\gamma)r}
      \ \le \
      n^{r+1-(1-d)(1+\gamma)r}
      \,.
    \end{align}
    For $k\ge 1$, again since $(1-d)(1+\gamma)<1$, we also have
    \begin{align}
      \begin{split}
      \label{eq:analytic:11}
      \sum_{t=k+1}^{n+k}
      t
      ^{-(1-d)(1+\gamma)}
      &
      \ \le \
      \min\left( n
      \cdot
      k^{-(1-d)(1+\gamma)},
      \int_k^{n+k}
      t
      ^{-(1-d)(1+\gamma)}
      \,\mathrm{d}t \right) \\
      & \ \lesssim \
      \min\left( n
      \cdot
      k^{-(1-d)(1+\gamma)},
      (n+k)^{1-(1-d)(1+\gamma)}
      \right) \,.
      \end{split}
    \end{align}
    Using the first bound in the estimate~\eqref{eq:analytic:11} and the fact that $(1-d)(1+\gamma)r>1$, we obtain
    \begin{align*}
      &
    \sum_{k = n+1}^{\infty}
      \left(
      \sum_{t=k+1}^{n+k}
      t
      ^{-(1-d)(1+\gamma)}
      \right)^r
      \\&
    \ \lesssim \
    n^r
    \sum_{k = n+1}^{\infty}
      k^{-(1-d)(1+\gamma)r}
      \ \lesssim \
    n^r
    \int_n^\infty
      t^{-(1-d)(1+\gamma)r}
      \,\mathrm{d}t
      \ \lesssim \
      n^{r+1-(1-d)(1+\gamma)r}
      \,.
     \end{align*}
    Applying the second bound in estimate~\eqref{eq:analytic:11},
    we obtain
    \[
    \sum_{k = 1}^{n}
\left(
      \sum_{t=k+1}^{n+k}
      t
      ^{-(1-d)(1+\gamma)}
      \right)^r
      \ \lesssim \
    \sum_{k = 1}^{n}
      (n+k)^{r-(1-d)(1+\gamma)r}
    \ \lesssim \
      n^{r+1-(1-d)(1+\gamma)r}
      \,.
    \]
    Finally,
    recalling the first bound in~\eqref{eq:analytic:10}, we obtain
    \begin{align*}
 \sum_{k = 1}^{n}
      \left(
      1
      \ + \
      \sum_{t= 1}^{n-k}
      t
      ^{-(1-d)(1+\gamma)}
      \right)^r
      \ \lesssim \
      n
      \left(
      \sum_{t=1}^n
      t^{-(1-d)(1+\gamma)}
      \right)^r
      \ \lesssim \
      n^{r+1-(1-d)(1+\gamma)r}
      \,.
    \end{align*}
    This completes the proof of the lemma.
    \end{proof}
    With all necessary tools in hand, we now turn to the final part of the proof.
\subsection{
Proof of Theorem~\ref{thm:approx}
}
    Let
    $n>k_0$.
    We are going to apply Lemmas~\ref{lem:cond_decomp}, \ref{lem:core_r}, and \ref{lem:analytic}.
    We begin the proof.
    By Lemma~\ref{lem:cond_decomp}, it follows
    \[
      \EE
      \left|
      \sum_{t=1}^n
      G_n(X_t)
      \ - \
      \EE[G_n(X_t)]
      \ - \
      G_{\infty,n}^{(1)}(0)X_t
      \right|^r
      \ \lesssim \
      \sum_{k=-\infty}^{n}
      \left(
      \sum_{t=k\lor 1}^{n}
      \norm{
      P_{k-t}\, \mathcal{U}_n(X_0)
      }_{L^r(\PP)}
      \right)^r
      \,,
    \]
    where $\mathcal{U}_n(X_t):=G_n(X_t)-\EE[G_n(X_t)]-G_{\infty,n}^{(1)}(0)X_t$. We split the inner sum based on whether $t-k>k_0+1$ and use the convexity of $x\mapsto x^r$ (due to $r>1$) to get
    \begin{align*}
      &\EE
      \left|
      \sum_{t=1}^n
      G_n(X_t)
      \ - \
      \EE[G_n(X_t)]
      \ - \
      G_{\infty,n}^{(1)}(0)X_t
      \right|^r \\
      &
      \ \lesssim \
      \sum_{k=-\infty}^{n}
      \left(
      \sum_{
      \begin{smallmatrix}
        (1\lor k)\le t \le n\\
        t-k > k_0+1
      \end{smallmatrix}
      }
      \norm{
      P_{k-t}\, \mathcal{U}_n(X_0)
      }_{L^r(\PP)}
      \right)^{r}
      \ + \
      \sum_{k=-\infty}^{n}
      \left(
      \sum_{
      \begin{smallmatrix}
        (1\lor k)\le t \le n\\
        t-k \le k_0+1
      \end{smallmatrix}
      }
      \norm{
      P_{k-t}\, \mathcal{U}_n(X_0)
      }_{L^r(\PP)}
      \right)^r
           \,.
    \end{align*}
    For the first term, we apply Lemma~\ref{lem:core_r}.(ii) and Lemma~\ref{lem:analytic}.
    This yields
    \begin{align*}
      &
      \sum_{k=-\infty}^{n}
      \left(
      \sum_{
      \begin{smallmatrix}
        (1\lor k)\le t \le n\\
        t-k > k_0+1
      \end{smallmatrix}
      }
      \norm{
      P_{k-t}\, \mathcal{U}_n(X_0)
      }_{L^r(\PP)}
      \right)^{r}
      \\&
      \ \lesssim \
      u_n^{(\gamma_G-\gamma)r}
      \sum_{k=-\infty}^{n}
      \left(
      \sum_{
      t=1\lor k
      }^n
      \left(
      1
      \land
      (t-k)^{-(1-d)(1+\gamma)}
      \right)
      \right)^{r}
      \\&
      \ \lesssim \
      u_n^{(\gamma_G-\gamma)r}
      n^{r+1-(1-d)(1+\gamma)r}
      \,.
    \end{align*}
    For the second term, note that the constraints $t\le k_0+k+1$ and $t \ge (1\lor k)$ ensure that the inner sum is empty when $k<-k_0$. Therefore, applying Lemma~\ref{lem:2.2}.(ii), we obtain for sufficiently large $n\in\NN$ that
    \begin{align*}
      &
      \sum_{k=-\infty}^{n}
      \left(
      \sum_{
      \begin{smallmatrix}
        (1\lor k)\le t \le n\\
        t-k \le k_0 +1
      \end{smallmatrix}
      }
      \norm{
      P_{k-t}\, \mathcal{U}_n(X_0)
      }_{L^r(\PP)}
      \right)^r
      \\&
 \ \lesssim \
      \left(
      \norm{G_n(X_0)}_{L^r(\PP)}
      \lor
      |G_{\infty,n}^{(1)}(0)|
      \right)^{r}
      \sum_{k=-k_0}^{n}
      \left(
      \#
      \{
      t\in\NN
      \,\colon\,
        (1\lor k)\le t \le (n\land (k+k_0+1))
      \}
      \right)^r
      \\&
 \ \leq \
      \left(
      \norm{G_n(X_0)}_{L^r(\PP)}
      \lor
      |G_{\infty,n}^{(1)}(0)|
      \right)^{r}
      \sum_{k=-k_0}^{n}
      \left(
      \#
      \{
      t\in\NN
      \,\colon\,
        k\le t \le k+k_0+1
      \}
      \right)^r
      \\&
      \ = \
      \left(
      \norm{G_n(X_0)}_{L^r(\PP)}
      \lor
      |G_{\infty,n}^{(1)}(0)|
      \right)^{r}
      (n+k_0+1)(k_0+2)^r
      \\&
      \ \lesssim \
      n \left(
      \EE[|G_n(X_0)|^r]
      \lor
      |G_{\infty,n}^{(1)}(0)|^r
      \right)
      \,.
    \end{align*}
    We conclude that
    \begin{align*}
      \EE
      \left[
      \left|\sum_{t=1}^n \mathcal{U}_n(X_t)\right|^r
      \right]
      \ \lesssim \
      u_n^{(\gamma_G-\gamma)r}n^{r+1 - (1-d)(1+\gamma)r}
      \ + \ n
      \left(
      \EE[|G_n(X_0)|^r]
      \lor
      |G_{\infty,n}^{(1)}(0)|^r
      \right)
    \,.
    \end{align*}
    This is the first inequality we wanted to prove. For the second inequality, observe that $1-(1-d)(1+\gamma) \ge 0$  due to $\gamma \le d/(1-d)$. Therefore 
    the $n$ rate of the first term dominates.
Since $\gamma_G<\gamma$, it holds that $u_n^{\gamma_G-\gamma}<\infty$ for all $n\in\mathbb{N}$. Applying Lemma~\ref{lem:swap} gives that $\EE[|G_n(X_0)|^{r}]<\infty$ and $|G_{\infty,n}'(0)|<\infty$ for all $n\in\mathbb{N}$, such that we may conclude
\begin{align*}
   u_n^{(\gamma_G-\gamma)r}n^{r+1 - (1-d)(1+\gamma)r}
      \ + \ n
      \left(
      \EE[|G_n(X_0)|^r]
      \lor
      |G_{\infty,n}^{(1)}(0)|^r
      \right)
      \ \lesssim \ 
   n^{r+1 - (1-d)(1+\gamma)r}
   \,.
\end{align*}
Taking power $1/r$ on both sides of the inequality finishes the proof.
    \qed

Having established a $L^r(\PP)$ moment bound in Theorem~\ref{thm:approx}, we now turn to the proof of Theorem~\ref{thm:approx_optimal} which sharpens the result by identifying the optimal rate of convergence. This requires a careful balance of the parameters $\gamma$ and $r$.

\subsection{Proof of Theorem~\ref{thm:approx_optimal}}

     Combining Theorem~\ref{thm:approx} with the following proposition immediately gives the desired result 
     \begin{proposition}
\label{prop:optim}
 Denote
      $\kappa(\gamma,r)=1+1/r-(1-d)(1+\gamma)$.
       \begin{enumerate}[label=(\roman*)]
         \item
      There exists a pair of unique minimizers $(\gamma_0,r_0)$ of $\kappa(\gamma,r)$ over the compact domain
      \begin{align*}
        0
         \ \le \
         \gamma
         \ \le \
  \min \left\{
  \frac{d}{1-d}
  \,,
         1
          -
         \frac{1}{r(1-d)}
         \,,
         \frac{\alpha}{r}
          -
         1
  \right\}
           \qquad\text{and}\qquad
         \frac{1}{1-d}
         \ \le \
         r
         \ \le \
         \alpha
         \,,
      \end{align*}
       namely
       \begin{align*}
 \gamma_0
   :=
  \begin{cases}
    \frac{d}{1-d}
    &
    \ \text{if}\
    \frac{1}{(1-d)(1-2d)}
    < \alpha\,,\\
    \frac{\alpha(1-d)-1}{\alpha(1-d)+1}
    &
    \
    \text{else,}
  \end{cases}
  \
  r_0
   :=
  \begin{cases}
    \alpha(1-d)
    &
    \ \text{if}\
    \frac{1}{(1-d)(1-2d)}
    < \alpha\,,\\
    \frac{1}{2}
    \left(
    \frac{1}{1-d}
    \ + \ \alpha
    \right)
    &
    \
    \text{else,}
  \end{cases}
  \end{align*}
  yielding
  \begin{align*}
  \kappa_0
    \ = \
    \kappa(\gamma_0,r_0)
  \ = \
  \left\{ \begin{array}{l}
    \frac{1}{\alpha(1-d)}
    \ \text{ if } \
    \frac{1}{(1-d)(1-2d)}
    < \alpha\,,\\[10pt]
    \frac{2(1-d) + (1-\alpha(1-d)(1-2d))}{\alpha(1-d)+1} = d
    \ + \
    (1-d)
    \frac{3-\alpha(1-d)}{\alpha(1-d)+1}
    \ \text{ else.}
  \end{array} \right.
\end{align*}
\item
It holds
\begin{align*}
  \gamma_0
  \ = \
  \min \left\{
  \frac{d}{1-d}
  \,,
         1
          -
         \frac{1}{r_0(1-d)}
         \,,
         \frac{\alpha}{r_0}
          -
         1
  \right\}
  \,,\quad
  r_0
  \in
  \left(
  \frac{1}{1-d}
  \,,
  \alpha
  \right)
  \end{align*}
  and
  \begin{align*}
  \kappa_0
  \ - \ (d+1/\alpha)
  \ < \
  0
  \,.
\end{align*}
\end{enumerate}
\end{proposition}

\begin{proof}
     We begin with (i).
     The goal is to 
     minimize
     \begin{align*}
  \kappa(\gamma,r)
  \ = \
  1
  \ + \
  \frac{1}{r}
  \ - \
  (1-d)(1+\gamma)
  \,.
\end{align*}
over $\gamma$ and $r$ from the 
closure of the range in Theorem~\ref{thm:approx}(i), namely such that
\begin{align*}
  0
         \ \le \
         \gamma
         \ \le \
         \gamma(r)
         \qquad\text{and}\qquad
         \frac{1}{1-d}
         \ \le \
         r
         \ \le \
         \alpha
         \,,
\end{align*}
where the function $\gamma(r)$ is defined as
\begin{align*}
   \gamma(r)
   \ := \
         \gamma_{1}(r)
         \
         \land
         \
         \gamma_{2}(r)
         \
         \land
         \
         \gamma_{3}(r)
         \,,
 \end{align*}
 with
 \begin{align*}
   \gamma_1(r)
   \ := \
   \frac{d}{1-d}
   \,,
   \qquad
   \gamma_2(r)
   \ := \
   1
   -
   \frac{1}{r(1-d)}
   \,,
   \qquad
   \gamma_3(r)
   \ := \
   \frac{\alpha}{r}
   -
   1
   \,.
 \end{align*}
The function $\kappa$ is continuous and strictly decreasing in both $\gamma$ and $r$, which implies that
\[
  (\gamma_0,r_0)
  \
  =
  \
  \mathrm{argmin} \left\{ \kappa(\gamma,r)
  \, \Bigg| \,
  (\gamma,r)\in K
  \right\}
  \quad
  \text{with}
  \quad
   K:=  \left\{
  (\gamma(r),r)
  \, \Bigg| \,
  \frac{1}{1-d}
  \ \le \
  r
  \ \le \
  \alpha
  \right\}
  \,.
\]
Moreover, for any admissible value of $r$, the value of $\kappa(\gamma(r),r)$ is determined by the smallest among $\gamma_1(r),\gamma_2(r),\gamma_3(r)$. Specifically,
\begin{align*}
  \kappa(\gamma(r),r)
  \ = \
  \begin{cases}
    \kappa(\gamma_{1}(r),r)\,,&\qquad \gamma_{1}(r)\le (\gamma_2(r)\land \gamma_{3}(r))\,,\\
    \kappa(\gamma_{2}(r),r)\,,&\qquad \gamma_{2}(r)\le (\gamma_1(r)\land \gamma_{3}(r))\,,\\
    \kappa(\gamma_{3}(r),r)\,,&\qquad \gamma_{3}(r)\le (\gamma_1(r)\land \gamma_{2}(r))\,.\\
  \end{cases}
\end{align*}
Note that $r\mapsto \kappa(\gamma(r),r)$ is not differentiable everywhere. We shall therefore argue that on the set where it is differentiable the derivative does not vanish and therefore the optimal values have to lie on the boundary.
Note that this set is essentially
\begin{align*}
\left\{ r>0 \, \mid \, (\gamma_1(r),\gamma_2(r),\gamma_3(r))\  \mbox{are pairwise distinct} \right\},
\end{align*}
and it is nonempty because $\alpha>1/(1-d)$, and open since each $\gamma_j(r)$ is continuous. Next, we compute the derivative of $r\mapsto \kappa(\gamma(r),r)$ on this set. 
 Clearly, for all $r>0$ it holds that
\begin{align*}
   \gamma_{1}'(r)
   \ = \
   0
   \,,
   \qquad
   \gamma_{2}'(r)
   \ = \
   \frac{1}{r^2(1-d)}
   \,,
   \qquad
   \gamma_{3}'(r)
   \ = \
   -
   \frac{\alpha}{r^2}
   \,.
 \end{align*}
 Applying the chain rule yields
 \begin{align*}
   &
   \frac{\mathrm{d}}{\mathrm{d}r}
   \kappa(\gamma_{j}(r),r)
   \ = \
   \gamma_j'(r)
  \frac{\partial}{\partial \gamma}
   \kappa(\gamma_j(r),r)
   \ + \
  \frac{\partial}{\partial r}
   \kappa(\gamma_j(r),r)
   \\&
   \ = \
   -
   \gamma_j'(r)
   (1-d)
   \ - \
\frac{1}{r^2}
   \,.
 \end{align*}
 Setting the derivative equal to zero gives
 \begin{align*}
   \gamma_j'(r)
   \ = \
   -
   \frac{1}{r^2(1-d)}
   \,.
 \end{align*}
 This equation clearly has no solution for $j=1,2$.
 For $j=3$, solving yields $\alpha=1/(1-d)$, which contradicts our assumption that $\alpha>1/(1-d)$.
 Therefore, we conclude that
 for all $r>0$ it holds that
 \begin{align*}
   \frac{\mathrm{d}}{\mathrm{d}r}
   \kappa(\gamma_{j}(r),r)
   \
   \neq
   \
   0
   \qquad\text{for}\ j=1,2,3
   \,.
 \end{align*}
To complete the analysis, we examine the behavior of $\kappa(\gamma(r),r)$ at values of $r$ where two or more of the functions $\gamma_j(r)$ coincide.

We begin by identifying the intersection points of the functions $\gamma_1(r),\gamma_2(r)$, and $\gamma_3(r)$.
Note that $\gamma_1$ is constant, $\gamma_2$ is strictly increasing, and $\gamma_3$ is strictly decreasing. Hence, each pair of functions can intersect at most once. These intersections occur at
\begin{align*}
\gamma_1
\
  =
\
  \gamma_2(r)
  \ = \
  \frac{d}{1-d}
  \qquad\text{if and only if}\qquad
  r
  \ = \
  r_{1,2}
  \ := \
  \frac{1}{1-2d}
  \,,
\end{align*}
\begin{align*}
\gamma_1
\
  =
\
  \gamma_3(r)
  \ = \
  \frac{d}{1-d}
  \qquad\text{if and only if}\qquad
  r
  \ = \
  r_{1,3}
  \ := \
  \alpha(1-d)
  \,,
\end{align*}
\begin{align*}
\gamma_2(r)
\
  =
\
  \gamma_3(r)
  \ = \
  \frac{\alpha(1-d)-1}{\alpha(1-d)+1}
  \qquad\text{if and only if}\qquad
  r
  \ = \
  r_{2,3}
  \ := \
  \frac{1}{2}
  \left(
  \frac{1}{1-d}
  \ + \
  \alpha
  \right)
  \,.
\end{align*}
We next need to calculate $\kappa(\gamma(r),r)$ at $r \in \{r_{1,2},r_{1,3},r_{2,3}\}$, which requires computing $\gamma(r)=\gamma_1\wedge\gamma_2(r)\wedge\gamma_3(r)$ at these points. To determine whether $\gamma_2(r_{2,3})$ lies above or below $\gamma_1$, we examine the sign of the difference:
\begin{align*}
  \mathrm{sgn}
  \left(
  \gamma_2(r_{2,3})
  \ - \
  \frac{d}{1-d}
  \right)
  \ = \
  \mathrm{sgn}
  \left(
  \alpha(1-d)(1-2d)
  \ - \ 1
  \right)
  \,.
\end{align*}
Thus,
\begin{align*}
  \gamma_2(r_{2,3})
  \ > \
  \frac{d}{1-d}
  \ = \
  \gamma_1
  \qquad\text{if and only if}\qquad
  \alpha
  \ > \
  \frac{1}{(1-d)(1-2d)}
  \,.
\end{align*}
We now distinguish between the two cases:
\begin{itemize}
  \item
$\alpha(1-d)(1-2d)> 1$
\item
$\alpha(1-d)(1-2d)\leq 1$
\end{itemize}
In the first case, $\alpha(1-d)(1-2d)>1$, the ordering of the intersection points is
\begin{align*}
   r_{1,2}
  \ < \
  r_{2,3}
  \ < \
  r_{1,3}
  \,,
\end{align*}
and we therefore have $\gamma(r)=d/(1-d)$ for all $r\in\{r_{1,2},r_{2,3},r_{1,3}\}$ due to the monotonicity properties of $\gamma_2$ and $\gamma_3$, see the left panel of Figure~\ref{fig:optimal}.
\begin{figure}[h]
    \centering
    \includegraphics[width=1\textwidth]{optimal_plot.png}
    \caption{General position of the curves representing the functions $\gamma_1$ (blue dotted line), $\gamma_2$ (orange dotted line) and $\gamma_3$ (green dotted line) in the cases $\alpha(1-d)(1-2d)> 1$ (left panel) and $\alpha(1-d)(1-2d)\leq 1$ (right panel). The purple curve represents the function $\gamma_1\wedge \gamma_2 \wedge \gamma_3$.
    }
  \label{fig:optimal}
\end{figure}
Since $\kappa$ is decreasing in both $\gamma$ and $r$,
the optimal value is attained at the largest feasible $r$, which in this case is $r_{1,3}$, provided it lies within the admissible interval.
Note that the inequality chain
\begin{align*}
 \frac{1}{1-d}
 \ < \
  \alpha(1-2d)
  \ < \
  \alpha(1-d)
  \ = \
  r_{1,3}
  \ < \
  \alpha
  \,,
\end{align*}
confirms that $r_{1,3}$ lies within the range $(1/(1-d),\alpha)$, and is therefore an admissible choice for minimizing $\kappa$ over $K$.
We conclude that, when $\alpha(1-d)(1-2d)>1$, the optimal choice is $(\gamma_0,r_0)=(d/(1-d),\alpha(1-d))$.
If on the contrary $\alpha(1-d)(1-2d)\le 1$, we have the ordering
\begin{align*}
   r_{1,3}
  \ \le \
  r_{2,3}
  \ \le \
  r_{1,2}
  \qquad\text{and}\qquad
  \gamma(r_{1,2})
  ,
  \gamma(r_{1,3})
  \ \le \
  \gamma(r_{2,3})
\end{align*}
as the right panel of Figure~\ref{fig:optimal} indicates. For $r\in[r_{2,3}, r_{1,2}]$, we have $\gamma(r)=\gamma_3(r)=\alpha/r-1$, and thus
\begin{align*}
  \kappa(\gamma(r),r)
  \ = \
  \kappa
  \left(
  \frac{\alpha}{r}
   -  1,r
  \right)
  \ = \
  1
  \ + \
  \frac{1}{r}
  (1-\alpha(1-d))
  \,.
\end{align*}
Since $\alpha(1-d)>1$ by assumption, this function is increasing in $r$ on the interval $[r_{2,3},r_{1,2}]$, so 
$\kappa(\gamma(r),r)$ is minimal at $r=r_{2,3}$ on this interval.
As both $r_{1,3}\le r_{2,3}$ and $\gamma(r_{1,3})\le \gamma(r_{2,3})$ (see again the right panel of Figure~\ref{fig:optimal}), and since $\kappa$ is decreasing in both $\gamma$ and $r$, the minimum of $\kappa(\gamma(r),r)$ over the full interval $[r_{1,3},r_{2,3}]$ is attained at $r=r_{2,3}$. Finally, given that $r_{2,3}$ lies in the center of the interval $[1/(1-d),\alpha]$, it is therefore an admissible choice for minimizing $\kappa$ over $K$. Therefore, the optimal choice in the case $\alpha(1-d)(1-2d)\le 1$ is
\[
(\gamma_0, r_0) = \left( \frac{\alpha(1-d)-1}{\alpha(1-d)+1}
  \,,
  \frac{1}{2}
  \left(
  \frac{1}{1-d}
  \ + \
  \alpha
  \right)
  \right)
  \,.
\]
Plugging the values of $\gamma_0$ and $r_0$ into $\kappa(\gamma,r)$ finishes the proof of (i).

For (ii) note that we already showed that $r_0\in(1/(1-d),\alpha)$, and the statement about $\gamma_0$ follows from $\gamma_0=\gamma_1(r_0)\wedge \gamma_2(r_0)\wedge \gamma_3(r_0)$. 
From what we showed it also follows that $\gamma_0$ lies on the upper bound of the admissible interval for $\gamma$.
It remains to show $\kappa_0 - (d+1/\alpha)<0$. In the case $\alpha(1-d)(1-2d)>1$ this follows from
\begin{align*}
  \frac{1}{\alpha(1-d)}
  \ - \
  d
  \ - \
  \frac{1}{\alpha}
  \ = \
  \frac{1 - (1-d)(\alpha d + 1 )}{\alpha(1-d)}
  \ = \
  \frac{d(1-\alpha(1-d))}{\alpha(1-d)}
  \ < \
  0
  \,,
\end{align*}
since $\alpha(1-d)>1$.
In the opposite case $\alpha(1-d)(1-2d)\le 1$, it holds that
\begin{align*}
  &
    d
    \ + \
    (1-d)
    \frac{3-\alpha(1-d)}{\alpha(1-d)+1}
\ - \
d
\ - \
\frac{1}{\alpha}
  \\&
  \ = \
  \frac{1}{\alpha(\alpha(1-d)+1)}
  \left(
  \alpha(1-d)(3 - \alpha(1-d))
  \ - \
  \alpha(1-d) - 1
  \right)
  \\&
  \ = \
  \frac{1}{\alpha(\alpha(1-d)+1)}
  \left(
  \alpha(1-d)(2 - \alpha(1-d))
  \ - \
  1
  \right)
  \,.
  \intertext{By $\alpha(1-d)(1-2d)\le 1$ and $\alpha(1-d)\le \alpha \le 2$ this is bounded above by}
  &
  \frac{1}{\alpha(\alpha(1-d)+1)}
  \left(
  \frac{
  2 - \alpha(1-d)
  }{1-2d}
  \ - \
  1
  \right)
  \,,
  \intertext{which in turn by $\alpha(1-d)>1$ is bounded above by }
  &
  \frac{1}{\alpha(\alpha(1-d)+1)}
  \left(
  \frac{
  1
  }{1-2d}
  \ - \
  1
  \right)
  \ < \ 0\,.
\end{align*}
It follows (ii).
\end{proof}
\subsection{Proof of Corollaries~\ref{cor:heavy_det} and~\ref{cor:light_det}}
\begin{proof}[Proof of Corollary~\ref{cor:heavy_det}]
  We want to apply Corollary~\ref{cor:sub_ord_univariateI_optim} for $G_n(x)=\ind\{x>u_n\}$ and $G_n(x)=\log(x/u_n)\ind\{x>u_n\}$, respectively.
  Note that both choices of $G_n$ satisfy Assumption~\ref{asu:G_n} for all $\gamma_G>0$ arbitrarily small.
  By Lemma~\ref{lem:swap} it holds $\EE[G_n(X_0)] = \PP[X_0>u_n]$ and $G_{\infty,n}'(0)
    =f_{X_0}(u_n)$ for $G_n(x)=\ind\{x>u_n\}$. Besides, for $G_n(x)=\log(x/u_n)\ind\{x>u_n\}$, one has
  \begin{align*}
    \EE[G_n(X_0)]
    \ &= \
    \int_{u_n}^\infty \log(x/u_n)f_{X_0}(x)
    \,\mathrm{d}x
    \ \sim\
    \frac{
    \PP[X_0>u_n]
    }{\nu}
  \end{align*}
  by the regular variation property of $f_{X_0}$ (see {\it e.g.} \cite[Equation~(3.2.1)]{dehaanExtremeValueTheory2006}, and
  \begin{align*}
    G_{\infty,n}'(0)
    \ &= \
    -\int_{u_n}^\infty \log(x/u_n)f'_{X_0}(x)
    \,\mathrm{d}x
    \ = \
    \int_{u_n}^\infty
    \frac{
    f_{X_0}(x)
    }{x}
    \,\mathrm{d}x
    \ \sim\
    \frac{
    f_{X_0}(u_n)
    }{\nu+1}
    \,,
  \end{align*}
  by partial integration and Karamata's theorem \cite[Theorem~B.1.5]{dehaanExtremeValueTheory2006}.
  Therefore it holds for $G_n(x)=\ind\{x>u_n\}$ that
  \begin{align*}
    \frac{\EE[G_n(X_0)]}{G_{\infty,n}'(0)}
    \ = \
    \frac{
    \PP[X_0>u_n]
    }{f_{X_0}(u_n)}
    \ \sim
    \
    \frac{u_n}{\nu}
    \,,
  \end{align*}
  by Karamata's theorem again, and for $G_n(x)=\log(x/u_n)\ind\{x>u_n\}$ that
  \begin{align*}
    \frac{\EE[G_n(X_0)]}{G_{\infty,n}'(0)}
    \sim
    \frac{
    \PP[X_0>u_n]
    }
    {f_{X_0}(u_n)}
    \frac{\nu+1}{\nu}
    \ \sim \
    u_n
    \frac{1}{\nu}
    \frac{\nu+1}{\nu}
    \,.
  \end{align*}
  We finally check that $n^{\kappa_0+\delta/2-1/(\nu\land 2)-d}/G_{\infty,n}'(0)\to 0$.
  For this it suffices to consider
  \begin{align*}
    \frac{n^{\kappa_0+\delta/2-1/(\nu\land 2)-d}}{f_{X_0}(u_n)}
   \  \sim\
    L(u_n)
    n^{\kappa_0+\delta/2-1/(\nu\land 2)-d}
    u_n^{\nu+1}
  \end{align*}
  where $L:x\mapsto x^{-\nu-1}/f_{X_0}(x)$ is slowly varying.  
  Note that the term in the last display converges to zero since $u_n^{\nu+1}=o(n^{-\kappa_0-\delta+d+1/(\nu\land 2)})$ and $L(u_n)=o(n^{\delta/2})$.
  Therefore, we may apply Corollary~\ref{cor:sub_ord_univariateI_optim} to yield the desired results.
\end{proof}

For the proof of Corollary~\ref{cor:light_det} we require the following auxiliary result.
\begin{lemma}
\label{lem:gronwall}
  If $\omega\in C^1(\RR)$ is positive and satisfies, for some $\beta>0$, that $x^{1-\beta}\omega'(x)/\omega(x)\to 0$ as $x\to\infty$, then for all $p\in\mathbb{R}$ it holds that  $x^{p}\omega(x)\exp(-x^{\beta}/\beta)\to 0$ as $x\to\infty$.
\end{lemma}
\begin{proof}
  Since
  $x^{1-\beta}\omega'(x)/\omega(x)\to 0$ as $x\to\infty$,
  there exists $x_0>0$ with $\omega'(x)\leq \frac{1}{2} x^{\beta-1} \omega(x)$ for all $x> x_0$.
  By Grönwall's lemma it holds, for $x>x_0$, 
 \begin{align*}
  \omega(x)
  \ \le \
  \omega(x_0)
  \exp(-x_0^{\beta}/(2\beta))
  \exp(x^{\beta}/(2\beta))
  \,.
\end{align*}
Therefore, it holds that for any $p\in\mathbb{R}$, as $x\to\infty$, 
  \begin{align*}
  x^{p}
  \omega(x)
  \exp(-x^{\beta}/\beta)
  \ \lesssim \
  x^{p}
  \exp(-x^{\beta}/(2\beta))
  \ \to\ 0
  \,,
\end{align*}
which immediately yields the result since $\omega$ is assumed to be non-negative. 
\end{proof}

\begin{proof}[Proof of Corollary~\ref{cor:light_det}]
  We proceed as in the proof of Corollary~\ref{cor:heavy_det}.
  There we checked that Assumption~\ref{asu:G_n} holds. We next establish the limit
  \begin{equation}
  \label{eqn:hopital}
  \lim_{n\to\infty}
    \frac
    {u_n^{1-\beta} f_{X_0}(u_n)}
    {\PP[X_0>u_n]} = 1.
  \end{equation}
  Let $\phi:x\mapsto x^{1-\beta} f_{X_0}(x)$ and $\psi:x\mapsto \PP[X_0>x]$. The functions $\phi$ and $\psi$ are differentiable in a neighborhood of infinity, converge to 0 at infinity, and $\psi'(x)=-f_{X_0}(x)<0$ for $x$ large enough. Moreover $x^{1-\beta}\omega'(x)/\omega(x)\to 0$ as $x\to\infty$ since $\beta>0$ and $\omega'$ is either identically zero far from the origin or regularly varying at infinity, so that
  \[
  \lim_{x\to\infty} \frac{\phi'(x)}{\psi'(x)} = \lim_{x\to\infty} -\frac{(1-\beta) x^{-\beta} f_{X_0}(x) + x^{1-\beta} f'_{X_0}(x)}{f_{X_0}(x)} = \lim_{x\to\infty} \left( 1-x^{1-\beta}\frac{\omega'(x)}{\omega(x)} \right)=1. 
  \]
  Then~\eqref{eqn:hopital} follows from l'H\^{o}pital's rule, that is, 
  \[
  \lim_{n\to\infty}
    \frac
    {u_n^{1-\beta} f_{X_0}(u_n)}
    {\PP[X_0>u_n]} = \lim_{n\to\infty}
    \frac
    {\phi(u_n)}
    {\psi(u_n)} = \lim_{n\to\infty}
    \frac
    {\phi'(u_n)}
    {\psi'(u_n)} = 1.
  \]
  Therefore $\PP[X_0>u_n]\sim u_n^{1-\beta}f_{X_0}(u_n)$.
  Next, note that by partial integration it holds
  \begin{align*}
  \EE[G_n(X_0)] &=\int_{u_n}^\infty
    \log(x/u_n)
    f_{X_0}(x)
    \,\mathrm{d}x \\
    &= -
    \lim_{x\to\infty}
    \log(x/u_n)\PP[X_0>x]
    \ +\ 
    \int_{u_n}^\infty
    \frac{\PP[X_0>x]}{x}
    \,\mathrm{d}x \ =\  \int_{u_n}^\infty
    \frac{\PP[X_0>x]}{x}
    \,\mathrm{d}x
  \end{align*}
  as the boundary term vanishes due to Lemma~\ref{lem:gronwall}. Similarly we get 
  \begin{align*}
  G_{\infty,n}'(0)=-\int_{u_n}^\infty
    \log(x/u_n)
    f'_{X_0}(x)
    \,\mathrm{d}x
    \ =\ 
    \int_{u_n}^\infty
    \frac{f_{X_0}(x)}{x}
    \,\mathrm{d}x
    \,.
  \end{align*}
  Note that
  \begin{align*}
    \lim_{n\to\infty}
    \frac{u_n^{-\beta} \PP[X_0>u_n]}
    {
    \int_{u_n}^{\infty}
    \frac{\PP[X_0>x]}{x}
    \,\mathrm{d}x
    }
    \ = \ 
    \lim_{n\to\infty}
    \frac{\beta u_n^{-\beta-1}\PP[X_0>u_n]+u_n^{-\beta}f_{X_0}(u_n)}{
    \PP[X_0>u_n]/u_n
    }
    \ = \ 1
    \,,
  \end{align*}
  and
  \begin{align*}
    \lim_{n\to\infty}
    \frac{u_n^{-1} \PP[X_0>u_n]}
    {
    \int_{u_n}^{\infty}
    \frac{f_{X_0}(x)}{x}
    \,\mathrm{d}x
    }
    \ = \ 
    \lim_{n\to\infty}
    \frac{u_n^{-2}\PP[X_0>u_n]+u_n^{-1}f_{X_0}(u_n)}{
    f_{X_0}(u_n)
    /u_n
    }
    \ = \ 1
    \,,
  \end{align*}
  where we used twice that $\PP[X_0>u_n]\sim u_n^{1-\beta}f_{X_0}(u_n)$ and l'H\^{o}pital's rule in a way similar to what was done above. This yields $\EE[G_n(X_0)]/G_{\infty,n}'(0)\sim u_n^{1-\beta}$.
  Finally we check that $n^{\kappa_0+\delta/2-d-1/2}/G_{\infty,n}'(0)\to 0$.
  Since $G_{\infty,n}'(0)\sim u_n^{-\beta} f_{X_0}(u_n)$, this boils down to
  \begin{align}
  \label{eq:omega_vanish}
  \frac{
  n^{\kappa_0+\delta/2-d-1/2}
  }{u_n^{-\beta}\omega(u_n)\exp(-u_n^{\beta}/\beta)}
  \ = \ 
  \frac{n^{-\delta/2}}{u_n^{-\beta}\omega(u_n)}
  \ \to \ 0
  \end{align}
  due to the regular variation property of $\omega$.
  Then, as before, applying Corollary~\ref{cor:sub_ord_univariateI_optim} yields the results.
\end{proof}


\section{Derandomization Device}

We state and prove our derandomization lemma which is the main ingredient in proving the convergence of PoT estimators with random thresholds (Corollaries~\ref{cor:heavy_rand} and~\ref{cor:light_rand}) from their convergence with deterministic thresholds (Corollaries~\ref{cor:heavy_det} and~\ref{cor:light_det}).
