\section{Verifying the conditions of Lemma~\ref{lem:derand} in the Settings of Corollary~\ref{cor:heavy_det} and~\ref{cor:light_det}}

In the next lemma we check the assumptions of Lemma~\ref{lem:derand} in the settings of Corollary~\ref{cor:heavy_det} and Corollary~\ref{cor:light_det}. Applying Lemma~\ref{lem:derand} then directly results in Corollary~\ref{cor:heavy_rand} and~\ref{cor:light_rand}.
\begin{lemma}
  \label{lem:derand:poly}
  Let $g=\log$. Then the assumptions of Lemma~\ref{lem:derand} hold in the settings of (i) Corollary~\ref{cor:heavy_det} and (ii) Corollary~\ref{cor:light_det}, respectively, with the following parameters
  \begin{enumerate}[label=(\roman*)]
    \item In Corollary~\ref{cor:heavy_det}, $r_n=n^{1-1/(\nu\land 2)-d} u_n$,
\begin{align*}
    \xi(u_n)
    \ = \
    \frac{u_nf_{X_0}(u_n)}{\PP[X_0>u_n]}
    \ \to \
    \nu
    \,,
\end{align*}
and the joint limit is
    \begin{align*}
    (\Phi, \Psi) 
    \ = \
    \left( \frac{\nu}{1+\nu}
    Z_{2\land\nu}, \ Z_{2\land\nu} \right)
    \,,
  \end{align*}
  with constant $c=1$ and $(\tau_n)$ any sequence satisfying \eqref{cond:tau:1} and \eqref{cond:tau:2}.
    \item In Corollary~\ref{cor:heavy_det}, $r_n=n^{1/2-d} u_n$,
\begin{align*}
    \xi(u_n)
    \ = \
    \frac{u_nf_{X_0}(u_n)}{\PP[X_0>u_n]}
    \ \sim \
   u_n^\beta
   \,,
\end{align*}
and the joint limit is $(\Phi, \Psi) = (Z_2, Z_2)$,
  with constant $c=1$ and $(\tau_n)$ any sequence 
  satisfying \eqref{cond:tau:1} and \eqref{cond:tau:2}.
  \end{enumerate}
 \end{lemma}


 \begin{proof}[Proof of Lemma~\ref{lem:derand:poly}]
We begin by showing all the assumptions of Lemma~\ref{lem:derand} except for the joint convergence. We do this separately for both settings.

In setting (i), it follows from Karamata's theorem, that
  \[
    \xi(u_n)
    \ = \
    \frac{u_nf_{X_0}(u_n)}{\PP[X_0>u_n]}
    \ \to \
    \nu
    \,.
  \]
  This implies $r_n/\xi(u_n)\to\infty$.
  Since $g'(u_n)=1/u_n$, and using equation~\eqref{i_know}, we also find that
  \begin{align*}
    u_n
    g'(u_n)
    \frac{\PP[X_0>u_n]}{\EE[(g(X_0)-g(u_n))\ind\{X_0>u_n\}]} = \frac{\PP[X_0>u_n]}{\EE
\left[
    \log
    \left(
    X_0/u_n
    \right)_+
\right]}
    \ \sim \
    \nu
    \ \sim \
    \xi(u_n)
    \,,
  \end{align*}
  which shows that Assumption~\eqref{lem:derand:c1} holds with constant $c=1$. Applying the mean value theorem and the regular variation property of $f_{X_0}$, along with the local uniformity property of regularly varying functions,
  we conclude that for each $t\in\mathbb{R}$,
  there exists a sequence $(\theta_n)=(\theta_n(t)) \subset (0,1)$ such that
  \begin{align*}
    &
 r_n
    \left(
    \frac{\PP[X_0>u_n]}{\PP[X_0>(1+t/r_n)\cdot u_n]}
    \ - \ 1
    \right)
    \\&
    \ = \
    \frac{r_n}{\PP[X_0>(1+t/r_n)u_n]}
    \frac{u_nt}{r_n}
    f_{X_0}((1+\theta_nt/r_n)u_n)
    \\&
    \ = \
    t
    \cdot
    \frac{u_n}{u_n(1+t/r_n)}
    \frac{
    u_n(1+t/r_n)\cdot  f_{X_0}(u_n(1+t/r_n))
