    \end{split}
  \end{align}
  Indeed, from this, Theorem~\ref{thm:approx_optimal} will imply
  that in case (i),
 \begin{align*}
    &
    \norm{
    n^{-d-1/\alpha}
    \frac{1}{
    f_{X_0}(u_n)
    }
    \sum_{t=1}^{n}
    (G_n(X_t)
    \ - \
    \EE[G_n(X_0)])
    \ - \
    \left(
    \lambda_1
    \frac{\nu}{1+\nu}
    \ + \
    \lambda_2
    \ + \
    o(1)
    \right)
    n^{-d-1/\alpha}
    \sum_{t=1}^{n}
    X_t
    }_{L^{r_0}(\PP)}
    \\&
    \ \lesssim \
    \frac{
   n^{\kappa_0+\delta/2-d-1/\alpha}
       }{
    f_{X_0}(u_n)
    }
\ \to \
0
\,,
  \end{align*}
  as $n\to\infty$.
  This conclusion follows from $f_{X_0}\in\mathrm{RV}_{-\nu-1}$ and
  $u_n=\operatorname{o}(n^{(d+1/\alpha-\kappa_0-\delta)/(\nu+1)})$.
  In case (ii), we similarly obtain
\begin{align*}
    &
    \norm{
    n^{-d-1/2}
    \frac{1}{
    f_{X_0}(u_n)
    }
    \sum_{t=1}^{n}
    (G_n(X_t)
    \ - \
    \EE[G_n(X_0)])
    \ - \
    \left(
    \lambda_1
    \ + \
    \lambda_2
    \ + \
    o(1)
    \right)
    n^{-d-1/2}
    \sum_{t=1}^{n}
    X_t
    }_{L^{r_0}(\PP)}
    \\&
    \ \lesssim \
    \frac{
  n^{\kappa_0+\delta/2-d-1/2}
       }{
    f_{X_0}(u_n)
    }
    \to
    0
    \,,
    \end{align*}
  as $n\to\infty$, due to \eqref{eq:omega_vanish}.
  Applying Theorem~\ref{thm:clt_partsum} and Slutsky's lemma then yields the desired convergence of 
  \eqref{eq:28891} and the announced result. 

We now provide details on both steps.
\subsection*{Details Step 1: Analysis of $R_1$}
We apply Theorem~\ref{thm:approx_optimal} using the function
\begin{align*}
  G_n^{R_1}
  (x)
  \ = \
  \ind\{x>u_n\}
  \ - \
  \ind\{x>u_n(1+\epsilon_n)\}
  \,,
\end{align*}
which satisfies the bound
\begin{align*}
|G_n^{R_1}(x)|\le \ind\{x>u_n(1-(-\epsilon_n)_+)\}\,.
\end{align*}
This ensures that Assumption~\ref{asu:G_n} is met, with the threshold $u_n$ replaced by $u_n(1-(-\epsilon_n)_+)$. 
We then decompose $R_1$ as
\begin{align*}
  R_1
  &
  \ = \
  R_{1,1}
  \ + \
  R_{1,2}
  \,,
\end{align*}
where
\begin{align*}
  R_{1,1}
  &
  \ := \
  \frac{
  1}{\PP[X_0>u_n]}
  \frac{r_n/\xi(u_n)}{n} \cdot
  \sum_{t=1}^n
  \left(
  G_n^{R_1}(X_t)
  \ - \
  \EE[ G_n^{R_1}(X_0) ]
  \ - \
  (G_{n,\infty}^{R_1})'(0)
  X_t
  \right)
  \,,
  \\
R_{1,2}
  &
  \ := \
  \frac{
  1}{\PP[X_0>u_n]}
  \frac{r_n/\xi(u_n)}{n} \cdot
  (G_{n,\infty}^{R_1})'(0)
  \sum_{t=1}^n
  X_t
  \,.
\end{align*}
First we analyze $R_{1,1}$. Note that by construction
\begin{align*}
  \frac{
  1}{\PP[X_0>u_n]}
  \frac{r_n/\xi(u_n)}{n}
  =
  \frac{n^{-d-1/\alpha}}{f_{X_0}(u_n)}
  \,.
\end{align*}
Applying Theorem~\ref{thm:approx_optimal}, we find that 
\begin{align*}
  &
  \norm{
  R_{1,1}
  }_{L^{r_0}(\PP)}
  \\&
  \ = \
  \frac{
  1}{f_{X_0}(u_n)}
  \norm{
  n^{-d-1/\alpha}
  \sum_{t=1}^n
  \left(
  G_n^{R_1}(X_t)
  \ - \
  \EE[ G_n^{R_1}(X_0) ]
  \ - \
  (G_{n,\infty}^{R_1})'(0)
  X_t
  \right)
  }_{L^{r_0}(\PP)}
  \\&
  \ \le \
  \frac{n^{\kappa_0+\delta/2-d-1/\alpha}}{f_{X_0}(u_n)}
  \ \to \
  0
  \,,
\end{align*}
due to the assumed growth rate on $u_n$, as was shown at the beginning of the proof.
Next we turn to $R_{1,2}$.
Since $r_n/(nu_n)=n^{-d-1/\alpha}$, it follows from
Theorem~\ref{thm:clt_partsum} that
\begin{align*}
  \frac{r_n}{nu_n}
  \sum_{t=1}^n
  X_t
  \stackrel{\mathrm{d}}{\longrightarrow}
  Z_{\alpha}\,.
\end{align*}
The remaining factor is
\begin{align*}
\frac{
  u_n
  (G_{n,\infty}^{R_1})'(0)
  }{\PP[X_0>u_n]\xi(u_n)}
  \,,
\end{align*}
which we will show
tends to zero as $n\to\infty$.
The stated convergence of $R_{1,2}$ then follows by Slutsky's lemma.
We now use Lemma~\ref{lem:swap}(ii) in order to evaluate
\begin{align*}
  &
\frac{
  u_n
  (G_{n,\infty}^{R_1})'(0)
  }{\PP[X_0>u_n]\xi(u_n)}
  \ = \
  \frac{f_{X_0}(u_n(1+\epsilon_n))-f_{X_0}(u_n)}{f_{X_0}(u_n)}
  \ = \
  \frac{f_{X_0}(u_n(1+\epsilon_n))}{f_{X_0}(u_n)}
  \ - \
  1
  \,.
\end{align*}
In case (i), we assume $f_{X_0}\in\mathrm{RV}_{-\nu-1}$, so by local uniformity of regular variation
\begin{align*}
  \frac{f_{X_0}(u_n(1+\epsilon_n))}{f_{X_0}(u_n)}
  \ = \
  (1+\epsilon_n)^{-\nu-1}
  \ + \
  o(1)
  \ \to \
  1
  \,,
\end{align*}
as $n\to\infty$, since $\epsilon_n\to 0$.
In case (ii), we have
\begin{align}
\label{helper123}
  \frac{f_{X_0}(u_n(1+\epsilon_n))}{f_{X_0}(u_n)}
  \ = \
  \frac{\omega(u_n(1+\epsilon_n))}{\omega(u_n)}
  \exp(u_n^\beta(1 - (1+\epsilon_n)^\beta)/\beta)
  \ \to \
  1
  \,,
\end{align}
since $\epsilon_n$ decays polynomially in $n$ while $u_n$ grows only logarithmically, and $\omega$ is either constant or regularly varying at infinity.
This shows $R_{1,2}\stackrel{\PP}{\longrightarrow} 0$, and thus $R_{1}\stackrel{\PP}{\longrightarrow}0$.
\subsection*{Details Step 1: Analysis of $R_2$}
The analysis of $R_2$ is
more straightforward, as the conditions of Theorem~\ref{thm:approx_optimal} are easily verified for the function
\begin{align*}
  G_n^{R_2}(x)
  \ = \
  \ind\{x>u_n(1+\varepsilon_n)\}
  \,.
\end{align*}
Recall first of all that we have just shown the convergence $f_{X_0}(u_n(1+\epsilon_n))/f_{X_0}(u_n)\to 1$. Moreover, in case (i), since $f_{X_0}\in \mathrm{RV}_{-\nu-1}$,
  it follows that $x\mapsto \PP[X_0>x]\in \mathrm{RV}_{-\nu}$.
  Therefore,
  \begin{align*}
  \frac{
  \PP[X_0>u_n(1+\epsilon_n)]
  \
-
  \
  \PP[X_0>u_n]
  }{\PP[X_0>u_n]}
    \ = \
    (1+\epsilon_n)^{-\nu}
    \ - \ 1
    \ + \ o(1)
  \ \to\ 0
  \,.
  \end{align*}
  In case (ii), we apply the mean value theorem: there exists $(\theta_n)\subset(0,1)$ such that
 \begin{align*}
   &
  \frac{
  \PP[X_0>u_n(1+\epsilon_n)]
  \
-
  \
  \PP[X_0>u_n]
  }{\PP[X_0>u_n]}
    \ = \
    -u_n\epsilon_n
    \frac{f_{X_0}(u_n)}{\PP[X_0>u_n]}
    \frac{f_{X_0}(u_n(1+\theta_n\epsilon_n))}{f_{X_0}(u_n)}
    \ \to \ 0\,,
  \end{align*}
  as $n\to\infty$, since $u_nf_{X_0}/\PP[X_0>u_n]\sim u_n^{\beta}$ with $\epsilon_n u_n^\beta\to 0$, and the remaining term converges to 1 due to \eqref{helper123}. This entails $\PP[X_0>u_n(1+\epsilon_n)]/\PP[X_0>u_n]\to 1$. Then, applying Theorem~\ref{thm:approx_optimal} and Theorem~\ref{thm:clt_partsum}, we obtain that
\begin{align*}
  &
  n^{1-(d+1/\alpha)} \cdot \frac{\PP[X_0>u_n(1+\varepsilon_n)]}{f_{X_0}(u_n(1+\varepsilon_n))} \cdot \frac{1}{n}
  \sum_{t=1}^n
  \left(
  \frac{\ind\{X_t>u_n(1+\epsilon_n)\}}{\PP[X_0>u_n(1+\epsilon_n)]}
  \ - \
  1
  \right)
\end{align*}
  converges in distribution to a non-degenerate random variable, and so does
  \begin{align*}
  &
  n^{1-(d+1/\alpha)} \cdot \frac{\PP[X_0>u_n]}{f_{X_0}(u_n)} \cdot \frac{1}{n}
  \sum_{t=1}^n
  \left(
  \frac{\ind\{X_t>u_n(1+\epsilon_n)\}}{\PP[X_0>u_n(1+\epsilon_n)]}
  \ - \
  1
  \right) \\
  &= 
\frac{r_n/\xi(u_n)}{n}
  \sum_{t=1}^n
  \left(
  \frac{\ind\{X_t>u_n(1+\epsilon_n)\}}{\PP[X_0>u_n(1+\epsilon_n)]}
  \ - \
  1
  \right) \\
  &= \frac
  {\PP[X_0>u_n]}
  {
  \PP[X_0>u_n(1+\epsilon_n)]
  \
-
  \
  \PP[X_0>u_n]
  }
  R_2.
\end{align*}
We conclude that in both settings it holds $R_2\stackrel{\PP}{\longrightarrow}0$.

We will now continue the analysis separated into the settings, where we have to check the validity of \eqref{eq:still_to_show}, and the remaining conditions of Lemma~\ref{lem:derand}.
\subsection*{Details Step 2}
We begin by verifying equation~\eqref{eq:still_to_show} in setting (i).
To simplify the notation, we write
  \[
  (\log(x)-\log(u_n))\ind\{x>u_n\}
  \
  =
  \
    \max\{
  \log(x/u_n),0
    \}
    \ =: \
  \log(x/u_n)_+.
  \]
  It then follows that
  \begin{align*}
    G_{\infty,n}'(0)
    &
    \ = \
    -\int_\RR
    G_n(x)
    f_{X_0}'(x)
    \,\mathrm{d}x
    \\&
    \ = \
    -\lambda_1
\frac{
    \int_{u_n}^{\infty}
    \log
    \left(
    x/u_n
    \right)
    f_{X_0}'(x)
    \,\mathrm{d}x
    }{
\EE
\left[
    \log
    \left(
    X_0/u_n
    \right)_+
\right]
    }
    \PP[X_{0}>u_n]
    \ + \
    \lambda_2
    \cdot
    f_{X_0}(u_n)
    \,.
  \end{align*}
 Using integration by parts and the regular variation of $f_{X_0}\in\mathrm{RV}_{-\nu-1}$, 
 we obtain
  \begin{align*}
    -\int_{u_n}^{\infty}
    \log
    \left(
    x/u_n
    \right)
    f_{X_0}'(x)
    \,\mathrm{d}x
    &
    \ = \
    \left[
    -f_{X_0}(x)
    \log(x/u_n)
    \right]^{x\to\infty}_{x=u_n}
    \ + \
\int_{u_n}^{\infty}
\frac{1}{x}
    f_{X_0}(x)
    \,\mathrm{d}x
    \,.
    \intertext{Changing variables, 
    and using the uniform convergence of $f_{X_0}(u_nx)/f_{X_0}(u_n)$ to 1 in neighborhoods of infinity, this becomes:}
   -\int_{u_n}^{\infty}
    \log
    \left(
    x/u_n
    \right)
    f_{X_0}'(x)
    \,\mathrm{d}x        &
           \ = \
\int_{1}^{\infty}
\frac{1}{x}
           f_{X_0}(u_nx)
           \,\mathrm{d}x
           \\&
           \ = \
           f_{X_0}(u_n)
\int_{1}^{\infty}
\frac{1}{x}
\frac{
           f_{X_0}(u_nx)
           }{f_{X_0}(u_n)}
           \,\mathrm{d}x
           \\&
           \ \sim \
           f_{X_0}(u_n)
\int_{1}^{\infty}
           \frac{1}{x^{2+\nu}}
           \,\mathrm{d}x
           \\&
           \ = \
           f_{X_0}(u_n)
           \frac{1}{1+\nu}
           \,.
         \end{align*}
  Additionally, by Karamata's theorem \cite[Theorem~B.1.5]{dehaanExtremeValueTheory2006}, we have
  \begin{align}
  \nonumber
\EE
\left[
    \log
    \left(
    X_0/u_n
    \right)_+
\right]
    &
    \ = \
    \int_{u_n}^{\infty}
    \log(x/u_n)
    f_{X_0}(x)
    \,\mathrm{d}x
    \\
    \nonumber
    &
    \ = \
    u_n
    f_{X_0}(u_n)
    \int_{1}^{\infty}
    \log(x)
    \frac{
    f_{X_0}(u_n x)
    }{
    f_{X_0}(u_n)
    }
    \,\mathrm{d}x
    \\
    \nonumber
    &
    \ \sim \
    \nu
    \PP[X_0>u_n]
    \int_{1}^{\infty}
    \log(x)
    \frac{1}{x^{1+\nu}}
        \,\mathrm{d}x
        \label{i_know}
        \\&
       \ = \
        \frac{
    \PP[X_0>u_n]
        }{\nu}
        \,.
  \end{align}
  It follows that
  \begin{align*}
    G_{\infty,n}'(0)
    \
    \ = \
    \
        f_{X_0}(u_n)
    \left(
    \lambda_1
    \frac{\nu}{1+\nu}
    \ + \
    \lambda_2
    \ + \
    o(1)
    \right)
    \,,
  \end{align*}
  which verifies equation~\eqref{eq:still_to_show} in setting (i).

To prove the same equation in case (ii),
first note that in the proof of Corollary~\ref{cor:light_det} we showed
\begin{align*}
\frac{\EE[G_n(X_0)]}{G_{\infty,n}'(0)} = \frac
{
\int_{u_n}^{\infty}
\log(x/u_n)f_{X_0}(x)\,\mathrm{d}x
}
{
-
\int_{u_n}^{\infty}
\log(x/u_n)f'_{X_0}(x)\,\mathrm{d}x
}
\
\sim
\
\frac{\PP[X_0>u_n]}{f_{X_0}(u_n)}
\
\sim
\
u_n^{1-\beta}
\,.
\end{align*}
From this it follows immediately that
  \begin{align*}
    G_{\infty,n}'(0)
    \
    =
    \
    u_n^{\beta-1} \EE[G_n(X_0)]
    \
    &=
    \
    u_n^{\beta-1} \PP[X_0>u_n] (\lambda_1 + \lambda_2 + o(1)) \\
    &
    \
    =
    \
    f_{X_0}(u_n)(\lambda_1 + \lambda_2 + o(1))
    \, ,
  \end{align*}
  that is, \eqref{eq:still_to_show}.
Having shown \eqref{eq:still_to_show} in both cases, we conclude the proof.
  \end{proof}
