\subsection{Notations}

\begin{itemize}
	\item We fix once and for all a prime number $p > 0$. All rings and schemes in this paper are defined over $\bF_p$.

	\item The symbol $k$ always refers to a perfect field.

	\item A variety is an integral scheme $X$ which is separated and of finite type over $k$.

	\item The symbol $F$ always denotes the absolute Frobenius of a $\bF_p$-scheme. An $\bF_p$-scheme $X$ is $F$-finite if its absolute Frobenius morphism $F \colon X \to X$ is finite. 


	\item Given a complex $C^{\bullet}$ with values in some abelian category and $i \in \bZ$, we denote by $\cH^i(C^{\bullet})$ its $i$-th cohomology object. When the context is clear, we may simply write $C$ instead of $C^{\bullet}$.

	\item Given a Noetherian ring $R$, we let $D_{\mathrm{fg}}(R)$ denote the derived category of $R$--modules with finitely generated cohomology modules.

	\item The symbol $A$ always denotes an abelian variety over an algebraically closed field, $\hat{A}$ denotes its dual, and $\cP$ denotes the normalized Poincaré bundle on $A \times \hat{A}$. Furthermore, given a closed point $\alpha \in \bighat{A}$, we write $\cP_\alpha \coloneqq \cP|_{A \times \alpha} \in \Pic^0(A)$.

	\item Given an $\bF_p$-scheme $X$ and $n \geq 1$, we write $W_nX$ for the scheme given by the ringed space $(X, W_n\cO_X)$. Given a morphism $f \colon X \to Y$, we still denote by $f$ the naturally induced morphism from $W_nX \to W_nY$.

	\item Given a separated morphism $f \colon X \to Y$ of finite type, we denote by $f^!$ the functor defined in \stacksproj{0A9Y}.

	\item Given a sheaf of abelian groups $\cF$ and an integer $m \geq 1$, the subsheaf $\cF[m] \inc \cF$ denotes the sheaf of $m$-torsion elements.
\end{itemize}

