\section{Preliminaries}

Here is a general lemma about Witt schemes that we will use throughout, without further mention.

\begin{lem}
	Let $f \colon X \to Y$ be a morphism of Noetherian, $F$--finite $\bF_p$--schemes.
	\begin{itemize}
		\item For all $n \geq 1$, the scheme $W_nX$ is also Noetherian, and the induced Frobenius $F \colon W_nX \to W_nX$ is finite.
		\item If $f$ is of finite type (resp. separated, proper), then so is the induced map $W_nX \to W_nY$.
	\end{itemize}
\end{lem}
\begin{proof}
	This is all contained in \cite[Appendix A.1]{Langer_Zink_De_Rham_Witt_cohomology_for_a_proper_and_smooth_morphism}.
\end{proof}

\subsection{Witt--Cartier modules and crystals}

Throughout, $X$ denotes a Noetherian $F$--finite $\bF_p$-scheme. 

\begin{defn}
	\begin{itemize}
		\item A \emph{$W_n$--Cartier module} is a pair ($\cM$, $\theta$) where $\cM$ is a coherent $W_n\cO_X$-module and $\theta \colon F_*\cM \to \cM$ is a morphism. We call $\theta$ the \emph{structural morphism} of $\cM$. 

		\item A morphism of $W_n$--Cartier modules $h \colon (\cM_1, \theta_1) \to (\cM_2, \theta_2)$ is a morphism of underlying $W_n\cO_X$-modules $h \colon \cM_1 \to \cM_2$ such $h \circ \theta_1 = \theta_2 \circ F_*h$. The category of $W_n$--Cartier modules is denoted $\Coh_{W_nX}^C$. When $n = 1$, we will call them Cartier modules, and denote their category by $\Coh_X^C$.
	\end{itemize}	
\end{defn}

\begin{rem}
	In other references (e.g. \cite{Baudin_Duality_between_Witt_Cartier_crystals_and_perverse_sheaves}), the objects we defined above are called coherent $W_n$--Cartier modules (the definition in \emph{loc. cit.} does not require (quasi)--coherence). Since all sheaves we will consider in this paper are coherent, this should not cause any trouble.
\end{rem}

Note that one can take the pushforward of a $W_n$--Cartier module: if $f \colon X \to Y$ is a proper morphism of Noetherian, $F$--finite $\bF_p$--schemes and $(\cM, \theta)$ is a $W_n$--Cartier module on $X$, then $(f_*\cM, f_*\theta)$ defines a $W_n$--Cartier module on $Y$ (the properness assumption is only here to ensure that $f_*\cM$ is coherent).

\begin{example}
	Arguably the most important example is the canonical $W_n$--dualizing sheaf $W_n\omega_X$, together with the Cartier operator, see \autoref{section_witt_dc}.
\end{example}

\begin{notation}\label{rem:def_Cartier_mod}
	\begin{enumerate}
		\item\label{itm:abuse_iterates_structure_map} Let $(\cM, \theta)$ be a $W_n$-Cartier module. We will abuse notations as follows: \[ \theta^e \coloneqq \theta \circ F_*\theta \circ \dots \circ F^{e-1}_*\theta \colon F^{e}_*\cM \to \cM. \]
		\item\label{itm:notation H^0_ss} Given a proper scheme $X$ over an algebraically closed field $k$ and $(\cM, \theta) \in \Coh_{W_nX}^{C}$, we set \[ H^i_{ss, \theta}(X, \cM) \coloneqq \bigcap_{e > 0} \im\left(H^i(X, F^{e}_*\cM) \xto{\theta^e} H^i(X, \cM)\right) \inc H^i(X, \cM). \] We also write $h^i_{ss, \theta}(X, \cM) \coloneqq \length H^i_{ss, \theta}(X, \cM)$ 
		and  \[ \chi_{ss, \theta}(\cM) \coloneqq \sum_i (-1)^ih^i_{ss, \theta}(X, \cM). \] Whenever the context is clear, we shall remove the $\theta$ from this notation.
	\end{enumerate}
\end{notation}

\begin{defn}\label{def:Cartier_crystal}
	A $W_n$--Cartier module is said to be \emph{nilpotent} if its structural morphism is nilpotent. These objects form a Serre subcategory of $\Coh_{W_nX}^{C}$ (meaning that being nilpotent is stable under subobjects, quotients and extensions). The corresponding quotient category (see \stacksproj{02MS}) is denoted by $\Crys_{W_nX}^{C}$, and the objects of this quotient category are called \emph{$W_n$--Cartier crystals}. 
\end{defn}

Intuitively, working in the category of crystals allows us to forget about nilpotent phenomena. For example, a $W_n$--Cartier module is the zero object as a $W_n$-Cartier crystal if and only if it is nilpotent. More generally, a morphism $f \colon \cM \to \cN$ of $W_n$-Cartier modules is an isomorphism at the level of crystals if and only if both $\ker(f)$ and $\coker(f)$ are nilpotent. Such a morphism is called a \emph{nil-isomorphism}.

\begin{notation}\label{notation_crystals}
	\begin{itemize}
		\item Morphisms in $\Crys_{W_nX}^C$ will be denoted by the symbol $\dashrightarrow$. Those which come from a morphism in $\Coh_{W_nX}^C$ will be denoted by a full arrow $\to$.
		\item If $\cM_1$ and $\cM_2$ are two $W_n$--Cartier modules which are isomorphic as crystals, then we shall write $\cM_1 \sim_C \cM_2$.
	\end{itemize}
\end{notation}

\begin{defn}
	Let $(\cM, \theta)$ be a $W_n$-Cartier module. Then the \emph{perfection} of $(\cM, \theta)$ is $\cM^{\perf} \coloneqq \lim_e F^e_*\cM$.
\end{defn}

\begin{lem}\label{Gabber_finiteness}
	Let $\cM$ be a $W_n$--Cartier module on $X$.
	\begin{enumerate}
		\item\label{itm:Gabber_fin} The inverse system $\{F^{e}_*\cM\}_{e \geq 1}$ satisfies the Mittag--Leffler condition. In particular, $\cM^{\perf} = \Rlim F^{e}_*\cM$ and perfection is exact on $W_n$--Cartier modules.
		\item We have that $\cM \sim_C 0$ if and only if $\cM^{\perf} = 0$.
		\item\label{itm:nil_iso_iff_perf_iso} For any morphism $f \colon \cM \to \cN$ of $W_n$--Cartier modules, $f$ is a nil--isomorphism if and only if $f^{\perf}$ is an isomorphism.
	\end{enumerate}
\end{lem}
\begin{proof}
	This is \cite[Lemma 4.4.2]{Baudin_Duality_between_Witt_Cartier_crystals_and_perverse_sheaves} (see also \cite[Lemma 13.1]{Gabber_notes_on_some_t_structures} for the first statement).
\end{proof}

\begin{rem}\label{rem_ss_cohomology}
	Given a Cartier module $\cM$ on a proper scheme $X$ over an algebraically closed field, it follows from \autoref{Gabber_finiteness}.\autoref{itm:Gabber_fin} that $H^i_{ss}(X, \cM) = H^i(X, \cM^{\perf})$. In particular, the groups $H^i(X, \cM^{\perf})$ are finite--dimensional.
\end{rem}

\subsection{Witt dualizing complexes}\label{section_witt_dc}

Throughout, $X$ denotes a fixed variety with structural morphism $g \colon X \to \Spec k$. Here is our main object of study:

\begin{defn}
	The \emph{canonical $W_n$-dualizing complex} is by definition $W_n\omega_X^{\bullet} \coloneqq g^!\cO_{W_n(k)}$. By \stacksproj{0AA3}, this is a dualizing complex on $W_nX$.
\end{defn}
\begin{rem}
	When $X$ is smooth, this complex agrees with the last piece of the de Rham--Witt complex from \cite{Illusie_Complexe_de_de_Rham_Witt_et_cohomologie_cristalline} (up to a shift), see \cite[Section I]{Ekedahl_Duality_Hodge_Witt}.
\end{rem}

In \cite[Section 2.2]{Baudin_Witt_GR_vanishing_and_applications} (see also \cite[Appendix]{Quasi_F_splittings_III}), we explain how to construct the Cartier operators $C \colon F_*W_n\omega_X^{\bullet} \to W_n\omega_X^{\bullet}$ and restriction maps $R \colon W_{n + 1}\omega_X^{\bullet} \to W_n\omega_X^{\bullet}$, satisfying $R \circ C = C \circ F_*R$. In particular, each sheaf $\cH^i(W_n\omega_X^{\bullet})$ is a $W_n$--Cartier module, and each map $\cH^i(R) \colon \cH^i(W_{n + 1}\omega_X^{\bullet}) \to \cH^i(W_n\omega_X^{\bullet})$ is a morphism of $W_{n + 1}$--Cartier modules. 

\begin{notation}
	We set \[ (W_n\omega_X^{\bullet})^{\perf} \coloneqq \Rlim_e F^e_*W_n\omega_X^{\bullet}, \] where the transition maps are given by the Cartier operators $C$. Note that by exactness of perfection (see \autoref{Gabber_finiteness}.\autoref{itm:Gabber_fin}), this does not cause any clash of notation with the perfection functor on $W_n$--Cartier modules.
\end{notation}

Since the restriction maps commute with the Cartier operators, there are induced morphisms $R \colon (W_{n + 1}\omega_X^{\bullet})^{\perf} \to (W_n\omega_X^{\bullet})^{\perf}$.

\begin{defn}
	We define the \emph{canonical Witt--dualizing complex} to be \[ W\omega_X^{\bullet} \coloneqq \Rlim \: W_n\omega_X^{\bullet}, \] where the transition maps are the restrictions $R \colon W_{n + 1}\omega_X^{\bullet} \to W_n\omega_X^{\bullet}$.
\end{defn}

An important (any maybe surprising) feature of canonical Witt dualizing complexes is the following:
\begin{lem}\label{Witt_omega_coperfect}
	The induced morphism $C \colon F_*W\omega_X^{\bullet} \to W\omega_X^{\bullet}$ is an isomorphism. In particular, there is a natural isomorphism \[ W\omega_X^{\bullet} \to \Rlim_n \: (W_n\omega_X^{\bullet})^{\perf}. \]
\end{lem} 
\begin{proof}
	This is \cite[Lemma 2.2.5]{Baudin_Witt_GR_vanishing_and_applications}.
\end{proof}

\begin{lem}\label{cone_of_p_Witt_omega}
	The following is an exact triangle
	\[ \begin{tikzcd}
		W\omega_X^{\bullet} \arrow[r, "p^m"] & W\omega_X^{\bullet} \arrow[r] & (W_m\omega_X^{\bullet})^{\perf} \arrow[r, "+1"] & {}
	\end{tikzcd} \] where the second map is the composition $W\omega_X^{\bullet} \xto{\cong} \Rlim_n \: (W_n\omega_X^{\bullet})^{\perf} \to (W_m\omega_X^{\bullet})^{\perf}$.
\end{lem}

\begin{proof}
	This is \cite[Lemma 2.2.7]{Baudin_Witt_GR_vanishing_and_applications}.
\end{proof}

\begin{defn}
	The \emph{canonical $W_n$--dualizing sheaf} is $W_n\omega_X \coloneqq \cH^{-\dim(X)}(W_n\omega_X^{\bullet})$. We also set the \emph{canonical Witt--dualizing sheaf} to be $W\omega_X \coloneqq \lim_n W_n\omega_X$.
\end{defn}

\begin{rem}\label{coincides_with_what_we_know}
	If $X$ is smooth, then $W\omega_X$ agrees with the last piece of the (non--truncated) de Rham--Witt complex of \cite{Illusie_Complexe_de_de_Rham_Witt_et_cohomologie_cristalline} up to a shift by \cite[Remark 2.2.12]{Baudin_Witt_GR_vanishing_and_applications}.
\end{rem}

\section{A weak Grauert-Riemenschneider sheaf}\label{section_weak_GR_sheaf}

