\begin{sthm}[{\cite{Baudin_Witt_GR_vanishing_and_applications}}]\label{Witt_GR_vanishing}
	In our setup above, there exists $e > 0$ such that for all $i > 0$, \[ p^e \cdot R^i\pi_*W\omega_X = 0. \]
