\begin{snotation}
	Let $\cF^{\bullet}$ be a complex of abelian sheaves. In order to lighten notations, we will write \[ \cF^{\bullet}/p^n \coloneqq \cF^{\bullet} \otimes_{\bZ}^L \bZ/p^n\bZ. \]
\end{snotation}

\begin{srem}\label{rem_derived_p_completion_first}
	Note that $\cF^{\bullet}/p^n$ is the cone of $\cF^{\bullet} \xto{p^n} \cF^{\bullet}$. Since all our functors are additive (hence respect multiplication by $p^n$), they will all preserve derived tensor product by $\bZ/p^n\bZ$.
\end{srem}

\begin{sprop}\label{cohomology_fg_mod_p}
	There exists a canonically defined sub--Cartier crystal $\cM$ of $\pi_*\omega_X$ such that \[ (\pi_*W\omega_X)/p \cong \cM^{\perf}. \]
\end{sprop}

\begin{proof}
	For any $n \geq 1$, let $\cM_n \subseteq \pi_*\omega_X$ be the sub--$W_n$--Cartier module defined by the image of \[ \pi_*W_n\omega_X \to \pi_*\omega_X. \] 
	Since it is a $p$--torsion $W_n$--Cartier module, we know by \cite[Lemma 4.3.8]{Baudin_Duality_between_Witt_Cartier_crystals_and_perverse_sheaves} that there exists a Cartier module $\cM_n'$, unique in the category of Cartier crystals that is equipped with a nil--isomorphism $\cM_n \to \cM_n'$ of $W_n$--Cartier modules. Again by \emph{loc.cit.}, there exists a injection of Cartier crystals $\cM_n' \dra \pi_*\omega_X$, and since we have inclusions \[ \dots \inc \cM_{n + 1} \inc \cM_n \inc \dots \inc \pi_*\omega_X, \] we obtain a descending chain of Cartier crystals \[ \dots \dra \cM_{n + 1}' \dra \cM_n' \dra \dots \dra \pi_*\omega_X. \]	

	Since Cartier crystals are Artinian objects (see e.g. \cite[Main theorem]{Blickle_Bockle_Cartier_modules_finiteness_results}), this descending chain must eventually stabilize. Set $\cM \coloneqq \cM_n'$ for $n \gg 0$ (it is only defined as a Cartier crystal!). By construction, we obtain that for $n \gg 0$, the inclusions $\cM_{n + 1} \inc \cM_n$ are nil-isomorphisms, so they induce isomorphisms \[ \cM_{n + 1}^{\perf} \cong \cM_n^{\perf} \] by \autoref{Gabber_finiteness}.\autoref{itm:nil_iso_iff_perf_iso}, and they agree with $\cM^{\perf}$. To finish the proof, we need to show that \[ (\pi_*W\omega_X)/p \cong \cM^{\perf}.\] We have that \[ (\pi_*W\omega_X)/p \expl{\cong}{\autoref{reinterpretation_of_inverse_system}} \left(\Rlim \pi_*W_n\omega_X^{\perf}\right)/p \expl{\cong}{\autoref{rem_derived_p_completion_first}} \Rlim\left((\pi_*W_n\omega_X)^{\perf}/p\right) \expl{\cong}{\autoref{rem_derived_p_completion_first} and \autoref{Gabber_finiteness}} \Rlim \left( (\pi_*W_n\omega_X)/p\right)^{\perf}. \] 
	First of all, we claim that \[ \Rlim \left(\left( (\pi_*W_n\omega_X)/p\right)^{\perf}\right) \cong \Rlim \cH^0\left((\pi_*W_n\omega_X)/p\right)^{\perf}. \] To see this, all we have to do is showing that $\Rlim \left(\cH^{-1}(\pi_*W_n\omega_X/p)^{\perf}\right) = 0$. The fact that $R^1\lim$ vanishes follows from \cite[Remark 2.2.11]{Baudin_Witt_GR_vanishing_and_applications}. Finally, the $\lim$ also vanishes, since \[ \lim \left(\cH^{-1}(\pi_*W_n\omega_X/p)^{\perf}\right) = \cH^{-1}\left(\Rlim \left( (\pi_*W_n\omega_X)/p\right)^{\perf}\right) \expl{\cong}{see above} \cH^{-1}\left((\pi_*W\omega_X)/p\right) = 0, \] where the last vanishing holds since $\pi_*W\omega_X$ is $p$--torsion free (see \cite[Lemma 2.2.9]{Baudin_Witt_GR_vanishing_and_applications}). Hence, our claim is proven.


%	In fact, it automatically follows from the commutativity of the diagram \[ \begin{tikzcd}
%		\cH^{-1}\left((\pi_*W_{n + 1}\omega_X)/p\right) \arrow[d, "\cong"] \arrow[rr] &  & \cH^{-1}\left((\pi_*W_n\omega_X)/p\right) \arrow[d, "\cong"] &  &                        \\
%		{(\pi_*W_{n + 1}\omega_X)[p]} \arrow[rr] \arrow[d, "\inc"]                    &  & {(\pi_*W_n\omega_X)[p]} \arrow[d, "\inc"]                    &  &                        \\
%		\pi_*W_{n + 1}\omega_X \arrow[rr] \arrow[rrrr, "\cdot p", bend right]         &  & \pi_*W_n\omega_X \arrow[rr, "\pi_*\bD(R)", hook]                  &  & \pi_*W_{n + 1}\omega_X
%	\end{tikzcd} \] that the maps in the inverse system $\{\cH^{-1}\left((\pi_*W_n\omega_X)/p\right)\}_{n \geq 1}$ are all zero, so the claim follows. \JB{What is $\bD(R)$ and why does this commute bruhbruh. Actually, I can completely avoid this explicit description, but...}

	Note that by construction, we have a commutative diagram \[ \begin{tikzcd}
		\Rlim \cH^0((\pi_*W_n\omega_X^{\perf})/p) \arrow[rr]                 &  & \Rlim \cM_n^{\perf} = \cM^{\perf} \arrow[d, "\inc"] \\
		(\pi_*W\omega_X)/p \arrow[u, "\cong"] \arrow[rr, hook] &  & \pi_*\omega_X^{\perf},                            
	\end{tikzcd} \] showing that the top arrow is injective. Since it is an inverse limit of surjective maps and there is no $R^1\lim$ in play by \cite[Remark 2.11]{Baudin_Witt_GR_vanishing_and_applications}, we deduce that the top arrow is in fact an isomorphism. All in all, we have shown that $(\pi_*W\omega_X)/p \cong \cM^{\perf}$.
\end{proof}

\begin{sdefn}
	The Cartier crystal $\cM$ in \autoref{cohomology_fg_mod_p} will be called the \emph{weak Grauert--Riemenschneider sheaf} (in short, weak GR sheaf) with respect to $\pi$. It will be denoted $\omega_{\pi, \GR}$.
\end{sdefn}

\begin{srem}\label{rem_we_may_assume_sub_Cartier_mod}
	By its very construction, $\omega_{\pi, \GR}$ is only defined as a sub--Cartier \emph{crystal} of $\pi_*\omega_X$, not as a sub--Cartier module. In practice, this might be a bit cumbersome, so let us explain how to see it as a sub--Cartier \emph{module} of $\pi_*\omega_X$. 

	Since we have an injective morphism of Cartier crystals $\omega_{\pi, \GR} \dra \pi_*\omega_X$, we know by \cite[Lemma 3.4.14]{Baudin_Duality_between_perverse_sheaves_and_Cartier_crystals} that we can fit it in a commutative diagram \[ \begin{tikzcd}
		F^e_*\omega_{\pi, \GR} \arrow[d] \arrow[rd, "g"] &               \\
		\omega_{\pi, \GR} \arrow[r, dashed]         & \pi_*\omega_X,
	\end{tikzcd} \] where the left vertical map is the structural morphism of $\omega_{\pi, \GR}$ (hence an isomorphism of crystals), and $g$ is a morphism of Cartier \emph{modules}. Since $g$ is also injective as a morphism of crystals, $\ker(g)$ is nilpotent. Hence, if we set $\ttilde{\omega_{a, \GR}} \coloneqq \im(g) \inc \pi_*\omega_X$, then $\omega_{\pi, \GR} \sim_C \ttilde{\omega_{\pi, \GR}} \inc \pi_*\omega_X$. \\
\end{srem}

Our goal is now to show that $\chi_{ss}(X, \omega_X) = \chi_{ss}(Y, \omega_{\pi, \GR})$ when $X$ and $Y$ are proper. An important intermediate step is to show that each $W(k)$--module $H^i(Y, \pi_*W\omega_X)$ is finitely generated, and the key notion to prove this is derived $p$--completeness. The reason is that a derived $p$--complete complex of $W(k)$--modules which is finitely generated modulo $p$ is in fact finitely generated (\stacksproj{0CQF}).

\begin{sdefn}[{\stacksproj{091Z}}]
	We say that a complex of abelian sheaves $\cF^{\bullet}$ is \emph{derived $p$-complete} if the natural map \[ \cF^{\bullet} \to \Rlim_n \: \cF^{\bullet}/p^n \] is an isomorphism.
\end{sdefn}

\begin{srem}\label{rem_derived_p_completion_second}
	Since derived pushforwards preserve $\Rlim$ and $- \otimes^L_{\bZ} \bZ/p^n\bZ$ (see \autoref{rem_derived_p_completion_first}), they also preserve derived $p$--complete objects.
\end{srem}

\begin{slem}\label{Witt_omega_derived_p_complete}
	The sheaf $W\omega_X$ is derived $p$--complete.
\end{slem}
\begin{proof}
	For any variety $X$, it follows from \autoref{cone_of_p_Witt_omega} and \autoref{Witt_omega_coperfect} that $W\omega_X^{\bullet}$ is derived $p$--complete. Note that $W\omega_X^{\bullet}$ is simply the sheaf $W\omega_X$ shifted in some degree in our case (this holds for each $W_n\omega_X^{\bullet}$ and $W_n\omega_X$ by the proof of \cite[Lemma 2.2.15]{Baudin_Witt_GR_vanishing_and_applications}, so apply Lemma 2.2.10 in \emph{loc.cit.}). The proof is then complete.
\end{proof}

\begin{slem}\label{pushforward_p_complete}
	The sheaf $\pi_*W\omega_X$ is derived $p$-complete. In particular, $\RGamma(Y, \pi_*W\omega_X)$ is also derived $p$-complete.
\end{slem}

\begin{proof}
	By \autoref{Witt_omega_derived_p_complete}, we know that $W\omega_X$ is derived $p$--complete. In particular, $R\pi_*W\omega_X$ is also derived $p$-complete by \autoref{rem_derived_p_completion_second}, so the canonical map \[ \begin{tikzcd}
		\pi_*W\omega_X \arrow[rr, "\theta"] &  & \cH^0\left(\Rlim R\pi_*W\omega_X/p^n\right)
	\end{tikzcd} \] is an isomorphism. For all $n \geq 1$, there is an exact triangle \[  \begin{tikzcd}
		(\pi_*W\omega_X)/p^n \arrow[rr] &  & (R\pi_*W\omega_X)/p^n \arrow[rr] 	&  & (\tau_{\geq 1}R\pi_*W\omega_X)/p^n \arrow[rr, "+1"] &  & {}
	\end{tikzcd} \] so applying $\Rlim$ gives an exact triangle \\
	\begin{equation}\label{triangle_p_compl}
		\Rlim \left(\left(\pi_*W\omega_X\right)/p^n\right) \xto{\psi} \Rlim \left(\left(R\pi_*W\omega_X\right)/p^n\right) \to \Rlim \left(\left(\tau_{\geq 1}R\pi_*W\omega_X\right)/p^n\right) \xto{+1} 
	\end{equation}
	Since $\pi_*W\omega_X$ is $p$--torsion free (\cite[Lemma 2.2.9]{Baudin_Witt_GR_vanishing_and_applications}), the complex $(\pi_*W\omega_X)/p^n$ is actually a sheaf in degree zero (and it agrees with the usual non--derived quotient). In particular, each map of sheaves $(\pi_*W\omega_X)/p^{n + 1} \to (\pi_*W\omega_X)/p^n$ is surjective, so $\lim \: (\pi_*W\omega_X)/p^n = \Rlim \: (\pi_*W\omega_X)/p^n$.

	By construction, we have a commutative diagram \[ \begin{tikzcd}
		\pi_*W\omega_X \arrow[rr, "\theta"] \arrow[rd] &                                        & \cH^0\left(\Rlim \: (R\pi_*W\omega_X)/p^n\right), \\
		& \lim \: (\pi_*W\omega_X)/p^n \arrow[ru, "\cH^0(\psi)"'] &                                    
	\end{tikzcd} \] so in order to show that $\pi_*W\omega_X$ is derived $p$-complete, it suffices to show that $\cH^0(\psi)$ is an isomorphism (see the previous paragraph).
	%	First of all, $\pi_*W\omega_X$ is $p$-torsion free, so each complex $\pi_*W\omega_X/p^n$ is a sheaf, and $\lim \pi_*W\omega_X/p^n = \Rlim \pi_*W\omega_X/p^n$. Thus, we have to show that 
	%	For all $n \geq 1$, there is an exact triangle \[ \pi_*W\omega_X/p^n \to R\pi_*W\omega_X/p^n \to \tau_{\geq 1}R\pi_*W\omega_X/p^n \xto{+1} \] and applying $\Rlim$ to these triangles give \[ \Rlim \pi_*W\omega_X/p^n \to \Rlim R\pi_*W\omega_X/p^n \to \Rlim \tau_{\geq 1}R\pi_*W\omega_X/p^n \xto{+1} \]
	Note that there is a commutative diagram \[ \begin{tikzcd}
		{(R^1\pi_*W\omega_X)[p^{n + 1}]} \arrow[rr, "\cdot p"]                                              &  & {(R^1\pi_*W\omega_X)[p^n]}                                                         \\
		\cH^0\left(\left(\tau_{\geq 1}R\pi_*W\omega_X\right)/p^{n + 1}\right) \arrow[rr] \arrow[u, "\cong"] &  & \cH^0\left(\left(\tau_{\geq 1}R\pi_*W\omega_X\right)/p^n\right) \arrow[u, "\cong"]
	\end{tikzcd} \] (this is not specific to $R\pi_*W\omega_X$, this fact holds for any complex of abelian sheaves). Since there exists $e > 0$ such that $p^e \cdot R^1\pi_*W\omega_X = 0$ by $\bQ_p$--GR vanishing (\autoref{Witt_GR_vanishing}), we deduce that \[ \cH^0\left(\Rlim\left(\left(\tau_{\geq 1}R\pi_*W\omega_X\right)/p^n\right)\right) = \lim\cH^0\left(\left(\tau_{\geq 1}R\pi_*W\omega_X\right)/p^n\right) = \lim \: R^1\pi_*W\omega_X[p^n] = 0. \] By the triangle \autoref{triangle_p_compl}, we deduce that $\cH^0(\psi)$ is an isomorphism.

	Thus, we have proven that $\pi_*W\omega_X$ is derived $p$--complete. The fact that $\RGamma(Y, \pi_*W\omega_X)$ is also derived $p$--complete follows from \autoref{rem_derived_p_completion_second}.
\end{proof}

\begin{srem}
	It seems likely to the author that $\bQ_p$--GR vanishing was not necessary in the proof above. It could be that in general, the $p^{\infty}$--torsion of higher pushforwards of $W\omega_X$ under any proper map is annihilated by some fixed $p$--power. Nevertheless, we will need the full $\bQ_p$--GR vanishing later.
\end{srem}

\begin{scor}\label{finiteness_of_cohomology}
	Assume that $X$ and $Y$ are proper.  Then for all $i \geq 0$, the $W(k)$--module $H^i(Y, \pi_*W\omega_X)$ is finitely generated, and there is an isomorphism \[ H^i\left(Y, (\pi_*W\omega_X)/p\right) \cong H^i_{ss}(Y, \omega_{\pi, \GR}). \]
\end{scor}
\begin{proof}
	We have \[ H^i\left(Y, (\pi_*W\omega_X)/p\right) \expl{\cong}{by definition} H^i(Y, \omega_{\pi, \GR}^{\perf}) \expl{\cong}{\autoref{rem_ss_cohomology}} H^i_{ss}(Y, \omega_{\pi, \GR}), \] and we know that this latter $k$--vector space is finitely generated by properness. In particular, \[ \RGamma(Y, \pi_*W\omega_X)/p \expl{\cong}{\autoref{rem_derived_p_completion_first}} \RGamma(Y, (\pi_*W\omega_X)/p) \in D_{\mathrm{fg}}(k), \] so we conclude by \stacksproj{0CQF} that \[ \Rlim \RGamma(Y, \pi_*W\omega_X)/p^n \in D_{\mathrm{fg}}(W(k)). \] By \autoref{pushforward_p_complete}, this complex above is exactly $\RGamma(Y, \pi_*W\omega_X)$.
\end{proof}

\begin{notation_sec}
	Let $L$ be a field, and let $V^{\bullet} \in D^b_{\mathrm{fg}}(L)$. We set \[ \chi_L(V^{\bullet}) \coloneqq \sum_{i \in \bZ} (-1)^i\dim_L(\cH^i(V^{\bullet})). \]
\end{notation_sec}

Now comes the trick that allows us to compare the semistable Euler characteristics of $\omega_X$ and $\omega_{\pi, \GR}$.
\begin{slem}\label{Linus_paper_trick}
	Let $M^{\bullet} \in D^b_{\mathrm{fg}}(W(k))$. Then \[ \chi_K(M^{\bullet} \otimes^L_{W(k)} K) = \chi_k(M^{\bullet}/p). \]
\end{slem}
\begin{proof}
	This is standard, see e.g. the proof of \cite[Lemma 2.20]{Baudin_Patakfalvi_Rosler_Zdanowicz_On_Gorenstein_Q_p_rational_threefolds_and_fourfolds}.
\end{proof}

\begin{scor}\label{weak_GR_sheaf}
	Assume that $X$ and $Y$ are proper. Then \[ \chi_{ss}(Y, \omega_{\pi, \GR}) = \chi_{ss}(X, \omega_X). \]
\end{scor}
\begin{proof}
	We have that \begin{align*}
		\chi_{ss}(Y, \omega_{\pi, \GR}) & \expl{=}{\autoref{rem_ss_cohomology}} \chi(Y, (\pi_*W\omega_X)/p) = \chi_k\left(\RGamma(Y, (\pi_*W\omega_X)/p)\right) = \chi_k\left(\RGamma(Y, \pi_*W\omega_X)/p\right) \\
		& \expl{=}{\autoref{finiteness_of_cohomology} and \autoref{Linus_paper_trick}} \chi_K\left(\RGamma(Y, \pi_*W\omega_X) \otimes^L_{W(k)} K\right) \expl{=}{\autoref{Witt_GR_vanishing}} \chi_K\left(\RGamma(X, W\omega_X) \otimes^L_{W(k)} K\right) \\
		& \expl{=}{\autoref{Linus_paper_trick}} \chi_k\left(\RGamma(X, W\omega_X)/p\right)
		\expl{=}{\autoref{cone_of_p_Witt_omega}} \chi_k\left(\RGamma(X, \omega_X^{\perf})\right) \expl{=}{\autoref{rem_ss_cohomology}} \chi_{ss}(X, \omega_X). \qedhere
	\end{align*} 
\end{proof}

