In fact, there is the following generalization which follows from our techniques. We will use it in the proof of \autoref{euler_char_zero_implies_alb_fibered_by_ab_vars}:

\begin{scor}\label{weak_GR_sheaf_on_steroids}
	Assume that $X$ and $Y$ are proper. Let $L \in \Pic(Y)$ be a line bundle satisfying the following properties: for all $i \geq 0$, the vector spaces \[ H^i(X, \omega_X^{\perf} \otimes \pi^*L) \] and \[ H^i(Y, \omega_{\pi, \GR}^{\perf} \otimes L) \] are finitely generated. Then \[ \chi(Y, \omega_{\pi, \GR}^{\perf} \otimes L) = \chi(X, \omega_X^{\perf} \otimes \pi^*L). \]
\end{scor}
\begin{proof}
	Let $\underline{L}$ denote the Teichmüller lift of $L$ (it is then a line bundle over the ringed space $(Y, W\cO_Y)$). Note that both $W\omega_X \otimes_{W\cO_X} \pi^*\underline{L}$ are $\pi_*W\omega_X \otimes_{W\cO_Y} \underline{L}$ are derived $p$-complete (being derived $p$-complete is a local statement, so this reduces to \autoref{pushforward_p_complete}). In particular $\RGamma(X, W\omega_X \otimes_{W\cO_X} \pi^*\underline{L})$ and $\RGamma(Y, \pi_*W\omega_Y \otimes_{W\cO_Y} \underline{L})$ are also derived $p$--complete.

	Note that twisting the triangle of \autoref{cone_of_p_Witt_omega} by $\pi^*\underline{L}$ shows that $(W\omega_X \otimes_{W\cO_X} \pi^*\underline{L})/p \cong \omega_X^{\perf} \otimes_{\cO_X} \pi^*L$, and similarly $(\pi_*W\omega_X \otimes_{W\cO_Y} \underline{L})/p \cong \omega_{\pi, \GR}^{\perf} \otimes_{\cO_Y} L$. Hence, the assumption and the same argument as in \autoref{finiteness_of_cohomology} imply that each $W(k)$--module $H^i(X, W\omega_X \otimes \pi^*\underline{L})$ is finitely generated, and similarly for $H^i(Y, \pi_*W\omega_X \otimes_{W\cO_Y} \underline{L})$.

	Finally, note that for all $i > 0$, the sheaves $R^i\pi_*(W\omega_X \otimes_{W\cO_X} \pi^*\underline{L}) \cong R^i\pi_*W\omega_X \otimes_{W\cO_Y} \underline{L} = 0$ are $p$--power torsion by \autoref{Witt_GR_vanishing} (we use the projection formula for the morphism of ringed spaces $\pi \colon (X, W\cO_X) \to (Y, W\cO_Y)$, see \stacksproj{01E8}). Thus, we can apply the exact same proof as in \autoref{weak_GR_sheaf}. 
\end{proof}

If $L$ is ample or anti-ample, there seems to be no chance that the hypotheses of \autoref{weak_GR_sheaf_on_steroids} hold in general. Nevertheless, it holds in the intermediate situation: 

\begin{slem}\label{cohom_perfection_twist_fg}
	Let $\cM$ be a Cartier module on a proper variety $X$. Then for all $L \in \Pic^{\tau}(X)$ and $i \geq 0$, the $k$--vector spaces $H^i(X, \cM^{\perf} \otimes L)$ are finitely generated.
\end{slem}
\begin{proof}
	Since line bundles in  $\Pic^{\tau}(X)$ form a bounded family, the quantity \[ \sup_{L \in \Pic^{\tau}(X)}\{ h^i(X, \cM \otimes L) \} \] is finite. Hence, the lemma is immediate from the projection formula, and the standard fact that if $\{V_n\}_{n \geq 1}$ is an inverse system of $k$--vector spaces such that $\dim(V_n)$ is bounded independently on $n$, then $\lim V_n$ is also finite--dimensional.
\end{proof}

\section{Euler characteristic of Cartier modules on abelian varieties}\label{section_Euler_char_V_modules}

Our goal is to show that on an ordinary abelian variety $A$ (see \autoref{def_ordinarity_AV}), any Cartier module has non-negative semistable Euler characteristic. Since Cartier modules are ``GV-sheaves up to nilpotence'' (see \cite{Hacon_Pat_GV_Characterization_Ordinary_AV, Baudin_Positive_characteristic_generic_vanishing_theory}), a first idea would be mimic the proof that GV--sheaves have non-negative Euler characteristic.

Unfortunately, working with semistable Euler characteristic (which we must if we want to use generic vanishing techniques) makes the situation subtler: it is not always true that Cartier modules on \emph{any} abelian variety have non-negative semistable Euler characteristic. For example, if $E$ is a supersingular elliptic curve, then $\chi_{ss}(E, \omega_E) = -1$.

The fundamental issue is that this semistable Euler characteristic is \emph{not} invariant under twists as above, see \cite[Remark 3.4.3]{Baudin_Positive_characteristic_generic_vanishing_theory}.

\subsection{$V$-modules and generic vanishing}

\begin{defn}[{\cite[Section 5]{Hacon_Pat_GV_Geom_Theta_Divs}}]\label{def:V-module}
	The \emph{relative Verschiebung} $V_{A/k} \colon \bighat{A}^{(p)} = \bighat{A^{(p)}} \to \bighat{A}$ is by definition the dual isogeny of the relative Frobenius $F_{A/k} \colon A \to A^{(p)}$, see \stacksproj{0CC9}.

	Since $k$ is perfect, we can canonically identify $\bighat{A}^{(p)}$ and $\bighat{A}$ as schemes. The induced morphism $V \colon \bighat{A} \to \bighat{A}$ is called the \emph{absolute Verschiebung}. By definition, the diagram
	\[ \begin{tikzcd}
		\bighat{A} \arrow[rr, "V"] \arrow[d] &  & \bighat{A} \arrow[d] \\
		\Spec k \arrow[rr, "F^{-1}"]         &  & \Spec k             
	\end{tikzcd} \] commutes.
	\begin{itemize}
		\item A \emph{$V$-module} on $\bighat{A}$ is a pair $(\cN, \theta)$ where $\cN$ is a coherent sheaf on $\bighat{A}$ with a morphism $\theta \colon \cN \to V^*\cN$. A morphism of $V$-modules is defined as for Cartier modules: it is a morphism of underlying sheaves commuting with the $V$-module structures. The category of $V^s$-modules on $\bighat{A}$ is denoted $\Coh_{\bighat{A}}^{V}$.
		\item A $V$-module $(\cN, \theta)$ is nilpotent if $\theta^N = 0$ for some $N \geq 0$ (we abuse notations as in \autoref{rem:def_Cartier_mod}.\autoref{itm:abuse_iterates_structure_map}). Nilpotent modules form a Serre subcategory, whose quotient is the category of \emph{$V$-crystals}, denoted $\Crys_{\bighat{A}}^{V}$. If $\cN_1$ and $\cN_2$ are $V$-modules which are isomorphic as crystals, we shall write $\cN_1 \sim_V \cN_2$. 
		\item A $V$-module $(\cN, \theta)$ is said to be \emph{injective} if its structural map $\theta$ is injective.
	\end{itemize}
\end{defn}
\begin{rem}\label{canonical_injective_V_module}
	\begin{itemize}
		\item For any $V$-module $\cN$, there exists a canonical injective $V$-module $\cN_{\injj}$ with a surjective map $\cN \surj \cN_{\injj}$, inducing an isomorphism of crystals. Explicitly, $\cN_{\injj}$ is given by the image of $\cN \to \colim V^{es, *}\cN$.

		Note that the induced morphism $\cN \to \cN_{\injj}$ is indeed an isomorphism of $V$-crystals, since it is surjective and by construction, $\ker(f)$ is a nilpotent $V$-module.
	\end{itemize}
\end{rem}

\begin{notation}\label{not_euler_char_V_mods}
	Let $\cN$ be a $V$-module. We define \[ \chi_{ss}(\cN) \coloneqq \sum_i (-1)^i \dim_k\left(\colim \Tor_i(V^{e, *}\cN, k(0))\right). \]
\end{notation}

\begin{rem}
	By resolving $\cN$ by a complex of free modules at $\cO_{\bighat{A}, 0}$, we see that the $k$--vector spaces $\Tor_i(V^{e, *}\cN, k(0))$ have bounded dimension, independently of $e$. In particular, their colimit is also finite--dimensional (this is a general result about systems of vector spaces, which we let the reader verify).
\end{rem}

\begin{defn}\label{def_ordinarity_AV}
	An abelian variety is said to be \emph{ordinary} if the natural morphism $H^1(A, \cO_A) \to H^1(A, F_*\cO_A)$ induced by the Frobenius is an isomorphism.
%	Let $\phi$ denote the action of the Frobenius on $H^1(A, \cO_A)$. By \cite[Corollary p.143]{Mumford_Abelian_Varieties}, we can write \[ H^1(A, \cO_A) \cong H^1(A, \cO_A)_{ss} \oplus H^1(A, \cO_A)_{\nilp}, \] where $H^1(A, \cO_A)_{ss}$ has a basis of fixed points by $\phi$, and $H^1(A, \cO_A)_{\nilp}$ is nilpotent under the action of $\phi$. The $p$-rank of $A$ is then by definition \[ r(A) \coloneqq \dim_k H^1(A, \cO_A)_{ss} \in \{0, \dots, g\}. \]
%	
%	If $r(A) = g$, then $A$ is said to be \emph{ordinary}.
\end{defn}

