The idea is to rephrase our sought statement on Cartier modules by a statement on $V$--modules, which is much easier to handle. The key to do this is to use the (symmetric) \emph{Fourier--Mukai transform} on Cartier modules.


\begin{defn}[{\cite{Mukai_Fourier_Mukai_transform, Schnell_Fourier_Mukai_transform_made_easy}}]
	\begin{itemize}
		\item The \emph{Fourier-Mukai transforms} are the functors $R\bighat{S} \colon D_{\coh}(A) \to D_{\coh}(\bighat{A})$ and $RS \colon D_{\coh}(\bighat{A}) \to D_{\coh}(A)$ defined by 
		\[ R\hat{S}(\cM) \coloneqq Rp_{\hat{A}, *}(Lp_A^*\cM \otimes \cP)  \esp \mbox{ and } \esp RS(\cN) \coloneqq Rp_{A, *}(Lp_{\bighat{A}}^*\cN \otimes \cP), \] where $p_A \colon A \times \bighat{A} \to A$ and $p_{\bighat{A}} \colon A \times \bighat{A} \to \bighat{A}$ denote the projections.
		\item The \emph{symmetric Fourier-Mukai transforms} are the functors $\FM_A \coloneqq R\bighat{S} \circ D_A$ and $\FM_{\bighat{A}} \coloneqq RS \circ D_{\bighat{A}}$, where $D_A \coloneqq \cR\HHom(-, \omega_A[g])$ (and similarly for $D_{\bighat{A}}$).
	\end{itemize}
\end{defn}

Although the precise definition of the (symmetric) Fourier-Mukai transforms may look technical, we will never use it explicitly in this paper. We will rather use some of its well--known properties, that we recall now.

\begin{thm}\label{properties_Fourier_Mukai_transform}
	\begin{enumerate}
		\item\label{itm:equiv_cat} The functors $\FM_A$ and $\FM_{\bighat{A}}$ are inverses of each other, and hence equivalences of categories.
		\item\label{itm:behaviour_pushforwards_and_pullbacks} Let $f \colon A \to B$ be a morphism of abelian varieties, and let $\bighat{f} \colon \bighat{B} \to \bighat{A}$ denote the dual morphism. Then we have \[ \FM_B \: \circ \: Rf_* = L\bighat{f}^* \circ \FM_A. \]
		Here are two special cases:
		\begin{itemize}
			\item if $\cM$ is a coherent sheaf on $A$, then for all $i \geq 0$, \[ H^i(A, \cM)^{\vee} \cong \Tor_i(\FM_A(\cM), k(0)); \]
			\item if $\cM$ is a Cartier module, then each $\cH^i(\FM_A(\cM))$ has an induced $V$-module structure.
		\end{itemize}
		\item\label{support_H0} If $\cM$ is a coherent sheaf, then \[ \Supp \cH^0(\FM_A(\cM)) = \bigset{\alpha \in \bighat{A}}{ H^0(A, \cM \otimes \cP_{\alpha}) \neq 0}. \]
	\end{enumerate}
\end{thm}
\begin{proof}
	The statements \autoref{itm:equiv_cat} and \autoref{itm:behaviour_pushforwards_and_pullbacks} follow respectively from \cite[Theorem 3.2 and 5.1]{Schnell_Fourier_Mukai_transform_made_easy}, and \autoref{support_H0} is \cite[Theorem 2.2.8.(g)]{Baudin_Positive_characteristic_generic_vanishing_theory}.
\end{proof}

