Thanks to \autoref{SCSL for H^i = SCSL for Tor^i}, our approach to prove \autoref{intro_prop_euler_char} will be to study the semistable Euler characteristic of $V$--modules.

\subsection{Semistable Euler characteristic of $V$-modules}

Recall that a module is said to be \emph{torsion} if it is zero on some dense open subset. Our goal here is to show the following:

\begin{prop}\label{euler_char_V_modules}
	Assume that $A$ is ordinary. Then for any $V$--module $\cN$ on $\bighat{A}$, we have \[ \chi_{ss}(\cN) \geq 0. \] If $\cN$ is in addition torsion, then \[ \chi_{ss}(\cN) = 0. \]
\end{prop}

Throughout, assume that $A$ is ordinary, and let $g \coloneqq \dim(A)$. The idea will be to work at the completion $\cO_{\bighat{A}, 0} \cong k\llbracket x_1, \dots, x_g \rrbracket \eqqcolon R$. Let $\fm$ denote its maximal ideal. The following lemma will make the situation much easier:

\begin{lemma}\label{nice_form_for_V}
	There exists $y_1, \dots, y_g \in R$ such that $\fm = (y_1, \dots, y_g)$ and $V(y_i) = y_i$.
\end{lemma}
\begin{rem}
	Recall that $V|_k = (\cdot)^{1/p}$ by construction, so the lemma above does \emph{not} imply that $V = \id_R$ (which would be very wrong).
\end{rem}
\begin{proof}
	Let us first construct the $y_i$'s up to first order. Write \[ V(x_i) = \sum_j a_{ij} x_j \mod \fm^2, \] with $A \coloneqq (a_{ji}) \in \GL_g(k)$ ($V$ is étale by \autoref{equivalence_ordinary}), and let $\lambda = (\lambda_1, \dots, \lambda_g)^T \in k^g$. Then modulo $\fm^2$, we have \begin{equation}\label{equation_fixed_points}
		V\left( \sum_i \lambda_ix_i \right) \longexpl{=}{$V|_k = (\cdot)^{1/p}$ by construction} \sum_j \left(\sum_i \lambda_i^{1/p}a_{ij}\right) x_j.
	\end{equation} Hence, to find $g$ generators of $\fm$ fixed by $V$ up to second order, we have to find a basis $\lambda(1), \dots, \lambda(g)$ of $k^g$ such that for all $l$, \[ A \cdot \lambda(l)^{1/p} = \lambda(l), \] where for a vector $v = (v_1, \dots, v_g)^T \in k^g$, we write $v^{1/p} = (v_1^{1/p}, \dots, v_g^{1/p})$. Indeed, then the elements $\sum_i y_i = \lambda(l)_ix_i$ will generate $\fm$ and be fixed by $V$ modulo $\fm^2$ by \autoref{equation_fixed_points}.


	 Up to the change of variables $\mu(l) \coloneqq \lambda(l)^{p}$ and setting $B \coloneqq A^{-1}$, we want a basis of $k^g$ of solutions of the system \[ B\cdot \mu(l)^{p} = \mu(l). \] Note that the additive map \[ \begin{tikzcd}[row sep = tiny]
		k^g \arrow[rr, "\phi"]        &  & k^g            \\
		v \arrow[rr, maps to] &  & B\cdot v^{p}. \end{tikzcd} \] 
	is $p$--linear and injective. By \cite[Corollary p.143]{Mumford_Abelian_Varieties}, there is a basis of $k^g$ consisting of fixed points of $\phi$. We then conclude that there exist $y_1, \dots, y_g \in R$ such that $\fm = (y_1, \dots, y_g)$ and $V(y_i) = y_i$ modulo $\fm^2$. \\

	Let us construct a new generating set that is fixed modulo $\fm^3$. Write \[ V(y_i) = y_i + \sum_{s,t}b^i_{st}y_sy_t \mod \fm^3 \] with $b^i_{st} \in k$, and let $c^i_{st}$ be a solution of the equation \[ b^i_{st} + (c^i_{st})^{1/p}  = c^i_{st}. \] (such a solution exists since $k$ is algebraically closed). Then one checks immediately that \[ V\left(y_i + \sum_{s, t}c^i_{st}y_sy_t\right) = y_i + \sum_{s, t}c^i_{st}y_sy_t \mod \fm^3, \] i.e. we have our generating set fixed modulo $\fm^3$. Continuing indefinitely like this concludes the proof.
\end{proof}

From now on, assume that $V(x_i) = x_i$ for all $i$ (we may do so by \autoref{nice_form_for_V}). Since $V$ is an endomorphism of $R$, there is an straightforward notion of $V$--module on $R$. We will also use \autoref{not_euler_char_V_mods} in this setting. Furthermore, note that by assumption, $V$ also restrict to a morphism $V \colon R/x_i \to R/x_i$. When $N$ is a $V$--module on $R/x_i$ (and hence it is also a $V$-module on $R$), we will write $\chi_{ss}^{R/x_i}(N)$ (resp. $\chi_{ss}^R(N)$) for the quantity $\chi_{ss}$ computed on $R/x_i$ (resp. on $R$).

\begin{lemma}\label{euler_char_torsion_V_modules}
	Let $N$ be a $V$--module on $R = k\llbracket x_1, \dots, x_g \rrbracket$ such that $N$ is $x_i^e$--torsion for some $e > 0$ and $i \geq 0$. Then $\chi_{ss}(N) = 0$.
\end{lemma}
\begin{proof}
	For all $j$, let $N_j \inc N$ be the submodule of $x_i^j$-torsion elements. Then all these $N_j$'s are $V$-submodules, and the successive quotients of the filtration $0 \inc N_1 \inc N_2 \inc \dots \inc N$ are all $x_i$--torsion $V$-modules. By additive of the Euler characteristic, we are reduced to the case where $N$ is $x_j$--torsion. Note that $R$ is naturally a $V$--module, and since $V(x_i) = x_i$, we have an exact sequence of $V$--modules \[ \begin{tikzcd}
		0 \arrow[rr] &  & R \arrow[rr, "x_i"] &  & R \arrow[rr] &  & R/x_i \arrow[rr] &  & {0,}
	\end{tikzcd} \]
	(hence $R/x_i$ is also a $V$-module). This shows that as $V$--modules on $R/x_i$, \[ \Tor^R_0(N, R/x_i) \cong \Tor^R_1(N, R/x_i) \cong N. \] A straightforward computation with the Leray spectral sequence \[ \Tor^{R/x_i}_a(\Tor^R_b(N, R/x_i), k) \implies \Tor^R_{a + b}(N, k) \] shows that \[ \chi^R_{ss}(N) = \chi^{R/x_i}_{ss}(N) - \chi^{R/x_i}_{ss}(N) = 0. \qedhere \]
\end{proof}

\begin{proof}[Proof of \autoref{euler_char_V_modules}]
	As already stated, it is enough to show the result for  $V$--modules on $R = k\llbracket x_1, \dots, x_g\rrbracket \cong \cO_{\bighat{A}, 0}$, and assume by \autoref{nice_form_for_V} that $V(x_i) = x_i$. 

	Let $N$ be a $V$--module on $R$. Then we will show that $\chi_{ss}(N) \geq 0$, and if $N$ is torsion, that $\chi_{ss}(N) = 0$. Let us show the result by induction on $g$. If $g = 0$, the result is trivial, so assume that $g > 0$.

	Let $N' \subseteq N$ denote the $V$--submodule of $N$ consisting of $x_g^e$--torsion elements for some $e > 0$. Then we have a short exact sequence \[ \begin{tikzcd}
		0 \arrow[rr] &  & N' \arrow[rr] &  & N \arrow[rr] &  & N'' \arrow[rr] &  & {0,}
	\end{tikzcd} \] so by \autoref{euler_char_torsion_V_modules} and additivity of $\chi_{ss}$, it is enough to show the result for $N''$, which is $x_g$--torsion free. Then $\Tor_i^R(N'', R/x_g) = 0$ for all $i > 0$, so by the Leray spectral sequence \[ \Tor_j^{R/x_g}\left(\Tor_i^R(N'', R/x_g), k\right) \implies \Tor_{i + j}^R(N'', k), \] we have \[ \chi^R_{ss}(N'') = \chi^{R/x_g}_{ss}(N''/x_gN''). \] Hence, we can conclude the proof by induction (note that if $N$ was torsion to begin with, then also $N''/x_gN''$ would be torsion in $R/x_g$ too).
\end{proof}

\begin{cor}\label{Euler_char_Cartier_modules_ordinary}
	Let $\cM$ be a Cartier module on an ordinary abelian variety $A$. Then $\chi_{ss}(A, \cM) \geq 0$. Furthermore, if there exists a Cartier module $\cM' \sim_C \cM$ and $L \in \Pic^0(A)$ such that $H^0(A, \cM' \otimes L) = 0$, then $\chi_{ss}(A, \cM) = 0$.
\end{cor}
\begin{proof}
	The first statement follows from \autoref{euler_char_V_modules} and \autoref{SCSL for H^i = SCSL for Tor^i}. Assume now that there exists a Cartier module $\cM'$ such that $\cM' \sim_C \cM$ and that $H^0(A, \cM' \otimes L) = 0$ for some $L \in \Pic^0(A)$. This second hypothesis implies that $\Supp \cH^0(\FM_A(\cM')) \neq \bighat{A}$ by \autoref{properties_Fourier_Mukai_transform}.\autoref{support_H0}, so $\chi_{ss}(A, \cM') = 0$ by \autoref{euler_char_V_modules} and \autoref{SCSL for H^i = SCSL for Tor^i}. Finally, since $\cM' \sim_C \cM$, we obtain that $\cN^{\perf} \cong \cM^{\perf}$ by \autoref{Gabber_finiteness}.\autoref{itm:nil_iso_iff_perf_iso} and \cite[Lemma 3.5.(b)]{Blickle_Bockle_Cartier_modules_finiteness_results}, and hence $\chi_{ss}(A, \cM') = \chi_{ss}(A, \cM)$.
\end{proof}

