\begin{sdefn}
	A proper variety $X$ is said to be \emph{weakly ordinary} if for all $i \geq 0$, the natural map $H^i(X, \cO_X) \to H^i(X, F_*\cO_X)$ is an isomorphism.
\end{sdefn} 

\begin{scor}\label{main_thm_ordinary}
	Let $X$ be a smooth proper weakly ordinary variety of maximal Albanese dimension. Then \[ \chi(X, \omega_X) \geq 0. \] If $X$ is in addition not of general type, then \[ \chi(X, \omega_X) = 0. \]
\end{scor}
\begin{proof}
	By definition of weak ordinarity and Serre duality, we know that $\chi_{ss}(X, \omega_X) = \chi(X, \omega_X)$. By \autoref{main_thm_ss}, it is then enough to show that $\Alb(X)$ is ordinary. Given that the pullback map $H^1(\Alb(X), \cO_{\Alb(X)}) \to H^1(X, \cO_X)$ is injective (\autoref{existence_albanese}) and that the Frobenius action on $H^1(X, \cO_X)$ is bijective, there cannot be any nilpotent element in $H^1(\Alb(X), \cO_{\Alb(X)})$.
	By definition, $\Alb(X)$ is then ordinary.
\end{proof}

Given a Cartier module $\cM$, we denote by $V^0_{\injj}(\cM)$ the support of $\cH^0\FM_A(\cM)_{\injj}$ (see \autoref{canonical_injective_V_module} for the $(\cdot)_{\injj}$ notation).


\begin{sthm}\label{euler_char_zero_implies_alb_fibered_by_ab_vars}
	Let $X$ be a smooth proper weakly ordinary variety of maximal Albanese dimension, and assume that $\chi(X, \omega_X) = 0$. Then $\alb_X(X)$ is fibered by ordinary abelian varieties.
\end{sthm}

In the proof of \autoref{euler_char_zero_implies_alb_fibered_by_ab_vars}, we will need the following result:

\begin{sprop}\label{fibering_alb_image}
	Let $Y$ be a normal variety of maximal Albanese dimension with Albanese morphism $a \colon Y \to A$, and assume that $V^0_{\injj}(a_*\omega) \neq \bighat{A}$ for some non--zero Cartier module $\omega \inc \omega_Y$. Then $a(Y)$ is fibered by abelian varieties.
\end{sprop} 
