\section{ Proof of \cref{thm:relaxed-program,thm:relaxed-program-storable} (Solving the Relaxed Program)} \label{sec:appendix-relaxed-program}

In this section, we first provide a proof for \cref{thm:relaxed-program-storable}, where we allow for $d<\infty$. In \cref{subsec:service-scenario}, we explain how the proof of \cref{thm:relaxed-program} follows immediately if one sets $d=\infty$.

To prove \cref{thm:relaxed-program-storable}, we take the guess and verify approach. We rewrite the relaxed program as a linear program and set up the Lagrangian. For each constraint, we guess the states at which the constraint binds. We then choose the multiplier corresponding to the constraint so that, when the constraint binds, the coefficient of some appropriately selected primal variable equals 0 (\ref{subsec:multipliers-for-buyer-queue}, \ref{subsec:multipliers-for-item-storage}). This gives us freedom in choosing the primal variables, and we choose them so that complementary slackness holds (\ref{subsec:choie-of-primal-variables}). Then, weak duality arguments imply that our choice of primal variables is the optimal solution to the relaxed program (\ref{subsec:weak-duality}).

Let us start by assuming that there exist exogenous finite upper bounds $K,L\in \N$ such that the number of buyers in the queue at any given point in time cannot exceed $K$, and the number of goods in storage cannot exceed $L$. We choose $K$ and $L$ that are sufficiently high, in a sense we will make precise below.
We will later show that imposing these upper bounds is without loss of optimality (\cref{subsec:K=L=infty}).




It will be convenient to work with $P_k(v)$ and $Q_\ell \:= \sum_{i=\ell}^{L^*} q_i$, rather than $p_k(v)$ and $q_\ell$.
The choice variables for the relaxed program can be represented by a tuple 
$$(\{P_k\}_{k\in\{1,\ldots,K\}},\{Q_\ell\}_{\ell\in\{1,\ldots,L\}}, \{y_k\}_{k\in\{1,\ldots,K\}},\{z_\ell\}_{\ell\in\{1,\ldots,L\}},X(v) ),$$
where each $P_k$ is a CDF, each $Q_\ell$ is a real number in $[0,1]$, and each $y_k$, each $z_\ell$, and $X$ are measurable functions from $[0,1]$ to $[0,1]$.
The relaxed program is
\begin{equation*}
    \max_{P,Q,y,z,X} \l \int_0^1 J(v)X(v)f(v)dv - c \sum_{k=1}^K k[P_{k+1}(0)-P_k(0)]  - d \sum_{\ell=1}^L \ell (Q_\ell - Q_{\ell+1}) \leqno{[\widetilde{\mathcal{P}}]}
\end{equation*}
subject to
\begin{align*}
    & \lambda  \int^1_v X(s)f(s)ds \le  \mu\sum_{k=1}^{K} y_k(v)[P_{k+1}(v)-P_{k}(v)] \\
    & \textcolor{white}{\lambda  \int^1_v X(s)f(s)ds } + \l \sum_{\ell=1}^L (Q_\ell - Q_{\ell+1}) \int_v^1 f(s)z_\ell(s)ds & \forall v \tag{$\widetilde{RF}$} \\
    & \lambda (P_k(v)-P_{k-1}(v))[1-F(v)]\ge \mu y_{k}(v)[P_{k+1}(v)-P_k(v)] & \forall k \leq K,\, \forall v  \tag{${B_k}$} \\
    & \l \int_0^1 f(s)z_\ell(s)ds (Q_\ell - Q_{\ell+1})\leq  \mu (Q_{\ell-1} - Q_\ell) & \forall \ell \leq L,\, \forall v. \tag{${B_{-\ell}}$}
\end{align*}
To make the program linear, we perform a change of variables
\begin{align*}
    & Y_k(v) := y_k(v)(P_{k+1}(v) - P_k(v)) \\
    & Z_\ell(v) := (Q_\ell - Q_{\ell+1})f(v)z_\ell(v),
\end{align*}
and require that $Y_k(v) \leq P_{k+1}(v) - P_k(v)$ for each $k$ and $v$, and require $Z_\ell(v) \leq (Q_\ell - Q_{\ell+1})f(v)$ for each $\ell$ and $v$.
We may then write the Lagrangian as
\begin{align*}
    & \int_0^1 \l J(v)X(v)f(v)dv - c \sum_{k=1}^K k (P_{k+1}(0) - P_k(0)) - d \sum_{\ell=1}^L \ell(Q_\ell - Q_{\ell+1}) \\
    & +  \int_0^1 \alpha (v) \left(\mu
\sum_{k=1}^{K} Y_k(v) + \l \sum_{l=1}^L \int_v^1 Z_\ell(s)ds - \lambda  \int^1_v X(s)f(s)ds \right) dv \\
& + \sum_{k=1}^K \int_0^1 \beta_k(v) \bigg( \l (P_k(v) - P_{k-1}(v))[1-F(v)] - \mu Y_k(v) \bigg) dv \\
& + \sum_{l=1}^L  \gamma_{l} \bigg( - \l \int_0^1 Z_\ell(s)ds + \mu (Q_{\ell-1} - Q_\ell) \bigg) \\
& + \sum_{k=1}^K \int_0^1 \eta_k(v) \left( P_{k+1}(v) - P_k(v) - Y_k(v) \right) dv \\
& + \sum_{l=1}^L \int_0^1 \kappa_\ell(v)\left( (Q_\ell - Q_{\ell+1})f(v) - Z_\ell(v) \right) dv,
\end{align*}
where $\alpha, \beta_k, \gamma_\ell, \eta_k,$ and $\kappa_\ell$ are the multipliers. 
We may rewrite the Lagrangian as
\begin{align*}
    & - c \sum_{k=1}^K k (P_{k+1}(0) - P_k(0)) - d \sum_{\ell=1}^L \ell(Q_\ell - Q_{\ell+1}) \\
    & + \int_0^1 \l \left(J(v) - \int_0^v \alpha(s)ds\right) X(v)f(v)dv \\
    & + \sum_{k=1}^K \int_0^1 \bigg( \mu\alpha(v) - \mu\beta_k(v) - \eta_k(v)  \bigg) Y_k(v)dv \\
    & + \sum_{k=0}^K \int_0^1 \bigg( \l[1-F(v)](\beta_k(v) - \beta_{k+1}(v)) - (\eta_k(v)-\eta_{k-1}(v)) \bigg) P_k(v) dv \\
    & + \sum_{\ell=0}^L \left( \int_0^1  \Big(\kappa_\ell(v) - \kappa_{\ell-1}(v) \Big) f(v)   dv - \mu(\gamma_\ell - \gamma_{\ell+1})\right) Q_\ell \\
    & + \sum_{\ell=1}^L\int_0^1 \left( \l\int_0^v\alpha(s)ds - \l\gamma_\ell - \kappa_\ell(v) \right) Z_\ell(v) dv \\
    & + \int_0^1 \eta_K(v) dv,
\end{align*}
where we defined $\beta_0(v) = \beta_{K+1}(v) = \eta_0(v) = \eta_{-1}(v) = \gamma_0 = \gamma_{L+1} = \kappa_0(v) = \kappa_{-1}(v) = 0$, and we have used integration by parts for the second line and for the penultimate line. We can then rewrite this as
\begin{align}
    & \int_0^1 \l \left(J(v) - \int_0^v \alpha(s)ds\right) X(v)f(v)dv \label{eq44} \\
    & + \sum_{k=1}^K \int_0^1 \bigg( \mu\alpha(v) - \mu\beta_k(v) - \eta_k(v)  \bigg) Y_k(v)dv \label{eq45} \\
    & + \sum_{k=1}^K \int_0^1 \bigg( \l[1-F(v)](\beta_k(v) - \beta_{k+1}(v)) - (\eta_k(v)-\eta_{k-1}(v)) \bigg) (P_k(v) - P_k(0)) dv \label{eq20} \\
    & + \sum_{k=2}^K \left(\int_0^1 \Big(\l[1-F(v)](\beta_k(v) - \beta_{k+1}(v)) - (\eta_k(v)-\eta_{k-1}(v)) \Big) dv + c \right)  P_k(0) \label{eq22}\\
    & + \left(\int_0^1 \Big( \l[1-F(v)](\beta_1(v) - \beta_2(v)) - \eta_1(v)   \Big) dv + \mu \gamma_1+ c \right)  P_1(0) \label{eq24}\\
    & + \left( \int_0^1 \Big( - \l[1-F(v)]\beta_1(v)  + \kappa_1(v) f(v) \Big) dv - \mu(\gamma_1 - \gamma_2) - d\right) Q_1 \cr
    & + \sum_{\ell=2}^L \left( \int_0^1 \Big( \kappa_\ell(v) - \kappa_{\ell-1}(v)\Big) f(v)   dv - \mu(\gamma_\ell - \gamma_{\ell+1}) - d\right) Q_\ell \cr
    & + \sum_{\ell=1}^L \int_0^1 \left( \l\int_0^v\alpha(s)ds - \l\gamma_\ell - \kappa_\ell(v) \right) Z_{\ell} (v) dv \label{eq28}\\
    & + \int_0^1 \eta_K(v) dv - cK, \notag
\end{align}
where we split $P_k(v)$ into $P_k(v) - P_k(0)$ and $P_k(0)$, incorporated the costs in the first line into the rest of the expression, wrote the lines for $P_k(0)$ and $Q_{\ell}$ separately for $k=0,1$ and $\ell=0,1$, where $P_0(0):=Q_1$ and $Q_0:=P_1(0)$.

\subsection{Multipliers for Buyer Queue}\label{subsec:multipliers-for-buyer-queue}


Considering the coefficient of $X(v)$ in \eqref{eq44}, we choose
\begin{align}
    \alpha(v) = \begin{cases}
        J'(v) & \text{if } v \geq J^{-1}(0) \\
        0 & \text{if } v < J^{-1}(0).
    \end{cases}\label{eq29}
\end{align}
Because we assumed that the density $f$ is absolutely continuous, $J(v)$ is also absolutely continuous, so that we have $J(v) = \int_0^v \alpha(s)ds$ for $v \geq J^{-1}(0)$. Then, the coefficient of $X(v)$ is nonpositive when $v< J^{-1}(0)$ and equal to 0 when $v \geq J^{-1}(0)$. Hence, to maximize the Lagrangian, we may set $X(v)$ to be 0 for $v< J^{-1}(0)$ and any value in $[0,1]$ for $v \geq J^{-1}(0)$.

Considering the coefficeint of $Y(v)$ in \eqref{eq45}, let us choose
\begin{align}
    \eta_k(v) = \mu\alpha(v) - \mu\beta_k(v) \qquad \forall k\geq 1. \label{eq23}
\end{align}
This means that, to maximize the Lagrangian, we may set $Y_k(v)$ to be any value in [0,1].

Let us take as given for now a sequence of threshold values $\{\hat v_k\}_{k=1,\ldots,K}$, where $\hat v_k < \hat v_{k+1}$.\footnote{In the proofs, we drop the primes ($'$) in denoting variables for the storable case, so that e.g. $\hat v_k$ rather than $\hat v_k'$ refers to the $k$-th threshold when goods are storable.} We will later pin down these thresholds.
Let us set $\b_k(v) = 0$ for all $v < \hat v_k$. For $v\geq \hat v_k$,
we wish to choose $\b_k(v)$ so that the coefficient of $P_k(v) - P_k(0)$ is weakly negative when $v<\hat v_k$ and equal to 0 when $v\geq \hat v_k$. This will ensure that, to maximize the Lagrangian, we may set $P_k(v) = P_k(0)$ when $v<\hat v_k$, and we may set $P_k(v)$ to be any value in $[0,1]$ when $v \geq \hat v_k$.

Towards this goal, replace $\eta_k(v)$ in \eqref{eq20} using \eqref{eq23}. Then, the coefficient of $P_k(v) - P_k(0)$ for $k\geq 2$ becomes\footnote{We defined $\eta_0(v)=0$, so \eqref{eq23} does not hold for $k=0$, which means the case of $k=1$ must be dealt with separately.}
\begin{align}
    \l[1-F(v)](\beta_k(v) - \beta_{k+1}(v)) - \mu(\beta_{k-1}(v) - \beta_k(v)), \label{eq21}
\end{align}
and for $k = 1$, the coefficient becomes
\begin{align}
    \l[1-F(v)](\beta_1(v) - \beta_2(v)) - \mu\alpha(v) + \mu\beta_1(v). \label{eq25}
\end{align}
Define $h_k(v)\:=\b_k(v) - \b_{k-1}(v)$ and $\sigma(v)\:= 1/\rho(v) = \mu/\l[1-F(v)]$.
We want
\begin{align}
    & h_{k+1}(v) = \sigma(v) h_k(v) \qquad &\forall k\geq 2, \forall v \geq \hat v_k \label{eq:2-sided-1} \\
    & h_2(v) = \sigma(v) \left(\b_1(v) - J'(v) \right) \qquad &\forall v\geq \hat v_1. \label{eq:2-sided-3}
\end{align}
Use \eqref{eq:2-sided-1} to write
\begin{align*}
    \b_k(v) - \b_{k-1}(v) = h_{k}(v) = \sigma(v)^{k-2}h_2(v) \qquad \forall k\geq 2,\, \forall v \geq \hat v_{k-1}.
\end{align*}
Summing across $k$, we get
\begin{align}
    \beta_k(v) = \beta_1(v) + h_2(v) (1 + \sigma(v) + \cdots + \sigma(v)^{k-2}) \qquad \forall k\geq 2,\,\forall v\geq\hat v_{k-1}. \label{eq:2-sided-2}
\end{align}

It remains to pin down $\beta_1$ and $h_2$, or equivalently, $\beta_1$ and $\beta_2$. We do so using two equalities.
Fix an integer $i\geq 1$, and consider the case $v \in [\hat v_{i},\hat v_{i+1})$.
Since we set $\beta_k(v)=0$ for all $v<\hat{v}_k$, \eqref{eq:2-sided-2} implies that
\begin{align}
    \b_{i+1}(v) =  0 = \beta_1(v) + h_2(v) (1 + \sigma(v) + \cdots + \sigma(v)^{i-1}). \label{eq:2-sided-4}
\end{align}
Using \eqref{eq:2-sided-3} and \eqref{eq:2-sided-4}, we obtain
\begin{align*}
    &\beta_1(v) = \frac{\sigma(v) + \sigma(v)^2 + \cdots + \sigma(v)^i}{1 + \sigma(v) + \cdots + \sigma(v)^{i}} J'(v)\\
    &\beta_2(v) = \frac{\sigma(v)^2 + \sigma(v)^3 + \cdots + \sigma(v)^i}{1 + \sigma(v) + \cdots + \sigma(v)^{i}}J'(v).
\end{align*}
Therefore, using \eqref{eq:2-sided-2}, we obtain the closed form solution for $\beta$ as follows: for all $i \in \{1,\ldots,K\}$ and for all $v\in [\hat v_{i},\hat v_{i+1})$, we have 
\begin{align}
    \beta_k(v) = \begin{cases}
        \dfrac{\sigma(v)^k + \sigma(v)^{k+1} + \cdots + \sigma(v)^i}{1 + \sigma(v) + \cdots + \sigma(v)^{i}}J'(v) &\text{if } k=1,\ldots,i \\
        0 & \text{if } k=i+1, \ldots, K.
                \end{cases} \notag
\end{align}

Now, we pin down the thresholds $\{\hat v_k\}$ up to a constant. Using the fact that \eqref{eq25} is 0 when $v\geq \hat v_1$, the coefficient of $P_1(0)$ in \eqref{eq24} can be written as
\begin{align*}
    &\, \int_0^1 \Big( \l[1-F(v)](\beta_1(v) - \beta_2(v)) - \mu\alpha(v) + \mu\beta_1(v)   \Big) dv + \mu \gamma_1+ c\\
    &\,= -\int_0^{\hat v_1} \mu\alpha(v)
  dv + \mu \gamma_1+ c  \\
  &\, = -\mu J(\hat v_1) + \mu \gamma_1+ c.
\end{align*}
Taking $\g_1$ as given for now, we want the above coefficient to be 0 if the buyer queue is nonempty with a positive probability ($P_1(0)<1$) and positive if the buyer queue is always empty ($P_1(0)=1$).
We therefore choose
\begin{align}
    \hat v_1 = \max \left\{
        J^{-1}\left(\dfrac{c}{\mu} + \gamma_1\right),\, 1\right\}.\label{eq33}
\end{align}
If $\g_1 \leq J(1) - c/\m = 1-c/\m$, the Lagrangian may be maximized by setting $P_1(0)$ to be any value in $[0,1]$. If $\g_1 > 1 - c/\m$, the Lagrangian is maximized by $P_1(0)=1$. 

Consider now the coefficient of $P_k(0)$ for $k \geq 2$ in \eqref{eq22}.
Using the fact that \eqref{eq21} equals 0 when $v < \hat v_k$, the coefficient can be simplified to
\begin{align}
    \int_{\hat v_{k-1}}^{\hat v_k} -\mu\beta_{k-1}(v) dv + c.\notag
\end{align}
We therefore choose the thresholds $\hat v_k$ iteratively, using the following algorithm.
\begin{enumerate}\itemsep1em
    \item Define\footnote{Note that \eqref{eq17} is identical to \eqref{eq51} because $\sigma(v) = 1/\rho(v)$.}
        \begin{align}
        H_k(\hat v_{k-1},\hat v_k)\:= - \m \int_{\hat v_{k-1}}^{\hat v_k} \frac{\sigma(v)^{k-1}}{1 + \sigma(v) + \cdots + \sigma(v)^{k-1}} J'(v) d v + c. \label{eq17}
     \end{align}
     Set $k=2$.
    \item While $H_k(\hat v_{k-1},1)\leq 0$, choose $\hat v_k \in (\hat v_{k-1},1]$ so that $H_k(\hat v_{k-1}, \hat v_k) = 0$.\footnote{Such a $\hat v_k$ is unique because the integrand is strictly positive.} Then, increase $k$ by 1 and repeat step (b). If $H_k(\hat v_{k-1},1) > 0$, set $\hat v_k = \ldots = \hat v_K = 1$.
\end{enumerate}
Let $K^* < \infty$ denote the largest $k$ such that $\hat v_k<1$. 
Such a $K^*$ exists, since $(\sigma(v)^{k-1}-\sigma(v)^k) / (1-\sigma(v)^k) \in [0,1]$, so that the algorithm terminates after a finite number of steps. We can now see that it is enough to set $K$, the exogenous upper bound on queue length, to be any integer greater than $K^*$.
For $k= 2, \ldots, K^*$, the Lagrangian is maximized by choosing $P_k(0)$ to be any value in $[0,1]$. For $k > K^*$, the coefficient of $P_k(0)$ is positive, so the Lagrangian is maximized by choosing $P_k(0) = 1$.


 \subsection{Multipliers for Goods Storage}\label{subsec:multipliers-for-item-storage}

In \cref{subsec:multipliers-for-buyer-queue}, we chose the multiplier $\a$, and taking the multiplier $\g_1$ as given, we also chose the multipliers $\b_k$ and $\eta_k$. We now show how the two remaining multipliers, $\g_\ell$ and $\kappa_\ell$, can be chosen in a way that is consistent with our choice of $\b_k$ and $\eta_k$.

Let us take as given for now a sequence of threshold values $\{\hat v_{-\ell}\}_{\ell=1,\ldots,L}$ satisfying 
\begin{align}
    \hat v_1 \geq \hat v_{-1} \geq \hat v_{-2} \ldots \geq \hat v_{-L} \geq J^{-1}(0).\notag
\end{align}
We will later pin down these thresholds.

Consider the coefficient of $Z_\ell(v)$ in \eqref{eq28}:
\begin{align}
    &\, \l\int_0^v\alpha(s)ds - \l\gamma_\ell - \kappa_\ell(v). \notag
\end{align}
Let us define, for all $l=1,\ldots,L$ and $v\in[0,1]$,
\begin{align}
    \kappa_\ell(v) = \begin{cases}
        \l\int_0^v \alpha(s) ds - \l \gamma_\ell = \l (J(v) - \gamma_\ell) & \text{if } v \geq \hat v_{-\ell} \\
        0 & \text{if } v<\hat v_{-\ell},
    \end{cases} \notag
\end{align}
where the equality in the first case follows from our choice of $\a$ in \eqref{eq29}. This ensures that the coefficient of $Z_\ell(v)$ is equal to 0 when $v \geq \hat v_{-\ell}$ and nonpositive otherwise, which in turn implies that to maximize the Lagrangian, we may choose $Z_\ell(v)$ to be any value in $[0,1]$ for $v \geq \hat v_{-\ell}$ and 0 if otherwise.

Let us choose
\begin{align}
    \gamma_\ell = J(\hat v_{-\ell}).\notag
\end{align}
It remains to pin down $\hat v_{-\ell}$ for $\ell\in \{1,\ldots,L\}$. To encode the dependency of $\b_1$ on $\g_1 = J(\hat v_{-1})$, let us write $\b_1(v;\hat v_{-1})$.
Then, the coefficient of $Q_\ell$ for $\ell\geq 2$ is
\begin{align*}
    &\, B(\hat v_{-\ell+1}, \hat v_{-\ell}, \hat v_{-\ell-1}) \\
    \:= &\, \l[J(\hat v_{-\ell+1}) - J(\hat v_{-\ell})](1-F(\hat v_{-\ell+1})) + \int_{\hat v_{-\ell}}^{\hat v_{-\ell+1}} \l(J(v)-J(\hat v_{-\ell})) \ddd F(v) - \mu(J(\hat v_{-\ell}) - J(\hat v_{-\ell-1})) - d.
\end{align*}
Likewise, the coefficient of $Q_1$ is
\begin{align*}
    & A(\hat v_{-1}, \hat v_{-2})    :=  -\int_0^1 \l[1-F(v)]\beta_1(v;\hat v_{-1})dv + \int_{\hat v_{-1}}^1 \l(J(v) - J(\hat v_{-1})) \ddd F(v) - \mu(J(\hat v_{-1}) - J(\hat v_{-2})) -d.
\end{align*}
Because $J(v)$ is continuous, and because the positive thresholds $\hat v_k$ vary continuously as one varies $\hat v_{-1}$, $A$ and $B$ are also continuous. 
We wish to choose a nonnegative integer $L^* \leq L$ and negative thresholds $\{\hat v_{-\ell}\}_{\ell=1,\ldots,L}$ such that $v_\ell = J^{-1}(0)$ if and only if $\ell > L^*$, and the coefficient of $Q_\ell$ is 0 for $\ell\leq L^*$ and nonpositive for $\ell > L^*$. This will ensure that, to maximize the Lagrangian, we may choose $Q_\ell$ to be any value in $[0,1]$ for $\ell \leq L^*$, and choose $Q_\ell = 0$ for $\ell > L^*$.\footnote{Under the optimal Markov policy, $L^*$ is the maximum number of goods that are stored at any point in time.}

In \cref{subsec:IVT}, by iteratively appealing to the intermediate value theorem, we show that there exist such an $L^*$ and $\{\hat v_{\ell}\}_{\ell=1,\ldots,L}$. Note that the positive and negative thresholds are determined jointly. The choice of $\hat v_{-1}$ affects the values of the positive thresholds $\hat v_k$'s. This affects $\beta_1(v;\hat v_{-1})$, which in turn enters the expression $A(\hat v_{-1},\hat v_{-2})$ and thus affects the choice of negative thresholds.




\subsection{Choice of Primal Variables}\label{subsec:choie-of-primal-variables}

We now choose the primal variables $(P, Q, y, z, X)$. 
First, we choose
\begin{align*}
    &y_k(v) = 1 \qquad \forall v\in[0,1], \,\, \forall k=1,\ldots,K \\
    &z_\ell(v) = \begin{cases}
        1 & \text{ if } v \geq \hat v_{-\ell} \\
        0 & \text{ if } v < \hat v_{-\ell}.
    \end{cases}
\end{align*}

\subsubsection{Choice of $P$}\label{subsubsec:choice-of-P}

In \ref{subsubsec:choice-of-P}, we take $Q_1$ as given and pin down $\{P_k\}$ up to $Q_1$. Next, in \ref{subsubsec:choice-of-Q}, we will take $P_1(0)$ as given and pin down $\{Q_\ell\}$ up to $P_1(0)$. Then, we will argue that there exist $P_1(0)$ and $Q_1$ that are consistent with each other.

For $k>K^*$, we choose $P_k(v)=1$ for all $v$. 
For each $k \leq K^*$ and $v \in [0, \hat v_k)$, we choose $P_k(v) = P_k(0)$.
Now, consider some $i\in\{1,\ldots,K^*\}$ and $v\in [\hat v_i, \hat v_{i+1})$. 
Recall that we chose $\b_k(v)$ to be positive if $v \geq \hat v_k$. Therefore, in order to satisfy complementary slackness, we want $B_k$ to bind for $k=1,\ldots,i$. Since we chose $y_k(v) = 1$, this means that
\begin{align}
    \l[1-F(v)] (P_k(v) - P_{k-1}(v)) = \m (P_{k+1}(v) - P_k(v)) \qquad \forall k\in\{1,\ldots,i\}, \,  \forall v \in [\hat v_i,\hat v_{i+1}). \notag
\end{align}
Using the definition $\rho(v)\:=\l[1-F(v)]/\m$ and defining $P_0(v)\:=Q_1$, we have
\begin{align}
    P_k(v) - P_{k-1}(v) = \rho(v)^{k-1}(P_1(v) - Q_1) \qquad \forall k\in\{1,\ldots,i+1\}, \,  \forall v \in [\hat v_i,\hat v_{i+1}). \label{eq50}
\end{align}
Taking a summation of the above equation gives
\begin{align}
    P_k(v) = Q_1 + (1 + \rho(v) + \cdots + \rho(v)^{k-1})(P_1(v) - Q_1) \qquad \forall k\in\{1,\ldots,i+1\}, \,  \forall v \in [\hat v_i,\hat v_{i+1}). \label{eq47}
\end{align}
In particular, for $k=i+1$, we have
\begin{align}
    P_{i+1}(0) = P_{i+1}(v) = Q_1 + (1+ \rho(v) +\cdots + \rho(v)^i) (P_1(v) - Q_1) \qquad \forall v \in [\hat v_i,\hat v_{i+1}). \label{eq46}
\end{align}
Let us suppose for now that $Q_1$ is exogenously given. Then, choosing $P_{i+1}(0)$ pins down $P_1(v)$ through \eqref{eq46}, which in turn iteratively pins down $P_k(v)$ for each $k\in \{1,\ldots,i\}$, via \eqref{eq47}. Hence, the choice of $P_{i+1}(0)$ for each $i$ pins down $P_k(v)$ for each $k\in\{1,\ldots,K\}$ and $v\in[0,1]$.

We will choose each $P_{i+1}(0)$ so that $P_1$, and therefore $P_k$ for each $k\in\{1,\ldots,K\}$, are continuous.\footnote{When showing that our solution can be implemented by the optimal policy (\cref{thm:optimal-policy,thm:optimal-policy-storable}), we make use of the continuity of $P_k$. There may exist other solutions to the relaxed program such that $P_k$ is not continuous.} 
In particular, this means that each $P_k$ is constant on the closed interval $[0,\hat v_k]$. Since the balance inequality $B_k$ holds for $v=\hat v_k$, it must also hold for $v = [0,\hat v_k)$,\footnote{For $v \in [0,\hat v_k)$, the LHS of the balance inequality, $\l[1-F(v)](P_k(v) - P_{k-1}(v))$, is decreasing in $v$, while the RHS, $\m(P_{k+1}(v) - P_k(v))$, is constant in $v$.} guaranteeing that our choice of $P$ satisfies the balance inequalities.

For $P_1$ given by \eqref{eq46} to be continuous at $\hat v_i$, it must be that
\begin{align}
    \frac{P_{i+1}(0) - Q_1}{1+ \rho(\hat v_i) + \cdots + \rho(\hat v_i)^i} = \frac{P_i(0) - Q_1}{1+\rho(\hat v_i) + \cdots + \rho(\hat v_i)^{i-1}}. \notag
\end{align}
That is, for each $i\in\{1,\ldots,K^*\}$, $P_i(0)$ is determined iteratively by $P_{i+1}(0)$, and the initial condition is $P_{K^*+1}(0) = 1$. In particular, we have
\begin{align}
    P_1(0)-Q_1 &\, = (P_2(0)-Q_1)\frac{1}{1+\rho(\hat v_1)} \cr
    &\, = (P_3(0) - Q_1) \frac{1}{1+\rho(\hat v_1)}\frac{1+ \rho(\hat v_2)}{1+\rho(\hat v_2) + \rho(\hat v_2)^2} \cr
    &\, \cdots \cr
    &\, = (1-Q_1) \frac{1}{1+\rho(\hat v_1)} \cdots \frac{1+\rho(\hat v_{K^*}) + \cdots + \rho(\hat v_{K^*})^{K^*-1}}{1+\rho(\hat v_{K^*}) + \cdots + \rho(\hat v_{K^*})^{K^*}} \cr
    &\, =: (1-Q_1) \Delta_{K^*}. \label{eq48}
\end{align}

\subsubsection{Choice of $Q$}\label{subsubsec:choice-of-Q}

For $\ell \geq L^*+1$, we choose $Q_\ell = 0$, which guarantees that $B_{-\ell}$ holds for $\ell \geq L^*+1$. For $\ell \leq L^*$, the multiplier $\g_\ell = J(\hat v_{-\ell})$ is positive, so to satisfy complementary slackness, we will choose $Q_\ell$ so that $B_{-\ell}$ binds. Given our choice of $z$, this means that
\begin{align}
    \m (Q_{\ell-1} - Q_\ell) = \l[1-F(\hat v_{-\ell})](Q_\ell - Q_{\ell+1}) \qquad \forall \ell\leq L^*. \notag
\end{align}
Using the definitions $\sigma(v) := \m / \l[1-F(v)]$ and $Q_0:=P_1(0)$, we have
\begin{align}
    Q_{\ell-1} - Q_\ell = \sigma(\hat v_{-\ell+1}) \sigma(\hat v_{-\ell+2}) \cdots \sigma(\hat v_{-1})(P_1(0)-Q_1) \qquad \forall \ell \leq L^*+1. \notag
\end{align}
Taking a summation gives
\begin{align*}
    Q_\ell &\, = P_1(0) - (1 + \sigma(\hat v_{-1}) + \sigma(\hat v_{-1})\sigma(\hat v_{-2}) + \cdots + \sigma(\hat v_{-1})\sigma(\hat v_{-2}) \cdots \sigma(\hat v_{-\ell+1})) (P_1(0) - Q_1) \\
    &\, = P_1(0) - W_{\ell-1}(P_1(0) - Q_1),
\end{align*}
where $W_{\ell-1}\coloneqq 1 + \sigma(\hat v_{-1}) + \sigma(\hat v_{-1})\sigma(\hat v_{-2}) + \cdots + \sigma(\hat v_{-1})\sigma(\hat v_{-2}) \cdots \sigma(\hat v_{-\ell+1})$.
In particular, we have
\begin{align}
    0 = Q_{L^*+1} = P_1(0) - W_{L^*} (P_1(0) - Q_1), \notag
\end{align}
or
\begin{align}
    P_1(0) =  \frac{W_{L^*}}{W_{L^*}-1}  Q_1. \label{eq49}
\end{align}

One can easily check that there exist $P_1(0),Q_1 \in [0,1]$ that satisfy both \eqref{eq48} and \eqref{eq49}.

\subsubsection{Choice of $X$}
\label{subsubsec:choice-of-X}

We choose $X(v)=0$ for $v < J^{-1}(0)$.
For $v \geq J^{-1}(0)$, the multiplier $\a(v)$ is positive, so to satisfy complementary slackness, we choose $X(v)$ so that the reduced-form feasibility constraint holds with equality for $v \geq J^{-1}(0)$. Both the LHS and the RHS of the constraint are equal to 0 when $v=1$, so it is enough to choose $X$ so that the derivatives with respect to $v$ of both sides are equal to each other for $v \geq J^{-1}(0)$. That is, we want
\begin{align}
    \l X(v) f(v) = \m \frac{\dd P_1(v)}{\dd v} + \l \sum_{\ell=1}^{L^*} (Q_\ell - Q_{\ell+1}) f(v) z_\ell(v). \notag
\end{align}
Therefore, if $v \geq \hat v_1$, then we choose
\begin{align}
    X(v) = \frac{\m}{\l f(v)} 
\frac{\dd P_1(v)}{\dd v} + Q_1, \notag
\end{align}
and if $v\in [\hat v_{-\ell}, \hat v_{-\ell+1})$ for $\ell \in \{2,\ldots,L^*\}$, then we choose
\begin{align}
    X(v) = Q_\ell. \notag
\end{align}
If $v \in [\hat v_{-1}, \hat v_1)$, then we choose $X(v) = Q_1$. If $v \in [J^{-1}(0), \hat v_{-L^*})$, then we choose $X(v) = 0$.

Clearly, the reduced-form feasibility constraint holds as well for $v < J^{-1}(0).$



\subsection{Weak Duality}\label{subsec:weak-duality}

Let $\mathcal{L}(P,Q,y,z,X; \a,\b,\g,\eta,\kappa)$ represent the Lagrangian as a function of the primal and the dual variables.
Let $(P^*, Q^*, y^*, z^*, X^*)$ denote the primal variables that we have chosen thus far, and let $(\a^*,\b^*,\g^*,\eta^*,\kappa^*)$ denote the multipliers we have chosen.
We have established that the following three conditions hold:
\bigskip
\begin{enumerate}
    \item $(P^*, Q^*, y^*, z^*, X^*)$ is a feasible solution to the relaxed program, i.e. it satisfies all the constraints of the program.
    \item Given $(\a^*,\b^*,\g^*,\eta^*,\kappa^*)$, $\mathcal{L}$ is maximized by $(P^*, Q^*, y^*, z^*, X^*)$.
    \item Complementary slackness holds.\footnote{To be precise, that complementary slackness holds means that, if we define the function $\mathcal{T}$ by
    \begin{align*}
    \mathcal{T}(P,Q,y,z,X; \a,\b,\g,\eta,\kappa) = &\,  \int_0^1 \alpha (v) \left(\mu
    \sum_{k=1}^{K} Y_k(v) + \l \sum_{l=1}^L \int_v^1 Z_\ell(s)ds - \lambda  \int^1_v X(s)f(s)ds \right) dv \\
    &\, + \sum_{k=1}^K \int_0^1 \beta_k(v) \bigg( \l (P_k(v) - P_{k-1}(v))[1-F(v)] - \mu Y_k(v) \bigg) dv \\
    &\, + \sum_{l=1}^L  \gamma_{l} \bigg( - \l \int_0^1 Z_\ell(s)ds + \mu (Q_{\ell-1} - Q_\ell) \bigg) \\
    &\, + \sum_{k=1}^K \int_0^1 \eta_k(v) \left( P_{k+1}(v) - P_k(v) - Y_k(v) \right) dv \\
    &\, + \sum_{l=1}^L \int_0^1 \kappa_\ell(v)\left( (Q_\ell - Q_{\ell+1})f(v) - Z_\ell(v) \right) dv,
    \end{align*}
    then $\mathcal{T}(P^*, Q^*, y^*, z^*, X^*;\a^*,\b^*,\g^*,\eta^*,\kappa^*)=0$.
    }
\end{enumerate}
\bigskip 

Then, for any feasible $(P,Q,y,z,X)$, we have
\begin{align*}
    &\,\int_0^1 \l J(v)X^*(v)f(v)dv - c \sum_{k=1}^K k (P^*_{k+1}(0) - P^*_k(0)) - d \sum_{\ell=1}^L \ell(Q^*_\ell - Q^*_{\ell+1}) \\
    = &\,\mathcal{L}(P^*, Q^*, y^*, z^*, X^*;\a^*,\b^*,\g^*,\eta^*,\kappa^*)\\
    \geq&\, \mathcal{L}(P, Q, y, z, X;\a^*,\b^*,\g^*,\eta^*,\kappa^*)\\
    \geq &\, \int_0^1 \l J(v)X(v)f(v)dv - c \sum_{k=1}^K k (P_{k+1}(0) - P_k(0)) - d \sum_{\ell=1}^L \ell(Q_\ell - Q_{\ell+1}),
\end{align*}
where the equality follows from (c), the first inequality from (b), and the second inequality from the feasibility of $(P,Q,y,z,X)$. Therefore, $(P^*, Q^*, y^*, z^*, X^*)$ solves the relaxed program $[\widetilde{\mathcal P}]$.


\subsection{Existence of Thresholds}\label{subsec:IVT}

For exposition, redefine 
\begin{align}
A(\g_1, \g_2) :=\d(\g_1) + \int_{J^{-1}(\g_1)}^1 \l(J(v) - \g_1) \ddd F(v) - \mu(\g_1 - \g_2) -d.  \notag
\end{align}
where $\d(\g_1):= -\int_0^1 \l[1-F(v)]\beta_1(v;J^{-1}(\g_{1}))dv$, and
\begin{align}
   B(\g_{\ell-1}, \g_\ell, \g_{\ell+1}):=    \l(\g_{\ell-1} - \g_\ell)(1-F(J^{-1}(\g_{\ell-1}))) + \int_{J^{-1}(\g_{\ell})}^{J^{-1}(\g_{\ell-1})} \l(J(v)-\g_\ell) \ddd F(v) - \mu(\g_\ell - \g_{\ell+1}) - d. \notag
\end{align}
$A(\g_1, \g_2)$ is increasing in $\g_2$. 
$B(\g_{\ell-1}, \g_\ell, \g_{\ell+1})$ is increasing in $\g_{\ell-1}$ and $\g_{\ell+1}$, and is decreasing in $\g_\ell$. Both $A$ and $B$ are continuous. Moreover, $A(1,\g_2)<0$ for all $\g_2$, and $B(\g_{\ell-1},\g_\ell,\g_{\ell+1})<0$ whenever $\g_{\ell-1} = \g_\ell$.

If $A(0,0) \leq 0$, then we set $L^*=0$, and we are done. Otherwise, since $A(0,0)>0$ and $A(1,1)<0$, there  exists $\gh^1 \in (0,1)$ such that $A(\gh^1, \gh^1)=0.$  
Without loss, assume that $\gh^1$ is the smallest such value. In other words, $A(\g,\g)>0$ for all $\g\in[0,\gh^1)$. Next, $A(\gh^1, \g)<0$ for all $\g<\gh^1$.  Hence, there exists $\g^0<\gh^1$ such that $A(\g^0,0)=0$.  Without loss, take $\g^0$ to be the largest such value, namely:  $A(\g,0)<0$ for all $\g\in (\g^0, \gh^1]$. If $B(\g^0,0,0) \leq 0$, then we choose $\g_1 = \g^0$ and $L^*=1$, and we are done.\\

Next, suppose $B(\g^0, 0,0)>0 $.
For any $\g\in [\g^0,\gh^1]$, since $A(\g,0)\leq 0$ and $A(\g,\g) \geq 0$, there exists $\nu_2(\g)\in [0,\gh^1]$ such that 
\begin{align}
    A(\g,\nu_2(\g))=0. \notag
\end{align}
Observe that $\nu_2(\gh^1)=\gh^1$ and 
$\nu_2(\g^0)=0$.  Further, since $A$ is continuous and is strictly increasing in its second argument, $\nu_2(\cdot)$ is continuous.  

Then, 
$B(\g^0,\nu_2(\g^0),0)>0$ and since 
$B(\gh^1,\nu_2(\gh^1), 0)<0$, there exists 
$\g^1\in [\g^0, \gh^1]$ such that 
 \begin{align} \label{eq:B}
    B(\g^1,\nu_2(\g^1), 0)=0.
\end{align}
Without loss, take $\g^1$ to be the largest such value. If $B(\nu_2(\g^1),0,0) \leq 0$, then we may choose $\g_1 = \g^1$, $\g_2 = \nu_2(\g^1)$, and $L^*=2$, and we are done.\footnote{Note that $\g_2>0$ because $B(\g^1,0,0) \geq B(\g^0,0,0) > 0$.} \\

At this point, we may proceed directly to the general induction argument, but for expositional purposes, we first work through one additional step.
Suppose that 
$$B(\nu_2(\g^1),0, 0)>0. $$



Since $B$ is increasing in its last argument, \eqref{eq:B} implies that $B(\g^1,\nu_2(\g^1),\nu_2(\g^1))>0$. Also, since $\nu_2(\gh^1) = \gh^1$, it must be that
$B(\gh^1,\nu_2(\gh^1),\nu_2(\gh^1))<0$. Thus there exists $\gh^2\in (\g^1 , \gh^1)$ such that 
$$B(\gh^2,\nu_2(\gh^2),\nu_2(\gh^2))=0.$$  Without loss, let $\gh^2$ be the smallest such value.

Fix any $\g\in [\g^1, \gh^2]$.  Then, 
$$B(\g,\nu_2(\g),\nu_2(\g))\ge 0.$$
This follows from the definition of $\gh^2$.
Note also that 
$$B(\g,\nu_2(\g),0)\le 0.$$
This follows from the definition of $\g^1$.

Hence, there exists $\nu_3(\g)\in [0,\nu_2(\g)]$ such that 
 \begin{align}
    B(\g,\nu_2(\g), \nu_3(\g))=0. \notag
\end{align}
Because $B$ is strictly increasing in its third argument, it must be that 
$\nu_3(\g^1)=0$ and $\nu_3(\gh^2)=\nu_2(\gh^2)$.
Moreover, because $B$ is continuous, and is strictly increasing in its third argument, $\nu_3$ is continuous.

Recall our hypothesis:   
$$B(\nu_2(\g^1),\nu_3(\g^1),0)=B(\nu_2(\g^1),0, 0)>0. $$
Since  $\nu_3(\gh^2)=\nu_2(\gh^2)$, we have 
$$B(\nu_2(\gh^2),\nu_3(\gh^2),0)<0.$$
Hence, there exists $\g^2\in [\g^1,\gh^2]$ such that 
 \begin{align} 
    B(\nu_2(\g^2),\nu_3(\g^2),0)=0.\notag
\end{align}
Without loss, let $\g^2$ be the largest such value. If $B(\nu_3(\g^2),0,0) \leq 0$, then we choose $\g_1 = \g^2$, $\g_2 = \nu_2(\g^2)$, and $\g_3 = \nu_3(\g^2)$, and choose $L^*$ to be the largest $\ell\in \{1,2,3\}$ such that $\g_\ell >0$, and we are done. \\

We now make the general induction argument.


\begin{defn}[Induction hypothesis at $k \geq 2$]
There exist $\g^{k-3}, \g^{k-2}, \g^{k-1}, \gh^{k-1}, \gh^{k-2} \in [0,1]$ with $\g^{k-3} \leq \g^{k-2} \leq \g^{k-1} \leq \gh^{k-1} \leq \gh^{k-2}$, a continuous function $\nu_{k-1}:[\g^{k-3},\gh^{k-2}] \to [0,\gh^{k-2}]$, and a continuous function $\nu_k:[\g^{k-2},\gh^{k-1}] \to [0,\gh^{k-1}]$ that satisfy the following conditions.\footnote{When $k=2$, define $\g^{-1}:=1$ and $\gh^0:=1$, and define $\nu_1$ to be the identity function on $[0,1]$.}
\vspace{1em}
\begin{enumerate}\itemsep1em
    \item $B(\nu_{k-1}(\g^{k-1}),\nu_k(\g^{k-1}),0) = 0$.
    \item $B(\nu_{k-1}(\g),\nu_k(\g),0) < 0$ for all $\g \in (\g^{k-1},\gh^{k-1}]$.
    \item $\nu_k(\g^{k-2})=0$ and $\nu_k(\gh^{k-1}) = \nu_{k-1}(\gh^{k-1})$.
    \item $\nu_k(\g) \leq \nu_{k-1} (\g)$ for all $\g \in [\g^{k-2},\gh^{k-1}]$.
\end{enumerate}
\end{defn}
\vspace{1em}

We showed above that either a solution exists with $L^* \leq 2$, or the induction hypothesis holds at $k=2$. We wish to show that, for $k\geq 2$, if
$$B(\nu_k(\g^{k-1}),0, 0)>0, $$
then the induction hypothesis at $k$ implies the induction hypothesis at $k+1$.
Since $B$ is strictly increasing in its last argument, induction hypothesis (a) implies that 
$$B(\nu_{k-1}(\g^{k-1}),\nu_k(\g^{k-1}),\nu_k(\g^{k-1}))>0.$$ 
Also, since $\nu_k(\gh^{k-1}) = \nu_{k-1}(\gh^{k-1})$ by hypothesis (c), it must be that
$$B(\nu_{k-1}(\gh^{k-1}),\nu_k(\gh^{k-1}),\nu_k(\gh^{k-1}))<0.$$ 
Thus there exists $\gh^k\in (\g^{k-1} , \gh^{k-1})$ such that 
\begin{align}\label{eq:ghk}
    B(\nu_{k-1}(\gh^k),\nu_k(\gh^k),\nu_k(\gh^k))=0.
\end{align}
Without loss, let $\gh^k$ be the smallest such value.

Fix any $\g\in [\g^{k-1}, \gh^k]$.  Then, by our choice of $\gh^k$, it must be that
$$B(\nu_{k-1}(\g),\nu_k(\g),\nu_k(\g))\ge 0.$$
Moreover, by induction hypothesis (b), we have
$$B(\nu_{k-1}(\g),\nu_k(\g),0)\le 0.$$
Hence, there exists $\nu_{k+1}(\g)\in [0,\nu_k(\g)]$ such that 
 \begin{align*} 
    B(\nu_{k-1}(\g),\nu_k(\g), \nu_{k+1}(\g))=0.
\end{align*}
Thus hypothesis (d) holds for $k+1$.
Because $B$ is strictly increasing in its third argument, it must be that 
$\nu_{k+1}(\g^{k-1})=0$ (by induction hypothesis (a)) and $\nu_{k+1}(\gh^k)=\nu_k(\gh^k)$ (by \eqref{eq:ghk}). Thus hypothesis (c) is satisfied for $k+1$.
Moreover, because $B$ is continuous, and is strictly increasing in its third argument, $\nu_{k+1}$ is continuous.

Recall that we assumed   
$$B(\nu_k(\g^{k-1}),\nu_{k+1}(\g^{k-1}),0)=B(\nu_k(\g^{k-1}),0, 0)>0. $$
Since  $\nu_{k+1}(\gh^k)=\nu_k(\gh^k)$, we have 
$$B(\nu_k(\gh^k),\nu_{k+1}(\gh^k),0)<0.$$
Hence, there exists $\g^k\in [\g^{k-1},\gh^k]$ such that 
\begin{align*} %\label{eq:Bk}
    B(\nu_k(\g^k),\nu_{k+1}(\g^k),0)=0.
\end{align*}
Without loss, let $\g^k$ be the largest such value. This satisfies hypotheses (a) and (b) for $k+1$.

Finally, for large enough $k$, we must have $B(\nu_k(\g^{k-1}),0,0)\leq 0$.
This is because the sum
\begin{align*}
    &\, A(\g_1, \g_2) + \sum_{\ell=2}^{\hat{L}} B(\g_{\ell-1}, \g_\ell, \g_{\ell+1}) \\
    = &\, \d(\g_1) + \int_{J^{-1}(\g_{\hat L})}^1 \l(J(v) - \g_{\hat L}) dF(v) - \mu(\g_1 - \g_{\hat L +1}) - \hat L d
\end{align*}
eventually becomes negative when $\hat L$ is large enough. When $B(\nu_k(\g^{k-1}),0,0)\leq 0$, there exists a solution with $L^* \leq k$.


\subsection{$K=L=\infty$} \label{subsec:K=L=infty}

We prove that it is without loss of optimality to restrict attention to policies with bounded queue lengths.

\begin{prop}
    There exists an optimal policy such that, at any point in time, at most $K \in \N$ buyers are in the queue, and at most $L \in \N$ goods are stored.
\end{prop}
\begin{proof}
Let $[\widetilde{\mathcal{P}}_{K,L}]$ denote the relaxed program with bounds $K,L\in \N\cup \{\infty\}$. Let $\text{val}(\widetilde{\mathcal{P}}_{K,L})$ denote the value of the program. The Lagrangian analysis tells us that for $K$ and $L$ large enough, $\text{val}(\widetilde{\mathcal{P}}_{K,L})$ becomes constant in $K$ and $L$. It will be enough to show that $\text{val}(\widetilde{\mathcal{P}}_{\infty,\infty}) = \lim_{K,L\to \infty} \text{val}(\widetilde{\mathcal{P}}_{K,L})$. It is clear that $\text{val}(\widetilde{\mathcal{P}}_{\infty,\infty}) \geq \lim_{K,L\to \infty} \text{val}(\widetilde{\mathcal{P}}_{K,L})$, so we only need to show that the inequality also holds in the other direction.


Suppose to the contrary that there exists a feasible (but not necessarily optimal) solution $(\bar P,\bar Q,\bar y,\bar z, \bar X)$ to $[\widetilde{\mathcal{P}}_{\infty,\infty}]$ that gives the seller a payoff $\mathcal{V} > \lim_{K,L\to \infty} \text{val}(\widetilde{\mathcal P}_{K,L})$. 
We will construct a sequence of solutions $(\bar P^K,\bar Q^K,\bar y^K,\bar z^K, \bar X^K)$ such that $(\bar P^K,\bar Q^K,\bar y^K,\bar z^K, \bar X^K)$ is feasible under $[\widetilde{\mathcal P}_{K,K}]$ for each $K\in \N$, and the seller's payoff under $(\bar P^K,\bar Q^K,\bar y^K,\bar z^K, \bar X^K)$ becomes arbitrarily close to $\mathcal{V}$ as $K$ grows large. This will imply that $\lim_{K,L\to \infty} \text{val}(\widetilde{\mathcal P}_{K,L}) \geq \mathcal{V}$, which is a contradiction.


To this end, given the solution $(\bar P,\bar Q,\bar y,\bar z, \bar X)$ to $[\widetilde{\mathcal P}_{\infty,\infty}]$, define a sequence of solutions by
\begin{align*}
    \bar P^K_k(v) &\, := \begin{cases}
        1 & \text{if } k\geq K+1 \\
        \bar P_k(v) / \bar P_{K+1}(v) & \text{if } k \leq K
        \end{cases}  &\forall k,\forall v \\
    \bar Q ^K_\ell &\, := \begin{cases}
        0 & \text{if } \ell \geq K+1 \\
        (\bar Q_\ell - \bar Q_{K+1}) / (1 - \bar Q_{K+1}) & \text{if } \ell \leq K
        \end{cases}  &\forall \ell \\
    \bar y_k^K(v) &\, :=\bar y_k(v) \qquad &\forall k,\forall v \\
    \bar z^K_\ell (v) &\, := \bar z_\ell (v) & \forall \ell, \forall v\\ 
    \bar X^K(v) &\, := \frac{\bar X(v) - (1 - \bar P_{K}(0)) - \bar Q_{K+1}}{B^K(v) } & \forall v,
\end{align*}
where
$$ B^K(v) := \max\{\bar P_{K+1}(v), 1 - \bar Q_{K+1} \}.$$
That is, $\bar P^K_k(v)$ is the distribution $\bar P_k(v)$ conditional on the $K+1$-th highest buyer having value at most $v$, and $\bar Q_\ell^K$ is the probability that there are at least $\ell$ goods, conditional on there being at most $K$ goods.\footnote{For low values of $K$, it may be that $\bar P_{K+1}(v)$ or $1-\bar Q_{K+1}$ equals 0. However, each of these must converge to 1 as $K$ grows large, so $\bar P_k^K$, $\bar Q_\ell^K$, and $\bar X^K$ are well-defined for $K$ large enough. This is sufficient for our purposes.} It is verified that $\bar X^K(v) \leq 1$.


We claim that, for each $K$, the solution $(\bar P^K,\bar Q^K,\bar y^K,\bar z^K, \bar X^K)$ is feasible for $[\widetilde{\mathcal P}_{K,K}]$. To see that the balance inequalities hold, observe that $(B_k)$ remains unchanged for $k\leq K$ and holds trivially for $k \geq K+1$ because the RHS is 0. Likewise, $(B_{-\ell})$ is satisfied. The reduced-form feasibility constraint holds because
\begin{align*}
    &\, \l \int_v^1 \bar X^K (s)f(s) ds \\ 
    = &\, \l \int_v^1 \frac{\bar X(s) - (1 - \bar P_{K}(0)) - \bar Q_{K+1}}{B^K(s) } f(s)ds \\
    \leq &\, \frac{1}{B^K(v)}\left(\l \int_v^1 \bar X (s)f(s)ds - \l [1-F(v)] (1 - \bar P_{K}(0) + \bar Q_{K+1}) \right)\\
    \leq &\, \frac{1}{B^K(v)}\left( \l \int_v^1  \bar X (s)f(s)ds - \l [1-F(v)] (1 - \bar P_{K}(v) + \bar Q_{K+1})\right)  \\
    = &\, \frac{1}{B^K(v)}\left( \l \int_v^1 \bar X (s)f(s)ds - \l [1-F(v)] \sum_{k=K+1}^\infty [\bar P_k(v) - \bar P_{k-1}(v)] - \l[1-F(v)] \sum_{\ell=K+1}^\infty [\bar Q_{\ell} - \bar Q_{\ell+1}] \right) \\ 
    \leq &\, \frac{1}{B^K(v)}\left( \l \int_v^1 \bar X (s)f(s)ds - \mu \sum_{k=K+1}^\infty y_{k}(v)[\bar P_{k+1}(v) - \bar P_k(v)] - \l \sum_{\ell=K+1}^\infty \int_v^1 f(s)z_\ell(s)ds [\bar Q_\ell - \bar Q_{\ell+1}] \right) \\
    \leq &\, \frac{1}{B^K(v)}\left( \mu \sum_{k=1}^{K} y_{k}(v)[\bar P_{k+1}(v) - \bar P_k(v)] + \l \sum_{\ell=1}^K \int_v^1 f(s)z_\ell(s)ds [\bar Q_\ell - \bar Q_{\ell+1}] \right) \\
    \leq &\, \mu \sum_{k=1}^{K} y_{k}(v)[\bar P_{k+1}^K(v) - \bar P_k^K(v)] + \l \sum_{\ell=1}^K \int_v^1 f(s)z_\ell(s)ds [\bar Q^K_\ell - \bar Q^K_{\ell+1}],
\end{align*}
where the first equality holds by the definition of $\bar X^K$, the first and second inequalities hold from the fact that $B^K(v)$ and $\bar P_{k}(\cdot)$ are non-decreasing, the second equality holds by the countable additivity of probability measures,\footnote{Recall that $P_k(v) - P_{k-1}(v)$ is the probability that there are exactly $k-1$ buyers in the queue with values above $v$.} the third inequality holds by the balance inequalities $(B_k)$ for $[\widetilde{\mathcal P}_{\infty,\infty}]$ and because $z_\ell(v) \leq 1$, the fourth inequality holds by the reduced-form feasibility constraint for $[\widetilde{\mathcal P}_{\infty,\infty}]$, and the final inequality uses the observation that
\begin{align}
    \bar Q_\ell^K - \bar Q_{\ell+1}^K = \begin{cases}
        \dfrac{\bar Q_\ell - \bar Q_{\ell+1}}{1 - \bar Q_{K+1}} & \text{if } \ell \leq K-1 \\
        \dfrac{\bar Q_K - \bar Q_{K+1}}{1-\bar Q_{K+1}} &\text{if } \ell = K \\
        0 & \text{if } \ell \geq K+1.
    \end{cases} \notag
\end{align}
It remains to show that the seller's payff under $(\bar P^K,\bar Q^K,\bar y^K,\bar z^K, \bar X^K)$ convergences to $\mathcal{V}$. Clearly, for each $v,k$, and $\ell$, we have 
\begin{align*}
    & \lim_{K\to\infty} \bar P_k^K(v) \to \bar P_k(v) \\
    & \lim_{K\to\infty} \bar Q_\ell^K \to \bar Q_\ell \\
    & \lim_{K\to\infty} \bar X^K(v) \to \bar X(v).
\end{align*}
Hence, to show 
\begin{align*}
     \lim_{K\to\infty} \bigg( &\, \l \int_0^1 J(v)\bar X^K (v)f(v)dv - c \sum_{k=1}^K k[\bar P^K_{k+1}(0)-\bar P^K_k(0)] - d \sum_{\ell=1}^K \ell [\bar Q^K_\ell - \bar Q^K_{\ell+1}] \bigg) \\
     = &\, \l \int_0^1 J(v)\bar X (v)f(v)dv - c \sum_{k=1}^\infty k[\bar P_{k+1}(0)-\bar P_k(0)] - d \sum_{\ell=1}^\infty \ell [\bar Q_\ell - \bar Q_{\ell+1}].
\end{align*}
we just need to justify the passage of the limit under the integral and the summations. Since $\bar X^K(v) \leq 1$ for every $v$ and $K$, the first term converges by the Lebesgue Dominated Convergence Theorem. To show convergence of the second term, first note that the summation is unchanged if we sum up to $k=\infty$ rather than $k=K$:
\begin{align}
    c \sum_{k=1}^K k[\bar P^K_{k+1}(0)-\bar P^K_k(0)] = c \sum_{k=1}^\infty k[\bar P^K_{k+1}(0)-\bar P^K_k(0)]. \notag
\end{align}
Also, for each $k$ and $K$, we have
\begin{align*}
    &\, k[\bar P^K_{k+1}(0)-\bar P^K_k(0)] \\
    \leq &\, k\left[\frac{\bar P_{k+1}(0)}{\bar P_{K+1}(0)}-\frac{\bar P_k(0)}{\bar P_{K+1}(0)}\right] \\
    \leq &\, \frac{1}{\min_{j\in\N} \{ \bar P_j(0) \mid P_j(0) > 0 \}}  k[\bar P_{k+1}(0) - \bar P_k(0)],
\end{align*}
where the first inequality holds with equality for $k \leq K$ and is possibly strict for $k \geq K+1$, and the second inequality holds because $\bar P_k(v)$ is non-decreasing in $k$.
Moreover, since the solution $(\bar P^K,\bar Q^K,\bar y^K,\bar z^K, \bar X^K)$ gives the seller a positive payoff $\mathcal{V} > \lim_{K,L\to \infty} \text{val}(\mathcal P_{K
,L}) \geq 0$, it must be that
\begin{align}
    \frac{1}{\min_{j\in\N} \{ \bar P_j(0) \mid P_j(0) > 0 \}} \sum_{k=1}^\infty k[\bar P_{k+1}(0) - \bar P_k(0)] < \infty, \notag
\end{align}
as otherwise the value of the objective function would be $-\infty$.
Therefore, by the Lebesgue Dominated Convergence Theorem for an infinite series, the second term also converges. Likewise, the third term converges because
\begin{align}
    \ell[\bar Q^K_\ell - \bar Q^K_{\ell+1}]
    \leq \frac{\ell[\bar Q_\ell - \bar Q_{\ell+1}]}{ 1 - \bar Q_{K+1}}
    \leq \frac{\ell[\bar Q_\ell - \bar Q_{\ell+1}]}{ 1 - \min_{j\in\N} \{\bar Q_j \mid 1-Q_j >0\}}. \notag
\end{align}
\end{proof}

\subsection{Service Scenario ($d=\infty$)} \label{subsec:service-scenario}

When $d=\infty$, the primal and dual variables for goods storage all collapse. That is, we have $Q_\ell = 0$, $\g_\ell = 0$ and $\hat v_{-\ell} = J^{-1}(0)$ for all $\ell \in \{1,\ldots,L\}$. In particular, because $\g_1=0$, we obtain an iterative characterization of the positive thresholds $\hat v_k$'s presented in \cref{thm:relaxed-program}, and there is no need to appeal to intermediate value theorems as we did in \cref{subsec:IVT}.


\section{Proof of \cref{thm:optimal-policy} and \cref{thm:optimal-policy-storable}}
\label{sec:appendix-proof-of-thm:optimal-policy}

We provide a proof for \cref{thm:optimal-policy-storable}; the proof of \cref{thm:optimal-policy} follows if one sets $d=\infty$. 
To prove the theorem, we first show that the distributions $P^*$ and $Q^*$ are stationary under the assignment and queue management rule $M^*$. We then show that $M^*$, $P^*$, and $Q^*$ induce $y^*$, $z^*$, and $X^*$. 
Finally, we show that $(M^*,t^*,\iota^*)$ is incentive compatible at $(P^*, Q^*, y^*, z^*, X^*)$.

\paragraph*{Stationarity of $P^*$ and $Q^*$.}
Since the empty state $\mathbf 0$ is positive recurrent under $M^*$, the Markov policy $(M^*,t^*,\iota^*)$ clearly admits a joint stationary distribution.
Let us suppose that $P_k^*(v)$ is the probability that the state is in set $S_k(v)$, and show that this probability remains stationary under the Markov policy $M^{*}$. For $k>K^*$, we have $P^*_k(v)=1$ for all $v$. Suppose $k \leq K^*$.
For $v \geq \hat v_k$, the (actual) outflow from $S_k(v)$ is 
$$ \l[1-F(v)] (P^*_k(v) - P^*_{k-1}(v)),  $$
while the (actual) inflow is
$$ \m (P^*_{k+1}(v) - P^*_k(v)). $$
Since we chose $P^*$ so that the balance inequality $B_k$ binds for $v \geq \hat v_k$, the above two expressions are equal.



For any $v < \hat v_k$, we have $S_k(v) = S_k(0)$ under the policy $M^{*}$, since there cannot be a $k$-th highest buyer in the queue with value strictly below $\hat v_k$. Also, we have
$$ S_k(\hat v_k) = S_k(0) \sqcup \{ \bv : v_k = \hat v_k\}, $$
where $\sqcup$ denotes the disjoint union. 
Under the optimal policy, an outflow occurs from $S_k(0)$ if and only if there are exactly $k-1$ buyers whose values are \textit{weakly} above $\hat v_k$, and a new buyer arrives with value \textit{weakly} above $\hat v_k$. Because we chose each $P^*_k(v)$ to be continuous, and the distribution $F$ of arriving buyer's type is continuous, this outflow is 
$$ \l[1-F(\hat v_k)] (P^*_k(\hat v_k) - P^*_{k-1}(\hat v_k)),  $$
which is equal to the outflow from $S_k(\hat v_k)$. Under the optimal policy, an inflow into $S_k(0)$ occurs if and only if there are exactly $k$ buyers whose values are \textit{weakly} above $\hat v_k$, and an item arrives. Again, by the continuity of $P_k^*$, this inflow is
$$ \m (P^*_{k+1}(\hat v_k) - P^*_k(\hat v_k)),$$
which is equal to the inflow to $S_k(\hat v_k)$. Since inflow and outflow are equal for $S_k(\hat v_k)$, they must be equal for $S_k(0)$ as well. We have thus proved that $P^*_k(v)$ is stationary under the optimal policy.



Let us suppose that $Q_\ell^*$ is the probability that the state is in $S_{-\ell}$, and show that this probability remains stationary under the optimal policy. For $\ell > L^*$, $Q^*_\ell = 0$. For $\ell \leq L^*$, the outflow from $S_{-\ell}$ is
$$\l[1-F(\hat v_{-\ell})](Q^*_\ell - Q^*_{\ell+1}),$$
while the inflow is
$$ \m (Q^*_{\ell-1} - Q^*_\ell). $$
Since we chose $Q^*$ so that the balance inequality $B_{-\ell}$ binds for $\ell \leq L^*$, the above two expressions are equal.

\paragraph*{Inducing $y^*$ and $z^*$.}

When buyers are waiting, the policy $M^{*}$ always assigns an incoming good to the highest-valued buyer, so it clearly induces $y^*_k(v)=1$ for all $v$ and $k$. Also, when $\ell$ goods are stored, the policy assigns a good to an arriving buyer if and only if his value is above $\hat v_{-\ell}$, so $z_\ell^*(v)$ is induced as well.


\paragraph*{Inducing $X^*$.}
Let $\tilde X(v)$ denote the interim allocation probability for a type $v$-buyer that is induced by the policy $M^{*}$, under the stationary distribution $(P^*,Q^*)$. We wish to show that $\tilde X(v) = X^*(v)$ for all $v\in[0,1]$, where $X^*(v)$ is the solution to the relaxed program derived in \cref{subsubsec:choice-of-X}.

For $\ell \in \{1, \ldots, L\}$, let $X_{-\ell}(v)$ denote the interim allocation probability under the optimal policy of a type-$v$ buyer who just arrived, conditional on there being exactly $\ell$ goods stored. Then, we have
\begin{align*}
    X_{-\ell}(v) = \begin{cases}
        1 \caseif v \geq \hat v_{-\ell} \\
        0 \caseif v < \hat v_{-\ell}.
    \end{cases}
\end{align*}
Hence, for $v \leq \hat v_1$, we obtain $\tilde X(v)$ as follows:
\begin{align*}
    \tilde X(v) = \begin{cases}
        0 & \text{if } v< \hat v_{-L^*} \\
        Q_\ell & \text{if } v \in [\hat v_{-\ell}, \hat v_{-\ell+1}) \text{ for } \ell \in \{2,\ldots,L^*\}\\
        Q_1 \caseif v \in [\hat v_{-1}, \hat v_{1}),
    \end{cases}
\end{align*}
which coincides with $X^*(v)$.

For $k\in \{1,\ldots,K^*\}$, let $X_k(v)$ denote the interim allocation probability, under the optimal policy, of a type-$v$ buyer who just arrived, conditional on no goods being stored, and conditional on the arriving buyer being the $k$-th highest buyer were he to join the queue.
If $v < \hat v_1$, then $X_k(v)=0$ for any $k$.
Suppose the arriving buyer has value $v \in [\hat v_i, \hat v_{i+1})$, for $i\in \{1,\ldots,K^*\}$.\footnote{We define $\hat v_{k}\:=1$ for all $k \geq K^*+1$.} Clearly, $X_k(v) = 0$ for $k \geq i+1$, since the buyer will not be allowed to join the queue. When $k \leq i$, the buyer joins the queue. Once the buyer joins the queue, every time a good arrives, the buyer's ranking improves by 1, and every time a new buyer arrives with value greater than $v$, the buyer's ranking drops by 1. The buyer obtains the good if his ranking reaches 0, and the buyer leaves the queue if his ranking reaches $i+1$. Therefore, for $v \in [\hat v_i, \hat v_{i+1})$, the conditional interim allocation $X_k(v)$ can be derived as the solution to a gambler's ruin problem and is given by
\begin{align}
    X_k(v) = \begin{cases}
    \dfrac{k}{i+1} & \text{if } k \leq i \text{ and } \mu = \l[1-F(v)]\\
    \dfrac{\rho(v)^{i-k+1} - 1}{\rho(v)^{i+1}-1} & \text{if } k \leq i \text{ and } \mu\neq \l[1-F(v)]  \\
    0    & \text{if } k \geq i+1.
    \end{cases}\label{eq:X_k}
\end{align}
Suppose $\mu\neq \l[1-F(v)]$. Then, the (unconditional) interim allocation probability $\tilde X(v)$ for a buyer with value $v \in [\hat v_i, \hat v_{i+1})$, for $i \in \{1,\ldots,K^*\}$, is given by
\begin{align*}
    \tilde X(v) = &\, Q_1 + \sum_{k=1}^{K^*} [P_k(v) - P_{k-1}(v)] X_k(v) \\
    = &\, Q_1 + \sum_{k=1}^i \rho(v)^{k-1} \frac{P_{i+1}(0) - Q_1}{1+\rho(v) + \cdots + \rho(v)^i} \dfrac{\rho(v)^{i-k+1} - 1}{\rho(v)^{i+1}-1} \\
    = &\, Q_1 + (P_{i+1}(0) - Q_1) \frac{i(\rho(v)^{i+1}-\rho(v)^i) +1 - \rho(v)^i}{(1-\rho(v)^{i+1})^2}.
\end{align*} 
where the second equality uses \eqref{eq50}, \eqref{eq46}, and the definition of $X_k(v)$. On the other hand,
For $i\in \{1,\ldots,K\}$ and $v \in [\hat v_i,\hat v_{i+1})$, the solution to the relaxed program is
\begin{align*}
    X^*(v) &\, = \frac{\m}{\l f(v)} 
\frac{\dd P_1(v)}{\dd v} + Q_1 \\
&\, = \frac{1+2\rho(v) + 3\rho(v)^2 +\cdots + i\rho(v)^{i-1}}{(1+\rho(v) +\cdots+\rho(v)^i)^2} (P_{i+1}(0) - Q_1) + Q_1\\
    &\, = \tilde X(v).
\end{align*}
Likewise, when $\mu = \l[1-F(v)]$, we have
\begin{align*}
    \tilde X(v) = X^*(v) = \frac{i}{2(i+1)} (P_{i+1}(0) - Q_1) + Q_1.
\end{align*}


\paragraph*{Incentives.}
Finally, we check that the policy $M^{*}$ satisfies obedience and incentive compatibility of buyers. Obedience is clearly satisfied, since buyers are reimbursed for their ex post waiting cost, so they never benefit by leaving the queue against the recommendation of the optimal policy. To check incentive compatibility, it is enough to verify that $X^*$ is non-decreasing. This must be the case, since the optimal policy always assigns an arriving good to the highest buyer.

\section{Proof of \cref{prop:thresholds-compstat}}\label{sec:appendix-thresholds-compstat}

If $\hat v_1=1$, then $K^*=0$, and the proposition is vacuously true. If $\hat v_1<1$,
it is clear from \eqref{eq33} that $\hat v_1$ is strictly increasing in $c$, constant in $\l$, and strictly decreasing in $\mu$.

For each $k \in\{2,\ldots, K^*\}$, the threshold $\hat v_k$ satisfies $H_k(\hat v_{k-1}, \hat v_k)=0$, or
\begin{align*}
    \m \int_{\hat v_{k-1}}^{\hat v_k} \frac{1}{1+\rho(v) + \cdots + \rho(v)^{k-1}} J'(v) dv = c,
\end{align*}
where we recall that $\rho(v) \:= \l[1-F(v)]/\m$.
Clearly, each $\hat v_k$ is strictly increasing in $c$, strictly increasing in $\l$, and strictly decreasing in $\mu$.


\section{Proof of \cref{thm:DSIC}}


Call the specified strategy {\it truthful}. The observation preceding the theorem implies that following the truthful strategy guarantees a nonnegative payoff; whenever he wins, his cutoff price is weakly below his value.

Clearly, a deviation in (a) is weakly dominated. Consider next a survival auction in (c). Dropping out before the clock price reaches its value is weakly dominated by the truthful strategy, which guarantees a nonnegative payoff. Staying past one's value is also weakly dominated because whenever one wins, his cutoff price is at least the highest reserve price (or the stopped clock price).

To argue that a buyer cannot profitably deviate in an assignment auction (d), we first need to consider the possibility that a buyer's deviation may affect other buyers' future bids. Since buyers' bids are frozen after their first assignment auction, the only way for buyer $A$ to influence buyer $B$'s bids is by changing the final clock price of a survival auction that buyer $B$ participates in before participating in any assignment auction. Then, if buyer $B$ conditions his future bids on the final clock price of this survival auction, buyer $A$ can influence buyer $B$'s future bids. We show that this can never be profitable for buyer $A$.
Second, given that a buyer cannot profitably affect future bids of others, we show that a buyer cannot benefit by deviating.

\paragraph*{Overbidding in Assignment Auction.}
We first consider the case in which a buyer overbids in an assignment auction. If the buyer loses after overbidding, he would also have lost by bidding truthfully, so he is no better off. If overbidding leads the buyer to win in the same assignment auction as he would have had he bid truthfully, then this does not provide any information to other bidders, since it does not change the final clock price of future survival auctions. Hence, such overbidding does not change the future bids of other buyers. Then, the cutoff price must remain the same, so the buyer's payoffs does not change.

Now, suppose truthful bidding would have led the buyer to win eventually, but overbidding makes the buyer win earlier. This affects the final clock price of future survival auctions if and only if the clock price rises above the true value of the buyer. However, in this scenario, the buyer would have lost if he had bid truthfully, so his cutoff price from overbidding would be above his true value, and he would make a loss. Therefore, we may without loss consider scenarios in which future bids of other buyers do not change in response to the buyer overbidding. Then, taking as given the future bids, the buyer's cutoff price does not change from winning earlier. Therefore, the buyer does not benefit from overbidding to win earlier.

Finally, suppose truthful bidding would have led the buyer to leave the queue without being assigned, but overbidding makes the buyer win. Again, such a deviation affects future bids only when the clock price rises above the buyer's true value, in which case the buyer makes a loss. Holding future bids constant, the buyer's cutoff price must be above his true value, as bidding truthfully would have led him not to win. Therefore, the buyer makes a loss.

\paragraph*{Underbidding in Assignment Auction.} 

If the buyer loses after underbidding, he cannot be better off than bidding truthfully and obtaining a weakly positive payoff. If the buyer wins after underbidding, then he would also have won from bidding truthfully. If the buyer wins in the same assignment auction, then the future bids of other buyers does not change, so the buyer's cutoff price is the same.

It remains to consider the case in which underbidding makes the buyer win in a later assignment auction. The only scenario in which underbidding in an assignment auction may influence future bids is if, in a subsequent survival auction, the clock price rises above the buyer's under-reported value, and the buyer drops out. In this case, the buyer does not win, which contradicts the assumption that the buyer wins in a later assignment auction. Thus future bids remain unchanged. Then, the buyer's cutoff price must also remain unchanged, so the buyer does not benefit.



\section{Proofs for \cref{sec:large-market}}

\subsection{Proof of \cref{lemma:large-market-1}}

Fix any feasible Markovian policy $(M,t,\iota)$ on any $(m,n)$-sample path. The policy $(M,t,\iota)$ induces an ex-post allocation rule, meaning a function that specifies the allocation as a function of realized values for the $n$ buyers.  The allocation rule is monotonic, making it feasible in the Oracle benchmark.  The standard Myerson analysis shows the optimal expected revenue is $R^*(m,n)$.  Since the Oracle benchmark involves no waiting costs for buyers or holding costs for items, $R^*(m,n)\ge R_M(m,n)$.

\subsection{Proof of \cref{lemma:large-market-2}}

    Whenever $\l,\m\to \infty$ with $\rho=\l/\m$ held constant, the numbers of buyers and items arriving during a unit interval, $n$ and $m$, must go to $\infty$ with $n/m\to \rho$.  Hence, the result follows: 
\begin{align*}
    & \limsup_{\l,\m\to\infty, \l/\m=\rho} \sup_{M\in \mathcal M}\E_{n\sim \l,m\sim \m}[ R_M(m,n)/m ]\\
    \le &  \limsup_{n,m\to\infty, n/m=\rho} \sup_{M\in \mathcal M} R_M(m,n)/m 
 \\
 \le &  \lim_{n,m\to\infty, n/m=\rho} R^*(m,n)/m \\
    = & R^*.
\end{align*}

\subsection{Proof of \cref{thm:large-market}}

By the arguments following the theorem, (a) follows from either (b) or (c).

\paragraph*{Proof of (b).}

We consider the case of $\l,\m,d \to \infty$ with $\rho = \l/\m$ and $\l/d$ held constant; as previously discussed, this is equivalent to $c\to 0$ up to rescaling of time. The upper bound of $R^*$ obtained in \cref{lemma:large-market-2} still applies, since also sending $d \to \infty$ cannot increase revenue.
It thus suffices to show that there exists a feasible Markovian policy $(M,t,\iota)$ whose expected per-unit revenue converges to $R^*$. Consider the following simple Markovian policy:  For any  $\epsilon>0$, admit a buyer if and only if his valuation is above
$$\tilde v_{\delta} \:= \max\{\tilde v, \hat  v_0\}+\delta,$$
where $\delta>0$ is chosen so that $R^*-\rho\tilde v_{\delta}[1-F(\tilde v_{\delta})]<\epsilon$.  
If a good arrives, it is discarded if there are no buyers in the queue; otherwise,  it is allocated to a randomly chosen buyer in the queue at price  $\tilde v_{\delta}$; the seller reimburses buyers for their waiting costs.  Under this policy, all buyers with valuations above $\tilde v_{\delta}$ are eventually allocated the good.  

The expected per-unit  revenue for the seller is then
$$\frac{\l}{\m}\tilde v_{\delta}[1-F(\tilde v_{\delta})]$$
minus the per-unit expected waiting time, or the total waiting time divided by the number of items.  We show that the latter vanishes in the limit.

\begin{lem}  The per-unit expected waiting time vanishes in the limit as $\l, \m\to \infty$ with $\rho=\l/\m$ held constant. 
\end{lem}

\begin{proof} Observe $$\rho_{\delta}:=\rho [1-F(\tilde v_{\delta})]<1.$$ 
Let $p_k$ denote the stationary probability that the queue has length $k=0, ..., \infty$. For each $k=0,...$,
we must have 
$$\lambda [1-F(\tilde v_{\delta})] p_k= \mu p_{k+1},$$
so  
$p_{k}=\frac{\rho^{k}_{\delta}}{%
\sum_{k=0}^{\infty} \rho^{k}_{\delta}}.$
Since $\rho_{\delta} <1$,
the average length of the queue 
\begin{eqnarray*}
\sum_{k=0}^{\infty} kp_{k} &=&\sum_{k=0}^{\infty}k  \frac{\rho^{k}_{\delta}}{%
\sum_{k=0}^{\infty} \rho^{k}_{\delta}} = \frac{\rho_{\delta}}{1-\rho_{\delta}}
\end{eqnarray*}%
is finite.  Since the effective arrival rate 
$$\lambda [1-F(\tilde v_{\delta})]$$ 
tends to infinity, by Little's law, the per-capita expected waiting time vanishes as $\l\to \infty$.  This means the per-unit expected waiting time (obtained by multiplying $\rho_{\delta}$) also vanishes in the limit. 
\end{proof}

Combining the preceding observations, we conclude that the limit expected (per-unit) revenue from the simple Markovian policy is no less than  
$R^*-\epsilon$. Therefore, the same conclusion applies to our optimal Markovian policy.

\paragraph*{Proof of (c).}

Analogously to the proof of (b), we will consider the case $\l,\m,c \to \infty$ with $\rho = \l/\m$ and $\l/c$ held constant. Our goal is to show that there exists a feasible Markovian policy $(M,t,\iota)$ whose expected per-unit revenue converges to $R^*$. Consider the following simple Markovian policy.  If a buyer arrives, he is turned away if there are no items stored; otherwise, for $\epsilon>0$, the buyer is allocated an item at a posted price of
$$\tilde v_{\delta} =\max\{\tilde v, \hat  v_0\}+\delta,$$
where $\delta>0$ is chosen so that $R^*-\rho\tilde v_{\delta}[1-F(\tilde v_{\delta})]<\epsilon$. 
Arriving goods are stored up to a cap of at most $\bar L \:= \left[ \sqrt{\mu} \right] $ in inventory.
Under this policy, the expected per-unit storage time is at most $\frac{\sqrt{\mu}}{\mu}$, which tends to 0 as $\mu \to \infty$.

Let $q_\ell$ denote the stationary probability under this policy that there are $\ell$ items in storage. For each $\ell  = 0,\ldots,\bar L-1$, we must have
\begin{align*}
    \mu q_\ell = \l[1-F(v_\d)]q_{\ell+1}.
\end{align*}
Therefore, the probability that the storage is empty is
$$q_0 = \frac{1}{1+\phi_\d + \cdots + \phi_{\d}^{\bar L}},$$
where
$$ \phi_{\d} \:= \frac{1}{\rho[1-F(\tilde v_\d)]} = \frac{1}{\rho_{\d}}.$$
Since $\phi_\d >1$, it must be that $q_0$ tends to 0 as $\bar L \to \infty$.
Therefore, buyers with valuations above $\tilde v_{\delta}$ are always allocated a good in the limit.

Combining the preceding observations, we conclude that the limit expected (per-unit) revenue from the simple Markovian policy is 
$$\frac{\l}{\m}\tilde v_{\delta}[1-F(\tilde v_{\delta})] > R^* - \epsilon.$$
Therefore, the same conclusion applies to our optimal Markovian policy.

\section{Proof of \cref{prop:comp-stat-in-pareto-weight}} \label{sec:appendix-proof-of-comp-stat-in-pareto-weight}

It is enough to show that if $w > \tilde w$ and $\hat v_k^w > \hat v_k^{\tilde w}$ for some $k \leq \min\{K_{\tilde w}, K_w\}-1$, then $\hat v_{k+1}^w > \hat v_{k+1}^{\tilde w}$. 
Assume for the sake of contradiction that $\hat v_k^w > \hat v_k^{\tilde w}$ and $\hat v_{k+1}^w \leq \hat v_{k+1}^{\tilde w}$ for some $k$. The thresholds must satisfy $H_{k+1}(\hat v^w_{k},\hat v_{k+1}^w) =0$ and $H_{k+1}(\hat v^{\tilde w}_{k},\hat v_{k+1}^{\tilde w}) =0$, which means
\begin{align}
    \m \int_{\hat v_{k}^w}^{\hat v^w_{k+1}} \frac{1}{1+\rho(v) + \cdots + \rho(v)^{k}} J'_w(v) dv = c \label{eq52} \\
    \m \int_{\hat v_{k}^{\tilde w}}^{\hat v^{\tilde w}_{k+1}} \frac{1}{1+\rho(v) + \cdots + \rho(v)^{k}} J'_{\tilde w}(v) dv = c.\label{eq53}
\end{align}
Because the inverse hazard rate is non-increasing, it must be that $J'_{\tilde w}(\cdot) \geq J'_w(\cdot) \geq 1$. Since we assumed that $\hat v_k^w > \hat v_k^{\tilde w}$ and $\hat v_{k+1}^w \leq \hat v_{k+1}^{\tilde w}$, the LHS of \eqref{eq53} must be strictly greater than the LHS of \eqref{eq52}, a contradiction.





