The equivalence relations on any set $W$ form a general (i.e.~not necessarily distributive) complete lattice $E(W)$ \cite{birkhoff1940lattice}. Lattices $E(W)$ serve as the algebraic environment  of interrogative agendas, as discussed in the next section. %and deliberation and/or decision-making scenarios involving them. 

\subsection{Equivalence relations, partitions and preorders}\label{interrogative:ssec:equivalence relations and preorders}
An {\em equivalence relation} over a set $W$ is a binary relation $e\subseteq W\times W$ which is {\em reflexive} (i.e.~$(w,w)\in e$ for every $w\in W$), {\em symmetric} (i.e.~for all $w, u\in W$, if $(w, u)\in e$ then $(u, w)\in e$) and {\em transitive} (i.e.~for all $w, u, v\in W$, if $(w, u)\in e$ and $(u, v)\in e$ then $(w, v)\in e$). For any $w\in W$, we let $[w]_e: = \{u\in W\mid (w, u)\in e\}$. A partition  of $W$ is a collection $\mathcal{E}\subseteq \mathcal{P}(W)\setminus \{\varnothing\}$ such that $\bigcup \mathcal{E} = W$ and the elements of $\mathcal{E}$ are pairwise disjoint.  Each equivalence relation $e$ on $W$ gives rise to the partition  $\mathcal{E}_e: = \{[w]_e\mid w\in W\}$; conversely, every partition $\mathcal{E}$ on $W$ gives rise to the equivalence relation $e_{\mathcal{E}}$ such that if $u, v\in W$, then $(u, v)\in e_{\mathcal{E}}$ iff $u\in C$ and $v\in C$ for some $C\in \mathcal{E}$. Clearly, for every $e$ and $\mathcal{E}$,
\[e = e_{\mathcal{E}_e}\quad \mbox{ and }\quad \mathcal{E} = \mathcal{E}_{e_{\mathcal{E}}},\]
so that  equivalence relations and partitions can be identified.

    A {\em preorder} over a set $W$  is a reflexive and transitive binary relation ${\leq} \subseteq W \times W$. Every pre-order  $\leq$ on $W$ gives rise to an equivalence relation $e_\leq$ on $W$ defined as   $w_1 e_\leq w_2$ iff $w_1 \leq w_2$ and $w_2 \leq w$. Conversely, any equivalence relation $e$ on a preordered set $(W, \leq)$ gives rise to  a preorder $\leq_e$ on $W$ defined as follows:  $w \leq_e u$ iff for all $w'\in [w]_e$ some $u' \in [u]_e$ exists such that $w' \leq u'$. That is, $w \leq_e u$ iff for any $w'$ which is $e$-equivalent to $w$,   some  $u'$ exists which is $e$-equivalent to $u$ and  $w' \leq u'$. 

    If $e$ and $\leq$ are an equivalence relation and a pre-order on $W$, then $e$ is  {\em compatible with}   $\leq$ if  $e\, \circ \leq \circ\, e\subseteq {\leq}$, where $\circ$ denotes the operation of relational composition, and is {\em strongly compatible with} $\leq$ if $e$ is  compatible with $\leq$ and  $e_\leq \subseteq e$.  The reflexivity of $e$ implies that if $e$ is  compatible with   $\leq$, then  $e\, \circ \leq \circ\, e = {\leq}$.  By definition, if $\leq$ is a preorder, then $e_\leq$ is strongly compatible with $\leq$.




    %If $e$ and $\leq$ are an equivalence relation and a pre-order on $W$, then $e$ is  %{\em semi-compatible with}   $\leq$ if  $e\, \circ \leq \circ\, e\subseteq {\leq}$, where $\circ$ denotes the operation of relational composition, and is  

%for any $w \leq u$ and  $w e w'$ and $u e u'$, we have $w' \leq u'$, 



\begin{lemma}\label{interrogative:lem:preorder-equivalence back-forth}
For any  preorder  $\leq$ on $W$,
\begin{enumerate}
    \item  $\leq_{e_\leq} = {\leq}$.
    \item For   any equivalence relation $e$, if $e$ is strongly compatible with $\leq$, then $e_{\leq_e}=e$. 
\end{enumerate}
\end{lemma}
\begin{proof}
1. By definition,  $w \leq_{e_\leq} u$ iff for every $w' \in W$, if $(w',w)\in e_\leq$ then $w' \leq u'$ for some $u'\in W$ s.t.~$(u',u)\in e_\leq$. Hence, by instantiating $w':=w$, $w \leq u'$ for some $u'\in W$ s.t.~$(u',u)\in e_\leq$. By definition,  $(u,u')\in  e_\leq $ implies $u' \leq u$. Therefore, as $\leq$ is transitive, $w \leq u$, as required.

Conversely, let $w, w', u\in W$ s.t.~$w  \leq  u$ and $(w, w')\in  e_\leq$. By definition, $(w, w')\in  e_\leq$ implies $w' \leq w$.  Therefore, since $\leq$ is transitive, $w' \leq u$. Hence, for every such $w'$, choosing $u':=u$  ensures that $w' \leq u'$, which proves  $w \leq_{e_\leq} u$, as required. 

2. By definition, $(w, u)\in e_{\leq_e}$ iff $w\leq_e u$ and $u\leq_e w$. If $w, w', u\in W$ s.t.~$(w, u)\in  e$ and $(w', w)\in e$, then $(w', w)\in e$, $w \leq w$, and $(w, u)\in e$ imply $w' \leq u$  by the  assumption that $e$ is compatible with $\leq$. Hence, for every such $w'$, choosing $u':=u$  ensures that $w' \leq u'$, which proves  $w \leq_{e} u$.  By symmetry, $(w, u)\in  e$ implies $(u, w)\in  e$, which implies $u \leq_e w$ by analogous reasoning. Therefore, $(w, u)\in e_{\leq_e}$, as required.

Conversely, if $(w, u)\in e_{\leq_e}$, then, by definition, $w \leq_e u$ and $u \leq_e w$. By instantiating $w':=w$ in its defining clause,  $w \leq_e u$ implies $w \leq u'$ for some $u'\in W$ s.t.~$(u, u')\in e $, which implies  $w \leq u$, since $e\, \circ \leq \circ\, e\subseteq {\leq}$ by assumption. Similarly, one shows that $u \leq_e w$ implies $u \leq w$, which shows that $(w, u)\in e_\leq \subseteq e$, as required.  
\end{proof}

   \begin{definition}
    \label{interrogative:def:e prefers}
%When the set $W$ is the space of profiles about which a decision is to be made, and  an equivalence relation $e$ on $W$ represents an interrogative agenda, 
For every $w, u\in W$,  $e$ {\em prefers $u$ over $w$} iff $w\leq_e u$ and $u\not\leq_e w$.
\end{definition}

\subsection{Algebras of equivalence relations}\label{interrogative:ssec:Algebra of equivalence relations}

 For every set $W$, let $E(W)\subseteq\mathcal{P}(W\times W)$  denote the subposet of the equivalence relations on $W$ ordered by inclusion. This subposet is in fact a complete $\bigcap$-subsemilattice of $\mathcal{P}(W\times W)$, and hence is a complete lattice the top element of which is $\tau: = W\times W$, the bottom element is $\epsilon: = \Delta = \{(w, w)\mid w\in W\}$, and moreover for any $\mathcal{X}\subseteq E(W)$,
\[ \bigsqcap_{E(W)}\mathcal{X}: = \bigcap\mathcal{X}\quad \mbox{ and }\quad \bigsqcup_{E(W)}\mathcal{X}: = \mathsf{RST}(\bigcup\mathcal{X}),\]
where $\mathsf{RST}(R): = \bigcup_{n\in \omega} (R^{-1}\cup R)^{n}$ denotes the reflexive, symmetric and transitive closure\footnote{We let $R^{-1}: = \{(u, w)\in W\times W\mid (w, u)\in R\}$, and for every $n\in \mathbb{N}$,    $R^0: = \Delta$ and $R^{n+1}: = R^n\circ R$, where $S\circ T: = \{(w, v)\mid (w, u)\in S \mbox{ and } (u, v)\in T \mbox{ for some } u\in W\}$ for all $S, T\in\mathcal{P}(W\times W)$.} of any $R\in \mathcal{P}(W\times W)$.
Finite meets and joins in $E(W)$ are more easily visualized when we switch to partitions. Indeed, if $e_1$ and $e_2$ are represented as the partitions on the left-hand side of the picture below, then $e_1\sqcap e_2$ is represented by the partition obtained by {\em superposing} the lines of $e_1$ and $e_2$ (more formally, the partition capturing $e_1\sqcap e_2$ is $\{[w]_{e_1}\cap [w]_{e_2}\mid w\in W \}$), while  $e_1\sqcup e_2$ is represented as the partition obtained by {\em erasing}   the lines that $e_1$ and $e_2$ do not share (in other words, the partition capturing $e_1\sqcup e_2$ is the one obtained by taking the union of overlapping cells of the two partitions).
