\subsection{Proof of Lemma \ref{Gradient_Lipschitz}} In proving this lemma we use the fact  that  $$\varphi(\boldsymbol{\theta})=\EE\left[\max_{j\in A}\{\boldsymbol{\theta}_{j}+\eta\epsilon_j\}\right]=\eta\EE\left[\max_{j\in A}\{\boldsymbol{\theta}_{j}/\eta+\epsilon_j\}\right]=\eta\varphi(\boldsymbol{\theta}/\eta).$$ 
Thus, it is easy to see that 
$\nabla\varphi(\boldsymbol{\theta})=\nabla\varphi(\boldsymbol{\theta}/\eta)$. In addition, simple algebra shows that  ${\partial^2\varphi(\boldsymbol{\theta})\over \partial \boldsymbol{\theta}_j\partial \boldsymbol{\theta}_i}={1\over \eta }{\partial^2\varphi(\boldsymbol{\theta}/\eta)\over \partial \boldsymbol{\theta}_j\partial \boldsymbol{\theta}_i},$ for all $i,j=1,\ldots, N.$ Under this equivalence we note that 
the condition in Assumption \ref{Gradient_LL} can be rewritten as $2Tr(\varphi(\boldsymbol{\theta}/\eta))\leq L$.
\smallskip

Define the function $f(t)=\nabla\varphi(\boldsymbol{\theta}_1/\eta+t(\boldsymbol{\theta}_2/\eta-\boldsymbol{\theta}_1/\eta))$  with $f^\prime(t)=\langle\nabla^2\varphi(\boldsymbol{\theta}_1/\eta+t(\boldsymbol{\theta}_2/\eta-\boldsymbol{\theta}_1/\eta)),\boldsymbol{\theta}_2/\eta-
\boldsymbol{\theta}_1/\eta\rangle$. Noticing that 
\begin{eqnarray}
\nabla\varphi(\boldsymbol{\theta}_2/\eta)-\nabla\varphi(\boldsymbol{\theta}_1/\eta)=f(1)-f(0)&=&\int_{0}^1f^\prime(t)dt\nonumber\\
&=&\int_{0}^1\nabla^2\varphi(\boldsymbol{\theta}_1/\eta+t(\boldsymbol{\theta}_2/\eta-\boldsymbol{\theta}_1/\eta))(\boldsymbol{\theta}_2/\eta-\boldsymbol{\theta}_1/\eta)dt.\nonumber\\
\|\nabla\varphi(\boldsymbol{\theta}_2/\eta)-\nabla\varphi(\boldsymbol{\theta}_1/\eta)\|_1&\leq& \int_{0}^1\|\nabla^2\varphi(\boldsymbol{\theta}_1/\eta+t(\boldsymbol{\theta}_2/\eta-\boldsymbol{\theta}_1/\eta))(\boldsymbol{\theta}_2/\eta-
\boldsymbol{\theta}_1/\eta)\|_1dt\nonumber\\
&\leq &\int_{0}^1\|\nabla^2\varphi(\boldsymbol{\theta}_1/\eta+t(\boldsymbol{\theta}_2/\eta-\boldsymbol{\theta}_1/\eta))\|_{\infty,1}\|\boldsymbol{\theta}_2/\eta-\boldsymbol{\theta}_1/\eta\|_1\nonumber
\end{eqnarray}

To complete the proof we stress two properties of the Hessian. First, each row (or columns) of $\nabla^2\varphi(\boldsymbol{\theta}_t/\eta)$ sums up to $0$. To see this we note that $\sum_{i=1}^N\nabla_i\varphi(\boldsymbol{\theta}_t/\eta)=1$. Then simple differentiation yields $\sum_{j=1}^N{1\over \eta}\nabla_{ij}\varphi(\boldsymbol{\theta}_t/\eta)=0$ for all $i=1,\ldots, N.$ Second,  it is well known that  the off-diagonal elements of ${1\over \eta}\nabla^2\varphi(\boldsymbol{\theta}_t/\eta)$ are nonnegative (\citet[Ch. 5]{mcf1}). To see why this is true, we recall that for alternative $i$ the choice probability is given by: $\nabla_i\varphi(\boldsymbol{\theta}_t/\eta)=\PP(i=\arg\max_{j\in A}\{\boldsymbol{\theta}_{jt}+\eta\epsilon_{jt}\})$. Then increasing the terms $\boldsymbol{\theta}_{jt}$ for $j\neq i$  cannot increase the probability of choosing $i$, which is formalized as ${1\over \eta}\nabla_{ij}\varphi(\boldsymbol{\theta}_t/\eta)\leq 0$.

Now, using previous observation, we have that for a convex combination  $\tilde{\boldsymbol{\theta}}/ \eta=\boldsymbol{\theta}_1/ \eta+t(\boldsymbol{\theta}_2/ \eta-\boldsymbol{\theta}_1/ \eta)$ we have
\begin{eqnarray}
{1\over \eta}\|\nabla^2\varphi(\tilde{\boldsymbol{\theta}}/\eta)\|_{\infty,1}&=&{1\over \eta}\max_{\|\bold{v}\|\leq 1}\{\|\nabla^2\varphi(\tilde{\boldsymbol{\theta}}/\eta)\bold{v}\|_1\}\nonumber\\
&\leq& {1\over \eta}\sum_{i=1}^N\sum_{j=1}^N|\nabla_{ij}^2\varphi(\tilde{\boldsymbol{\theta}})|\nonumber\\
&=& {1\over \eta}2Tr(\nabla^2\varphi(\tilde{\boldsymbol{\theta}}))\leq {L\over \eta},\nonumber
\end{eqnarray}
where the last inequality follows from Assumption \ref{Gradient_LL}. 
Plugging  in, we arrive to the conclusion
$$\|\nabla\varphi(\boldsymbol{\theta}_2/\eta)-\nabla\varphi(\boldsymbol{\theta}_1/\eta)\|_1\leq {L }\|\boldsymbol{\theta}_2/\eta-\boldsymbol{\theta}_1/\eta\|_1\quad\forall \boldsymbol{\theta}_1,\boldsymbol{\theta}_2.$$

Finally, using the fact $\nabla\varphi(\boldsymbol{\theta})=\nabla\varphi(\boldsymbol{\theta}/\eta)$
we get
$$\|\nabla\varphi(\boldsymbol{\theta}_2)-\nabla\varphi(\boldsymbol{\theta}_1)\|_1\leq {L\over \eta }\|\boldsymbol{\theta}_2-\boldsymbol{\theta}_1\|_1\quad\forall \boldsymbol{\theta}_1,\boldsymbol{\theta}_2.$$
\eproof
\begin{lemma}\label{Positive_R_Bound_D}Let Assumption \ref{Shocks_Assumption} hold. Then	$\mathcal{R}(\bold{x})\leq 0$ for all $\bold{x}\in \Delta_N$.

\end{lemma}
\proof  First, we note that the Fenchel equality implies $\mathcal{R}(\bold{x})=\langle \boldsymbol{\theta},
\bold{x}\rangle-\varphi(\boldsymbol{\theta})=\langle \boldsymbol{\theta},
