\begin{lemma}\label{Bound_Regret_FTRL}Let Assumptions \ref{Shocks_Assumption} and \ref{Gradient_LL} hold. Then in the SSA 
	\begin{equation}\label{FRTL_Bounded}
	\textsc{R}_{SSA}^T\leq \eta\varphi(\bold{0})+{L\over 2\eta}Tu^2_{max}.
	\end{equation}
\end{lemma}
\proof The proof of this lemma exploits the convex duality structure of the RUM-ODP model. 
%\citet[Lemma 2.20]{Shalev-Shwartz2012}.
By the Fenchel-Young inequality we know that 

$$\forall\bold{x}\in\Delta_N:\quad\mathcal{R}(\bold{x})\geq \langle\boldsymbol{\theta}_T,\bold{x}\rangle-\varphi(\boldsymbol{\theta}_T),$$
where the equality holds when $\bold{x}$ maximizes $\langle\boldsymbol{\theta}_T,\bold{x}\rangle-\mathcal{R}(\bold{x})$.

The Fenchel-Young inequality implies
$$\mathcal{R}(\bold{x})-\langle\boldsymbol{\theta}_T,\bold{x}\rangle\geq -\varphi(\boldsymbol{\theta}_T).$$

Noting that $-\varphi(\boldsymbol{\theta}_T)$ can be equivalently expressed as:
$$-\varphi(\boldsymbol{\theta}_T)=-\varphi(\boldsymbol{\bold{0}})-\sum_{t=1}^T\left(\varphi(\boldsymbol{\theta}_{t})-\varphi(\boldsymbol{\theta}_{t-1})\right).$$

From the definition of Bregman divergence combined with  $\bold{x}_t=\nabla\varphi(\boldsymbol{\theta}_{t-1})$, it follows that 
$$\sum_{t=1}^T\left(\varphi(\boldsymbol{\theta}_{t})-\varphi(\boldsymbol{\theta}_{t-1})\right)=\sum_{t=1}^T\left(D_\varphi(\boldsymbol{\theta}_t||\boldsymbol{\theta}_{t-1})-\langle\bold{u}_t,\bold{x}_t\rangle\right).$$

Thus, it follows that 
$$\mathcal{R}(\bold{x})-\langle\boldsymbol{\theta}_T,\bold{x}\rangle\geq -\eta\varphi(\bold{0})-\sum_{t=1}^T\left(D_\varphi(\boldsymbol{\theta}_t||\boldsymbol{\theta}_{t-1})-\langle\bold{u}_t,\bold{x}_t\rangle\right).$$

Combining Lemmas \ref{Positive_R_Bound_D} and \ref{Bregman_Bound}, the previous inequality can be rewritten as
$$\sum_{t=1}^T\langle\bold{x}-\bold{x}_t,\bold{u}_t\rangle\leq \mathcal{R}(\bold{x})+\eta\varphi(\bold{0})+\sum_{t=1}^TD_\varphi(\boldsymbol{\theta}_t||\boldsymbol{\theta}_{t-1})\leq \eta\varphi(\bold{0})+{L\over 2\eta}Tu^2_{max}.$$

Because the previous inequality holds for all $\bold{x}\in \Delta_N$ we conclude:
$$\textsc{R}_{SSA}^T\leq \eta\varphi(\bold{0})+{L\over2\eta}Tu^2_{max}.$$
\eproof
\subsection{Proof of Theorem \ref{SS_Surplus_algorithm_regret}} The bound (\ref{Bound1}) follows from Lemma \ref{Bound_Regret_FTRL}. To derive Eq. (\ref{Bound2}), define the function $\psi(\eta)=\eta\varphi(\bold{0})+\frac{L}{2\eta}Tu^2_{max}$. Given the strict convexity of $\psi(\eta)$, the first order conditions are necessary and sufficient for  a minimum. In particular, we get $$\psi^\prime(\eta)=\varphi(\bold{0})-\frac{L}{2\eta^2}Tu^2_{max}=0$$
The optimal $\eta$ is given by $\eta^*=\sqrt{{LTu^2_{max}\over2\varphi(\bold{0})}}$. Then, it follows that $\psi(\eta^*)=u_{max}\sqrt{2\varphi(\bold{0})LT}$. Thus  we conclude that




$$\textsc{R}_{SSA}^T\leq \psi(\eta^*)=2u_{max}\sqrt{\varphi(\bold{0})LT}.$$\eproof
