\begin{lemma}\label{GNL_regret_lemma} In the GNL model the following statements hold:
	\begin{itemize}
		\item[i)] The Social Surplus function has a Lipschitz continuous gradient with constant  $({2\over \min_{k}\lambda_k}-1)/\eta.$
		\item[ii)] $\log G(\bold{1})=\log \sum_{k=1}^K\left(\sum_{i=1}^N\alpha^{1/\lambda_k}_{ik} \right)^{\lambda_k}\leq \log N,$
	\end{itemize} 

\end{lemma}
\proof i) This follows from a direct application of  \citet[Cor. 4]{Nesterovetal2019}. ii) To prove this, we first show that  for $\lambda_k<\lambda_k^\prime$ we have:

$$\left(\sum_{i=1}^N\alpha^{1/\lambda_k}_{ik} \right)^{\lambda_k}\leq \left(\sum_{i=1}^N\alpha^{1/\lambda^\prime_k}_{ik} \right)^{\lambda^\prime_k}\quad\mbox{for $k=1,\ldots,K.$}$$
Let $p_k={1\over \lambda_k}$ and $p_{k^\prime}={1\over \lambda_{k^\prime}}$, noting that $p^\prime_k<p_k$ whenever $\lambda_k<\lambda_k^\prime$. Using this change of variable, we can write the following ratio

\begin{eqnarray}
{\left(\sum_{i=1}^N\alpha^{p_k}_{ik} \right)^{1/p_k}\over \left(\sum_{j=1}^N\alpha^{p^\prime_k}_{jk} \right)^{1/p^\prime_k}}&=& \left({\sum_{i=1}^N\alpha^{p_k}_{ik} \over \left(\sum_{j=1}^N\alpha^{p^\prime_k}_{jk} \right)^{p_k/p^\prime_k}}\right)^{1/p_k}\nonumber \\
&=& \left(\sum_{i=1}^N\left({\alpha^{p^\prime_k}_{ik} \over \sum_{j=1}^N\alpha^{p^\prime_k}_{jk}}\right)^{p_k/p_k^\prime}\right)^{1/p_k}\nonumber\\
&\leq& \left(\sum_{i=1}^N\left({\alpha^{p^\prime_k}_{ik} \over \sum_{j=1}^N\alpha^{p^\prime_k}_{jk}}\right)\right)^{1/p_k}=1.\nonumber
\end{eqnarray}
The last inequality implies that 
$$\left(\sum_{i=1}^N\alpha^{1/\lambda_k}_{ik} \right)^{\lambda_k}\leq \left(\sum_{i=1}^N\alpha^{1/\lambda^\prime_k}_{ik} \right)^{\lambda^\prime_k}\quad\mbox{for $k=1,\ldots,K.$}$$
Then for $\lambda_k=1$ for $k=1,\ldots, K$, we get
$$\log \sum_{k=1}^K\left(\sum_{i=1}^N\alpha^{1/\lambda_k}_{ik} \right)^{\lambda_k}\leq \log \sum_{k=1}^K\sum_{i=1}^N\alpha_{ik}=\log N.$$
\eproof
