\subsection{Proof of Proposition \ref{R_smooth}}
i) From the definition of $\mathcal{R}(\bold{x})$ we know that $\mathcal{R}(\bold{x})=\eta\varphi^\ast(\bold{x};\eta)$
where $\varphi^\ast(\bold{x};\eta)$ is the convex conjugate of  the parametrized social surplus function $\varphi(\boldsymbol{\theta}/\eta)$. By Lemma \ref{Gradient_Lipschitz}  it follows  that $\varphi(\boldsymbol{\theta}/\eta)$ is $L$-Lipschitz continuous.  Applying  Lemma \ref{Baillon_Haddad} it follows that $\varphi^\ast(\bold{x};\eta)$ is $1/L$ strongly convex. Then it follows that $\mathcal{R}(\bold{x})$ is ${\eta\over L}$-strongly convex. \\
ii) This is a direct implication of Lemma \ref{Convexity_smoothness}.\\
iii) It is easy to see that $ \langle \boldsymbol{\theta},\bold{x}\rangle-\mathcal{R}(\bold{x})$ is a  ${\eta\over L}$-strongly concave function on $\Delta_N$. This implies that  the optimization problem $\max_{\bold{x}\in \Delta_N}\{\langle \boldsymbol{\theta},\bold{x}\rangle-\mathcal{R}(\bold{x})
\}$ must have a unique solution. Let $\bold{x}^*$  be the unique optimal solution. Using the differentiability of $\mathcal{R}(\bold{x})$ combined with the Fenchel equality it follows that $\bold{x}^*=\nabla\varphi(\boldsymbol{\theta})$ iff   $\nabla\varphi(\boldsymbol{\theta})=\arg\max_{\bold{x}\in \Delta_N}\{\langle\boldsymbol{\theta},\bold{x}\rangle-\mathcal{R}(\bold{x})\}$.\eproof
\subsection{Proof of Theorem \ref{Equiv_SSA_FTRL}} From Proposition \ref{R_smooth} we know  $\nabla\varphi(\boldsymbol{\theta}_t)=\bold{x}_{t+1}=\arg\max_{\bold{x}\in \Delta_N}\{\langle\boldsymbol{\theta}_t,\bold{x}\rangle-\R(\bold{x})\}$. Plugging in this observation in the FTRL algorithm the equivalence follows at once.\eproof


\subsection{Proof of Corollary \ref{No_regret_Discrete_choice}} From Proposition \ref{R_smooth}iii) we know $$\bold{x}_{t+1}=\nabla\varphi(\boldsymbol{\theta}_{t})=\arg\max_{\bold{x}\in\Delta_N}\left\{\langle\boldsymbol{\theta}_t,\bold{x}\rangle-\R(\bold{x})\right\}.$$

 This fact implies that  the FRTL algorithm is equivalent to the SSA.  Then the argument used in proving Theorem \ref{SS_Surplus_algorithm_regret} applies. Thus $\textsc{R}^T_{FTRL}$ is bounded by the same term that bounds $\textsc{R}^T_{SSA}$. Similarly, the same optimized bound achieved in $\textsc{R}^T_{SSA}$ applies to $\textsc{R}^T_{FTRL}$. \eproof


\subsection{Proof of Proposition \ref{Recursive_Choice_FTRL}} Let us focus at period $t+1$. Accordingly, the associated  Lagrangian is given by:
 	$$\mathcal{L}(\bold{x}_{t+1};\lambda)=\sum_{i=1}^N\boldsymbol{\theta}_{it} \bold{x}_{it+1}-{\eta}\sum_{i=1}^N\bold{x}_{it+1}\log\Phi_i(\bold{x}_{t+1})+\lambda\left(\sum_{i=1}^N\bold{x}_{it+1}-1\right).$$
 	From \cite[Prop. A1ii)]{Fosgerauetal2019a} we know that $\Phi(\bold{x}_{t+1})$ is differentiable with 
 	$$\sum_{j=1}^N\bold{x}_{jt+1}{\partial \Phi_j(\bold{x}_{t+1})\over \partial \bold{x}_{it+1}}=1\quad\forall i\in A.$$
 	Using this fact, the set of  first order conditions can be written as:
 	\begin{eqnarray}
 		{\partial \mathcal{L}(\bold{x}_{t+1};\lambda)\over \partial\bold{x}_{t+1}}&=&\boldsymbol{\theta}_t-{ \eta}\log \Phi(\bold{x}_{t+1})-{ \eta}+\lambda=0.\label{FOC11}\\
 		{\partial \mathcal{L}(\bold{x}_{t+1};\lambda)\over \partial\lambda}&=&\sum_{i=1}^n\bold{x}_{it+1}-1=0.\label{FOC22}
 	\end{eqnarray}
 	Noting that  $\boldsymbol{\theta}_t=\bold{u}_t+\boldsymbol{\theta}_{t-1}$,  Eq. (\ref{FOC11}) can be expressed as
 	\begin{eqnarray}\label{FOC33}
 		e^{\bold{u}_t/\eta+\boldsymbol{\theta}_{t-1}/\eta}e^{\lambda/\eta-1}&=&\Phi(\bold{x}_{t+1})
 	\end{eqnarray}
 	Recalling that $\Phi(\cdot)=H^{-1}(\cdot)$, from (\ref{FOC33}) we get:
 	\begin{eqnarray}
 		H(e^{\bold{u}_t/\eta+\boldsymbol{\theta}_{t-1}/\eta}e^{\lambda/\eta-1})&=&\bold{x}_{t+1}.\nonumber
 	\end{eqnarray}
 	Noting that $H(\cdot)$ is homogeneous of degree 1, we get:
 	\begin{eqnarray}
 		H(e^{\bold{u}_t/\eta+\boldsymbol{\theta}_{t-1}/\eta})e^{\lambda/\eta-1}&=&\bold{x}_{t+1}.\nonumber
 	\end{eqnarray}
 	Using (\ref{FOC22}) we find that 
 	\begin{eqnarray}
 		e^{\lambda/\eta-1}&=&{1\over \sum_{j=1}^NH_j(e^{\bold{u}_t/\eta+\boldsymbol{\theta}_{t-1}/\eta})}.\nonumber
 	\end{eqnarray}
 	Then it is easy to see that 
 	\begin{equation}\label{FOC44}
 		\bold{x}_{jt+1}={H_j(e^{\bold{u}_t/\eta+\boldsymbol{\theta}_{t-1}/\eta})\over \sum_{i=1}^NH_i(e^{\bold{u}_t/\eta+\boldsymbol{\theta}_{t-1}/\eta})}\quad \mbox{for all  $j\in A, t\geq 1.$}
 	\end{equation}
 	From (\ref{FOC44}), it is easy to see that at period $t$ we must have:
 	\begin{equation}\label{FOC55}
 		\bold{x}_{jt}={H_j(e^{\boldsymbol{\theta}_{t-1}/\eta})\over \sum_{i=1}^NH_i(e^{\boldsymbol{\theta}_{t-1}/\eta})}\quad \mbox{for all  $j\in A$.}
 	\end{equation}
 	Once again, using the fact that $\Phi(\cdot)$ is homogeneous of degree 1,  in (\ref{FOC55}) we find:
 	\begin{equation}\label{FOC51}
 		\Phi(\bold{x}_{t})\sum_{i=1}^NH_i(e^{\boldsymbol{\theta}_{t-1}/
 			\eta})=e^{\boldsymbol{\theta}_{t-1}/\eta}\quad \mbox{for  all $j\in A$.}
 	\end{equation}
 	%Taking log on both sides we obtain
 	%\begin{equation}\label{FOC66}
 	%\log\Phi(\bold{x}_{t})+\log\left(\sum_{j=1}^nH_j(e^{\eta\bold{z}_{t-1}})\right)=\eta\bold{z}_{t-1}\quad \mbox{for  $i=1,\ldots,n$.}
 	%\end{equation}
 	Define $w_{t-1}\triangleq\log\left(\sum_{i=1}^NH_i(e^{\boldsymbol{\theta}_{t-1}/\eta})\right)$. Using this definition, combined with Eq. (\ref{FOC44}),  we get:
 	\begin{equation}
 		\bold{x}_{jt+1}={H_j(\Phi(\bold{x}_{t})e^{\bold{u}_t/\eta+ w_{t-1}})\over\sum_{i=1}^N H_i(\Phi(\bold{x}_{t})e^{\bold{u}_t/\eta+w_{t-1}})}.\nonumber
 	\end{equation}
 	Finally, using the homogeneity of $H$, we conclude that 
 	\begin{equation}
 		\bold{x}_{jt+1}={H_j(e^{\bold{u}_t/\eta+\alpha(\bold{x}_t)})\over\sum_{i=1}^N H_i(e^{\bold{u}_t/\eta+\alpha(\bold{x}_t)})}, \quad\forall j\in A, t\geq 1.\nonumber
 	\end{equation}
