\begin{lemma}\label{Bound_OFTRL}Let Assumptions \ref{Shocks_Assumption} and \ref{Gradient_LL} hold.  Then in the OFTRL algorithm the following hold:
	\begin{equation}\label{Regret_OFTRL}
	\sum_{t=1}^T\langle\bold{x}^*-\bold{x}_t,\bold{u}_t\rangle\leq \eta\varphi(\bold{0})+{L\over 2\eta}\sum_{t=1}^{T}\left\|\mathbf{u}_{t}-\boldsymbol{\beta}_{t}\right\|_{*}^{2}.
	\end{equation}
\end{lemma}
\proof The proof of this Lemma follows from a simple adaptation of \cite[Lemma 2]{RakhlinSridharan2013}.\eproof

\begin{lemma}\label{Cases_regret}In the OFTRL with $S$-step recency bias, the following inequality holds:
		$$\sum_{t=1}^T\|\bold{u}_t-\boldsymbol{\beta}_t\|^2_\ast\leq S^2\sum_{t=1}^T\|\bold{u}_t-\bold{u}_{t-1}\|^2_\ast$$
%\begin{itemize}
		%\item[i)] 
		%\item[ii)] In the geometrically discounted recency bias we have:

		%$$\sum_{t=1}^T\|\bold{u}_t-\boldsymbol{\beta}_t\|^2_\ast\leq 	\frac{1}{(1-\delta)^{3}} \sum_{t=1}^{T}\left\|\mathbf{u}_{t}-\mathbf{u}_{t-1}\right\|_{*}^{2}$$
	%\end{itemize}

\end{lemma}


\proof In proving this result we follow the proof of Lemma 21 in \citet{NIPS2015_5763}. In particular, we use the following:

\begin{eqnarray}
\sum_{t=1}^T\|\bold{u}_t-\boldsymbol{\beta}_t\|^2_\ast&=& \sum_{t=1}^{T}\left\|\mathbf{u}_{t}-\frac{1}{S} \sum_{\tau=t-H}^{t-1} \mathbf{u}_{\tau}\right\|_{*}^{2},\nonumber\\
&=&  \sum_{t=1}^{T}\left(\frac{1}{S} \sum_{\tau=t-S}^{t-1}\left\|\mathbf{u}_{t}-\mathbf{u}_{\tau}\right\|_{*}\right)^{2}.\label{Eq.S.Steps}
\end{eqnarray}

By the triangle inequality we get
\begin{eqnarray}
\frac{1}{S} \sum_{\tau=t-S}^{t-1}\left\|\mathbf{u}_{t}-\mathbf{u}_{\tau}\right\|_{\ast}&\leq & \frac{1}{S} \sum_{\tau=t-S}^{t-1} \sum_{q=\tau}^{t-1}\left\|\mathbf{u}_{q+1}-\mathbf{u}_{q}\right\|_{*}\nonumber\\
&=& \sum_{\tau=t-S}^{t-1} \frac{t-\tau}{S}\left\|\mathbf{u}_{\tau+1}-\mathbf{u}_{\tau}\right\|_{*} \leq \sum_{\tau=t-S}^{t-1}\left\|\mathbf{u}_{\tau+1}-\mathbf{u}_{\tau}\right\|_{*}\nonumber
\end{eqnarray}

By the Cauchy-Schwarz inequality, we get:
$$
\left(\sum_{\tau=t-S}^{t-1}\left\|\mathbf{u}_{\tau+1}-\mathbf{u}_{\tau}\right\|_{*}\right)^{2} \leq S \sum_{\tau=t-S}^{t-1}\left\|\mathbf{u}_{\tau+1}-\mathbf{u}_{\tau}\right\|_{*}^{2}.
$$
Thus it follows that:
\begin{eqnarray}
\sum_{t=1}^T\|\textbf{u}_t-\boldsymbol{\beta}_t\|^2_\ast&\leq& S\sum_{t=1}^{T} \sum_{\tau=t-S}^{t-1}\left\|\mathbf{u}_{\tau+1}-\mathbf{u}_{\tau}\right\|_{*}^{2}\nonumber\\
&\leq& S^{2} \sum_{t=1}^{T}\left\|\mathbf{u}_{t}-\mathbf{u}_{t-1}\right\|_{*}^{2}\nonumber
\end{eqnarray}
