\begin{theorem}\label{thm:DualityRelationFlow}
    Let $s<t$ and $\eta,\xi\in \N^{V} $. Let $(\bfX_{s,t}[\eta])_{t\geq 0}$ be the process defined in Theorem~\ref{thm:ExistenceAndFeller} and $(\widehat{\bfX}_{s,t}[\eta])_{t\geq 0}$ as in \eqref{eq:DualDoubleIndexedProcess}. If there exists an $u\in[s,t]$ such that $\bfX_{s,u}[\eta]\leq \widehat{\bfX}_{u+,t}[\xi]$, $\IP$-almost surely, then $\bfX_{s,u}[\eta]\leq \widehat{\bfX}_{u+,t}[\xi]$ for all $u\in[s,t]$, $\IP$-almost surely. This implies in particular that for any arbitrary $t\geq 0$ it hold that
    \begin{equation*}
        [0,t]\ni s\mapsto\IP\big(\bfeta^{\eta}_{s}\leq \bfxi^{\xi}_{t-s}\big)
    \end{equation*}
    is a constant function.
\end{theorem}
\begin{proof}
    Let us again denote by $S$ a jump time of either of the two processes and $x\in V$ the unique associated vertex which is affected by the change. It suffices to show that 
    \begin{equation*}%\label{eq:DualityRelationProof}
        \bfX_{s,S-}[\eta]\leq \widehat{\bfX}_{S,t}[\xi] \text{ if and only if } \bfX_{s,S}[\eta]\leq \widehat{\bfX}_{S+,t}[\xi].
    \end{equation*}

    We first assume that
    \begin{equation}\label{eq:Contradiction1DualityProof}
        \bfX_{s,S-}[\eta]\not\leq \widehat{\bfX}_{S,t}[\xi] \text{ and } \bfX_{s,S}[\eta]\leq \widehat{\bfX}_{S+,t}[\xi]
    \end{equation}
    and show that this situation cannot occur. We will show this with a proof by contradiction. 
    \begin{itemize}
    \item  Suppose that $S\in \IU_x$. Then the only relevant case is if $\bfX_{s,S-}[\eta](x)-1=\widehat{\bfX}_{S,t}[\xi](x)$, $S\in \widehat{\cD}_{s,t}(x,\xi)$ and $S\notin \cU_{s,t}(x,\eta)$. Then we have  $\bfX_{S-,t}[\eta](x)=\bfX_{S,t}[\eta](x)$, and thus there exists $\alpha\in [0,\infty)$ such that $(\alpha,S) \in \IU_x$  and $\alpha< \birth(\bfX_{s,S-}[\eta](x)+1)$, which implies $S\in \widehat{\cU}_{s,t}(x,\xi)$. This contradicts \eqref{eq:Contradiction1DualityProof}.
    \item Next suppose that $S\in \ID_x$. Similarly as in the previous point, the only relevant case is $\bfX_{s,S-}[\eta](x)-1=\widehat{\bfX}_{S,t}[\xi](x)$,  $S\in \cD_{s,t}(x,\eta)$ and $S\notin \widehat{\cU}_{s,t}(x,\xi)$. But, this implies that $\widehat{\bfX}_{S,t}[\xi](x)=\widehat{\bfX}_{S+,t}[\xi](x)$, and thus there exists $\alpha\in [0,\infty)$ such that $(\alpha,S) \in \IU_x$  and $\alpha< \death(\widehat{\bfX}_{s,S+}[\eta](x)+1)$, which implies $S\in \widehat{\cU}_{s,t}(x,\xi)$. Thus, we again have a contradiction to \eqref{eq:Contradiction1DualityProof}.
    \item Finally, assume that $S\in \II_{(x,y)}$ for some $y\in \cN_x$. First, we observe that $\bfX_{S-,t}[\eta](x)=\bfX_{S,t}[\eta](x)$ and $\widehat{\bfX}_{S,t}[\xi](x)=\widehat{\bfX}_{S+,t}[\xi](x)$. Furthermore, the only relevant case is if $\widehat{\bfX}_{S+,t}[\xi]\geq \bfX_{S,t}[\eta](x)>0$. It follows immediately that $\bfX_{S,t}[\eta](y)>0$, and thus we know by assumption that $\widehat{\bfX}_{S+,t}[\xi](y)>0$. This allows us to conclude that $\widehat{\bfX}_{S+,t}[\xi](x)=\widehat{\bfX}_{S,t}[\xi](x)\geq \bfX_{S,t}[\eta](x)$, and thus $\bfX_{s,S-}[\eta]\leq \widehat{\bfX}_{S,t}[\xi]$. This leads to a contradiction of \eqref{eq:Contradiction1DualityProof}.
    \end{itemize}
    On the other one can show that 
    \begin{equation*}
        \bfX_{s,S-}[\eta]\leq \widehat{\bfX}_{S,t}[\xi] \text{ and } \bfX_{s,S}[\eta]\not\leq \widehat{\bfX}_{S+,t}[\xi].
    \end{equation*}
    cannot be true by the same line of arguments. 
\end{proof}
\begin{proof}[Proof of Proposition~\ref{prop:Duality}]
    This is a direct consequence of Theorem~\ref{thm:DualityRelationFlow}.
\end{proof}
Finally, we state the monotonicity properties of the CPLI.
\begin{lemma}\label{lem:MonotonictyForTheCPLI}
    Let $\bfxi=(\bfxi_t)_{t\geq 0}$ be a CPLI with infection rates $\lambda>0$ and rate function $\birth,\death$.
    \begin{enumerate}
        \item  $\bfxi$ is a monotone Markov process, i.e.\ if $\eta_1\leq \eta_2$, then $\bfxi_t^{\xi_1}\leq \bfxi_t^{\xi_2}$ for all $t\geq 0$, where $\xi_1,\xi_2\in \N^V$.
        \item $\bfxi$ is a monotone with respect to $\lambda$, i.e.\ if $\lambda<\lambda'$ then there exists a CPVL $\bfxi'$ with infection rate $\lambda'$ and rate functions $\birth$ and $\death$ and $\bfxi_{0}= \bfxi'_{0}$ such that $\bfxi_{t}\leq  \bfxi'_{t}$ for all $t\geq 0$.
    \end{enumerate}
\end{lemma}
\begin{proof}
    This can be proven analogously as Lemma~\ref{lem:MonotonictyInRates} and Theorem~\ref{thm:DualityRelationFlow}, i.e.\ by showing that all potential jumps preserver the order.
\end{proof}

\section{Survival of the CPVL and its upper invariant law}\label{sec:SurvivalCPVL}
The first result we will show in this section is that the critical behaviour of the survival probability of the CPVL does not depend on the initial configuration as long as the initial configuration $\eta$ is non-empty and finite. This means that 
\begin{equation*}
     \IP(|\bfeta^{\delta_{\zero}}_t|>0 \,\forall\, t\geq 0)>0\,\, \Leftrightarrow\,\,\IP(|\bfeta^{\eta}_t|>0 \,\forall\, t\geq 0)>0
\end{equation*}
for all $\eta\in \N_0^V$ with $|\eta|\in (0,\infty)$.
\begin{proof}[Proof of Propostion~\ref{prop:CriticalValueIndependentOfStart}]
    If the left-hand side is true by monotonicity, the right-hand side is a direct consequence. On the other hand, by additivity we know that
    \begin{equation*}
        \bfeta^{\eta}_t=\bigvee_{x\in V: \eta(x)>0} \bfeta_t^{\eta(x)\delta_x}
    \end{equation*}
    for all $t\geq 0$. In particular it holds that if $\bfeta^{\eta}$ has a strictly positive probability to survive so does $\bfeta^{M \delta_x}$, where $M:=\max_{x\in V}\eta(x)<\infty$. %The fact that $M<\infty$ follows, since we assumed that $|\eta|<\infty$. 
    Now we see that
    \begin{equation*}
        \IP(\bfeta^{\delta_x}_1=M\delta_x)>0
    \end{equation*}
    and together with the the Markov property we conclude that
    \begin{equation*}
        \IP(|\bfeta^{\delta_x}_t|>0 \, \forall\,  t\geq 0)\geq \IP(|\bfeta^{M\delta_x}_t|>0\,\forall\, t\geq 0)\IP(\bfeta^{\delta_x}_1=M\delta_x)>0.\qedhere
    \end{equation*}
\end{proof}
Now we prove the sufficient criterion stated in Proposition~\ref{thm:upperbound} for survival of the CPVL in the sense that the survival probability is positive.
\begin{proof}[Proof of Proposition~\ref{thm:upperbound}]
    We can couple the CPVL $\bfeta$ with an infection rate function $\Lambda$ and  rate functions $\birth$ and $\death$ with a contact process $\bfzeta$ with the infection rate $\Lambda(1)$ and recovery rate $d(1)$. This can be achieved using Proposition~\ref{lem:MonotonictyInRates} with $\birth'(n)=0$ for all $n\geq 0$ and the same infection and death rate function $\Lambda$ and $\death$. In words this means that we do not allow any birth events on a vertex. Thus, at infection, a vertex gets assigned the viral load $1$, which cannot increase further and will eventually drop to $0$ at rate $d(1)$. Note that these are the same dynamics as a classical contact process with infection rate $\Lambda(1)$ and death rate $\death(1)$, which proves the claim.
\end{proof}
Next, we prove the criterion that guarantees extinction stated in Theorem~\ref{thm:LowerBound}. 
\begin{proof}[Proof of Theorem~\ref{thm:LowerBound}]
    We consider the situation where $\bfeta_{0}=\delta_{\zero}$, i.e.\ the origin is infected and in state $1$. The aim of the proof is to couple the CPVL with a discrete time branching process such that if the branching process dies out so does the CPVL. Let us introduce the following notation
    \begin{equation}
        \T:=\{\alpha=0 \alpha_1\cdots \alpha_n : n\in \N,\ a_i\in \N, \ \forall \  i\leq n\}.
    \end{equation}
    The idea of this coupling is to count every infection event which could potentially transmit an infection. This means we count every $((x,y),t)\in \Delta^{\inf}$ such that $\bfeta_{t-}(x)>0$ regardless of the state of its neighbour $y$.

    Thus, we change our perspective in the sense that we say that we start initially with a particle at the origin $\zero$, which is born at time $0$ with initial viral load $1$ and the viral load evolves according to a BD-process $X(0)=(X_t(0))_{t\geq 0}$. This particle has in particular a life time $T_0:=\inf\{t>0: X_t(0)=0\}\sim \tau_{rec}$ and we lable it by $\bfX_{0}:=(\zero,0,X(0))$. Let us denote by  
    \begin{equation*}
        \cI_{0}:=\{(t,y) \in [0,T_0)\times \cN_{\zero}: \exists \alpha\in [0,\infty)\text{ s.t. } \exists \big((0,y),\alpha,t\big) \in \II \text{ s.t. } \alpha<\Lambda(X_t(0)) \}
    \end{equation*}
    the set of all birth times and location of all particles generated by the initial particle $\bfX_0$.
    It is not difficult to see that the total number of generated particles $|\cI_{0}|\sim \text{Poi}\big(D\int_{0}^{\tau_{\text{rec}}}\Lambda(X_s)ds\big)$, where $X$ is a BD-process with rates $\birth$ and $\death$ and $X_0=1$. We can now order the points in $\cI_{0}$ according to the birth time such that we can represent the set as
     \begin{equation*}
        \cI_{0}:=\{(x_{01},t_{01}),\dots (x_{0|\cI_{0}|},t_{0|\cI_{0}|})\}
    \end{equation*}
    where $0\leq t_{01}\leq \cdots\leq t_{0|\cI_{0}|}<T_0$ and $x_{0k}\in N_{\zero}$ for all $k\in \{1,\cdots, |\cI_{0}|\}$. Note that since we assumed that $\IE[\int_{0}^{\tau_{\text{rec}}}\Lambda(X_s)ds]<\infty$ there are almost surely only finitely many space-time points.

    The only piece which is missing now is the evolution of the offspring particles. These are again started with an initial viral load of $1$ which evolve according to independent BD-process $X(0k)$ with rate functions $\birth$ and $\death$ and we denote the life time by $T_{0k}$. 

    For the sake of the coupling with $\bfeta$ we check for every pair $(x_{0k},t_{0k})$ if $\bfeta_{t_{0k}-}(x_{0k})=0$. If that is the case then we can choose $X(0k)=\bfeta_{t_{0k}}(x_{0k})$, since $t_{0k}$ is indeed a true infection time for CPVL such that the evolution of this particle is coupled via the Poisson construction with the viral load of vertex $x_k$ started at time $t_k$. If that is not the case, i.e.\ $\eta_{t_k}(x_k)>0$, then we choose $X(0k)$ independent from the Poisson construction and the other particles. We can interpret the second case as if we generate an artificial particle. 

    We again denote all offspring particles by $\bfX_{0k}:=(x_{0k},t_{0k},X(0k))$ and $\cI_{0k}$ again denotes the set of all birth times and location of all particles generated by the $0k$th-particle $\bfX_{0k}$.

    According to this scheme we successively generate a family of random variables $\bfX_{\alpha}=(x_{\alpha},t_{\alpha},X(\alpha))$ and random sets $\cI_{\alpha}$. Of course if the $\alpha$-th particle was never created then $\cI_{\alpha}=\emptyset$. With this in place we define by
    \begin{equation*}
        \bfzeta_s(x):=\1_{\{x_{0}=x, s\in [0,T_{0})\}}+\sum_{\alpha\in \T}\1_{\{\cI_{\alpha}\neq \emptyset\}}\sum_{k=1}^{|\cI_{\alpha}|}\1_{\{x_{\alpha k}=x, s\in [t_{\alpha k},T_{\alpha k}+t_{\alpha k})\}}
    \end{equation*}
    the number of all particles alive at time $s$ at location $x$. Note that by construction $\bfeta_s\leq \bfzeta_s$ for all $s\geq 0$. Thus, if we can show that $|\bfzeta_t|= 0$ at some time $t$, then this implies extinction of $\bfeta$.

    Furthermore, since we assumed that $\IE[\int_{0}^{\tau_{\text{rec}}}\Lambda(X_s)ds]<\infty$ we know that every particle will die almost surely, and therefore $|\bfzeta_t|= 0$ at some time $t$ is equivalent that the total progeny $\cT:=1+\sum_{\alpha\in\T}|\cI_{\alpha}|<\infty$ almost surely. Now if we forget about the locations and precise times when the particles are alive, then $\cT$ is nothing else but the total progeny of a discrete time branching process with offspring distribution $Y\sim \text{Poi}( D \int_{0}^{\tau_{\text{rec}}}\Lambda(X_s)ds)$ and we know that if $\IE[Y]= D \IE[\int_{0}^{\tau_{\text{rec}}}\Lambda(X_s)ds]<1$, then $\cT<\infty$ almost surely, which proves the claim.
\end{proof}
Finally, we show the existence of an upper invariant law $\overline{\nu}$ if $\IE[\tau_{rec}]<\infty$.
\begin{proof}[Proof of Theorem~\ref{thm:InvariantDistributionCPVL}]
    Let us denote by $(T_t)_{t\geq 0}$ the semi-group associated with $(\bfeta_t)_{t\geq 0}$ and by $(S_t)_{t\geq 0}$ the semi-group associated with the Markov process $(\bfzeta_t)_{t\geq 0}$ and transitions 
    \begin{equation*}
        \begin{aligned} 
            \zeta(x)&\to \zeta(x)+1\quad \text{ at rate } %\lambda D \1_{\{\eta(x)=0\}} +
            \birth(\eta(x))%\1_{\{\eta(x)>0\}} 
            \text{ and }\\
            \zeta(x)&\to \zeta(x)-1\quad \text{ at rate } \death(\eta(x))\1_{\{\eta(x)>1\}}.
        \end{aligned}
    \end{equation*}
    Appealing to Proposition~\ref{prop:CouplingWithIndBD} we can couple these two process such that if $\bfeta_0\leq \bfzeta_0$, then $\bfeta_t\leq \bfzeta_t$ for all $t\geq 0$. Note that the state space of $\bfzeta$ is $\N^V$.

    Furthermore, let $f:\overline{\N}_0^V\to \IR$ be a continuous and increasing function, i.e.\ $f(\eta^1)\leq f(\eta^2)$ if $\eta^1\leq \eta^2$. By the coupling between $(\bfeta_t)_{t\geq 0}$ and $(\bfzeta_t)_{t\geq 0}$ we know that $T_tf(\eta)\leq S_tf(\eta)$ for all $\eta\in \N^V$ and $t\geq 0$ if $f$ is increasing. Note that since both systems are monotonous it follows that $T_tf$ and $S_tf$ are again increasing function. First of all, it follows that
    \begin{equation*}
        \int f(x) \pi T_{t+s}(d x)=\int T_{s}[T_{t}f(x)] \pi(d x)\leq \int S_{s}[T_{t}f(x)] \pi(d x)=\int T_{t}f(x) \pi S_{s}(d x)
    \end{equation*}
    Recall that $\pi$ was the invariant distribution of $(\bfzeta_t)_{t\geq 0}$, i.e.\ $\pi S_s=\pi$ for all $s\geq 0$. Thus, it follows that
    \begin{equation*}
        \int f(x) \pi T_{t+s}(d x)\leq \int f(x) \pi  T_{t}(d x).
    \end{equation*}
    This means that $t\mapsto \int f(x) \pi  T_{t}(d x)$ is a decreasing function for all increasing functions $f$. Furthermore, this function is bounded from below by $0$ such that it follows that
    \begin{equation*}
        \overline{\nu}f:=\lim_{t\to \infty}\int f(x) \pi  T_{t}(d x)
    \end{equation*}
    exists for all increasing $f$. Note that the class of all bounded and increasing functions is convergence determining.

    Next let $\mu$ be another probability law on $\N^V$ such that $\pi\prec \mu$. By monotonicity it follows that $\pi T_t f\leq \mu T_t f$ for all $t\geq 0$, which implies
    \begin{equation*}
        \overline{\nu}f\leq \liminf_{t\to \infty} \int T_s f(x) \mu T_{t}(d x).
    \end{equation*}
    Monotonicity also implies that
    \begin{equation*}
       \limsup_{t\to \infty} \int T_s f(x) \mu T_{t}(d x)\leq \lim_{t\to \infty} \int T_s f(x) \mu  S_{t}(d x)= \pi T_s f,
    \end{equation*}
    where we also used that $\pi$ is the unique invariant (limiting) distribution of $(S_t)_{t\geq 0}$. But now we can use the semi-group property of $(T_t)_{t\geq 0}$, i.e.\ that $T_tT_s=T_{t+s}$ and that $t\mapsto T_t$ is strongly continuous and send $s\to \infty$. This yield that 
    \begin{equation*}
        \overline{\nu}f\leq \lim_{t\to \infty} \int f(x) \mu T_{t}(d x)\leq \overline{\nu}f.
    \end{equation*}
    Thus, $\overline{\nu}$ is the largest invariant distribution with respect to the stochastic order.

    It remains to show the two additional statements. First, we know that $\pi(\N^V)=1$ and by construction $\overline{\nu}\preceq \pi$. Thus it follows that $\overline{\nu}(\N^V)=1$.

    For the second statement we note that $p:=\overline{\nu}(\{\szero\})\in \{0,1\}$ follows by the fact that $\nu(\,\cdot\, ):=\overline{\nu}(\,\cdot\, |\{\szero\})$ is again a invariant distribution and 
    \begin{equation*}
        \overline{\nu}=(1-p)\nu+p \delta_{\szero}.
    \end{equation*}
    If we assume that $p<1$, then it follows that $\overline{\nu}\leq \nu$, but since $\overline{\nu}$ is the upper invariant law it must hold that $\overline{\nu}= \nu$, which yields that $p=0$.
\end{proof}


\begin{proof}[Proof of Corollary~\ref{Cor:SurvivalForSpecialCase}]
    First we prove that
    \begin{equation}\label{eq:EquivalenceForSurvival}
        \IE\bigg[\int_{0}^{\tau_{\text{rec}}}\Lambda(X_s)\mathrm{d}s\bigg]<\infty \Leftrightarrow \sum_{n=1}^{\infty} \frac{n^k}{\death(n)} \prod_{j=1}^{n-1}\frac{\birth(j)}{\death(j)}<\infty
    \end{equation}
    For $k=0$ this is equivalent to $\IE[\tau_{\text{rec}}]<\infty$, which we will assume from now on.

    Let $Z$ be BD-process on $\N$ with $Z_0=1$ and the same rates as $X$, except that it cannot enter the state $0$, i.e.\ it has transitions
   \begin{align*}
        n\to n+1 &\text{ with rate } \birth(n)\\
        n\to n-1 &\text{ with rate } \death(n)\1_{\{n\geq 2\}}.
    \end{align*}
    Since we assume $\IE[\tau_{\text{rec}}]<\infty$ we know that the process $Z$ is positive recurrent and 
    \begin{equation*}
        \pi(k)=\pi(1)\frac{\birth(1)\cdots \birth(k-1)}{\death(2)\cdots \death(k)} \text{ and }\pi(1):=\bigg(1+\sum_{n=1}^{\infty}\prod_{i=1}^{n} \frac{\birth(i)}{\death(i+1)}\bigg)^{-1}.
    \end{equation*}
    Let $T_1:=\inf\{t\geq 1: Z_t=1\}$ one can show that 
    \begin{equation*}
        \IE\bigg[\int_{0}^{\tau_{\text{rec}}}\Lambda(X_s)\mathrm{d}s\bigg]=\frac{\birth(1)+\death(1)}{\death(1)}\IE\bigg[\int_{0}^{T_1}\Lambda(Z_s)\mathrm{d}s\bigg] 
    \end{equation*}
    using that the number of times needed to enter state $0$ from $1$ is geometric distributed  with success probability $\frac{\death(1)}{\birth(1)+\death(1)}$. Finally, we use that by standard Markov-chain theory it is known that $\pi(y)=\IE[\int_{0}^{T_1} \1_{\{Z_t=y\}}dt]$, and thus we get that
    \begin{equation*}
       \IE\bigg[\int_{0}^{T_1}\lambda(Z_t)dt\bigg]=\sum_{k=1}^{\infty}\lambda(k)\IE\bigg[\int_{0}^{T_1} \1_{\{Z_t=k\}}dt\bigg]=\pi(1)\sum_{k=1}^{\infty}\lambda(k)\prod_{i=1}^{k-1} \frac{\birth(i)}{\death(i+1)}
    \end{equation*}
    Putting everything together yields that
    \begin{equation*}
        \IE\bigg[\int_{0}^{\tau_{\text{rec}}}\Lambda(X_s)\mathrm{d}s\bigg] \Leftrightarrow \sum_{n=1}^{\infty} \frac{n^k}{\death(n)} \prod_{j=1}^{n-1}\frac{\birth(j)}{\death(j)},
    \end{equation*}
    which proves the claim.

    Now we just need to verify \eqref{eq:EquivalenceForSurvival} for both cases, since if this is the case by Theorem~\ref{thm:upperbound} we get that for $\lambda$ large enough the CPVL dies out, and thus $\lambda_c(\gamma)>0$.

    First set $\birth(n)=n$ and $\death(n)=(n+(a-1))\1_{\{n\geq 1\}}$ for all $n\geq 0$ with $a\geq 1$, then we get that
    \begin{equation*}
        \sum_{n=1}^{\infty} \frac{n^\gamma}{n+a-1} \prod_{j=1}^{n-1}\frac{j}{j+a-1}=  \sum_{n=1}^{\infty} \Gamma(a+1)n^{\gamma-1}\frac{\Gamma(n+1)}{\Gamma(n+a+1)}<\infty
    \end{equation*}
    if $\gamma<a-1$, since $\lim_{n\to \infty}\frac{\Gamma(n+a)}{\Gamma(n)}\frac{1}{n^a}=1$.


    Next let $\birth(n)=\alpha n$ and $\death(n)=\beta n$ for all $n\geq 0$ with $\alpha<\beta$, then we get for all for all $\gamma\geq 0$ that 
    \begin{equation*}
        \sum_{n=1}^{\infty} \frac{n^\gamma}{\beta n} \prod_{j=1}^{n-1}\frac{\alpha}{\beta}=  \sum_{n=1}^{\infty} n^{\gamma-1}\alpha\bigg(\frac{\alpha}{\beta}\bigg)^{n}<\infty.\qedhere
    \end{equation*}
\end{proof}


\section{Phase transition of the CPLI}\label{Sec:PhaseTransitionCPLI}
Throughout the section, we consider the CPVL with a constant infection rate function, i.e.\ $\Lambda(n)=\lambda$ for all $n\geq 0$, and assume that $\supp(b)=\supp(d)=\N$. Recall that we denote the critical infection for survival by $\lambda_c$. 

The main goal of this section is to prove Theorem~\ref{thm:PhasetrastionCPLI}, and therefore to establish the connection between the phase transition of the CPLI and the CPVL. But in order to do so we need some technical results about survival probability of the CPVL.
\begin{lemma}\label{lem:AsymtoticSurvivalAS}
     Assume that $\lambda>\lambda_c$ and let $(M_N)_{N\geq 1}$ be a monotone sequences of subsets that convergence to $V$, i.e. $M_N\subset V$ such that $M_N\uparrow V$. Then it holds that 
    \begin{equation*}
        \lim_{N\to \infty}\IP(|\bfeta^{\delta_{M_N}}_t|>0 \,\forall \, t\geq 0)=1.
    \end{equation*}
\end{lemma}
\begin{proof}
First of all note that we assumed that $G=\Gamma(\mathfrak{g},\mathfrak{s})$ is a Cayley graph and with $\mathfrak{g}$ being an infinite group that is finitely generated by $\mathfrak{s}$. Thus, there must exist a graph automorphism $S$ and a vertex $x_0\in V$ such that $|\{S^n(x_0): n\in \Z\}|=\infty$.
Without loss of generality, we set $x_0:=\zero$ otherwise we relabel. Furthermore, we set $\cS:=\{S^n(\zero): n\in \Z\}$.

Now define $Y_x(s):=\1_{\{|\bfeta^{x}_t|>0\,\forall t\geq 0\}}$ as the indicator variable for the event of survival of the process, which starts with only $x$ being in state $1$ and everything else $0$. 

Recall that we constructed $\bfeta$ through three independent PPP $\II,\IU$ and $\ID$. From a different perspective these PPP's can be seen as families of independent Poisson point processes on $\IR\times \IR_+$, namely $(\II_{(x,y)})_{(x,y)\in \vec{E}}$, $(\IU)_{x\in V}$ and $(\ID)_{x\in V}$ on $\IR\times \IR_+$. To shorten the notation, we define $\Delta:=(\II,\IU,\ID)$.

It is clear that $S$ is a measure preserving map with respect to the distribution of this family of the three Poisson processes, i.e.\ 
\begin{equation*}
    S^{-1}(\II,\IU,\ID)=:\big(S^{-1}(\II),S^{-1}(\IU),S^{-1}(\ID)\big)\stackrel{d}{=}(\II,\IU,\ID).
\end{equation*}
Furthermore, every of the three processes are a collection of independent random variables, and thus are ergodic with respect to $S$. Since the three processes are independent it follows immediately that $(\Delta,S)$ is ergodic.

Since $\bfeta$ is constructed via the Poisson construction we see that there must exist a measurable function $f$ mapping $\Delta$ to $\{0,1\}$ such that
\begin{align*}
	f(S^{-k}(\Delta))=\1_{\{|\bfeta^{x_k}_t|>0\,\forall t\leq s\}}:=Y_k
\end{align*}
for every $k\in\Z$, where $x_k=S^{-k}(\zero)$. Note that by translation invariance, $\IP( Y_0 = 1 )=\IP(Y_{k} = 1)$ for all $k\in \Z$ and by assumption we know that $\IP(Y_{\zero} = 1)>0$. Then by Birkhoff's mean ergodic theorem \cite[Theorem~9.6]{kallenberg2002foundations}, it follows that
\begin{align*}
\frac{1}{2n}\sum_{k=-n}^{n}Y_k =\frac{1}{2n}\sum_{k=-n}^{n}f(S^{-k}(\Delta))\to\IE[f(\Delta)]=\IP\big(|\bfeta^{\delta_{\zero}}_t|>0\,\forall\, t\leq s\big)>0
\end{align*}
almost surely. This implies that almost surely there must exist a $k$ for which $Y_k= 1$. By additivity, it follows that the event $\big\{|\bfeta^{\delta_{\cS}}_t|>0 \,\,\forall t\geq 0\big\}$ occurs as soon as the event $\{Y_k = 1\}$ occurs for some vertex in $x_k\in \cV$ which proves the statement.
\end{proof}


\begin{lemma}\label{lem:AysmtoticSurvivalAtOneSite}
    Assume that $\lambda>\lambda_c$. Then it holds that 
    \begin{equation*}
        \lim_{N\to \infty}\IP\big(|\bfeta^{N\delta_{\zero}}_t|>0 \, \forall \,t\geq 0\big)=1.
    \end{equation*}
\end{lemma}
\begin{proof}
    First set $T_0^N:=\inf\{t>0:\bfeta_t^{N\delta_{\zero}}(\zero)=0\}$. Note that since $\death(n)\in O(n)$ as $n\to \infty$ it follows that $T_0^N\to \infty$ almost surely.

    Suppose the statement is false, which means that there exists an $\varepsilon>0$ such that
        \begin{equation*}
            \lim_{N\to \infty}\IP\big(|\bfeta^{N\delta_{\zero}}_t|>0 \, \forall \,t\geq 0\big)< 1-\varepsilon<1.
        \end{equation*}
    Furthermore, by monotonicity follows that $\IP\big(|\bfeta^{N\delta_{\zero}}_t|>0 \, \forall \,t\geq 0\big)< 1-\varepsilon$
    for all $N>0$. On the other hand it follows by Lemma~\ref{lem:AsymtoticSurvivalAS} that there exists a $\eta_\varepsilon$ such that
    \begin{equation*}
        \IP\big(|\bfeta^{\eta_{\varepsilon}}_t|>0 \,\forall\, t\geq 0\big)>1-\frac{\varepsilon}{3}.
    \end{equation*}
    It again follows by monotonicity that on the event that $\bfeta_t(\zero)>0$ it holds that
    \begin{equation*}
        \IP(\bfeta_{t+1}\geq \eta_{\varepsilon}|\bfeta_{t})\geq \IP(\bfeta_{t+1}\geq \eta_{\varepsilon}|\bfeta_{t}=\delta_{\zero})>\varepsilon',
    \end{equation*}
    where $\varepsilon'$ only depends on $\eta_{\varepsilon}$ and the left hand side is the probability that we reach a larger state than $\eta_{\varepsilon}$ after a time period of length $1$. 

    In the next step we can use the strong Markov property to conclude that
    \begin{align*}
        \IP\big(|\bfeta^{N\delta_{\zero}}_t|<|\eta_{\varepsilon}| \,\forall\, t\in \{1,\dots, \lfloor T_0^{N}\rfloor\}\big)&<\IE\bigg[\prod_{i=1}^{\lfloor T_0^{N}\rfloor}\IP\big(|\bfeta^{N\delta_{\zero}}_{i}|<|\eta_{\varepsilon}|\,\big|\bfeta^{N\delta_{\zero}}_{i-1}\big)\bigg]\\
        &<\IE\big[(1-\varepsilon')^{\lfloor T_0^{N}\rfloor}\big].
    \end{align*}
    Since we assumed that $T_0^N\to \infty$ almost surely as $N\to \infty$ we obtain with monotone convergences that $\IE\big[(1-\varepsilon')^{\lfloor T_0^{N}\rfloor}\big]\to 0$. Thus, there exists an $N_0\geq 0$ such that $\IE\big[(1-\varepsilon')^{\lfloor T_0^{N}\rfloor}\big]<\frac{\varepsilon}{3}$ for all $N\geq N_0$.
    \begin{align*}
        \IP(\exists t\leq T_0^N \text{ s.t. } \bfeta^{N\delta_{\zero}}_t\geq \eta_{\varepsilon})&\geq \IP(\bfeta^{N\delta_{\zero}}_t\geq \eta_{\varepsilon} \text{ for some } t\in \{1,\dots, \lfloor T_0^N\rfloor \big)\\
        &\geq 1-\IE\big[(1-\varepsilon')^{\lfloor T_0^{N}\rfloor} \big]>1-\frac{\varepsilon}{3}.
    \end{align*}
    But by using again the strong Markov property it follows that
    \begin{equation*}
        \IP\big(|\bfeta^{N\delta_{\zero}}_t|>0 \forall t\geq 0\big)>\Big(1-\frac{\varepsilon}{3}\Big)^2>1-\varepsilon,
    \end{equation*}
    which leads to a contradiction.
\end{proof}


Finally, we can show the desired result and establish the formal connection between the two phase transitions.

\begin{proof}[Proof of Proposition~\ref{thm:PhasetrastionCPLI}]
Let us assume that $\lambda\neq \lambda_c$. Thus, by Lemma~\ref{lem:AysmtoticSurvivalAtOneSite} we know that 
\begin{equation*}
    \lim_{N\to \infty}\IP(|\bfeta^{N\delta_y}_t|>0 \,\forall\, t\geq 0)=\begin{cases}
        1   &\text{ if } \lambda>\lambda_c\\
        0   &\text{ if } \lambda<\lambda_c
    \end{cases}
\end{equation*}
By using the duality relation stated in Proposition~\ref{prop:Duality} and monotonicity of the measure $\overline{\mu}$ we get that
\begin{equation*}
    \lim_{N\to \infty}\IP(|\bfeta^{N\delta_y}|>0 \, \forall \, t\geq 0)=\lim_{N\to \infty}\overline{\mu}(\xi: \xi(y)< N)=\overline{\mu}(\xi: \xi(y)< \infty)
\end{equation*}
Now consider a sequences $(V_n)_{n\in \N}$ of finite subset of $V$, such that $V_n\subset V_{n+1}$ and $\bigcup_{n\in \N}V_n=V$. Then we see that for $\lambda>\lambda_c$ 
\begin{equation*}
    \overline{\mu}(\xi: \xi(y)<\infty \,\forall\, y\in V_n )= \overline{\mu}\bigg(\bigcap_{y\in V_n}\{\xi:  \xi(y)<\infty\}\bigg)=1
\end{equation*}
for every $n\geq 0$, where we used the fact that the intersection of finitely many sets with mass $1$ has again mass $1$. By using continuity from above we get that
\begin{equation*}
    \overline{\mu}(\xi: \xi(y)<\infty \,\forall\, y\in V)= \lim_{n\to 0} \overline{\mu}\bigg(\bigcap_{y\in V_n}\{\xi:  \xi(y)<\infty\}\bigg)=1.
\end{equation*}
Analogously it follows for $\lambda<\lambda_c$
\begin{equation*}
    \overline{\mu}(\xi: \exists x\in V_n \text{ s.t. } \xi(y)<\infty)= \overline{\mu}\bigg(\bigcup_{y\in V_n}\{\xi:  \xi(y)<\infty\}\bigg)=0
\end{equation*}
and by using continuity from below we get that
\begin{equation*}
    \overline{\mu}(\xi:  \exists x\in V \text{ s.t. } \xi(y)<\infty)= \lim_{n\to 0} \overline{\mu}\bigg(\bigcup_{y\in V_n}\{\xi:  \xi(y)<\infty\}\bigg)=0.\qedhere
\end{equation*}
\end{proof}
