\newpage

\begin{algorithm}[ht]
    \begin{algorithmic}[1]
        \Require $\theta_{hist}$: history of $\theta_c$ from Alg. \ref{alg:newadam}
        \Require $\theta_{est_{hist}}$: history of $\theta_{est}$, detrended linearly \Comment{from \textit{soundloc} agent}
        \Require $i_{bored}$: current number of `bored' windows
        \Require $N_{bored}$: maximum number of `bored' windows
        \Require $\sigma_{bored}$: variance threshold to establish `boredom'
        \State $N_{est_{hist}} \gets \mathit{length}(\theta_{est_{hist}})$
        \State $w_{est_{hist}} = \frac{1}{1+e^{-\left(\left[1...N_{est_{hist}} \right]-\frac{N_{est_{hist}}}{2}\right)}}$
        \State $\overline{\theta_{est_{hist}}} \gets \frac{\sum_i \theta_{est_{hist}}[i]}{N_{est_{hist}}}$
        \State $\sigma_{est_{hist}} \gets \sqrt{\frac{\sum_i (\theta_{est_{hist}}[i] - \overline{\theta_{est_{hist}}})*(\theta_{est_{hist}}[i]w_{est_{hist}}[i] - \overline{\theta_{est_{hist}}})}{N_{est_{hist}}-1}}$
        \If{$i_{bored} \geq N_{bored}$}
            \If{$\sigma_{est_{hist}} > \sigma_{bored}$}
                \State $i_{bored} \gets 0$ \Comment{Excited, start using $\theta_{est}$}
                \State suspend Algorithm \ref{alg:newadam}
            \Else
                \State restart Algorithm \ref{alg:newadam} \Comment{Bored, keep using $\theta_{corr}$}
            \EndIf
            \State $\theta_{corr} \gets \theta_{hist}[last]$
        \Else
            \State $N_{hist} \gets \mathit{length}(\theta_{hist})$
            \State $\overline{\theta_{hist}} \gets \frac{\sum_i \theta_{hist}[i]}{N_{hist}}$
            \State $\sigma_{hist} \gets \sqrt{\frac{\sum_i (\theta_{hist}[i] - \overline{\theta_{hist}})^2}{N_{hist}-1}}$
            \State $w_{est} \gets atan \left(\frac{\sigma_{hist}}{\sigma_{est_{hist}}} \right)$
            \State $\theta_{corr} \gets (w_{est}*\overline{\theta_{hist}}) + ((1-w_{est})*\theta_{hist}[last])$
            \If{$\sigma_{hist} > \sigma_{bored}$}
                \State $i_{bored} \gets 0$ \Comment{Keep being excited}
            \Else
                \State $i_{bored} \gets i_{bored} + 1$  \Comment{Starting to get bored}
            \EndIf
        \EndIf
        \State return $\theta_{corr}$
        \caption{$merge\_theta$ function.}\label{alg:mergedoa}
    \end{algorithmic}
\end{algorithm}

\newpage

