\section{Preliminaries}\label{Section: Preliminaries}


All sets, functions and maps in this paper are assumed to be definable in a polynomially bounded o-minimal structure over $\mathbb{R}$ with the field of exponents $\mathbb{F}$, for example, real semialgebraic or subanalytic (see \cite{LvandenDRIES98} and \cite{DRIES-SPREISSEGGER}). Unless the contrary is explicitly stated, we consider germs at the origin of all sets and maps.

\subsection{Basic concepts in Lipschitz geometry}\label{Subsec: Holder triangles}

We present the necessary nomenclature and requisites in Lipschitz geometry of germs for the proper understanding of this paper. Most of the preliminaries used in the subsection are included with much more details in the survey paper \cite{livro}.

\begin{Def}\label{DEF: inner, outer and normally embedded}
	 Given a germ at the origin of a set  $X\subset \mathbb{R}^{n}$ we can define two metrics on $X$, the \textbf{outer metric}  $d(x,y)=||x-y||$ and the \textbf{inner metric} $d_{i}(x,y)=\inf_{\alpha}\{l(\alpha)\}$, where $l(\alpha)$ is the length of a rectifiable path $\alpha$ from $x$ to $y$ in $X$. Note that such a path $\alpha$ always exists since $X$ is definable. A set $X \subset \R^{n}$ is \textbf{Lipschitz normally embedded} (\textbf{LNE} for short) if the outer and inner metrics are equivalent.
\end{Def}

\begin{remark}
	 The inner metric is not definable, but it is equivalent to a definable metric (see \cite{KurdykaOrro97}), for example, the \textbf{pancake metric} (see \cite{LBirbMosto2000NormalEmbedding}).
\end{remark}


\begin{Def}\label{Def: arc}
		An \textbf{arc} in $\mathbb{R}^{n}$ is a germ at the origin of a mapping $\gamma \colon [0,\epsilon) \longrightarrow \mathbb{R}^{n}$ such that $\gamma(0) = 0$. Unless otherwise specified, we suppose that arcs are parameterized by the distance to the origin, i.e., $||\gamma(t)||=t$. We usually identify an arc $\gamma$ with its image in $\mathbb{R}^{n}$. For a germ at the origin of a set $X$, the set of all arcs $\gamma \subset X$ is denoted by $V(X)$ (known as the \textbf{Valette link of $X$}, see \cite{valette2007link}).
\end{Def}


\begin{Def}\label{DEF: order of tangency}
	 The \textbf{tangency order} of two arcs $\gamma_{1}$ and $\gamma_{2}$ in $V(X)$ (notation $\tord(\gamma_{1},\gamma_{2})$) is the exponent $q$ where $||\gamma_{1}(t) - \gamma_{2}(t)|| = ct^{q} + o(t^{q})$ with $c\neq 0$. By convention, $\operatorname{tord}(\gamma,\gamma)=\infty$. For an arc $\gamma$ and a set of arcs $Z \subset V(X)$, the tangency order of $\gamma$ and $Z$ (notation $\tord(\gamma, Z)$), is the supremum of $\tord(\gamma, \lambda)$ over all arcs $\lambda \in Z$. The tangency order of two sets of arcs $Z$ and $Z'$ (notation $\tord(Z,Z')$) is the supremum of $\tord(\gamma, Z')$ over all arcs $\gamma \in Z$. Similarly, we define the tangency orders in the inner metric of $X$, denoted by $\itord(\gamma_{1},\gamma_{2}),\; \itord(\gamma, Z)$ and $\itord(Z,Z')$.
\end{Def}

\begin{remark}\label{Rem: non-archimedean property}
	 An interesting fact about the tangency order of arcs in $\R^n$ is the so called ``non-archimedean property'' (it first appeared in \cite{B.F.METRIC-THEORY} as ``Isosceles property''): given arcs $\gamma_1,\gamma_2,\gamma_3$ in $\R^n$, we have $$\tord(\gamma_2,\gamma_3) \ge \min(\tord(\gamma_1,\gamma_2),\tord(\gamma_1,\gamma_3)).$$ If $\tord(\gamma_1,\gamma_2)\ne \tord(\gamma_1,\gamma_3)$ then $\tord(\gamma_2,\gamma_3) = \min(\tord(\gamma_1,\gamma_2),\tord(\gamma_1,\gamma_3))$.
\end{remark}

\begin{Def}\label{DEF: standard Holder triangle}
	 For $\beta \in \mathbb{F}$, $\beta \ge 1$, the \textbf{standard $\beta$-H\"older triangle} $T_\beta\subset\R^2$ is the germ at the origin of the set
	\begin{equation*}
		T_\beta = \{(x,y)\in \R^2 \mid 0\le x\le 1, \; 0\le y \le x^\beta\}.
	\end{equation*}
	The curves $\{x\ge 0,\; y=0\}$ and $\{x\ge 0,\; y=x^\beta\}$ are the  \textbf{boundary arcs} of $T_\beta$.

    For $\beta \in \mathbb{F}$, $\beta \ge 1$, the \textbf{standard  $\beta$-horn}  $H_\beta\subset\R^2$ is the germ at the origin of the set
	\begin{equation*}\label{Formula:Standard Holder triangle}
		H_\beta = \{(x,y,z)\in \R^3 \mid z\ge 0, \; x^2+y^2=z^{2\beta}\}.
	\end{equation*}
\end{Def}

\begin{Def}\label{DEF: Holder triangle}
	 A germ at the origin of a set $T \subset \mathbb{R}^{n}$ that is bi-Lipschitz equivalent with respect to the inner metric to the standard $\beta$-H\"older triangle $T_\beta$ is called a \textbf{$\beta$-H\"older triangle} (see \cite{birbrair1999local}).
	The number $\beta \in \mathbb{F}$ is called the \textbf{exponent of $T$} (notation $\beta=\mu(T)$). The arcs $\gamma_{1}$ and $\gamma_{2}$ of $T$ mapped to the boundary arcs of $T_\beta$ by the homeomorphism are the \textbf{boundary arcs of $T$} (notation $T=T(\gamma_{1},\gamma_{2})$). All other arcs of $T$ are \textbf{interior arcs}. The set of interior arcs of $T$ is denoted by $I(T)$.

    A germ at the origin of a set $H \subset \mathbb{R}^{n}$ that is bi-Lipschitz equivalent with respect to the inner metric to the standard $\beta$-horn $H_\beta$ is called a \textbf{$\beta$-horn} (see \cite{birbrair1999local}).
	The number $\beta \in \mathbb{F}$ is called the \textbf{exponent of $H$} (notation $\beta=\mu(H)$).
\end{Def}

\begin{remark}\label{Rem: NE HT condition}
	It was proved in \cite{birbrair1999local} that $\mu(T)$ and $\mu(H)$ are inner bi-Lipschitz invariants. Moreover, it was proved in \cite{birbrair2018arc}, using the Arc Selection Lemma (see Theorem 2.2), that a H\"older triangle $T$ is Lipschitz normally embedded if, and only if, $\tord(\gamma,\gamma')=\itord(\gamma,\gamma')$ for any two arcs $\gamma$ and $\gamma'$ of $T$.
\end{remark}

\begin{Def}\label{DEF: Lipschitz non-singular arc}
	 Let $X$ be a surface (a two-dimensional set). An arc $\gamma \subset X$ is \textbf{Lipschitz non-singular} if there exists a Lipschitz normally embedded H\"older triangle $T \subset X$ such that $\gamma$ is an interior arc of  $T$ and $\gamma \not\subset \overline{X\setminus T}$. Otherwise, $\gamma$ is \textbf{Lipschitz singular}. In particular, any interior arc of a Lipschitz normally embedded H\"older triangle is Lipschitz non-singular. The union of all Lipschitz singular arcs in $X$ is denoted by $\Lsing(X)$.
\end{Def}

\begin{remark}\label{Rem: boundary arcs are Lips sing arcs}
	 It follows from pancake decomposition (see Definition \ref{Def: pancake decomposition}) that a surface $X$ contains finitely many Lipschitz singular arcs. For an interesting example of a Lipschitz singular arc see Example 2.11 of \cite{GabrielovSouza}. Arcs which are boundary arcs of H\"older triangles or self-intersections of the surface are trivial examples of Lipschitz singular arcs.
\end{remark}


\begin{Def}\label{DEF: non-singular Holder triangle}
	 A H\"older triangle $T$ is \textbf{non-singular} if all interior arcs of $T$ are Lipschitz non-singular.
\end{Def}

\begin{Def}\label{Def: generic arc of a surface}
	 Let $X$ be a surface germ with connected link. The \textbf{exponent $\mu(X)$ of $X$} is defined as $\mu(X)=\min\, \itord(\gamma,\gamma')$, where the minimum is taken over all arcs $\gamma,\,\gamma'$ of $X$.
	A surface $X$ with exponent $\beta$ is called a $\beta$-surface. An arc $\gamma \subset X\setminus \Lsing(X)$ is \textbf{generic} if $\itord(\gamma,\gamma') = \mu(X)$ for all arcs $\gamma'\subset \Lsing(X)$. The set of generic arcs of $X$ is denoted by $G(X)$. 
\end{Def}


\begin{remark}\label{Rem: generic arcs of a non-singular HT}
	 If $X=T(\gamma_{1},\gamma_{2})$ is a non-singular $\beta$-H\"older triangle then an arc $\gamma\subset X$ is generic if, and only if, $\itord(\gamma_{1},\gamma) = \itord(\gamma,\gamma_{2}) = \beta$. 

     Let $X$ be the standard $\beta$-H\"older triangle for some $\beta\ge 1$ in $\F$. For any $n\in \N$, $n\ge 2$, the arcs $\delta_n(t) = \dfrac{x^\beta}{n}$ are generic arcs of $X$, although the sequence $\{\delta_n\}_{n=2}^{\infty}$ converges to the boundary arc $\{x\ge 0, \; y=0\}$. Similarly, $\{\tilde \delta_n\}_{n=2}^{\infty}$, where $\tilde \delta_n(t) = \left(1 - \dfrac{1}{n}\right)x^\beta$, is a sequence of generic arcs of $X$ converging to the boundary arc $\{x\ge 0, \; y=x^\beta\}$. Since inner tangency orders are preserved by inner bi-Lipschitz homeomorphisms, this argument proves that for any given H\"older triangle $X$ there exists a sequence of its generic arcs converging to one of its boundary arcs.


     %ESCREVER COM O TRIÂNGULO STARDARD A VERSÃO SIMPLIFICADA E DIZER QUE ESSA É CONSEQUENCIA, POIS LIPEO INNER PRESERVA ITORD. Moreover, we can define a sequence of generic arcs ``converging'' to the boundary arc $\gamma_1$ as follows: For each $n \in \mathbb{N}$, let $c_n>0$ and $a_n: \R_+\to \R$ such that $a_n(t)= c_n+o(1)$. Then, we consider a sequence $\{\delta_n\}_{n\in \mathbb{N}}$ of generic arcs in $X$ by setting, for all $n \in \mathbb{N}$ and $t>0$, $\delta_n(t)$ as the only point in $X\cap \{x\in \mathbb{R}^n : \|x\|=t\}$ such that $d_i(\gamma_1(t),\delta(t))=a_n(t)\cdot d_i(\gamma_1(t),\gamma_2(t))$. Note that $\itord(\gamma_{1},\delta_n) = \itord(\delta_n,\gamma_{2}) = \beta$. It is worth mentioning that the condition $a_n(t)= c_n+o(1)$ is necessary to have $\delta_n \in G(X)$, because if $a_n(t)=c_nt^{\theta}+o(t^{\theta})$, for some $\theta>0$, then $itord(\gamma_1,\delta_n)=\beta+\theta>\mu(X)$, and thus $\delta_n$ is not generic.
\end{remark}























\subsection{Zones, abnormal surfaces and snakes}\label{subsec 1.4}

Some of the definitions below were first introduced in \cite{LevMendes2018}, while the definition of snake is given in \cite{GabrielovSouza}. %Those concepts will be necessary to investigate the outer Lipschitz geometry of surface germs (in particular, snakes and circular snakes) and their minimal pancake decompositions.

\begin{Def}\label{Def: zone}
	A nonempty set of arcs $Z \subset V(X)$ is a \textbf{zone} if, for any two distinct arcs $\gamma_{1}$ and $\gamma_{2}$ in $Z$, there exists a non-singular H\"older triangle $T=T(\gamma_{1},\gamma_{2}) \subset X$ such that $V(T) \subset Z$. If $Z = \{\gamma\}$ then $Z$ is a \textbf{singular zone}.
\end{Def}



\begin{Def}\label{Def: maximal zone in}
	Let $B \subset V(X)$ be a nonempty set. A zone $Z\subset B$ is \textbf{maximal in} $B$ if, for any H\"older triangle $T$ such that $V(T) \subset B$, one has either $Z\cap V(T)=\emptyset$ or $V(T) \subset Z$.
\end{Def}

\begin{remark}
	A zone could be understood as an analog of a connected subset of $V(X)$, and a maximal zone in a set $B$ is an analog of a connected component of $B$.
\end{remark}


\begin{Def}\label{Def:order of zone}
	The \textbf{order} $\mu(Z)$ of a zone $Z$ is defined as the infimum of $\operatorname{tord}(\gamma,\gamma')$ over all arcs $\gamma$ and $\gamma'$ in $Z$. If $Z$ is a singular zone, we define $\mu(Z) = \infty$. A zone $Z$ of order $\beta$ is called a $\beta$-zone.
\end{Def}

\begin{remark}
	The tangency order can be replaced by the inner tangency order in Definition \ref{Def:order of zone}. Note that, for any arc $\gamma \in Z$, $\inf_{\gamma'\in Z}\operatorname{tord}(\gamma,\gamma')=\inf_{\gamma'\in Z}\itord(\gamma,\gamma')=\mu(Z)$. Moreover, differently from Definition \ref{Def: generic arc of a surface}, the order of a zone could not be a minimum (for such an example, see Example 2.46 of \cite{GabrielovSouza}).
\end{remark}

\begin{Def}\label{Def: LNE zone}
	A zone $Z$ is LNE if, for any two arcs $\gamma$ and $\gamma'$ in $Z$, there exists a LNE H\"older triangle $T=T(\gamma,\gamma')$ such that $V(T)\subset Z$.
\end{Def}

\begin{Def}\label{DEF: normal and abnormal arcs and zones}
	A Lipschitz non-singular arc $\gamma$ of a surface germ $X$ is \textbf{abnormal} if there are two LNE H\"older triangles $T\subset X$ and $T'\subset X$ such that $T\cap T' = \gamma$ and $T\cup T'$ is not LNE.
	Otherwise $\gamma$ is \textbf{normal}. A zone is \textbf{abnormal} (resp., \textbf{normal}) if all of its arcs are abnormal (resp., normal). The sets of abnormal and normal arcs of $X$ are denoted by $Abn(X)$ and $Nor(X)$, respectively. A surface germ $X$ is called \textbf{abnormal} if $Abn(X)=G(X)$.
\end{Def}

\begin{Def}\label{Def: maximal abnormal and normal zones}
	Given an abnormal (resp., normal) arc $\gamma \subset X$, the \textbf{maximal abnormal zone} (resp., \textbf{maximal normal zone}) in $V(X)$ containing $\gamma$ is the union of all abnormal (resp., normal) zones in $V(X)$ containing $\gamma$. Alternatively, the maximal abnormal (resp., normal) zone containing $\gamma$ is a maximal zone in $Abn(X)$ (resp., $Nor(X)$) containing $\gamma$.
\end{Def}

\begin{remark}\label{max zones are unique}
	It follows from Definition \ref{DEF: normal and abnormal arcs and zones} that the property of an arc to be abnormal (resp., normal)
	is an outer bi-Lipschitz invariant: if $h:X\to X'$
	is an outer bi-Lipschitz map then $h(\gamma)\subset X'$ is an abnormal (resp., normal) arc for any abnormal (resp., normal) arc $\gamma\subset X$.
	Since the property of an arc to be abnormal (resp., normal) is outer Lipschitz invariant,
	maximal abnormal (resp., normal) zones in $V(X)$ are also outer Lipschitz invariant: if $h:X\to X'$
	is an outer bi-Lipschitz map then $h(Z)\subset V(X')$ is a maximal abnormal (resp., normal) zone for any maximal abnormal (resp., normal) zone $Z\subset V(X)$. Here, $h: V(X) \to V(X') $ denotes the natural action of $h$ on the space of arcs in $X$.

\end{remark}

\begin{Def}\label{Def:snake}
	A non-singular $\beta$-H\"older triangle $T$ is called a $\beta$\textbf{-snake} if $T$ is an abnormal surface (see Definition \ref{DEF: normal and abnormal arcs and zones}). Similarly, a non-singular $\beta$-horn $X$ is called a $\beta$\textbf{-circular snake} if $X$ is an abnormal surface.
\end{Def}



\subsection{Segments, nodal zones and weakly outer bi-Lipschitz maps}\label{Subsection: weak equivalence}

In this subsection we summarize the concepts of segments and nodal zones of snakes and circular snakes. We also recall how those invariant parts of the Vallete link of an abnormal surface are used to obtain the classification theorems summarized in Theorem \ref{Teo:weak equivalence}. Roughly speaking, the segments are zones where we have space to move an arc to both sides without changing the Lipschitz contact (this notion is translated through the multiplicity of this arc) of the surface with itself, while the nodal zones are the zones where this cannot be done. Since segments and nodal zones are canonical up outer bi-Lipschitz homeomorphisms, given an orientation we could use them to associate a word with a snake (resp., a circular snake). This word is the combinatorial object used in Theorem \ref{Teo:weak equivalence}.

%{\color{red} REESCREVER ISSO AQUI PASSANDO ESSA EXPLICAO INFORMAL} These notions on the Valette link can be seen, in some sense, as an analogue to lines and points on a curve, where we ``join'' arcs with tangency order bigger than the exponent of the snake in nodes. To formalize those analogies, we establish the definitions of weakly outer bi-Lipschitz maps and cluster partitions and relate them in Theorem \ref{Teo:weak equivalence}. We also give examples to describe snakes and circular snakes with their words, which are combinatorial objects that capture the weakly outer Lipschitz geometry of them.

\begin{Def}\label{Def:horn-neighbourhood}
	 Let $X$ be a surface and $\gamma \subset X$ an arc. For $a>0$ and $1\leq\alpha\in \mathbb{F}$, the \textbf{$(a,\alpha)$-horn neighborhood of $\gamma$ in $X$} is defined as follows: 
 $$
 \mathcal{H}X_{a,\alpha}(\gamma) = \bigcup_{0\le t \ll1} X\cap S(0,t)\cap \overline{B}(\gamma(t),at^{\alpha}),
 $$
	where $S(0,t)=\{x \in \mathbb{R}^{n}\mid ||x||=t\}$ and $\overline{B}(y,R) = \{x \in \mathbb{R}^{n}\mid ||x - y||\le R\}$.
\end{Def}

\begin{Def}\label{Def of multiplicity}
	 If $X$ is a $\beta$-snake (or circular $\beta$-snake) and $\gamma$ an arc in $X$, the \textbf{multiplicity} of $\gamma$, denoted by $m_{X}(\gamma)$ (or just $m(\gamma)$, when $X$ is understood), is defined as the number of connected components of the set $\mathcal{H}X_{a,\beta}(\gamma)\setminus \{0\}$, for every $a>0$ small enough.
\end{Def}

\begin{Def}\label{constant zone}
    Let $X$ be a $\beta$-snake (or circular $\beta$-snake) and $Z\subset V(X)$ a zone. We say that $Z$ is a \textbf{constant zone of multiplicity $q$} if all arcs in $Z$ have the same multiplicity $q$. We say that $\gamma \in V(X)$ is a \textbf{segment arc} if there exists a $\beta$-H\"older triangle $T \subset X$ such that $\gamma$ is a generic arc of $T$ and $V(T)$ is a constant zone. Otherwise $\gamma$ is a \textbf{nodal arc}. We denote the set of segment arcs and the set of nodal arcs in $X$ by $S(X)$ and $N(X)$, respectively. A \textbf{segment of $X$} is a maximal zone in $S(X)$. A \textbf{nodal zone} of $X$ is a maximal zone in $N(X)$. We write $Seg_{\gamma}$ or $Nod_{\gamma}$ for a segment or a nodal zone containing an arc $\gamma$.
\end{Def}


\begin{remark}\label{Rem:words}
	It was proved in \cite{GabrielovSouza} (resp., in \cite{circular-snakes}) that if $X$ is a snake (resp., circular snake) then its Valette link can be decomposed into finitely many disjoint segments and nodal zones. For snakes the segments and nodal zones are always LNE, while for circular snakes we may have segments not LNE, althoug this only happens for the ones without nodal zones. 

    Using this decomposition the authors in \cite{GabrielovSouza} (resp., in \cite{circular-snakes}) created a combinatorial object, $W(X)$ (resp., $[[W_N(X)]]$, where $N$ is a given nodal zone of $X$), associated with such snake (resp., circular snake) $X$. More specifically, $W(X)$ (resp., $W_N(X)$ is a word (resp., circular word), in some alphabet, say $\{x_1, x_2,\ldots \}$, satisfying two conditions (see Definitions 6.6 in \cite{GabrielovSouza} and 5.9 in \cite{circular-snakes}). Any word satisfying those conditions is called a \textbf{snake name} (resp., \textbf{circular snake name}) and it was proved that, for any snake name $W$ (resp., circular snake name $W_N$) with length $m>3$ (resp., lenght $m\ge 5$), there is a snake (resp., circular snake) $X$ such that $W = W(X)$ (resp., $W=W_N(X)$) (see Theorems 6.23 in \cite{GabrielovSouza} and 7.10 in \cite{circular-snakes}).

    Theorems 6.23 in \cite{GabrielovSouza} and 7.10 in \cite{circular-snakes} are realization theorems. Along this text we will be giving examples of snakes and circular snakes presenting only their links, however, since the word associated with a snake (resp., circular snake) can be easily obtained from its link, the existence of a snake (resp., circular snake) with the given link is guaranteed by those theorems. 

    %In \cite{circular-snakes}, Costa, Medeiros and Souza proved that every circular snake with at least one nodal zone has a cyclic decomposition into segments and nodal zones. They created a combinatorial object, $[[W_N(X)]]$, associated with a circular snake $X$ with nodal zones. More specifically, given a nodal zone $N$ of $X$, $[[W_N(X)]]$ is an equivalence class of words, in some alphabet, say $\{x_1, x_2,\ldots \}$, satisfying cyclic conditions (see Definition 6.10 in \cite{circular-snakes}). Any equivalence class satisfying those conditions is a \textbf{circular snake name} and they proved that, for any circular snake name $W$ with length $m\ge 5$, there is a circular snake $X$, an orientation for it and a nodal zone $N$ of $X$ such that $W = W_N(X)$ (see Theorem 7.10 in \cite{circular-snakes}).
\end{remark}

\begin{Exam}\label{Exam:snake-name-construction}
	In this example we illustrate how to associate a word $W(X)$ with a snake $X = T(\gamma_{1},\gamma_{2})$. Let $X$ be a snake with link as in Figure \ref{Fig. snake word}. Recall that a \textbf{node} of $X$ is the union of nodal zones with tangency orders higher than $\mu(X)$ (see Definition 4.31 of \cite{GabrielovSouza}). First, we choose an orientation for $X$, say from $\gamma_{1}$ to $\gamma_{2}$. Second, we assign letters to the nodes by moving through the link of $X$, respecting this orientation, in a way that the first node encountered is assigned to the first letter of the alphabet and so on, skipping the nodes already assigned. Finally, we obtain the word associated with $X$ by traversing the link again, accordingly to the orientation, adding a letter every time we pass through a node. In this case, in the alphabet $\{x_1, x_2,\ldots \}$, we have $W(X) = [x_1x_2x_1x_3x_2x_3]$.

