The (circular) words associated with (circular) snakes ignores many geometric properties of them such as the contact orders of arcs in a same node. Still, it is an interesting Lipschitz invariant combinatorial object, since it is possible to create a weaker notion of outer bi-Lipschitz homeomorphism for which those words are preserved.

\begin{Def}\label{Def:weak equivalence}
Let $h:X\to X'$ be an inner bi-Lipschitz map between two $\beta$-surfaces $X$ and $X'$. We say that $h$ is \textbf{weakly outer bi-Lipschitz} when, for any two arcs $\gamma$ and $\gamma'$ of $V(X)$, we have
$$
\tord(h(\gamma),h(\gamma'))>\beta \iff \tord(\gamma,\gamma')>\beta.
$$
% $\tord(h(\gamma),h(\gamma'))>\beta$ if, and only if, $\tord(\gamma,\gamma')>\beta$.
If such a homeomorphism exists, we say that $X$ and $X'$ are \textbf{weakly outer Lipschitz equivalent}.
\end{Def}

\begin{Def}\label{Def: clusters}
Let $\mathcal{N}$ and $\mathcal{N}'$ be nodes of a $\beta$-snake (or a circular $\beta$-snake) $X$, and let $\mathcal{S}(\mathcal{N},\mathcal{N}')$ be the (possibly empty) set of all segments of $X$ having adjacent nodal zones in the nodes $\mathcal{N}$ and $\mathcal{N}'$. Two segments $S$ and $S'$ in $\mathcal{S}(\mathcal{N},\mathcal{N}')$ belong to the same \textbf{cluster}
if $\tord(S,S')>\beta$. This defines a \textbf{cluster partition} of $\mathcal{S}(\mathcal{N},\mathcal{N}')$.
The size of each cluster $C$ of this partition is equal to the multiplicity of each segment $S\in C$ (see Definition \ref{Def of multiplicity}).
\end{Def}

We are now ready to describe when two $\beta$-snakes (or circular $\beta$-snakes with nodal zones) are weakly outer Lipschitz equivalent. For $\beta$-snakes, this is Theorem 6.28 of \cite{GabrielovSouza}; for circular $\beta$-snakes with nodal zones, this is Theorem 8.3 of \cite{circular-snakes}. For the special case of circular $\beta$-snakes without nodal zones, Theorem \ref{Teo:Multiplicity without Nodes} is Theorem 8.4 of \cite{circular-snakes}.

\begin{Teo}[Theorem 8.3 in \cite{circular-snakes}]\label{Teo:weak equivalence}


Two $\beta$-snakes $X$ and $X'$ with nodal zones (or circular $\beta$-snakes with nodal zones) are weakly outer Lipschitz equivalent if, and only if, they can be oriented so that
\begin{enumerate}
\item[(i)] They have the same (circular) snake names, the nodes $\mathcal{N}_1,\ldots,\mathcal{N}_n$ of $X$ are in one-to-one correspondence with the nodes
$\mathcal{N}'_1,\ldots,\mathcal{N}'_n$ of $X'$ (with $\mathcal{N}_i$ corresponding to $\mathcal{N}'_i$, for each $i$), and the nodal zones $N_1,\ldots,N_m$ of $X$ are in one-to-one correspondence with the nodal zones $N'_1,\ldots,N'_m$ of $X'$ (with $N_i$ corresponding to $N'_i$, for each $i$);
\item[(ii)] For any two nodes $\mathcal{N}_j$ and $\mathcal{N}_k$ of $X$, and the corresponding nodes $\mathcal{N}'_j$ and $\mathcal{N}'_k$ of $X'$,
each cluster of the cluster partition of the set $\mathcal{S}(\mathcal{N}'_j,\mathcal{N}'_k)$ (see Definition \ref{Def: clusters}) consists
of the segments of $X'$ corresponding to the segments of $X$ contained in a cluster of the cluster partition of the set $\mathcal{S}(\mathcal{N}_j,\mathcal{N}_k)$. 
\end{enumerate}
\end{Teo}

\begin{Teo}[Theorem 8.4 in \cite{circular-snakes} ]\label{Teo:Multiplicity without Nodes}
Let $X$ and $X'$ be two circular $\beta$-snakes without nodal zones. Then, $X$ and $X'$ are weakly outer Lipschitz equivalent if, and only if, $X$ and $X'$ have the same multiplicity.
\end{Teo}

\section{Pancake decomposition of surfaces}\label{section:pancake decomposition}

In this section, we give the definitions of a pancake decomposition and the corresponding concepts of minimal and reduced decompositions. We present the definition of weakly bi-Lipschitz equivalence of pancake decompositions aiming to obtain later, in Section \ref{Sec: Weakly canonicity}, a minimal decomposition which is canonical with respect to this equivalence. We also give an example showing that not all reduced decompositions are minimal, which explicitly shows the need for a more sophisticated algorithm to find minimal pancake decompositions in a canonical way.

\begin{Def}\label{Def: pancake decomposition}
	 Let $X\subset \mathbb{R}^{n}$ be the germ at the origin of a closed set. A \textbf{pancake decomposition of $X$} is a finite collection of closed LNE subsets $X_{k}$ of $X$ with connected links, called \textbf{pancakes}, such that $X=\bigcup X_{k}$ and $$\dim(X_{j}\cap X_{k}) < \min(\dim(X_{j}),\dim(X_{k}))\quad\text{for all}\; j,k.$$
\end{Def}

\begin{remark}\label{Rem: existence of pancake decomp}
	 The term ``pancake'' was introduced in \cite{LBirbMosto2000NormalEmbedding}, but this notion first appeared (with a different name) in \cite{kurdyka1992subanalytic} and \cite{KurdykaOrro97}, where the existence of such a decomposition was established.
\end{remark}

\begin{remark}\label{Rem:pancake of holder triangle is holder triangle}
	 If $X$ is a H\"older triangle and $\{X_k\}_{i=1}^p$ is its pancake decomposition, then each pancake $X_k$ is also a H\"older triangle. Moreover, if $X$ is a non LNE surface germ and has circular link, then $p>1$ and each pancake is also a H\"older triangle.  
\end{remark}


\begin{Def}\label{Def: reduced pancak decomp}
	 A pancake decomposition $\{X_{k}\}_{i=1}^{p}$ of a set $X$ is \textbf{reduced} if the union of any two adjacent pancakes $X_{j}$ and $X_{k}$ (such that $X_{j}\cap X_{k}\ne \{0\}$) is not LNE. We also say that $\{X_{k}\}_{i=1}^{p}$ is \textbf{minimal} if $p$ is minimal among all pancake decompositions of $X$.
\end{Def}

\begin{remark}\label{Rem: reduced PD always exists}
	 When the union of two adjacent pancakes is LNE, they can be replaced by their union, reducing the number of pancakes. Thus, a reduced pancake decomposition of a set $X$ always exists. Moreover, every minimal pancake decomposition of $X$ is reduced, but the converse is false, as seen in Example \ref{Exam: two non-equiv decomp}. This example also shows that it is not possible, in general, to obtain a minimal pancake decomposition from a reduced one.
\end{remark}

Since every set $X$ can be decomposed into a finite number of pancakes (see \cite{kurdyka1992subanalytic}, \cite{KurdykaOrro97} and \cite{LBirbMosto2000NormalEmbedding}), a minimal pancake decomposition of $X$ always exists. However, one may wonder if there is a constructive way to find such a decomposition, and if such a construction is canonical. For snakes and circular snakes, we give an affirmative answer, but first, we must define weakly bi-Lipschitz equivalence between pancake decompositions.

\begin{Def}\label{Def: equiv of pancake decomp}
    Let $X, \tilde X$ be two surfaces and let $\{X_i\}_{i\in I}$, $\{\tilde X_j\}_{j\in J}$ be pancake decompositions of $X$ and $\tilde X$, respectively. We say that $\{X_i\}_{i\in I}$ and $\{\tilde X_j\}_{j\in J}$ are \textbf{weakly outer bi-Lipschitz equivalent} pancake decompositions for $X$ and $\tilde X$ if there is a bijection $\sigma \colon I \rightarrow J$ and a weakly outer bi-Lipschitz map $h\colon X \rightarrow \tilde X$ such that $h(X_i) = \tilde X_{\sigma(i)}$ for all $i\in I$.
\end{Def}

\begin{Exam}\label{Exam: two non-equiv decomp}
    In Figure \ref{Fig. two non-equiv decompositions} we have the link of an abnormal $\beta$-surface $X$ and the representation of two of its reduced pancake decompositions, denoted by $\{X_j = T(\lambda_{j-1},\lambda_j)\}_{j=1}^2$ and $\{\tilde X_j = T(\tilde \lambda_{j-1},\tilde \lambda_j)\}_{j=1}^3$. Clearly such decompositions are not weakly bi-Lipschitz equivalent (See Definition \ref{Def: equiv of pancake decomp}), since the number of pancakes is different (See Proposition \ref{Prop: canonical-snakes}). This example shows that a reduced decomposition is not necessarily minimal. Moreover, it shows that it is not always possible to obtain a minimal pancake decomposition from a given pancake decomposition by joining LNE adjacent pancakes into a single new pancake, as described in Remark \ref{Rem: reduced PD always exists}.
\end{Exam}

