In the rest of this section, let $X=T(\gamma_1, \gamma_2)$ be a $\beta$-snake oriented from $\gamma_1$ to $\gamma_2$ and let $\{N_i\}_{i=0}^{m}$, $\{S_i\}_{i=1}^m$ be the decomposition of the $V(X)$ into nodal zones and segments, respectively, as in Definition \ref{Def: minimal sequence}, enumerated accordingly to the given orientation.

\begin{Lem}\label{Lem: tord segments and nodal zones}
    For every $i \in \{0,1,\dots,m\}$, $j\in \{1,\dots,m\}$ such that $j \ne i, i+1$,we have $\operatorname{tord}(N_i,S_j) = \beta.$
\end{Lem}
\begin{proof}
    By Proposition 4.27 of \cite{GabrielovSouza}, given $\gamma \in N_i$, if $\itord(\gamma,\gamma') >\beta$ then $\gamma' \in N_i$, for any $\gamma'\in V(X)$. Thus, since $S_j\cap N_i= \emptyset$ for all $j\ne i, i+1$, we must have $\operatorname{tord}(S_i,N_j) = \beta$. 
\end{proof}

\begin{Lem}\label{Lem: segments gr beta implies adj nodal z gr beta}
   Let $S, S'$ be distinct segments of $X$ and let $N,\tilde N$ and $N',\Tilde{N'}$ be nodal zones adjacent to $S$ and $S'$, respectively. Assume that $\operatorname{tord}(\tilde N, \tilde N') >\beta$ and $\operatorname{tord}(S,S')>\beta$. Then $\operatorname{tord}(N,N')>\beta$.
\end{Lem}
\begin{proof}
    Suppose that $N$ and $N'$ are on nodes $\mathcal{N}$ and $\mathcal{N}'$, respectively. We have $\operatorname{tord}(\tilde N, \tilde N') >\beta$, implying that $\tilde N$ and $\tilde N'$ are in the same node $\tilde{\mathcal{N}}$. Since $\operatorname{tord}(S,S')>\beta$, $S$ and $S'$ belongs to the same cluster of $\mathcal{S}(\tilde{\mathcal{N}},\mathcal{N})$ and the same cluster of $\mathcal{S}(\tilde{\mathcal{N}},\mathcal{N}')$. Therefore, $\mathcal{N}=\mathcal{N}'$ by Proposition 4.59 of \cite{GabrielovSouza} and the result follows.
\end{proof}

\begin{remark}
    Lemmas \ref{Lem: tord segments and nodal zones} and \ref{Lem: segments gr beta implies adj nodal z gr beta} are also true when $X$ is a circular snake with nodal zones, and their respective proofs are analogous.
\end{remark}


\begin{Teo}\label{Teo: minimal pancake decomposition}
    Let $\{j_0,j_1,\dots,j_p\}$ be the minimal sequence of $X$. Consider the following decomposition of $X$ into H\"older triangles $\{X_i\}_{i=1}^{p+1}$, with $X_i = T(\lambda_{i-1},\lambda_i)$ defined recursively as follows: 
    \begin{enumerate}
        \item set $\lambda_0 = \gamma_1$ and choose any $\lambda_1 \in S_{j_1}$;
        \item for all $1<i\le p$, choose $\lambda_i \in S_{j_i}$ such that $\mathcal{H}(X_i)_{a,\mu(X)}(\lambda_i)\setminus\{0\}$ consists in only one connected component, for $a>0$ small enough;
        \item set $\lambda_{p+1}=\gamma_2$.
    \end{enumerate}
    Then,  $\{X_i\}_{i=1}^{p+1}$ is a minimal pancake decomposition of $X$. 
\end{Teo}


\begin{proof}
    Choosing any $\lambda_1$ in $S_{j_1}$ we obtain that $X_1$ is LNE, otherwise, it follows from the condition on the construction of the minimal sequence and Lemma \ref{Lem: tord segments and nodal zones} that $\operatorname{tord}(S_k, S_{j_1})>\beta$, for some segment $S_k$ where $j_0 < k < j_1$. However, Lemma \ref{Lem: segments gr beta implies adj nodal z gr beta} implies that there would exist a nodal zone $N_l$, adjacent to the segment $S_k$, with $0\le l<j_1$, where $\operatorname{tord}(N_l,N_{j_1 - 1})>\beta$, a contradiction with the minimality of $j_1$ in the minimal sequence of $X$. 

    If $\operatorname{tord}(S_{j_2},S_{j_1})=\beta$, then any arc $\lambda_2 \in S_{j_2}$ clearly satisfies $(2)$ and a similar argument shows that $X_2$ is LNE. If $\operatorname{tord}(S_{j_2}, S_{j_1})>\beta$, we must be careful when choosing $\lambda_2 \in S_{j_2}$ (see Figure \ref{Fig: Condition (2) of Theorem}). In this case we necessarily have $\operatorname{tord}(N_{j_1},N_{j_2})>\beta$. Notice that the nodal zones adjacent to $S_{j_2}$ are $N_{j_2}$ and $N_{j_2 - 1}$. Let $\lambda'_1 \in S_{j_2}$ be an arc such that $\operatorname{tord}(\lambda_1,\lambda'_1)>\beta$. Given an arc $\theta_{j_2 - 1} \in N_{j_2 - 1}$ we have $\lambda_2 \in G(T(\theta_{j_2 - 1},\lambda'_1)) \subset S_{j_2}$ such that $\operatorname{tord}(\lambda_1, \mathcal{H}(X_2)_{a,\mu(X)}(\lambda_2)) = \beta$ for any $a>0$ small enough (the existence of such arcs $\lambda_2$ is guaranteed by taking a sequence of generic arcs of $T(\theta_{j_2 - 1},\lambda'_1)$ converging to $\theta_{j_2 - 1}$, see Remark \ref{Rem: generic arcs of a non-singular HT}). In particular, this implies that $\mathcal{H}(X_2)_{a,\mu(X)}(\lambda_2)\setminus\{0\}$, for $a>0$ small enough, has a single connected component. Hence, arcs satisfying condition $(2)$ do exist. If $\lambda_2$ is any arc in $S_{j_2}$ satisfying $(2)$, then, for any $\theta_{j_1} \in N_{j_1}$, $\operatorname{tord}(\lambda_2,T(\lambda_1, \theta_{j_1})) = \beta$. Thus $X_2=T(\lambda_1, \lambda_2)$ is LNE. Therefore, we proved in both cases that $X_2$ is LNE. The proof that $X_i$, $i>2$, is LNE follows analogously.  

