\end{proof}

\begin{Def}\label{Def: Greedy decomposition in Snakes}
    Any decomposition $\{X_i\}_{i=1}^{p+1}$ of a snake $X$ satisfying the properties of Theorem \ref{Teo: minimal pancake decomposition} is defined as a \textbf{greedy (pancake) decomposition of $X$.}
\end{Def}

