In the rest of this subsection, let $X$ be a $\beta$-snake with an orientation $\varepsilon$, $N=N_1$ be a initial nodal zone. Let $p$ and $q$ be the respective lengths of the fundamental and minimal sequences of $X$, and let $\{N_i\}_{i=1}^{m}$, $\{S_i\}_{i=1}^m$ be the decomposition of $V(X)$ into nodal zones and segments, respectively, as in Definition \ref{Def: minimal sequence-circular}.

\begin{Lem}\label{Lem: fundamental-minimal}
    Let $t\in \mathbb{Z}_{>0}$ such that $j_{k+p+1}=j_{k+1}+tm$. Then, $p\ge t(q-1)+1$.
\end{Lem}

\begin{proof}
    For each $1\le s\le t-1$, let $x_s$ be the minimum integer such that $j_{k+q}+(s-1)m+1\le j_{k+x_s+1}$ and let $y_s$ be the maximum integer such that $j_{k+y_s}\le j_{k+q}+sm$. Informally, we are looking at the indices $j_i$ that appear on the $s^{\rm th}$ lap on the link of $X$ (which contains $m$ of such indices, one for each nodal zone), starting from $j_{k+q}$ and following the orientation $\varepsilon$. Such indices are precisely $j_{k+x_s+1},\dots,j_{k+y_s}$. 

    The key observation is that, for every $1\le r \le q-1$, there is at least one index $l\in[x_s+1,y_s]$ such that $j_{k+r}+sm < j_{k+l}<j_{k+r+1}+sm$. If that was not the case, then by discrete continuity there is $\tilde l$ such that $j_{k+\tilde l}<j_{k+r}+sm <j_{k+r+1}+sm<j_{k+\tilde l+1}$ (we cannot have equality on each inequality, because otherwise the fundamental sequence of $X$ would have length lesser than $p$). However, this contradicts the minimality of $j_{k+\tilde l+1}$ with respect to $j_{k+\tilde l}$, since $T(\theta_{j_{k+\tilde l}},\theta_{j_{k+r+1}+sm})$ is not LNE, because $$T(\theta_{j_{k+r}},\theta_{j_{k+r+1}})=T(\theta_{j_{k+r}+sm},\theta_{j_{k+r+1}+sm})\subset T(\theta_{j_{k+\tilde l}},\theta_{j_{k+r+1}+sm})$$ and $T(\theta_{j_{k+r}},\theta_{j_{k+r+1}})$ is not LNE by construction. Therefore, the fundamental sequence $\{j_{k+1},\cdots,j_{k+p}\}$ has at least $q-1$ terms $j_{k+l}$ with $l\in[x_s+1,y_s]$. Since all intervals $[x_1+1,y_1], \dots, [x_{t-1}+1,y_{t-1}]$ are disjoint, we have at least $(t-1)(q-1)$ indices $j_{k+l}$ with $l>q$ in $\{j_{k+1},\cdots,j_{k+p}\}$. Counting with $j_{k+1},\dots,j_{k+q}$, we have $p\ge (t-1)(q-1)+q=t(q-1)+1$ and the lemma follows.
\end{proof}

\begin{Teo}\label{Teo:Minimal-pancake-circular-snakes-with-nodes}
Let $X$ be a circular $\beta$-snake with nodal zones, and let $\{\tilde j_{k+1}, \dots, \tilde j_{k+q}\}$ be its minimal sequence with respect to $(N,\varepsilon)$, for some nodal zone $N$ and orientation $\varepsilon$. Consider a cyclic sequence of arcs $\{\lambda_i\}_{i=1}^{q} \subset V(X)$ such that:
\begin{enumerate}
    \item For each $1 \leq i \leq q$, we have $\lambda_i \in S_{j_{k+i}}$;
    \item The arcs $\lambda_i$ are ordered so that the H\"older triangles $X_i = T(\lambda_i, \lambda_{i+1}) \subset X$, with $\lambda_{q+1} := \lambda_0$ have the orientation induced from $X$;
    \item For $1\le i\le q$, $\mathcal{H}(X_i)_{a,\mu(X)}(\lambda_{i+1})\setminus\{0\}$ consists in only one connected component, for every $a>0$ small enough.
\end{enumerate}
Then, the collection $\{X_i = T(\lambda_i, \lambda_{i+1})\}_{i=1}^{q}$ is a minimal pancake decomposition of $X$.
\end{Teo}

\begin{proof}
Note initially that, by the same argument in the proof of Theorem \ref{Teo: minimal pancake decomposition}, the arcs $\lambda_1,\dots,\lambda_q$ satisfying all three conditions indeed exist. The proof that each $X_i$ is LNE follows analogously from the respective proof in Theorem \ref{Teo: minimal pancake decomposition}, so it remains to prove that $\{X_i\}_{i=1}^{q}$ is a minimal pancake decomposition of $X$.

%We first prove that $\{X_i\}_{i=1}^{q}$ is a pancake decomposition of $X$. Suppose the contrary, i.e., there is $1 \le i \le q$ such that $X_i$ is not normally embedded. Let
%\(
%Z_i = \bigcup_{\ell = j_{k+i}}^{j_{k+i+1} - 2} \left( N_\ell \cup S_{\ell+1} \cup N_{\ell+1} \right),
%\)
%with indices taken modulo $m$. If $\operatorname{tord}(Z_i, S_{j_{k+i+1}}) > \beta$, then by Lemma~\ref{Lem: tord segments and nodal zones}, there exists an index $k' \in \{j_{k+i} + 1, \ldots,j_{k+i+1} - 1\}$ such that $\operatorname{tord}(S_{k'}, S_{j_{k+i+1}}) > \beta$. However, by Lemma~\ref{Lem: segments gr beta implies adj nodal z gr beta}, this would imply that the H\"older triangle $T(\theta_{j_{k+i}}, \theta_{k'})$ is not normally embedded, contradicting the minimality of $j_{k+i+1}$ in the minimal sequence of $X$. Therefore, $\operatorname{tord}(Z_i, S_{j_{k+i+1}}) = \beta$ and, by condition $(3)$, $X_i$ is normally embedded. Hence $\{X_i\}_{i=1}^{q}$ is a pancake decomposition of $X$.

We look initially at the case where $p=q$ i.e., the fundamental and minimal sequences coincide. Note that by the construction of the minimal sequence of $X$, the Valette link of a single pancake cannot intersect both nodal zones $N_{j_{k+i}}$ and $N_{j_{k+i+1}}$, for any $i = 1, \ldots, p$, since this would contradict normal embedding. Hence, each pancake can intersect at most one of the nodal zones $N_{k+j_i}$, and any pancake decomposition of $X$ must have at least $p$ pancakes. This shows that $\{X_i\}_{i=1}^{q}$ is a minimal pancake decomposition of the circular snake $X$ in this case, as $p=q$.

Consider now the case $q<p$ and let $t\in \mathbb{Z}_{>0}$ as in Lemma \ref{Lem: fundamental-minimal}. Let also $[[x_1x_2\dots x_mx_1]]$ be the circular snake name of $X$, with $x_1$ corresponding to the node containing $N=N_1$, and define $w=x_1x_2\dots x_m$. Consider $\tilde{X}$ as a circular $\beta$-snake whose circular snake name is $[[w\cdots wx_1]]$, where we concatenated $t$ copies of $w$ (such circular snake always exists, by Theorem 7.10 in \cite{circular-snakes}). Let $\{\tilde N_i\}_{i=1}^{tm}$ and $\{\tilde S_i\}_{i=1}^{tm}$ be the decomposition of the Valette link of $\tilde X$ into nodal zones and segments, respectively. Suppose that $\tilde N_{i-1}$, $\tilde N_{i}$ are the nodal zones adjacent to $\tilde S_i$, for each $i \in \mathbb{Z}$, where the indices are taken modulo $tm$. By the way we constructed its circular snake name (see Remark \ref{Rem: minimal-from-circular-name}), the fundamental and minimal sequences of $\tilde X$ coincide, and the fundamental sequence of $\tilde X$ is the same of $X$. Therefore, by the previous case, any minimal pancake decomposition of $\tilde X$ has $p$ elements. 

Suppose now that $X$ has a pancake decomposition with less than $q$ elements. Let $\{X_i'\}_{i=1}^{q-1}$ be such decomposition (one can subdivide any pancake to obtain exactly $q-1$ of them, if necessary), and suppose that $X_i'=T(\lambda_i',\lambda_{i+1}')$ have the orientation induced from $X$ (consider $\lambda_{q}'=\lambda_1'$). Suppose also that, for $i=1,\dots,q-1$, we have $\lambda_i' \in W_{s(i)}$, where $W_{s(i)}$ is either a segment $S_{s(i)}$ or a nodal zone $N_{s(i)}$ of $X$ (note that $1\le s(i)\le m)$. Now, for $i=1,\dots,t(q-1)$ with $i=r(i)+\ell(q-1)$ ($r(i)$ is the remainder of $i$ modulo $q-1$), define $\tilde{W}_i$ as either the nodal zone $\tilde{N}_{s(r(i))+\ell m}$ of $\tilde X$, if $W_{s(r(i))}$ is a nodal zone of $X$, or the segment $\tilde{S}_{s(r(i))+\ell m}$ of $\tilde X$, if $W_{r(i)}$ is a segment of $X$. Consider in $\tilde X$ the H\"older triangles $\tilde{X}_i'=T(\tilde{\lambda}_i',\tilde{\lambda}_{i+1}')$, where $\tilde{\lambda}_i' \in \tilde{W}_i$, for $1\le i\le t(q-1)$, and $\tilde{\lambda}_{t(q-1)+1}'=\tilde{\lambda}_1'$ (the orientation of $\tilde{X}_i'$ is induced from the orientation of $\tilde X$). Since $\{X'_i\}_{i=1}^{q-1}$ is a pancake decomposition of $X$, its induced decomposition $\{\tilde{X}_i'\}_{i=1}^{t(q-1)}$ on $\tilde X$ is also a pancake decomposition. This implies $p\le t(q-1)$, a contradiction with Lemma \ref{Lem: fundamental-minimal}. The result then follows.
\end{proof}

\begin{Def}\label{Def: Greedy decomposition in circ Snakes with nodes}
Any decomposition $\{X_i\}_{i=1}^{q}$ of a circular snake $X$ with nodal zones satisfying the properties of Theorem \ref{Teo:Minimal-pancake-circular-snakes-with-nodes} is defined as a \textbf{greedy (pancake) decomposition of $X$ with respect to $(N,\varepsilon)$}.
\end{Def}

