    \caption{Surfaces where the greedy algorithm fails to obtain a minimal pancake decomposition. Points inside shaded disks
represent arcs with the tangency order higher than the respective surface's exponent.}\label{11}
\end{figure}

    Let $\{X_i=T(\theta_{i-1},\theta_i)\}_{i=1}^5$ and $\{X'_i=T(\theta'_{i-1},\theta'_i)\}_{i=1}^5$ be pancake decompositions of $X$ with boundary arcs represented by the dots on the link of $X$. If $\alpha''>\alpha'>\alpha>\mu(X)$ are such that $$\alpha''=\operatorname{tord}(X_1',X_4') = \operatorname{tord}(\theta'_1,\theta'_4)>\operatorname{tord}(\theta_1,\theta_4)=\operatorname{tord}(X_1,X_4)=\alpha',$$ 
    then those pancake decompositions are not outer equivalent, since outer bi-Lipschitz homeomorphisms preserve tangency orders. Analogously, let $\{Y_i=T(\lambda_{i-1},\lambda_i)\}_{i=1}^3$ and $\{Y'_i=T(\lambda'_{i-1},\lambda'_i)\}_{i=1}^3$ be greedy pancake decompositions of $Y$ with boundary arcs represented by the dots on the link of $Y$. If $\alpha'>\alpha>\mu(X)$ are such that $$\alpha'=\operatorname{tord}(Y_1',Y_3') = \operatorname{tord}(\lambda_1',Y_3')>\operatorname{tord}(\lambda_1,Y_3)=\operatorname{tord}(Y_1,Y_3)=\alpha,$$ then those pancake decompositions are not outer equivalent.
    \end{Exam}

