\begin{algorithm}[h!]
\caption{Hilbert Curve Computation}
\label{algo_hilbert_curve}
\begin{algorithmic}[1]
\scriptsize
\Statex \textbf{Input: }\texttt{Set of Biological Sequences ($S$), Number of Iterations $p$, Number of Dimensions $N$, Alphabets ($A$)}
\Statex \textbf{Output: }\texttt{Hilbert Curve  Coordinates($H$)}
\Function{ComputeHilbertCurve}{$S$,$p$,$N$}
\State H $\gets$ [ ]
% \Comment{Initialize Hilbert Curve}
\State $\Theta$ = $2^{(p * N)}$
\Comment{Compute number of unit hypercubes using p = 6 and N = 2}

\For{\texttt{ $s_{1}$ in S\hspace{0.2cm}}}
% {
    \State L $\gets$ Length($s_{1}$)

    \For{\texttt{ $char$ in $s_{1}$\hspace{0.2cm}}}
    % {
    \State Index $\gets$ \Call{IndexMapping}{$char$, $A$}
    \State D $\gets$ $\dfrac{Index}{L}$ * $\Theta$ \Comment{Compute distances along Hilbert curve}
    \State Coordinates $\gets$ PointfromDistance(D) \Comment{Single Hilbert curve point coordinates} 
    % \State NormIndex $\gets$ Index / length($s_{1}$) * NumUnitCubes 
    \State $H$.append(Coordinates)
    % }
    \EndFor
% }
\EndFor
\State \Return $H$ 
\EndFunction
\end{algorithmic}
\end{algorithm}

\begin{algorithm}[h!]
