\begin{algorithm}[h!]
\caption{Distance to Hilbert Curve Point}
\label{algo_Points}
\begin{algorithmic}[1]
\scriptsize
\Statex \textbf{Input: }\texttt{Distance along Hilbert Curve ($D$), Number of Iterations ($p$)}
\Statex \textbf{Output: }\texttt{Point($\phi$)}
\Function{PointfromDistance}{$D$}
\State NumBits = $N*p$ \Comment{Number of bits}
\State Bits = Binary($D$)
\Comment{Distance to Binary string representation of $N$*$p$ bits}
\State OddIdxBits $\gets$ [ ]
\State EvenIdxBits $\gets$ [ ]
\State Components $\gets$ [ ]

\For{i in range(0, LenBits)}
% {   
\If{i \% 2 = 0}
    % {
    \State EvenIdxBits.append(Bits[i])

    \ElsIf{i \% 2 = 1}
    % {
    \State OddIdxBits.append(Bits[i])
    % }
    % }
    \EndIf
% }
\EndFor
\State EvenIdxDeci = Decimal(EvenIdxBits)
\State Components.append(EvenIdxDeci)
\State OddIdxDeci = Decimal(OddIdxBits)
\State Components.append(OddIdxDeci)
\State GrayCode $\gets$ \Call{GenerateGrayCode}{Components, $n$}
\State $\phi$ $\gets$ \Call{Refining}{GrayCode, $p$}
\State \Return $\phi$ 
\EndFunction
\end{algorithmic}
