\begin{algorithm}[h!]
\caption{Gray Code Computation}
\label{algo_Gray_Code}
\begin{algorithmic}[1]
\scriptsize
\Statex \textbf{Input: }\texttt{Components ($C$),$n$}
\Statex \textbf{Output: }\texttt{Gray Code($\gamma$)}
\Function{GenerateGrayCode}{$C$}
\State $r$ = $C$[$n$-1] $\gg$ 1 \Comment{Right shift}

\For{i in range($n$-1, 0, -1)}
    % {
    \State $C$[i] $\gets$ $C$[i] $\oplus$ $C$[i-1] \Comment{Bitwise XOR between two consecutive bits}
    % }
    \EndFor
\State $C$[0] $\gets$ $C$[0] $\oplus$ $r$
\State $\gamma$ $\gets$ $C$
\State \Return $\gamma$ 
\EndFunction
\end{algorithmic}
\end{algorithm}


\begin{algorithm}[h!]
\caption{Refining}
\label{algo_clean_up}
\begin{algorithmic}[1]
\scriptsize
\Statex \textbf{Input: }\texttt{Gray Code Integers($g$), Number of Iterations ($p$)}
\Statex \textbf{Output:} \texttt{Point($\beta$)}
\Function{Refining}{$g$}
       \State q = 2
       \State z = 2 $\ll$ ($p$-1)

        \While{q != z}
         % {  
         \State w = q - 1

            \For{i in range(n-1, -1, -1)}
            % {
                \If{$g$[i] $\BitAnd$ q}
                    % {
                    \Comment{Check if the specific bit that is ON in q is also ON in $g$[i]}
                    \State $g$[0] = $g$[0] $\oplus$ w \Comment{Invert low bits of $g$[0]}
                    % }
                    \Else
                    % {
                    \State t = ($g$[0] $\oplus$ $g$[i]) $\BitAnd$ w 
                    \State $g$[0] = $g$[0] $\oplus$ t\Comment{Exchange low bits of $g$[0] and $g$[i]}
                    \State $g$[i] = $g$[i] $\oplus$ t
                    % }
                    \EndIf

            % }
            \EndFor
            \State q = q $\ll$ 1
        % }
        \EndWhile
\State $\beta$ $\gets$ $g$
\State \Return $\beta$ 
\EndFunction
\end{algorithmic}
\end{algorithm}

\subsection{Mathematical Justification}

\paragraph{Gray Code Utilization:}
Gray codes are employed to minimize the Hamming distance between successive integer values, which translates to minimal movement between adjacent points on the Hilbert curve. This is crucial for maintaining the continuity and smoothness of the curve, and it enhances the preservation of sequential information in the image representation.

\paragraph{Refinement Process:}
The refinement step corrects the over-transformation caused by the global Gray code application. By performing inversions and exchanges in a backward pass through the higher-order bits, we ensure that the final coordinates accurately reflect the intended mapping.

\subsection{Collision Guarantee}
The Hilbert curve is a space-filling curve, and thus, as $p \rightarrow \infty$, the curve becomes denser, filling all points in the space. For a finite $p$, the guarantee is that the curve will cover all unit hypercubes without any overlap within the resolution limit set by $\Theta = 2^{p \times N}$.


\subsection{Upper Bound on Uniqueness}
Since the Hilbert curve is injective for any given resolution, there is no loss of information within the resolution constraints. As long as the number of unit hypercubes exceeds the sequence length (i.e., $\Theta > L$), the curve guarantees a unique mapping of characters to curve points. If $\Theta \leq L$, multiple characters may map to the same spatial location, leading to potential loss of information.

