\subsection{Degree Lower Bound}

We now state and prove the degree lower bound that we use in the rank lower bound.
We begin with the bound that was used in \cite{GHT22}.

\begin{lemma}[\cite{FSTW21} Proposition 5.3]
\label{subsetsumdegree}
    Let $n \geq 1$, $\chara(\FF) = 0$ or $\chara(\FF) > n$, and $\beta \in \mathbb{F} \setminus \{0,1,\ldots,n\}$.
    If $f \in \mathbb{F}[x_1, \ldots, x_n]$ is the multilinear polynomial such that
    \[
    f(\xbar) \left(\sum_{i \in [n]} x_i - \beta \right) = 1 \pmod {\xbar^2 - \xbar},
    \]
    then $\deg f = n$.
\end{lemma}

\begin{lemma}
\label{lem:deg-bound-general}
    Let $\xbar = \bigsqcup_{i \in I} \xbar_i$ be a partition of the variables $\xbar = \{x_1, \ldots, x_n\}$, $\chara (\FF)= 0$ or $\chara(\FF) = p > |I|$, and $\beta \in \mathbb{F} \setminus \{0,1,\ldots,|I|\}$.
    For $i \in I$, let $\psi_i \in \FF[\xbar_i]$ be a polynomial over the $\xbar_i$-variables that is multilinear, full degree (that is, $\deg \psi_i = |\xbar_i|$) and a Boolean function.
    If $f \in \FF[\xbar]$ is the multilinear polynomial such that
    \begin{equation}
        f(\xbar) \left(\sum_{i \in I} \psi_i - \beta \right) = 1 \pmod {\xbar^2 - \xbar},
    \end{equation}
    then $\deg f = n$.
\end{lemma}
\begin{proof}
    Let $\{w_i\}_{i \in I}$ be Boolean variables and $f_w \in \FF[\wbar]$ be the multilinear polynomial such that
    \begin{equation}
    \label{eq:deg-bound-general-aux}
        f_w(w_1, \ldots, w_{|I|}) \left( \sum_{i \in I} w_i - \beta \right) = 1 \pmod {\wbar^2 - \wbar}.
    \end{equation}
    By \Cref{subsetsumdegree}, we have $\deg f_w = |I|$.
    We show that the following polynomial identity over the $\xbar$-variables holds:
    \begin{equation}
    \label{eq:deg-bound-general-sub}
        f_w(\psi_1, \ldots, \psi_{|I|}) \left( \sum_{i \in I} \psi_i - \beta \right) = 1 \pmod {\xbar^2 - \xbar}.
    \end{equation}
    We note that $f_w$ is a polynomial over the $\wbar$-variables that is multilinear and for every $i \in I$, $\psi_i$ is a polynomial over the $\xbar_i$-variables that is multilinear.
    Therefore, as $\xbar = \bigsqcup_{i \in I} \xbar_i$ is a partition of the $\xbar$-variables, $f_w(\psi_1, \ldots, \psi_{|I|})$ is a polynomial over the $\xbar$-variables that is multilinear.
    Thus, to show \Cref{eq:deg-bound-general-sub}, it suffices to show that
    \begin{equation}
    \label{eq:deg-bound-general-bool}
        f_w(\psi_1, \ldots, \psi_{|I|}) \left( \sum_{i \in I} \psi_i - \beta \right) = 1
    \end{equation}
    holds for all $\xbar \in \{0,1\}^n$.
    Let $\alpha \in \{0,1\}^n$ be a Boolean assignment for the $\xbar$-variables and, for all $i \in I$, let $w_i = \psi_i(\alpha|_{\xbar_i})$.
    Since, for all $i \in I$, $\psi_i$ is a Boolean function, the assignments on the $\wbar$-variables are all Boolean assignments. 
    Therefore, for these Boolean assignments on the $\wbar$-variables, by \Cref{eq:deg-bound-general-aux},
    \[
         f_w(w_1, \ldots, w_{|I|}) \left( \sum_{i \in I} w_i - \beta \right) = 1.
    \]
    Since $w_i = \psi_i(\alpha|_{\xbar_i})$ for all $i \in I$, we see that \Cref{eq:deg-bound-general-bool} holds for the Boolean assignment $\alpha$ on the $\xbar$-variables.
    We therefore see that \eqref{eq:deg-bound-general-sub} holds.
    Thus, $f = f_w(\psi_1, \ldots, \psi_{|I|})$.
    Finally, as $f_w$ has full degree and for all $i \in I$, $\psi_i$ has full degree, we see that $f_w(\psi_1, \ldots, \psi_{|I|})$ has full degree.
    Therefore, $\deg f = \deg f_w(\psi_1, \ldots, \psi_{|I|}) = n$.
\end{proof}

\begin{corollary}
\label{lem:deg-bound-special}
     Let $\xbar = \bigsqcup_{i \in I} \xbar_i$ be a partition of the variables $\xbar = \{x_1, \ldots, x_n\}$, $\chara (\FF)= 0$ or $\chara(\FF) = p > |I|$, and $\beta \in \mathbb{F} \setminus \{0,1,\ldots,|I|\}$.
    If $f \in \FF[\xbar]$ is the multilinear polynomial such that
    \begin{equation}
    \label{eqnpartitiondegree}
        f(\xbar) \left(\sum_{i \in I} \prod_{x \in \xbar_i} (1-x) - \beta \right) = 1 \pmod {\xbar^2 - \xbar},
    \end{equation}
    then $deg (f) = n$.
\end{corollary}
\begin{proof}
    This follows from \Cref{lem:deg-bound-general}, taking for all $i \in I$,
    \[
        \psi_i(\xbar_i) = \prod_{x \in \xbar_i} (1-x),
    \]  
    and noting that $\psi_i$ is a multilinear, full degree polynomial and a Boolean function.
\end{proof}

\subsection{Rank Lower Bound}

\begin{lemma}
\label{lem:rank-lower-bound}
    Let $\mathbb{F}$ be a field with characteristic $p$ and $w \in \mathbb{Z}^d$ be a balanced word.
    If $f$ is the multilinear polynomial such that
    \[
    f = \frac{1}{\ks_{w,p}} \text{ over Boolean assignments,}
    \]
    then $M_w(f)$ has full rank.
\end{lemma}
\begin{proof}
    We recall the assumption that $|w_{N_w}| \geq |w_{P_w}|$ from the construction of $\ks_{w,p}$.
    Now write
    \begin{equation}
    \label{lem:rank-f-monomial}
        f = \sum_m g_m(\xbar) m,
    \end{equation}
    where the sum ranges over all multilinear monomials $m$ in the $\ybar$-variables and $g_m(\xbar)$ is some multilinear polynomial in the $\xbar$-variables.

    \begin{claim}
        For any monomial $m$ that is set-multilinear on some $w|_T$, where $T \subseteq N_w$, the leading monomial of $g_m(\xbar)$ is less than or equal to
        \[
        m (\sigma(m)|_{A_w^{S}}),
        \]
        where $S$ is the maximal subset of $P_w$ such that $A_w^S \subseteq B_w^T$.
        Moreover, if $m$ is set-multilinear on $w|_{N_w}$, then the leading monomial of $g_m(\xbar)$ equals 
        \[
        m (\sigma(m)|_{A_w^{P_w}}).
        \]
    \end{claim}
    \begin{proof}
        We prove this claim by induction on the size of $T$.\\\\
        \textit{Base case:} If $T = \emptyset$, consider the partial assignment $\tau_1$ that maps all the $\ybar$-variables to $0$.
        We have $\tau_1(f) = g_1(\xbar)$, where $g_1(\xbar)$ is the coefficient of the empty monomial $1$.
        On the other hand, $\tau_1(\ks_{w,p}^{(i)}) = 1$ for all $i$.
        Since
        \[
            f = \frac{1}{\ks_{w,p}} \text{ over Boolean assignments,}
        \]
        we see that $\tau_1(f) = 1/(r-\beta)$ over Boolean assignments.
        As $g_1(\xbar)$ is multilinear, $g_1(\xbar) = 1/(r-\beta)$ as a polynomial identity, so the the leading monomial of $g_1(\xbar)$ is the empty monomial $1$.
        \\\\
        \textit{Inductive step:}
        Suppose that $T$ is non-empty, and let $m$ be a set-multilinear monomial over $w|_T$.
        Consider the partial assignment $\tau_m$ that maps any $\ybar$-variable in $m$ to $1$ and any other $\ybar$-variable to $0$.
        By \Cref{lem:rank-f-monomial}
        \begin{equation}
        \label{eqn_f_inductive_assign}
            \tau_m(f) = \sum_{m'}g_{m'}(\xbar),
        \end{equation}
        where $m'$ ranges over all submonomials of $m$.
        On the other hand,
        \[
        \tau_m(\ks_{w,p}) = \sum_{j \in [r]} \prod_{i \in P_w^{(j)}} \tau_m(\ks_{w,p}^{(i)}) - \beta.
        \]
        For $i \in P_w$, if $A_w^{(i)} \not \subseteq B_w^T$, then $\tau_m(\ks_{w,p}^{(i)}) = 1$; however, if $A_w^{(i)} \subseteq B_w^T$, then $\tau_m(\ks_{w,p}^{(i)}) = 1- x_{\sigma_i}^{(i)}$, where $\sigma_i$ is the binary string indexed by $A_w^{(i)}$ that agrees with $\sigma(m)$ on $A_w^{(i)}$.
        Therefore
        \[
        \tau_m(f)  \left(\sum_{j \in [r]} \prod_{i \in P_w^{(j)} } (1- x_{\sigma_i}^{(i)}) - \beta \right)= 1  \text{ over Boolean assignments,}
        \]
        where the product ranges over $i \in P_w^{(j)}$ such that $A_w^{(i)} \subseteq B_w^T$.
        From \Cref{lem:deg-bound-special}, it follows that the leading monomial of $\tau_m(f)$ is the product of all the $x_{\sigma_i}^{(i)}$ appearing above, and thus the leading monomial is
        \begin{equation}
        \label{eqn_lead_monomial}
            m (\sigma(m)|_{A_w^{S}}),
        \end{equation}
        where $S$ is the maximal subset of $P_w$ such that $A_w^S \subseteq B_w^T$ (see \Cref{fig:leading-monomial}).
        If the leading monomial of $g_m(\xbar)$ were greater than $ m (\sigma(m)|_{A_w^{S}})$, then it must be cancelled by some monomial of $g_{m'}(\xbar)$ in \Cref{eqn_f_inductive_assign} for some proper submonomial of $m$; however, by the inductive hypothesis, for all such proper submonomials $m'$, the leading monomial of $g_{m'}(\xbar)$ is less than or equal to $m (\sigma(m')|_{A_w^{S}})$.
        Therefore, the leading monomial of $g_m(\xbar)$ must be less than or equal to \Cref{eqn_lead_monomial}, concluding the induction.\\\\
        It remains to show that the leading monomial of $g_m(\xbar)$ equals  $m (\sigma(m)|_{A_w^{P_w}})$ whenever $m$ is set-multilinear on $w|_{N_w}$.
        Let $m'$ be a proper submonomial of $m$ that is set-multilinear over $w|_{T}$ for some $T \subsetneq N_w$.
        As $w$ is a balanced word, there is some $i \in P_w$ such that $A_w^{(i)} \not\subseteq B_w^T$, and thus the leading monomial of $g_{m'}(\xbar)$ is strictly smaller than $m (\sigma(m)|_{A_w^{P_w}})$.
        From \Cref{eqn_lead_monomial}, it follows that the leading monomial of $g_m(\xbar)$ must equal $m (\sigma(m)|_{A_w^{P_w}})$.
    \end{proof}
    For each monomial $m_P$ that is set-multilinear over $w|_{P_w}$, there exists a monomial $m_N$, set-multilinear over $w|_{N_w}$, such that the leading monomial of $g_{m_N}(\xbar)$ is exactly $m_P$.
    Consequently, the $(m_P,m_N)$ entry of $M_w(f)$ is non-zero in $\FF$, while for every monomial $m_P' \neq m_P$, also set-multilinear over $w|_{P_w}$ and satisfying $m_P \leq m_P'$, the $(m_P',m_N)$ entry is zero.
    For $M_w(f)$, it follows that the dimension of the column space equals the number of rows, so $M_w(f)$ has full rank.
\end{proof}

\begin{corollary}
\label{cor:relrank-lower-bound}
    Let $\mathbb{F}$ be a field with characteristic $p$, and let $w \in \mathbb{Z}^d$ be a balanced word with $|w_i| \leq b$ for all $i \in [d]$.
    If $f$ is the multilinear polynomial such that
    \[
    f = \frac{1}{\ks_{w,p}} \text{ over Boolean assignments,}
    \]
    then $\relrk(f) \geq 2^{-b/2}$.
\end{corollary}
\begin{proof}
    Recall that, by the construction of $\ks_{w,p}$, we assume $|w_{N_w}| \geq |w_{P_w}|$.
    Since $w$ is balanced and satisfies $|w_i| \leq b$ for all $i \in [d]$, it follows that $|w_{P_w}| - |w_{N_w}| \geq -b$.
    By \Cref{lem:rank-lower-bound}, $M_w(f)$ has rank $|M^P_w|$.
    Therefore
    \[
        \relrk_w(f) = \sqrt{\frac{|M^P_w|}{|M^N_w|}} = \sqrt{2^{|w_{P_w}| - |w_{N_w}|}} \geq 2^{-b/2}.
    \]
\end{proof}

