\subsection{IPS Lower Bound}
We now state and prove our lower bound for constant-depth $\IPS$ over finite fields.
We begin by recalling notation from \cite{BDS24_journal}.
Let $F(n)$ denote the $n$-th Fibonacci number, defined by $F(0)=1, F(1)=2$ and $F(i)=F(i-1)+F(i-2)$ for $i \geq 2$; let $G(i) = F(i) - 1$ for all $i$.
Fix the product-depth $\Delta \leq \nicefrac{\log \log \log n}{4}$, and let $d = \lfloor \nicefrac{\log n}{4}  \rfloor$ and $\lambda = \lfloor d^{1/G(\Delta)} \rfloor$.
\begin{theorem}[\cite{GHT22} over Finite Fields]
\label{thm:ips-modp-main}
    Let $p \geq 5$ be a prime, and let $\FF$ be a field of characteristic $p$.
    Let $n, \Delta \in \NN_+$ with $\Delta \leq \nicefrac{\log \log \log n}{4} $.
    Then any product-depth at most $\Delta$ multilinear $\lbIPS$ refutation over $\FF$ of  $\ks_{w,p}$ has size  at least
    \[
    n^{\Omega(\lambda/\Delta)}.
    \]
\end{theorem}
The proof of \Cref{thm:ips-modp-main} relies on the following result:
\begin{theorem}
\label{thm:knapsack-modp-lower-bound}
    Let $p \geq 5$ be a prime, and let $\FF$ be a field of characteristic $p$.
    Let $\Delta$ be as above.
    If $f$ is the multilinear polynomial that equals
    \[
    \frac{1}{\ks_{w,p}} \text{ over Boolean assignments,}
    \]
    then any circuit of product-depth at most $\Delta$ computing $f$ has size at least
    \[
    n^{\Omega(\lambda/\Delta)}.
    \]
\end{theorem}
\begin{proof}[Proof of \Cref{thm:ips-modp-main} from \Cref{thm:knapsack-modp-lower-bound}]
Let $C(\vx, \vy, \vz)$ be a multilinear $\lbIPS$ refutation of $\ks_{w,p}$\footnote{$\ks_{w,p}$ involves both $\vx$- and $\vy$-variables. As this distinction will not play a role in the proof, we treat all variables in $\ks_{w,p}$ as $\vx$-variables. We therefore use the standard notation $C(\vx, \vy, \vz)$ for an $\IPS$ refutation, where $\vx$ are variables of the axioms, and $\vy$, $\vz$ serve as placeholder variables for the axioms.}.
As there is only one non-Boolean axiom, $C$ has a single $\ybar$-variable, which we denote by $y$.
Since $\widehat C(\vx, y, \vnz)$ is linear in the $y$-variable and satisfies $\widehat C(\vx, 0, \vnz) = 0$, it follows that
\[
\widehat C(\vx, y, \vnz) = g(\vx) \cdot y
\]
for some polynomial $g(\vx) \in \FF[\vx]$.
This polynomial $g(\vx)$ is computed by the circuit $C(\vx,1,\vnz)$, so the minimal product-depth-$\Delta$ circuit size of $g(\vx)$ lower bounds that of $C(\vx, \vy, \vz)$.
Therefore, it suffices to lower bound the size of product-depth at most $\Delta$ circuits computing $g(\vx)$.

We have
        $$
        \widehat C(\vx,y,\vz)= \widehat  C(\vx,y,\vnz) +\sum_{i} h_i\cdot z_i
        $$
        for some polynomials $h_i$ in $\vx,y,\vz$,
        hence $\widehat  C(\vx,y,\vz) =  g(\vx)\cdot y + \sum_{i} h_i\cdot z_i$. 
        Since
        \[
        \widehat C\left(\vx,\ks_{w,p},\vx^2-\vx\right) = 1, 
        \]
        we see that
        \[
        g(\vx) \cdot \left(\ks_{w,p}\right) + \sum_{i} (h_i \cdot (x_i^2-x_i)) = 1.
        \]
        Therefore, over Boolean assignments, $g(\vx)\cdot\ks_{w,p} \equiv 1$.
        The result now follows from \Cref{thm:knapsack-modp-lower-bound}.
\end{proof}

\begin{lemma}
\label{lem:set-multilinear-circuit-lb}
Let $p \geq 5$ be a prime, and let $\FF$ be a field of characteristic $p$.
Let $\Delta$, $d$ and $\lambda$ be as above.
There exist $\alpha \in \mathbb{Q}$ with $\nicefrac{1}{2} \leq \alpha < 1$, and $k \in \NN_+$ with $k \in [\nicefrac{\lfloor \log n \rfloor}{2}, \lfloor \log n \rfloor]$ and $\alpha k \in \ZZ$, such that if $w \in \ZZ^d$ is a balanced word over the alphabet $\{\alpha k, -k\}$, and $f$ is the multilinear polynomial which equals $\nicefrac{1}{\ks_{w,p}}$ over Boolean assignments, then any set-multilinear circuit of product-depth $\Delta$ computing the set-multilinear projection $\Pi_w(f)$ has size at least
    \[
    s \geq 2^{\frac{k(\lambda/256 - 1)}{2 \Delta}}.
    \]
\end{lemma}
\begin{proof}
Let $C$ be a set-multilinear circuit of size $s$ and product-depth $\Delta$ computing $\Pi_w(f)$.
By unwinding $C$ into a formula, we obtain a set-multilinear formula $F$ of size $s^{2 \Delta}$ and product-depth $\Delta$ that also computes $\Pi_w(f)$.
We now make use of the following claim from \cite{BDS24_journal}:
\begin{claim}[\cite{LST21},\cite{BDS24_journal} Lemma 4.3]
\label{clm_rel_rank_bound}
    Let $\delta \leq \Delta$ be an integer.
    There exist $\alpha \in \mathbb{Q}$ with $\nicefrac{1}{2} \leq \alpha < 1$, and $k \in \NN_+$ with $k \in [\nicefrac{\lfloor \log n \rfloor}{2}, \lfloor \log n \rfloor]$ and $\alpha k \in \ZZ$, such that if $w \in \ZZ^d$ is a word over the alphabet $\{\alpha k, -k\}$, and $F$ is a set-multilinear formula of product-depth $\delta$, degree at least $\lambda^{G(\delta)}/8$ and size at most $s$, then 
    \[
    \relrk_w(F) \leq s 2^{-k \lambda/256}.
    \]
\end{claim}
As $w$ is balanced, by \Cref{lem:rank-lower-bound}, $M_w(f)$ has full rank and $\deg F \geq d \geq \lambda^{G(\delta)}/8$.
Thus, applying \Cref{cor:relrank-lower-bound} and \Cref{clm_rel_rank_bound}, we obtain 
\[
2^{-k} \leq \relrk_w(\Pi_w(f)) \leq s^{2 \Delta} 2^{-k \lambda/256}.
\]
We therefore see that
\[
    s^{2 \Delta} \geq 2^{k(\lambda/256 - 1)},
\]
from which the claim of the lemma follows.
\end{proof}

\begin{lemma}[\protect{\cite[Corollary~27]{forbes24}}]
    \label{lem:forbes-set-multilinearization}
    Let $\mathbb{F}$ be any field, and let the variables $\xbar$ be partitioned into $\xbar = \xbar_1 \sqcup \cdots \sqcup \xbar_d$.
    Suppose $f \in \mathbb{F}[\xbar]$ can be computed by a size $s$, product-depth $\Delta$ algebraic circuit.
    Then the set-multilinear projection $\Pi_{\textnormal{sml}}(f) \in \mathbb{F}[\xbar]$ can be computed by a size $\poly(s, \Theta (\frac{d}{\ln d} )^d)$, product-depth $2\Delta$ set-multilinear circuit.    
\end{lemma}

\begin{proof}[Proof of \Cref{thm:ips-modp-main}]
    Let $C$ be a circuit of size $s \geq n$ and product-depth at most $\Delta$ computing $f$.
    Let $d = \lfloor \nicefrac{\log n}{4}  \rfloor$ and $\lambda = \lfloor d^{1/G(\Delta)} \rfloor$ be as defined above, and let $\nicefrac{1}{2} \leq \alpha < 1$ and $k \in [\nicefrac{\lfloor \log n \rfloor}{2}, \lfloor \log n \rfloor]$ be as constructed in \Cref{lem:set-multilinear-circuit-lb}.
    Construct, by induction, a balanced word $w \in \ZZ^d$ over the alphabet $\{\alpha k, -k\}$.

    By \Cref{lem:forbes-set-multilinearization}, there exists a set-multilinear circuit $C'$ of size $\poly(s, \Theta (\frac{d}{\ln d} )^d)$ and product-depth $2\Delta$ computing the set-multilinear projection $\Pi_w(f)$ of $f$.

    Moreover, by \Cref{lem:set-multilinear-circuit-lb}, any set-multilinear circuit of product-depth $2\Delta$ computing $\Pi_w(f)$ must have size at least
    \[
        2^{\frac{k(\lambda/256 - 1)}{2 \Delta}} \geq n^{\frac{\lambda/256 - 1}{8 \Delta}},
    \]
    where the inequality follows from the lower bound on $k$.
    Combining the two bounds above, we obtain
    \[
    \poly(s, \Theta (\frac{d}{\ln d} )^d) \geq n^{\frac{\lambda/256 - 1}{8 \Delta}},
    \]
    and therefore,
    \[
    d ^{O(d)} \poly(s) \geq n^{\Omega(\lambda/\Delta)}.
    \]
    Since $\Delta \leq \nicefrac{\log \log \log n}{4} \leq \nicefrac{\log \log d}{2}$, it follows that $\lambda \geq (\log d)^2$.
    Hence,
    \[
    n^{\Omega(\lambda/\Delta)} \geq d^{\omega(d)},
    \]
    from which the claim of the theorem follows.
\end{proof}

\textbf{Comment}
(constructing a scattered partition):
Our instance $\ks_{w,p}$ and rank lower bound require a scattered partition $P_w = P_w^{(1)} \sqcup \cdots\sqcup P_w^{(r)}$ of the positive indices having fewer than $p$ parts.
Let $\xi := \Delta_G(N_w)$ be the negative overlap of the overlap graph.
We construct a scattered partition with $r = \xi$ as follows.
For each positive index $i \in P_w$, define $\pi'(i) := |\{i' \in P_w \mid i' \leq i\}|$, and let $\pi(i)$ be the least residue of $\pi'(i) \pmod{\xi}$; that is, $\pi(i) \in [\xi]$ with $\pi(i) \equiv \pi'(i) \pmod{\xi}$.
The map $\pi$ partitions $P_w$ into $\xi$ parts such that in each part, the neighbourhoods of the vertices are pairwise disjoint, hence $\pi$ induces a scattered partition (see \Cref{fig:scattered-partition}).

Because our $\IPS$ lower bound assumes $p \geq 5$, it suffices to construct a scattered partition with $r < 5$.
Since the word $w \in \ZZ^d$ is over the alphabet $\{\alpha k, -k\}$ with  $\nicefrac{1}{2} \leq \alpha < 1$, it follows that $ \Delta_G(N_w) \leq 3$.
Therefore, $\pi$ yields a scattered partition with $r \leq 3$.

