    \centering
    \includegraphics[scale=0.7]{img/scattered-partition.pdf}
    \caption{\small Illustration of the scattered partition induced by $\pi:P_w \to [\Delta_G(N_w)]$ with $\Delta_G(N_w) = 3$. The values of $\pi$ appear above the positive boxes, while the neighbourhoods of the positive indices are shown below the negative boxes. Since this is a scattered partition, vertices in the same part have pairwise disjoint neighbourhoods.}
