\section{Upper Bounds for Constant-depth Multilinear IPS}
\label{sec:upper_bound}
\subsection{Elementary Symmetric Sums}

\begin{proposition}
Over any field $\mathbb{F}$, for $|\xbar| = n \geq l \geq d \geq 0$,
    \[ e_l (\xbar) \cdot e_d (\xbar) = \sum_{i=k}^{d} \binom{l+d - i}{l} \binom{l}{i} e_{l+d - i} (\xbar) \pmod {\xbar^2 - \xbar},\]
where $k \geq 0$ is the smallest integer such that $l+d - k \leq n$. 
\end{proposition}
\begin{proof}
    Since $\ml(e_l (\xbar) \cdot e_d (\xbar))$ is symmetric in $\xbar$, we have
    \[
        e_l (\xbar) \cdot e_d (\xbar) = \sum_{i=k}^{d} \gamma_i \cdot e_{l+d - i} (\xbar) \pmod {\xbar^2 - \xbar},
    \]
    for $\gamma_i \in \mathbb{F}$.
    Let $S \subseteq [n]$ with $|S| = l+d - i$.
    The coefficient of the monomial $x^S$ in $\ml(e_l (\xbar) \cdot e_d (\xbar))$ is $\binom{l+d - i}{l} \binom{l}{i}$.
    This is because each of the $\binom{l+d - i}{l}$ many sub-monomials $x^A$ of $x^S$ in $e_l (\xbar)$ combines with $\binom{l}{i}$ many monomials $x^B$ in $e_d (\xbar)$, where $|A \cap B| = i$, to produce $x^S$ in $\ml(e_l (\xbar) \cdot e_d (\xbar))$.
    Therefore, $\gamma_i = \binom{l+d - i}{l} \binom{l}{i}$.
\end{proof}

We observe that elementary symmetric polynomials are unsatisfiable even over constant characteristic fields, when their degree meets a simple condition on their $p$-base expansion. 



\begin{lemma}[\cite{Lucas_Theorem_paper} Lucas's Theorem]
\label{thm:lucas}
    Let $p$ be a prime and $m,n \in \NN_+$.
    If $m = m_k p^k + \cdots + m_1p + m_0$ and $n = n_k p^k + \cdots + n_1p + n_0$ are the base $p$ expansions of $m$ and $n$ respectively (where $0 \leq m_i,n_i \leq p-1$ for $0 \leq i \leq k$), then 
    \[\binom{m}{n} \equiv \prod_{i=0}^{k} \binom{m_i}{n_i} \pmod p.\]
\end{lemma}

\begin{lemma}
\label{lem:symmetric-sums-boolean}
    Let $\FF$ be a field with characteristic $p$. 
    If $d = d_k p^k + \cdots + d_1p + d_0$ is the base $p$ expansion of $d$, then 
    \[
        | \{e_d(\xbar) \mid x \in \{0,1\}^n \} | \leq \prod_{\substack{i \in \{0, \ldots, k\} \\ d_i \neq 0}} (p-d_i) + 1.
    \]
    In particular, if $d$ has only one non-zero digit $d_i$ in its base $p$ expansion and $d_i \geq 2$, then there exists $\beta \in \mathbb{F}$ such that $e_d(\xbar) - \beta = 0$ is unsatisfiable over Boolean assignments.
\end{lemma}
\begin{proof}
    If $m$ is the Hamming weight of a Boolean assignment $\alpha \in \{0,1\}^n$,
    then $e_d(\alpha) = \binom{m}{d}$.
    By \Cref{thm:lucas}, we have 
    \[
        \binom{m}{d} \equiv \prod_{i \in \{0, \ldots,k\}}\binom{m_i}{d_i} \equiv \prod_{\substack{i \in \{0, \ldots,k\} \\ d_i \neq 0} }\binom{m_i}{d_i} \pmod p.
    \]
    We see that $e_d(\alpha) = 0$ in $\FF$ if and only if $m_i < d_i$ for some $i$ with $d_i \neq 0$.
    Conversely, $e_d(\alpha)$ is non-zero in $\FF$ if and only if $d_i \leq m_i \leq p-1$ for all $i$ with $d_i \neq 0$.
    Therefore, $e_d(\alpha)$ can attain at most
    \[
    \prod_{\substack{i \in \{0, \ldots,k\} \\ d_i \neq 0} }((p-1)-d_i+1)
    \]
    distinct non-zero values in $\FF$.
    This completes the proof of the main claim of the lemma.

    Now if $d_i \geq 2$ is the only non-zero digit in the base $p$ expansion of $d$, then over Boolean assignments, $e_d(\xbar)$ can attain at most $p - d_i + 1 \leq p-1$ distinct values in $\FF$.
    The existence of $\beta$ follows. 
\end{proof}

Occasionally, instead of viewing $\xbar$ as Boolean variables, we consider them more generally as Boolean functions.
By a similar argument, it is straightforward to verify that \Cref{lem:symmetric-sums-boolean} continues to hold in this more general setting.

\subsection{Separation}

Here, we separate the constant-depth $\IPS$ subsystem over finite fields, as considered in this work, from the constant-depth $\IPS$ subsystem over large fields studied in \cite{GHT22}.

Let $p \geq 3$ be a prime and let $\F$ be a field of characteristic $p$.
We construct the \textit{symmetric knapsack} of degree $2$, denoted as $\ks_{w, e_2}$.
Over Boolean assignments, $\ks_{w, e_2}$ is unsatisfiable in $\F$ and in every field of characteristic $0$.
Moreover, constant-depth multilinear $\lbIPS$ over $\F$ admits a polynomial-size refutation of $\ks_{w, e_2}$, whereas constant-depth multilinear $\lbIPS$ over any characteristic $0$ field does not.

Using the notation from \Cref{sec:cd-IPS}, let $w \in \ZZ^d$ be a word with $|w_i| \leq b$ for every $i$.  
Our separating instance is defined as:
\[
    \ks_{w, e_2} := \ml \left(e_2 \left(\{x_\sigma^{(i)}f_\sigma^{(i)}\}_{i\in P_w, \sigma\in\{0,1\}^{A_w^{(i)}}} \right) \right) - \beta.
\]
where $\beta \in \FF$ is chosen such that $\ks_{w, e_2} = 0$ admits no satisfying Boolean assignment in $\FF$.

\textbf{Comment} (the existence of $\beta$):
The existence of $\beta$ follows from \Cref{lem:symmetric-sums-boolean}, specifically from the remark following the lemma concerning its application to Boolean functions rather than Boolean variables.

\textbf{Comment} (computing $\ks_{w,e_2}$ by a $\poly(d,2^b)$-size, product-depth $2$, multilinear formula):
Since
\[
    \ks_{w,e_2} = \sum_{\substack{(i_1,\sigma_1), (i_2, \sigma_2) \in S \\ (i_1,\sigma_1)\neq (i_2, \sigma_2)}} x_{\sigma_1}^{(i_1)}x_{\sigma_2}^{(i_2)} \ml(f_{\sigma_1}^{(i_1)}f_{\sigma_2}^{(i_2)}) - \beta
\]
where $S = \{(i, \sigma) \mid i\in P_w, \sigma\in\{0,1\}^{A_w^{(i)}}\}$, it suffices to verify that $\ml(f_{\sigma_1}^{(i_1)}f_{\sigma_2}^{(i_2)})$ can be computed by a suitable polynomial-size constant-depth multilinear formula.
Since the positive overlap of $w$ satisfies $\Delta_G(P_w) \leq b$, we see that each $f_{\sigma}^{(i)}$ can be written as $\sum \prod (1-y)$ where the fan-in of the sum gate is $O(2^b)$ and the product ranges over distinct $\ybar$-variables.
Moreover, because $\ml((1-y)^2) = 1-y$, each $\ml(f_{\sigma_1}^{(i_1)}f_{\sigma_2}^{(i_2)})$ can likewise be written in this form.
Altogether, $\ks_{w,e_2}$ can thus be written as a product-depth $2$, multilinear formula of $\poly(d,2^b)$-size.
Moreover, each $f_\sigma^{(i)}$ has degree at most $O(b2^b)$, so the overall degree of $\ks_{w,e_2}$ is therefore $O(b2^b)$.

\begin{lemma}
     Over $\FF$, there exists a product-depth $3$ multilinear $\lbIPS$ refutation of $\ks_{w,e_2}$ of size  $\poly(d^p,2^{bp})$.
\end{lemma}
\begin{proof}
    By Fermat's little theorem, we see that
    \begin{equation}
    \label{eq:sym-ks-deg-2-refutation}
        \ml((\ks_{w,e_2})^{p-2}) \cdot \ks_{w,e_2} + \sum_{\psi \in \xbar \cup \ybar} h_\psi (\psi^2 - \psi) = 1
    \end{equation}
    for some polynomials $h_\psi \in \FF[\xbar,\ybar]$.
    From computing $\ks_{w,e_2}$ by a $\poly(d,2^b)$-size product-depth $2$, multilinear formula, we see that $\ml((\ks_{w,e_2})^{p-2})$ can be computed by a product-depth $2$, multilinear formula of size $\poly(d^p,2^{bp})$.
    Moreover, we see that each $h_\psi$ can be computed by a product-depth $2$ formula of size $\poly(d^p,2^{bp})$.
    Therefore, over $\FF$, \Cref{eq:sym-ks-deg-2-refutation} is a product-depth $3$ multilinear $\lbIPS$ refutation of $\ks_{w,e_2}$. 
\end{proof}


Let $E$ be a field of characteristic $0$.
Since $\ks_{w, e_2}$ admits no satisfying Boolean assignment in $\F$, it likewise admits none in $E$.
Over $E$, we will prove a lower bound against constant-depth multilinear $\lbIPS$ for $\ks_{w, e_2}$.
We first prove a degree lower bound.
\begin{lemma}
\label{lem:deg-lower-bound-e2-large-field}
    Let $\textnormal{char}(\mathbb{F}) = 0$, $n > 1$ and $\beta \in \ZZ^+$ such that $e_2 (x_1, \ldots, x_n) - \beta = 0$ is unsatisfiable over $\mathbb{F}$ for $\xbar \in \{0,1\}^n$.
    If $f \in \mathbb{F}[x_1, \ldots, x_n]$ is the multilinear polynomial such that
    \[
    f(\xbar) \left(e_2 (\xbar) - \beta \right) = 1 \pmod {\xbar^2 - \xbar},
    \]
    then $\deg f = n$.
\end{lemma}
We note that a degree lower bound of $ \deg f \geq n-1$ follows from \cite{HLT24} Corollary 1.2; however, we need the tight bound of $\deg f \geq n$.
\begin{proof}[Proof of \Cref{lem:deg-lower-bound-e2-large-field}]
    As $f(\xbar)$ is multilinear, we have
    \[
    f(\xbar) = \sum_{T \subseteq [n]} f(\mathbbm{1}  _T) \prod_{i \in T} x_i \prod_{i \notin T}(1-x_i),
    \]
    where $\mathbbm{1}_T \in \{0,1\}^n$ is the indicator vector of the set $T$.
    Therefore
    \[
    f(\xbar) = \sum_{T \subseteq [n]} \frac{1}{\binom{|T|}{2} - \beta} \prod_{i \in T} x_i \prod_{i \notin T}(1-x_i).
    \]
    The coefficient of $\prod_{i \in [n]} x_i$ in $f(\xbar)$ is thus
    \begin{equation}
    \label{eqn_lead_coef_e2-b}
        \sum_{T \subseteq [n]} \frac{1}{\binom{|T|}{2} - \beta} (-1)^{n - |T|} = \sum_{j = 0}^n \binom{n}{j} \frac{1}{\binom{j}{2} - \beta} (-1)^{n - j}.
    \end{equation}
    We show that \Cref{eqn_lead_coef_e2-b} is nonzero.
    As \Cref{eqn_lead_coef_e2-b} lies in the subfield of $\mathbb{F}$ that is isomorphic to $\mathbb{Q}$, it suffices to show that it is nonzero over $\mathbb{Q}$.
    It therefore suffices to show that \Cref{eqn_lead_coef_e2-b} is nonzero over $\mathbb{R}$.
    We have, over $\mathbb{R}$,
    \[
        \frac{1}{\binom{j}{2} - \beta} = \frac{2}{j^2 - j - 2\beta} = \frac{2}{(j-\gamma_1)(j-\gamma_2)} = 2\sqrt{1+8\beta} \left(\frac{1}{j-\gamma_2} - \frac{1}{j-\gamma_1}\right),
    \]
    where $\gamma_1 = (1 - \sqrt{1+8\beta})/2$ and $\gamma_2 = (1 + \sqrt{1+8\beta})/2$.
    Hence
    \begin{align*}
        \sum_{j = 0}^n \binom{n}{j} \frac{1}{\binom{j}{2} - \beta} (-1)^{n - j} &= 2\sqrt{1+8\beta} \sum_{j = 0}^n \binom{n}{j}\left(\frac{1}{j-\gamma_2} - \frac{1}{j-\gamma_1}\right) (-1)^{n - j} \\
        &= 2\sqrt{1+8\beta} \left(- \frac{n!}{\prod_{j=0}^n (\gamma_2 - j)} + \frac{n!}{\prod_{j=0}^n (\gamma_1 - j)} \right),
    \end{align*}
    where the last equality follows from
    \begin{claim}[\cite{FSTW21} Subclaim B.2]
        \[
        \sum_{j=0}^k \binom{k}{j} \frac{1}{j-\beta} (-1)^{k-j} = - \frac{k!}{\prod_{j=0}^k (\beta - j)}.
        \]
    \end{claim}
Finally, to show that \Cref{eqn_lead_coef_e2-b} is nonzero, it suffices to show that
\begin{equation}
\label{eqn_lead_coef_e2-b_aux_prod}
    \prod_{j=0}^n (\gamma_1 - j) \neq \prod_{j=0}^n (\gamma_2 - j).
\end{equation}
We note that $\gamma_1 (\gamma_1 - 1) = \gamma_2 (\gamma_2 - 1) = 2\beta$; however, for $k > 1$, we have $|\gamma_1 - k| > |\gamma_2 - k|$.
We therefore have
\[
    \left|\prod_{j=0}^n (\gamma_1 - j) \right| > \left|\prod_{j=0}^n (\gamma_2 - j) \right|,
\]
hence \Cref{eqn_lead_coef_e2-b_aux_prod} holds and \Cref{eqn_lead_coef_e2-b} is nonzero.
\end{proof}


\begin{lemma}
    Let $E$ be a field of characteristic $0$, and $n,\Delta \in \NN_+$ with $\Delta \leq \nicefrac{\log \log \log n}{4}$.
    Then any product-depth at most $\Delta$ multilinear $\lbIPS$ refutation of $\ks_{w,e_2}$ is of size at least
    \[
        n^{\Omega(\lambda/\Delta)},
    \]
    where $d = \lfloor \nicefrac{\log n}{4} \rfloor$ and $\lambda = \lfloor d^{1/G(\Delta)} \rfloor$.
\end{lemma}
\begin{proof}
    The proof of this lemma is essentially the same as the proof of \Cref{thm:ips-modp-main} (and \cite{GHT22}) and is omitted here.
    We recall the general strategy of reducing an $\IPS$ lower bound to a rank lower bound, to a degree lower bound, which for this instance is \Cref{lem:deg-lower-bound-e2-large-field}).
\end{proof}

\begin{theorem}[Separation: \cite{GHT22} over Finite Fields vs.\ \cite{GHT22}]
\label{thm:separation}
    Let $p \geq 3$ be a prime, and let $\F$ be a field of characteristic $p$.
    Let $n, \Delta \in \NN_+$ with $\Delta \leq \nicefrac{\log \log \log n}{4} $.
    Then there exists a product-depth $2$, multilinear formula $\ks_{w,e_2}$ of size $\poly(n)$ such that:
    \begin{itemize}
        \item $\ks_{w,e_2}$ has no satisfying Boolean assignment over $\F$, and over any field of characteristic $0$;
        \item there is a $\poly(n)$-size, product-depth-$3$ multilinear $\lbIPS$ refutation of $\ks_{w,e_2}$ over $\F$;
        \item for every field of characteristic $0$, any product-depth at most $\Delta$ multilinear $\lbIPS$ refutation of $\ks_{w,e_2}$ requires size at least
    \[
        n^{\Omega(\lambda/\Delta)},
    \]
    where $d = \lfloor \nicefrac{\log n}{4} \rfloor$ and $\lambda = \lfloor d^{1/G(\Delta)} \rfloor$.
    \end{itemize}
\end{theorem}


\section{Lower Bounds for roABP-IPS}
\label{sec:roABP}
In this section, we work over field $\F_q$, where $q$ is a constant greater than 2. In addition to proving a lower bound over finite fields, this work significantly simplifies \cite{HLT24}, though we note that we are still working in the placeholder model. Consider the following hard instance
\begin{equation}
    \label{equa: hard instance for roABP}
    f(\xbar) \coloneqq \prod_{i=1}^n (1 - x_i) - 2.
\end{equation}
Clearly this function never evaluates to 0 over boolean assignments in $\F_q$ (when $q>2$). In contrast, the hard instance from \cite{HLT24} is a subset-sum instance, therefore requiring large characteristic to be defined. 

\subsection{roABP-IPS Lower Bounds in Fixed Order}
We begin by proving a lower bound where the roABPs are given a fixed order of the variables. By \Cref{lem:deg-bound-special}, we have the following lemma.

\begin{lemma}
    \label{lemma: degree lower bounds for roABP}
    Let $\F_q$ be a finite field with $q >2$, and let $f(\xbar)$ be as in \Cref{equa: hard instance for roABP}. If $g(\xbar)$ is the multilinear polynomial such that
    \[
        g(\xbar) \cdot f(\xbar) = 1 \mod{\xbar^2- \xbar},
    \]
    then $\deg(g) = n$.
\end{lemma}


For any $\xbar, \ybar$ variables, with $|\xbar| = |\ybar|= n$, we use $\xbar \circ \ybar$ to denote the entry-wise product $(x_1 y_1, \dots, x_n y_n)$. In other words, the \emph{gadget} we use is the mapping
\[
    x_i \mapsto x_i y_i,
\]
which substitutes the variables $x_i$ by $x_i y_i$, for every $i$. We use $\mathbbm{1}_S \in \{0,1\}^n$ to denote the indicator vector for a set $S$.

\begin{theorem}
    \label{theorem: leading monomials lower bounds}
    Let $f(\xbar)$ be as in \Cref{equa: hard instance for roABP}. Let $g(\xbar,\ybar) \cdot f(\xbar \circ \ybar) =1 \mod{\xbar^2- \xbar}$. Then,
    \begin{equation}
        \label{equa: leading monomial lower bounds}
        \Big | \LM \big ( \{ \ml(g(\xbar,\mathbbm{1}_S)) : S\subseteq [n]\}\big)\Big| = 2^{n}.
    \end{equation}

\end{theorem}


\begin{proof}
We first need the claim below.
    \begin{claim} Each $S \subseteq [n]$ induces a distinct leading monomial in $\ml(g(\xbar, \mathbbm{1}_S))$.
    \end{claim}

    \begin{proof}[Proof of claim:]
        Let $S \subseteq [n]$. By the assumption $g(\xbar, \ybar) \cdot f(\xbar \circ \ybar) =1 \mod{\xbar^2 - \xbar}$, we also have
        \begin{equation}
            \label{equa: condition for degree lower bounds}
            \ml(g(\xbar, \mathbbm{1}_S)) \cdot f(\xbar \circ \mathbbm{1}_S) =1 \mod{\xbar^2-\xbar},
        \end{equation}
         since multilinearizing $g(\xbar, \mathbbm{1}_S)$ does not affect the equality (as we work modulo $\xbar^2 -\xbar$). By the lifting defined above, $\ml(g(\xbar, \mathbbm{1}_S))$ is a (multilinear symmetric) polynomial that \emph{depends on the variables $x_i$, for $i \in S$}. Similarly, $f(\xbar \circ \mathbbm{1}_S)$ is a polynomial of the same form as \Cref{equa: hard instance for roABP} that \emph{depends on the variables $x_i$, for $i \in S$}. In addition, $f(\xbar)$ has no Boolean roots, so neither does $f(\xbar \circ \ybar)$. This together with \Cref{equa: condition for degree lower bounds} means the conditions of \Cref{lemma: degree lower bounds for roABP} are met, so we have
        \[
            \deg(\ml(g(\xbar, \mathbbm{1}_S))) = |S|.
        \]
        Since we assumed that our monomial ordering respects degree,
        \begin{equation}
            \label{equa: leading monomial degree lower bounds}
            \deg(\LM(\ml(g(\xbar, \mathbbm{1}_S)))) = |S|.
        \end{equation}
        There is only one possible multilinear monomial of degree $|S|$ on $|S|$ variables; it follows that every $S$ induces a unique leading monomial (consisting exactly of all variables in $S$).
    \end{proof}
    This concludes the proof of \Cref{theorem: leading monomials lower bounds}.
\end{proof}

\begin{theorem}
    \label{theorem: roABP IPS size lower bounds for fixed order}
    Let $f(\xbar)$ be as in \Cref{equa: hard instance for roABP}. Then, any $\roAlbIPS$refutation of $f(\xbar \circ \ybar) =0$ is of size $2^{\Omega(n)}$, when the variables are ordered such that $\xbar < \ybar$ (i.e., $\xbar$-variables come before $\ybar$-variables).
\end{theorem}

\begin{proof}
    Let $g(\xbar,\ybar)$ be a polynomial such that $g(\xbar, \ybar) \cdot f(\xbar \circ \ybar) =1$ over $\xbar, \ybar \in \{0,1\}^n$. Hence,
    \[
        g(\xbar, \ybar) = \frac{1}{f(\xbar \circ \ybar)} \ \text{ over } \xbar,\ybar \in \{0,1\}^n. 
    \]
    We show that $\dim\coeffs{\xbar| \ybar}g \geq 2^{\Omega(n)}$. This will conclude the proof by Lemma \ref{lem:roABP_width_equals_coeff_dim} which will give the roABP size (width) lower bound and by the functional lower bound in \Cref{thm:func_lb_method}.

    By lower bounding coefficient dimension by the evaluation dimension over the Boolean cube (\Cref{lem:eval_dim_lb_coeff_dim}),
    \begin{align*}
        \dim\coeffs{\xbar|\ybar}g &\geq \dim\evals{\xbar|\ybar,\{0,1\}}g \\
                                                &=\dim\{g(\xbar, \mathbbm{1}_S): S \subseteq [n]\} \\
                                                &\geq \dim\{\ml(g(\xbar,\mathbbm{1}_S)): S\subseteq [n]\}.
    \end{align*}
    Here we used that dimension is non-increasing under linear maps. For $S \subseteq [n]$, denoted by $\xbar_S \coloneqq \{x_i : i \in S\}$ and note that for $\xbar \in \{0,1\}^n$,
    \[  
        g(\xbar, \mathbbm{1}_S) = \frac{1}{f(\xbar_S)},
    \]
    and that $\ml(g(\xbar,\mathbbm{1}_S))$ is a multilinear polynomial only depending on $\xbar_S$.
    By \Cref{theorem: leading monomials lower bounds}, we can lower bound the number of distinct leading monomials of $\ml(g(\xbar, \mathbbm{1}_S)$, where $S$ ranges over subsets of $[n]$:
    \[
        \Big | \LM \big ( \{ \ml(g(\xbar,\mathbbm{1}_S)) : S\subseteq [n]\}\big)\Big| =2^{n}.
    \]
    Therefore, we can lower bound the dimension of the above space by the number of leading monomials (\Cref{lem:span}),
    \begin{align*}
        \dim\coeffs{\xbar|\ybar}g &\geq \dim\{\ml(g(\xbar,\mathbbm{1}_S)): S \subseteq [n]\}\\
                                                &\geq \Big | \LM \big ( \{ \ml(g(\xbar,\mathbbm{1}_S)) : S\subseteq [n]\}\big)\Big| \\
                                                &= 2^{n}.
    \end{align*}
\end{proof}

\subsection{roABP-IPS Lower Bounds in Any Order}
We now extend this previous result to roABPs in any variable order. Consider a polynomial $f(\wbar)$ over $m$ variables, where $m = \binom{2n}{2}$ and $\wbar = \{w_{i,j}\}_{i < j \in [2n]}$. We apply the same gadget from \cite{HLT24}, defined by the mapping
\[
    w_{i,j} \mapsto z_{i,j} x_i x_j,
\]
which substitutes the $m$ variables $w_{i,j}$ by $m+2n$ variables $\{z_{i,j}\}_{i <j \in [2n]}, x_1,\dots,x_{2n}$ such that:
\begin{equation}
    \label{equa: hard instance for roABP for any order}
    f^\star(\zbar,\xbar) \coloneqq f(\wbar)_{w_{i,j} \mapsto z_{i,j} x_i x_j},
\end{equation}
where $f(\wbar)_{w_{i,j} \mapsto z_{i,j} x_i x_j}$ means that we apply the lifting $w_{i,j} \mapsto z_{i,j} x_i x_j$ to the $\wbar$ variables.

Let $f \in \F[\xbar,\ybar,\zbar]$. We denote by $f_{\zbar}$ the polynomial $f$ considered as a polynomial in $\F[\zbar](\xbar,\ybar)$, namely as a polynomial whose indeterminates are $\xbar,\ybar$ and whose scalars are from the ring $\F[\zbar]$. We will consider the dimension of a (coefficient) matrix when the entries are taken from the ring $\F[\zbar]$, and where the dimension is considered over the field of rational functions $\F(\zbar)$. Note that for any $\abar \in \F^{\zbar}$, we have $f_{\abar}(\xbar,\ybar) = f(\xbar, \ybar, \abar) \in \F[\xbar,\ybar]$. We reference the following simple lemma.
\begin{lemma}[\cite{FSTW21}]
    \label{lemma: dimension non-increase under assignment}
    Let $f \in \F[\xbar, \ybar, \zbar]$. Then for any $\abar \in \F^{|\overline{z}|}$
    \[
        \dim_{\F(\zbar)}\coeffs{\xbar|\ybar}f_{\zbar}(\xbar,\ybar) \geq \dim_{\F}\coeffs{\xbar|\ybar}f_{\abar}(\xbar,\ybar).
    \]
\end{lemma}

We now prove the proposition below.
\begin{proposition}
    \label{prop: dimesnion lower bounds for any order}
    Let $n \geq 1$, $m = \binom{2n}{2}$, and $\F_q$ be a finite field of constant characteristic $q$. Let $f \in \F[\wbar]$ be as in \Cref{equa: hard instance for roABP}, and $f^\star(\zbar, \xbar)$ be as in \Cref{equa: hard instance for roABP for any order}. Let $g \in \F[z_1,\dots,z_m, x_1, \dots, x_{2n}]$ be a polynomial such that
    \[
        g(\zbar, \xbar)  = \frac{1}{f^\star(\zbar, \xbar)},
    \]
    for $\zbar \in \{0,1\}^m$ and $\xbar \in \{0,1\}^{2n}$. Let $g_{\zbar}$ denote $g$ as a polynomial in $\F[\zbar][\xbar]$. Then, for any partition $\xbar = (\ubar, \vbar)$ with $|\ubar| = |\vbar| =n$,
    \[
        \dim_{\F(\zbar)}\coeffs{{\ubar|\vbar}}g_{\zbar} \geq 2^{\Omega(n)}.
    \]
\end{proposition}

\begin{proof}
    We embed $\frac{1}{f(\ubar \circ \vbar)}$ in this instance via a restriction of $\zbar$. Define the $\zbar$-evaluation $\abar \in \{0,1\}^{\binom{2n}{2}}$ to restrict $g$ to sum over those $x_ix_j$ in the natural matching between $\ubar$ and $\vbar$, so that
    \begin{equation*}
        \alpha_{ij} = \begin{cases}
            1 \quad x_i=u_k, x_j = v_k,\\
            0 \quad \text{otherwise.}
        \end{cases}
    \end{equation*}
    It follows that $g(\ubar, \vbar, \abar) = \frac{1}{f(\ubar \circ \vbar)}$ for $\ubar, \vbar \in \{0,1\}^n$. Suppose for contradiction that there exists a partition $\xbar = (\ubar, \vbar)$ with $|\ubar| = |\vbar| =n$, such that
    \[
        \dim_{\F(\zbar)}\coeffs{{\ubar|\vbar}}g_{\zbar}(\ubar, \vbar) < 2^{\Omega(n)}.
    \]
    By \Cref{lemma: dimension non-increase under assignment}, we get the relation between the coefficient dimensions of $g_{\zbar}$ and $g_{\abar}$
    \begin{align*}
        \dim_{\F}\coeffs{{\ubar|\vbar}}g_{\abar}(\ubar, \vbar) &\leq \dim_{\F(\zbar)}\coeffs{{\ubar|\vbar}}g_{\zbar}(\ubar, \vbar)\\
            &< 2^{\Omega(n)},
    \end{align*}
    which contradicts our lower bound for a fixed partition (\Cref{theorem: roABP IPS size lower bounds for fixed order}).
\end{proof}

\begin{corollary}
    \label{corollary: roABP lower bounds for any order}
    Let $n \geq 1$, $m = \binom{2n}{2}$, and $\F_q$ be a finite field with constant characteristics $q$. Let $f \in \F[\wbar]$ be as in \Cref{equa: hard instance for roABP}, and $f^\star(\zbar, \xbar)$ be as in \Cref{equa: hard instance for roABP for any order}. Then, any $\roAlbIPS$ refutation (in any variable order) of $f^\star(\zbar, \xbar)$ requires $2^{\Omega(n)}$-size.
\end{corollary}

\begin{proof}
    Consider the polynomial $g \in \F[z_1,\dots,z_m, x_1, \dots, x_{2n}]$ such that
    \[
        g(\zbar, \xbar)  = \frac{1}{f^\star(\zbar, \xbar)}.
    \]
    for $\zbar \in \{0,1\}^m$ and $\xbar \in \{0,1\}^{2n}$. We will show that any roABP computing $g$ requires width $\geq 2^{\Omega(n)}$ in any variable order. The $\roAlbIPS$ lower bound follows immediately from this functional lower bound on $g$ along with the reduction (\Cref{thm:func_lb_method}).

    Suppose that $g(\zbar, \xbar)$ is computable by a width-$r$ roABP in \emph{some} variable order. By pushing the $\zbar$ variables into the fraction field, it follows that $f_{\zbar}$ ($f$ as a polynomial in $\F[\zbar][\xbar]$) is also computable by a width-$r$ roABP over $\F(\zbar)$ in the induced variable order on $\xbar$ (\Cref{fact:roABP}).
    By splitting $\xbar$ in half along its variable order and by the relation between the width of a roABP and its coefficient dimension (\Cref{lem:roABP_width_equals_coeff_dim}), we obtain
    \[
         \dim_{\F(\zbar)}\coeffs{{\ubar|\vbar}}g_{\zbar} < 2^{\Omega(n)},
    \]
     which contradicts the coefficient dimension lower bound of \Cref{prop: dimesnion lower bounds for any order}.
\end{proof}

% ----------------------------------------------
\subsection{roABP-IPS Lower Bounds by Multiple}
% ----------------------------------------------
Here we present another roABP-$\IPS$ lower bound over finite fields, but this time using the lower bound for multiples method from \cite{FSTW21}. We introduce the following two lemmas from their paper.


\begin{lemma}[Corollary 6.23 in \cite{FSTW21}]
    \label{lemma: rtABP lower bounds for multiple}
    Let $f \in \F[x_1,\dots, x_n]$ be defined by $f(\xbar) \coloneqq \prod_{i < j} (x_i+x_j +\alpha_{i,j})$ for $\alpha_{i,j} \in \F$. Then for any $0 \neq g \in \F[\xbar]$, $g \cdot f$ requires width-$2^{\Omega(n)}$ as a read-twice oblivious ABP.
\end{lemma}

\begin{lemma}[Lemma 7.1 in \cite{FSTW21}]
    \label{lemma: IPS refutation is a multiple}
    Let $f,\overline{g}, \xbar^2- \xbar \in \F[x_1,\dots, x_n]$ be an unsatisfiable systems of equations, where $\overline{g}, \xbar^2- \xbar$ is satisfiable. Let $C \in \F[\xbar, y, \zbar, \wbar]$ be an $\IPS$ refutation of $f, \overline{g}, \xbar^2-\xbar$. Then
    \[
        1-C(\xbar, 0 , \overline{g}, \xbar^2- \xbar)
    \]
    is a nonzero multiple of $f$.
\end{lemma}

From here, consider the field $\F_q$ for some constant $q$, and let the following two polynomials be our hard system of equations.
\begin{equation}
    f \coloneqq \prod_{i < j} (x_i + x_j +1), \quad
    g \coloneqq \prod_{i=1}^n (1-x_i) -1.
\end{equation}

Note that our $f$ above is the same as in \cite{FSTW21}, but our $g$ differs (they use $\sum_{i=1}^n x_i - n$, which is why they must work in fields of characteristic $>n$). We now state our lower bound.

\begin{theorem}
    \label{theorem: lower bounds by multiple}
    Let $\F_q$ be a finite field of constant characteristic $q$. Let $f,g \in \F[x_1,\dots, x_n]$, where $f \coloneqq \prod_{i < j} (x_i + x_j +1)$ and $g \coloneqq \prod_{i=1}^n (1-x_i) -1$. Then, the system of equations $f, g, \xbar^2- \xbar$ is unsatisfiable, and any $\roAlbIPS$ refutation (in any order of the variables) requires size $\exp\big({\Omega(n)}\big)$.
\end{theorem}

\begin{proof}
    The system $g(\xbar)=0$ and $\xbar^2- \xbar=0$ is satisfiable and has the unique satisfying assignment $\overline{0}$. However, this single assignment does not satisfy $f$ as $f(\overline{0}) = \prod_{i<j} (0+0+1) =1 \neq 0$, so the entire system is unsatisfiable. Thus by \Cref{lemma: IPS refutation is a multiple}, for any $\roAlbIPS$ refutation $C(\xbar,y,z, \wbar)$ of $f, g, \xbar^2- \xbar$, $1- C(\xbar, 0 , g, \xbar^2-\xbar)$ is a nonzero multiple of $f$.

    Let $s$ be the size of $C$ as an roABP. We now argue that $1-C(\xbar, 0 ,g, \xbar^2- \xbar)$ has a small read-\emph{twice} oblivious ABP. First, note that we can expand $C(\xbar, 0, z, \wbar)$ into powers of $z$: 
    $$
    C(\xbar, 0 ,z, \wbar)  = C_0(\xbar, \wbar) + C_1(\xbar, \wbar) z.
    $$
    There are only two terms because $C(\xbar, y,z, \wbar)$ is a $\roAlbIPS$ refutation, implying the degree of $z$ in $C(\xbar, y, z, \wbar)$ is at most $1$. Each $C_i(\xbar,\wbar)$ has a $\poly(s)$-size roABP (in the order of the variables of $C$ where $z$ is omitted), as we can compute $C_i$ via interpolation over $z$ (since each evaluation preserves roABP size by \Cref{fact:roABP}). Furthermore, as $g$ can also be computed by a $\poly(n)$-size roABP, we see that 
    $$
    1-C(\xbar,0,g ,\wbar) = 1- C_0(\xbar,\wbar) -C_1(\xbar,\wbar) g
    $$
    has a $\poly(s,n)$-size roABP in the order of variables that $C$ induces on $\xbar, \wbar$. As each Boolean axiom $x_i^2- x_i$ only refers to a single variable, substituting $\wbar \leftarrow \xbar^2-\xbar$ for $1-C(\xbar, 0 ,g, \wbar)$ in the roABP will preserve obliviousness, but now each variable is read twice. Therefore, $1-C(\xbar, 0 ,g, \xbar^2- \xbar)$ has a $\poly(s,n)$-size read-twice oblivious ABP. Finally, using the fact that a nonzero multiple of $f$ requires $\exp(\Omega(n))$ size to be computed as read-twice oblivious ABPs (\Cref{lemma: rtABP lower bounds for multiple}), it follows that $\poly(s,n) \geq \exp(\Omega(n))$, implying $s \geq \exp(\Omega(n))$ as desired.
\end{proof}


% ---------------------------------------------------
\subsection{Limitations}
% ---------------------------------------------------

The following discusses the limitations of the functional lower bound method for roABP-$\IPS$. Namely, we show that it is impossible to get a non-placeholder functional lower bound against roABP-$\IPS$ over finite fields, even if the refutation is restricted to a multilinear polynomial. We first recall this fact about roABPs.

\begin{fact}
\label{fact:roabp_width}
If $f,g\in\mathbb{F}[\overline{x}]$ are computable by width-$r$ and width-$s$ roABPs respectively, then
\begin{itemize}
    \item $f+g$ is computable by a width-$(r+s)$ roABP.
    \item $f\cdot g$ is computable by a width-$(rs)$ roABP.
\end{itemize}
\end{fact}

Now, as discussed in \Cref{sec:upper_bound}, for a given unsatisfiable instance $f$ in finite field $\mathbb{F}_p$, by Fermat's Little Theorem we have the following refutation:  
\begin{equation}
\label{eq:finite_ub}
    f(\overline{x})^{p-2}f(\overline{x})=1 \mod \overline{x}^2-\overline{x}.
\end{equation}

Thus, if $f$ is easy for roABPs then by \Cref{fact:roabp_width}, so is $f(\overline{x})^{p-2}$ (as $p$ is constant), so in this case it is impossible to acheive a lower bound on roABP-$\IPS$ refutations. Now, consider the case where refutations must be multilinear (that is, an analogue to the constant-depth multilinear $\IPS$ proof system from \Cref{sec:cd-IPS}). In this proof system, the refutation in \Cref{eq:finite_ub} cannot work, as it is not multilinear. However, it is shown in \cite{FSTW21} that roABPs are closed under multilinearization. We restate their result for concreteness.

\begin{proposition}[Proposition 4.5 from \cite{FSTW21}]
    Let $f\in\mathbb{F}[\overline{x}]$ be computable by a width-$r$ roABP, in order of the variables $x_1<\cdots<x_n$, and with individual degrees at most $d$. Then, ml$(f)$ has a poly$(r,n,d)$-explicit width-$r$ roABP in order of the variables $x_1<\cdots<x_n$.
\end{proposition}
Thus, we simply consider the multilinear polynomial $g=\text{ml}(f^{p-2})$ to be our refutation (as $g$ agrees with $f^{p-2}$ over the Boolean cube, implying \Cref{eq:finite_ub} holds). By the above proposition, since $f^{p-2}$ has a small roABP computing it, so does $g$. This leads to the following theorem.

\begin{theorem}
\label{thm:flbm_limitation}
    The functional lower bound method cannot establish non-placeholder lower bounds on the size of roABP-$\IPS$ refutations when working in finite fields.
\end{theorem}


% -----------------------------------------------------
\section{Towards Lower Bounds for CNF Formulas}\label{sec:translation-lemmas}
% -----------------------------------------------------

    We now turn to the problem of establishing lower bounds for CNF formulas. In the previous sections, the lower bounds we presented were for algebraic instances. In contrast, we show that an $\IPS$ lower bound against an unsatisfiable set of one or more polynomial equations over finite fields implies the existence of a hard Boolean instance. However, this implication requires a subsystem of $\IPS$ which can reason with large degree, therefore our results do not meet this criteria. Accordingly, the existence of any hard instance for $\IPS$ over finite fields (even when the equations are given as algebraic circuits), allowing refutations of possibly exponential total degree, implies the existence of hard Extended Frege instances. Similarly, if the hard instance is only against $\IPS$ refutations of polynomial total degree, then there are hard instances against Frege. 
    \medskip 

    We work in finite field $\mathbb{F}_q$ where $q$ is a constant (independent of the size of the formulas and their number of variables). When we work with $\CNF$ formulas in $\IPS$ we assume that the $\CNF$ formulas are translated according to the following definition.
    \begin{definition}[Algebraic translation of CNF formulas]
        \label{def: Algebraic translation of CNF formulas}
        Given a $\CNF$ formula in the variables $\overline{x}$, every clause $\bigvee_{i \in P}x_i \lor \bigvee_{j \in N} \neg x_j$ is translated into $\prod_{i \in P}(1-x_i) \cdot \prod_{j \in N}x_j=0$. (Note that these expressions are represented as algebraic circuits, where the products are not expanded.)
    \end{definition}
    Notice that a $\CNF$ formula is satisfiable by 0-1 assignment if and only if the assignment satisfies all the equations in the algebraic translation of the $\CNF$. The following definitions are taken from \cite{ST25}, and we supply them here for completeness. 
    \begin{definition}[Algebraic extension axioms and unary bits \cite{ST25}] 
        \label{def: algebraic extension axioms and unary bits}
        Given a circuit $C$ and a node $g$ in $C$, we call the equation
        \begin{equation*}
            x_g = \sum_{i=0}^{q-1} i \cdot x_{g_i}
        \end{equation*}
        the algebraic extension axiom of $g$, with each variable $x_{g_i}$ being the $i$th unary-bit of $g$.
    \end{definition}

    \begin{definition}[Plain CNF encoding of constant-depth algebraic circuit $\cnf(C(\overline{x}))$ \cite{ST25}]
        \label{def: plain CNF encoding of constant-depth algebraic circuit cnf(C(x))}
        Let $C(\overline{x})$ be a circuit in the variables $\overline{x}$. The plain $\CNF$ encoding of the circuit $C(\overline{x})$, denoted $\cnf(C(\overline{x}))$ consists of the following $\CNF$s in the unary-bits variables of all the gates in $C$ and extra extension variables (and only in the unary-bit variables):
        \begin{enumerate}
            \item If $x_i$ is an input node in $C$, the plain $\CNF$ encoding of $C$ uses the variables $x_{x_{i0}},\cdots,x_{x_{i(q-1)}}$ that are the unary-bits of $x_i$, and includes clauses ensuring that exactly one unary bit is 1 and all others are 0:
            \begin{equation*}
                    \bigvee_{j=0}^{q-1} x_{x_i j} \land \bigwedge_{j \neq l \in \{0,\cdots,q-1\}} (\neg x_{x_i j} \lor \neg x_{x_i l}).
            \end{equation*}
            \item If $\alpha \in \mathbb{F}_q$ is a scalar input node in $C$, the plain $\CNF$ encoding of $C$ contains the $\{0,1\}$ constants corresponding to the unary-bits of $\alpha$. These constants are used when fed to (translation of) gates according to the wiring of $C$ in item 4.
            \item For every node $g$ in $C(\overline{x})$ and every satisfying assignment $\overline{\alpha}$ to the plain $\CNF$ encoding, the corresponding unary-bit $x_{g_i}$ evaluates to $1$ if and only if the value of $g$ equals $i \in {0,\dots, q-1}$ (when the algebraic inputs $\overline{x} \in (\mathbb{F}_q)^\ast$ to $C(\overline{x})$ take on the values corresponding to the Boolean assignment $\overline{\alpha}$; "$\ast$" here means the Kleene star). This is ensured with the following equations: if $g$ is a $\circ \in \{+, \times\}$ node that has inputs $u_1,\cdots, u_t$. Then we consider the following equations:
                \begin{align*}
                     &u_1 \circ u_2 = v_1^g \\
                    &u_{i+2} \circ v_{i}^g = v_{i+1}^g, \qquad 1 \leq i \leq t-3 \\
                    &u_{t} \circ v_{t-2}^g = g.
                \end{align*}
                Then, for each equation above, for simplicity, we denote as $x \circ y =z$. For each $x+y=z$ we have a $\CNF$ $\phi$ in the unary-bits variables of $x, y,z$ that is satisfied by assignment precisely when the output unary-bits of $z$ get their correct values based on the (constant-size) truth table of $\circ$ over $\mathbb{F}_q$ and the input unary-bits of $x$ and $y$ (we ensure that if more than one unary-bit is assigned $1$ in any of the unary-bits of  $x,y,z$ then the $\CNF$ is unsatisfiable).
            \item For every unary-bit variable $x_{g_i}$, we have the Boolean axiom (recall we write these Boolean axioms explicitly since we are going to work with $\IPS^\alg$):
            \begin{equation*}
                x_{g_i}^2 - x_{g_i} = 0.
            \end{equation*}
        \end{enumerate}

    \end{definition}
    Therefore, we can see that the formula size of $\cnf(C(\overline{x})=0)$ is $\poly(q^2 \cdot |C|)$.
    \begin{definition}[Plain CNF encoding of a constant-depth circuit equation $\cnf(C(\overline{x})=0)$ \cite{ST25}]
        \label{def: plain CNF encoding of a constant-depth circuit equation cnf(C(x)=0)}
         Let $C(\overline{x})$ be a circuit in the variables $\overline{x}$. The plain $\CNF$ encoding of the circuit equation $C(\overline{x})=0$ denoted $\cnf(C(\overline{x})=0)$ consists of the following $\CNF$ encoding from \Cref{def: plain CNF encoding of constant-depth algebraic circuit cnf(C(x))} in the unary-bits variables of all the gates in $C$ ( and only in the unary-bit variables), together with the equations:
         \begin{equation*}
                x_{g_{out}0} =1 \quad \text{and} \quad x_{g_{out}i} = 0, \quad \text{for all }i=1,\cdots,q-1,
            \end{equation*}
            which express that $g_{out} = 0$, where $g_{out}$ is the output node of $C$.

    \end{definition}

    \begin{definition}[Extended CNF encoding of a circuit
    equation (circuit, resp.); $\ecnf(C(\overline{x})=0)$ ($\ecnf(C(\overline{x}))$, resp.) \cite{ST25}]
        \label{def: Extended CNF encoding of a circuit equation cnf(C(x)=0)}
         Let $C(\overline{x})$ be a circuit in the variables $\overline{x}$ over the finite field $\mathbb{F}_q$. The extended $\CNF$ encoding of the circuit equation $C(\overline{x})=0$ (circuit $C(\overline{x})$, resp.), in symbols $\ecnf(C(\overline{x})=0)$ ($\ecnf(C(\overline{x}))$, resp.), is defined to be a set of algebraic equations over $\mathbb{F}_q$ in the variables $x_g$ and $x_{g0},\cdots,x_{gq-1}$ which are the unary-bit variables corresponding to the node $g$ in $C$, that consist of:
         \begin{enumerate}
             \item the plain $\CNF$ encoding of the circuit equation $C(\overline{x})=0$ (circuit $C(\overline{x})$, resp.), namely, $\cnf(C(\overline{x})=0)$ ($\cnf(C(\overline{x}))$, resp.); and
             \item the algebraic extension axiom of $g$, for every gate $g$ in $C$.
         \end{enumerate}

    \end{definition}

    Since we work with extension variables, it is more convenient to express a circuit equation $C(\overline{x})=0$ as a set of equations encoding each gate of $C$, which we call the straight line program of $C(\overline{x})$ (and is equivalent in strength to algebraic circuits).

    \begin{definition}[Straight line program ($\SLP$)]
        \label{def: Straight line program SLP}
        An $\SLP$ of a circuit $C(\overline{x})$, denoted by $\SLP(C(\overline{x}))$, is a sequence of equations between variables such that the extension variable for the output node computes the value of the circuit assuming all equations hold. Formally, we choose any topological order $g_1,g_2, \cdots,g_i,\cdots,g_{|C|}$ on the nodes of the circuit $C$ (that is, if $g_j$ has a directed path to $g_k$ in $C$ then $j < k$) and define the following set of equations to be the $\SLP$ of $C(\overline{x})$:
        \begin{center}
            $g_i = g_{j1} \circ g_{j2} \circ \cdots \circ g_{jt}$ for $\circ \in \{+, \times \}$ iff $g_i$ is a $\circ$ node in $C$ with $t$ incoming edges from $g_{j1},\cdots,g_{jt}$.
        \end{center}
        An $\SLP$ representation of a circuit equation $C(\overline{x})=0$ means that we add to the $\SLP$ above the equation $g_{|C|}=0$, where $g_{|C|}$ is the output node of the circuit.
    \end{definition}

    The following lemma, which we refer to as the \emph{translation lemma} throughout this paper, shows that we can derive (with some additional axioms) the circuit equation $C(\overline{x})=0$ given the extended $\CNF$ encoding of this circuit equation $\ecnf(C(\overline{x})=0)$, and vice versa.
    \begin{lemma}[Translating between extended $\CNF$s and circuit equations in Fixed Finite Fields \cite{ST25}] 
        \label{lemma: Translating between extended CNF formulas and circuit equations in Fixed finite fields}
        Let $\mathbb{F}_q$ be a finite field, and let $C(\overline{x})$ be a circuit of depth $\Delta$ in the $\overline{x}$ variables over $\mathbb{F}_q$. Then, both of the following hold:
        \begin{align}
            \ecnf(C(\overline{x})=0) \sststile{\IPS^\alg}{*,O(\Delta)} C(\overline{x})=0.  
        \end{align}
\begin{equation}
\hspace*{-6.5em}
\begin{aligned}
\begin{array}{@{}r@{}}
\{x_g  =\sum_{i=0}^{q-1} i \cdot x_{gi}: g \text{ is a node in } C\}, \\[0.7em]
\{x_{gi}^2 - x_{gi} =0: g \text{ is a node in } C, 0 \leq i < q\}, \\[0.7em]
\{\sum_{i=0}^{q-1} x_{gi} =1 : g \text{ is a node in } C\}, \\[0.7em]
\SLP(C(\overline{x})), \\[0.7em]
C(\overline{x})=0
\end{array}
\quad
\sststile{\IPS^\alg}{*,O(\Delta)}
\quad
\ecnf(C(\overline{x})=0).
\end{aligned}
\label{eq:your_label}
\end{equation}
    \end{lemma}
\smallskip

    \begin{proposition}[Proposition 3.7 in \cite{ST25}]
        \label{prop: C <-> cnf <-> ecnf fixed finite fields}
        Let $C(\overline{x})=0$ be a circuit equation over $\mathbb{F}_q$ where $q$ is any constant prime. Then, $C(\overline{x})=0$ is unsatisfiable over $\mathbb{F}_q$ iff $\cnf(C(\overline{x})=0)$ is an unsatisfiable $\CNF$ iff $\ecnf(C(\overline{x})=0)$ is an unsatisfiable set of equations over $\mathbb{F}_q$.
    \end{proposition}

    From here, we extend their result by eliminating these additional axioms in both directions. The only additional axioms we need are the \emph{field axioms} $\{x^q -x =0: x \text{ is a variable in } C\}$, which can be easily derived from the Boolean axioms if the variables in the circuit are Boolean (as we are working in finite fields). We use $\UBIT_j(x)$ to denote the following Lagrange polynomial:
    \begin{equation*}
        \label{UBITs}
        \frac{\prod_{i=0, i \neq j}^{q-1}(x-i)}{\prod_{i=0, i \neq j}^{q-1}(j-i)},
    \end{equation*}
    where $x$ can be a single variable or an algebraic circuit. Hence, it is easy to observe that
    \begin{equation*}
        \UBIT_j(x) = \begin{cases}
            1, \quad x = j,\\
            0, \quad \text{otherwise}.
        \end{cases}
    \end{equation*}
    Also, suppose $x$ has size $|x|$ and depth $\depth(x)$ (when $x$ is a single variable, it has size $1$ and depth $1$). Then, $\UBIT_j(x)$ can be computed by an algebraic circuit of size $O(|x|^{q-1})$ and depth $\depth(x)+2$. In addition, we introduce a Semi-CNF $\SCNF$, which is a substitution instance of a $\CNF$.


    \begin{definition}[Semi-CNF $\SCNF$ encoding of a constant-depth circuit equation $\SCNF(C(\overline{x})=0)$]
        \label{def: semi-CNF encoding}
        Let $C(\overline{x})$ be a circuit in the variables $\overline{x}$. The semi-CNF encoding of the circuit equation $C(\overline{x})=0$ denoted $\SCNF(C(\overline{x}))$ is a substitution instance of the plain CNF encoding in \Cref{def: plain CNF encoding of a constant-depth circuit equation cnf(C(x)=0)} where each unary-bits $x_{uj}$ of all the gates and extra extension variables $u$ is substituted with $\UBIT_j(C_u)$ where $C_u$ is the constant-depth algebraic circuit computes $u$.\footnote{This $C_u$ can be constructed from $\SLP$s easily.}
    \end{definition}
    We now demonstrate the connection between semi-CNFs and circuit equations.


    \begin{theorem}[Translate semi-CNFs from circuit equations in Fixed Finite Fields]
        \label{lemma: Translate semi-CNFs from circuit equations in Fixed Finite Fields}
        Let $\mathbb{F}_q$ be a finite field, and let $C(\overline{x})$ be a circuit of depth $\Delta$ in the $\overline{x}$ variables over $\mathbb{F}_q$. Then, the following holds
        \begin{gather*}
            \{x^q -x =0: x \text{ is a variable in } C\}, \;C(\overline{x})=0  \sststile{\IPS^\alg}{*,O(\Delta)} \SCNF(C(\overline{x})=0).
        \end{gather*}
    \end{theorem}

Since the field equations $x^q-x=0$ are efficiently derivable from the Boolean axioms, we get the following for $\IPS$ (which by default contains the Boolean axioms):
\begin{gather*}
        C(\overline{x})=0  \sststile{\IPS^\alg}{*,O(\Delta)} \SCNF(C(\overline{x})=0).
        \end{gather*}

    \begin{proof}
        In \Cref{lemma: Translating between extended CNF formulas and circuit equations in Fixed finite fields}, the given axioms include:
        \begin{enumerate}
        \centering
            \item[$(i)$] $\{x_g = \sum_{i=0}^{q-1}i \cdot x_{gi}: g \text{ is a node in } u\circ v=w \}$,
            \item[$(ii)$] $\{x_{gi}^2 - x_{gi} = 0: g \text{ is a node in } u\circ v =w\}$,
            \item[$(iii)$] $\{\sum_{i=0}^{q-1} x_{gi} =1 : g \text{ is a node in } u\circ v = w\}$,
            \item[$(iv)$] $\sum_{i=0}^{q-1}i \cdot x_{ui} \circ \sum_{i=0}^{q-1}i \cdot x_{vi} = \sum_{i=0}^{q-1}i \cdot x_{wi}$,   
         \end{enumerate}
        and there is a constant-depth constant-size $\IPS$ derivation of the plain CNF encoding of $u \circ v = w$. Thus, we must show that we can derive the above four axioms when we substitute $x_{gi}$ with $\UBIT_i(C_g)$. Due to the standard property of Lagrange polynomials, the following circuit equation is a polynomial identity, which can be proved freely in $\IPS$ (in finite field $\mathbb{F}_q$):
        \begin{equation*}
            x = \sum_{j=0}^{q-1} j \cdot \UBIT_j(x),
        \end{equation*}
        which is exactly the axiom in $(i)$. Hence, we know that $C_u = \sum_{j=0}^{q-1} j \cdot \UBIT_j(C_u)$, $C_v = \sum_{j=0}^{q-1} j \cdot \UBIT_j(C_v)$ and $C_u \circ C_v = C_w = \sum_{j=0}^{q-1} j \cdot \UBIT_j(C_w)$. These polynomial identities give us the substitution instance of the last equation $(iv)$:
        \[
             \sum_{j=0}^{q-1} j \cdot \UBIT_j(C_u) \circ  \sum_{j=0}^{q-1} j \cdot \UBIT_j(C_v) =  \sum_{j=0}^{q-1} j \cdot \UBIT_j(C_w).
        \]

        The second set of equations $(ii)$ is in the ideal of the field axioms for $g$. We show that in depth-$O(\Delta)$ and polynomial size, we can derive the field axioms $C_g^q - C_g =0$ for all circuits that compute the nodes and extension variables (using the field axioms $x^q-x=0$, for every input variable). We derive the field axioms for nodes and extension variables by induction on depth.  
        When $g$ is a $\circ \in \{+, \times\}$ node that has inputs $u_1,\cdots, u_t$, the $\SLP$s includes:
        \begin{align*}
            &u_1 \circ u_2 = v_1^g \\
            &u_{i+2} \circ v_{i}^g = v_{i+1}^g, \qquad 1 \leq i \leq t-3 \\                &u_{t} \circ v_{t-2}^g = g.
        \end{align*}
        For each $v_i^{g} = u_1 \circ \cdots \circ u_{i+2}$, $C_{v_i^g} =C_{u_1} \circ \cdots \circ C_{u_{i+2}}$ is a polynomial identity. By induction, we already have the field axioms for all $C_{u_i}$. We show that we can derive the field axioms for all $C_{v_i^g}$ and $C_g$ simultaneously. Now suppose $\circ = +$, then the following equations hold over $\F_q$:
        \begin{align*}
            C_{v_i^g}^q &\equiv (C_{u_1}+ \cdots + C_{u_{i+2}})^q \\
                        & \equiv C_{u_1}^q + \cdots + C_{u_{i+2}}^q \\
                        & \equiv C_{u_1} + \cdots + C_{u_{i+2}} \\
                        & \equiv C_{v_i^g}.
        \end{align*}
        The proof for the node $g$ is the same. We can therefore conclude that if $\circ =+$, we can derive the field axioms for all $C_{v_i^g}$ and $C_g$ simultaneously. Suppose $\circ = \times$, then the following equations hold over $\F_q$:
        \begin{align*}
            C_{v_i^g}^q &\equiv (C_{u_1}\times \cdots \times C_{u_{i+2}})^q \\
                        & \equiv C_{u_1}^q \times \cdots \times C_{u_{i+2}}^q \\
                        & \equiv C_{u_1} \times \cdots \times C_{u_{i+2}} \\
                        & \equiv C_{v_i^g}.
        \end{align*}
        Again, the proof for the node $g$ is the same and thus we conclude that given the field axioms for the input variables,  we can derive the field axioms for all circuits that compute the nodes and extension variables in depth $O(\Delta)$ and polynomial size. It remains to show that $\UBIT_j(x)^2 - \UBIT_j(x) =0$ is in the ideal of the field axiom of $x$, for any $x$. The equation $x^q-x=0$ is the unique monic polynomial of degree $q$ that has all elements of $\mathbb{F}_q$ as roots. Therefore, any polynomial $f(x) \in \mathbb{F}_q[x]$ that vanishes when evaluated to any $x \in \mathbb{F}_q$ must be divisible by $x^q-x$. It is easy to check that $\UBIT_j(x)^2 - \UBIT_j(x) $ vanishes at all points, implying it is in the ideal generated by $x^q-x$. Hence, there is a degree (of $x$) $q-2$ polynomial $Q(x)$ such that $Q(x) \cdot (x^q-x) = \UBIT_j(x)^2 - \UBIT_j(x)$, and as a result there is a depth-$\Delta$ polynomial-size proof for $\UBIT_j(x)^2 - \UBIT_j(x) =0$ from $x^q-x$.

        Finally, $\sum_{j=0}^{q-1} \UBIT_j(x) =1$ is a polynomial identity, for every $x$. This follows from the fact that it is a single-variable polynomial with degree $q-1$, but has $q$ many distinct roots. By the fundamental theorem of algebra, it must be a zero polynomial, and consequently we get axioms in $(iii)$ for free in $\IPS$. All together, we can conclude that
        \[
            \{x^q -x =0: x \text{ is a variable in } C\}, C(\overline{x})=0  \sststile{\IPS^\alg}{*,O(\Delta)} \SCNF(C(\overline{x})=0
        \]
        by first deriving the substitution instance above, and then substituting the derivation for the CNF to get the derivation for the semi-CNF.
    \end{proof}


    Since $\SCNF$s are substitution instances of $\CNF$s, lower bounds for $\CNF$s imply lower bounds for $\SCNF$s, which gives the following corollary.
    \begin{corollary}[Lower bounds for circuit equations imply lower bounds for CNFs]
        \label{corollary: lower bounds for circuit equation implies lower bounds for CNFs}
         Let $\mathbb{F}_q$ be a finite field, and let $\{C(\overline{x})\}$ be a set of circuits of depth at most $\Delta$ in the Boolean variable $\overline{x}$. Then, if a set of circuit equations $\{C(\overline{x}) =0\}$ cannot be refuted in $S$-size, $O(\Delta^\prime)$-depth $\IPS$, then the CNF encoding of the set of circuit equations $\{\CNF(C(\overline{x})=0)\}$ cannot be refuted in ($S-\poly(|C|)$)-size, $O(\Delta^\prime + \Delta)$-depth $\IPS$.
    \end{corollary}



    \begin{lemma}[Translate circuit equations from semi-CNFs in fixed finite fields]
        \label{lemma: Translate circuit equations from semi-CNFs in Fixed Finite Fields}
        Let $\mathbb{F}_q$ be a finite field, and let $C(\overline{x})$ be a circuit of depth $\Delta$ in the $\overline{x}$ variables over $\mathbb{F}_q$. Then, the following holds:
        \begin{gather*}
            \{x^q -x =0: x \text{ is a variable in } C\}, \; \SCNF(C(\overline{x})=0)  \sststile{\IPS^\alg}{*,O(\Delta)} C(\overline{x})=0.
        \end{gather*}
    \end{lemma}

    \begin{proof}
        From the CNF encoding of each $\SLP$ axiom $u\circ v =w$ and the Boolean axioms for each unary bit, we have
        \[
            \sum_{j=0}^{q-1} j\cdot x_{uj} \circ \sum_{j=0}^{q-1} j\cdot  x_{vj} = \sum_{j=0}^{q-1} j\cdot  x_{wj}
        \]
        in constant-depth polynomial-size $\IPS$. As we showed in the proof of \Cref{lemma: Translate semi-CNFs from circuit equations in Fixed Finite Fields}, the field axioms for all circuits that compute nodes and extension variables can be derived from the field axioms of the input variables, in constant-depth polynomial-size $\IPS$. We also showed that these derived field axioms can in turn also derive the Boolean axioms for all $\UBIT$ polynomials (of circuits that compute nodes and extension variables) in constant-depth polynomial-size $\IPS$. As a result, substituting each $x_{gj}$ above with $\UBIT_j(C_g)$ for $g \in \{u,v,w\}$ and $0 \leq j \leq q-1$, we get a constant-depth polynomial-size $\IPS$ derivation of
        \[
            \sum_{j=0}^{q-1} j\cdot  \UBIT_j(C_u) \circ \sum_{j=0}^{q-1} j \cdot \UBIT_j(C_v) = \sum_{j=0}^{q-1} j \cdot \UBIT_j(C_w)
        \]
        from the semi-CNF encoding of $u \circ v =w$ and the Boolean axioms for each $\UBIT$. Lastly, as mentioned in the proof of  \Cref{lemma: Translate semi-CNFs from circuit equations in Fixed Finite Fields}, in finite field $\mathbb{F}_q$ we get the following circuit equation for free in $\IPS$ (as it is a polynomial identity):
        \begin{equation*}
            x = \sum_{j=0}^{q-1} j \cdot \UBIT_j(x).
        \end{equation*}

        Therefore, we get the full $\SLP$ for the circuit equation $C(\overline{x})=0$, and consequently the circuit equation can easily be obtained from this $\SLP$.
    \end{proof}




