\section{Additional Details about the Simulation Hamiltonian}
\label{app:HamDetails}
\noindent
This work considers 1+1D QCD with periodic boundary conditions (PBCs) and two flavors of quarks, up $u$ and down $d$.
Discretized onto a staggered lattice with $L$ spatial sites, corresponding to $N=2L$ staggered sites, the Kogut-Susskind Hamiltonian is~\cite{Kogut:1974ag, Banks:1975gq},
%
\begin{equation}
\hat{H}_{\text{KS}} \ = \ \sum_{f=u,d}\left [\frac{1}{2}\sum_{n=0}^{N-1}\left (\phi^{(f)\dagger}_{n} U_n\phi_{n+1}^{(f)} + {\rm h.c.} \right ) \ + \ m_f \sum_{n=0}^{N-1}(-1)^n\phi^{(f)\dagger}_{n}\phi_{n}^{(f)}\right ]\ + \ \frac{g^2}{2}\sum_{n=0}^{N-1}\sum_{a=1}^8 \vert {\bf E}_n^{(a)} \vert^2  \ ,
\label{eq:HKS}
\end{equation}
%
where $f =\{u,d\}$ labels the quark flavor, $m_f$ is the quark mass and $g$ is the gauge coupling.
The quark field operators $\phi_n^{(f)}$ are in the fundamental representation ${\bf 3}$ of $SU(3)$, and the three color components $\{r,g,b\}$ have been suppressed for simplicity.
The chromoelectric field ${\bf E}_n^{(a)}$ is in the adjoint representation of $SU(3)$ with $a=\{1,2,\ldots,8\}$.
The spatial gauge link in $A_t^{(a)}=0$ (Weyl) gauge is $U_n$.
Staggered sites related by one period are identified, e.g., $\phi_n^{(f)} = \phi_{n+N}^{(f)}$.

Physical states must satisfy Gauss's law, ${\bf E}_n^{(a)} - {\bf E}_{n-1}^{(a)} = Q_n^{(a)}$, where $Q_n^{(a)} = \sum_f\phi^{(f)\dagger}T^{(a)}\phi^{(f)}$ are the $SU(3)$ charges and the $T^{(a)}$ are the generators of $SU(3)$ in the {\bf 3} representation, i.e., they are $3\times3$ matrices.
With open boundary conditions, these constraints uniquely determine the state of the the gauge field given the state of the fermions.
As a result, explicit gauge field degrees of freedom can be removed, leaving a system of fermions interacting through a Coulomb interaction.
With PBCs, there is one spatial mode of the gauge field that is not constrained.
In order to keep the translational symmetry manifest, it is beneficial to isolate the $k=0$ (zero mode) component of the gauge field~\cite{Dempsey:2022nys},
%
\begin{align}
\hat{H}_{\text{KS}} \ \to \ &\sum_{f=u,d}\left [\frac{1}{2}\sum_{n=0}^{N-1}\left (\phi^{(f)\dagger}_{n} U \, \phi_{n+1}^{(f)} + {\rm h.c.} \right ) \ + \ m_f \sum_{n=0}^{N-1}(-1)^n\phi^{(f)\dagger}_{n}\phi_{n}^{(f)}\right ]  \nonumber \\
&+ \ \frac{Ng^2}{2}\sum_{a=1}^8\left (E^{(a)}\right )^2 \ + \
\frac{g^2}{2}
\sum_{s=1}^{L}\left (-s + \frac{s^2}{N} \right ) (1 - \frac{1}{2} \delta_{s,L}) \left(\ \sum_{n=0}^{N-1}\sum_{a=1}^8 
Q_n^{(a)} Q_{n+s}^{(a)} \ \right)  \ .
\label{eq:HKSPBC}
\end{align}
%
Here, $E^{(a)} = \sum_{n=0}^{N-1} E_n^{(a)}/N$ is the zero mode of the electric field, and $U^N = \prod_n U_n$ is its conjugate variable.
The gauge field populates a bosonic Hilbert space that is formally infinite dimensional.
However, it is expected that observables will converge rapidly in the chromoelectric field basis if an increasing number of states are kept.
In this paper, the gauge-field dynamics are frozen, leaving only fermionic degrees of freedom.
The convergence of observables with increasing number of gauge-field states will be quantified in future work.
The Hamiltonian 
that we implement
only has fermionic operators,
%
\begin{align}
\hat{H}_{\text{KS}} \ \to \ &\sum_{f=u,d}\left [\frac{1}{2}\sum_{n=0}^{N-1}\left (\phi^{(f)\dagger}_{n} \phi_{n+1}^{(f)} + {\rm h.c.} \right ) \ + \ m_f \sum_{n=0}^{N-1}(-1)^n\phi^{(f)\dagger}_{n}\phi_{n}^{(f)}\right ]  \nonumber \\
&
\qquad
+ \
\frac{g^2}{2}
\sum_{s=1}^{L}\left (-s + \frac{s^2}{N} \right )(1-\frac{1}{2}\delta_{s,L}) \left(\ \sum_{n=0}^{N-1}\sum_{a=1}^8 
Q_n^{(a)} Q_{n+s}^{(a)} \ \right)  \ .
\label{eq:HKSPBCv2}
\end{align}
%
Similar Hamiltonians that have used Gauss's law to remove gauge degrees of freedom in 1+1D lattice gauge theories with PBCs were used in Refs.~\cite{Klco:2018kyo,Zache:2018cqq,Nagele:2018egu,Davoudi:2025rdv,Chai:2025qhf,Farrell:2025nkx}.



%%%%%%%
\subsection{Truncating the Chromoelectric Interaction}
\label{sec:truncHam}
\noindent
In theories with a mass gap between the vacuum and first excited state, like 1+1D QCD, correlations in the vacuum decay exponentially between distant charges,
%
\begin{equation}
\sum_{a=1}^8\langle Q_n^{(a)} Q_{n+s}^{(a)}\rangle \ \sim \ e^{-c_1 s \, m_{\text{hadron}}} \ ,
\end{equation}
%
where $c_1$ is a geometrical factor, and $m_{\text{hadron}}$ is the mass of the lightest excitation in the vacuum sector, the scalar meson. 
Vacuum expectation values are denoted by $\langle \, . \, \rangle$.
In previous work~\cite{Farrell:2024fit}, the exponential decay of correlations between electric charges in the Schwinger model (one-dimensional $U(1)$ lattice gauge theory) was used to form an approximate interaction where charges interacting beyond a certain range were truncated.\footnote{In $U(1)$ gauge theory, due to staggering, it is only the connected part of this correlation that falls exponentially.
In $SU(3)$ gauge theory, the disconnected part of the correlation vanishes when evaluated in physical color singlet states.}
A similar strategy is used here to truncate interactions between color charges separated by more than $\lambda$ staggered sites as,
%
\begin{equation}
\hat{H}_{el}(\lambda) \ = \ \frac{g^2}{2}
\sum_{s=1}^{\lambda}\left (-s + \frac{s^2}{2L} \right )(1-\frac{1}{2} \delta_{s,L}) \left(\ \sum_{n=0}^{2L-1}\sum_{a=1}^8 
Q_n^{(a)} Q_{n+s}^{(a)} \right ) \ .
\label{eq:Hellambda}
\end{equation}
%
This truncated interaction reduces the two-qubit gate count required for time evolution from scaling as $\mathcal{O}(N^2)$ to $\mathcal{O}(\lambda N)$.
The quantum simulations performed on IonQ Forte-generation QPUs in Sec.~\ref{sec:IonQsim} used $\lambda=1$.




