\section{Optimal Investment Strategies}
\label{sec:solution}
In this section, we solve the problem \eqref{eq:game_problem} to obtain agents' optimal investment strategies. We show that agents' optimal strategies are linear combinations of their rational strategies, and propose a fast algorithm to find the approximated optimal strategies with low computational complexity. 

\subsection{The Analytical Solution of Agents' Optimal Strategies}
% Using the variational method, we can derive the analytical solution of the optimal strategies. 
We first show that the $j$-th agent's optimal strategy $\{\boldsymbol{P}_j^*(t)\}_{t\in\mathcal{T}}$ is a linear combination of his/her rational strategy $\{\bar{\boldsymbol{P}}_j(t)\}_{t\in\mathcal{T}}$ and his/her average followees' optimal strategy $\{\boldsymbol{Q}_j^*(t)\}_{t\in\mathcal{T}}$. In the following, we denote $\boldsymbol{I}_m\in\mathbb{R}^{m\times m}$ and $\boldsymbol{O}_m\in\mathbb{R}^{m\times m}$ as the identity and all-zero matrices, respectively.

\begin{theorem}\label{the:1}
The $j$-th agent's optimal strategy $\{\boldsymbol{P}_j^*(t)\}_{t\in\mathcal{T}}$ in the differential game problem \eqref{eq:game_problem} is
\begin{equation}
    \boldsymbol{P}_j^*(t)=\boldsymbol{Z}_j\bar{\boldsymbol{P}}_j(t)+(\boldsymbol{I}_m-\boldsymbol{Z}_j)\boldsymbol{Q}_j^*(t),
    \label{eq:decomposition1}
\end{equation}
where $\boldsymbol{Q}^*_j(t)$ is the average followees' optimal strategy with
\begin{equation}
    \boldsymbol{Q}^*_j(t):=\sum_{i\in\mathcal{N}}w_{ji}\boldsymbol{P}_i^*(t),
    \label{eq:q}
\end{equation}
$\boldsymbol{Z}_j$ is called the $j$-th agent's investment opinion with
\begin{equation}
    \boldsymbol{Z}_j:=(\boldsymbol{I}_m+\alpha_j^{-1}\eta_j^{-1}\theta_j\boldsymbol{\varSigma}^{-1})^{-1},
    \label{eq:opinion}
\end{equation}
and $\eta_j$ is the integral constant with
\begin{align}
     \eta_j&:=\exp\left[-\alpha_jx_j\mathrm{e}^{rT}-\alpha_j\int_0^T\mathrm{e}^{r(T-t)}\boldsymbol{\nu}^\top\boldsymbol{P}_j^*(t)\dif t\right.\notag\\
     &\left.+\frac{\alpha_j^2}{2}\int_0^T\mathrm{e}^{2r(T-t)}\boldsymbol{P}_j^{*\top}(t)\boldsymbol{\varSigma}\boldsymbol{P}_j^*(t)\dif t\right].
     \label{eq:integral}
\end{align}
\end{theorem}

