Following our prior work in \cite{wang2024herd}, we call the weight matrix $\boldsymbol{Z}_j$ the $j$-th agent's investment opinion, which quantifies the $j$-th agent's adherence to his/her rational strategy in his/her optimal strategy $\{\boldsymbol{P}_j^*(t)\}_{t\in\mathcal{T}}$. % and reflects the opinion on how good his/her own rational strategy is.

Next, we further show that the $j$-th agent's optimal strategy $\{\boldsymbol{P}_j^*(t)\}_{t\in\mathcal{T}}$ is a linear combination of all $n$ agents' rational strategies. To simplify the notation, we denote $\boldsymbol{U}:=[\boldsymbol{U}_{ji}]_{j,i\in\mathcal{N}}\in\mathbf{R}^{mn\times mn}$, $\boldsymbol{Z}:=\mathrm{diag}(\boldsymbol{Z}_j)_{j\in\mathcal{N}}\in\mathbf{R}^{mn\times mn}$,
$\boldsymbol{S}:=\boldsymbol{I}_{mn}-\boldsymbol{Z}\in\mathbf{R}^{mn\times mn}$, $\boldsymbol{P}^*(t):=[\boldsymbol{P}_j^*(t)]_{j\in\mathcal{N}}^\top\in\mathbf{R}^{mn}$, and $\bar{\boldsymbol{P}}(t):=[\bar{\boldsymbol{P}}_j(t)]_{j\in\mathcal{N}}^\top\in\mathbf{R}^{mn}$ in the concatenated form.

\begin{theorem}\label{the:2}
The $j$-th agent's optimal strategy $\{\boldsymbol{P}_j^*(t)\}_{t\in\mathcal{T}}$ in the differential game problem \eqref{eq:game_problem} is % a linear combination of all $n$ agents' rational strategies, which is 
\begin{equation}
    \boldsymbol{P}_j^*(t)=\sum_{i\in\mathcal{N}}\boldsymbol{U}_{ji}\bar{\boldsymbol{P}}_i(t),
    \label{eq:decomposition}
\end{equation}
where $\boldsymbol{U}_{ji},i\in\mathcal{N}$ are elements in the $j$-th row of the matrix
\begin{equation}
    \boldsymbol{U}=[\boldsymbol{I}_{mn}-\boldsymbol{S}(\boldsymbol{W}\otimes\boldsymbol{I}_m)]^{-1}\boldsymbol{Z},
    \label{eq:u}
\end{equation}
and satisfy
\begin{equation}
    \sum_{i\in\mathcal{N}}\boldsymbol{U}_{ji}=\boldsymbol{I}_m.
    \label{eq:sumu}
\end{equation}
Here, $\otimes$ represents the Kronecker product of two matrices.
\end{theorem}

\begin{proof}
From \eqref{eq:decomposition1}, we have
\begin{equation}
    \boldsymbol{P}^*(t)=\boldsymbol{Z}\bar{\boldsymbol{P}}(t)+\boldsymbol{S}(\boldsymbol{W}\otimes\boldsymbol{I}_m)\boldsymbol{P}^*(t).
    \label{eq:ZS_concate}
\end{equation}
Therefore, using matrix operations, we can prove that
\begin{equation}
    \boldsymbol{P}^*(t)=\boldsymbol{U}\bar{\boldsymbol{P}}(t),
    \label{eq:pu}
\end{equation}
where $\boldsymbol{U}$ is in \eqref{eq:u}. When writing \eqref{eq:pu} in the component form, we have \eqref{eq:decomposition}. Denote $\boldsymbol{I}:=\boldsymbol{1}_n\otimes\boldsymbol{I}_m\in\mathbf{R}^{mn\times m}$ and $\boldsymbol{1}_n\in\mathbf{R}^n$ as the all-one vector, and we can prove that
\begin{align}
    &[\boldsymbol{I}_{mn}-\boldsymbol{S}(\boldsymbol{W}\otimes\boldsymbol{I}_m)]\boldsymbol{I}=\boldsymbol{I}-\boldsymbol{S}(\boldsymbol{W}\otimes\boldsymbol{I}_m)(\boldsymbol{1}_n\otimes\boldsymbol{I}_m)\notag\\
    =\ &\boldsymbol{I}-\boldsymbol{S}(\boldsymbol{W}\boldsymbol{1}_n)\otimes(\boldsymbol{I}_m\boldsymbol{I}_m)=\boldsymbol{I}-\boldsymbol{S}(\boldsymbol{1}_n\otimes\boldsymbol{I}_m)\notag\\
    =\ &(\boldsymbol{I}_{mn}-\boldsymbol{S})\boldsymbol{I}=\boldsymbol{Z}\boldsymbol{I},
    \label{eq:ZI}
\end{align}
where we use the property of the row-stochastic adjacency matrix $\boldsymbol{W}\boldsymbol{1}_n=\boldsymbol{1}_n$, and the property of the Kronecker product $(\boldsymbol{A}\otimes\boldsymbol{B})(\boldsymbol{C}\otimes\boldsymbol{D})=(\boldsymbol{A}\boldsymbol{C})\otimes(\boldsymbol{B}\boldsymbol{D})$ when the dimensions of $\boldsymbol{A}$, $\boldsymbol{B}$, $\boldsymbol{C}$, and $\boldsymbol{D}$ are compatible for multiplication. Therefore, from \eqref{eq:u} and \eqref{eq:ZI}, we have
\begin{align}
    \boldsymbol{U}\boldsymbol{I}=[\boldsymbol{I}_{mn}-\boldsymbol{S}(\boldsymbol{W}\otimes\boldsymbol{I}_m)]^{-1}\boldsymbol{Z}\boldsymbol{I}=\boldsymbol{I}.
    \label{eq:ui=i}
\end{align}
When writing \eqref{eq:ui=i} in the component form, we have \eqref{eq:sumu}.
\end{proof}

\subsection{The Proposed Fast Algorithm}
From Theorem \ref{the:1} and Theorem \ref{the:2}, we can obtain the analytical solutions for agents' optimal strategies. However, this method has high computational complexity. Especially, in \eqref{eq:integral}, we must compute the integral $\{\eta_j\}_{j\in\mathcal{N}}$ involving vectors. In Python, we can use \texttt{scipy.integrate.quad} to compute $\{\eta_j\}_{j\in\mathcal{N}}$ with a small error tolerance of $1.49\times10^{-8}$, which is very close to the exact value. Since \texttt{scipy.integrate.quad} uses adaptive quadrature techniques, it evaluates the integrand at numerous sample points and sums the results, which makes computing the integral with such high accuracy computationally expensive. To address this problem, we propose a fast algorithm to approximate $\{\eta_j\}_{j\in\mathcal{N}}$, as shown in Algorithm \ref{alg:1}.

In the fast algorithm, we utilize the right rectangle method in \cite{davis2007methods} and approximate $\eta_j$ with
\begin{equation}
     \hat{\eta}_j=\zeta_j\exp\left[-\alpha_jT\boldsymbol{\nu}^\top\boldsymbol{P}_j^*(T)+\frac{\alpha_j^2T}{2}\boldsymbol{P}_j^{*\top}(T)\boldsymbol{\varSigma}\boldsymbol{P}_j^*(T)\right],
     \label{eq:hatintegral}
\end{equation}
where $\zeta_j:=\exp(-\alpha_jx_j\mathrm{e}^{rT})$. In \eqref{eq:hatintegral}, we only need to perform simple matrix operations, which reduces the computational complexity. % As $\delta u$ increases, the computational complexity of \eqref{eq:hatintegral} decreases, and when $\delta u$ is not very large, the error in \eqref{eq:hatintegral} is not significant, which will be validated using numerical experiments in Section \ref{sec:experiment}. Equation \eqref{eq:hatintegral} significantly reduces the computational complexity when compared with \eqref{eq:u}. 
Compared to \texttt{scipy.integrate.quad}, the fast algorithm has a larger error when computing $\{\eta_j\}_{j\in\mathcal{N}}$, while the overall error when calculating agents' optimal strategies $\{\boldsymbol{P}_j^*(t)\}_{t\in\mathcal{T}}$ remains small, which will be validated in Section \ref{sec:experiment}.

