\begin{algorithm}[t]\label{alg:1}
\small
	\caption{The Fast Algorithm.}
	\KwData{Interest rate $r$, excess return rate $\boldsymbol{\nu}$, volatility $\boldsymbol{\sigma}$, investment period $T$, adjacency matrix $\boldsymbol{W}$, risk aversion coefficients $\{\alpha_j\}_{j\in\mathcal{N}}$, influence coefficients $\{\theta_j\}_{j\in\mathcal{N}}$, initial wealth $\{x_j\}_{j\in\mathcal{N}}$, error tolerance $\varepsilon$.}
