	\BlankLine
	$k=0,\delta\eta^{(0)}=+\infty,\eta_j^{(0)}=\exp(-\alpha_jx_j\mathrm{e}^{rT}-\frac{1}{2}\kappa T), j\in\mathcal{N}$;

