  Calculate $\boldsymbol{Z}_j^{(k)},j\in\mathcal{N}$ using \eqref{eq:opinion};

  Calculate $\boldsymbol{U}_{ji}^{(k)},j,i\in\mathcal{N}$ using \eqref{eq:u};

  Calculate $\{\boldsymbol{P}_j^{(k)}(t)\}_{t\in\mathcal{T}},j\in\mathcal{N}$ using \eqref{eq:decomposition};

  Calculate $\eta_j^{(k+1)},j\in\mathcal{N}$ using \eqref{eq:hatintegral};

  $\delta\eta^{(k+1)}=\max_{j\in\mathcal{N}}|\eta_j^{(k+1)}-\eta_j^{(k)}|$;}

  $\boldsymbol{P}_j^*(t)\approx\boldsymbol{P}_j^{(k)}(t),t\in\mathcal{T},j\in\mathcal{N}$.
\end{algorithm}

