\subsection{The Optimal Strategies}
To analyze the impact of mutual influence on agents' optimal strategies, we first derive the asymptotic strategy as the influence coefficients $\{\theta_j\}_{j\in\mathcal{N}}$ approach infinity, and then show that agents' optimal strategies are linear combinations of their rational strategies and the asymptotic strategy.

\subsubsection{The Asymptotic Strategy}
First, we can show that, as the influence coefficients $\{\theta_j\}_{j\in\mathcal{N}}$ approach infinity, the optimal strategies of all $n$ agents converge to the same function, which we call the \textit{asymptotic strategy}. Thus, analyzing the impact of the mutual influence on the $j$-th agent's optimal strategy is equivalent to comparing his/her rational strategy $\{\bar{\boldsymbol{P}}_j(t)\}_{t\in\mathcal{T}}$ and the asymptotic strategy $\{\tilde{\boldsymbol{P}}(t)\}_{t\in\mathcal{T}}$.

\begin{theorem}\label{the:3}
As the influence coefficients $\{\theta_j\}_{j\in\mathcal{N}}$ approach infinity, all $n$ agents' optimal strategies converge to % the asymptotic strategy, which is
% \begin{equation}
%     \tilde{\boldsymbol{P}}(t)=\frac{\sum_{j\in\mathcal{N}}\eta_j\alpha_j\bar{\boldsymbol{P}}_j(t)}{\sum_{j\in\mathcal{N}}\eta_j\alpha_j}=\frac{\sum_{j\in\mathcal{N}}\eta_j}{\sum_{j\in\mathcal{N}}\eta_j\alpha_j}\boldsymbol{\varSigma}^{-1}\boldsymbol{\nu}\mathrm{e}^{r(t-T)}.
%     \label{eq:asymptotic}
% \end{equation}
\begin{equation}
    \tilde{\boldsymbol{P}}(t)=\tilde{\alpha}^{-1}\mathrm{e}^{r(t-T)}\boldsymbol{\varSigma}^{-1}\boldsymbol{\nu},
    \label{eq:asymptotic}
\end{equation}
where $\tilde{\alpha}$ is the \textit{asymptotic risk aversion coefficient} with
\begin{equation}
    \tilde{\alpha}:=\frac{\sum_{j\in\mathcal{N}}\eta_j\alpha_j}{\sum_{j\in\mathcal{N}}\eta_j}.
    \label{eq:asy_alpha}
\end{equation}
\end{theorem}

\begin{proof}
First, we prove that when $\{\theta_j\}_{j\in\mathcal{N}}$ approaches infinity, all $n$ agents' optimal strategies converge to the same function. We prove it by contradiction. Assume there exist $j',j''\in\mathcal{N}$ and $t\in\mathcal{T}$ such that $\boldsymbol{P}_{j'}^*(t)\ne\boldsymbol{P}_{j''}^*(t)$, and we can find at least one agent, e.g., the $j$-th agent, whose average deviation $D(\boldsymbol{P}_j^*,\boldsymbol{Q}_j^*)$ is strictly positive. When $\theta_j$ approaches infinity, the $j$-th agent's objective functional $\mathbb{E}\phi_j[X_j(T)]-\theta_jD(\boldsymbol{P}_j^*,\boldsymbol{Q}_j^*)$ approaches negative infinity, which does not reach its supremum. Therefore, all $n$ agents' optimal strategies must converge to the same function, and we define it as the asymptotic strategy $\{\tilde{\boldsymbol{P}}(t)\}_{t\in\mathcal{T}}$.

Next, we derive the expression of the asymptotic strategy. % From \eqref{eq:opinion}, we have
% \begin{equation}
%     \lim_{\theta_j\to+\infty}\boldsymbol{Z}_j=\boldsymbol{O}_m,
% \end{equation}
% and thus
% \begin{equation}
%     \lim_{\theta_j\to+\infty}\boldsymbol{S}_j=\boldsymbol{I}_m-\lim_{\theta_j\to0}\boldsymbol{Z}_j=\boldsymbol{I}_m.
% \end{equation}
% In the concatenated form, we have
% \begin{equation}
%     \lim_{\theta_j\to+\infty,j\in\mathcal{N}}\boldsymbol{S}=\boldsymbol{I}_{mn}.
%     \label{eq:s_infty}
% \end{equation}
Substituting \eqref{eq:opinion} into \eqref{eq:u}, using the L'Hôpital's rule, we have
\begin{equation}
    \lim_{\{\theta_j\}_{j\in\mathcal{N}}\to\infty}\boldsymbol{U}=\mathrm{diag}\left(\frac{\eta_i\alpha_i}{\sum_{j\in\mathcal{N}}\eta_j\alpha_j}\right)_{i\in\mathcal{N}}\otimes\boldsymbol{I}_m.
    \label{eq:tildeu}
\end{equation}
Therefore, substituting \eqref{eq:tildeu} into \eqref{eq:pu}, we can prove that
\begin{equation}
    \tilde{\boldsymbol{P}}(t)=\frac{\sum_{j\in\mathcal{N}}\eta_j}{\sum_{j\in\mathcal{N}}\eta_j\alpha_j}\mathrm{e}^{r(t-T)}\boldsymbol{\varSigma}^{-1}\boldsymbol{\nu},
\end{equation}
which is \eqref{eq:asymptotic} given the definition of $\tilde{\alpha}$ in \eqref{eq:asy_alpha}.
\end{proof}

From Theorem \ref{the:3}, to compare the $j$-th agent's rational strategy $\{\bar{\boldsymbol{P}}_j(t)\}_{t\in\mathcal{T}}$ and the asymptotic strategy $\{\tilde{\boldsymbol{P}}(t)\}_{t\in\mathcal{T}}$, we only need to compare the $j$-th agent's risk aversion coefficient $\alpha_j$ and the asymptotic risk aversion coefficient $\tilde{\alpha}$. From \eqref{eq:asy_alpha}, the asymptotic risk aversion coefficient $\tilde{\alpha}$ represents the average level of risk aversion among all agents. We define the \textit{social average agent} as a representative agent whose behavior reflects the average characteristics of a group of agents, and whose risk aversion coefficient is $\tilde{\alpha}$ in \eqref{eq:asy_alpha}. Therefore, when the influence coefficients $\{\theta_j\}_{j\in\mathcal{N}}$ approaches infinity, all $n$ agents eventually converge to the social average agent, sharing the same level of risk aversion.

If $\alpha_j<\tilde{\alpha}$, the absolute value of $\{\tilde{\boldsymbol{P}}(t)\}_{t\in\mathcal{T}}$ is smaller than that of $\{\bar{\boldsymbol{P}}_j(t)\}_{t\in\mathcal{T}}$. It indicates that if the $j$-th agent is more risk-taking than the social average agent, he/she will become more risk-averse under mutual influence. Conversely, if $\alpha_j>\tilde{\alpha}$, the absolute value of $\{\tilde{\boldsymbol{P}}(t)\}_{t\in\mathcal{T}}$ is larger than that of $\{\bar{\boldsymbol{P}}_j(t)\}_{t\in\mathcal{T}}$. It indicates that if the $j$-th agent is more risk-averse than the social average agent, he/she will become more risk-taking under mutual influence. % In summary, mutual influence causes agents' levels of risk aversion to become closer.
% That is, the asymptotic strategy of all $n$ agents, considering the mutual influence, is equivalent to each of the $n$ agents with the asymptotic risk aversion coefficient making strategies independently. Therefore, by comparing the $j$-th agents' risk aversion coefficient $\alpha_j$ with the asymptotic risk aversion coefficient $\tilde{\alpha}$, we can analyze the impact of mutual influence on his/her optimal strategies. 

% If the $j$-th agent's risk aversion coefficient is smaller than the asymptotic risk aversion coefficient, i.e., $\alpha_j<\tilde{\alpha}$, then the absolute value of the asymptotic strategy $\{\tilde{\boldsymbol{P}}(t)\}_{t\in\mathcal{T}}$ is smaller than that of the $j$-th agent's rational strategy $\{\bar{\boldsymbol{P}}_j(t)\}_{t\in\mathcal{T}}$. It indicates the $j$-th agent becomes more risk-averse under the impact of the mutual influence. Conversely, if $\alpha_j>\tilde{\alpha}$, then the absolute value of the asymptotic strategy $\{\tilde{\boldsymbol{P}}(t)\}_{t\in\mathcal{T}}$ is larger than that of the $j$-th agent's rational strategy $\{\bar{\boldsymbol{P}}_j(t)\}_{t\in\mathcal{T}}$, which indicates the $j$-th agent becomes more risk-taking under the impact of the mutual influence. 

\subsubsection{The Relationship Among Optimal Strategy, Rational Strategy, and Asymptotic Strategy}
With Theorem \ref{the:3}, we can further prove that the $j$-th agent's optimal strategy $\{\boldsymbol{P}_j^*(t)\}_{t\in\mathcal{T}}$ is a linear combination of his/her rational strategy $\{\bar{\boldsymbol{P}}_j(t)\}_{t\in\mathcal{T}}$ and the asymptotic strategy $\{\tilde{\boldsymbol{P}}(t)\}_{t\in\mathcal{T}}$. % Therefore, the $j$-th agent's influence coefficient $\theta_j$, by influencing the weight matrix $\boldsymbol{V}_j$, affects the value of $\{\boldsymbol{P}_j^*(t)\}_{t\in\mathcal{T}}$ between $\{\bar{\boldsymbol{P}}_j(t)\}_{t\in\mathcal{T}}$ and $\{\tilde{\boldsymbol{P}}(t)\}_{t\in\mathcal{T}}$.

\begin{theorem}\label{the:5}
The $j$-th agent's optimal strategy $\{\boldsymbol{P}_j^*(t)\}_{t\in\mathcal{T}}$ in the differential game problem \eqref{eq:game_problem} is % a linear combination of all $n$ agents' rational strategies, which is 
\begin{equation}
    \boldsymbol{P}_j^*(t)=\boldsymbol{V}_j\bar{\boldsymbol{P}}_j(t)+(\boldsymbol{I}_m-\boldsymbol{V}_j)\tilde{\boldsymbol{P}}(t),
    \label{eq:decomposition2}
\end{equation}
where the weight matrix is
\begin{equation}
    \boldsymbol{V}_j:=(\alpha_j^{-1}-\tilde{\alpha}^{-1})^{-1}\left(\sum_{i\in\mathcal{N}}\alpha_i^{-1}\boldsymbol{U}_{ji}-\tilde{\alpha}^{-1}\boldsymbol{I}_m\right).
    \label{eq:v}
\end{equation}
\end{theorem}

\begin{proof}
Combining \eqref{eq:rational}, \eqref{eq:decomposition}, and \eqref{eq:asymptotic}, we can obtain \eqref{eq:decomposition2} and \eqref{eq:v}, and we omit the details here.
\end{proof}

Theorem \ref{the:5} shows the relationship among the $j$-th agent's optimal strategy $\{\boldsymbol{P}_j^*(t)\}_{t\in\mathcal{T}}$, rational strategy $\{\bar{\boldsymbol{P}}_j(t)\}_{t\in\mathcal{T}}$, and the asymptotic strategy $\{\tilde{\boldsymbol{P}}(t)\}_{t\in\mathcal{T}}$. When $\theta_j=0$, we have the weight matrix $\boldsymbol{V}_j=\boldsymbol{I}_m$, which indicates that $\{\boldsymbol{P}_j^*(t)\}_{t\in\mathcal{T}}=\{\bar{\boldsymbol{P}}_j(t)\}_{t\in\mathcal{T}}$, i.e., the $j$-th agent makes rational strategies without others influence. As $\theta_j$ approaches infinity, we have the weight matrix $\boldsymbol{V}_j=\boldsymbol{O}_m$, which indicates that $\{\boldsymbol{P}_j^*(t)\}_{t\in\mathcal{T}}=\{\tilde{\boldsymbol{P}}(t)\}_{t\in\mathcal{T}}$, i.e., the $j$-th agent's optimal strategy converges to the asymptotic strategy under mutual influence among agents. As $\theta_j$ increases from $0$ to infinity, the weight matrix $\boldsymbol{V}_j$ transitions from $\boldsymbol{I}_m$ to $\boldsymbol{O}_m$, signifying that as the mutual influence becomes strong, the $j$-th agent's optimal strategy gradually shifts from his/her rational strategy to the asymptotic strategy. However, due to the complex form of \eqref{eq:v}, it is challenging to derive the quantitative relationship between $\theta_j$ and $\{\boldsymbol{P}_j^*(t)\}_{t\in\mathcal{T}}$, and we will use numerical experiments to study the impact of $\theta_j$ on $\{\boldsymbol{P}_j^*(t)\}_{t\in\mathcal{T}}$ in Section \ref{sec:experiment}.

% \subsubsection{Summary of the Expressions of The Optimal Strategy}
% So far, we have obtained three expressions for agents' optimal strategies in Theorem \ref{the:1}, Theorem \ref{the:2}, and Theorem \ref{the:5}. All three expressions decompose the optimal strategy into linear combinations of the agent's rational strategy and some other strategies or strategies. In Theorem \ref{the:1}, the $j$-th agent's optimal strategy $\{\boldsymbol{P}_j^*(t)\}_{t\in\mathcal{T}}$ can be decomposed into his/her rational strategy $\{\bar{\boldsymbol{P}}_j(t)\}_{t\in\mathcal{T}}$ and the average followees' optimal strategy $\{\boldsymbol{Q}_j^*(t)\}_{t\in\mathcal{T}}$, with the weight coefficients being the matrix $\boldsymbol{Z}_j$. In Theorem \ref{the:2}, the $j$-th agent's optimal strategy $\{\boldsymbol{P}_j^*(t)\}_{t\in\mathcal{T}}$ can be decomposed into his/her rational strategy $\{\bar{\boldsymbol{P}}_j(t)\}_{t\in\mathcal{T}}$ and others' rational strategies $\{\bar{\boldsymbol{P}}_i(t)\}_{t\in\mathcal{T}}$ for all $\mathcal{N}\ni i\ne j$, with the weight coefficient being the matrices $\boldsymbol{U}_{ji}$ for all $i\in\mathcal{N}$. In Theorem \ref{the:5}, the $j$-th agent's optimal strategy $\{\boldsymbol{P}_j^*(t)\}_{t\in\mathcal{T}}$ can be decomposed into his/her rational strategy $\{\bar{\boldsymbol{P}}_j(t)\}_{t\in\mathcal{T}}$ and the asymptotic strategy $\{\tilde{\boldsymbol{P}}_j(t)\}_{t\in\mathcal{T}}$, with the weight coefficient being the matrix $\boldsymbol{V}$. Although the specific forms of these three decompositions differ, they are equivalent, reflecting the relationship between the agents' optimal strategies and other strategies or strategies. 

\subsection{The Terminal Wealth}
Next, we analyze the impact of the mutual influence on agents' terminal wealth. We compare agents' terminal wealth when the influence coefficients $\{\theta_j\}_{j\in\mathcal{N}}$ are zero to the case when $\{\theta_j\}_{j\in\mathcal{N}}$ approach infinity. We will study the general cases with arbitrary $\{\theta_j\}_{j\in\mathcal{N}}$ using numerical experiments in Section \ref{sec:experiment}. When the influence coefficients $\{\theta_j\}_{j\in\mathcal{N}}$ are equal to zero and agents make independent strategies without mutual influence, we call the $j$-th agent's terminal wealth $\bar{X}_j(T)$ the \textit{rational terminal wealth}. As the influence coefficients $\{\theta_j\}_{j\in\mathcal{N}}$ approaches infinity, we call the $j$-th agent's terminal wealth $\tilde{X}_j(T)$ the \textit{asymptotic terminal wealth}. In Theorem \ref{the:4}, we derive the means and variances of the rational terminal wealth $\bar{X}_j(T)$ and asymptotic terminal wealth $\tilde{X}_j(T)$, respectively.
% We can show that the rational terminal wealth $\bar{X}_j(T)$ and asymptotic terminal wealth $\tilde{X}_j(T)$ satisfy normal distributions. 

\begin{theorem}\label{the:4}
The means and variances of the $j$-th agent's rational terminal wealth $\bar{X}_j(T)$ and asymptotic terminal wealth $\tilde{X}_j(T)$ are
\begin{align}
    \mathbb{E}\bar{X}_j(T)=x_j\mathrm{e}^{rT}+\alpha_j^{-1}\kappa T\quad \text{and}\quad \ \mathbb{D}\bar{X}_j(T)=\alpha_j^{-2}\kappa T,\label{eq:ed1}\\
    \mathbb{E}\tilde{X}_j(T)=x_j\mathrm{e}^{rT}+\tilde{\alpha}^{-1}\kappa T\quad \text{and}\quad \mathbb{D}\tilde{X}_j(T)=\tilde{\alpha}^{-2}\kappa T.\label{eq:ed2}
\end{align}
\end{theorem}

\begin{proof}
% From \eqref{eq:wealth}, the $j$-th agent's terminal wealth is
% \begin{equation}
%     X_j(T)=x_j\mathrm{e}^{rT}+\int_0^T\mathrm{e}^{r(T-t)}\boldsymbol{P}_j^\top(t)[\boldsymbol{\nu}\dif t+\boldsymbol{\sigma}\dif\boldsymbol{B}(t)],
% \end{equation}
Following our prior work in \cite{wang2024herd}, the mean and variance of the $j$-th agent's terminal wealth are
\begin{align}
    \mathbb{E}X_j(T)&=x_j\mathrm{e}^{rT}+\int_0^T\mathrm{e}^{r(T-t)}\boldsymbol{P}_j^\top(t)\boldsymbol{\nu}\dif t\quad \text{and}\label{eq:ex}\\
    \mathbb{D}X_j(T)&=\int_0^T\mathrm{e}^{2r(T-t)}\boldsymbol{P}_j^\top(t)\boldsymbol{\varSigma}\boldsymbol{P}_j(t)\dif t,\label{eq:dx}
\end{align}
respectively. Substituting \eqref{eq:rational} and \eqref{eq:asymptotic} into \eqref{eq:dx}, we can obtain \eqref{eq:ed1} and \eqref{eq:ed2}.
% can derive the mean and variance of the rational terminal wealth $\bar{X}_j(T)$ and the asymptotic terminal wealth $\tilde{X}_j(T)$.
\end{proof}

From Theorem \ref{the:4}, to compare the $j$-th agent's rational terminal wealth $\bar{X}_j(T)$ and asymptotic terminal wealth $\tilde{X}_j(T)$, we only need to compare his/her risk aversion coefficient $\alpha_j$ and the asymptotic risk aversion coefficient $\tilde{\alpha}$. %If the $j$-th agent's risk aversion coefficient is smaller than the asymptotic risk aversion coefficient, i.e., 
If $\alpha_j<\tilde{\alpha}$, the mean and variance of the asymptotic terminal wealth are smaller than those of the rational terminal wealth, i.e., $\mathbb{E}\tilde{X}_j(t)<\mathbb{E}\bar{X}_j(t)$ and $\mathbb{D}\tilde{X}_j(t)<\mathbb{D}\bar{X}_j(t)$. It indicates that if the $j$-th agent is more risk-taking than the social average agent, he/she will seek lower returns and risk under mutual influence. % and become more risk-averse under mutual influence. %, which indicates he/she becomes more risk-averse under the influence of mutual influence. 
Conversely, if $\alpha_j>\tilde{\alpha}$, then $\mathbb{E}\tilde{X}_j(t)>\mathbb{E}\bar{X}_j(t)$ and $\mathbb{D}\tilde{X}_j(t)>\mathbb{D}\bar{X}_j(t)$. It indicates that if the $j$-th agent is more risk-averse than the social average agent, he/she will seek higher returns and risk under mutual influence. % and become more risk-taking under mutual influence. %, which indicates he/she becomes more risk-taking under the influence of mutual influence. 

