\section{Omitted Proofs}

\subsection{Evaluating Data Attribution in SAM via Hessian-based IF}

\begin{theorem}\label{app:HIF-easy}
    Consider the data $(x_k, y_k)$ along with a SAM-trained model $\omega^*$, $\hat{\epsilon}(\omega^*)$ represents the model weight perturbation that results in the largest loss.
Then the corresponding SAM-IF is defined as:
\begin{align*}
    \text{SAM-IF}(x_k, y_k) &= -H_{\omega}^{-1} \cdot\nabla L_S^k(\omega^*+ \hat{\epsilon}(\omega^*))
\end{align*}
where $H_{\omega}$ is defined as $H_{\omega} = \nabla^2 L_S\left(\omega^*+\hat{\epsilon}(\omega^*)\right)+ \lambda\cdot I$. $\omega_{k}$ can be approximated by 
\begin{equation*}
    \omega_{k}  \approx  \omega^*-\text{SAM-IF}(x_k, y_k).
\end{equation*}
\end{theorem}


\begin{proof}
Recalling the definition $\hat{\epsilon}(\omega) = \argmax_{||\epsilon||_p\leq\rho} L_S(\omega+\epsilon)$ and
\begin{equation}\label{app:optimal}
    \begin{split}
        \omega^* &= \argmin_{\omega} L_S(\omega) + 
        \frac{\lambda}{2} \cdot ||\omega||^2_2\\
        &=\argmin_{\omega} L_S(\omega +  \hat{\epsilon}(\omega)) + \frac{\lambda}{2}\cdot ||\omega||^2_2\\
        &= \argmin_{\omega} \sum_{i=1}^n\ell(x_i,y_i;\omega+ \hat{\epsilon}(\omega)) + \frac{\lambda}{2}\cdot ||\omega||^2_2\\
        &= \argmin_{\omega} \sum_{i=1}^n L_S^i(\omega +  \hat{\epsilon}(\omega))  + \frac{\lambda}{2}\cdot ||\omega||^2_2
    \end{split}
\end{equation}    
Now we consider removing the $k$-th data $(x_k, y_k)$. The retrained parameter after the removal is denoted as $\omega_k$:
\begin{equation*}
    \omega_k = \argmin_{\omega} \sum_{i=1, i\neq k}^n L_S^i(\omega +  \hat{\epsilon}(\omega))  + \frac{\lambda}{2}\cdot ||\omega||^2_2
\end{equation*}
To estimate this $\omega_k$, we can firstly up-weigh the loss term $L_S^k(\omega +  \hat{\epsilon}(\omega))$ by $\delta$ in the original loss function defined in (\ref{app:optimal}), then a series of optimization problem can be defined as:
    \begin{align}\label{app:optimal_delta}
        \omega_{\delta} = \argmin_{\omega}L_S(\omega +  \hat{\epsilon}_{\delta}(\omega)) + \delta \cdot L_S^k(\omega+ \hat{\epsilon}_{\delta}(\omega)) + \frac{\lambda}{2}\cdot ||\omega||^2_2
    \end{align}
Noting here $\hat{\epsilon}_{\delta}(\omega)$ will change according to $\delta$ and is defined as
    \begin{equation*}
        \hat{\epsilon}_{\delta}(\omega) = \argmax_{||\epsilon||_p\leq\rho}  \left[ L_S(\omega+ {\epsilon})+  \delta \cdot L_S^k(\omega+ {\epsilon}) \right]
    \end{equation*}
From the minimizing condition in Equation (\ref{app:optimal}) and (\ref{app:optimal_delta}) and Lemma \ref{danskin}, we have
    \begin{equation}\label{app:optimal_condition}
        \begin{split}
\nabla L_S(\omega^*+\hat{\epsilon}(\omega^*)) = 0,\indent\nabla L_S(\omega_{\delta}+\hat{\epsilon}_{\delta}(\omega_{\delta})) +  \delta\cdot\nabla L^k_S(\omega_{\delta}+\hat{\epsilon}_{\delta}(\omega_{\delta}))= 0.
        \end{split}
    \end{equation}
To estimate $\omega_{\delta}- \omega^*$, we perform a Taylor expand at $\omega^*$ for the first equation in (\ref{app:optimal_condition}).:
    \begin{equation}\label{app:taylor_expand}
        \begin{split}
            0  &=   \nabla L_S\left(\omega^*+\hat{\epsilon}(\omega^*)\right) + \delta \cdot \nabla L^k_S\left(\omega^*+\hat{\epsilon}(\omega^*)\right) + \nabla^2 L_S\left(\omega^*+\hat{\epsilon}(\omega^*)\right)\cdot \left(\omega_{\delta} - \omega^*\right)\\
       & +\nabla^2 L_S\left(\omega^*+\hat{\epsilon}(\omega^*)\right) \cdot \left(\hat{{\epsilon}}_{\delta}\left(\omega_{\delta}\right) - \hat{\epsilon}(\omega^*)\right) 
        \end{split}
    \end{equation}
    In the above expansion, the first term equals $0$ from (\ref{app:optimal_condition}). And to make thing easier, we can neglect the last term and deduce a simple influence function for SAM.
    \begin{align*}
        \text{SAM-IF}(x_k, y_k) &= \left.\frac{\mathrm{d}\omega_{\delta}}{\mathrm{d}\delta}\right|_{\delta = 0}= -H_{\omega}^{-1} \cdot\nabla L_S^k(\omega^*+ \hat{\epsilon}(\omega^*)),
    \end{align*}
    where $H_{\omega}$ is defined as $H_{\omega} = \nabla^2 L_S\left(\omega^*+\hat{\epsilon}(\omega^*)\right)+ \lambda\cdot I$. 

When $\delta = -1$, $\omega_{\delta}$ becomes $\omega_{k}$. Then $\omega_{k}$ can be approximated by a first-order Taylor expansion:
\begin{equation*}
    \omega_{k}  \approx  \omega^*-\text{SAM-IF}(x_k, y_k).
\end{equation*}
\end{proof}



\begin{lemma}\label{lemma2}
    The term 
   $\hat{{\epsilon}}_{k, \delta}\left(\omega_{k, \delta}\right) - \hat{\epsilon}(\omega^*)$ can be approximated by
   \begin{equation}
   \begin{split}
       &\hat{\epsilon}_{k,\delta}(\omega_{k,\delta}) - \hat{\epsilon}(\omega^*)\\
       =& \hat{\epsilon}_{k, \delta}(\omega^*) - \hat{\epsilon}(\omega^*)  + \left. \frac{\mathrm{d} \hat{\epsilon}_{k, \delta}(\omega)}{\mathrm{d} \omega} \right|_{\omega = \omega^*} \cdot (\omega_{k,\delta} - \omega^*).
   \end{split}
   \end{equation}
   \end{lemma}


\begin{proof}    
Now, we begin to estimate $\hat{\epsilon}_{k,\delta}(\omega_{k,\delta}) - \hat{\epsilon}(\omega^*)$. Recalling the definitions as following:
  \begin{align*}
    \hat{{\epsilon}}_{k, \delta}\left(\omega_{k, \delta}\right)  &=\argmax_{||\epsilon||_p\leq\rho} \left[ L_{S}(\omega_{k, \delta}+ {\epsilon}) + \delta\cdot L_S^k(\omega_{k, \delta}+ {\epsilon}) \right],\\
          \hat{\epsilon}(\omega^*) &= \argmax_{||\epsilon||_p\leq\rho}.
          L_S(\omega^* + {\epsilon})
  \end{align*}
  We will use $\hat{\epsilon}_{k, \delta}(\omega^*)$ as an intermediate variable to simplify the approximation, which is defined as
  \begin{equation*}
    \hat{\epsilon}_{k, \delta}(\omega^*) = \argmin_{||\epsilon||_p\leq\rho}  \left[ L_{S}(\omega^*+ {\epsilon}) + \delta\cdot L_S^k(\omega^*+ {\epsilon}) \right]
  \end{equation*}
  Firstly, we perform a Taylor expansion for $\hat{{\epsilon}}_{k, \delta}\left(\omega_{k, \delta}\right)$ at $\omega^*$ as follows:
  \begin{equation*}
    \hat{{\epsilon}}_{k, \delta}\left(\omega_{k, \delta}\right) \approx \hat{{\epsilon}}_{k, \delta}\left(\omega^*\right)   + \left. \frac{\mathrm{d} \hat{{\epsilon}}_{k, \delta}\left(\omega_{k, \delta}\right)}{\mathrm{d} \omega} \right|_{\omega = \omega^*} \cdot(\omega_{k,\delta} - \omega^*)
  \end{equation*}
  Then the objective to estimate becomes
\begin{align*}\label{lemma2}
    &\hat{\epsilon}_{k,\delta}(\omega_{k,\delta}) - \hat{\epsilon}(\omega^*)\\
=&  \hat{\epsilon}_{k,\delta}(\omega_{k,\delta}) - \hat{\epsilon}_{k,\delta}(\omega^*) + \hat{\epsilon}_{k,\delta}(\omega^*)  - \hat{\epsilon}(\omega^*)\\
=& \hat{\epsilon}_{k,\delta}(\omega^*)  - \hat{\epsilon}(\omega^*) + \left. \frac{\mathrm{d} \hat{{\epsilon}}_{k, \delta}\left(\omega_{k, \delta}\right)}{\mathrm{d} \omega} \right|_{\omega = \omega^*} \cdot(\omega_{k,\delta} - \omega^*)
\end{align*}
\end{proof}



\begin{theorem}\label{app:HIF-complex}
Consider the $k$-th data $(x_k, y_k)$ along with a SAM-trained model $\omega^*$. Define the Hessian-based influence function for SAM(SAM-HIF) as:
\begin{align*}
    &\text{SAM-HIF}(x_k, y_k)\\
    =& -\left(H_{\omega} +H_{\omega}\cdot  \frac{\mathrm{d} \hat{\epsilon}(\omega^*)}{\mathrm{d} \omega }\right)^{-1} \cdot\nabla L^k_S\left(\omega^*+\hat{\epsilon}(\omega^*)\right).
\end{align*}
Then $ \omega_{k}$ can be approximated by:
\begin{equation*}
    \omega_{k} \approx \omega^* -\text{SAM-HIF}(x_k, y_k).
\end{equation*}
\end{theorem}

   \begin{proof}
Based on the expansion in Equation (\ref{app:taylor_expand}) in Theorem \ref{app:HIF-easy}, we can further estimate the term $\hat{{\epsilon}}_{k, \delta}\left(\omega_{k, \delta}\right) - \hat{\epsilon}(\omega^*)$ by Lemma \ref{app:epsilon_approx}:
\begin{equation}
    \begin{split}
        0  &=   \nabla L_S\left(\omega^*+\hat{\epsilon}(\omega^*)\right) + \delta \cdot \nabla L^k_S\left(\omega^*+\hat{\epsilon}(\omega^*)\right) + \nabla^2 L_S\left(\omega^*+\hat{\epsilon}(\omega^*)\right)\cdot \left(\omega_{\delta} - \omega^*\right)\\
   &+ \nabla^2 L_S\left(\omega^*+\hat{\epsilon}(\omega^*)\right)\cdot \left(\hat{\epsilon}_{\delta}(\omega^*)  - \hat{\epsilon}(\omega^*) + \left. \frac{\mathrm{d} \hat{{\epsilon}}_{\delta}\left(\omega_{\delta}\right)}{\mathrm{d} \omega} \right|_{\omega = \omega^*} \cdot(\omega_{\delta} - \omega^*) \right)
    \end{split}
\end{equation}
The first term equals $0$ from (\ref{app:optimal_condition}). Then we have
\begin{equation}
    \begin{split}
        0  &=  \delta \cdot \nabla L^k_S\left(\omega^*+\hat{\epsilon}(\omega^*)\right) + \left(H_{\omega}+ H_{\omega} \cdot\frac{\mathrm{d} \hat{{\epsilon}}_{\delta}\left(\omega_{\delta}\right)}{\mathrm{d} \omega}\right)\cdot \left(\omega_{\delta} - \omega^*\right)+ H_{\omega}\cdot \left(\hat{\epsilon}_{\delta}(\omega^*)  - \hat{\epsilon}(\omega^*) \right).
    \end{split}
\end{equation}
Then 
\begin{align*}
\omega_{\delta} - \omega^*  = &- \left(H_{\omega}+ H_{\omega} \cdot\frac{\mathrm{d} \hat{{\epsilon}}_{\delta}\left(\omega_{\delta}\right)}{\mathrm{d} \omega}\right)^{-1}\cdot H_{\omega}\cdot \left(\hat{\epsilon}_{\delta}(\omega^*)  - \hat{\epsilon}(\omega^*) \right)  \\
&- \delta \cdot \left(H_{\omega}+ H_{\omega} \cdot\frac{\mathrm{d}  \hat{{\epsilon}}_{\delta}\left(\omega_{\delta}\right)}{\mathrm{d} \omega}\right)^{-1}\cdot \nabla L^k_S\left(\omega^*+\hat{\epsilon}(\omega^*)\right).
\end{align*}
Then we can obtain the following equation:
\begin{align*}
    \left.\frac{\mathrm{d} \omega_{\delta}}{\mathrm{d}\delta}\right|_{\delta = 0}
      = & - \left(H_{\omega}+ H_{\omega} \cdot\frac{\mathrm{d} \hat{{\epsilon}}\left(\omega^*\right)}{\mathrm{d} \omega}\right)^{-1}\cdot H_{\omega}\cdot 
        \left.\frac{\mathrm{d}  \hat{\epsilon}_{\delta}(\omega^*)}{\mathrm{d}\delta}\right|_{\delta = 0} \\
        &-  \left(H_{\omega}+ H_{\omega} \cdot\frac{\mathrm{d} \hat{{\epsilon}}\left(\omega^*\right)}{\mathrm{d} \omega}\right)^{-1}\cdot \nabla L^k_S\left(\omega^*+\hat{\epsilon}(\omega^*)\right).
\end{align*}


To enhance the computation efficiency, we drop the first term, and obtain the SAM-HIF as
\begin{equation}
    \begin{split}
      \text{SAM-IF}=&  \left.\frac{\mathrm{d} \omega_{\delta}}{\mathrm{d}\delta}\right|_{\delta = 0}
      =-  \left(H_{\omega}+ H_{\omega} \cdot\frac{\mathrm{d} \hat{{\epsilon}}\left(\omega^*\right)}{\mathrm{d} \omega}\right)^{-1}\cdot \nabla L^k_S\left(\omega^*+\hat{\epsilon}(\omega^*)\right).
    \end{split}
\end{equation}
\end{proof}



\subsection{Computation Acceleration}
\begin{theorem}\label{app:IS}
    Given a validation dataset defined as $D_{val} = \{(x_t,y_t)\}_{t=1}^n$.
    Denote the SAM-retrained model after the removal of $(x_k,y_k)$ as $\omega^*_{-k}$, then 
    \begin{equation*}
    \begin{split}
           &\sum_{(x,y)\in D_{val}}\ell(x,y;\omega^*) - \sum_{(x,y)\in D_{val}}\ell(x,y;\omega^*_{-k}) \\
           \approx &\sum_{(x,y)\in D_{val}} \nabla \ell(x,y;\omega^*) \cdot \text{IF}(x,y)\triangleq \text{IS}(x,y), 
    \end{split}
    \end{equation*}
    where IF can be  SAM-HIF or SAM-GIF. We define the right hand of the above equation as the Influence Score (IS). 
    \end{theorem}

\begin{proof}

\begin{equation*}
    \begin{split}
&\sum_{(x,y)\in D_{val}}\ell(x,y;\omega^*) - \sum_{(x,y)\in D_{val}}\ell(x,y;\omega^*_{-k}) \\
\approx &\sum_{(x,y)\in D_{val}} \nabla \ell(x,y;\omega^*) \cdot \left(\omega^* - \omega^*_{-k}\right)\\
=&\sum_{(x,y)\in D_{val}} \nabla \ell(x,y;\omega^*) \cdot \text{IF}(x,y)\triangleq \text{IS}(x,y).
    \end{split}
    \end{equation*}

\end{proof}


\section{Omitted Algorithms}

\begin{algorithm}
\caption{SAM-IF with gradient trajectory\label{alg:3}}
\begin{algorithmic}[1]
    \STATE {\bf Input:} \\
    {\bf data:} 
    Training Dataset $S = \{(x_i, y_i\}_{i=1}^n$, data point $({x}_k, {y}_k)$ to be evaluated.\\
    {\bf Parameter: } Parameter checkpoint set $\Omega = \{\omega_c\}_{c=1}^s$, learning rate $\eta_c$ at step $c$. \\
%     {\bf Definition: }
%     \begin{align}
%     \hat{\epsilon}(\omega) & = \rho \cdot \text{sign}(\nabla_w  L_{S}(\omega, {0}) )\cdot\frac{|\nabla_w  L_{S}(\omega, {0})  |^{q-1}}{\left( \|\nabla_w  L_{S}(\omega, {0}) \|_q^q \right)^{1/p}}
% \end{align}
    % {\bf Hyper parameter ρ\rho}, which is the norm constraints of the perturbation
\STATE Compute the influence of $(x_k, y_k)$ in the $c$-th checkpoint as 
\begin{equation*}
    \text{IF}_c = \eta_c \cdot \nabla L_S^k(\omega_{c-1} + \hat{\epsilon}(\omega_{c-1}))
\end{equation*}
\STATE Sum up to obtain the final influence as
\begin{equation*}
    \text{SAM-IF}_{\text{Step}} = \sum_{c=1}^s\text{IF}_c
\end{equation*}
\STATE {\bf Return: }$\text{SAM-IF}_{\text{Step}}$. Final Parameter $\omega^- = \omega^* - \text{SAM-IF}$.
\end{algorithmic}
\end{algorithm}

\begin{algorithm}
\caption{Simple SAM-IF\label{alg:simple}}
\begin{algorithmic}[1]
    \STATE {\bf Input:} \\
    {\bf Data:} 
    Training Dataset $S = \{(x_i, y_i\}_{i=1}^n$, data point $({x}_k, {y}_k)$ to be evaluated.\\
    {\bf Parameter: } 
    The learned SAM-parameter $\omega^*$, the learned best perturbation $\hat{\epsilon}$.
 \STATE Compute $T^k$ as:
 \begin{equation*}
     T^k = \nabla L^k_S\left(\omega^*+ \hat{\epsilon}\right)
 \end{equation*}
 \STATE Define the Hessian matrix $H$ as:
 \begin{equation*}
    \nabla^2 L_S\left(\omega^*+\hat{\epsilon}\right)
 \end{equation*}
\STATE Use EK-FAC to compute the Hessian-vector product of $H$ and $T^k$:
\begin{equation*}
    \text{SAM-IF} = -H^{-1}\cdot T^k
\end{equation*}
\STATE Obtain the estimated parameter by $$\omega^- = \omega^* -\text{SAM-IF}.$$
\STATE {\bf Return: }$\text{SAM-IF}$, $\omega^-$.
\end{algorithmic}
\end{algorithm}



\begin{algorithm}
\caption{SAM-IF with total Hessian\label{alg:complete}}
\begin{algorithmic}[1]
    \STATE {\bf Input:} \\
    {\bf Data:} 
    Training Dataset $S = \{(x_i, y_i\}_{i=1}^n$, data point $({x}_k, {y}_k)$ to be evaluated.\\
    {\bf Parameter: } 
    The learned SAM-parameter $\omega^*$, the learned best perturbation $\hat{\epsilon}$.
 \STATE Compute $T^k$ as:
 \begin{equation*}
     T^k = \nabla L^k_S\left(\omega^* + \hat{\epsilon}\right)
 \end{equation*}
 \STATE Define the gradient of $\epsilon$ as
 $$C^{\epsilon} = \nabla_{\omega}\frac{|\nabla_w  L_{S}(\omega^*)  |^{q-1}}{\left( \|\nabla_w  L_{S}(\omega^*) \|_q^q \right)^{1/p}}$$
 \STATE Give the definition of $H$ as
\begin{align*}
 H =&    \nabla^2 L_S\left(\omega^*+\hat{\epsilon}\right) + \nabla^2 L_S\left(\omega^*+ \hat{\epsilon}\right) \cdot  C^{\epsilon}.
\end{align*}
 \STATE $j\xleftarrow{}1$\\
 $T^k\xleftarrow{}I_0$
\IF{$\|I_j - I_{j-1}\|_1 > \zeta$}
\STATE Use EK-FAC to compute the Hessian-vector product $S_j\triangleq H\cdot  I_j$.
\STATE Compute $I_{j+1}$ by
\begin{equation*}
I_{j+1}= I_{j} -  \delta\cdot I_{j} + S_j +  T^k
\end{equation*}
\STATE $j\xleftarrow{}j+1$
\ENDIF
\STATE $\text{SAM-IF} \leftarrow I_{j+1}$.
\STATE Obtain the estimated parameter by $\omega^- = \omega^* -\text{SAM-IF}.$
\STATE {\bf Return: }$\text{SAM-IF}$. $\omega^-$.
\end{algorithmic}
\end{algorithm}


