	\label{fig:feedbackcycle:D}
  \end{minipage}
  \qquad
  \begin{minipage}[t]{0.5 \linewidth}
	\centering
    \includegraphics[page=6]{torusRELV1}
	\subcaption{The left-first and right-first cycles $C_\ell$ and $C_r$ have $\hati (C_\ell,C_r)\neq 0$;
