\section{Appendix}
\subsection{Derivation of Optimal Allocation Strategy}

We begin with our bankruptcy risk function:
\begin{equation}
P(B(t)) = \Phi(\beta_1 DTI(t) + \beta_2 SER(t) + \beta_3\sigma_I(t) + \beta_4\sigma_M(t))
\end{equation}

Our objective is to minimize this bankruptcy probability while maintaining utility maximization. This leads to a constrained optimization problem:

\begin{equation}
\min_{D(t),S(t),E(t)} P(B(t))
\end{equation}

subject to:
\begin{align}
D(t) + S(t) + E(t) &= I(t) \text{ (Budget constraint)} \\
U(D(t),S(t),E(t)) &\geq U_{min} \text{ (Utility requirement)}
\end{align}

\subsubsection{Step 1: Express DTI and SER}
First, we express the debt-to-income and savings-to-expense ratios:
\begin{align}
DTI(t) &= \frac{D(t)}{I(t)} \\
SER(t) &= \frac{S(t)}{E(t)}
\end{align}

\subsubsection{Step 2: Incorporate Uncertainty}
Given our stochastic processes for income and savings:
\begin{align}
I(t) &= I_0(1 + \mu t + \sigma_I W(t)) \\
\frac{dS(t)}{S(t)} &= r dt + \sigma_M dZ(t)
\end{align}

The expected values of DTI and SER become:
\begin{align}
\mathbb{E}[DTI(t)] &= \frac{D(t)}{I_0(1 + \mu t)} + \text{volatility terms} \\
\mathbb{E}[SER(t)] &= \frac{S(t)}{E(t)}(1 + rt) + \text{volatility terms}
\end{align}

\subsubsection{Step 3: Risk-Adjusted Optimization}
We combine the bankruptcy probability minimization with utility maximization:
\begin{equation}
\mathcal{L} = \Phi(\beta_1 DTI(t) + \beta_2 SER(t) + \beta_3\sigma_I(t) + \beta_4\sigma_M(t)) - \lambda[U(D,S,E) - U_{min}]
\end{equation}

\subsubsection{Step 4: First-Order Conditions}
Taking derivatives with respect to D, S, and E:
\begin{align}
\frac{\partial \mathcal{L}}{\partial D} &= \phi(\cdot)\beta_1\frac{1}{I(t)} - \lambda\frac{\partial U}{\partial D} = 0 \\
\frac{\partial \mathcal{L}}{\partial S} &= \phi(\cdot)\beta_2\frac{1}{E(t)} - \lambda\frac{\partial U}{\partial S} = 0 \\
\frac{\partial \mathcal{L}}{\partial E} &= -\phi(\cdot)\beta_2\frac{S(t)}{E(t)^2} - \lambda\frac{\partial U}{\partial E} = 0
\end{align}

where $\phi(\cdot)$ is the standard normal PDF.

\subsubsection{Step 5: Risk Adjustment Terms}
Solving these equations and using the fact that in the absence of uncertainty, the 1/3 rule is optimal, we get:
\begin{align}
\alpha_D(\sigma_I) &= \frac{\beta_3\sigma_I^2}{2\beta_1} \\
\alpha_S(\sigma_I,\sigma_M) &= \frac{\beta_3\sigma_I^2}{2\beta_2} + \frac{\beta_4\sigma_M^2}{2\beta_2} \\
\alpha_E(\sigma_I) &= \frac{\beta_3\sigma_I^2}{2\beta_1}
\end{align}

\subsubsection{Step 5a: Verification of Adjustment Terms}
These adjustment terms have several important properties:
\begin{enumerate}
    \item Zero-sum property:
\begin{equation}
-\alpha_D(\sigma_I) + \alpha_S(\sigma_I,\sigma_M) - \alpha_E(\sigma_I) = 0
\end{equation}
This ensures the budget constraint continues to hold.

\item Quadratic dependence on volatility:
The adjustments are proportional to squared volatilities ($\sigma_I^2$ and $\sigma_M^2$), reflecting that risk adjustments should be symmetric for both positive and negative volatility.

\item Relative scaling:
The terms are scaled by the sensitivity parameters ($\beta_1$, $\beta_2$, $\beta_3$, $\beta_4$) from the original bankruptcy risk function, ensuring consistency with our risk model.
\end{enumerate}
\subsubsection{Step 5b: Transition to Optimal Allocation}
Starting with the basic 1/3 rule allocation:
\begin{align}
D(t) &= \frac{1}{3}I(t) \\
S(t) &= \frac{1}{3}I(t) \\
E(t) &= \frac{1}{3}I(t)
\end{align}

We adjust each component by its respective risk term:
\begin{enumerate}
\item For debt allocation:
\begin{equation}
D^*(t) = (\frac{1}{3} - \frac{\beta_3\sigma_I^2}{2\beta_1})I(t) = (1/3 - \alpha_D(\sigma_I))I(t)
\end{equation}

\item For savings allocation:
\begin{equation}
S^*(t) = (\frac{1}{3} + \frac{\beta_3\sigma_I^2}{2\beta_2} + \frac{\beta_4\sigma_M^2}{2\beta_2})I(t) = (1/3 + \alpha_S(\sigma_I,\sigma_M))I(t)
\end{equation}

\item For expenses allocation:
\begin{equation}
E^*(t) = (\frac{1}{3} - \frac{\beta_3\sigma_I^2}{2\beta_1})I(t) = (1/3 - \alpha_E(\sigma_I))I(t)
\end{equation}
\end{enumerate}
\subsubsection{Step 6: Final Solution}
Therefore, our optimal allocation strategy becomes:
\begin{align}
D^*(t) &= (1/3 - \alpha_D(\sigma_I))I(t) \\
S^*(t) &= (1/3 + \alpha_S(\sigma_I,\sigma_M))I(t) \\
E^*(t) &= (1/3 - \alpha_E(\sigma_I))I(t)
\end{align}
The adjustment terms represent the optimal deviation from the 1/3 rule needed to minimize bankruptcy risk while maintaining utility above the minimum threshold.


This solution has the following key features:

\begin{enumerate}
    \item It preserves the total budget constraint: $D^*(t) + S^*(t) + E^*(t) = I(t)$
    \item It increases savings allocation when either income or market volatility increases
    \item It symmetrically reduces both debt and expenses to fund the increased savings buffer
    \item The adjustments are proportional to the level of uncertainty in the system
\end{enumerate}

\section{Appendix}
\subsection{Derivation of the Quadratic Penalty Function}

To establish the quadratic nature of deviation penalties, we begin with our utility function and show how deviations from the optimal 1/3 allocation lead to quadratic utility losses.

\begin{theorem}[Quadratic Penalty Derivation]
Given the household utility function U(D, S, E) that satisfies our earlier assumptions of continuity and diminishing returns, the penalty for deviating from the optimal 1/3 allocation takes the quadratic form:
\[ P(d) = kd^2 + O(d^3) \]
where $d$ is the magnitude of deviation and $k > 0$ is a scaling factor.
\end{theorem}

\begin{proof}
Consider our established Cobb-Douglas utility function:
\[ U(D,S,E) = D^\alpha S^\beta E^\gamma \]
where $\alpha = \beta = \gamma = \frac{1}{3}$ for symmetric preferences.

Let $(D^*, S^*, E^*) = (\frac{I}{3}, \frac{I}{3}, \frac{I}{3})$ be the optimal allocation.
Consider a deviation $d$ from this optimum where we increase one component and decrease another while maintaining the budget constraint:

\[ (D,S,E) = (\frac{I}{3} + d, \frac{I}{3} - d, \frac{I}{3}) \]

The utility difference is:
\[ \Delta U = U(D^*,S^*,E^*) - U(D,S,E) \]

Expanding:
\[ \Delta U = (\frac{I}{3})^\alpha (\frac{I}{3})^\beta (\frac{I}{3})^\gamma - (\frac{I}{3} + d)^\alpha (\frac{I}{3} - d)^\beta (\frac{I}{3})^\gamma \]

Using Taylor expansion around $d=0$:
\begin{align*}
U(D,S,E) &= U(D^*,S^*,E^*) + \frac{\partial U}{\partial D}d - \frac{\partial U}{\partial S}d \\
&+ \frac{1}{2}(\frac{\partial^2 U}{\partial D^2}d^2 + \frac{\partial^2 U}{\partial S^2}d^2 - 2\frac{\partial^2 U}{\partial D\partial S}d^2) + O(d^3)
\end{align*}

At the optimal point $(D^*,S^*,E^*)$, first-order terms cancel due to the first-order conditions:
\[ \frac{\partial U}{\partial D} = \frac{\partial U}{\partial S} = \lambda \]

Therefore:
\[ \Delta U = -\frac{1}{2}(\frac{\partial^2 U}{\partial D^2} + \frac{\partial^2 U}{\partial S^2} - 2\frac{\partial^2 U}{\partial D\partial S})d^2 + O(d^3) \]

Computing the second derivatives at the optimal point:
\begin{align*}
\frac{\partial^2 U}{\partial D^2} &= -\frac{\alpha(\alpha-1)}{(I/3)^2}U \\
\frac{\partial^2 U}{\partial S^2} &= -\frac{\beta(\beta-1)}{(I/3)^2}U \\
\frac{\partial^2 U}{\partial D\partial S} &= \frac{\alpha\beta}{(I/3)^2}U
\end{align*}

Substituting $\alpha = \beta = \frac{1}{3}$:
\[ \Delta U = \frac{2U}{9(I/3)^2}d^2 + O(d^3) \]

Define:
\[ k = \frac{2U}{9(I/3)^2} > 0 \]

Therefore:
\[ P(d) = -\Delta U = kd^2 + O(d^3) \]

The positivity of $k$ follows from the concavity of the utility function.
\end{proof}

\begin{corollary}[Economic Interpretation]
The quadratic penalty function implies:
\begin{enumerate}
    \item Small deviations result in proportionally small penalties
    \item Large deviations are disproportionately costly
    \item The penalty grows continuously and smoothly with deviation size
\end{enumerate}
\end{corollary}

This derivation explains why households face increasing pressure to return to the 1/3 allocation as their deviation increases. The quadratic nature of the penalty function provides a mathematical foundation for the empirically observed stability of the 1/3 rule.

