% If $B^\dagger$ is the result of gluing two copies of $B$ together along the boundary component $\partial B\backslash f^{-1}(\{0\})$, and $f^\dagger: B^\dagger \rightarrow [0,\infty)$ is the tautological extension of $f$ to $B^\dagger$, 
%Then $B^\dagger\times^\sN_{f^\dagger} F$ satisfies the condition $\RCD(KN, N+1)$.
\end{theorem}

\begin{remark}
