Then, for $t\in[0,1]$, we define the \emph{volume distortion coefficients} for $\kappa=\tfrac{K}{N}$ with $K\in\R$ and $N\geq1$ as
\begin{equation*}
    \sigma_{\kappa}^{(t)}(\theta):=\begin{cases}
        \tfrac{\sin_\kappa(t\theta)}{\sin_\kappa(\theta)}\quad&\mathrm{if}\,\kappa\theta^2\neq0\,\mathrm{and}\,\kappa\theta^2<\pi^2,\\
        t&\mathrm{if}\,\kappa\theta^2=0,\\
        +\infty&\mathrm{if}\,\kappa\theta^2>+\infty\,,
    \end{cases}
\end{equation*}
and set $\sigma_{K,N}^{(t)}(0)=t$. Define then
\begin{align}\label{distortioncoef}
    \sigma_{K,N}^{(t)}(\theta):=\sigma_{\frac{K}{N}}^{(t)}(\theta), \ \ \ \ \ \ \ 
    \tau_{K,N}^{(t)}(\theta):=(t\cdot\sigma_{K,N-1}^{(t)}(\theta)^{N-1})^{\frac{1}{N}}.
\end{align}
When $N=1$ we set $\smash{\tau_{K,1}^{(t)}(\theta)=t}$ if $K\leq0$ and $\smash{\tau_{K,1}^{(t)}(\theta)=+\infty}$ if $K>0$. 
\smallskip

Let $f: [a,b]\rightarrow [0, \infty)$ be a Lipschitz function. The following statements are equivalent.
\begin{enumerate}
\item For all $  t_0, t_1\in [a,b]$ it holds
$$f((1-s) t_0 + s t_1) \geq \sigma_{K}^{(1-s)}(t_1-t_0) f(t_0) + \sigma_{K}^{(s)}(t_1-t_0) f(t_1) \ \forall s\in [0,1], $$
\item $f''+ K f\leq 0$ in the distributional sense.
\end{enumerate}
If (1) or (2) hold, we say $f$ is $fK$-concave. 
\smallskip

We call a Lipschitz function $f: B\rightarrow [0, \infty)$ $fK$-conave if $f\circ \gamma=h$ is $hK$-concave for every distance preserving map $\gamma:[a,b]\rightarrow B$.
 If $f: B\rightarrow [0, \infty)$ is $fK$-concave, we also write $f''+Kf \leq 0$. 

 In particular $f$ is semi-concave. In this case the left and right derivative $f^-$ and $f^+$ exist in every point, and are right, respectively, left continuous.  We call  $Df= \max\{ f^+ , - f^-\}$ the Alexandrov derivative of $f$, and $Df$ coincides a.e. with the derivative $f'$.

