\subsection{Differential calculus on metric measure spaces}

A metric measure space $X$ is a triple $(X,\de_\sX, \m_\sX)$ where $(X, \de_\sX)$ is a complete, separable metric space and $\m_\sX$ is a locally finite Borel measure on $X$ with full support, i.e. $\m_\sX(B_r(x))\in (0, \infty)$ for every $x\in X$ and $r>0$ sufficiently small.  We also write mm space when we mean metric measure space.  %We will assume that $\supp \m_\sX =X$. 


Let $\gamma:[a,b]\rightarrow X$ be a continuous map. We call $\gamma$ a path in $X$. The length of $\gamma$ is defined via
$$
\sup \sum_{i=1}^N \de_\sX(\gamma(t_{i-1}), \gamma(t_i))=: L^{\sX}(\gamma)$$
where the supremum is w.r.t. to  every partitions $a=t_0\leq t_1 \leq   \dots \leq t_N=b$ of $[a,b]$. 


A metric space $(X, \de_\sX)$ is called  intrinsic (or a length space) if  for every pair of points $x,y\in X$ it holds $\de_\sX(x,y)= \inf L^{\sX}(\gamma)$ where the infimum is w.r.t. all rectifiable curves
%, i.e. curves with finite $L^{\sX}$-length, 
whose endpoints are $x$ and $y$.  
Assuming $x,y\in X$ admit a rectifiable curve $
\gamma$ connecting them such that $L^\sX(\gamma)=\de_\sX(x,y)$, then the curve $\gamma$ is called a  minimal geodesic or  just  geodesic. If every pair $x,y\in X$ admits a minimal geodesic connecting them,  we call $X$ strictly intrinsic or a geodesic space. 

\subsubsection{Cheeger energy}
We will denote by $\lip(X)$ space of Lipschitz functions and by $\lip_b(X)$ the space of bounded Lipschitz functions on $X$. For $f\in \lip(X)$ we denote the local slope by 
$$\lip f(x):= \limsup_{y\rightarrow x} \frac{|f(x)- f(y)|}{\de_{\sX}(x,y)}.$$

We denote with $L^p(\m_\sX)$ the $L^p$ spaces.
The Cheeger energy $\Ch^\sX: L^2(\m_\sX)\rightarrow [0,\infty]$ is the convex and lower semicontinuous functional defined through
$$\liminf_{\scriptscriptstyle \lip(X)\cap L^2(\m_\sX)\ni f_n\overset{L^2}{\rightarrow} f} \int_X(\lip f_n)^2 \de\m_\sX=:\Ch^\sX(f)$$
The finiteness domain of $\Ch$ equipped with the norm $\left\| f\right\|_{W^{1,2}}^2= \left\| f \right\|_{L^2}^2+ \Ch(f)$ we call $W^{1,2}(X)$.

 It is possible to identify  a function $|\nabla f|= |\nabla f|_\sX\in L^2(\m_\sX)$ such that 
$$\Ch^\sX(f)= \int |\nabla f|^2 \de\m_\sX, \ \ \forall f\in W^{1,2}(X). $$

Consider  $f\in L^2(\m_\sX)$.  A function $G\geq 0$ in $L^2(\m_\sX)$ is called  a weak upper gradient of $f$ if 
\begin{align*}\int |f(e_0(\gamma))- f(e_1(\gamma))| \de \Pi \leq \int  \int_0^1 G(\gamma_t)|\dot \gamma_t| \de t  \de \Pi(\gamma)\end{align*}
for every test plan $\Pi$ on $X$. A test plan is a probability measure $\Pi \in \mathcal P(C([0,1], X))$ such that 
\begin{itemize}
\item There exists $C>0$ such that $(e_t)_\sharp\Pi = \mu_t\leq C\m_{\sX}$ for every $t\in [0,1]$, 
\item It holds $\int_0^1 \int |\dot \gamma(t)|^2 \de \Pi(\gamma) \de t< \infty$. 
\end{itemize}
% where $C([0,1],X)$ is the set of continuous maps $\gamma:[0,1]\rightarrow X$.

Then $|\nabla f|$ is {\it the minimal} weak upper gradient in the following sense: if $G$ is a weak upper gradient, then $|\nabla f|\leq G$ $\m_\sX$-a.e.  
\begin{remark}\hspace{0mm}
\begin{itemize}
%\item The definition of the property "for a.e. curve" can be found in \cite{agsriemannian}. 
\item
For a Lipschitz function $u$ one has that $\lip u$ is a weak upper gradient, and hence $|\nabla u|\leq \lip u$ but no equality in general. 
\item
A Borel function $g: X\rightarrow [0, \infty)$ is an upper gradient of a continuous function $u: X\rightarrow \R$ if 
$$ |f(e_0(\gamma))- f(e_1(\gamma))| \leq   \int_0^1 G(\gamma_t)|\dot \gamma_t| \de t  $$
holds  for any absolutely continuous curve $\gamma:[0, 1]\rightarrow X$.  An upper gradient $g$ for a continuous function $u$ is also a weak upper gradient.
\end{itemize}
\end{remark}
\begin{lemma}\label{lem:stabilitywug}
 If $u_n\in W^{1,2}(X)\!\rightarrow\!u\in L^2(\m_\sX)$ p.w. a.e. and $|\nabla u_n|$ converges $L^2$-weakly  to $g\in L^2(\m_\sX)$, then $u\in W^{1,2}(X)$ s.t. $|\nabla u|\leq g$ $\m_\sX$-a.e. 
\end{lemma}

A metric measure space $X$ satisfies the Sobolev-to-Lipschitz property if any $f\in W^{1,2}(X)\cap L^\infty(\m_\sX)$ with $|\nabla f|\leq 1$ $\m_\sX$-a.e. has a representative $\tilde f\in \lip_b(X)$ with $\lip(\tilde f)\leq 1$. 

\subsubsection{Laplace operator}
\begin{definition}[\cite{giglistructure}]
Any mm space $X$ such that $\Ch^\sX$ is a quadratic form is said to be infinitesimally Hilbertian. 
\end{definition} Under this assumption there exists a symmetric bilinear form $$(f,g)\in W^{1,2}(X)\times W^{1,2}(X)\mapsto \langle \nabla f, \nabla g\rangle\in L^1(\m_\sX).$$


The Laplace operator $L^\sX: D(L^\sX)\rightarrow L^2(\m_\sX)$ is defined as follows. We say $f\in W^{1,2}(X)$ is in the domain $D(L^\sX)=D_{L^2}(L^\sX)$ of $L^\sX$ if there exists $L^\sX f\in L^2(\m_\sX)$ such that 
$$\int \langle \nabla f, \nabla \phi\rangle \de \m_\sX= - \int L^\sX f \phi \de \m_\sX, \ \ \forall \phi\in W^{1,2}(X).$$
Since $X$ is infinitesimal Hilbertian,  it holds that $L^\sX$ is linear. 

The heat flow $P_t^\sX$ is  the $L^2(\m_\sX)$ gradient flow of $\Ch^\sX$. 
In the case of an infinitesimal Hilbertian mm space $X$  the heat flow $P_t^\sX$ is a linear, continuous and self-adjoint contraction semigroup  characterized by saying that for any $u\in L^2(\m_\sX)$ the curve $t\mapsto P_t^\sX u\in L^2(\m_\sX)$ is locally absolutely continuous in $(0, \infty)$ and satisfies
$$\frac{d}{dt} P^\sX_t u= L^\sX P_t^\sX u \  \mbox{ for } \mathcal L^1\mbox{-a.e. } t\in (0, \infty), \\  \lim_{t\downarrow 0}P_t u= u \mbox{ in } L^2(\m_\sX).$$
The semigroup $P_t^\sX$ has a unique $L^p$ continuous extension from $L^2\cap L^p$ to $L^p$ for any $p\in [1, \infty)$, and by duality a weak$^*$-continuous extension to $L^\infty(\m_\sX)$. 

\subsubsection{Doubling property}
We say that a metric measure space $X$ satisfies a local  doubling property if for every bounded subset $Y$ in $X$ there exists a constant $C_Y>0$ such that for all $x\in X$ and $0<r<\diam(X,\de_\sX)$ with $B_r(x)\subset Y$ we have 
$$\m_\sX(B_{2r}(x))\leq C_Y \m_\sX(B_r(x)).$$
If one choose $Y=X$, then we say $X$ satisfies a global doubling property. 
\subsubsection{Local Poincar\'e inequality}
We say $X$ supports a weak local $(q,p)$-Poincar\'e inequality with $1\leq p\leq q<\infty$ if for every compact subset $Y$ there exists constants $C>0$ and $\lambda\geq 1$ such that for every Lipschitz function $u$, any point $x\in X$ and $r>0$ with $B_{\lambda r}(x)\subset Y$, it holds
\begin{align}\label{ineq:pi}\left( \int_{B_r(x)} |u - {\textstyle \int_{B_r(x)} u\de\m_\sX}|^q \de \m_\sX\right)^{\frac{1}{q}}\leq C r\left( \int_{B_{\lambda r}(x)} \lip u^p \de \m_\sX\right)^{\frac{1}{p}}.
\end{align}
If $\lambda=1$, we say $X$ supports a strong $(p,q)$-Poincar\'e inequality. 
\begin{remark}\hspace{0mm}
\begin{itemize}
\item Under a doubling property a weak local Poincar\'e inequality implies a strong one. 
\item By H\"older's inequality a weak local $(1,p)$-Poincar\'e inequality implies a weak local $(1,p')$-Poincar\'e inequality for $p'\geq p$.  
\item If a metric measure space satisﬁes a local doubling property, Hajlasz and Koskela proved in \cite{koskela} that
a weak local $(1,p)$-Poincaré inequality also implies a $(q,p)$-Poincaré inequality for $q< \frac{pN}{N-p}$ for $N$ such that  the doubling
constant satisﬁes $C\leq 2^N$. 
%In particular, $X$ supports a weak local $(2,2)$-Poincar\'e inequality. In the following we say that a metric measure
%space $X$  supports a (weak) local Poincaré inequality if it supports a weak local $(1,1)$-Poincaré inequality.
\end{itemize}
\end{remark}
	\begin{theorem}[\cite{cheegerlipschitz}]\label{th:cheegerlipschitz}
			If $X$ is a complete, locally compact and intrinsic metric measure space that satisfies a doubling property and supports a $(1,2)$-Poincar\'e inequality, then for every function $u:X\rightarrow \R$ that is locally Lipschitz, it holds $\lip u=|\nabla u|$. 
		\end{theorem}


\subsection{Curvature-dimension conditions}\label{subsection:rcd}
We will introduce the Riemannian curvature-dimension condition via its characterization in terms of the Bakry-Emery condition for the associated Cheeger energy.
\smallskip

The {\it carr\'e-du-champ operator} (or {\it $\Gamma_2$-operator}) associated to $\Ch^\sX$ is a multilinear form defined via 
$$\Gamma^\sX_2(u,v;\phi)= \int \langle \nabla u, \nabla v \rangle L^\sX \phi \de\m_\sX - \int \langle \nabla u, \nabla L^\sX v\rangle \phi\de\m_\sX$$
for $u, v\in D_{W^{1,2}}(L^\sX),  \phi \in D_{L^\infty}(L^\sX)\cap L^\infty(\m_\sX).$ We set $\Gamma^\sX(u,u)=:\Gamma^\sX(u)$. 
\begin{definition}\label{def:rcd}
A mm space $X$ satisfies the Riemannian curvature-dimension condition $\RCD(K,N)$ for $K\in \R$ and $N\in [1, \infty)$ if 
\begin{enumerate}
\item $\m_\sX(B_r(x_o))\leq C e^{cr^2}$ for some $c, C>0$ and $x_o\in X$, 
\item $X$ is infinitesimal Hilbertian, 
\item $X$ satisfies the Sobolev-to-Lipschitz property, 
\item The Bakry-Emery condition $\BE(K,N)$ holds:
$$\Gamma^\sX_2(u; \phi) \geq K \int |\nabla u|^2 \phi \de\m_\sX + \frac{1}{N} \int (L^\sX u)^2 \phi \de\m_\sX$$
for any $u\in D_{W^{1,2}}(L^\sX)$ and any $\phi\in D_{L^\infty}(L^\sX)\cap L^\infty(\m_\sX)$ with $\phi\geq 0$. 
\end{enumerate}
\end{definition}
\begin{remark}
Equivalently, a metric measure space $X$ satisfies the condition $\RCD(K,N)$ if and only if $X$ satisfies the curvature-dimension $\CD(K,N)$  in the sense of Lott-Sturm-Villani \cite{stugeo1, stugeo2, lottvillani} and is infinitesimally Hilbertian \cite{giglistructure}.  This was the  definition  proposed in \cite{giglistructure}. The condition $\RCD(K, \infty)$ was introduced in \cite{agsriemannian}.   The main contributions for the equivalence with the properties in the Definition \ref{def:rcd} are \cite{giglikuwadaohta}, \cite{agsbakryemery}, \cite{erbarkuwadasturm}, \cite{amsnonlinear} and \cite{cavmil}. We  refer to \cite{gigli_gromov} for further informations on the historical developments, in particular  the Bibliographical Notes of Section 4.4.
\end{remark}
We collect some properties of $\RCD$ spaces that we need later.
\begin{remark}
The condition $\RCD(K,N)$ for $K\in\R $ and $N\geq 1$ is stable w.r.t.  pointed measured Gromov-Hausdorff convergence. Moreover, the class of  pointed $\RCD(K,N)$ spaces $(X,o)$ such that $\m_X(B_1(o))\leq V$ is compact w.r.t. pointed measured GH convergence \cite{stugeo1, stugeo2, lottvillani, gmsstability, erbarkuwadasturm}.
\end{remark}

\begin{remark}The condition $\CD(K,N)$ (and hence the condition $\RCD(K,N)$) implies the measure contraction property $\MCP(K,N)$ \cite{rajala2}, i.e. for a measurable subset $A\subset X$ (such that $A\subset B_{\scriptscriptstyle\pi\sqrt{(N-1)/K}}(x)$ if $K>0$), there exists an $L^2$-Wasserstein geodesic $\Pi$ such that $(e_0)_\# \Pi= \delta_x$ and $(e_1)_\# \Pi= {\m_\sX(A)}^{-1} \m|_A$ and 
$$\m\geq (e_t)_\#\left( \tau^{(1-t)}_{K,N}(L(\gamma)) \m(A) \Pi\right).$$
\end{remark}
\begin{enumerate}
\item This version of the measure contraction property was introduced by Ohta in \cite{ohtmea} (see also \cite{stugeo2} and \cite{kush_bg}).
\item It is known that a metric measure space $X$ that satisfies the condition $\RCD(K,N)$ or the condition $\MCP(K,N)$ has a local doubling property. If $K\geq 0$, $N=1$ or if $X$ is compact, a global doubling property holds such that the doubling constant $C_X\leq 2^N$. 
\item Moreover, a metric measure space $X$ that satisfies the condition $\RCD(K,N)$ or that is nonbranching and satisfies  $\MCP(K,N)$ supports a weak local $(1,1)$-Poincar\'e inequality. 
\end{enumerate}

\subsubsection{Dirichlet forms}
Given a locally compact metric measure space $X$ we recall that a symmetric, quadratic form $\mathcal E: L^2(\m_\sX)\rightarrow [0, \infty]$ that is $L^2(\m_\sX)$-lower semicontinuous and satisfies the Markov property, is called a Dirichlet form. A Dirichlet form is closed if $D(\mathcal E)=\{ u\in L^2(\m_\sX): \mathcal E(u)< \infty\}$ is a Hilbert space.  A Dirichlet form is called regular if it possesses a core $\mathcal C$, i.e. a subset that is dense in $D(\mathcal E)$ w.r.t. the energy norm and dense in $C_0(X)$ w.r.t. uniform convergence. We say $\mathcal E$ is strongly local if $\mathcal E(u,v)$ whenever $u,v\in D(\mathcal E)$ and $(u+a)v=0$ $\m_\sX$-a.e. for all $a\in \R$. For any such form $\mathcal E$ we have that for any $u\in D(\mathcal E)$ there exists a measure $\de\Gamma(u)$, the energy measure, such that $\mathcal E(u)= \int d\Gamma(u)$. If $\de \Gamma(u)= \Gamma(u)\de\m_\sX$ for any $u\in D(\mathcal E)$, where $\sqrt{\Gamma(u)}\in L^2(\m_\sX)$ we say $\mathcal E$ admits a $\Gamma$-operator.  In this case one can define $D_{loc}(\mathcal E)$ as follows. $u\in D_{loc}(\mathcal E)$ if $u\in L^2_{loc}(\m_\sX)$ and there exists $K$ compact such that there exist $v\in D(\mathcal E)$ and $u=v$ $\m_\sX$-a.e. in $K$. The energy measure defines an intrinsic distance 
$$\de_{\mathcal E}(x,y)= \sup\{u(x)-u(y): u\in D_{loc}(\mathcal E)\cap C(X), \de \Gamma(u)\leq \de\m_\sX\mbox{ on } X\}.$$
The distance $\de_{\mathcal E}$ may be degenerated in the sense that $\de_{\mathcal E}(x,y)=\infty$ and $\de_{\mathcal E}(x,y)=0$ for $x,y\in X$ is possible. 
The Dirichlet form $\mathcal E$ is called strongly regular if it is regular and the topology induced by $\de_\mathcal{E}$ coincides with the topology on $X$. In particular $\de_{\mathcal E}$ is nondegenerated. 
\begin{remark}
 The Cheeger energy $\Ch^\sX$ of an $\RCD$ space $X$ is a strongly local and strongly regular Dirichlet form that admits a $\Gamma$-operator. In particular, a core is given by compactly supported Lipschitz function and  the intrinsic distance $\de_{\Ch^\sX}$ associated to $\Ch^\sX$ coincides with the distance $\de_\sX$ \cite{agsriemannian}.
\end{remark}
\begin{remark}\label{rem:feller}
Given a Dirichlet form on $X$ there is a self-adjoint operator associated to it, as well as semi-group $P_t$, that coincide with the Laplace operator and the heat flow in the case of the Cheeger energy.  A Dirichlet form satisfies the  local doubling property if the  space $(X, \de_{\mathcal E}, \m_\sX)$ satisfies a local doubling property. Similarly, a Dirichlet form $\mathcal E$ supports a weak local $(2,2)$-Poincar\'e inequality if \eqref{ineq:pi} holds for all $u\in D(\mathcal E)$ with $\de\Gamma(u)$ in place of $\lip(u)^2 \de \m_\sX$. If in addition closed balls w.r.t. $\de_{\mathcal E}$ are compact, one can infer the following properties for $P_t$ \cite{sturmdirichlet2, sturmdirichlet3}.
\begin{enumerate}
\item $P_t$  is a Feller semi-group. 
\item $P_t$ is $L^2\rightarrow L^\infty$-ultracontractive. 
\item If $\m(X)< \infty$, then harmonic functions are constant. 
\end{enumerate}
\end{remark}
\noindent
Koskela and Zhou proved the following Theorem \cite{koskelazhou}.
\begin{theorem}\label{th:kz}
Let $\mathcal E$ be a strongly local, strongly regular, symmetric Dirichlet form on $L^2(\m_\sX)$. Assume $X$ equipped with $\de_{\mathcal E}$ and $\m_\sX$ satisfies a doubling property. Then $\lip(X)\subset D_{loc}(\mathcal E)$ and every $u\in \lip(X)$ admits a $\Gamma$-operator such that $\Gamma(u)\leq \lip(u)^2$ $\m_\sX$-a.e.
\end{theorem}
\subsection{Second order calculus on $\RCD$ spaces} For the following we refer to \cite{savareself, giglinonsmooth}.

Let $X$ be an $\RCD(K,N)$ space. 
The space of test functions is
$$ 
\tf(X)= \left\{ f\in D(L^\sX)\cap \lip_b(X):   L^\sX f \in W^{1,2}(X)\right\}
$$
The space $\tf(X)$ is an algebra and for every $f\in \tf(X)$ it holds
\begin{enumerate}
\item Let $-g=\langle \nabla f, \nabla \Delta f\rangle + K |\nabla f|^2.$ Then $\int g\de\m_{\sX}\geq 0$ and $|\nabla f|^2 \in W^{1,2}(X)$ with
$$\Ch(|\nabla f |^2)\leq \lip(f)^2 \left( \left\| |\nabla f|\right\|_{L^2} \left\| |\nabla L^\sX f|\right\|_{L^2} + K^-\left\| |\nabla f|\right\|_{L^2}^2\right).$$
\item There exists a unique finite, signed Borel measure $\mu:= \mu^+ - g\m_\sX$ with $\mu_+\geq 0$ and $\mu_+(X) \leq \int_X g\de\m_\sX$ such that 
\begin{enumerate}
\item every $\Ch$-polar set ist $|\mu|$-neglligible, 
\item the quasi-continuous representative $\tilde \phi$ of any  function $\phi \in W^{1,2}(X)$ is in $L^1(|\mu|)$, 
\item it holds
$$\int \langle \nabla u, \nabla \phi \rangle \de\m_\sX= - \int \tilde \phi \de \mu, \ \ \forall \phi \in W^{1,2}(X).$$
\end{enumerate}
We will write ${\bf L}^\sX u:= \mu$. 
\item We denote by ${\bf \Gamma}_2^{\sX}(f)$ the finite, signed Borel measure 
$${\bf \Gamma}_2^{\sX}(f):= \frac{1}{2} {\bf L}^\sX |\nabla f|^2 - \langle \nabla f , \nabla L^\sX f\rangle \de \m_\sX.$$
${\bf \Gamma}_2^\sX(f)$ has finite total variation, and vanishes on sets of $0$ capacity. We write 
$${\bf \Gamma}_2^{\sX}(f) = \gamma_2^{\sX}(f)\m_\sX + {\bf \Gamma}_2^{\sX, \perp}, $$
where $0\leq {\bf \Gamma}_2^{\sX, \perp}\perp \m_{\sX}$. It holds $$\gamma_2^{\sX}(f)\geq K|\nabla f|^2 + \frac{1}{N} (L^\sX f)^2 \mbox{ $\m_\sX$-a.e. in $X$ }$$
as well as 
\begin{align}\label{ineq:bo}{\bf \Gamma}_2^{\sX}(f) \geq \left[K |\nabla f|^2 + \frac{1}{N} (L^\sX f)^2\right] \m_\sX.\end{align}
\end{enumerate}
%Hence 
%$$\int {\bf \Gamma}_2(f) P_t \phi_n \de \m_\sX\geq \int \left[ K |\nabla f|^2 + \frac{1}{N} (L^\sX f)^2 \right] P_t \phi_n \de \m_\sX$$
%implies 
%\begin{align} \label{ineq:intest} 0 \geq \int \left[ \langle \nabla f , \nabla L^\sX f \rangle + K |\nabla f|^2 + {\scriptstyle\frac{1}{N}} (L^\sX f)^2 \right] \de\m_\sX= \int \left[ (L^\sX f)^2 + K |\nabla f|^2 + {\scriptstyle\frac{1}{\sN}} (L^\sX f)^2\right] \de\m_\sX. 
%\end{align}
\begin{corollary}\label{cor:bochnerext}Let $u\in D_{W^{1,2}}(L^\sX)$ and $\psi= \phi + \lambda$ with $\psi\geq 0$, $\phi \in D_{L^\infty}(L^\sX)\cap L^\infty(\m_\sX)$ and $\lambda\in \R$. Then it holds 
$$ \Gamma_2^\sX(u; \psi)\geq  \int\left[K |\nabla u|^2  +{\frac{{1}}{\textstyle N}  }(L^\sX)^2\right]\psi \de\m_\sX$$
where $\Gamma_2^\sX(u; \psi):= \Gamma_2^\sX(u; \phi) - \lambda\int \langle \nabla u, \nabla L^\sX u\rangle \de\m_\sX.$
\end{corollary}
\begin{proof}
{\bf (1)} We pick $f\in \tf(X)$, and $\psi= \phi+ \lambda$ as in the assumptions.  

Since ${\bf \Gamma}_2^\sX(f)$ is a finite, signed measure and $\psi \in L^\infty(\m_\sX)$, it follows that $\int \psi \de {\bf \Gamma}_2^{\sX}(f)$ is well-defined. From \eqref{ineq:bo} we obtain
$$ \int \psi \de{\bf \Gamma}_2^\sX(f) = \int (\phi+ \lambda) \de {\bf \Gamma}_2^\sX(f)\geq \int \left[ K |\nabla f|^2 + \frac{1}{N} (L^\sX f)^2 \right] \psi \de \m_\sX.$$
{\bf (2)} {\it Claim.} $\int \frac{1}{2} \de{\bf L}^\sX |\nabla f|^2 =0$.

Indeed, we can argue as follows. 
Let $\phi_n \in L^2(\m_\sX)$ such that $\phi_n\uparrow 1$. Then, $P_t \phi_n \uparrow 1$ for every $t>0$.  For every $f\in \tf(X)$ it follows that 
\begin{align*} \int  P_t \phi_n  \frac{1}{2}\de{\bf L}^\sX |\nabla f|^2 =&\int\frac{1}{2} \langle P_t\phi_n, \nabla |\nabla f|^2\rangle \de\m_\sX\\
=& \int \frac{1}{2} L^\sX P_t \phi_n |\nabla f|^2 \de \m_\sX\\
=&\int \frac{1}{2} L^\sX P_{\frac{t}{2}} \phi P_{\frac{t}{2}}|\nabla f|^2 \de\m_\sX\\
=&  \int \frac{1}{2} P_{\frac{t}{2}} \phi_n  L^\sX P_{\frac{t}{2}} |\nabla f|^2\de\m_\sX \\
&\rightarrow \int \frac{1}{2} L^{\sX} P_{\frac{t}{2}}|\nabla f |^2 \de\m_\sX=0 \mbox{ as $n\rightarrow \infty$}. \end{align*}
The left-hand side converges to $\frac{1}{2} \int \de {\bf L}^\sX |\nabla f|^2 .$ This proves the claim. \qed
\smallskip

It follows
\begin{align*}\int \psi \de{\bf \Gamma}_2^\sX(f)=&\int\left[ \frac{1}{2} {\bf L}^\sX |\nabla f|^2  - \langle \nabla f , \nabla L^\sX f\rangle \right] \psi \de \m_\sX\\
=& \int\left[\frac{1}{2} |\nabla f|^2 L^\sX \phi  - \langle \nabla f, \nabla L^\sX f\rangle \psi\right] \de \m_\sX = \Gamma_2(f; \psi)
% \geq \int \left[ K |\nabla f|^2 + \frac{1}{N} (L^\sX f)^2 \right] \psi \de \m_\sX
.\end{align*}
{\bf (3)} Let $u\in D_{W^{1,2}}(L^\sX)$ and choose $u_n\in \tf(X)$ such that $u_n\rightarrow u$ in $D(L^\sX)$. 
Since $\phi, L^\sX\phi \in L^\infty(\m_\sX)$, it follows 
\begin{align*} 
\frac{1}{2} \int |\nabla u_n|^2 L^\sX \phi &\rightarrow \frac{1}{2} \int |\nabla u|^2 L^\sX\phi \de\m_\sX\\
K \int |\nabla u_n |^2 \psi \de \m_\sX&\rightarrow K \int |\nabla u|^2 \psi \de \m_\sX\\
\frac{1}{N} \int (L^\sX u_n)^2 \psi \de \m_\sX& \rightarrow \frac{1}{N} \int (L^\sX u)^2 \psi \de\m_\sX. 
\end{align*}

To treat $\int \langle \nabla u_n , \nabla L^\sX u_n\rangle \psi \de\m_{\sX}$
let us pick $P_t\phi$ in place of $\phi$. Then, since $X$ satisfies the condition $\RCD(K,N)$, we have that $P_t\phi \in \lip_b(X)$. Consequently, we can compute that
\begin{align*}\int \langle \nabla u_n , \nabla L^\sX u_n\rangle (P_t \phi + \lambda) \de\m_{\sX}=& - \int (L^\sX u_n)^2 (P_t \phi  + \lambda) \de\m_\sX\\
& \ \ \ \ - \int \langle \nabla u_n , \nabla P_t\phi\rangle L^\sX u_n \de \m_\sX.
\end{align*}
Since $u_n\rightarrow u$ in $D(L^\sX)$, for $n\rightarrow \infty$ the left- and right-hand side converge to 
\begin{align*}&\int \langle \nabla u , \nabla L^\sX u\rangle (P_t \phi + \lambda) \de\m_{\sX}=\\
&- \int (L^\sX u)^2 (P_t \phi  + \lambda) \de\m_\sX - \int \langle \nabla u , \nabla P_t\phi\rangle L^\sX u \de \m_\sX.\end{align*}
Hence,  the desired inequality follows for $u \in D_{W^{1,2}}(L^\sX)$ and $\psi= P_t\phi +\lambda$. 

Finally, we can replace $P_t\phi$ with $\phi$ by an application of the dominated convergence theorem since $P_t\phi \rightarrow \phi$ pointwise $\m_\sX$-a.e.
\end{proof}

\subsection{Weighted $1$-dimensional Riemannian manifolds}
Let $B$ be a complete $1$-dimensional Riemannian manifold, i.e.  $B$ is isometric to $[0,\pi]$, $[0, \infty)$, $\R$ or $\mathbb S^1$.  We  write $u'v'= \langle u', v' \rangle_\sB$ for smooth functions $u, v$ on $B$.

Let $f: B\rightarrow [0,\infty)$ be smooth and not identical $0$.
%  locally Lipschitz  and  $\lambda$-concave.  
\smallskip

\noindent
{\bf We assume} that $$\partial B= f^{-1}(\{0\})$$ 
in case either set is non-empty.
%\begin{jjj}
%We note that $f''+fK\leq 0$, $\Im f\geq 0$ and $\partial B\subset f^{-1}(\{0\})$ implies $\partial B= f^{-1}(\{0\})$. 
%\end{jjj}
%
\begin{remark}
If we assume that\begin{center} $f''+K\leq 0$ and $\partial B\subset f^{-1}(\{0\})$, \end{center}
then it follows  from the maximum principle that $\partial B= f^{-1}(\{0\})$.
\end{remark}
\smallskip

We set $\m_\sB^\sN=f^\sN\vol_\sB$. Then we consider the pair $(B, \m_\sB^\sN)$ and the  quadratic form 
$$\mathcal E^{\sB, \sN}(u)= \int |u'|^2 \de \m_{\sB}^\sN, \ \ u\in C^\infty(B).$$


The form closure of $\mathcal E^{\sB, \sN}$ in $L^2(\m^\sN_\sB)$ is the Cheeger energy  $\Ch^{\sB, \sN}$ of the metric measure space $(B,\m_\sB^\sN)$ where the domain of $\Ch^{\sB, \sN}$ is $W^{1,2}(B, \m_\sB^\sN)$, the space of $L^2$ Sobolev functions. 

We can also consider the closure $W_0^{1,2}(\mathring B, \m_\sB^\sN)$  of $C^\infty_c(\mathring B)$ in $W^{1,2}(B, \m_\sB^\sN)$ and the following lemma explains the relation between $W^{1,2}(B, \m_\sB^\sN)$ and $W_0^{1,2}(B, \m_\sB^\sN)$.
\begin{lemma} If $N\geq 1$,
$W_0^{1,2}(\mathring B, \m_\sB^\sN)= W^{1,2}(B, \m_\sB^\sN).$
\end{lemma}
\begin{proof}
First we recall the $2$-capacity of a set $K\subset B$: 
$$\mbox{Cap}_2(K)= \inf \left\| u\right\|_{W^{1,2}}$$
where the infimum is w.r.t. all functions $u$ such that $0\leq u\leq 1$ and $u\geq 1$ on a neighborhood of $K$. 

We can  construct a Lipschitz function such that $u\equiv 1$ on $B_{\frac{\epsilon}{3}}(\partial B)$, $u\equiv 0$ on $B\backslash B_{\epsilon}(\partial B)$ and  $|u'|_\sB \leq \frac{3}{\epsilon}$.  Since $f$ is $\lambda$-concave, there exists $g>0$ such that  $$f(t)\leq f(t_0) + g (t-t_0) + o(t) \ \forall t_0\in \partial B.$$ One can compute that
$$\int_B |u'|_{\sB}^2 \m_\sB^\sN \leq \int_{\frac{\epsilon}{3}}^\epsilon \left(\frac{3}{\epsilon}\right)^2 f^\sN(t) dt\leq C(f, N) \frac{1}{\epsilon^2}\int_{\frac{\epsilon}{3}}^\epsilon t^\sN dt\leq  C(f, N) \epsilon^{\sN-1} .$$
Applying Mazur's lemma and letting $\epsilon\downarrow 0$ we find  a sequence that strongly converges to $0$  in $W^{1,2}$. It follows that $\mbox{Cap}_2(\partial B)=0$. 
%
%Then the claim follow, for instance like in Lemma 2.2 in \cite{...}.
\end{proof}
The space $C_c^\infty( B)$ is a core of $\Ch^{\sB, \sN}$. A core is a subset of $W^{1,2}(B, \m_\sB^\sN)\cap C_c(B)$  that is dense in $W^{1,2}(B, \m_\sB^\sN)$ w.r.t. to the norm 
$$\left\| u\right\|^2_{W^{1,2}}= \left\| u\right\|^2_{L^2} + \Ch^{\sB, \sN}(u)$$
and dense in $C_c(B)$ w.r.t. uniform convergence. 

The domain $D(L^{\sB, \sN})$ of the generator $L^{\sB, \sN}$ associated to $\Ch^{\sB, \sN}$ is the set of $u\in W^{1,2}(B, \m_\sB^\sN)$ such that $ \exists g\in L^2(\m_\sB^\sN) \mbox{ with }$$$ \Ch^{\sB, \sN}(u,v)= -\int g v \m_\sB^\sN \ \forall v\in W^{1,2}(B, \m_\sB^\sN).$$
We write $L^{\sB, \sN} u:= g$ and for $u\in C^\infty_{c} (\mathring B)$ it follows that
$$
L^{\sB, \sN}u= u'' - \frac{N}{f} \langle f', u'\rangle_\sB.
$$
\begin{proposition} Let $f: B\rightarrow [0,\infty)$ be a smooth function such that $\partial B= f^{-1}(\{0\})$. Then the following statements are equivalent: 
\begin{enumerate} 
\item $f$ satisfies $f''+ K f\leq 0$, 
\item The space $(B, \m^\sN_\sB)$ satisfies the condition $\RCD(KN,N+1)$.  
\end{enumerate}
\end{proposition}
\begin{proof}
%The implication (i)$\Rightarrow$(ii) is a consequence of Theorem 1.7 (ii) in \cite{stugeo2} and the fact that the $1$-dimensional space $B$ is infinitesimal Hilbertian. 
%
%For the implication (ii)$\Rightarrow$(i), for instance, 
We note that $f$ is smooth and therefore the $\RCD(KN,N+1)$ condition holds if and only if   the Bakry-Emery $N$-Ricci tensor satisfies \begin{center}$\ric^{N+1, f}_\sB= - \frac{1}{N}\frac{f''}{f} g_\sB \geq  K g_\sB \mbox{ on } B\backslash \partial B$
\end{center}Hence $f''+ Kf\leq 0$ on $B$.
\end{proof}
\begin{example}
Let $B=[0, \pi]$ and $f(r)= \sin(r)$. Then the mm space $([0,\pi], f^{N-1}\de r)$ satisfies the condition $\RCD(N-1, N)$. 
\end{example}
