\end{corollary}
We also recall the following general statement about warped products and Alexandrov  lower curvature bounds. For the definition of  Alexandrov curvature bounded from below, CBB,  we refer to \cite{bbi}. We assume that the Hausdorff dimension is finite. 

\begin{theorem}[Alexander-Bishop, {\cite{albi}}]\label{th:albi1} Let $B$ and $F$ be complete, locally compact intrinsic metric spaces. Let $f: B\rightarrow [0, \infty)$ be a Lipschitz function.

Then the  warped product 
$B\times_ f F$ has CBB by $K$ if and only if 
\begin{enumerate}
	\item \begin{itemize}\item[(a)] $B$ has CBB by $K$,\item[(b)] $f$ is $Kf$-concave,
\item[(c)] If $B^\dagger$ is the result of gluing two copies of $B$ along the closure of the set of boundary points where $f$ is nonvanishing, and $f^\dagger: B^\dagger \rightarrow [0,\infty)$ is the tautological extension of $f$, then $B^\dagger$ has CBB by $K$ and $f^\dagger$ is $fK$-concave. 
\end{itemize}

\item $F$ has CBB by $K_F=\sup_B\{ |D f|^2 {\displaystyle+} Kf^2\}$, 

\end{enumerate}
\end{theorem}

