Since $C_c^\infty(\mathring B)\otimes W^{1,2}(F)$ is dense in $D(\mathcal E^*)$ w.r.t. $\left\| \cdot \right\|_{\mathcal E^*}$, this identity extends to all $v\in D(\mathcal E^*)$. 

Moreover, since $r\mapsto u(r,x), L^{\sB, \sN}u(r,x), L^\sF u(r,x)$ belong to $C^\infty_c(\mathring B)$ for $\m_\sF$-a.e. $x\in F$, it follows that 
$$L^{\sB, \sN}u^x + f^{-2} L^\sF u^r \in L^2(\m^\sN).$$
Hence $u\in D_{L^2}(L^*)$ and the desired formula for $Lu$ holds. 
\smallskip

(2) We pick $u_2\in E(\lambda)$ and $u_1\in D(L^{\sB, \sN, \lambda})$, and set $u_1 \otimes u_2 =u$. We notice first that $u^x(r)= u_1(r) u_2(x)$, and hence $L^{\sB, \sN, \lambda} u^x= \left[ L^{\sB, \sN, \lambda} u_1\right] u_2(x)\in L^2(\m^\sN)$.  We compute for any $v\in C_c^\infty(\mathring B) \otimes W^{1,2}(F)$
\begin{align*}&
\mathcal E^*(u,v)= \\
&\int \int  \langle (u^x)', (v^x)'\rangle_\sB  \dint \m^{\sN}_\sB \dint \m_\sF(x)+ \int \frac{1}{f^2} \int \langle \nabla u^r, \nabla u^r\rangle_\sF \dint \m_\sF \dint \m_\sB^\sN(r)\\
&=\int \int  \langle (u^x)', (v^x)'\rangle_\sB  \dint \m^{\sN}_\sB \dint \m_\sF(x)- \int \frac{\lambda}{f^2} \int u^r v^r \dint \m_\sF \dint \m_\sB^\sN(r)\\
&=\int \int  \left[\langle (u^x)', (v^x)'\rangle_\sB  -  \frac{\lambda}{f^2}  uv\right] \dint \m_\sF \dint \m_\sB^\sN(r)\\
&= \int \mathcal E^{\sB, \sN, \lambda}(u^x, v^x) \dint \m_\sF(x) \\
&=- \int \int L^{\sB, \sN, \lambda} u^x v^x \dint \m_\sB^\sN \dint \m_\sF=- \int \left[L^{\sB, \sN, \lambda} u\right] v \dint \m^\sN
\end{align*}
This identity again extends to all $v\in D(\mathcal E^\snwp)$. Therefore we obtain the claim. 
\end{proof}
\begin{proposition}
Let $P_t^{\sB, \sN, \lambda}$ the semi-group induced by $L^{\sB, \sN, \lambda}$. 
For $u=u_1\otimes u_2\in C^\infty_c(\mathring B)\otimes E(\lambda)\subset D_{L^2}(L^\sC)\cap L^\infty(\m_\sF)\cap \lip(F)$ we have that 
$$P_t^* u= P_t^{\sB, \sN, \lambda} u_1 \otimes u_2$$
where $P_t^*$ is the semi-group associated to $L^*$. 

In particular, for $u=u_1\otimes u_2\in C^\infty_c(\mathring B)\otimes E(\lambda)$ we have a  formula for $P_t^* u$ in terms of $P_t^{\sB, \sN, \lambda} u_1$ and $u_2$. 
\end{proposition}
\begin{proof}
Indeed, since $P_t^{\sB, \sN, \lambda} C_c^\infty(\mathring B)\subset D(L^{\sB, \sN, \lambda})$ and since
$$\frac{d}{dt} P_t^{\sB, \sN, \lambda} u_1 = L^{\sB, \sN, \lambda} P_t^{\sB, \sN, \lambda} u_1, \ \ u_1\in C_c^\infty(\mathring B),$$
we also have 
$$\frac{d}{dt} P_t^{\sB, \sN, \lambda} u_1 \otimes u_2= L^{\sB, \sN, \lambda} P_t^{\sB, \sN, \lambda} u_1 \otimes u_2= L^*(P_t^{\sB, \sN, \lambda} u_1 \otimes u_2)$$
where the last equality is the second statement in the  Proposition \ref{prop:wpop}.
\end{proof}
\begin{definition}
We define 
\begin{align*}\Xi' &= \sum_{i=0}^\infty P_t^{\sB, \sN, \lambda} C_c^\infty(\mathring B) \otimes E(\lambda_i) \\
&= \left\{ \sum^k_{i=0} u^i_1\otimes u^i_2: u_1^i\in P_t^{\sB, \sN, \lambda}C_c^\infty(\mathring B), u^i_2\in E(\lambda_i), k\in \N\right\}.
\end{align*}
The class $\Xi'$ is dense in $D(L^\sC)$ and stable w.r.t. $P_t^\sC$. 
\end{definition}
\subsection{Regularity of $N$-warped products with one-dimensional fiber}
Towards our main theorem we can make use of the fact that the result is already established for the case of a smooth $f$ and  a one-dimensional fiber space $F$. This follows since for smooth $f$ the warped product  is a smooth weighted Riemannian manifold away from points of degeneration of $f$. The following theorem is a direct corollary of Theorem 1.1 in \cite{ketterer}.
\begin{theorem} 
Assume $(B,g_\sB)$ is a Riemannian manifold that has Alexandrov curvature bounded from below, $f$ is smooth on $B$,  $\partial B\subset f^{-1}(\{0\})$, $N>1$, and
\smallskip
\begin{enumerate}
\item $\nabla^2 f+ K f g_\sB \leq 0$, 
\medskip
\item $|\nabla f|_\sB^2 + K f^2 \leq K_F$, 
\end{enumerate} 
Then the $N$-warped product satisfies $B\times_f^N \left( [0,\frac{\pi}{\sqrt{K_F}}], \sin^{N-1}(\sqrt{K_F}r) dr\right)$ satisfies the condition $\RCD((N+d-1)K,N+d)$.
\end{theorem}
\begin{corollary} \label{th:boundschroedinger}
Assume $B\subset \R$ is a closed interval, $f$ is smooth on $B$,  $\partial B\subset f^{-1}(\{0\})$, $N>1$ and $\lambda>0$.
Assume
\smallskip
\begin{enumerate}
\item $f''+ K f\leq 0$, 
\medskip
\item $|f'|^2 + K f^2 \leq K_F$. 
\end{enumerate} 
If $K_F>0$, we assume $\lambda\geq \frac{K_F N}{N-1}$. 
Consider the semi-group $\left( P_t^{\sB, \sN, \lambda}\right)_{t>0}$ associated to the operator $L^{\sB, \sN, \lambda}$. 
Then 
$$ P_{t}^{\sB, \sN, \lambda} u, |\nabla P_{t}^{\sB, \sN, \lambda} u|\in L^\infty(\m_{\sB}^\sN),  \ \forall t>0, \ \ u\in C^\infty_c(B).$$
\end{corollary}
\begin{proof}
The proof of this corollary is the same as the corresponding result for spherical $N$-suspension in Section 3.4 of \cite{ketterer2}.\end{proof}
From this we  can deduce the following important regularity property of elements in $\Xi'$ (this is Remark 3.21 in \cite{ketterer2}).
\begin{corollary}
If $u\in \Xi'$, then $u, |\nabla u|, L^\sC u \in L^\infty(\m^\sN)$. 
\end{corollary}
\section{Metric structure of $N$-warped products over $\RCD$ spaces}\label{sec:metricstructure}


Let $F$ be a compact $\RCD(K_\sF(N-1),N)$ space where $N>1$ and $K_F\in \R$. In particular $\m_\sF$ is finite.


Assume $B$ is a  $1$-dimensional Riemannian manifold, $f: B\rightarrow [0,\infty)$ is smooth,  $\partial B\subset f^{-1}(\{0\})$, and
\smallskip
\begin{enumerate}
	\item $f''+ K f\leq 0$, 
	\medskip
	\item $|f'|^2 + K f^2 \leq K_F$. 
\end{enumerate} 
\smallskip

The $N$-warped product $\nwp$ is a complete metric measure space. Hence, we can also consider its Cheeger energy $\Ch^\snwp$ and the associated space of Sobolev functions $D(\Ch^\snwp)=W^{1,2}(\nwp)$. In the following we investigate the relation between the energy $\mathcal E^*$ and $\Ch^\snwp$.
\begin{proposition}\label{prop:energyineq} It holds $D(\mathcal E^*)\subset W^{1,2}(\nwp)$ and for all $u\in C^\infty_c(\mathring B)\otimes \lip(F)$ we have 
\begin{align}\label{ineq:wugs}|\nabla u|^2_{\snwp} \leq |\nabla u|_\sB^2 + \frac{1}{f^2} |\nabla u|^2_{\sF} = |\nabla u|_{*}^2  \ \ \mbox{$\m^\sN$-a.e}.
\end{align}
and for all $u\in D(\mathcal E^*)$ we have \begin{align}\label{ineq:wugenergy}\mbox{$|\nabla u|^2_\snwp\leq \Gamma^*(u,u)$ $\m^\sN$-a.e.  }
\end{align}
where $\Gamma^*$ is the $\Gamma$-operator associated to $\mathcal E^*$ and $|\nabla (\cdot)|_{\snwp}$ is the minimal weak upper gradient of $\Ch^\snwp$.
\end{proposition}
\begin{proof}
{\bf (1)}
Let $u\in C^\infty_c(\mathring B)\otimes \lip(F)$, i.e. $u= \sum_{i=1}^N u^i_1\otimes u_2^i$ with $u_1^i\in C^\infty_c(\mathring B)$ and $u_2^i\in \lip(F)$.

Let $\gamma=(\alpha, \beta):[0,1]\rightarrow \mathring B\times F$ be a continuous curve in $AC^2(\mathring B\times F)$. It is straightforward to check that $\alpha \in AC^2(\mathring B)$ and $\beta \in AC^2(F)$. Hence 
\begin{align*} 
\left| u(\alpha(s), \beta(t))- u(\alpha(s), \beta(t'))\right|&\leq L \de_\sF(\beta(t), \beta(t'))\\
&\leq \int_t^{t'} g(\tau)\dint \tau\leq |v(t)- v(t')|\\
\left| u(\alpha(s), \beta(t))- u(\alpha(s'), \beta(t))\right|&\leq L  |\alpha(s)- \alpha(s')|\\
&\leq \int_{s}^{s'} g(\tau)\dint \tau\leq |v(s)- v(s')|
\end{align*}
where $v(t) =\int_0^t g(\tau) \dint \tau$ for an integrable function $g: [0, 1] \rightarrow [0,\infty)$ that depends on $\gamma= (\alpha, \beta)$. 

Then, we can use Lemma 4.3.4 in \cite{agsgradient} to obtain 

\begin{align*}
\left|\frac{d}{dt} (u\circ \gamma)(t)\right|\leq &\limsup_{h\rightarrow 0} \frac{|u(\alpha(t-h), \beta(t))- u(\alpha(t), \beta(t))|}{h}\\
&  \ \ \ \ \ \ \ + \limsup_{h\rightarrow 0} \frac{|u(\alpha(t), \beta(t+h))- u(\alpha(t), \beta(t))|}{h}\  
\end{align*}
$\mbox{for  $\mathcal L^1$-a.e. } t\in [0,1].$

Applying the definition of the local Lipschitz constant it follows that 
\begin{align}\label{ineq:loclip}
&\left|\frac{d}{dt} (u\circ \gamma)(t)\right|\leq \lip u^{\beta(t)}(\alpha(t)) |\dot{\alpha}(t)| + \lip u^{\alpha(t)}(\beta(t))|\dot \beta(t)| 
%\\
%&\leq \sqrt{ \lip u^{\beta(t)}(\alpha(t)) + {\textstyle \frac{1}{(f\circ \alpha(t))^2}} \lip u^{\alpha(t)}(\beta(t))} \sqrt{  |\dot{\alpha}(t)| + (f\circ \alpha(t))^2 |\dot \beta(t)|^2 } 
\end{align}
 for  $\mathcal L^1$-a.e. $ t\in [0,1].$

 We note  $u^{r}=u(r,\cdot)$  is locally Lipschitz in  $F$ for every $r\in B$. Hence, since $F$ is $\RCD$, and therefore satisfies a doubling property and supports a weak local Poincar\'e inequality, by Theorem \ref{th:cheegerlipschitz} it follows that  $\lip u^{r}= |\nabla u^{r}|_\sF$.  Moreover, $u^{
 x}$ is smooth on $B$ for every $x\in F$, and therefore $\lip u^{x}= |(u^{
 x})'|$.


We set $$G_u(r,x):= \sqrt{ \left((u^{x})'(r)\right)^2 + {\textstyle \frac{1}{(f(r))^2}}|\nabla u^{r}|^2_\sF(x)}.$$

Hence, in combination with the Cauchy-Schwarz inequality it follows from \eqref{ineq:loclip} that
$$
	\left|\frac{d}{dt} (u\circ \gamma)(t)\right|\leq G_u(
	\alpha(t), \beta(t))  \sqrt{  |\dot{\alpha}(t)| + (f\circ \alpha(t))^2 |\dot \beta(t)|^2 } 
$$

We integrate this inequality w.r.t. $t$ and obtain
\begin{align}\label{ineq:wug}|u(
\gamma(1))- u(
\gamma(0))|\leq \int_0^1 G_u(\gamma(t)) |\gamma'(t)| \de t.
\end{align}
Since $u$ is compactly supported in $\mathring B\times F$, it already follows from the inequality \eqref{ineq:wug}, that holds for every $\gamma=(\alpha, \beta):[0,1]\rightarrow \mathring B\times F$ in $AC^2(\mathring B\times F)$, that $G$ is a weak upper gradient of $u$. Hence 
$$|\nabla u|^2 \leq G_u \ \m^\sN\mbox{-a.e.}$$
\smallskip
{\bf (2)}
We have that $C_c^\infty(\mathring B)\otimes \lip(F)$ is dense in $D(\mathcal E^*)$ by definition of the closed form $\mathcal E^*$. Hence, if $u\in D(\mathcal E^*)$ we can pick a sequence $u_n\in C_c^\infty(\mathring B)\otimes \lip(F)\rightarrow u$ w.r.t. $\left\|\cdot \right\|_{\mathcal E^*}^2$.  In particular, we have  $u_n\rightarrow u$ in $L^2(\m^\sN)$. 
$$\Ch^\snwp(u_n)\leq \mathcal E^*(u_n)\rightarrow \mathcal E^*(u)<\infty.$$
Hence $u\in W^{1,2}(\nwp)$, and $\Ch^\snwp(u)\leq \mathcal E^*(u)$. 
After extracting a subsequence $|\nabla u_n|$ converges pointwise $\m^\sN$-a.e. to a weak upper gradient of $u$ by the stability property of minimal weak upper gradients. 

On the other hand 
$$\sqrt{ (\lip u_n^{x})2 + \frac{1}{f^2} |\nabla u_n|^2_F} \rightarrow \Gamma^*(u,u)$$
in duality with $L^\infty(\m^\sN)$ by property (4) in Remark \ref{properties:estar}.
Since the left hand side is a weak upper gradient of $u_n$, after taking another subsequence, it converges  to a weak upper gradient of $u$ by Lemma \ref{lem:stabilitywug}. Hence, the desired inequality \eqref{ineq:wugenergy} follows. \end{proof}
We recall the following result from \cite{cks}.
\begin{theorem}\label{th:mcpfornwp}
Let $F, I$ and $f$ be as before. Then $\nwp$ satisfies the measure contraction property $\MCP(KN, K+1)$. 
\end{theorem}
Recall that the intrinsic distance $\de_{\mathcal E^*}$ of the strongly local, regular Dirichlet form $\mathcal E^*$ is defined through
\begin{align*}&\de_{\mathcal E^*}((s,x),(t,y))\\
	&\ \ \ \ \ = \sup\{ u(s,x)-u(t,y): u\in D_{loc}(\mathcal E^*)\cap C(B\times F/\sim), \Gamma^*(u,u)\leq 1\}.
	\end{align*}
\begin{proposition}\label{prop:distancewp} Let $F, B$ and $f$ as before. The intrinsic distance of $\mathcal E^*$ coincides with the distance on $\mwp$. 
\end{proposition}
\begin{proof} {\bf (1)}
We know by Proposition \ref{prop:energyineq} that $D(\mathcal E^*)\subset W^{1,2}(\nwp)$, and for any $u\in D(\mathcal E^*)$ we have 
$$\left| \nabla u\right|^2:= \left| \nabla u\right|_\snwp^2\leq\Gamma^*(u,u).$$
Then, $\Gamma^*(u,u)\leq 1$ implies that $|\nabla u|\leq 1$.\smallskip\\
{\it Claim:} Since $\nwp$ satisfies the measure contraction property $\MCP(KN, N+1)$, it also satisfies the Sobolev-to-Lipschitz property.
\smallskip

 Indeed, for points $p, q\in \nwp$ we set $\mu_0= \m(B_\epsilon(q))^{-1}\m^\sN|_{B_\epsilon(q)}$ and $\mu_1=\delta_p$. Let $\Pi$ be the unique optimal dynamical plan  between $\mu_0$ and $\mu_1$.  Hence the restriction $(e_{[0, t_0]})_\sharp \Pi$ is a $2$-test plan. Since $|\nabla u|$ is in particular a weak upper gradient it follows
\begin{align*}&\int |u(e_1(\gamma))- u(e_0(\gamma))| \dint \Pi(\gamma)
	\\
	&\ \ \ \ \ \leq \int \int_0^1 |\nabla u|(e_t(\gamma))L(\gamma) \de t \de \Pi(\gamma)\leq W(\mu_0, \mu_1)\end{align*}
where we used $|\nabla u|\leq 1$ and  the Cauchy-Schwarz inequality in the last inequality. 

If we send $\epsilon\rightarrow 0$, we obtain $|u(p)- u(q)|\leq \de_{\smwp}(p,q).$
This yields 
$$\de_{\mathcal E^*}(p,q)= \sup\{ u( p) - u( q)\} \leq \de_{\smwp}(p,q).$$
{\bf (2)}
On the other hand,  we pick $p=(s,x)$ and $q=(t,y)$ in $\mwp$, and let $\gamma=(\alpha, \beta): [0,1]\rightarrow \mwp$ be the geodesic between $p$ and $q$.  By Theorem \ref{th:albi0} $\gamma$ is determined by $s, t$ and $L^\sF(\beta)=L$. Hence 
$$L(\gamma)= L(\tilde \gamma)$$
where $\tilde \gamma$ is the geodesic between the points $(s,0)$ and $(t, L)$ in $B\times_f \R$. 
Hence \begin{align}\label{formula:gencos}\de_{\smwp}(p,q)=\de_{B\times_f \R}((s,0), (t, L))=: h(t, L)= h(t, \de_\sF(x,y)) =:g(t,y).
\end{align}
Since $h$ is just the distance function to $(s,0)$ in $B\times_f \R$ we have  $|\nabla^{(t,L)} h|\leq 1$ in $B\times_f \R$. 

The chain rule for the $\Gamma$-operator $\Gamma^*$ applied to the function $g$, that is a composition of $h$ and $\de_\sF(x, \cdot)$, yields 
\begin{align*}\Gamma(g,g)(t,y)&= \left( \frac{\partial}{\partial t} h(t, L)\right)^2+ \frac{1}{f^2(t)} \left(\frac{\partial}{\partial L} h(t, L) \right)^2|\nabla \de_\sF(x, \cdot)|^2(y)\\
&\leq\left( \frac{\partial}{\partial t} h(t, L)\right)^2+ \frac{1}{f^2(t)} \left(\frac{\partial}{\partial L} h(t, L) \right)^2\\
&=|\nabla^{(t,L)} h|(r,L)^2\leq 1\end{align*}
Hence 
$$
\de_{\smwp}(p,q)= g(q)- g(q)\leq \de_{\mathcal E^*}(p,q).$$
\end{proof}
\begin{assumption}\label{assumption:doubling}
In addition to our  assumptions above  we  assume that \begin{center}
$(\%)$ \ $B\times_f^N F$ satisfies a  {\bf global} doubling property.\end{center}\end{assumption}
\begin{assumption}\label{assumption:doubling2}
The Assumption \ref{assumption:doubling} holds in each of the following cases: 
\begin{enumerate}
\item 
 If $B$ and $F$ are  compact, $B\times_f F$ is compact. Then the property $\MCP(KN,N+1)$ implies $(\%)$.  
\item If $K\geq 0$, then $B\times_f F$ satisfies $\MCP(0,N+1)$ that implies  $(\%)$. 
\item If   $f$  is a bounded function and $F$ is compact, then $(\%)$ holds. 
Indeed, this is true  since $B\times_f^\sN F$  satisfies $\MCP(KN, N+1)$, and since boundedness of $f$ and compactness of $F$ imply that the volume of balls of radius $r$ grows at most like $\sim r$. 
\end{enumerate}
\end{assumption}
\begin{corollary} 
	Let $B, f$ and $F$ as before and  $(\%)$ holds. Then $\mathcal E^*= \Ch^\snwp$. 
\end{corollary}
\begin{proof}
	We have $\de_{\mathcal E^*}= \de_{\smwp}$ by the previous proposition. Hence, $\de_{\mathcal E^*}$ induces the topology of $B\times F/\sim$. By Theorem \ref{th:mcpfornwp} $B\times_f^N F$ satisfies the property $MCP(KN, N+1)$. Because of the property $(\%)$ $\nwp$ satisfies a doubling property. Hence $B\times F/\sim$ with $\de_{\mathcal E^*}$ and $\m^\sN$ satisfies a doubling property.  Then, it follows by Theorem \ref{th:kz} that any for any Lipschitz function $u$ w.r.t. $\de_{\mathcal E^*}= \de_{\smwp}$ we have that $u\in D_{loc}(\mathcal E^*)$ and $\Gamma^*(u,u)\leq \lip(u)^2$.  Since $\nwp$ also satisfies a local Poincar\'e inequality, by a theorem of Cheeger we have $\lip(u)=|\nabla u|$. On the other hand, the Proposition \ref{prop:energyineq} says that 
	$|\nabla u|^2\leq \Gamma^*(u,u)$.  Hence, by integration w.r.t. $\m^\sN$ we have that $\mathcal E^*(u)= \Ch^{\snwp}(u)$ for any Lipschitzfunction. We infer that $\mathcal E^*= \Ch^\snwp$.
\end{proof}
