\subsection{The carr\'e-du-champ operator on $N$-warped products}\label{subsec:gamma2}

Let $F$ be a compact length space with a  finite measure such that $L^\sF$ has a discrete spectrum. Let $N>1$.

%{\color{red}

We assume $B$ is a  $1$-dimensional Riemannian manifold, $f: B\rightarrow [0,\infty)$ is smooth, and  $\partial B= f^{-1}(\{0\})$.

\begin{proposition}\label{prop:oneill}
We consider $u \in C^\infty_{c}(\mathring B)\otimes D_{\sW^{1,2}}(L^\sF)\subset D_{W^{1,2}}(L)$ and $\phi \in P_t^{\sB, \sN, \lambda} C_c^\infty(\mathring B)\otimes E(\lambda)$.
%such that  $\phi, L\phi\in L^\infty(\m^\sN)$. 
Then we have 
\begin{align}\label{id:formula}
\Gamma_2(u; \phi)
=& \int \Gamma_2^{\sB, \sN}(u; \phi) \dint \m_\sF + \int  \frac{1}{f^4} \Gamma_2^{\sF}(u;\phi) \dint \m_\sB^{\sN}\nonumber\\
&+\int\left[ 2\langle {\textstyle \frac{f'}{f}}, u'\rangle_\sB\frac{ \eL^\sF u}{f^2}  - \frac{f^\#}{f^2} | \nabla u|^2_{\sF}+2\left| \nabla \big({\textstyle \frac{u}{f}}\big)'\right|^2_{\sF}\right]
\phi \de\m^\sN
\end{align}
where $f^\#:=\frac{ \Delta^\sB f }{f}+ {(N-1)} \frac{|f'|_\sB^2}{f^2}$. 
\begin{remark} 
\hspace{0mm}
\begin{enumerate}\item $u'(r,x)=\frac{d}{dr} \big|_r u(\cdot,x)$ for $\m_\sF$-a.e. $x\in F$ and $\forall r\in B$, and $|\nabla u|_\sF(r,x)=|\nabla u(r, \cdot)|_\sF(x)$  $\forall r\in B$ and $\m_\sF$-a.e. $x\in F$. 
