\end{proof}
\begin{proposition}
Formula \eqref{id:formulav2} holds for $u+v=u_1\otimes u_2+ v_1\otimes v_2$ with  $v_1\otimes v_2 \in C_c^\infty(\mathring B) \otimes D_{W^{1,2}}(L^\sF)$, $$u_1\in \bigcup_{t>0} P_t^{\sB, \sN}C_{c}^\infty(\mathring B),$$ $u_2\equiv c\in \R$ and $\phi \in \Xi'$. 
%
%More precisely, $\Gamma_2(u+v;\phi)$ is well-defined and it holds
