=& \int \left[\Gamma_2^{\sB, \sN}(u; 1) +   \frac{1}{f^4} \Gamma_2^{\sF}(u;1)\right] d\m^{\sN}\nonumber\\
&+\int\left[ 2\langle {\textstyle \frac{f'}{f}}, u'\rangle_\sB\frac{ \eL^\sF u}{f^2}  - \frac{f^\#}{f^2} | \nabla u|^2_{\sF}+2\left| \nabla \big({\textstyle \frac{u}{f}}\big)'\right|^2_{\sF}\right] \de\m^\sN.
\end{align*}
\end{corollary}
\begin{proof}
We pick $\phi_n= \phi_{1,n}\otimes 1 \in P_t^{\sB, \sN} C_0^\infty(\mathring B)\otimes E(0)$ where $\phi_{1,n}= P_t^{\sB, \sN}\psi_n$ for a sequence  $(\psi_n)_{n\in \N}\subset  C^\infty_0(\mathring B)$   such that $\psi_n\uparrow 1$ pointwise $\m_\sB^\sN$-a.e. in $B$.  Then, $P_t^{\sB, \sN} \psi_n \uparrow 1$ for every $t>0$. 

Let $u$ be as in the assumptions. With $P_t(\psi_n \otimes 1)= (P_t^{\sB, \sN}\psi_n )\otimes 1= P_t^{\sB, \sN}\psi$ it follows that 
\begin{align*}\int |\nabla u|^2 L \left( P_t^{\sB, \sN} \psi_n \otimes 1 \right)\dint \m^\sN&= \int |\nabla u|^2 L P_t( \psi_n\otimes 1)\dint \m^\sN
\\
= \int L P_{t/2}|\nabla u|^2 P_{t/2}^{\sB, \sN} \psi_1 &\rightarrow \int LP_{t/2} |\nabla u|^2 \dint \m^\sN=0
\end{align*}
as well as 
\begin{align*} \int \langle \nabla u, \nabla Lu\rangle P^{\sB, \sN}_t\psi_n \dint\m^\sN &\rightarrow \int \langle \nabla u, \nabla Lu\rangle \dint\m^\sN.
\end{align*}
Similarly, one checks that 
\begin{align*}\int  |u'|_\sB^2L^{\sB, \sN} \phi_{1,n} \dint \m_\sB^\sN \rightarrow&\  0 \\ 
\int \langle u', (L^{\sB, \sN} u)'\rangle_\sB \phi_{1,n}\dint \m_\sB^\sN\rightarrow &\int  \langle u', (L^{\sB, \sN} u)'\rangle_\sB\dint \m_\sB^\sN\end{align*}
where these limits hold $\m_\sF$-almost everywhere in $F$. By Lebesgue's dominant convergence theorem it then follows
\begin{align*}
\int \int L^{\sB, \sN} \phi_{1,n} |u'|_\sB^2 \dint \m_\sB^\sN \dint \m_\sF \rightarrow&\  0 \\ 
\int \int \langle u', (L^{\sB, \sN} u)'\rangle_\sB \phi_{1,n}\dint \m_\sB^\sN\dint \m_\sF\rightarrow &\int  \Gamma_2^{\sB, \sN}(u; 1)\dint \m_\sF.
\end{align*}
On the other hand, we have that 
\begin{align*}\Gamma_2^{\sF}(u;\phi)= &\int |\nabla u|_\sF^2 L^\sF 1 \dint\m_\sF \phi_{1,n} - \int \langle \nabla u, \nabla (L^\sF u)\rangle_\sF \dint \m_\sF \phi_{1,n}\\
=&-\int \langle \nabla u, \nabla (L^\sF u)\rangle_\sF \dint \m_\sF \phi_{1,n}\rightarrow \Gamma_2^{\sF}(u;1)\end{align*}
Moreover $\left[ 2\langle {\textstyle \frac{f'}{f}}, u'\rangle_\sB\frac{ \eL^\sF u}{f^2}  - \frac{f^\#}{f^2} | \nabla u|^2_{\sF}+2\left| \nabla \big({\textstyle \frac{u}{f}}\big)'\right|^2_{\sF}\right]\phi_n = f_n$ is uniformily integrable w.r.t. $\m^\sN$. So 
$$\int f_n \dint\m^\sN\rightarrow\int \left[ 2\langle {\textstyle \frac{f'}{f}}, u'\rangle_\sB\frac{ \eL^\sF u}{f^2}  - \frac{f^\#}{f^2} | \nabla u|^2_{\sF}+2\left| \nabla \big({\textstyle \frac{u}{f}}\big)'\right|^2_{\sF}\right]\dint \m^\sN.$$

Hence, the desired formula follows from the formula in the previous corollary with $\phi=\phi_n$, and then letting $n$ go to $ \infty$. 
\end{proof}

\begin{corollary}\label{cor:formula}
We consider $u \in  \bigcup_{t>0} P_t^{\sB, \sN}C_{c}^\infty(\mathring B) +C^\infty_{c}(\mathring B)\otimes D_{\sW^{1,2}}(L^\sF)$, and $\phi \in \Xi'$. We set $\psi= \phi +\lambda$ for $\lambda \in\R$. 
%such that  $\phi, L\phi\in L^\infty(\m^\sN)$. 
Then we have 
\begin{align}\label{formula:important}
\Gamma_2(u; \psi)
=& \int \left[\Gamma_2^{\sB, f^\sN}(u; \psi) +   \frac{1}{f^4} \Gamma_2^{\sF}(u;\psi)\right] d\m^{\sN}\nonumber\\
&+\int\left[ 2\langle {\textstyle \frac{f'}{f}}, u'\rangle_\sB\frac{ \eL^\sF u}{f^2}  - \frac{f^\#}{f^2} | \nabla u|^2_{\sF}+2\left| \nabla \big({\textstyle \frac{u}{f}}\big)'\right|^2_{\sF}\right]
\psi \de\m^\sN
\end{align}
where $\Gamma_2(u; \psi):= \Gamma_2(u; \phi) + \lambda \Gamma_2(u; 1)$ and similarly for $\Gamma_2^{\sB, \sN}$ and $\Gamma_2^\sF$. 
\end{corollary}
\subsection{Spectral decomposition of $N$-warped products}\label{subsec:spectral}

In this subsection we assume that $F$ is a compact $\RCD(K_\sF(N-1),N)$ space where $N>1$ and $K_F\in \R$. In particular $\m_\sF$ is finite.
In particular, the operator $L^\sF$ has a discrete spectrum $\{\lambda_i\}_{i\in \N_0}$.

Let $E(\lambda_i)$ be the eigenspace for the eigenvalue $\lambda_i$. In particular, we have  the spectral decomposition
\begin{align*}
%&\bigoplus_{i=0}^\infty \left(E(\lambda_i) , \left\|\cdot \right\|_{L^2(\m_\sF)}\right) =\left\{ \sum_{i=0}^\infty v_i: \sum_{i=0}^\infty \left\|v_i\right\|_{L^2(\m_\sF)}<\infty\right\}= L^2(\m_\sF)\\
%&\bigoplus_{i=0}^\infty \left(E(\lambda_i) , \left\|\cdot \right\|_{W^{1,2}(F)}\right) =\left\{ \sum_{i=0}^\infty v_i: \sum_{i=0}^\infty \left\|v_i\right\|_{W^{1,2}(F)}<\infty\right\}= W^{1,2}(F)\\
&\bigoplus_{i=0}^\infty \left(E(\lambda_i) , \left\|\cdot \right\|_{D(L^\sF)}\right) =\left\{ \sum_{i=0}^\infty v_i: \sum_{i=0}^\infty \left\|v_i\right\|_{D(L^\sF)}<\infty\right\}= D(L^\sF).
\end{align*} 
We also define 
$$
\sum_{i=0}^\infty E(\lambda_i)= \left\{ \sum_{i=1}^k v_i : v_i\in E(\lambda_i) , k\in \N\right\}.
$$
\begin{proposition} Let $F$ be a compact metric measure space, and let $B$ and $f: B\rightarrow [0,\infty)$ be as before.   We assume that 
\begin{enumerate}
\item $f''+ Kf\leq 0$,  
\item $F$ satisfies the condition $\RCD(K_F(N-1), N)$ where 
$$K_F> \sup_B\{ (f')^2+ Kf^2\}.$$
\end{enumerate}
Then, for $u\in D_{W^{1,2}}(L)$ and $\psi= \phi+\lambda$ where $\phi \in \Xi'$ and $\lambda\in \R$ with $\psi\geq 0$, we have \begin{align}\label{ineq:bochner2}\Gamma_2(u;\psi)\geq {KN} \int |\nabla u|^2 \psi d\m^\sN + \frac{1}{N+1} \int \left( L u\right)^2 \psi d\m^\sN.
\end{align}
\end{proposition}
\begin{proof}  {\bf (1)} Assumption (1) yields that the mm space $(B, \m_\sB^\sN)$ satisfies the condition $\RCD(KN, N+1)$.


{\it Claim:}
\begin{align*}\Gamma_2(u;\psi)\geq {KN} \int |\nabla u|^2 \psi \dint \m^\sN + \frac{1}{N+1} \int \left( L u\right)^2 \psi \dint \m^\sN
\end{align*}
where $\psi$ is as in the assumptions and 
$u \in  \bigcup_{t>0} P_t^{\sB, \sN}C_{c}^\infty(\mathring B) +C^\infty_{c}(\mathring B)\otimes D_{\sW^{1,2}}(L^\sF)$.

{\it Proof of the Claim:}
The key steps  are the same as in the proof of Theorem 3.9 in \cite{ketterer2}. We indicate the main points of the proof. 

From formula \eqref{formula:important} in Corollary \ref{cor:formula} we get
\begin{align*}
\Gamma_2(u; \psi)
\geq& \int \left[\Gamma_2^{\sB, f^\sN}(u; \psi) +   \frac{1}{f^4} \Gamma_2^{\sF}(u;\psi)\right] \de \m^{\sN}\nonumber\\
&+\int\left[ 2\langle {\textstyle \frac{f'}{f}}, u'\rangle_\sB\frac{ \eL^\sF u}{f^2}  - \frac{f^\#}{f^2} | \nabla u|^2_{\sF}\right]
\psi \de\m^\sN
\end{align*}
 In combination with Corollary \ref{cor:bochnerext},  the $\RCD(K_F(N-1),N)$ condition for $F$, the properties of $f$ and since 
 $$f^\#=\frac{ \Delta^\sB f }{f}+ {(N-1)} \frac{| f'|_\sB}{f^2}$$
 it follows  that 
\begin{align*}
&\Gamma_2(u; \psi)\geq\\
& \int KN |u'|^2_\sB +  (\Delta^\sB u)^2+ \frac{1}{f^2} K N |\nabla u|_\sF^2 +\frac{1}{N} \left( N\langle {\textstyle \frac{f'}{f}}, u'\rangle_\sB+\frac{ \eL^\sF u}{f^2} \right)^2\de \m^\sN.
\end{align*}
Finally we use  $a^2 + \frac{1}{N} b^2= \frac{1}{N+1} (a+b)^2 + \frac{1}{(N+1)N} ( b- N a)^2$ to deduce the estimate in the claim. \hfill \qed
\smallskip
\\
{\bf (2)}
If $f^{-1}(\{0\})\neq \emptyset$, we have $K_F>\sup_B\{ (f')^2 + K f^2\}$. We can  rescale $f$ and $F$ such that $K_F>\sup_B\{(f')^2+ Kf^2\}=1$.

In particular, $F$ is  still an $\RCD(K_F(N-1), N)$ space with $K_F>0$. Then any eigenvalue $\lambda$ of $L^\sF$ satisfies \begin{center}$\lambda\geq K_F N> N\geq 1$\end{center} by the Lichnerowicz spectral estimate. 

{
Hence,  by Proposition \ref{prop:essential} we have  that
$$L^\sC u= L^{\sB,\sN, \lambda} u_1\otimes u_2, \ \ u_1\otimes u_2 =u \in C_c^\infty(\mathring B)\otimes E(\lambda)$$
is essentially self-adjoint for any positive eigenvalue $\lambda$ of $L^\sF$ --  independently of whether $f^{-1}(\{0\})$ is empty or not. }

Moreover 
$$L^\sC u= L^{\sB, \sN} u_1 \otimes u_2, \ \ u_1\otimes u_2 = u\in P_t^{\sB, \sN} C_c(\mathring B)\otimes E(0)$$
is essentially self-adjoint. 

Hence, the operator 
$$ u\in \bigcup_{t>0} P_t^{\sB, \sN}C_c(\mathring B)\otimes E(0) + \sum_{i=1}^\infty C_c^\infty(\mathring B)\otimes E(\lambda_i)=:\Xi\mapsto L^\sC u $$
is essentially self-adjoint.  

Hence, there is a unique self-adjoint extension  that must necessarily be the Laplace operator of the Cheeger energy associated to $B\times_f^\sN F$. In particular, $\Xi$ is dense in $D(L^\sC)$ w.r.t.  the operator norm. 
\smallskip\\
{\bf (3)} If we pick $u\in D_{W^{1,2}}(L)$ there exists a sequence $(u^n)_{n\in \N}$ in $\Xi$ such that $u_n\rightarrow u$ in $D_{L^2}(L)$.  Then 
\begin{align*}
\int | \nabla u_n|^2 L\phi d\m^\sN \rightarrow &\int | \nabla u|^2 L\phi d\m^\sN\\
\int |\nabla u|^2 \psi d\m^\sN \rightarrow& \int |\nabla u|^2 \psi \dint \m^\sN\\
\int L u_n \psi \dint \m^\sN \rightarrow& \int Lu \psi \dint \m^\sN.
\end{align*}
Here $\phi\in \Xi'$ and hence $\phi+ \lambda= \psi, L\phi \in L^\infty(\m^\sN)$.

We still have to show convergence of $\int \langle \nabla u_n, \nabla Lu_n\rangle \psi \dint \m^\sN$.  Since $u_n, Lu_n, \phi \in W^{1,2}(B\times_f^\sN F)$, we can apply the Leibniz rule. Hence 
\begin{align*}
\int \langle \nabla u_n, \nabla Lu_n\rangle \psi \dint\m^\sN&= \int \left[\langle \nabla u_n, \nabla (\psi Lu) \rangle -\langle \nabla u_n, \nabla \phi \rangle L u_n \right] \dint\m^\sN=(*).
\end{align*}
We have $\psi, |\nabla \psi|\in L^\infty(\m^\sN)$ since $\phi\in \Xi'$. Therefore
\begin{align*}
(*)&=- \int \psi (Lu_n)^2 \dint \m^\sN - \int \langle \nabla u_n, \nabla \phi\rangle Lu_n \dint \m^\sN.
\end{align*}
Now $\int \psi (Lu_n)^2 \dint \m^\sN\rightarrow \int\psi (Lu)^2 d\m^\sN$, and since $|\nabla\phi|\in L^\infty(\m^\sN)$, also
$$\int \langle \nabla u_n, \nabla \phi\rangle Lu_n \dint \m^\sN\rightarrow \int \langle \nabla u, \nabla \phi\rangle Lu \dint \m^\sN.$$
We obtain
$$\int \langle \nabla u_n, \nabla Lu_n\rangle \psi \dint \m^\sN\rightarrow \int \langle \nabla u, \nabla Lu\rangle \psi \dint \m^\sN.$$
This yields the desired inequality for $u\in D_{W^{1,2}}(L)$. 
%\medskip
%Finally we want  the inequality to  hold for any admissible test function $\phi\in D(L)$ with $\phi\geq 0$ and $\phi, L\phi\in L^\infty(\m^\sN)$. 
\end{proof}
\begin{theorem} Let $F$ be a metric measure space, and let $B$ and $f: B\rightarrow [0,\infty)$ be as before.   We assume that 
\begin{enumerate}
\item $f''+ Kf\leq 0$,  
\item $F$ satisfies the condition $\RCD(K_F(N-1), N)$ where 
$$K_F>  (f')^2+ Kf^2.$$
\end{enumerate}
For $u\in D_{W^{1,2}}(L)$ and $\phi \in D(L)$ with $\phi\geq 0$ and $\phi, L\phi\in L^\infty(\m^\sN)$, we have $$\Gamma_2(u;\phi)\geq {KN} \int |\nabla u|^2 \phi d\m^\sN + \frac{1}{N+1} \int \left( L u\right)^2 \phi d\m^\sN.$$
i.e. $\nwp$ satisfies the condition $\BE(K,N)$. 
\end{theorem}
\begin{proof}
{The  Cheeger energy on $B\times_f^\sN F$ is a strongly local, strongly regular Dirichlet form. Moreover
we  know that $B\times_f^\sN F$ satisfies 
\begin{itemize}
\item a local $(2,2)$-Poicar\'e inequality and 
\item a local volume doubling property
\end{itemize}
(Remark \ref{rem:feller}).}

In this situation, we have a Gaussian upper bound for the heat kernel and consequently the heat semi-group $P_t^\sC=P_t$ on $B\times_f^N F=C$ is $L^2-L^\infty$ ultra-contractive, i.e. $P_t^\sC: L^2(\m^\sN) \rightarrow L^\infty(\m^\sN)$ is a bounded operator. 

Let $\phi \in D(L)$ with $\phi\geq 0$ and $\phi, L\phi\in L^\infty(\m^\sN)$, and let $\phi_n\in \Xi'$ be a sequence that converges to $\phi$ in $D(L)$. By $L^2-L^\infty$ ultracontractivity we get that $P_t\phi_n$ as well as $LP_t\phi_n$ converge in $L^\infty(\m^\sN)$ to $P_t\phi$ and $LP_t\phi$ respectively. 

In particular, we have for $n\in \N$ sufficiently large, let's say $n\geq n_0$, that $P_t\phi_n, LP_t\phi_n\geq -\lambda$. Hence, $\psi_n=P_t \phi_n+\lambda\geq 0$ for $n\geq n_0$  and the formula \eqref{ineq:bochner2} from the previous corollary holds for $u\in D_{W^{1,2}}(L)$ and for $\psi$. 

The uniform convergence implies that the formula \eqref{ineq:bochner2} still holds with $P_t\phi+ \lambda$ in place of $P_t\phi_n+\lambda$.  We can send  first $\lambda$ to $0$ and the formula holds for $P_t\phi$. Then we can send $t$ to $0$ and in combination with the dominated convergence theorem we have that $P_t\phi$ and $LP_t\phi$ converge in weak-* sense to $\phi$ and $L\phi$. From this we obtain the desired estimate. 
\end{proof}

\begin{corollary} \label{main:smooth} Let $K\in \R$ and $N\in (1, \infty)$. Let $F$ be a mm space,  let $B$ be  a $1$-dimensional Riemannian manifold. Let $f: B\rightarrow [0,\infty)$  be smooth  such that $\partial B\subset f^{-1}(\{0\})$ and  $(\%)$ holds.   Assuming that 
\begin{enumerate}
\item $f''+ Kf\leq 0$,  
\item $F$ satisfies the condition $\RCD(K_F(N-1), N)$ where 
$$K_F\geq  (f')^2+ Kf^2,$$
\end{enumerate}
then $B\times_f^\sN F$ satisfies the condition $\RCD(KN, N+1)$. 
\end{corollary}

\begin{proof}{We first notice that, if $\partial B\neq 0$, then $K_F>0$. Then we first assume that $K_F>\sup_B\{(f')^2 + Kf^2\}$. 
\begin{enumerate}
\item Since $\nwp$ satisfies $\MCP$, an exponential growth condition holds by the Bishop-Gromov volume comparison theorem.
\item Since $\Ch^\snwp=\mathcal E^*$, $\nwp$ is infinitesimally Hilbertian. 
\item In step {\bf (1)} of  the proof for Proposition \ref{prop:distancewp} we showed that $\nwp$ satisfies the Sobolev-to-Lipschitz property. 
\item The previous theorem shows that the $\BE(KN,N+1)$ holds. 
\end{enumerate}
Thus $\nwp$ satisfies the conditin $\RCD(KN,N+1)$.}

Finally, if $K_F\geq \sup_B\{(f')^2 + K f^2\}$, we can rescale $F$  into $F'$ such that $F'$ satisfies $\RCD(K'_F(N-1), N)$ with $K_F'>\sup_B\{(f')^2 + Kf^2\}$.  The warped product $B\times^\sN_f F'$ satisfies $\RCD(KN, N+1)$ and converges in measured Gromov-Hausdorff sense to $B\times_f^\sN F$. Hence also the limit satisfies $\RCD(KN,N+1)$. 
\end{proof}
\subsection{Removing smoothness of $f$}
\begin{theorem} Let $K\in\R$ and $N\in (1, \infty)$.  Let $F$ be a mm space,  let $B$ be  a 1D Riemannian manifold, and  let $f: B\rightarrow [0,\infty)$  be Lipschitz continuous such that $\partial B\subset f^{-1}(\{0\})$ and one of the points in Assumption \ref{assumption:doubling2} holds.   We assume that 
\begin{enumerate}
\item $f''+ Kf\leq 0$,  
\item $F$ satisfies the condition $\RCD(K_F(N-1), N)$ where 
$$K_F\geq  (f')^2+ Kf^2.$$
\end{enumerate}
Then $B\times_f^\sN F$ satisfies the condition $\RCD(KN, N+1)$. 
\end{theorem}
\begin{proof} We will construct a sequence of intervals $B_i$ and smooth functions $f_i: B_i\rightarrow [0, \infty)$ respectively such that $\partial B_i\subset f^{-1}(\{0\})$, $(\%)$ holds and
\begin{enumerate}
\item $f_i''+ Kf_i\leq 0$,  
\item $F$ satisfies the condition $\RCD((K_F-\epsilon_i)(N-1), N)$ where 
$$K_F-\epsilon_i\geq  (f_i')^2+ Kf_i^2.$$
\end{enumerate}
Moreover, $B_i$ converges in the pointed Gromov-Hausdorff sense to $B$, and $f_i$ converges uniformly to $f$ on any compact subset of $B_i$. This will be done as follows.
\medskip


We will consider the following  cases separately. 
\begin{enumerate}
\item[\bf i.] $\partial B=\emptyset$: $B\simeq \R$,  or $B\simeq \mathbb S^1$ where $\mathbb S^1\simeq \R/{\textstyle (2\pi \Z)}$;
\item[\bf ii.] $\partial B\neq \emptyset$: $B\simeq [0, 2\pi]$, or $B\simeq [0, \infty)$. 
\end{enumerate}
We recall that   $\partial B\subset f^{-1}(\{0\})$ by assumption. 
\medskip\\
{\bf i.} By Corollary \ref{cor:special} we have that $K\leq  0$ and  $$K_F\geq   K \inf_B f^2 \mbox{ if and only if  }K_F\geq \sup_B\{ |f'|^2_\sB+ K f^2\}.$$
We choose  $\phi\in C_c^2((-1,1), [0, \infty))$ with $\int \phi(\tau) \de \tau=1$ and set $\phi_\epsilon(\tau)= \frac{1}{\epsilon} \phi( \frac{1}{\epsilon} \tau)$. Then we define
$$ 
s\in B\mapsto f_\epsilon(s) = \int_{-\epsilon}^\epsilon \phi_\epsilon(\tau) f(s+\tau) \dint \tau = \int_{-\epsilon}^\epsilon \phi_\epsilon(r-s) f(r) \dint r.$$ 
Then $f_\epsilon$ is $C^2$ and satisfies 
\begin{center}
$f_\epsilon'' + K f_\epsilon \leq 0$ on $B$. 
\end{center}
Therefore $f_\epsilon$ is $K f_\epsilon$-concave. Moreover $f_{\epsilon}$ converges uniformly to $f$ on any compact subset of $B$.

In the following we pick a sequence $\epsilon_n\downarrow 0$ and write $f_{\epsilon_n}= f_n$.
\smallskip\\
{\it Claim.} If $K_F\geq K \inf_B f^2$, then \begin{center}$\forall \epsilon>0$ $\exists n_\epsilon$:  $ (1+\epsilon) K\geq K\inf_B f^2_n$\  \ $\forall n\geq n_\epsilon$.\end{center}
\begin{proof}[Proof of the claim.]
We pick $s_0 \in B$ such that $I:=\inf_B f^2 \geq  f^2(s_0)- \frac{\epsilon}{2}I$. Then we choose $n_{0} \in \N$ such that $\forall n\geq n_0$ we have that \begin{center}$f^2(s_0)\geq f_n^2(s_0)-\frac{\epsilon}{2}I\geq \inf_B f_n^2- \frac{\epsilon}{2}I$.\end{center}
Hence $(1+\epsilon)\inf_B f^2 \geq \inf_B f^2_n$ for all $n\geq n_0\in \N$. \end{proof}


We rescale $\de_\sF$ with $\sqrt{(1+\epsilon)}\de_\sF= \de^\epsilon_F$. Then the  space $F^\epsilon=(F, \de^\epsilon_F, \m_\sF)$ satisfies $\RCD((1+\epsilon)K_\sF (N-1), N)$. 

Moreover, the points in Assumption \ref{assumption:doubling2} are preserved and therefore we still have $(\%)$. 



Hence, Corollary \ref{main:smooth} applies with $F^\epsilon$ and $f_{n}$ for $n\geq n_\epsilon$. It follows that $B\times_{f_n}^N F^\epsilon$ satisfies the condition $\RCD(KN, N+1)$. 
\smallskip\\
{\it Claim.} The $N$-warped product $B\times_{f_n}^N F^\epsilon$ converges in pointed measured GH sense to $B\times_f^N F^\epsilon$ as $n\rightarrow \infty$. 

\begin{proof}[Proof of the claim]
We consider a minimal geodesic $\gamma=(\alpha, \beta): [0, D] \rightarrow B\times_f F$ between points $p_0=(r_0, x_0)$ and $p_1=(r_1, x_1)$. Then, $\beta$ is a pregeodesic in $F$  between $x_0$ and $x_1$ by  (a) in Theorem \ref{th:albi0}. We set  $\de_\sF(x_0, x_1)=L(\beta)=:L$. Let $\varphi$ be an arc length reparametrization of $\beta$, i.e. $\beta\circ \varphi$ is parametrized by arc length. Then $\tilde \gamma=(\alpha, \varphi^{-1}): [0, D] \rightarrow $ is geodesic in $I\times_f [0,L]$ between $(r_0, 0)$ and $(r_1,L)$ by (b) in Theorem \ref{th:albi0}. 
Here $I\times_f[0, L]$ is  a $C^0$ warped product, i.e.  $I\times [0, L]$ equipped with the $C^0$ Riemannian metric $g_\sB+ f^2 (dr)^2$. Since $f$ is semi-concave, $B\times_f[0,L]$ has locally Alexandrov curvature bounded from below (Theorem \ref{th:albi1}). In particular, $\tilde \gamma|_{[\epsilon, D-\epsilon]}=\tilde \gamma^\epsilon$ is the unique, up to reparametrization, minimizer between its endpoints for all $\epsilon>0$. Let us denote the endpoints of $\tilde \gamma^\epsilon$ with $\tilde p_0^\epsilon=(r_0^\epsilon, x_0^\epsilon)$ and $\tilde p^\epsilon_1=(r_1^\epsilon, x_1^\epsilon)$. 

Since $f_n\rightarrow f$ locally uniformly, it follows that 
$$ g_\sB + f_n^2 (dr)^2 \ \rightarrow g_\sB+ f^2 (d r)^2 \mbox{ locally uniformly on } B\times [0, L].$$
We can consider geodesics $\tilde \gamma^\epsilon_n$ in $B\times_{f_n}[0,L]$ between $\tilde p_0^\epsilon$ and $\tilde p_1^\epsilon$.  After extracting a subsequence $\tilde \gamma_n^\epsilon$ will converge uniformily to  a minimal geodesic that must be $\tilde \gamma^\epsilon$ by uniqueness. Moreover, by a diagonal argument we find a sequence of geodesics $\tilde \gamma_n=( \alpha_n, \psi_n): [\epsilon_n, D-\epsilon_n] \rightarrow B\times_{f_n}[0,L]$ (with endpoints $p_0^n=(r_0^n, x_0^n)$ and $p_1^n=(r_1^n, x_1^n)$) that converges to $\tilde \gamma$ and $\epsilon(n)\downarrow 0$ as $n\rightarrow \infty$.  Moreover,  it also holds that  $x_0^n\downarrow 0$ and $x_1^n\uparrow L$.  Hence, given $\delta>0$ there exists $n_\delta\in \N$ that only depends $r_0, r_1$ and $L$ such that
 \begin{align}\label{est:unif}\mbox{$|L(\tilde \gamma_n)- L(\tilde \gamma)|= \left| |p_0^n- p_1^n|- |p_0-p_1|\right|\leq \epsilon$ $\forall n\geq n_\delta$. }
\end{align}
$\psi_n: [\epsilon_n, D-\epsilon_n] \rightarrow [0, L]$ is a minimal geodesic between $x_0^n, x_1^n \in [0,L]$.
\smallskip

Then, it follows that $(\alpha_n, \beta\circ \varphi \circ\psi_n)= \gamma_n: [\epsilon_n, D-\epsilon_n] \rightarrow B\times_{f_n} F$ is a minimal geodesic in $B\times_{f_n} F$, again by (b) in Theorem \ref{th:albi0}. 
%Moreover,  $\gamma_n$ converges uniformily to $\gamma$ in $B\times_f F$. 
 The uniform estimate \eqref{est:unif} then also holds for the endpoints  $p_0^n, p_1^n, p_0, p_1$ of the geodesic $\gamma_n$ and $\gamma$. In particular, this estimate only depends on $r_0, r_1$ and $L$.

Hence, on a compact ball in $B\times_f F$ the assignment $|p_0,p_1| \mapsto |p_0^n, p_1^n|$ is a correspondence (compare with \cite{bbi}) whose distortion is bounded by a constant that gets small as $n\rightarrow \infty$.
We infer that $B\times_{f_n}F$ converges in pointed GH sense to $B\times_f F$. 

Finally, since $f_n$ converges locally uniformly to $f$, clearly $ f_n^N(r) \de r\otimes \de \m_\sF$ converges weakly to $f^N(r) \de r \otimes \de \m_\sF$. 
\end{proof}
Since $B\times_f F^\epsilon$ is the pointed measured GH limit of $\RCD(KN, N+1)$ spaces it satisfies the same condition itself.  Finally, if $\epsilon \downarrow 0$, it follows easyly that $B\times_f F^\epsilon$ converges in measured GH sense to $B\times_f F$ that therefore also also satisfies the condition $\RCD(KN, N+1)$. 
\medskip\\
{\bf ii.}  Since $\partial B\neq \emptyset $, by Corollary \ref{cor:special} we have
$$\sup_{\partial B}|Df|_\sB^2= \sup_B\{ |Df|^2_\sB+ K f^2\}>0.$$
Here $Df=\max\left\{ f^+, -f^-\right\}$ is  the {\it Alexandrov derivative}  where $\frac{d^+ f}{ds}=f^+$ and $\frac{d^- f}{ds}=f^-$ are the right and the left derivatives of $f$. $f^\pm$ exist everywhere because $f$ is semi-concave. $Df$ coincides a.e. with the usual derivative $f'$ that is defined a.e.

There are at most 2 boundary components $\alpha$ and $\omega$. $\alpha$ denotes the boundary  on the left end of the interval $B$, and $\omega$ the boundary  on the right end. We consider $B$ equipped with the standard orientation. 

W.l.o.g. we will assume that $B$ has exactly one boundary component $\alpha$. The other case works similarly.  W.l.o.g. we also assume that $\alpha=0$. Hence $B\simeq [0, \infty)$ and $f'= f^+$ in $0.$

We define $[ \epsilon, \infty)=: B^{\epsilon}$ and $f_{\epsilon}$  as above is  clearly well-defined for $s\in B^\epsilon$. We also set $f_n= f_{\epsilon_n}$ for $\epsilon_n\downarrow 0$ as $n\in \N\rightarrow \infty$. 

Semi-concavity of $f$ implies the following. The left and the right derivative, $f^+$ and $f^-$, are continuous from the left and from the right, respectively.  We also  recall that $f^-\geq f^+$ and $f^+=f^-$ a.e. 

We note that $f^+(\alpha)>0$ since $f$ is semi-concave and positive away from $\alpha$.

Let $\eta\in (0,\frac{1}{4} f^+(0))$. Then there exists  $\epsilon_\eta>0$ such that  $f(s)\leq\frac{1}{2} \eta$ and $0<f^+(0)-\eta\leq f^+(s)\leq  K_F(1+ \eta)$  for  $s\in (0, 2\epsilon_\eta)$. 
\smallskip\\
{\it Claim.}
It holds 
$$|f_n'|(s)\rightarrow |f'|(s) $$ 
%$$\limsup_{\epsilon \rightarrow 0} \sup_{I_\epsilon} \{\pm |h'_\epsilon|^2 + \kappa h_\epsilon^2 \}\leq \sup_{I}\{\pm |h'|^2 + \kappa h_\epsilon^2\}$$
for every $s\in B\backslash \partial B=: \mathring B$ such that $f'(s)$ exists. 
\begin{proof} 
From the uniform convergence of $f_n$ to $f$ and since both $f$ and $f_n$ are  semi-concave, one has
$$\liminf_{n \rightarrow \infty} |f'_n|(s)=\liminf_{n \rightarrow \infty} |Df_n|(s)\geq |Df|(s) \ \ \forall s \in \mathring B.$$
Moreover, it holds
$$f'_\epsilon(s)= \int_{-\epsilon}^\epsilon \phi_\epsilon(\tau) f'(s+ \tau) \de \tau.$$
Hence 
$$|f'_\epsilon(s)|\leq \int_{-\epsilon}^\epsilon \phi_\epsilon(\tau) |f'(\tau + s)| \de \tau=: (|f'|)_\epsilon(s).$$
The left hand side $(|f'|)_\epsilon(s)$  converges pointwise to $|f'|(s)$  as $\epsilon \rightarrow 0$ for $s\in \mathring B$ whenever $f'(s)$ exists. 
Hence 
$$\limsup |f'_n|(s)\leq \lim_{n\rightarrow \infty} (|f'|)_n(s) = |f'|(s) \mbox{ for a.e. $s\in B$.}$$
This proves the claim. 
\end{proof}

We choose $\epsilon\in (0, \epsilon_\eta)$ such that $f'(\epsilon)$ exists,  $f_n(\epsilon)\leq \eta$ and 
\begin{center} $\frac{1}{2} f^+(0)<f^+(0)-2\eta\leq f'(\epsilon)-\eta\leq f'_n(\epsilon)\leq  f'(\epsilon)(1+\eta)\leq K_F(1+p(\eta))$\end{center}
where $p(\eta)$ is a function s.t.  $p(\eta)\rightarrow 0$ for $\eta\downarrow 0$.

Moreover, let $n_0\in \N$ such that $\epsilon_n\in (0, \epsilon)$ for all $n\geq n_0$ and
\smallskip
%We consider the case $K\geq 0$ and $K\leq 0$ seperately. 
\smallskip

%$K\geq 0$: 
We choose $\bar g: [0, \infty)\rightarrow [0, \infty)$ such that $\bar g''- \frac{f''_n(\epsilon)}{f_n{\epsilon}} \bar g=0$ and $\bar g(0)= f_n(\epsilon)$, $\bar g'(0)= -f_n'(\epsilon)$.  We set $-\frac{f''_n(\epsilon)}{f_n(\epsilon)}=: K(\epsilon)\geq K$. Thus $\bar g''+K\bar g\leq 0$. Then, more precisely, we have
$$\bar g(s)= f_n(\epsilon)\cos_{K(\epsilon)}- f'_n(\epsilon) \frac{1}{\sqrt{ K(\epsilon)}} \sin_{K(\epsilon)}(s)$$
where $\cos_{K(\epsilon)}$ and $\sin_{K(\epsilon)}$ are solutions of $u'' + K(\epsilon) u=0$ with initial conditions $u(0)=1, u'(0)=0$ and $u(0)=0, u'(0)=1$, respectively.

There exists a constant $C_{K, K_F}(\eta)\in (0, \infty)$ such that $t_0=\inf \{t>0: \bar g(t)=0\}\leq C_{K,K_F}(\eta)$ and $C_{K, K_F}(\eta)\rightarrow 0$ if $\eta\rightarrow 0$. 

Moreover $$\bar g'(t_0)\geq - f_n'(\epsilon)(1+\delta(\eta))\geq - K_F(1+p(\eta))(1+\delta(\eta))=:-K_F^\eta.$$

We set $\bar g(-t + \epsilon)= g(t)$. Then $g$ satisfies $g(\epsilon)=f_n(\epsilon)$, $g'(\epsilon)=f_n'(\epsilon)$,  $g''(\epsilon)=-K(\epsilon)g_n(\epsilon)=  f_n''(\epsilon)$ and $g_\epsilon'(\epsilon -t_0)\leq K_\sF^\eta$.
We set 
$$h_\epsilon(s)= \begin{cases} f_\epsilon(s)& s\in ( \epsilon, \infty) \\
g(s)& s\in  [\epsilon -t_0,  \epsilon].
\end{cases}
$$
Therefore $h_\epsilon$ is $C^2$ by construction and satisfies 
\begin{enumerate}
\item $h_n'' + K h_n\leq 0, $
\item $h'_n(\alpha+\epsilon -t_0) \leq K_F^\eta.$
\item $h_n: [\alpha+\epsilon - t_0, \infty)\rightarrow [0, \infty)$ converges  locally uniformly to $f:[\alpha, \infty)\rightarrow [0, \infty)$. 
\end{enumerate}
{\it Claim.} The $N$-warped product $B\times_{f_n}^N F^\epsilon$ converges in pointed measured GH sense to $B\times_f^N F^\epsilon$ as $n\rightarrow \infty$. 

We can prove this claim  similarly as in {\bf i.}  We omit details but recall the following fact for a geodesic $\gamma=(\alpha, \beta)$ in $B\times_f F$. If $\alpha$ does not intersect $\partial B$ we can proceed as before. If $\gamma$ does intersect $\partial B$, then $\gamma$ is a cancatenation of segments in $B$. This type of geodesic is clearly the limit of geodesics in $B\times_{f_n} F$. 
\end{proof}
\begin{theorem} Let $K\in \R$ and $N\in (1, \infty)$.  Let $F$ be a mm space,  let $B$ be  a $1$-dimensional Riemannian manifold, and  let $f: B\rightarrow [0,\infty)$  be Lipschitz continuous such that $(\dagger)$ holds.   It holds $(\%)$. We assume that 
\begin{enumerate}
\item $f''+ Kf\leq 0$,  
\item $F$ satisfies the condition $\RCD(K_F(N-1), N)$ where 
$$K_F\geq  (f')^2+ Kf^2.$$
\end{enumerate}
Then $B\times_f^\sN F$ satisfies the condition $\RCD(KN, N+1)$. 
\smallskip\\
$(\dagger)$ If $B^\dagger$ is the result of gluing two copies of $B$ together along the boundary component $\partial B\backslash f^{-1}(\{0\})$, and $f^\dagger: B^\dagger \rightarrow [0,\infty)$ is the tautological extension of $f$ to $B^\dagger$, then $(f^\dagger)''+ K f^\dagger\leq 0$ is satisfied on $B^\dagger$. 
\end{theorem}
\begin{proof} We observe that $\partial B^\dagger\subset (f^\dagger)^{-1}(\{0\})$.
Hence, we can apply the previous theorem with $B^\dagger$ and $f^\dagger$ in place of $B$ and $f$ respectively.  We obtain that $B^\dagger\times_{f^\dagger}^\sN F$ satisfies the condition $\RCD(KN,N+1)$. 
\smallskip\\
{\it Claim.} $B\times_f F$ is a geodesically convex subset of $B^\dagger\times_{f^\dagger} F=C^\dagger$. 

Let $\gamma=(\alpha, \beta): [0,1] \rightarrow C^\dagger$ be geodesic such that $\gamma(0), \gamma(L)\in C$. Let $\phi: [0,L]\rightarrow [0,1]$ be a $1$-speed reparametrization of $\beta$. We set $\psi= \phi^{-1}$. 
The warped products $B\times_f [0,L]$ is a geodesically convex subset of   $B^\dagger\times_{f^\dagger}[0,L]$. 
By fiber independence the curve $(\alpha, \psi)$ is a minimal geodesic in $B^\dagger\times_{f^\dagger}[0,L]$ with endpoints in $B\times_f[0,L]$. Since $B\times_f [0,L]$ is geodesically convex, we have $\alpha:[0,1]\rightarrow B$. It follows that $\Im\gamma\subset C$. 
\smallskip

Since $C$ is a geodesically convex subset of $C^\dagger$, we have that the condition $\RCD(KN, N+1)$ for $B\times_f^\sN F$ follows from the corresponding condition for $B^\dagger\times_{f^\dagger}^\sN F$. 
\end{proof}
\begin{proof}[End of the proof of Theorem \ref{maintheorem1}] {
Let us first assume $N=1$. The $\RCD(0,1)$ condition for $F$ yields that $F$ is isometric to  $[0, L]$ or to $\alpha\mathbb S^1$. Then  result follows from Theorem \ref{th:albi1} in combination with \cite{lytchakstadler}.}

  Hence we can assume $N>1$. We  have already finished the proof under the assumption $(\%)$.


Therefore we   have to remove the assumption $(\%)$. The  only case that we have to consider is when $f$ is not bounded. 

In this case, we can find sequences $r^{\pm}_n=r^\pm\rightarrow \pm \infty$ such that $f^-(r^+)\leq  0$ and $f^+(r^-)\leq 0$. Hence $B^r=[r^-, r^+]$ and $f|_{[r^-, r^+]}$ satisfy $(\dagger)$.  Thus $B^r\times _f F$ satisfies the condition $\RCD(KN, N+1)$. 

If we choose a point $p=(r,x)\in \nwp$ and a bounded neighborhood $U$ of $p$ in $\nwp$, then there exsits $n\in \N$ large enough such that $U$ isometrically embeds into $B^r\times_f^N F$. 

Now, since $B^r\times^N_f F$ satisfies $\RCD(KN, N+1)$ and since $p$ and $U$ in $\nwp$ are arbitrary, $\nwp$ satisfies the condition $\CD(KN, N+1)$ locally  in the sense of \cite{stugeo2}. Since $\nwp$ is nonbranching, it therefore satisfies the condition $\CD(KN,N+1)$ globally by \cite{cavmil}. Moreover, by construction and since $F$ is $\RCD$, $\m^\sN$-a.e. point in $\nwp$ admits a Euclidean tangent cone. Hence, it follows from \cite{Kap-Ket-18} that $\nwp$ is $\RCD(KN, N+1)$.

This finishes the proof of Theorem \ref{maintheorem1}. \end{proof}


