In brief, Algor. \ref{Monte Carlo Simulation} illustrates the Monte Carlo process for the complex network modeling based on the game between individuals with Q-learning in reinforcement learning. It is important to note that, at each discrete time step, all individuals first move synchronously and then play the snowdrift game with their neighbors in the updated network structure. Following this, the Q-table and strategy of each individual are updated synchronously.

\begin{algorithm}[htp]
\caption{\textbf{Monte Carlo Simulation}}
\label{Monte Carlo Simulation}
\begin{algorithmic}[1]
\State \textbf{Initialize} the current time $t_{now}=0$, the update time $t_{update}=0$, the weights among individuals $weight$, the network structure $\mathcal{G}$, each individual's state $S$, action $a$, utility table $Q(S, a)$, strategy $s$, and payoff $U$. %\# It includes the current time $t_{now}$, the updating time $t_{update}$, weight between individuals $weight$, individual's state $S$, action $a$, utility table $Q(S, a)$, strategy $s$, and payoff $U$
\State \textbf{Initialize} the death time of each individual and the birth time of the next individual.
    \While {$t_{now}< MC_{step}$}
		\While {$t_{update}< t_{now}$}
            \For {each individual $x$}
                \State Choose action $a$ from $Q$-table based on \indent \indent \hspace{0.1cm} $\epsilon$-greedy policy.
                \State Take action $a$ and observe the new state $S'$.
            \EndFor
            \State Update the weights among individuals $weight$ \indent \hspace{0.25cm} and obtain a new network structure $\mathcal{G}$.
            \State Calculate each individual's payoff $U$ based on the \indent \hspace{0.25cm} game interactions.
            \For {each individual $x$}
                \State Update $Q(S, a)$: $Q(S, a) \leftarrow Q(S, a) + \eta[R + \indent \indent \hspace{0.2cm} \gamma \max_{a'} Q(S', a') - Q(S, a)]$.
                \State Randomly select a neighbor $y$ and generate a \indent \hspace{0.75cm} random number $p$ between 0 and 1.
                \If {$p < P(s_{x} \leftarrow s_{y})$}
                    \State Update strategy: $s_{x} \leftarrow s_{y}$.
                \EndIf
            \EndFor
        \State Increase update time: $t_{update}\leftarrow t_{update}+1$.
        \EndWhile
    \State Determine the time $t_{death}$ of the first individual to \indent \hspace{-0.25cm} die and the time $t_{birth}$ when the next individual $j$ is \indent \hspace{-0.2cm} born into the system.
    \If{$t_{birth} < t_{death}$}
        \State Update current time: $t_{now} \leftarrow t_{birth}$.
        \State Determine the death time of individual $j$ and the \indent \hspace{0.25cm} birth time of the subsequent new individual.
        \State Update the weights among individuals $weight$ \indent \hspace{0.25cm} and the network structure $\mathcal{G}$.
    \Else
        \State Update current time: $t_{now} \leftarrow t_{death}$.
        \State Update the weights among individuals $weight$ \indent \hspace{0.25cm} and the network structure $\mathcal{G}$.
    \EndIf
\EndWhile
\end{algorithmic}
\end{algorithm}

