See Appendix A. %\ref{app:appA}.
\end{IEEEproof}


Lemma \ref{prop:prop1} reveals that the LLMO with the BPE tokenizer operates in the finite language space $\mathbb{S}$ in \eqref{eq:S}. This means that any action population $\mathbf{X}^{(t)}$ as well as in-context examples $\mathbf{X}^{(t)}_{\sf{ex}}$ can be interpreted as a discrete representation within $\mathbb{S}$. Deriving $\mathbb{S}$ for other tokenizers is not straightforward. In this case, the vocabulary set $\mathbb{T}$ might contain additional tokens, which potentially increase the number of tokens $N_{\sf{token}}$. Nevertheless, the cardinality $|\mathbb{T}|$ and $N_{\sf{token}}$ are finite numbers, indicating that the LLMO realized with arbitrary tokenizers still relies on a finite language space $\mathbb{S}$. Therefore, our subsequent analysis holds for diverse types of LLMs and tokenizers.

Based on these results, we can model the LLMO, including the LLM inference $\mathcal{L}(\cdot)$ in \eqref{eq:LLM2} and the sampling operator $\mathcal{S}(\cdot)$ in \eqref{eq:sampler}, as a finite-state Markov chain as follows.

\begin{theorem}\label{prop:prop3}
    %Suppose that Assumptions \ref{amp:amp1} and \ref{amp:amp2} hold. 
    The LLMO forms the Markov chain as
    \begin{align}\label{eq:markov}
        \mathbf{X}^{(0)}_{\sf{ex}}\rightarrow\mathbf{X}^{(1)}_{\sf{ex}}\rightarrow\cdots\rightarrow\mathbf{X}^{(T)}_{\sf{ex}},
    \end{align}
    where $T$ stands for the maximum iteration number of Algorithm \ref{alg:alg1} and $\mathcal{T}_{\sf{BPE}}(\mathbf{X}^{(t)}_{\sf{ex}})\in\mathbb{S}$. The transition probability $\Pr\{\mathbf{X}^{(t)}_{\sf{ex}}|\mathbf{X}^{(t-1)}_{\sf{ex}}\}$ is computed by
        \begin{align}\label{eq:trans_prob}
        \Pr\{\mathbf{X}^{(t)}_{\sf{ex}}&|\mathbf{X}^{(t-1)}_{\sf{ex}}\}=\!\!\!\!\!\!\!\!\!\sum_{\mathcal{T}_{\sf{BPE}}(\mathbf{X}^{(t)})\in\mathbb{S}}\!\!\!\!\Big(p_{\mathcal{S}}(\mathbf{X}^{(t)}_{\sf{ex}}|\mathbf{X}^{(t)},\mathbf{X}^{(t-1)}_{\sf{ex}})\\
    &\times p_{\mathcal{L}}(\mathcal{T}_{\sf{BPE}}(\mathbf{X}^{(t)})|\mathcal{T}_{\sf{BPE}}(\mathbf{X}^{(t-1)}_{\sf{ex}}),\mathcal{T}_{\sf{BPE}}(\mathbf{r}^{(t-1)}_{\sf{ex}}),\mathbf{z}_{\sf{fix}})\Big),\nonumber
    \end{align}
    where $p_{\mathcal{S}}(\cdot|\cdot)$ accounts for the transition probability of the sampling operator $\mathcal{S}(\cdot)$ in \eqref{eq:sampler} and $\mathbf{z}_{\sf{fix}}$ is the fixed token vector of $\sf{pmpt}^{(t-1)}$ excluding the in-context example part.
\end{theorem}
\begin{IEEEproof}
See Appendix B. % \ref{app:appC}
\end{IEEEproof}

Theorem \ref{prop:prop3} states that the action population matrices of the in-context examples $\mathbf{X}_{\sf{ex}}^{(t)}$ form a Markov chain within the finite language space $\mathcal{T}_{\sf{BPE}}(\mathbf{X}_{\sf{ex}}^{(t)})\in\mathbb{S}$. 
%Since it is not difficult to see from Algorithm \ref{alg:alg1} that the Markov chain $\mathbf{X}_{\sf{ex}}^{(t-1)}\rightarrow\mathbf{X}^{(t)}\rightarrow\mathbf{X}^{(t)}_{\sf{ex}}$ holds in general.
The transition probability in \eqref{eq:trans_prob} captures the effects of both the sampling operator $\mathcal{S}(\cdot)$ and the random token sampling in \eqref{eq:topk}. Thus, our analysis explicitly involves unpredictable LLM responses including the hallucination issue. Notice that the result in \eqref{eq:trans_prob} is valid for any stochastic sampling operators $p_{\mathcal{S}}(\mathbf{X}^{(t)}_{\sf{ex}}|\mathbf{X}^{(t)},\mathbf{X}^{(t-1)}_{\sf{ex}})$.

Since the LLMO continually updates the best action $\mathbf{x}_{\sf{best}}^{(t)}$ based on $\mathbf{X}^{(t)}_{\sf{ex}}$, it suffices to prove the optimality of the LLMO through the Markov chain in \eqref{eq:markov}. In the following, we will show that the LLMO with the elitist sampler converges to the optimal action. This provides the theoretical foundations for existing works \cite{OPRO,BHuang:24,LMEA,GD,LEO,ANie:23,HLee:24a,HLee:24b,MALLM,MALLM2,HLi:24,KQiu:24,JTong:24,MOEAD}.

\subsection{Convergence analysis} \label{sec:sec3c}


To proceed with the convergence analysis, we introduce essential definitions in the following.
\begin{definition}\label{def:def1}
A token vector $\mathcal{T}_{\sf{BPE}}(\mathbf{X}_{\sf{ex}}^{(t)})$ of the in-context examples $\mathbf{X}_{\sf{ex}}^{(t)}$ is represented as a state $s^{(t)}\triangleq\mathcal{T}_{\sf{BPE}}(\mathbf{X}_{\sf{ex}}^{(t)})$ in the finite state space $s^{(t)}\in\mathbb{S}$.
Conversely, the in-context examples are retrieved through the decoding process as $\mathbf{X}_{\sf{ex}}^{(t)}=\mathcal{T}_{\sf{BPE}}^{-1}(s^{(t)})$.
\end{definition}
\begin{definition}\label{def:def3}
A state $s^{(t)}\in\mathbb{S}$ is said to be an optimal state if the associated action population $\mathbf{X}_{\sf{ex}}^{(t)}$ contains at least one globally optimal action to the problem in \eqref{eq:P}.
\end{definition}
\begin{definition}\label{def:def4}
The optimal state set $\mathbb{S}^{\star}\subset\mathbb{S}$ is defined as a set of all optimal states. Also, $\mathbb{S}^{\prime}=\mathbb{S}\setminus\mathbb{S}^{\star}$ denotes the set of non-optimal states.
\end{definition}
\begin{definition}\label{def:def5}
An inequality $s\succ\tilde{s}$ defines the ordering between two states $s,\tilde{s}\in\mathbb{S}$ if the maximum reward among $P$ actions in $\mathcal{T}_{\sf{BPE}}^{-1}(s)$ is greater than that of $\mathcal{T}_{\sf{BPE}}^{-1}(\tilde{s})$. If they have the same maximum reward, we proceed by comparing the next largest rewards. Two states are said to be equivalent, i.e., $s= \tilde{s}$, if all rewards are identical.
\end{definition}
\begin{definition}\label{def:def7}
Without loss of generality, states are assumed to be sorted in descending order in $\mathbb{S}=\{s_{1},s_{2},\cdots,s_{|\mathbb{S}|}\}$ such that $s_{1}\succeq s_{2}\cdots\succeq s_{|\mathbb{S}|}$. Thus, the first $|\mathbb{S}^{\star}|$ states $s_{1},\cdots,s_{|\mathbb{S}^{\star}|}$ correspond to the optimal states, while the remaining $|\mathbb{S}^{\prime}|=|\mathbb{S}|-|\mathbb{S}^{\star}|$ states belong to the non-optimal states.
\end{definition}


