\section{Proof of Theorem \ref{prop:prop3}} \label{app:appC}

Let $\mathbf{X}_{\sf{ex}}^{(1:t-1)}\triangleq\{\mathbf{X}_{\sf{ex}}^{(\tau)}:\forall \tau=0,1,\cdots,t-1\}$ be the set of past in-context examples. To prove Theorem \ref{prop:prop3}, it suffices to show that the current in-context examples $\mathbf{X}_{\sf{ex}}^{(t)}$ depend only on $\mathbf{X}_{\sf{ex}}^{(t-1)}$ but not its entire history $\mathbf{X}_{\sf{ex}}^{(1:t-1)}$ as
\begin{align}
    \Pr\{\mathbf{X}_{\sf{ex}}^{(t)}|\mathbf{X}_{\sf{ex}}^{(1:t-1)}\}=\Pr\{\mathbf{X}_{\sf{ex}}^{(t)}|\mathbf{X}_{\sf{ex}}^{(t-1)}\}. \label{eq:pXex}
\end{align}
We begin by expanding $\Pr\{\mathbf{X}_{\sf{ex}}^{(t)}|\mathbf{X}_{\sf{ex}}^{(1:t-1)}\}$ as
\begin{subequations}\label{eq:pspl}
\begin{align}
    &\Pr\{\mathbf{X}_{\sf{ex}}^{(t)}|\mathbf{X}_{\sf{ex}}^{(1:t-1)}\}=\!\!\!\!\!\!\sum_{\mathcal{T}_{\sf{BPE}}(\mathbf{X}^{(t)})\in\mathbb{S}}\!\!\!\!\!\!\!\!\!\Pr\{\mathbf{X}^{(t)}_{\sf{ex}},\mathbf{X}^{(t)}|\mathbf{X}^{(1:t-1)}_{\sf{ex}}\}\\
    &=\!\!\!\!\!\!\sum_{\mathcal{T}_{\sf{BPE}}(\mathbf{X}^{(t)})\in\mathbb{S}}\!\!\!\!\!\!\!\!\!\Pr\{\mathbf{X}^{(t)}_{\sf{ex}}|\mathbf{X}^{(t)},\mathbf{X}^{(1:t-1)}_{\sf{ex}}\}\Pr\{\mathbf{X}^{(t)}|\mathbf{X}^{(1:t-1)}_{\sf{ex}}\}, \label{eq:psplc}
\end{align}
\end{subequations}
where the summations are taken over all possible tokens $\mathcal{T}_{\sf{BPE}}(\mathbf{X}^{(t)})\in\mathbb{S}$. In what follows, we show that two conditional distributions $\Pr\{\mathbf{X}^{(t)}_{\sf{ex}}|\mathbf{X}^{(t)},\mathbf{X}_{\sf{ex}}^{(1:t-1)}\}$ and $\Pr\{\mathbf{X}^{(t)}|\mathbf{X}_{\sf{ex}}^{(1:t-1)}\}$ in \eqref{eq:psplc} can be written as
\begin{subequations}\label{eq:p_ind}
\begin{align}
    &\Pr\{\mathbf{X}_{\sf{ex}}^{(t)}|\mathbf{X}^{(t)},\mathbf{X}_{\sf{ex}}^{(1:t-1)}\}=p_{\mathcal{S}}(\mathbf{X}^{(t)}_{\sf{ex}}|\mathbf{X}^{(t)},\mathbf{X}^{(t-1)}_{\sf{ex}}),\label{eq:psam}\\
    &\Pr\{\mathbf{X}^{(t)}|\mathbf{X}_{\sf{ex}}^{(1:t-1)}\}\nonumber\\
    &=p_{\mathcal{L}}(\mathcal{T}_{\sf{BPE}}(\mathbf{X}^{(t)})|\mathcal{T}_{\sf{BPE}}(\mathbf{X}_{\sf{ex}}^{(t-1)}),\mathcal{T}_{\sf{BPE}}(\mathbf{r}^{(t-1)}_{\sf{ex}}),\mathbf{z}_{\sf{fix}}),\label{eq:pL}
\end{align}
\end{subequations}
where $p_{\mathcal{S}}(\cdot|\cdot)$ stands for the transition probability of the sampling operator $\mathcal{S}(\cdot)$ in \eqref{eq:sampler} and $p_{\mathcal{L}}(\cdot|\cdot)$ equals the pretrained token distribution of the LLM given in \eqref{eq:zout}. With \eqref{eq:p_ind}, we readily obtain \eqref{eq:pXex}, leading to the Markov property in \eqref{eq:markov}.

We first consider the distribution $\Pr\{\mathbf{X}_{\sf{ex}}^{(t)}|\mathbf{X}^{(t)},\mathbf{X}_{\sf{ex}}^{(1:t-1)}\}$ in \eqref{eq:psam} which describes the probability of generating the in-context examples $\mathbf{X}_{\sf{ex}}^{(t)}$. In the LLMO framework, such an operation is governed by the sampling operator $\mathcal{S}(\cdot)$. At the $(t+1)$-th iteration of Algorithm \ref{alg:alg1}, $\mathbf{X}_{\sf{ex}}^{(t)}$ is drawn from the memory $\mathbb{M}^{(t)}$. As shown in \eqref{eq:memory}, it consists of previous in-context examples $\mathbf{X}^{(t-1)}_{\sf{ex}}$ and decisions of the LLM $\mathbf{X}^{(t)}$ along with their reward values $\mathbf{r}_{\sf{ex}}^{(t-1)}$ and $\mathbf{r}^{(t)}$. Defining $\mathbf{r}_{\sf{ex}}^{(1:t-1)}\triangleq\{\mathbf{r}_{\sf{ex}}^{(\tau)}:\forall \tau=0,1,\cdots,t-1\}$ as the set of past reward vectors, it follows
\begin{subequations}\label{eq:pS}
\begin{align}
    &~~~\Pr\{\mathbf{X}_{\sf{ex}}^{(t)}|\mathbf{X}^{(t)},\mathbf{X}_{\sf{ex}}^{(1:t-1)}\}\\
    &=\Pr\{\mathbf{X}_{\sf{ex}}^{(t)}|\mathbf{X}^{(t)},\mathbf{r}^{(t)},\mathbf{X}_{\sf{ex}}^{(1:t-1)},\mathbf{r}_{\sf{ex}}^{(1:t-1)}\}\label{eq:pSb}\\
    %&=\Pr\{\mathbf{X}_{\sf{ex}}^{(t)}|\mathbf{X}^{(t)},\!\mathbf{r}^{(t)},\!\mathbf{X}_{\sf{ex}}^{(t-1)},\!\mathbf{r}_{\sf{ex}}^{(t-1)},\!\mathbf{X}_{\sf{ex}}^{(1:t-2)},\!\mathbf{r}_{\sf{ex}}^{(1:t-2)}\!\}\\
    &=p_{\mathcal{S}}(\mathbf{X}_{\sf{ex}}^{(t)}|\mathbb{M}^{(t)})\label{eq:pSd}\\
    &=p_{\mathcal{S}}(\mathbf{X}_{\sf{ex}}^{(t)}|\mathbf{X}^{(t)},\mathbf{X}_{\sf{ex}}^{(t-1)}),\label{eq:pSe}
\end{align}
\end{subequations}
where \eqref{eq:pSb} and \eqref{eq:pSe} hold since the reward values $\mathbf{r}^{(t)}$ and $\mathbf{r}_{\sf{ex}}^{(1:t-1)}$ are deterministic functions of $\mathbf{X}^{(t)}$ and $\mathbf{X}_{\sf{ex}}^{(1:t-1)}$, respectively, and \eqref{eq:pSd} results from the fact that $\mathcal{S}(\cdot)$ depends only $\mathbb{M}^{(t)}$ in \eqref{eq:memory}. We thus have \eqref{eq:psam}.

Meanwhile, the conditional distribution $\Pr\{\mathbf{X}^{(t)}|\mathbf{X}_{\sf{ex}}^{(1:t-1)}\}$ in \eqref{eq:pL} defines the probability of producing the new action population $\mathbf{X}^{(t)}$ via the pretrained LLM $p_{\mathcal{L}}(\cdot|\cdot)$ in \eqref{eq:zout}. Let $\mathbf{z}^{(t)}\triangleq\mathcal{T}_{\sf{BPE}}({\sf{pmpt}}^{(t)})$ be a token vector for the prompt $\sf{pmpt}^{(t)}$ in \eqref{eq:prompt}. It can be represented as a concatenation of three components, i.e., variable token vectors $\mathcal{T}_{\sf{BPE}}(\mathbf{X}^{(t)}_{\sf{ex}})$ and $\mathcal{T}_{\sf{BPE}}(\mathbf{r}^{(t)}_{\sf{ex}})$ and fixed token vector $\mathbf{z}_{\sf{fix}}$. Thus, $\mathbf{z}^{(t)}$ is written by
\begin{align}
    \mathbf{z}^{(t)}=[\mathcal{T}_{\sf{BPE}}(\mathbf{X}^{(t)}_{\sf{ex}}),\mathcal{T}_{\sf{BPE}}(\mathbf{r}^{(t)}_{\sf{ex}}),\mathbf{z}_{\sf{fix}}].
\end{align}
The LLM samples an output token $\mathcal{T}_{\sf{BPE}}(\mathbf{X}^{(t)})$ from $p_{\mathcal{L}}(\cdot|\mathbf{z}^{(t-1)})$. Since $\mathbf{z}^{(t-1)}$ relies only on $\mathbf{X}_{\sf{ex}}^{(t-1)}$ but not past values $\mathbf{X}_{\sf{ex}}^{(1:t-2)}$, $\mathbf{X}^{(t)}$ becomes independent of $\mathbf{X}_{\sf{ex}}^{(1:t-2)}$. Thus, we can calculate $\Pr\{\mathbf{X}^{(t)}|\mathbf{X}_{\sf{ex}}^{(1:t-1)}\}$ as
\begin{subequations}\label{eq:pLL}
\begin{align}
    &~~~\Pr\{\mathbf{X}^{(t)}|\mathbf{X}_{\sf{ex}}^{(1:t-1)}\}=\Pr\{\mathbf{X}^{(t)}|\mathbf{X}_{\sf{ex}}^{(t-1)}\}\\
    &=\Pr\{\mathcal{T}_{\sf{BPE}}(\mathbf{X}^{(t)})|\mathcal{T}_{\sf{BPE}}(\mathbf{X}_{\sf{ex}}^{(t-1)})\}\label{eq:pLLb}\\
    &=\Pr\{\mathcal{T}_{\sf{BPE}}(\mathbf{X}^{(t)})|\mathcal{T}_{\sf{BPE}}(\mathbf{X}_{\sf{ex}}^{(t-1)}),\mathcal{T}_{\sf{BPE}}(\mathbf{r}_{\sf{ex}}^{(t-1)}),\mathbf{z}_{\sf{fix}}\}\label{eq:pLLc}\\
    &=p_{\mathcal{L}}(\mathcal{T}_{\sf{BPE}}(\mathbf{X}^{(t)})|\mathbf{z}^{(t-1)}),\label{eq:pBPE}
\end{align}
\end{subequations}
where \eqref{eq:pLLb} is attained since $\mathcal{T}_{\sf{BPE}}(\cdot)$ forms an one-to-one mapping and \eqref{eq:pLLc} comes from the facts that $\mathbf{r}_{\sf{ex}}^{(t-1)}$ is directly obtained from $\mathbf{X}_{\sf{ex}}^{(t-1)}$ and $\mathbf{z}_{\sf{fix}}$ is a constant. This proves \eqref{eq:pL}.

Combining \eqref{eq:pS} and \eqref{eq:pLL}, the conditional probability $\Pr\{\mathbf{X}_{\sf{ex}}^{(t)}|\mathbf{X}_{\sf{ex}}^{(1:t-1)}\}$ can be derived as
\begin{subequations}
\begin{align}
    &\Pr\{\mathbf{X}_{\sf{ex}}^{(t)}|\mathbf{X}_{\sf{ex}}^{(1:t-1)}\}\\
    &=\!\!\!\!\!\!\!\!\!\!\sum_{\mathcal{T}_{\sf{BPE}}(\mathbf{X}^{(t)})\in\mathbb{S}}\!\!\!\!\!\!\!\!p_{\mathcal{S}}(\mathbf{X}^{(t)}_{\sf{ex}}|\mathbf{X}^{(t)},\mathbf{X}^{(t-1)}_{\sf{ex}})p_{\mathcal{L}}(\mathcal{T}_{\sf{BPE}}(\mathbf{X}^{(t)})|\mathbf{z}^{(t-1)})\\
    %&=\!\!\!\!\!\!\!\!\!\!\sum_{\mathcal{T}_{\sf{BPE}}(\mathbf{X}^{(t)})\in\mathbb{S}}\!\!\!\!\!\!\!\!p_{\mathcal{S}}(\mathbf{X}^{(t)}_{\sf{ex}}|\mathbf{X}^{(t)}\!,\mathbf{X}^{(t-1)}_{\sf{ex}}\!)\!\Pr\!\{\mathcal{T}_{\sf{BPE}}(\mathbf{X}^{(t)})|\mathcal{T}_{\sf{BPE}}(\mathbf{X}_{\sf{ex}}^{(t-1)})\}\\
    &=\Pr\{\mathbf{X}_{\sf{ex}}^{(t)}|\mathbf{X}_{\sf{ex}}^{(t-1)}\}.
\end{align}
\end{subequations}
This completes the proof.
%where we remove the fixed token vector $\mathbf{z}_{\sf{fix}}$ in \eqref{eq:prop3} since it is a constant for all iterations. Also, \eqref{eq:prop3_2} is directly determined from $\mathbf{X}^{(t)}_{\sf{ex}}$. From \eqref{eq:pLBPE}, we can infer that at the output of the LLM $\mathbf{X}^{(t)}$ depends only on $\mathbf{X}^{(t-1)}_{\sf{ex}}$ but not the past values $\mathbf{X}^{(\tau)}_{\sf{ex}}$, $\forall \tau=0,1,\cdots,t-2$.}

