\section{Introduction}\label{sec1}

In this paper, we work over the field $\mathbb{C}$ and use the basic notations from \cite{km98}. We assume that all varieties appear in this paper to be projective and normal. A variety $X$ is called \textit{Fano variety} if its first Chern class $c_1(X)$ is ample. A variety $X$ has \textit{terminal} (resp. \textit{canonical}, \textit{klt}, \textit{lc}) singularities if the discrepancy $a(E,X)>0$ (resp. $a(E,X)\ge 0$, $a(E,X)>-1$, $a(E,X)\ge -1$) for every divisor $E$ over $X$. A divisor $D$ over $X$ is called a \textit{crepant divisor} if $a(E,X)=0$. A variety $X$ is called \textit{Gorenstein} if the Weil divisor $K_X$ is Cartier. A variety $X$ is \textit{$\mathbb{Q}$-factorial} if for every Weil divisor $D$ on $X$, there is a positive integer $r$ such that $rD$ is Cartier on $X$. All singularities above appear naturally in the Minimal Model Program (MMP for short). 

The \textit{(anticanonical) degree} $c_1(X)^3=(-K_X)^3$ plays an important role in the study of a Fano threefold $X$. Hence computing the optimal upper bound of anticanonical degrees under different conditions is vital. 

Prokhorov \cite{pr07} had shown that for a non-Gorenstein $\mathbb{Q}$-factorial terminal Fano threefold $X$ with Picard number one, $c_1(X)^3\le \frac{125}{2}$. Moreover, the equality holds if and only if $X\cong \mathbb{P}(1,1,1,2)$. Chen Jiang and Yu Zou \cite{jz23} had shown that for a canonical weak Fano threefold, $c_1(X)^3\le 324$. Chen Jiang, Haidong Liu and Jie Liu \cite{jll25} considered the invariants $\qW$ and $\qQ$ (See Definition 2.1) and had shown that for a $\mathbb{Q}$-factorial canonical Fano threefold $X$ with Picard number one, $c_1(X)^3\le 72$, and the equality holds if and only if $X\cong \mathbb{P}(1,1,1,3)$ and $\mathbb{P}(1,1,4,6)$. Note that $\mathbb{P}(1,1,1,3)$ and $\mathbb{P}(1,1,4,6)$ are all Gorenstein. 

In this paper, we obtain the optimal upper bound of anticanonical degrees of non-Gorenstein $\mathbb{Q}$-factorial canonical Fano threefolds with Picard number one. Here is the main theorem of this paper.

\begin{thm}[Corollary 4.3]
    For a non-Gorenstein $\mathbb{Q}$-factorial canonical Fano threefold $X$ with Picard number one, we have $c_1(X)^3\le \frac{200}{3}$. Moreover, we have $\qQ(X)=\qW(X)\in \{2,4,5,10,20,40\}$ if equality holds.
\end{thm}

We have the following example, which implies that the upper bound $\frac{200}{3}$ can be achieved.
\begin{ex}
    There is a toric $\mathbb{Q}$-factorial canonical Fano threefold $X\cong \mathbb{P}(1,1,3,5)$ with Picard number one, such that $c_1(X)^3=\frac{200}{3}$ and $\qW(X)=10$. We see that the two singular points in $X$ are of the form $\frac{1}{3}(1,-1,1)$ and $\frac{1}{5}(1,1,-2)$ respectively, where the former one is terminal and the latter one is canonical by \cite{ms84}*{Theorem 2.3}.
\end{ex}

\section{Preliminaries}

Here are the definitions of some invariants we consider in this paper.
\begin{defn}
    Let $X$ be a canonical Fano variety. We can define two kinds of \textit{Fano indices} by
    $$\qW(X):=max\{q|-K_X\sim qB,\qquad B\in \Cl(X)\};$$
    $$\qQ(X):=max\{q|-K_X\sim_{\mathbb{Q}} qB,\qquad B\in \Cl(X)\}.$$
\end{defn}

\begin{defn}

Let $X$ be a canonical threefold. By \cite{reid87}*{(10.2)(3)}, there exists a basket of points
$$B_X=\{(r_i,b_i)\in \mathbb{Z}^2\ |\ 1\le i\le k;\ 1<b_i\le \frac{r_i}{2};\ gcd(b_i,r_i)=1\}$$
for $X$, where a pair $(r_i,b_i)$ corresponds to an orbifold point $Q_i$ of type $\frac{1}{r_i}(1,-1,b_i)$. We call it \textit{Reid's basket} (basket for short).

Denote by $\mathcal{R}_X$ the collection of $r_i$ appearing in $B_X$. Let $r_X$ be the least positive integer such that $r_XK_X$ is Cartier and we call it \textit{Gorenstein index}. Then 
$$r_X=\lcm \{r_i|r_i\in \mathcal{R}_X\}.$$

\end{defn}

\begin{thm}[\cite{reid87}*{(10.3)}, \cite{jll25}*{Theorem 2.1}]
    Let X be a canonical Fano threefold and $B_X$ the basket for $X$. Then
    \begin{equation}
        c_2(X)\cdot c_1(X)+\sum_{r_i\in \mathcal{R}_X}(r_i-\frac{1}{r_i})=24;
    \end{equation}
    \begin{equation}
        \frac{1}{2}c_1(X)^3+3-\sum_{(r_i,b_i)\in B_X}\frac{b_i(r_i-b_i)}{2r_i}=h^0(X,-K_X)\in \mathbb{Z}_{\ge 0}.
    \end{equation}
\end{thm}

One of main tools of this paper is the following lemma, which is implied by Kawamata-Miyaoka type inequality \cites{liu19, ijl25, ll25, ll252, jll25}.
\begin{lem}
    Let X be a $\mathbb{Q}$-factorial canonical Fano threefold with Picard number one. Let $q:=\qQ(X)$ be the $\mathbb{Q}$-Fano index of X. Then
    \begin{equation}
        c_1(X)^3\le\begin{cases}
        \frac{16}{5}c_2(X)\cdot c_1(X)  &if q\le 5;\\
        \frac{4q^2}{q^2+2q-4}c_2(X)\cdot c_1(X) &if q\ge 6.
    \end{cases}
    \end{equation}
\end{lem}

\begin{proof}
    Direct corollary of \cite{jll25}*{Theorem 3.8} and \cite{jll25}*{Theorem 4.6}.
\end{proof}

Here is the other main tool of this paper, which expresses relationships between some invariants of a canonical Fano threefold.

\begin{thm}[\cite{jll25}*{Theorem 4.2}]
    Let X be a canonical Fano threefold. Let $r_X$ be the Gorenstein index of $X$. Let A be a Weil divisor such that $-K_X\equiv \qQ(X)A$. Take $J_A$ to be the smallest positive integer such that $J_AA$ is Cartier in codimension 2. Then 

    (1)$J_Ar_X(-K_X)^3/\qQ(X)^2$ is a positive integer;

    (2)$\qW(X)\mid r_X(-K_X)^3$;

    (3)If $\qQ(X)=\qW(X)$, $J_A\mid \qQ(X)$.
\end{thm}

As we know, the terminal singularities lie in codimension three. Hence the singularities in codimension two is canonical or even worse. So it is useful to consider the curves lying in $\Sing(X)$ for a canonical threefold $X$.
\begin{defn}
    Let $X$ be a canonical threefold and given an irreducible curve $C\subset \Sing(X)$. We say that $C\subset X$ is \textit{of type} $\mathsf{A}_n(resp. \  \mathsf{D}_m,\ \mathsf{E}_k)$ if at a general point of $C$, $X$ is analytically  isomorphic to $\mathbb{A}^1\times S_C$ where $S_C$ is a Du Val singularities of type $\mathsf{A}_n\ (resp. \ \mathsf{D}_m,\ \mathsf{E}_k)$, where $n\ge 1\ (resp. \ m\ge 4,\ 6\le k\le 8)$. See \cite{jaf92}*{Theorem 1.1} for the types of Du Val singularities.

    Let $e_C$ be 1 plus the number of exceptional curves on the minimal resolution of $S_C$. Let $g_C$ be the order of the local fundamental group of $S_C$ (see \cite{llm19}*{Example 5.2}). Let $j_C$ be the order of the Weil divisor class group of $S_C$ (see \cite{lip69}*{Section 24}). We can list them as following.
    \begin{table}[!ht]
        \centering
        \caption{}
        \label{}
        \begin{tabular}{c|ccccc}
            Type of C & $\mathsf{A}_n$ & $\mathsf{D}_m$ & $\mathsf{E}_6$ & $\mathsf{E}_7$ & $\mathsf{E}_8$ \\
            \hline
            $e_C$ & n+1 & m+1 & 7 & 8 & 9 \\
            $g_C$ & n+1 & 4m-8 & 24 & 48 & 120 \\
            $j_C$ & n+1 & 4 & 3 & 2 & 1 \\
        \end{tabular}
    \end{table}
\end{defn}

\begin{lem}
    Let X be a canonical Fano threefold. Then 
    \begin{align*}
        0 &\le \sum_{C\subset \Sing(X)}(j_C-\frac{1}{j_C})(r_Xc_1(X)\cdot C) \\
        &\le \sum_{C\subset 
        Sing(X)}(e_C-\frac{1}{g_C})(r_Xc_1(X)\cdot C) \\
        &\le \begin{cases}
        r_Xc_2(X)\cdot c_1(X)-\frac{5}{16}r_Xc_1(X)^3 &if\ q\le 5;\\
        r_Xc_2(X)\cdot c_1(X)-\frac{q^2+2q-4}{4q^2}r_Xc_1(X)^3 &if\ q\ge 6.
        \end{cases}
    \end{align*}
\end{lem}

\begin{proof}
    Direct corollary of \cite{jll25}*{Lemma 4.5} and \cite{jll25}*{Theorem 4.6}.
\end{proof}

\begin{lem}[\cite{jll25}*{Corollary 4.7}]
Let X be a $\mathbb{Q}$-factorial canonical Fano threefold with Picard number one. Let A be an ample Weil divisor generating $\Cl(X)/\sim_{\mathbb{Q}}$. Take $J_A$ to be the smallest positive integer such that $J_AA$ is Cartier in codimension 2. Let $J_A=p_1^{a_1}p_2^{a_2}...p_k^{a_k}$ be the prime factorization, where $p_i$ are distinct prime numbers. Then
\begin{equation}
    \sum_{i=1}^k(p_i^{a_i}-\frac{1}{p_i^{a_i}})\le \begin{cases}
    r_Xc_2(X)\cdot c_1(X)-\frac{5r_X}{16}c_1(X)^3\qquad \qquad\quad\ if\ q\le 5;\\
    r_Xc_2(X)\cdot c_1(X)-\frac{r_X(q^2+2q-4)}{4q^2}c_1(X)^3\qquad \ if\ q\ge 6.
\end{cases}
\end{equation}
In particular, 
\begin{equation}
    \sum_{i=1}^k(p_i^{a_i}-\frac{1}{p_i^{a_i}})<r_Xc_2(X)\cdot c_1(X)-\frac{r_X}{4}c_1(X)^3.
\end{equation}
\end{lem}

The following lemmas are useful in this paper.
\begin{lem}[\cite{jll25}*{Lemma 5.1}]
    Let X be a canonical weak Fano threefold with Picard number one and $\qQ(X)\ge 7$. Suppose that $\Cl(X)$ has an s-torsion element, where $s\ge 1$ is a positive integer. Then there exists a threefold $X'$ with the following properties:

    (1)$X'$ is a $\mathbb{Q}$-factorial canonical Fano threefold with Picard number one;

    (2)$\qQ(X')\ge \qQ(X)\ge 7;$

    (3)$(-K_{X'})^3\ge s(-K_X)^3$.
\end{lem}

\begin{lem}
    Suppose that X is a canonical Fano variety with Picard number one. If $\qQ(X)=1$, then the tangent sheaf $\mathcal{T}_X$ is $\alpha$-stable for every movable class $\alpha\in \text{\rm N}_1(X)_{\mathbb{R}}$. Furthermore, let $\dim X=3$ and $\alpha=c_1(X)^2$. By $\mathbb{Q}$-Bogomolov--Gieseker inequality (see \cite{kmm94}*{Lemma 6.5}) we have
    $$c_1(X)^3\le 3c_2(X)\cdot c_1(X).$$
\end{lem}

\begin{proof}
    This is a direct consequence of \cite{ll25}*{Proposition 3.6} and \cite{ou23}*{Theorem 1.4}. As mentioned in \cite{jll25}*{Remark 5.7}, $-c_1(\mathcal{F})$ is nef for any proper subsheaf $\mathcal{F}$ of $\mathcal{T}_X$. So $\mathcal{T}_X$ is $\alpha$-stable for every movable class $\alpha\in \text{\rm N}_1(X)_{\mathbb{R}}$.
\end{proof}

\begin{lem}[\cite{jl25}*{Lemma 4.8}]
    Let $X$ be a canonical Fano threefold, $f\colon Y\rightarrow X$ be a sequential terminalization as in \cite{jl25}*{Definition 4.1}. Let $D$ be a $\mathbb{Q}$-Cartier Weil divisor on X such that $D\equiv 0$ but $D\not\sim 0$. We denote $f^{\lfloor*\rfloor}(D)$ the Weil pullback of $D$ on $Y$ as in \cite{jl25}*{Definition 4.3}. Then
    $$2=\sum_{(r,b)\in B_X}\frac{\overline{i_{f^{\lfloor *\rfloor}(D)}b}(r-\overline{i_{f^{\lfloor *\rfloor}(D)}b})}{2r}+\frac{1}{2}(f^{\lfloor *\rfloor}(D))^2\cdot K_Y,$$
    where $i_{f^{\lfloor *\rfloor}(D)}$ is the local index of $f^{\lfloor *\rfloor }(D)$ at the orbifold point of type $(r,b)\in B_X$. 
\end{lem}

