\section{Reducing the cases}
\setcounter{case}{0}
In this section, we reduce some cases in Table 2 and determine the optimal upper bound of anticanonical degrees.

\begin{prop}
    The case $c_1^3=336/5$ in Table 2 doesn't exist.
\end{prop}
\begin{proof}
    Suppose $X$ satisfies $c_1^3=336/5$, $c_2c_1=96/5$, $q=\hat{q}=84$, $J_A=21$, $B_X=\{(5,2)\}$. Then by Lemma 2.7 we have
    \begin{align*}
        \sum_{C\subset \Sing(X)}(j_C-\frac{1}{j_C})(r_Xc_1(X)\cdot C) &\le \sum_{C\subset \Sing(X)}(e_C-\frac{1}{g_C})(r_Xc_1(X)\cdot C) \\
        &\le r_Xc_2c_1-\frac{84^2+2\times 84-4}{4\times 84^2}r_Xc_1^3 \\
        &= 10+\frac{1}{21}.
    \end{align*}
    By the definition of $J_A$ and $j_C$, we have $J_A\mid \lcm\{j_C\}$. By combining above inequality and Table 1, we obtain that there are exactly two curves $C_3$ and $C_7$ in $\Sing(X)$, where $C_i$ is of type $\mathsf{A}_{i-1}$ for $i=3,7$. We can resolve the curve $C_3$ by crepant blow up and obtain a crepant morphism $f\colon Y\rightarrow X$ (see \cite{kaw15}*{Proposition 2.4}). Since $j_{C_3}=3$, $B:=f^*(3A)$ is a well-defined Weil divisor in $Y$. Since $-K_X\sim 84A$ in $X$, we have $-K_Y=f^*(-K_X)\sim 28B$ in $Y$.

    Now we run a K-MMP on $Y$. Since $\rho(Y)=2$, we have following diagram
\[\begin{tikzcd}
	Y & {Y'} \\
	X & {X'}
	\arrow["g", dashed, from=1-1, to=1-2]
	\arrow["f"', from=1-1, to=2-1]
	\arrow["{f'}", from=1-2, to=2-2]
\end{tikzcd}\]
where $g$ is an isomorphism or the composition of finitely many flips, and $f'$ is a divisorial contraction or a Mori fibre space. Since the K-MMP of $Y$ ends up with a Mori fibre space, we have that either $X'$ is a $\mathbb{Q}$-factorial canonical Fano threefold with Picard number one or $X'$ is of dimension 1 or 2.
\begin{case}
     $f'$ is a Mori fibre space and $X'$ is of dimension 1 or 2. Then the general fibre $F$ of $f'$ is a canonical del Pezzo surface or $\mathbb{P}^1$ and we have $-K_F=-K_{Y'}|_F\sim 28B'|_F$, where $B'$ is the strict transform of $B$ in $Y'$. Hence $\qW(F)\ge 28$, which contradicts \cite{wan24}*{Proposition 3.3}.
\end{case}

\begin{case}
    $f'$ is a divisorial contraction and $X'$ is a $\mathbb{Q}$-factorial canonical Fano threefold with Picard number one. Let $B'$ be the strict transform of $B$ in $X'$. We have $-K_{X'}\sim 28B'$, then $28\mid \qW(X')$. By (2.2) we have
    $$h^0(X,-K_X)=\frac{1}{2}\times \frac{336}{5}+3-\frac{2\times 3}{10}=36.$$
    By definition we have $-K_{Y'}+aE=f'^*(-K_{X'})$ for some $a\in \mathbb{R}_{>0}$, hence
    $$h^0(X',-K_{X'}) \ge h^0(Y',-K_{Y'})=h^0(Y,-K_Y)=h^0(X,-K_X)=36.$$
    \begin{subcase}$X'$ is non-Gorenstein. Then again by (2.2) we have 
    $$c_1(X')^3=2h^0(X',-K_{X'})-6+2\sum_{(r_i,b_i)\in B_X}\frac{b_i(r_i-b_i)}{2r_i}>66.$$
    Hence we know that $X'$ is one of Table 2. Since $28\mid \qW(X')$, $X'$ again satisfies $c_1(X')^3=336/5$, $c_2(X')\cdot c_1(X')=96/5$, $\qQ(X')=\qW(X')=84$, $B_{X'}=\{(5,2)\}$. Let $e(X)$ be the number of crepant divisors for a given resolution of $X$, the definition is independent of the choice of resolutions. By above diagram, we see that there is no crepant divisor contracted in the map from Y to $X'$, so $e(X')=e(Y)=e(X)-1$. We can repeat above process at most e(X) times to obtain a variety $\tilde{X}$, either $\tilde{X}$ is a variety in subcase 2.2 or $\tilde{X}$ is a non-Gorenstein $\mathbb{Q}$-factorial terminal Fano threefold $\tilde{X}$ with Picard number one, $c_1(\tilde{X})^3=\frac{336}{5}$, $\qW(\tilde{X})=84$. But the latter case cannot happen since for such variety $\qW(\tilde{X})\le 19$ by \cite{suz04}*{Theorem 0.3}.

    \end{subcase}

    \begin{subcase}$X'$ is Gorenstein. Then by (2.2) we see that 
    $$\frac{1}{2}c_1(X')^3+3-\sum_{(r_i,b_i)\in B_X}\frac{b_i(r_i-b_i)}{2r_i}=h^0(X',-K_{X'})\ge 36.$$
    Hence $c_1(X')^3\ge 66$, then $c_1(X')^3$ must be one of 66, 68, 70, 72. Then by Theorem 2.5 we have 
    $$28\mid \qW(X')\mid c_1(X')^3,$$
    which is impossible for the $c_1(X')^3$ listed above.\qedhere
    \end{subcase}
\end{case}
\end{proof}

\begin{prop}
    The cases that $q\neq \hat{q}$ in Table 2 don't exist.
\end{prop}

\begin{proof}
    Suppose not the case, then there is a torsion Weil divisor $D$ on such an $X$. By Lemma 2.11, we have a sequential terminalization $f\colon Y\to X$ and 
    $$ (f^{\lfloor *\rfloor}(D))^2\cdot K_Y =\begin{cases}
        \frac{10}{3}, &if\  \overline{i_{f^{\lfloor *\rfloor}(D)}b}(r-\overline{i_{f^{\lfloor *\rfloor}(D)}b})=2; \\
        4, &if\ \overline{i_{f^{\lfloor *\rfloor}(D)}b}(r-\overline{i_{f^{\lfloor *\rfloor}(D)}b})=0. \\
    \end{cases}$$
    By the definition of Weil pullback (\cite{jl25}*{Definition 4.3}), we have $f^{\lfloor *\rfloor}(D)=f^*D-E$ for an effective exceptional Weil $\mathbb{Q}$-divisor $E$. Then we have
    $$(f^*D-E)^2\cdot K_Y=E^2\cdot f^*K_X=\begin{cases}
        \frac{10}{3}, &if\  \overline{i_{f^{\lfloor *\rfloor}(D)}b}(r-\overline{i_{f^{\lfloor *\rfloor}(D)}b})=2; \\
        4, &if\ \overline{i_{f^{\lfloor *\rfloor}(D)}b}(r-\overline{i_{f^{\lfloor *\rfloor}(D)}b})=0. \\
    \end{cases}$$
    By Lemma 2.7, we see that for all cases $q\neq \hat{q}$ in Table 2,
    $$\sum_{C\subset \Sing(X)}(j_C-\frac{1}{j_C})(r_Xc_1(X)\cdot C)\le \sum_{C\subset 
        \Sing(X)}(e_C-\frac{1}{g_C})(r_Xc_1(X)\cdot C)\le 64-\frac{5}{16}\times 200=1.5.$$
    If $\Sing(X)$ has no curve, then $E^2\cdot f^*K_X=0$ by \cite{jl25}*{Lemma 4.10}, contradiction. Then there is exactly one curve $C$ lying in $\Sing(X)$, $j_C=e_C=2$, $r_Xc_1(X)\cdot C=3c_1(X)\cdot C=1$ by above inequality. Hence we see that $C$ is of type $\mathsf{A}_1$ by Table 1. Let $E_0$ be the crepant divisor whose center is $C$, then we have 
    $$E^2\cdot f^*K_X=r^2E_0^2\cdot f^*K_X=\begin{cases}
        \frac{10}{3}, &if\  \overline{i_{f^{\lfloor *\rfloor}(D)}b}(r-\overline{i_{f^{\lfloor *\rfloor}(D)}b})=2; \\
        4, &if\ \overline{i_{f^{\lfloor *\rfloor}(D)}b}(r-\overline{i_{f^{\lfloor *\rfloor}(D)}b})=0, \\
    \end{cases}$$
    where $r\in \mathbb{Q}$.

    Fix $m\gg 0$ and let $S\in |-3mK_X|$ be a general member. Then $S$ meets $C$ for $-3mK_X\cdot C=m$ points which are of Du Val singularities of type $\mathsf{A}_1$, and $\tilde{S}:=f^{-1}(S)$ is the blow up of these singularities. For every irreducible exceptional curve $F$ of $f|_{\tilde{S}}$, we have 
    $$-2=deg\ K_F=K_{\tilde{S}}\cdot F+F^2=F^2.$$
    Hence we have 
    $$E_0^2\cdot f^*K_X=-\frac{1}{3m}(E_0|_{\tilde{S}})^2=-\frac{m}{3m}(F^2)=\frac{2}{3}.$$
    Therefore, we obtain that $r=\sqrt{5}$ or $\sqrt{6}$, which contradicts that $r$ is rational.
\end{proof}

\begin{cor}
    For a non-Gorenstein $\mathbb{Q}$-factorial canonical Fano threefold $X$ with Picard number one, we have $c_1(X)^3\le \frac{200}{3}$. Moreover, we have $\qQ(X)=\qW(X)\in \{2,4,5,10,20,40\}$ if equality holds.
\end{cor}

\begin{proof}
    By combining Theorem 3.1, Proposition 4.1 and Proposition 4.2.
\end{proof}


