		\title[Complex Monge-Amp\`ere equations on compact Hermitian manifolds]
		{Degenerate complex Monge-Amp\`ere type equations on compact Hermitian manifolds and applications II}

		%\author[K. Pang]{Kai Pang}
		%\address{Kai Pang: School of Mathematical Sciences\\ Beijing Normal University\\ Beijing 100875\\ P. R. China}
		%\email{202331130031@mail.bnu.edu.cn}
		\author[H. Sun]{Haoyuan Sun}
		\address{Haoyuan Sun: School of Mathematical Sciences\\ Beijing Normal University\\ Beijing 100875\\ P. R. China}
		\email{202321130022@mail.bnu.edu.cn}
		\author[Z. Wang]{Zhiwei Wang}
		\address{Zhiwei Wang: Laboratory of Mathematics and Complex Systems (Ministry of Education)\\ School of Mathematical Sciences\\ Beijing Normal University\\ Beijing 100875\\ P. R. China}
		\email{zhiwei@bnu.edu.cn}

		\begin{abstract}
			Let $(X,\omega)$ be a compact Hermitian manifold of complex dimension $n$, equipped with a Hermitian metric $\omega$. Let $\beta$ be a possibly non-closed smooth $(1,1)$-form on $X$ such that $\int_X\beta^n>0$. Assume that there is a bounded $\beta$-plurisubharmonic function $\rho$ on $X$ and $\underline{\mathrm{Vol}}(\beta) > 0$. In this paper, we establish solutions to the degenerate complex Monge-Amp\`ere equations on $X$ within the Bott-Chern space of $\beta$ (as introduced by Boucksom-Guedj-Lu) and derive stability results for these solutions. As applications, we provide partial resolutions to the extended Tosatti-Weinkove conjecture and Demailly-P\u aun conjecture.
		\end{abstract}

		\subjclass[2010]{32W20, 32U05, 32U40, 53C55}
		\keywords{Bott-Chern classes, Volume, Degenerate complex Monge-Amp\`ere equation, Stability}


		\maketitle

		\tableofcontents

		\section{Introduction}

		The complex Monge-Amp\`ere equation, which plays a fundamental role in pluripotential theory, complex analysis, and complex geometry, has led to many profound applications in K\"ahler geometry over the past decade. See, for example, \cite{Yau78,BT76,BT82,Ko98,Tsu88,Kol03,TZ06,EGZ09,BEGZ10,EGZ11,EGZ17} and the references therein.

		In recent years, there has been remarkable progress in Hermitian pluripotential theory, particularly in its applications to Hermitian geometry and degenerate complex Monge-Amp\`ere equations on Hermitian manifolds. See, for example, \cite{Che87,Han96,GL10,TW10,Kol05,KN15,Ngu16,LWZ24,BGL24} and the references therein.



		Let $(X, \omega)$ be a compact Hermitian manifold of complex dimension $n$, equipped with a Hermitian metric $\omega$. Let $\beta$ be a smooth possibly non-closed $(1,1)$ form. A function $u:X\rightarrow [-\infty,+\infty)$ is said to be quasi-plurisubharmonic if locally $u$ can be written as the sum of a smooth function and a plurisubharmonic function. A $\beta$-plurisubharmonic ($\beta$-psh for short) function $u$ is defined as a quasi-plurisubharmonic function satisfying $\beta+dd^cu\geq 0$ in the sense of currents. The set of all $\beta$-psh functions on $X$ is denoted by $\mbox{PSH}(X,\beta)$. We say $\beta$ is pseudoeffective, if $\mbox{PSH}(X,\beta)\neq \emptyset$. We say a pseudoeffective $(1,1)$-form is big (cf.\cite{BGL24}), if there is a $\beta$-psh function $\rho$ with analytic singularities such that $\beta+dd^c\rho$ dominates a Hermitian form on $X$.


		In \cite{LWZ24}, the authors solved the degenerate complex Monge-Amp\`ere equation
		\begin{equation*}
			(\beta + dd^c u)^n = f \, \omega^n
		\end{equation*}
		for $0 \leq f \in L^p(X)$ under the condition that the class $\beta$ is closed  and there is a bounded $\beta$-psh function (see also \cite{PSW24, LLZ24} for related results).

		In \cite{BGL24}, Boucksom-Guedj-Lu   made a remarkable extension of the foundational work by Boucksom-Eyssidieux-Guedj-Zeriahi \cite{BEGZ10} to the Hermitian setting.  Specifically, assume that  $\beta$ is a big (possibly non-closed) smooth $(1,1)$-form. They established that the degenerate complex Monge-Amp\`ere equation
		\begin{equation*}
			(\beta + dd^c \phi)^n = c f \omega^n
		\end{equation*}
		admits a solution for $0 \leq f \in L^p(X, \omega)$, where the constant $c > 0$ is uniquely determined by the data $(f, \beta, X, \omega, p, \|f\|_{p}:=\int_X|f|^p\omega^n)$.


		The main goal of this paper is to extend these results to possibly non-closed pseudoeffective $(1,1)$-forms $\beta$ that admit a bounded $\beta$-psh function, under the additional quantitative assumption  
		\begin{equation*}
			\underline{\mathrm{Vol}}(\beta):= \inf_{\substack{u \in \mathrm{PSH}(X,\beta) \cap L^\infty(X)}} \int_X (\beta + dd^c u)^n > 0.
		\end{equation*}
		Note that if $\beta$ is closed,  the condition $\underline{\mathrm{Vol}}(\beta)>0$ is equivalent to the condition that $\int_X\beta^n>0$, since $\underline{\mathrm{Vol}}(\beta)=\int_X\beta^n$.
		\begin{remark}
			Let $X$ be a compact complex surface, and let $\alpha$ be a semipositive, possibly non-closed $(1,1)$-form on $X$ satisfying $\int_X \alpha^2 > 0$ and $\partial\bar{\partial} \alpha = 0$ (for instance, $\alpha$ could be the Gauduchon metric on $X$). Let $\pi: \widetilde{X} \rightarrow X$ be a log resolution of $X$. Then, $\beta := \pi^* \alpha$ satisfies the desired assumptions. This observation can be utilized to construct higher-dimensional examples by considering products of compact complex surfaces with compact K\"ahler manifolds.
		\end{remark}

		Our first main result is as follows.
		\begin{theorem}[=\cref{MA equation 1}]\label{thm:main 1}
			Let $(X, \omega)$ be a compact Hermitian manifold of complex dimension $n$, equipped with a Hermitian metric $\omega$. Let $\beta$ be a possibly non-closed smooth $(1,1)$-form such that there exists a bounded $\beta$-psh function $\rho$ and $\underline{\mathrm{Vol}}(\beta) > 0$.
			Assume $0\leq f\in L^p(X,\omega^n)$ with $p>1$ and $||f||_p>0$. Then, for each $\lambda>0$, there exists a unique $\varphi_{\lambda}\in \mbox{PSH}(X,\beta)\cap L^{\infty}(X)$ such that
			$$
			(\beta+dd^c\varphi_{\lambda})^n=e^{\lambda\varphi_{\lambda}}f\omega^n.
			$$
			Furthermore, we have $|\varphi_{\lambda}|\leq C$ for some uniform constant C depending only on $\lambda,\beta,p,||f||_p$, $X,\omega$.
		\end{theorem}

		The key ingredient in the proof of \cref{thm:main 1} is the new $L^\infty$-a priori estimate established by Guedj-Lu in \cite{GL21}.
		When $\lambda=0$, we have the following theorem.
		\begin{theorem}[=\cref{main thm}]\label{thm:main 2}
			Let $(X, \omega)$ be a compact Hermitian manifold of complex dimension $n$, equipped with a Hermitian metric $\omega$. Let $\beta$ be a possibly non-closed smooth $(1,1)$-form such that there exists a bounded $\beta$-psh function $\rho$ and $\underline{\mathrm{Vol}}(\beta) > 0$.
			Assume that $0 \leq f \in L^p(X, \omega^n)$ with $p > 1$ and $\|f\|_p > 0$. Then there exists a constant $c > 0$ and a function $\varphi \in \mathrm{PSH}(X, \beta) \cap L^{\infty}(X)$ such that
			\[
			(\beta + dd^c\varphi)^n = cf \omega^n.
			\]
			Furthermore, the constant $c$ is uniquely determined by $f$, $\beta$, $X$ and the oscillation of $\varphi$, defined as $\mathrm{osc}\,\varphi := \sup_X \varphi - \inf_X \varphi$, satisfies $\mathrm{osc}\,\varphi \leq C$ for some constant $C$ depending only on $\beta$,  $p$, $\|f\|_{p}$, $X$, and $\omega$.
		\end{theorem}

		The proof of  \cref{thm:main 2} follows the strategy in \cite{GL23}. The uniqueness of the solution remains largely open. For the uniqueness when $f$ is uniformly bounded away from $0$ and $\beta$ is positive, see \cite{KN19}. 

		\begin{remark}
			When $\beta$ is closed, we have $\int_X \beta^n = \underline{\mathrm{Vol}}(\beta)$. In this case, the same results as those in Theorem \ref{thm:main 1} and Theorem \ref{thm:main 2} are obtained in \cite{LWZ24}. When $\beta$ is semipositive, the same results as those in Theorem \ref{thm:main 1} and Theorem \ref{thm:main 2} are obtained in \cite{GL23}.
		\end{remark}


		For applications, we establish the following stability result for the equation given in \cref{thm:main 1}.
		\begin{theorem}[=\cref{thm:stablity of MA 1}]\label{thm:main 3}

			Let $(X, \omega)$ be a compact Hermitian manifold of complex dimension $n$, equipped with a Hermitian metric $\omega$. Let $\beta$ be a possibly non-closed smooth $(1,1)$-form on $X$ such that there exists a bounded $\beta$-psh function $\rho$ and $\underline{\mathrm{Vol}}(\beta) > 0$. 
			Fix $f, g \in L^p(X, \omega^n)$ with $p > 1$ and $\|f\|_p, \|g\|_p>0$. Let $\varphi, \psi \in \mathrm{PSH}(X, \beta) \cap L^{\infty}(X)$ be such that
			\[
			(\beta + dd^c \varphi)^n = e^{\lambda \varphi} f \omega^n, \quad \text{and} \quad (\beta + dd^c \psi)^n = e^{\lambda \psi} g \omega^n,
			\]
			where $\lambda>0$ is a fixed constant. 
			Then we have the estimate
			\[
			\|\varphi - \psi\|_{\infty} \leq C \|f - g\|_p^{\frac{1}{n}},
			\]
			where $C > 0$ is a constant depending on $n$, $p$, $\lambda$, $\|f\|_p$, and $\|g\|_p$. 
			In particular, this implies the uniqueness of the solution to the complex  Monge-Amp\`ere equation in \cref{thm:main 1}.
		\end{theorem}	
		The above theorems can be used to establish a partial result toward an extended version of the Tosatti-Weinkove conjecture and the Demailly-P\u{a}un conjecture \cite[Conjectures 1.1, 1.2]{LWZ24}. Namely, we establish the following two theorems.

		\begin{theorem}[=\cref{thm: TW conj}]\label{thm: main 4}
			Let $(X, \omega)$ be a compact Hermitian manifold of complex dimension $n$, equipped with a Hermitian metric $\omega$. Let $\beta$ be a possibly non-closed smooth $(1,1)$-form on $X$ such that there exists a bounded $\beta$-psh function $\rho$ and $\underline{\mathrm{Vol}}(\beta) > 0$. Let $x_1,\dots,x_N$ be fixed points and $\tau_1,\dots,\tau_N$ be positive real numbers such that
			\begin{align*}
				\sum_{i=1}^{N}\tau_i^n < \underline{\mathrm{Vol}}(\beta). 
			\end{align*}
			Then there exists a $\beta$-psh function $\varphi$ with logarithmic poles at $x_1,\dots,x_N$:
			\begin{align*}
				\varphi(z) \leq c\tau_j\log|z| + O(1) 
			\end{align*}
			in a coordinate ball $(z_1,\dots,z_n)$ centered at $x_j$, where $c \geq 1$ is a uniform constant.
		\end{theorem}	

		\begin{definition}\label{def:upper lower volume}
			Let $(X, \omega)$ be a compact Hermitian manifold of complex dimension $n$, equipped with a Hermitian metric $\omega$. Let $\beta$ be a possibly non-closed smooth $(1,1)$-form on $X$ such that there exists a bounded $\beta$-psh function $\rho$. We then define:
			\begin{align*}
				\overline{\text{Vol}}_{n-1}(\beta) & := \sup_{u\in \text{PSH}(X, \beta)\cap L^{\infty}(X)}\int_X(\beta+dd^cu)^{n-1}\wedge\omega. 
			\end{align*}
			It is clear that the property $\overline{\text{Vol}}_{n-1}(\beta)<+\infty$ does not depend on the choice of the Hermitian metric $\omega$. 
		\end{definition}


		\begin{theorem}[=\cref{thm:DP conjecture}]\label{thm: main 5}
			Let $(X, \omega)$ be a compact Hermitian manifold of complex dimension $n$, equipped with a Hermitian metric $\omega$. Let $\beta$ be a possibly non-closed smooth $(1,1)$-form on $X$ such that there exists a bounded $\beta$-psh function $\rho$ and $\underline{\mathrm{Vol}}(\beta) > 0$  and $\overline{\mbox{Vol}}_{n-1}(\beta)<+\infty$.  Then $\beta$ is big, i.e., it contains a Hermitian current.
		\end{theorem}

		%The proofs of \cref{thm: main 4} and \cref{thm: main 5} are modeled on the work in \cite{LWZ24}; see also \cite{Ngu16}.
		\begin{remark}
			In \cite[Theorem 3.20]{BGL24}, the authors proved that the function $\underline{\text{Vol}}$ vanishes outside the big cone under the assumption of the bounded mass property, i.e., the Hermitian metric $\omega$ satisfies
			\[
			\overline{\text{Vol}}(\omega) := \sup_{u \in \text{PSH}(X, \omega) \cap L^\infty(X)} \int_X (\omega + dd^c u)^n < +\infty.
			\]
			The bounded mass property directly implies that   $\overline{\text{Vol}}_{n-1}(\beta) < +\infty$.

			Indeed, it follows from \cite[Proposition 3.2]{GL22} that $\overline{\text{Vol}}(A\omega) < +\infty$ for all constants $A > 0$. Thus, we may assume that $\beta \leq \omega$.
			For any $u \in \text{PSH}(X, \beta) \cap L^\infty(X)$, $u \in \text{PSH}(X, \omega)$, and hence
			\[
			\int_X (\beta + dd^c u)^{n-1} \wedge \omega \leq \int_X (\omega + dd^c u)^{n-1} \wedge \omega \leq \int_X (\omega + dd^c u + \omega)^n \leq \overline{\text{Vol}}(2\omega) < +\infty.
			\]
			Consequently, our result extends \cite[Theorem 3.20]{BGL24} at least when the class $\{\beta\}$ admits a bounded $\beta$-psh potential.
		\end{remark}

		\begin{remark}
			When $\beta$ is closed, the same results as those in  \cref{thm: main 4} are obtained in \cite{LWZ24}. Additionally, when $\beta$ is closed and the Hermitian metric $\omega$ is pluriclosed, the same results as those in  \cref{thm: main 5} are obtained in \cite{LWZ24}.
		\end{remark}	




