\subsection{Lattices as independent sets in powers of fraction graphs}

Given an invertible matrix $A \in \mathbb{R}^{n \times n}$, we let $\mathcal{L}(A)$ denote the lattice generated by the columns of $A$, that is, $\mathcal{L}(A) = \{A\vect{x} : \vect{x} \in \mathbb{Z}^n\}$.
For $\vect{v} \in \RR^n$ we let $\|\vect{v}\|_\infty = \max_i |\vect{v}_i|$.
Given a lattice $\Lambda$, we define the minimum distance $\lambda_{\infty}(\Lambda) = \min\{\|\vect{v}\|_\infty : \vect{v} \in \Lambda\setminus\{\vect{0}\}\}$.

\begin{lemma}
    \label{lem:matrixtolattice}
    Let $A,B \in \mathbb{Z}^{n \times n}$ and $p,q \in \ZZ_{\geq 1}$. Suppose $AB = p I_n$ and 
    %
    $\lambda_{\infty}(\mathcal{L}(A)) = q$. Then $\alphag(E_{p/q}^{\boxtimes n}) \geq \abs[0]{\det(B)}$.
    %
\end{lemma}

\begin{proof}
    Let $\Lambda = \mathcal{L}(A)$ and $S = \{v \pmod{p} : v \in \Lambda\}$. Note that $S$ is a subgroup of $(\mathbb{Z}/p\mathbb{Z})^n$ and that $p\mathbb{Z}^n$ is a sublattice of $\Lambda$. Let $x \in S$ nonzero and consider the representative $v \in \Lambda$ such that $v_i \in (-p/2,p/2]$ for all indices $i$. Since $x \neq 0$, we know that $v \neq 0$ and thus $|v|_\infty \geq q$. This implies that there exists an index $i$ such that the distance from $x_i$ to $0$ is at least $q$ modulo $p$. It follows that $S$ is an independent set of $E_{p/q}^{\boxtimes n}$. Using \cite[Lemma~10]{dadush}, we have $|S| = \abs[0]{\Lambda / p \ZZ^n} = \abs[0]{\det(p \ZZ^n) / \det(\Lambda)} = p^n / \abs[0]{\det(A)} = \abs[0]{\det(B)}$.
\end{proof}

%
%
%


%
%
%

In \autoref{fig:lattice} we give an illustration of \autoref{lem:matrixtolattice}.

\begin{remark}
A lattice $\Lambda$ such that $p\mathbb{Z}^n \subseteq \Lambda \subseteq \ZZ^n$, like $\mathcal{L}(A)$ in \autoref{lem:matrixtolattice}, is called a $p$-ary lattice \cite[Definition 1]{dadush-lecture9}. 
\end{remark}


\begin{remark}
    \autoref{lem:matrixtolattice} explains how any lattice $\Lambda$ such that $p \mathbb{Z}^n \subseteq \Lambda \subseteq \mathbb{Z}^n$ and $\lambda_\infty(\Lambda) \geq q$ corresponds to a subgroup independent set in $E_{\smash{p/q}}^{\boxtimes n}$. 
    %
    In the other direction, if $S$ is an independent set in  $E_{\smash{p/q}}^{\boxtimes n}$ that is also a subgroup we can consider the lattice $\Lambda_S$ generated by $p \mathbb{Z}^n$ together with a set of representatives of the elements of $S$ in $\mathbb{Z}^n$. It is not hard to see that $S \mapsto \Lambda_S$ gives a one to one correspondence between subgroup independent sets in $E_{\smash{p/q}}^{\boxtimes n}$ and lattices $\Lambda$ such that $p \mathbb{Z}^n \subseteq \Lambda \subseteq \mathbb{Z}^n$ and $\lambda_\infty(\Lambda) \geq q$.
\end{remark}

%

\subsection{Lower bound on the minimum distance via principal minors}

In general it is a hard problem to determine the minimum distance $\lambda_\infty(\Lambda)$ \cite{vanEmdeBoas1981}. To get a handle on it we will use the concept of a $P_0$-matrix \cite{MR4411340}. For any matrix $M \in \RR^{n \times n}$ and $S \subseteq [n]$ we denote by $M_S$ the principal submatrix $(M_{i,j})_{i,j \in S}$.
We call~$M$ a \emph{$P_0$-matrix} if for every $S\subseteq[n]$ we have $\det(M_S)\geq0$, where we define $\det(M_\emptyset) = 1$. 
\begin{lemma}\label{lem:inf-dist-lb}
    Suppose $M \in \mathbb{R}^{n \times n}$ is a $P_0$-matrix.  
    %
    %
    %
    %
    %
    Then for every $q > 0$  the matrix $A = M + q \cdot I_n$ is invertible and satisfies $\lambda_\infty(\mathcal{L}(A)) \geq q$.
\end{lemma}

We work towards the proof of \autoref{lem:inf-dist-lb}, which we note is closely related to known results about $P_0$-matrices and the stronger notion of $P$-matrices \cite{MR4411340}.

%
%
%
%

%

%
%
%
%
%
%

\begin{lemma}\label{lem:det-comp}
    For $M \in \RR^{n \times n}$, $\det(M + \mathrm{diag}(d_1, \ldots, d_n)) = \sum_{S \subseteq [n]} \det(M_S) \prod_{i \not\in S} d_i$.
\end{lemma}
\begin{proof}
    This follows from multilinearity of the determinant and cofactor expansion over appropriate columns.
\end{proof}

%

%
%
%
%
%
%

\begin{lemma}\label{lem:P0nonneg}
    Let $M \in \RR^{n \times n}$ be a $P_0$-matrix. Then for every $\vect{x} \in \mathbb{R}^n \setminus \{ \vect{0} \}$ there exists an $i \in [n]$ such that  ${\vect{x}}_i \neq 0$ and  $(M \vect{x})_i \, \vect{x}_i \geq 0$.
\end{lemma}
\begin{proof}
    Suppose that there is an $x \in \RR^n \setminus \{0\}$ such that for every $j \in [n]$ we have $x_j = 0$ or  $x_j (Mx)_j < 0$. By restricting the coordinates of $x$ and taking the appropriate submatrix of $M$ we may assume that $x_j\neq 0$ for all $j$. Let $d_j = - (Mx)_j / x_j$. Note that $d_j > 0$. Let $A = M + \mathrm{diag}(d_1, \ldots, d_n)$. Then by \autoref{lem:det-comp}, $\det(A) \geq \prod_{j \in [n]} d_j > 0$. However, by construction of the $d_j$, we have $Ax = 0$, which is a contradiction.
\end{proof}



