%
%
%
%
%
%
%
%
%



%

%
\begin{proof}[Proof of \autoref{lem:M_alpha}]
    Using \autoref{lem:Ma},  \autoref{lem:det} and $\alpha \in [0,1]$, it follows that  
    \[
    \det(M_{\alpha}) = \frac{\det(R_{\alpha} + \alpha I_n)}{ \det(R_\alpha - I_n)} = 
    \frac{(-1)^n\alpha+\alpha^n}{(-1)^n\alpha+(-1)^n} = \frac{\alpha+(-\alpha)^n}{\alpha+1} \geq 0.
    \] 
    Since every principal submatrix of $M_\alpha$ is again of the form $M_\alpha$ (but of a smaller size), it follows that~$M_{\alpha}$ is a $P_0$-matrix.
\end{proof}


%
%
\begin{lemma}\label{lem:Malphafrac}%
    %
        %
        %
        %
        For $\alpha\neq-1, \beta\neq0$, 
        \[
        x I_n + y D_\beta M_\alpha D_\beta^{-1} = (\beta (x+y) R_{\alpha \beta^{-n}} + (-x + y \alpha)I_n) (\beta R_{\alpha \beta^{-n}} - I_n)^{-1}.
        \]
    %
\end{lemma}
\begin{proof}
    From a direct computation, it follows that $D_\beta R_\alpha D_\beta^{-1} = \beta R_{\alpha \beta^{-n}}$. From this and  \autoref{lem:Ma} we obtain $D_\beta M_\alpha D_\beta^{-1} = (\beta R_{\alpha \beta^{-n}} + \alpha I_n) (\beta R_{\alpha \beta^{-n}} - I_n)^{-1}$. Then the claim follows by writing $I_n = (\beta R_{\alpha \beta^{-n}} - I_n)(\beta R_{\alpha \beta^{-n}} - I_n)^{-1}$ and collecting terms.
\end{proof}






