\subsection{Construction of lattices}

In this section we define a family of lattices parameterized by $n,k,b,r,s$. In what follows $n$ will always be a positive integer but, unless stated otherwise, $k,b,r,s$ are allowed to be arbitrary real numbers. We will define numbers $a,p,q$ and matrices $X,Y,A,B$ whose values and entries respectively are given by polynomial expressions with integer coefficients in the parameters $k,b,r,s$ and are thus integers whenever all these parameters are integers. This will not always be clear from the definition, since it will often be more convenient to work with a simplified rational form. When working with such rational expressions, since we know that they represent polynomials, we will omit stipulating that denominators are nonzero when proving identities between them.


\begin{definition}\label{def:pqdef}
    We define
    \[
        a = k b^n + s b + r,
        \quad
        p = \displaystyle\frac{s^n r + k a^n}{r + k b^n},
        \quad\text{ and }\quad
        q = \displaystyle\frac{s^{n-1} r + kba^{n-1}}{r + kb^n}.
    \]
\end{definition}

\begin{lemma}
    \label{lem:pqdef}
    Both $p$ and $q$ are polynomials in the parameters $k,b,r,s$, with integer coefficients, and they satisfy: 
    \begin{enumerate}[label=\upshape(\roman*)]
    %
    %
    %
    %
    %
    %
    %
    %
    \item 
    $p = qs + ka^{n-1}$.\label{eq:num1}
    \item 
    $pb = qa -rs^{n-1}$.\label{eq:num2}
    \item 
    If $b,k > 0$ and $r,s \geq 0$, then $p/q \leq a/b$. \label{eq:num3}
    %
    %
    %
    %
    \end{enumerate}
\end{lemma}
\begin{proof}
Define the sequence $x_0, \dots, x_n$ by $x_0 = 1$, $x_{m+1} = \tfrac ab x_m - \tfrac{rs^m}{b}$. Inductively it follows that
\begin{equation}\label{eq:rec-sol}
x_m = \frac{s^m r + k b^{n-m} a^m}{a-sb}.
\end{equation}
We see that $p = x_n$ and $q = x_{n-1}$.
We substitute $r = a - sb - kb^n$ in \autoref{eq:rec-sol} and rewrite to get
\begin{equation}\label{eq:rec-rw}
x_m = s^m + k b^{n-m} \frac{a^m - (sb)^m}{a-sb}
= s^m + kb^{n-m} \sum_{i=1}^m a^{i-1}(sb)^{m-i}.
\end{equation}
It follows that indeed $p$ and $q$ are polynomials in the parameters $k,b,r,s$. One verifies claim \ref{eq:num1} using \autoref{eq:rec-rw}. Claim~\ref{eq:num2} follows directly from the recursive definition of $(x_m)$ applied to $m = n-1$.

Finally, claim~\ref{eq:num3} follows by observing that under the conditions $0 < bq$. If we divide both sides of claim~\ref{eq:num2} by $bq$ we find $p/q = a/b - rs^{n-1}/bq$, which proves the statement.
\end{proof}

We now define matrices $X,Y \in \mathbb{R}^{n\times n}$ using the matrix $M_\alpha$ defined in \autoref{def:Malpha}.

\begin{definition}
    We define
    \[
    X = \frac{k a^{n-1}}{s} D_{s/a} M_{(rs^n)/(k a^n)} D_{a/s}
    \quad\text{ and }\quad 
    Y = -k b^{n-1} D_{1/b} M_{r/(kb^n)} D_b.
    \]
\end{definition}

One can directly verify that the entries of $X$ and $Y$ are polynomials in the parameters by observing that 
\[
X_{ij} = \begin{cases} 
      r a^{j-i-1} s^{n-(j-i+1)} & \text{if } i < j, \\
      0 & \text{if } i = j, \\
      -k a^{n-(i-j+1)}s^{i-j-1} & \text{if } i > j
   \end{cases}
    \quad
    \text{ and }
    \quad 
    Y_{ij} = \begin{cases} 
      -r b^{j-i-1} & \text{if } i < j, \\
      0 & \text{if } i = j, \\
      k b^{n-(i-j+1)}& \text{if } i > j.
   \end{cases}
\]

\begin{lemma}\label{lem:X-P0}
    Let $n \in \mathbb{N}$, $r,s \in \mathbb{R}_{\geq 0}$, and $k,b \in \mathbb{R}_{\geq 1}$ with $r \leq b$, then $X$ is a $P_0$-matrix.
\end{lemma}

\begin{proof}
    Because the $P_0$ property %
    is a closed condition within the space of $n \times n$ matrices, we may assume that $s$ is nonzero. %
    %
    %
    %
    %
    %
    We claim that $M_{(rs^n)/(k a^n)}$ is a $P_0$-matrix. 
    Then, since the $P_0$ property %
    is preserved under both left and right multiplication with nonnegative diagonal matrices, $X$ is $P_0$. Note that $(rs^n)/(k a^n) \in [0,1]$. Indeed, $rs^n \leq b s^n \leq (bs)^n \leq (k\cdot b^n + s \cdot b + r)^n = a^n \leq ka^n.$
    Then the claim follows from \autoref{lem:M_alpha}.
\end{proof}

We now define the matrices $A,B$. The columns of $A$ represent a basis for the lattice that we are interested in. We subsequently prove that the matrices $A,B$ satisfy the requirements of \autoref{lem:matrixtolattice}.

\begin{definition}
    \label{def:AB}
    We define 
    \[
        A = qI_n + X 
        \quad\text{ and }\quad
        B = \frac{a-r}{b} I_n + Y.
    \]
\end{definition}




