\section{Proof of the limit theorem\label{sec:limit}}

In this section we prove \autoref{th:intro-circle-limit}. We will first prove that \autoref{th:intro-circle-limit} is equivalent to \autoref{th:intro-lattice-limit}. We recall that \autoref{th:intro-lattice-limit} directly implies \autoref{eq:intro-2}.

\subsection{Equivalence of 
\autoref{th:intro-lattice-limit} and \autoref{th:intro-circle-limit}}

We recall that there is a cohomomorphism from $E_{p/q}$ to $E_{s/t}$ if and only if $p/q \leq s/t$. In particular,  $p/q \leq s/t$ implies $\alpha(E_{p/q}) \leq \alpha(E_{s/t})$. The same is not true however for $\alphag$. For instance, as noted in \autoref{rem:alphag}, $\alphag(E_{5/2}) = 1$, while $\alphag(E_{10/4}) = 2$. The reason that $\alphag$ is not monotone under the cohomomorphism order is because cohomomorphisms (and indeed graph isomorphisms) need not preserve subgroup structure. Still, when restricted to graphs of the form $E_{p/q}$, there is monotonicity in the following sense. 

\begin{lemma}
    \label{lem:map-subgroup-up}
    Let $a_1, \dots, a_n,b_1, \dots, b_n\in \mathbb{Z}_{\geq 1}$ and let $p,q \in \mathbb{Z}_{\geq 1}$ such that for every $i$, $2 \leq a_i/b_i \leq p/q$. Then there exists $s,t \in \mathbb{Z}_{\geq 1}$ with $s/t = p/q$ such that for each $i$ there is a  group homomorphism from $\mathbb{Z}/a_i\mathbb{Z}$ to $\mathbb{Z}/s\mathbb{Z}$ that is a graph cohomomorphism from $E_{a_i/b_i}$ to $E_{s/t}$.
\end{lemma}


\begin{proof}
    Let $A = a_1 \cdots a_n $.
    It is not hard to check that the map $\mathbb{Z}/a_i\mathbb{Z} \to \mathbb{Z}/Ap\mathbb{Z}$ given by multiplication by $Ap/a_i$ is a cohomomorphism from $E_{a_i/b_i}$ to $E_{Ap/Aq}$. 
\end{proof}

For a given fraction $p/q$ we are interested in the value of $\sup_{a,b: \, a/b=p/q} \Thetag(E_{a/b})$, which we recall gives a lower bound on $\Theta(E_{p/q})$. The previous lemma shows that this value is nondecreasing in $p/q$. It is slightly inconvenient having to consider all equivalent fractions $\{a,b: \, a/b=p/q\}$. To remedy this we will show that we may equivalently consider $\Thetag$ of a well chosen infinite graph.

We recall the definition of the circle graph $E_{x}^{\open}$. This graph is defined as the Cayley graph on $\mathbb{T} = \mathbb{R}/\mathbb{Z}$ where distinct vertices are adjacent if and only if their distance modulo $1$ is strictly less than $1/x$. The following lemma is based on~\cite[Lemma~5.4~(a)]{deboer2024asymptotic}.
\begin{lemma}
    \label{lem:circle-graph-finite-graph-iso}
    Let $x \in \RR_{\geq2}$, $N \in \ZZ_{\geq2}$, and let $S$ be the finite subgroup of $\mathbb{T}$ generated by $1/N$. Then there exists a group isomorphism from $S$ to $\mathbb{Z}/N\mathbb{Z}$ that is a graph isomorphism from $E_x^\open[S]$ to $E_{N/\lceil N/x \rceil}$.
\end{lemma}

\begin{proof}
    Take $v \in S$ let $v' \in \mathbb{R}$ be a representative of $v$ and define $f(v) \in \mathbb{Z}/N\mathbb{Z}$ as the integer $Nv'$ modulo $N$. It is not hard to see that this does not depend on the choice of~$v'$. 

    One verifies directly that the map $f$ is a group isomorphism from $S$ to $\mathbb{Z}/N\mathbb{Z}$. Moreover, distinct $u,v \in S$ are adjacent in $E_x^\open[S]$ if and only if there are representatives $u',v' \in \mathbb{R}$ such that $|u'-v'| < 1/x$, which is the case if and only if $|Nu'-Nv'| < N/x$.
    Since the distance between $Nu'$ and $Nv'$ is an integer, this condition holds if and only if $|Nu'-Nv'| < \lceil N/x \rceil$, which concludes the proof.
\end{proof}

It follows from \autoref{lem:circle-graph-finite-graph-iso} that, for any $p/q$, every $E_{a/b}$ with $a/b = p/q$ is a subgraph of $E_{p/q}^\open$ induced by a subgroup. We can prove the following:

\begin{lemma}
    For $p,q \in \mathbb{Z}_{\geq 1}$ with $p/q \in \mathbb{Q}_{\geq 2}$ we have
    \[
    \Thetag(E^\open_{p/q})= \sup \{ \Thetag(E_{a/b}) : a,b \in \NN,\, a/b=p/q\}.
    \]
\end{lemma}

\begin{proof}
    It follows from \autoref{lem:circle-graph-finite-graph-iso} that any $E_{\smash{a/b}}^{\boxtimes n}$ with $a/b = p/q$ is isomorphic, both as a graph and as a group, to a subgraph of $(E_{p/q}^{\open})^{\boxtimes n}$ induced by a subgroup and thus 
    \[
        \sup \{ \Thetag(E_{a/b}) : a,b \in \NN,\,  a/b=p/q\} \leq \Thetag(E^\open_{p/q}).
    \]

    For the other direction, let $I$ be a subgroup independent set in $(E_{\smash{p/q}}^{\open})^{\boxtimes n}$. For $i = 1, \dots, n$ let $I_i = \{x_i : x \in I\} \subseteq \mathbb{T}$ be the $i$th projection of $I$. Then $I_i$ is a subgroup of $\mathbb{T}$ and thus generated by an element $1/N_i$ for some nonnegative integer $N_i$. It follows from \autoref{lem:circle-graph-finite-graph-iso} that $I$ can be mapped to a subgroup independent set of the same size in 
    \[
        E_{N_1 / \lceil q N_1 / p \rceil} \boxtimes \cdots \boxtimes E_{N_n / \lceil q N_n / p \rceil}.
    \]
    Because $N_i / \lceil q N_i / p \rceil \leq p/q$ for all $i$, it now follows from \autoref{lem:map-subgroup-up} that this subgroup independent set can be mapped to a subgroup independent set of the same size in $E_{\smash{s/t}}^{\boxtimes n}$ for some $s/t = p/q$. 
 \end{proof}

It follows that \autoref{th:intro-lattice-limit} and \autoref{th:intro-circle-limit} are equivalent. To prove \autoref{th:intro-circle-limit} we shall repeatedly use the following.


\begin{lemma}
    \label{lem:grp-shannon-nondecreasing}
    The map $\mathbb{R}_{\geq 2} \to \mathbb{R}_{\geq 2}, x \mapsto \Thetag(E^\open_x)$ is nondecreasing.
\end{lemma}
\begin{proof}
    Whenever $x \leq y$ the graph $E_x^\open$ is a spanning subgraph of $E_y^\open$ and thus any independent set of $(E_x^\open)^{\boxtimes n}$ that is also a subgroup remains independent and a subgroup in $(E_y^\open)^{\boxtimes n}$.
\end{proof}

\subsection{Proof of \autoref{th:intro-circle-limit}}

We define the function 
\[
    \Delta(n, k,b,r,s) = \frac{k\cdot b^n + s\cdot b + r}{b} - \left(\frac{\frac{r}{k}s^n + (k\cdot b^n + s\cdot b + r)^n}{\frac{r}{k}+b^n}\right)^{1/n}.
\]

\begin{lemma}
    \label{lem:shan_bound}
    Let $n,k,b,r,s \in \mathbb{Z}_{\geq 0}$ with $1 \leq n, k,b$. Let $a = k\cdot b^n + s\cdot b + r$, then 
    \[
        \frac{a}{b} - \Thetag(E^{\open}_{a/b}) \leq \Delta(n,k,b,r,s).
    \]
\end{lemma}


\begin{proof}
    Let $p,q$ be as in \autoref{def:pqdef}. We use \autoref{cor:construction}, \autoref{lem:grp-shannon-nondecreasing}, and \ref{eq:num3} of \autoref{lem:pqdef} to find 
    \[
        p^{1/n} \leq \alphag(E_{p/q}^{\boxtimes n})^{1/n} \leq \Thetag(E_{p/q}^\open) \leq \Thetag(E_{a/b}^\open),
     \]
    from which the claim follows.
\end{proof}

\begin{lemma}
    \label{lem:Delta_bound}
    For $n,k,b,r,s \in \mathbb{R}_{\geq 0}$ with $1 \leq n,k,b$, and $k,r \leq b$, and $s \leq b^n$ we have:
    \[
        \Delta(n,k,b,r,s) \leq 6b^2/n.
    \]
\end{lemma}

\begin{proof}
    Write $a = k\cdot b^n + s\cdot b + r$ then 
    \[
    \Delta(n,k,b,r,s) = \frac{a}{b} - \left(\frac{\frac{r}{k}s^n + a^n}{\frac{r}{k}+b^n}\right)^{1/n} \leq \frac{a}{b} - \left(\frac{a^n}{\frac{r}{k}+b^n}\right)^{1/n} = \frac{a}{b}\left[1 - \frac{1}{\left(\frac{r}{kb^n} + 1\right)^{1/n}}\right].
    \]
    We calculate 
    \[
    1 - \frac{1}{\left(\frac{r}{kb^n} + 1\right)^{1/n}} = 
    \frac{\left(\frac{r}{kb^n} + 1\right)^{1/n} - 1}{\left(\frac{r}{kb^n} + 1\right)^{1/n}} \leq \left(\frac{k}{r}\right)^{1/n} \cdot b \cdot \left[\left(\frac{r}{kb^n} + 1\right)^{1/n} - 1\right].
    \]
    For any $0 \leq x \leq 1$ we have $(1+x)^{1/n} = e^{\log(1+x)/n} \leq e^{x/n} \leq 1 + 2x/n$. We apply this to $x = \frac{r}{kb^n}$ to obtain:
    \[
        \left(\frac{r}{kb^n} + 1\right)^{1/n} - 1 \leq 2\frac{r}{kb^nn}.
    \]
    Combining the above three inequalities we obtain
    \[
        \Delta(n,k,b,r,s) \leq 2 \cdot \frac{a}{b^n} \cdot \left(\frac{r}{k}\right)^{1-1/n} \cdot \frac{1}{n}.
    \]
    Because $1 \leq k \leq b$, $r \leq b$ and $s \leq b^n$ we have $a = k\cdot b^n + s\cdot b + r \leq 3b^{n+1}$ and $r/k \leq b$. The conclusion follows.
\end{proof}

%

We now prove the main result of the paper, which we restate for convenience.
\circlelimit*
\begin{proof}
    Let $\varepsilon \in (0,1)$ and let $n \in \mathbb{Z}_{\geq 1}$. Fix an integer $b \geq 2$ with $1/\varepsilon < b \leq 2/\varepsilon$. Now suppose $x \geq b^n$. Let $m = \lfloor x \rfloor$ and note that, because $b^n$ is an integer, we also have $m \geq b^n$. Let $r = \lfloor b(x - m )\rfloor$, then $r \in \{0, 1, \dots, b-1\}$ and $x - 1/b \leq (bm + r)/b \leq x$. Let $n_m$ be the largest integer for which $m \geq b^{n_m}$, observe that $n_m \geq n$. It follows from \autoref{lem:shan_bound} and \autoref{lem:Delta_bound} that
    \[
        \frac{bm + r}{b} - \Thetag(E_{(bm+r)/b}^\open) \leq \Delta(n_m + 1, 1,b,r,m-b^{n_m}) \leq \frac{6 b^2}{n_m+1} \leq \frac{24}{n \cdot \varepsilon^2}.
    \]
    We use the fact that $x \mapsto \Thetag(E_{x}^\open)$ is nondecreasing to conclude 
    \[
        x - \Thetag(E_{x}^\open) \leq \frac{1}{b} + (bm + r)/b - \Thetag(E_{(bm + r)/b}^{\open}) < \varepsilon + \frac{24}{n \cdot \varepsilon^2}.
    \]
    This can be made arbitrarily small which concludes the proof.
\end{proof}

