\section{Spectrum of the Steady State for the Case of an Attractive Fixed Point} \label{app:attract}

Near an attractive fixed point the equations of motion can be linearized.
For simplicity, and without lost of generality, we assume the fixed
point is at $\boldsymbol{\eta}=0$, for which case 
\begin{align*}
\pd_{\tau}\begin{pmatrix}\boldsymbol{\eta}\\
\boldsymbol{\bar{\eta}}
\end{pmatrix}=- & \bs{\Lambda}\begin{pmatrix}\boldsymbol{\eta}\\
\boldsymbol{\bar{\eta}}
\end{pmatrix}-\frac{1}{\sqrt{N}}\begin{pmatrix}\boldsymbol{z}\\
\boldsymbol{\bar{z}}
\end{pmatrix},
\end{align*}
with 
\begin{align*}
\mathbb{E}\left[\begin{pmatrix}\boldsymbol{z}\left(t\right)\\
\boldsymbol{\bar{z}}\left(t\right)
\end{pmatrix}\begin{pmatrix}\boldsymbol{z}\left(t'\right)\\
\boldsymbol{\bar{z}}\left(t'\right)
\end{pmatrix}^{\dagger}\right] & =\bs M\delta\left(t-t'\right),
\end{align*}
and where both $\bs{\Lambda}$ and $\bs M$ are constant matrices.
By stability of the fixed point, the eigenvalues of $\bs{\Lambda}$
have a positive real part, and $\bs M$ is a positive defined hermitian
matrix that characterizes the noise. Solving explicitly the equations
of motion, we have that for large times 
\begin{align*}
\mathbb{E}\left[\begin{pmatrix}\boldsymbol{\eta}\left(t\right)\\
\boldsymbol{\bar{\eta}}\left(t\right)
\end{pmatrix}\begin{pmatrix}\boldsymbol{\eta}\left(t\right)\\
\boldsymbol{\bar{\eta}}\left(t\right)
\end{pmatrix}^{\dagger}\right] & =\frac{1}{N}\tilde{\bs M},
\end{align*}
where 
\begin{align*}
\tilde{\bs M} & =\sum_{\alpha\alpha'}\frac{\ket{\alpha}\bra{\tilde{\alpha}}\bs M\ket{\tilde{\alpha}'}\bra{\alpha'}}{\Lambda_{\alpha}+\bar{\Lambda}_{\alpha'}}
\end{align*}
is a positive defined hermitian matrix, with $\ket{\alpha}$ and $\bra{\tilde{\alpha}}$
the right and left eigenvalues of $\bs{\Lambda}$ with eigenvalue
$\Lambda_{\alpha}$. Working in the basis where $\bs{\tilde{M}}$
is diagonal, i.e. $\bs{\tilde{M}}=\text{diag\ensuremath{\left\{  \varepsilon_{2},\varepsilon_{3},\varepsilon_{2},\varepsilon_{3}\right\} } }$,
we get 
\begin{align*}
\rho_{0} & \propto\int d\eta_{2}d\eta_{3}\,e^{-N\left(\varepsilon_{2}\bar{\eta}_{2}\eta_{2}+\varepsilon_{3}\bar{\eta}_{3}\eta_{3}\right)}\frac{\ket{\boldsymbol{\eta}}\bra{\boldsymbol{\eta}}}{\braket{\boldsymbol{\eta}}{\boldsymbol{\eta}}}.
\end{align*}
Using the overlap of the coherent states with the number basis 
\begin{align*}
\braket{\bs n}{\boldsymbol{\eta}} & =\sqrt{\frac{N!}{n_{1}!n_{2}!n_{3}!}}\frac{\eta_{2}^{n_{2}}\eta_{3}^{n_{3}}}{\left(1+\abs{\eta_{2}}^{2}+\abs{\eta_{3}}^{2}\right)^{N/2}},
\end{align*}
one obtains
\begin{align*}
\bra{\bs n}\rho_{0}\ket{\bs n'} & \propto\delta_{ \bs n, \bs n'}\int d\eta_{2}d\eta_{3}\,e^{-N\left(\varepsilon^{-1}_{2}\bar{\eta}_{2}\eta_{2}+\varepsilon^{-1}_{3}\bar{\eta}_{3}\eta_{3}\right)}\frac{N!}{n_{1}!n_{2}!n_{3}!}\frac{\abs{\eta_{2}}^{2n_{2}}\abs{\eta_{3}}^{2n_{3}}}{\left(1+\abs{\eta_{2}}^{2}+\abs{\eta_{3}}^{2}\right)^{M}}.
\end{align*}
In the large $N$ limit, this expression simplifies to 
\begin{align*}
\bra{\bs n}\rho_{0}\ket{\bs n'} & \propto\delta_{ \bs n, \bs n'}\frac{e^{-\left(n_{2}+1\right)\log\left(\varepsilon^{-1}_{2}+1\right)-\left(n_{3}+1\right)\log\left(\varepsilon^{-1}_{3}+1\right)}}{4N}+O\left(\frac{1}{N}\right)^{2}.
\end{align*}
Thus the effective Hamiltonian of $\rho_{0} = e^{-H_\text{eff}}$ has a spectrum $e_{\bs n}= e_0 + n_{2} \log\left(\varepsilon^{-1}_{2}+1\right)+n_{3}\log\left(\varepsilon^{-1}_{3}+1\right)$,
with $e_0$ a normalization constant and $n_{2,3}=0,1,2...$ . 



\section{Explicit Form of the $\text{IPR}_\phi$} \label{app:IPR}

In the number basis, $\ket{\boldsymbol n=\{n_{1},n_{2},n_{3}\}\in\Lambda_{N}}$,  
with $\Lambda_{N}=\left\{ \bs n:0\le n_{i=1,2,3}\le N\wedge\sum_{i=1}^{3}n_{i}=N\right\} $, integrals over phase-space in Eq.~(\ref{eq:IPR_phi}), can be evaluated explicitly using spherical coordinates in Eq.~(\ref{eq:inv_stereo}). This yields  
\begin{equation}
\int d\mu(\boldsymbol\eta) \, \mathbb{H}_\rho(\boldsymbol\eta) = \sum_{\bs n \in\Lambda_{N}}\bra{\bs n}\rho\ket{\bs n} = \tr{[\rho]},
\end{equation}
and
\begin{equation}
\int d\mu(\boldsymbol\eta)  \, \mathbb{H}_\rho(\boldsymbol\eta)^2 = \sum_{\bs n,\bs m,\bs o,\bs p\in\Lambda_{N}}\bra{\bs n}\rho\ket{\bs m}\bra{\bs o}\rho\ket{\bs p}C\left(\bs n,\bs m,\bs o,\bs p\right), 
\end{equation}
with 
\begin{equation}
C\left(\bs n,\bs m,\bs o,\bs p\right) =\delta_{\bs m+\bs o,\bs n+\bs p}\frac{(N+1)(N+2)(N!)^{2}}{(2N+2)!}\frac{\left(m_{1}+o_{1}\right)!\left(m_{2}+o_{2}\right)!\left(m_{3}+o_{3}\right)!}{\sqrt{m_{1}!m_{2}!m_{3}!n_{1}!n_{2}!n_{3}!o_{1}!o_{2}!o_{3}!p_{1}!p_{2}!p_{3}!}}. 
\end{equation}

\end{widetext}

\section{Leading Lyapunov exponent}
The leading Lyapunov exponent can be defined as  $$\lambda = \lim_{t\rightarrow \infty}  \frac{1}{t} \ln \frac{|\delta Y(t)|}{|\delta Y(0)|}, $$ where $$\delta Y(t) = M^t(Y_0) \delta Y(0)$$ is the time evolution of an initial infinitesimal deviation, $\delta Y(0)$, around the reference classical trajectory 
$$ Y_0(t) = \begin{pmatrix} \boldsymbol{\eta}(t)  \\ \boldsymbol{\bar{\eta}}(t) \end{pmatrix},  $$ and $M^t(Y_0)$ is the monodormy matrix respecting
$$ \partial_t \mathcal{M}^t(Y_0) = J^t(Y_0)  \mathcal{M}^t(Y_0), $$
with 
$$ J^{t}(Y_0) = \begin{pmatrix} \partial_{\boldsymbol{\eta}} \boldsymbol{X} &  \partial_{\boldsymbol{\bar{\eta}}} \boldsymbol{X}\\ \partial_{\boldsymbol{\eta}} \boldsymbol{\bar{X}} &  \partial_{\boldsymbol{\bar{\eta}}} \boldsymbol{\bar{X}} \end{pmatrix}, $$
the Jacobian of the classical evolution given by Eq.(\ref{semiclassical}), and initial condition $\mathcal{M}^{t=0}(Y_0)=\boldsymbol{1}$. 

Defining a normalized initial deviation vector, $\hat{n}=\frac{\delta \vec{Y}(0)}{| \delta \vec{Y}(0)|}$, we can  write 
\begin{equation}
     \lambda = \lim_{t\rightarrow \infty}  \frac{1}{t} \ln | \mathcal{M}^t(Y_0) \hat{n}|,
\end{equation}
which at large $t$, is dominated by the largest stability multiplier 
$\Lambda_1$ (for example $\Lambda_k$ for $k=1$), so the leading Lyapunov exponent is $\lambda =\lim_{t\rightarrow \infty}  \frac{1}{t} \ln | \Lambda_1|$ where $ \Lambda_1$  is the leading eigenvalue of the Jacobian matrix $J^t(Y_0) $. 




