\title{Quantum theory of fractional topological pumping of lattice solitons}
%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%

\author{Julius Bohm}
\affiliation{Department of Physics and Research Center OPTIMAS, University of Kaiserslautern-Landau, 67663 Kaiserslautern, Germany}
