    \caption{Overlap of eigensolution of DNLSE with single-particle Bloch bands for different interaction strength. Data points for the same interaction strength correspond to different times in pumping cycle.}
    \label{fig:overlap}
\end{figure}





\subsection{COM transport and many-body Chern number }
\label{sec:transport_methods}



The time evolution of the center of mass position of the $N$ particles, $\hat X =\sum_{j=1}^N \hat x_j/N$, is governed by the $N$-particle velocity operator $\partial_t \hat X = \hat V = -i[\hat X,{\cal H}] = -i [\hat X,{\cal H}_0]$, which can be conveniently expressed in terms of a momentum-shifted Hamiltonian $\mathcal{H}(q) = e^{-i q \hat X}\, \mathcal{H}\,  e^{i q\hat X}$. I.e. $\hat V = \hat V(q)\vert_{q=0}$ with $\hat V(q) = e^{-i q \hat X}\, \hat V\,  e^{i q\hat X} = \partial {\cal H}(q)/\partial q$. 
%
\begin{equation}
    \frac{d}{dt} \langle \hat X\rangle = \left\langle \hat V(q)\right\rangle_{q=0}=\left \langle \frac{\partial \mathcal{H}(q)}{\partial q}\right\rangle_{q=0}.
\end{equation}
%
 Let us first consider a non-degenerate soliton band, i.e. for a given COM momentum $K$ there is only one eigenstate for each energy band in the whole pump cycle. In order to calculate the transport of a soliton from a single non-degenerate band one can follow the well-known arguments for the transport of a single particle \cite{thouless_pump,thouless1982quantized}. To account for the topological transport starting in an instantaneous eigenstate  $\vert E_0(K,t)\rangle$ at time $t$ one has to take into account non-adiabatic corrections. As the modulation of the Hamiltonian does not affect the translational invariance, non-adiabatic transitions only couple to states with the same COM  momentum. Non-degenerate time-dependent perturbation theory yields
 %
 \begin{equation}
     \vert \Psi(K,t)\rangle = e^{i\gamma}\vert E_0(K) \rangle  + i \sum_{\alpha\ne 0}
    \vert E_{\alpha}(K)\rangle\frac{\langle E_{\alpha}(K)\vert \partial_t E_0(K)\rangle }{E_{\alpha}(K)-E_{0}(K)}
 \end{equation}
%
where we have suppressed the dependence on time for notational simplicity. We note that $\vert \partial_t E_0(K)\rangle $ is orthogonal to $\vert E_0(K)\rangle $ and that the second term in the above expression is small. Calculating the average velocity in this states gives in lowest order
of perturbation theory
%
\begin{eqnarray}
    &&\langle \hat V(q=0,t)\rangle = 
    \frac{\partial E_{0}(K)}{\partial K} + \nonumber\\
    && \qquad + i \sum_{\alpha\ne 0}  
    \Biggl(\frac{\langle \Psi_{0}\vert \partial_q \mathcal{H}(q)\vert_{q=0}\vert \Psi_{\alpha}\rangle\langle \Psi_{\alpha}\vert \partial_t \Psi_{0}\rangle }{E_{\alpha}-E_{0}} -c.c.\Biggr)\nonumber\\
    && \qquad=\frac{\partial E_{0}(K)}{\partial K} + i \left(\left\langle \frac{\partial \Psi_0}{\partial t }\biggr\vert \frac{\partial \Psi_0}{\partial K}\right\rangle- c.c. \right).\label{eq:v}
\end{eqnarray}
%
The first term in this expression describes the dynamical contribution to the transport. If we consider an initial state that has equal probability in all COM momenta $K$ in the Brillouin zone $\{-\pi,\pi\}$, the dynamical contribution vanishes. 
Then the shift of the center of mass of the soliton in one period $T$ is given by the second term in eq.\eqref{eq:v} integrated over all COM momenta $K$, which eventually yields eq.\eqref{eq:COM-Chern-number} of the main text.


 In the degenerate case, i.e. if there are crossings of $m$ bands at some points in time 
we need to apply degenerate time-dependent perturbation theory 
to an $m$ component vector $\vert \underline{\Psi}(K)\rangle =\bigl( \vert \Psi_0(K)\rangle,\dots, \vert \Psi_{m-1}(K)\bigr)^\top$ and can express the time-evolved state 
as
%
\cite{wilczek-zee}
%
\begin{eqnarray}
    \vert \underline{\Psi}(K,t)\rangle &=& {\cal T}\exp\left\{-i\int_0^t\!\! d\tau \mathbf{A}_\tau(K,\tau)\right\} \vert \underline{\Psi}(K,0)\rangle\qquad \label{eq:Wilczek-Zee} \\
    && + \textrm{non-adiabatic\, terms},\nonumber
\end{eqnarray}

where

\begin{eqnarray*}
    \mathbf{A}_\tau = \left(
    \begin{array}{cccc}
         E_0 & - i \langle E_0\vert \partial_t E_1\rangle & - i \langle E_0\vert \partial_t E_2\rangle & ... \\
         - i \langle E_1\vert \partial_t E_0\rangle & E_1 & - i \langle E_1\vert \partial_t E_2\rangle & ... \\
         - i \langle E_2\vert \partial_t E_0\rangle & - i \langle E_2\vert \partial_t E_1\rangle & E_2 & ... \\
         ... & ... & ... & ...
    \end{array}
    \right)
    \label{eq:wilczek-zee-matrix}
\end{eqnarray*}
%
is the Wilczek-Zee non-Abelian Berry phase, and ''non-adiabatic terms'' denotes the perturbative contributions due to non-adiabatic couplings to other, energetically separated states as in the non-degenerate case. We note that since
$\langle E_l\vert \partial_t E_m\rangle = \bigl(\langle E_l\vert \partial_t {\cal H} \vert E_m\rangle\bigr)/(E_m-E_l)$, the eigenstates of the matrix $\mathbf{A}_\tau$ coincide in the adiabatic limit with the bare states $\vert E_0\rangle \dots \vert E_m\rangle$ far away from the crossing point. At the crossing point the off-diagonal elements however diverge in general, which leads to a mixing. Suppose the cyclic change of the Hamiltonian starts at a point where there is no degeneracy between COM bands and the system is prepared in one band, say $\vert E_0(K)\rangle$. Then in the presence of isolated crossing points with other bands $\vert E_\alpha(K)\rangle$, a single cycle $t=0 \to t=T$ will in general not return the initial state to itself, but multiple cycles are needed. 
Then the topological transport is only integer quantized after multiple cycles, giving rise to a fractional average transport per cycle characterized by the Wilson loop as given in eq.\eqref{eq:wilson-loop} of the main text.



\subsection{Effective soliton Hamiltonians in the limit of strongly localized solitons}
\label{sec:effective_methods}


To derive an effective model for strongly localized composite particles let us first look at the binding energy of such a maximally localized soliton in the AAH model \eqref{eq:aah-hamiltonian} (i.e. a localization length $\xi$ smaller than the lattice spacing) which has a binding energy given by 
%
 \begin{align}
     E_{\textrm{int}, N} = \frac{U}{2} N (N-1)
 \end{align}
 %
 whereas states with $N-1$ localized particles have an energy
 %
 \begin{align}
     E_{\textrm{int}, N-1} = \frac{U}{2} (N-1) (N-2).
 \end{align}
%
The energy difference $\vert E_{\textrm{int}, N} - E_{\textrm{int}, N-1}\vert$ is $U(N-1)$. So if $U$ is sufficiently larger than the bose-enhanced hopping $\sqrt{N} J$, the energetically lowest states are localized soliton.

To derive an effective description of the maximally localized solitons, as proposed in Eq. \eqref{eq:effective_hamiltonian}, we have to identify the relevant processes, treating the partiocle hopping as perturbation. These have to be resonant between the degenerate groundstates of the interaction Hamiltonian $\mathcal{H}_{\textrm{int}}$ \cite{Mila_2010}:
For the effective potential, it is the virtual hopping of a single-particle occuring in second order perturbation theory
%
\begin{align*}
  \sim  \hat{a}^{\dagger}_{l}\hat{a}_{l+1} \hat{a}^{\dagger}_{l+1}\hat{a}_{l} \vert \Psi \rangle.
\end{align*}
%
On the other hand the effective hopping of the complete composite particle emerges only in $N$th order perturbation theory 
%
\begin{align*}
    \sim (\hat{a}^{\dagger}_{l+1} \hat{a}_{l})^{N} \vert \Psi \rangle.
\end{align*}
%
The amplitude for the virtual hopping scales as $ \sim 1/U$ while the effective hopping goes with $ \sim 1/U^{N-1}$. 


\paragraph*{The minimal particle number: Triplons --} In the following we will explicitly calculate an effective Hamiltonian for the minimal possible particle number: the triplon. 
For a composite object consisting of only two particles  both processes would have the same scaling $1/U$ and therefore the interaction has no qualitative influence on the system properties. 

The effective potential is calculated directly within second order perturbation theory of the Hamiltonian and is given as
%
\begin{equation}
    \epsilon_{l, \textrm{eff}} = \frac{3}{2} \frac{J_{l-1}^2 + J_l^2}{U}.
\end{equation}
%
Calculating the effective triplon hopping in perturbation theory is possible but already requires good bookkeeping since it is a third order process. 

Therefore we will take a look at the local  basis of two sites  for three particles:
%
\begin{equation*}
    \vert 30 \rangle, \vert 21 \rangle, \vert 12 \rangle, \vert 03 \rangle.
\end{equation*}
%
The local Hamiltonian for these states 
can be written in matrix form:
%
\begin{equation*}
    \left (
    \begin{matrix}
        -3U & -\sqrt{3}J_l & 0 & 0 \\
        -\sqrt{3}J_l & -U & -2J_l & 0 \\
        0 & -2J_l & -U & -\sqrt{3}J_l \\
        0 & 0 & -\sqrt{3}J_l & -3U 
    \end{matrix}
    \right ) .
\end{equation*}
%
Here we assume - without loss of generality - the left site is located at position $l$ in our system.  The two low-energy eigenstates are
%
\begin{equation*}
    \vert\psi_\pm\rangle \propto \vert 30 \rangle \pm \vert 03 \rangle.
\end{equation*}
%
The corresponding eigenenergies are given as
%
\begin{equation*}
    E_\pm = \pm J_{l,\textrm{eff}} + \textrm{const}. 
\end{equation*}
%
From this we can expand the energy difference for small values of the hopping amplitude and extract the effective hopping:
%
\begin{equation}
    J_{l,\textrm{eff}} = \frac{3}{2}\frac{J_l^3}{U^2}.
    \label{eq:effective_hopping_triplon}
\end{equation}

Given both the effective hopping and on-site potential one can calculate the system given by the effective Hamiltonian \eqref{eq:effective_hamiltonian}.


