		\title[Topological $(\f,\g)-$shadowing property]{Topological $(\f,\g)-$shadowing property}
		\author[S. H. Joshi]{Shital H. Joshi}
		\address{Department of Mathematics, Shree M. P. Shah Arts and Science College, Surendranagar, India\\
			Department of Mathematics, Faculty of Science, The Maharaja Sayajirao University of Baroda, Vadodara, India}
