 \section{Natural numbers within $\BISH$}
 \label{sec: nat}


 Within $\BISH$ the natural numbers $\Nat$ is a primitive set equipped with a primitive \textit{equality} and a primitive \textit{inequality} $x \neq_{\Nat} y$. If $1 := S(0)$, where $S \colon \Nat \to \Nat$ is the primitive successor function, the top and the bottom in $\Nat$ are the following formulas, respectively
 $$\top_{\Nat} := 0 \neq_{\Nat} 1, \ \ \ \ \ \bot_{\Nat} := 0 =_{\Nat} 1.$$
 The following axioms on $\Nat$ are accepted: \\[1mm]
 $(\Peano_1)$ $\top_{\Nat}$ .\\[1mm]
 $(\Peano_2)$ $S$ is an \textit{embedding} i.e., $\forall_{x, y \in \Nat}\big(S(x) =_{\Nat} S(y) \To x =_{\Nat} y\big)$.\\[1mm]
 $(\Peano_3)$ or $\IND_{\Nat}$:  $\big[P(0) \ \& \ \forall_{x \in \Nat}(P(x) \To P(S(x)))\big] \To \forall_{x \in \Nat}P(x),$ where $P(x)$ is an \textit{extensional} formula on $\Nat$, that is\footnote{Extensional formulas on a set in $\BISH$ incorporate ``by definition'' the \textit{transport} of Martin-L\"of Type Theory $(\MLTT)$ (see~\cite{HoTT13}).} $\forall_{x, y \in \Nat}\big([x =_{\Nat } y \ \& \ P(x)] \To P(y)\big)$.\\[1mm]
 $(\Bisho_1)$ The equality $x =_{\Nat} y$ is an equivalence relation.\\[1mm]
 $(\Bisho_2)$ The inequality $x \neq_{\Nat} y$ is a \textit{decidable} $(\Ineq_4)$ \textit{apartness relation} $(\Ineq_1 - \Ineq_3)$, where\\[1mm]
 $(\Ineq_1) \  \forall_{x, y \in \Nat}\big(x =_{\Nat} y \ \& \ x \neq_{\Nat} y \To \bot_{\Nat} \big)$.\\[1mm]
 $(\Ineq_2)  \ \forall_{x, y \in \Nat}\big(x \neq_{\Nat} y \To y \neq_{\Nat} x\big)$.\\[1mm]
 $(\Ineq_3) \ \forall_{x, y \in \Nat}\big(x \neq_{\Nat} y \To \forall_{z \in \Nat}(z \neq_{\Nat} x  \vee  z \neq_{\Nat} y)\big)$.\\[1mm]
 $(\Ineq_4) \ \forall_{x, y \in \Nat}\big(x =_{\Nat} y \vee x \neq_{\Nat} y\big)$.\\[2mm]
 The extensionality $(\Ineq_5)$ of $\neq_{\Nat}$ follows from $(\Ineq_1 - \Ineq_3)$, see~\cite{Pe20} Remark 2.2.6, where\\[1mm]
 $(\Ineq_5) \ \forall_{x, x{'}, y, y{'} \in \Nat}\big(x =_{\Nat} x{'} \ \& \ 
 	y =_{\Nat} y{'} \ \& \ x \neq_{\Nat} y \To x{'} \neq_{\Nat} y{'}\big)$.\\[2mm]
The \textit{prime formulas} in $\BISH$ are of the form: $s =_{\Nat} t$, $s \neq_{\Nat} t$, where $s, t \in \Nat$. The \textit{complex formulas} in $\BISH$ are defined as follows: if $A, B$ are formulas, then $A \vee B, A \wedge B, A \To B$ are formulas, and if $S$ is a set and $\phi(x)$ is a  formula, for every variable $x$ of set $S$, then $\exists_{x \in S} \big( \phi(x)\big)$ and $\forall_{x \in S} \big(\phi(x)\big)$ are formulas. If $P$ is a formula in $\BISH$, the \textit{weak negation} $\neg_{\Nat} P$ of $P$ is the formula $\neg_{\Nat} P := P \To \bot_{\Nat}$.
By $(\Ineq_1)$ we get $x \neq_{\Nat} y \To \neg_{\Nat} \big(x =_{\Nat} y)$ i.e., the strong inequality $x \neq_{\Nat} y$ implies the weak inequality $\neg_{\Nat} \big(x =_{\Nat} y)$. The converse implication also follows constructively for $\Nat$ (Proposition~\ref{prp: botnat}(v)).


 All subsets $A$ of $\Nat$ considered here are \textit{extensional} i.e., $A := \{x \in \Nat \mid P(x)\}$, where $P(x)$ is an extensional formula on $\Nat$. The totality of extensional subsets of $\Nat$ is denoted by $\C E(\Nat)$, and the equality on $\C E(\Nat)$ is defined in the obvious way.
 Let $\PEM_{\Nat}$ be the axiom scheme $P \vee \neg_{\Nat} P$, where $P$ is any formula in $\BISH$, such that 
 there is at most one variable $x$ of $\Nat$ ocurring in $P$ and in that case $P(x)$ is extensional. We need this hypothesis of extensionality, in order to apply the separation scheme, which concerns bounded (i.e., formulas with bounded quantifiers only) extensional formulas.
 We include the following standard proof, in order to stress that it is within a certain version of minimal logic $(\MIN)$, which is intuitionisitic logic $(\INT)$ without the ex falso principle $\EFQ_{\Nat}$: $\bot_{\Nat} \To Q$, where $Q$ is an arbitrary formula in $\BISH$. 

\begin{proposition}[$\MIN$]\label{prp:  LNPtoPEM} 
$\LNP$ implies $\PEM_{\Nat}$.
\end{proposition}

\begin{proof}
If $P$ is a formula as it is indicated in $\PEM_{\Nat}$, let $A_P := \{x \in \Nat \mid x =_{\Nat} 1\} \cup \{x \in \Nat \mid x =_{\Nat} 0 \ \& \ P\}$. Clearly, $\min_{A_P} = 0$, or $\min_{A_P} = 1$. If $\min_{A_P} = 0$, then $0 \in A_P$ and hence $P$. If $\min_{A_P} = 1$, we suppose $P$. In this case $0 \in A_P$, hence $0 = \min_{A_P}$. By the uniqueness of $\min_{A_P}$ we get $0 =_{\Nat} 1$ i.e., $\neg_{\Nat} P$. 
\end{proof}

Many instances of $\EFQ_{\Nat}$ are provable within $\MIN$. Next follow some of them.


\begin{proposition}[$\MIN$]\label{prp: botnat} The following hold:\\[1mm]
	\normalfont (i)
	\itshape $\bot_{\Nat} \To \forall_{x \in \Nat}\big(x \neq_{\Nat}
	x\big)$.\\[1mm]
	\normalfont (ii)
	\itshape $\bot_{\Nat} \To \forall_{x \in \Nat}\big(0 =_{\Nat}
	x \big)$.\\[1mm]
	\normalfont (iii)
	\itshape $\bot_{\Nat} \To \forall_{x, y \in \Nat}\big(x =_{\Nat}
	y\big)$.\\[1mm]
	\normalfont (iv)
	\itshape $\bot_{\Nat} \To \forall_{x, y \in \Nat}\big(x \neq_{\Nat}
	y\big)$.\\[1mm]
	\normalfont (v)
	\itshape $\forall_{x, y \in \Nat}\big(\neg_{\Nat} \big(x =_{\Nat} y) \To x \neq_{\Nat} y\big)$.\\[1mm]
		\normalfont (vi)
	\itshape $\forall_{x, y \in \Nat}\big(\neg_{\Nat} (x \neq_{\Nat} y) \To x =_{\Nat} y\big)$
\end{proposition}

\begin{proof}
	(i) By induction on $x \in \Nat$. First we show that $0 \neq_{\Nat} 0$. As $0 \neq_{\Nat} 1$, and since by hypothesis $0 =_{\Nat} 1$, by the extensionality of $\neq_{\Nat}$ we get $0 \neq_{\Nat} 0$. The implication $x \neq_{\Nat} x \To S(x) \neq_{\Nat} S(x)$ follows by the injectivity of the successor function $S \colon \Nat \to \Nat$ i.e., $x \neq_{\Nat} y \To S(x) \neq_{\Nat}  S(y)$, for every $x, y \in \Nat$. To show the latter, we suppose that $S(x) =_{\Nat} S(y)$ and since $S$ is an embedding we get $x =_{\Nat} y$. As $x \neq_{\Nat} y$ by hypothesis, we get $\bot_{\Nat}$  from $(\Ineq_1)$. Using the rule $\big[(P \vee Q) \ \& \ \neg_{\Nat} P\big] \To Q$ and the decidability of $\neq_{\Nat}$ we get $S(x) \neq_{\Nat} S(y)$.\\
	(ii) Again we use induction on $x \in \Nat$. The base case $0 =_{\Nat} 0$ follows immediately. The implication 
	$0 =_{\Nat}	x \To 0 =_{\Nat} S(x)$ follows from the fact that if $0 =_{\Nat} x$, then $S(0) =_{\Nat} S(x)$ i.e., $1 =_{\Nat} S(x)$. By the definition of $\bot_{\Nat}$ and the equivalence relation properties of $=_{\Nat}$ we get the required $0 =_{\Nat} S(x)$.\\
	(iii) It follows immediately by case (ii) and the fundamental properties of $=_{\Nat}$.\\
	(iv) It follows immediately by cases (i), (iii) and the extensionality of $\neq_{\Nat}$.\\
	(v) By decidability $x =_{\Nat} y \vee x \neq_{\Nat} y$. If $\neg(x =_{\Nat} y)$ by hypothesis, the rule  $\big[(P \vee Q) \ \& \ \neg_{\Nat} P\big] \To Q$ again gives us $x \neq_{\Nat} y$.\\
	(vi) We work exactly as in the proof of (v).
\end{proof}



\begin{remark}\label{rem: ontheproof}
	\normalfont
	If we use the properties of multiplication on $\Nat$, cases (i) and (ii) of the previous proposition can be shown without induction: if $0 =_{\Nat} 1$, then $0 =_{\Nat}  0 \cdot x =_{\Nat} 1 \cdot x =_{\Nat} x$, for every $x \in \Nat$, and hence $x =_{\Nat} y$, for every $x, y \in \Nat$. By the extensionality of $\neq_{\Nat}$ the inequality $0 \neq_{\Nat} 1$, together with the equalities $x =_{\Nat} 0$ and $1 =_{\Nat} x$ imply that $x \neq_{\Nat} x$, for every $x \in \Nat$. 
\end{remark}


The canonical orders $<_{\Nat}, \leq_{\Nat}$ on $\Nat$ can be defined using the operation of addition, or of cut-off subtraction (see~\cite{TvD88}, p.~124). They can also be introduced as primitive extensional relations on $\Nat$, and they satisfy all expected properties. For example, for every $x, y \in \Nat$ we have that\footnote{For simplicity we omit the subscripts from $<_{\Nat}, \leq_{\Nat}$, and we write $<$ and $\leq$, respectively.}: \\[2mm]
%\noindent
(I1) $x < y \vee x \geq y$,\\[1mm]
(I2) $x \geq y \TOT x = y \vee x > y$.\\[1mm]
(I3) $x < y \To x \neq_{\Nat} y$.\\[1mm]
(I4) $x \neq_{\Nat} y \To x < y \vee y < x$.\\[1mm]
(I5) $\neg_{\Nat}((x < y) \To x \geq y$.

\begin{definition}[Categories of sets]\label{def: sets} Let $(\Set, \Fun)$ be the category\footnote{We denote a category by the pair of its objects \textit{and} arrows.}  of sets and functions, and let $(\SetIneq, \StrExtFun)$ be the category of sets with an inequality that satisfies the corresponding properties $(\Ineq_1, \Ineq_2)$ for $X$, of and strongly extensional functions i.e., functions $f \colon X \to Y$ satisfying $f(x) \neq_Y f(x{'}) \To x \neq_X x{'}$, for every $x, x{'} \in X$. Let $(\SetExtIneq, \StrExtFun)$ be the category of sets with an extenional inequality i.e., the corresponding property $(\Ineq_5)$ holds for $X$, and of strongly extensional functions.	
\end{definition}

Clearly, 
%we have the following sequence of subcategories
$(\SetExtIneq, \StrExtFun) \leq (\SetIneq, \StrExtFun) \leq (\Set, \Fun)$, and $(\Nat, =_{\Nat}, \neq_{\Nat}) \in \SetExtIneq$. 
%The arrows in the category of sets with an inequality are \textit{strongly extensional functions} i.e., functions $f \colon X \to Y$ satisfying $f(x) \neq_Y f(x{'}) \To x \neq_X x{'}$, for every $x, x{'} \in X$. 
All functions of type $\Nat \to \Nat$ are strongly extensional. This we cannot accept constructively for every function of type $\Real \to \Real$, as this is equivalent to Markov's principle (see~\cite{Di20}, p.~40). We call a function $f \colon \Nat \to \Nat$ \textit{strongly monotone}, if $\forall_{x, y \in X}\big(f(x) < f(y) \To x < y\big)$. The proof of Proposition~\ref{prp: se} is trivial, and it is based on $(\Ineq_4)$. 


\begin{proposition}\label{prp: se}
	Let $f \colon \Nat \to \Nat$ be a function.\\[1mm]
	\normalfont (i)
	\itshape $f$ is strongly extensional.\\[1mm]
	\normalfont (ii)
	\itshape If $f$ is monotone, then $f$ is strongly monotone.\\[1mm]
	\normalfont (iii)
	\itshape If $f$ is strongly monotone and an embedding, then $f$ is monotone.
\end{proposition}

















\section{The coinductive principle $\exists \PWF_{\Nat}$ of well-foundedness of $\Nat$}
\label{sec: PWF}


The main principle regarding $<_{\Nat}$ that will be used in the proof of Theorem~\ref{thm: CLNP} is the following constructive and coinductive version of well-foundedness of $\Nat$:\\[2mm]$(\exists \PWF_{\Nat})$ $\exists$-well-foundedness of $\Nat$: if $P(x), Q(x)$ are formulas on $\Nat$ that respect $=_{\Nat}$, then
$$\bigg[\exists_{x \in \Nat}Q(x) \ \& \ \forall_{x \in \Nat}\bigg(Q(x) \To \big[P(x) \vee \exists_{y \in \Nat}\big(y < x \ \& \ Q(y)\big)\big]\bigg)\bigg] \To \exists_{x \in \Nat}P(x).$$
%such that \\[1mm]
%$(\PWF_1)$ $\exists_{x \in \Nat}Q(x),$ and\\[1mm]
%$(\PWF_2)$ $\forall_{x \in \Nat}\bigg(Q(x) \To P(x) \vee \exists_{y \in \Nat}\big(y < x \ \& \ Q(y)\big)\bigg)$.\\[1mm]
%Then $\exists_{x \in \Nat}P(x)$.
$\exists \PWF_{\Nat}$ is a sort of dual to the standard induction principle $\IND_{\Nat}$; its conclusion is an existential formula, and the second disjunct in its hypothesis involves a backward step, rather than a forward one. The algorithm of finding $x \in \Nat$ with $P(x)$ that is captured by this principle is the following: if $x_0 \in \Nat$ with $Q(x_0)$, then either $P(x_0)$, or there is $x_1 < x_0$ with $Q(x_1)$. In the second case, we repeat the argument, and either $P(x_1)$, or there is $x_2 < x_1$ with $Q(x_2)$. After at most $(x_0 +1)$-number of steps we findd $x \in \Nat$ with $P(x)$, since if $Q(0)$ is the case, there is no $x < 0$, and hence $P(0)$ must hold.
