Such an anrgument can be used in a classical proof of $\LNP$: if $x_0 \in A$, then classically either $x_0 =_{\Nat} \min_A(x_0)$, or there is $x_1 \in A$ with $x_1 < x_0$, and so on. I.e, $Q_A(x) :\TOT x \in A$ and $P_A(x) :\TOT \forall_{y \in A}(y \geq x)$. 
So far, we know that $\exists \PWF_{\Nat}$ is only classically equivalent to transfinite (or strong) induction $\forall \PWF_{\Nat}$  on $\Nat$, according to which $\forall_{x \in \Nat}\big(\forall_{y < x}P(y) \To P(x)\big) \To \forall_{x \in \Nat}P(x)$, where $P(x)$ is a formula on $\Nat$ that respects $=_{\Nat}$.
Notice that the proof of the implication $\IND_{\Nat} \To \forall \PWF_{\Nat}$ is within $\INT$, since the proof of $P(0)$ requires $\EFQ$. 

%In order to work within $\MIN$, we accept both $\IND_{\Nat}$ \textit{and} $\exists \PWF_{\Nat}$ in our axiomatisation of the natural number. Hence, \textit{we add} $\exists \PWF_{\Nat}$ \textit{in the axioms of the natural number system in} $\BISH$.


\begin{proposition}\label{prp: equiv}
\normalfont (i)
\itshape $\forall \PWF_{\Nat}$ implies $\exists \PWF_{\Nat}$ constructively\footnote{We would like to thank Thierry Coquand for suggesting this proof to us.}.\\[1mm]
\normalfont (ii)
\itshape $\exists \PWF_{\Nat}$ implies classically $\forall \PWF_{\Nat}$ and $\LNP$.\\[1mm]
\normalfont (iii)
\itshape $\exists \PWF_{\Nat}$ implies constructively that for every sequence $\alpha \colon \Nat \to \Nat$, there is $i \in \Nat$ with $\alpha(i) \leq \alpha(i+1)$.\\[1mm]
\normalfont (iv)
\itshape The non-existence of an infinite descending sequence in $\Nat$ implies classically $\exists \PWF_{\Nat}$.
\end{proposition}

\begin{proof}
(i) We suppose that $\exists_{x \in \Nat}(Q(x)$, and let $n_0 \in \Nat$, such that $Q(n_0)$ holds. We also suppose that 
$$\forall_{x \in \Nat}\big(Q(x) \To (P(x) \vee \exists_{y < x}(Q(y)))\big).$$
 Let the predicate
$$R(n) :\TOT \bigg[Q(n) \ \& \ \forall_{x \in \Nat}\big(Q(x) \To (P(x) \vee \exists_{y < x}(Q(y)))\big)\bigg] \To \exists_{x \in \Nat}(P(x)).$$
It suffices to show that $\forall_{x \in \Nat}\big(\forall_{y < x}R(y) \To R(x)\big)$, since then by $\forall \PWF_{\Nat}$ we get $\forall_{x \in \Nat}R(x)$, and then the conlusion $R(n_0)$ tohether with the first two hypotheses imply with Modus Ponens the required formula $\exists_{x \in \Nat}(P(x))$.
Let $x \in \Nat$ and let 
$$\forall_{y < x}\bigg(\bigg[Q(y) \ \& \ \forall_{u \in \Nat}\big(Q(u) \To (P(u) \vee \exists_{w < u}(Q(w)))\big)\bigg] \To \exists_{z \in \Nat}(P(z))\bigg).$$
We show 
$$R(x) :\TOT \bigg[Q(x) \ \& \ \forall_{v \in \Nat}\big(Q(v) \To (P(v) \vee \exists_{k < v}(Q(k)))\big)\bigg] \To \exists_{z \in \Nat}(P(z)).$$
Let $Q(x) \ \& \ \forall_{v \in \Nat}\big(Q(v) \To (P(v) \vee \exists_{k < v}(Q(k)))\big)$. Hence, 
$Q(x)$ or $\exists_{k < x}(Q(k))$. In the first case, we get immediately what we want, while in the second case we use the inductive hypothesis for $Q(k)$.\\
%To prove the implication $\forall \PWF_{\Nat} \To \exists \PWF_{\Nat}$, let $\exists_{x \in \Nat}Q(x)$ and $\forall_{x \in \Nat}\big(Q(x) \To \big[P(x) \vee \exists_{y \in \Nat}\big(y < x \ \& \ Q(y)\big)\big]\big)$, and suppose that $\neg_{\Nat}\exists_{x \in \Nat}P(x)$. Let $x_0 \in \Nat$ with $Q(x_0)$. By hypothesis there is $x_1 < x_0$, such that $Q(x_1)$. Clearly, an infinite descending sequance in $\Nat$ is formed with dependent choice. $\forall \PWF_{\Nat}$ implies in $\MIN$ the standard induction principle $\IND_{\Nat}$, which in turns implies constructively the non existence of an infinite descending sequence $\alpha$ in $\Nat$, since it implies the existence of an index $i \in \Nat$ with $\alpha(i) \leq \alpha(i+1)$ (see~\cite{Pe22}, Proposition 2.1).\\
(ii) To prove the implication $\exists \PWF_{\Nat} \To \forall \PWF_{\Nat}$, we suppose that $\forall_{x \in \Nat}\big(\forall_{y < x}P(y) \To P(x)\big)$ and that $\neg_{\Nat} \forall_{x \in \Nat}P(x)$, hence classically $\exists_{x \in \Nat}\neg P(x)$. If $Q{'}(x) :\TOT \neg P(x)$ and $P{'}(x) :\TOT P(x) \ \& \ \neg P(x)$, then by hypothesis we have that $\exists_{x \in \Nat}Q{'}(x)$. Let $x \in \Nat$ with $P{'}(x)$. If $x =_{\Nat} 0$, then since $P(0)$ holds trivially, we get $P{'}(0)$. If $x > 0$, then by the hypothesis of $\forall \PWF_{\Nat}$ there is $y < x$ with $Q{'}(y)$. By the conclusion of $\exists \PWF_{\Nat}$ for $Q{'}(x)$ and $P{'}(x)$ we have that $\exists_{x \in \Nat}(P(x) \wedge \neg P(x))$, hence $\neg \neg_{\Nat} \forall_{x \in \Nat}P(x)$, and by double negation elimination we get $\forall_{x \in \Nat}P(x)$.
The fact that $\exists \PWF_{\Nat}$ implies classically $\LNP$ follows from the fact that $\forall \PWF_{\Nat}$ is classically equivalent to $\LNP$ (see~\cite{TvD88}, p.~129).\\
(iii) Let $\alpha \colon \Nat \to \Nat$. We define $Q_{\alpha}(x) :\TOT \exists_{n \in \Nat}(x =_{\Nat} \alpha(n))$ and $P_{\alpha}(x) :\TOT \exists_{n \in \Nat}\big(x =_{\Nat} \alpha(n) \ \& \ \alpha(n) \leq \alpha(n+1)\big)$. Trivially, $Q_{\alpha}(a_0)$ holds. Let $x, n \in \Nat$, such that $x =_{\Nat} \alpha(n)$. By (I1), if $\alpha(n) \leq \alpha(n+1)$, then $P_{\alpha}(x)$ holds. If $\alpha(n) > \alpha(n+1)$, then $Q_{\alpha}(\alpha(n+1))$. As the hypothesis of $\exists \PWF_{\Nat}$ holds for $Q_{\alpha}$ and $P_{\alpha}$, we get $x, n \in \Nat$, such that $x =_{\Nat} \alpha(n) \ \& \ \alpha(n) \leq \alpha(n+1)\big)$.\\
(iv) We work as in the classical proof of the implication $\forall \PWF_{\Nat}\To \exists \PWF_{\Nat}$ in case (i).
\end{proof}

