\section{The constructive least number principle $\CLNP$}
\label{sec: CLNP}

\textit{Throughout this section} $\B A := (A^1, A^0)$ \textit{is a complemented subset of} $\Nat$.

\begin{definition}\label{def: mcs}
We call $\B A$ downset located, if
$$\forall_{x^1 \in A^1}\big(\C D_{\B A}(x^1) \subseteq A^0 \vee \C D_{\B A}(x^1) \between A^1\big).$$
\end{definition}

\begin{example}\label{ex: lpl}
\normalfont
(i) If $\B A$ is total, then $\B A$ is downset located. If $0 \in A^1$, then $\C D_{\B A}(0) =_{\C E(\Nat)} \emptys_{\Nat}$, and with $\EFQ$ we get\footnote{For many concrete subsets $A^0$ of $\Nat$ the inclusion $\emptys_{\Nat} \subseteq A^0$ can be shown within $\MIN$. See the proof in Example~\ref{ex: lpl}(ii).} $\emptys_{\Nat} \subseteq A^0$. If $x^1$ is a non-zero element of $A^1$, then $\C D_{\B A}(0) =_{\C E(\Nat)} \{0, \ldots, x^1-1\}$ and the required disjunction holds because for every $i \in \{0, \ldots, x^1-1\}$ we have that $i \in A^1 \vee i \in A^0$. Using this argument and classical logic, then all complemented subsets of $\Nat$ are downset located.\\
(ii) Let $A^1 := \{x \in \Nat \mid x =_{\Nat} 2\} =: \{2\}$ and $A^0 := \{3\}$. Then $\B A$ is downset located, but not total. Working as in example (i), we have that $\C D_{\B A}(2) =_{\C E(\Nat)} \emptys_{\Nat}$. The inclusion $\emptys_{\Nat} \subseteq A^0$ is shown within $\MIN$ as follows: if $x \in \emptys_{\Nat}$, then by $(\Ineq_1)$ we get $\bot_{\Nat}$, and by Proposition~\ref{prp: botnat}(ii)
 %we conclude that 
 $3 =_{\Nat} 0 =_{\Nat} x$.\\
 (iii) The complemented subset $\B P := (P^1, P^0)$, where $P^1, P^0$ are defined in Example~\ref{ex: nontotal}, cannot be accepted constructively to be downset located. As $1 \in P^1$, its downset  $\C D_{\B P}(1) := \{x \in P^1 \cup P^0 \mid x < 0\}$ overlaps with $P^1$ only if $0 \in P^1$ and $P$ holds, and it is included in $P^0$ if there is $x \in P^1 \cup P^0$, such that $x < 1$ and $x \in P^0$, hence $\neg_{\Nat} P$.
\end{example}

Next, we show that there is a plethora of downset located subsets of $\Nat$, induced by appropriate monotone functions from $\Nat$ to $\Nat$. 
%Notice that the hypothesis of surjectivity on $B^1$ mentioned in the next result can be replaced by the hypothesis of $f$ being a \textit{simulation}\footnote{See \url{https://ncatlab.org/nlab/show/simulation}.} from $(\Nat, <)$ to $(\Nat, <)$ i.e., $f$ is a monotone function, such that $\forall_{x, y \in \Nat}\big(y < f(x) \To \exists_{z < x}\big(y = f(z)\big)\big)$. 


\begin{proposition}\label{prp: invlpc}
Let $f \colon \Nat \to \Nat$ be a monotone function and $\B B$ a downset located complemented subset of $\Nat$. If $f$ is onto $B^1$, then  $f^{-1}(\B B)$ is also downset located.
\end{proposition}


\begin{proof}
By the hypothesis on $\B B$ we have that $\forall_{y^1 \in B^1}\big(\C D_{\B B}(y^1) \subseteq B^0 \vee \C D_{\B B}(y^1) \between B^1\big)$. Let $x^1 \in f^{-1}(B^1) \TOT f(x^1) \in B^1$. Hence, by the hypothesis on $\B B$ we get
$$\C D_{\B B}(f(x^1)) \subseteq B^0 \ \vee \ \C D_{\B B}f((x^1)) \between B^1.$$
We show that 
$$\C D_{f^{-1}(\B B}(x^1) \subseteq f^{-1}(B^0) \ \vee \ \C D_{f^{-1}(\B B}(x^1) \between f^{-1}(B^1).$$
First, we suppose that $\C D_{\B B}(f(x^1)) \subseteq B^0$ i.e., $\{u \in \dom(\B B) \mid u < f(x^1)\} \subseteq B^0$, and we show that $\C D_{f^{-1}(\B B}(x^1) \subseteq f^{-1}(B^0)$.
For that, let $w \in f^{-1}(B^1) \cup f^{-1}(B^0) \TOT f(w) \in \dom(\B B)$, such that $w < x^1$. By monotonicity of $f$ we get $f(w) < f(x^1)$, and hence $f(w) \in B^0$ i.e., $w \in f^{-1}(B^0)$. Hence, we showed that $\C D_{f^{-1}(\B B}(x^1) \subseteq f^{-1}(B^0)$. Next, we suppose that $\C D_{\B B}f((x^1)) \between B^1$ i.e., there is $u^1 \in B^1$ with $u^1 < f(x^1)$, and we show that $\C D_{f^{-1}(\B B}(x^1) \between f^{-1}(B^1)$ i.e., we find $w \in  f^{-1}(B^1) \cup f^{-1}(B^0)$ with $w < x^1$ and $f(w) \in B^1$. Since $f$ is onto $B^1$, there is $w \in \Nat$, such that $f(w) =_{\Nat} u^1$ i.e., $w \in f^{-1}(B^1)$. By the extensionalty of $<$ we get $f(w) < f(x^1)$, while by the extensionality of $B^1$ we get $f(w) \in B^1$. Since by 
Proposition~\ref{prp: se}(ii) $f$ is strongly monotone, we get $w < x^1$, and $\C D_{f^{-1}(\B B}(x^1) \between f^{-1}(B^1)$ is shown.
\end{proof}


It is also straightforward to show that if $f \colon \Nat \to \Nat$ is monotone, then
$$f\big(\C D_{f^{-1}(\B B}(x)\big) \subseteq \C D_{\B B}(f(x)) \ \ \ \& \ \ \  f^{-1}\big(\C D_{\B B}(f(x))\big) \subseteq \C D_{f^{-1}(\B B}(x).$$








\begin{definition}\label{def: min}
A natural number $\mu$ is a least element\footnote{If $\B A$ is total, then this definition is the complemented subset version of the standard definition of a least element $\mu$ of a subset $A$ of $\Nat$: $\mu \in A \ \& \ \forall_{x \in \Nat}\big(x < \mu \To \neg_{\Nat}(x \in A)\big)$ (see also~\cite{TvD88}, p.~129).} of $\B A$ if and only if 
$$\mu \in A^1 \ \& \ \forall_{x \in \dom(\B A)}\big(x < \mu \To x \in A^0\big).$$
\end{definition}

\begin{corollary}[$\MIN$]\label{cor: min1}
Let $\mu, \nu \in \Nat$, such that $\mu$ and $\nu$ are least elements of $\B A$.\\[1mm]
\normalfont 
(i) \itshape $\forall_{x \in A^1}\big(x \geq \mu\big)$.\\[1mm]
\normalfont (ii) \itshape $\mu =_{\Nat} \nu$.\\[1mm]
\normalfont (iii) \itshape If $0 \in A^1$, then $0$ is the least element of $\B A$.
\end{corollary}

\begin{proof}
(i) If $x \in A^1$, then by dichotomy
 %we have that
  $x < \mu \vee x \geq \mu$. If $x < \mu$, then by the definition of $\mu$ we get $x \in A^0$, hence $x \neq_{\Nat} x$, and consequently $\bot_{\Nat}$. Hence, we get $\neg_{\Nat}(x < \mu)$. Consequently, we get $x \geq \mu$.\\
(ii) As $\mu, \nu \in A^1$, by case (i) we have that $\nu \geq \mu$ and $\mu \geq \nu$, hence $\mu =_{\Nat} \nu$.\\[1mm]
(iii) Let $x \in A^1 \cup A^0$ i.e., $x \in A^1 \vee x \in A^0$. If $x < 0$, then the hypothesis $x \in A^1$ implies by (i) that $x \geq 0$, hence $x < x$ and $x \neq_{\Nat} x$. Consequently, we get $\bot_{\Nat}$ i.e., $\neg_{\Nat}(x \in A^1)$. Thus, $x \in A^0$. 
\end{proof}

The following equivalence is our constructive least number principle $\CLNP$. If $0 \in A^1$, then by Corollary~\ref{cor: min1}(iii) $0$ is the least element of $\B A$. 

\begin{theorem}[$\MIN$]\label{thm: CLNP}
%	Let $\B A$ be inhabited i.e., there is
	Let $a^1 \in A^1$ with $a^1 > 0$. The following are equivalent:\\[1mm]
	\normalfont (i) \itshape $\B A$ has a least element.\\[1mm]
	\normalfont (ii) \itshape $\B A$ is downset located.
\end{theorem}

\begin{proof}
(i) $\To$ (ii): Let $\mu \in A^1$, such that $\forall_{x \in \dom(\B A)}\big(x < \mu \To x \in A^0\big)$.
Let $x^1 \in A^1$. By Corollary~\ref{cor: min1}(i) we get $x^1 \geq \mu$. By (I2) we have that $x^1 =_{\Nat} \mu$ or $x^1 > \mu$. If $x^1 =_{\Nat} \mu$, then by Definition~\ref{def: min} and the extensionality of $<$ we have that $\C D_{\B A}(x^1) =_{\mathsmaller{\mathsmaller{\C E(\Nat})}} \C D_{\B A}(\mu) \subseteq A^0$. If $x^1 > \mu$, then $\mu \in \C D_{\B A}(x^1) \cap A^1$ i.e., $\C D_{\B A}(x^1) \between A^1$.\\
(ii) $\To$ (i) (informally): By hypothesis we have that $\C D_{\B A}(a^1) \subseteq A^0 \vee \C D_{\B A}(a^1) \between A^1$. If $\C D_{\B A}(a^1) \subseteq A^0$, then $a^1$ is the least element of $\B A$. If $\C D_{\B A}(a^1) \between A^1$, let $a^2 \in A^1$ with $a^2 \in \C D_{\B A}(a^1) \cap A^1$ i.e., $a^2 \in A^1$ and $a^2 < a^1$. Again $\C D_{\B A}(a^2) \subseteq A^0 \vee \C D_{\B A}(a^2) \between A^1$, and we repeat the previous argument. After at most $(a^1 + 1)$-number of steps, we will have found the least element of $\B A$. \\
(ii) $\To$ (i) (formally): Let $Q_{\B A}(x) :\TOT x \in A^1$ and $P_{\B A}(x) :\TOT x \in A^1 \ \& \ \C D_{\B A}(x) \subseteq A^0$. By hypothesis we have that $Q_{\B A}(a^1)$. Let $x \in \Nat$ with $x \in A^1$. Since $\B A$ is downset located, we get $\C D_{\B A}(x) \subseteq A^0 \vee \C D_{\B A}(x) \between A^1$. In the first case, we get immediately $P_{\B A}(x)$. In the second case, we get some $y \in \Nat$ with $y < x$ and $y \in A^1 \TOT: Q_{\B A}(y)$. Hence, by $\exists \PWF_{\Nat}$ ther is $x \in \Nat$, such that $x \in A^1$ and $\C D_{\B A}(x) \subseteq A^0$. Clearly, $x$ is then the least element of $\B A$.
\end{proof}

The above proof of the implication (ii) $\To$ (i) can be seen as the constructive content of the corresponding classical proof of the least number principle for an arbitrary non-empty subset of $\Nat$, which employs the principle of the exluded middle. We can also use $\CLNP$ directly, in order to prove Proposition~\ref{prp: prime}. If $n \in \Nat$ with $n > 1$, let $\B P(n) := \big(P^1(n), P^0(n)\big)$, where
$$P^1(n) := \{x > 1 \mid x \mid n \ \& \ \Coprime(x)\}, \ \ \ P^0(n) := \{x > 1 \mid x \mid n \ \& \ \Prime(x)\}.$$
Clearly, $P^1(n) \Disj P^0(n)$. If $\Coprime(n)$, then $n > 0$, and trivially $n \in P^1(n)$. We show that $\B P(n)$ is downset located. If $x^1 \in P^1(n)$, then the disjunction $\C D_{\B P(n)}(x^1) \subseteq P^0 \vee \C D_{\B P(n)}(x^1) \between P^1$ follows by the decidability $(D) \ \forall_{x > 1}(\Prime(x) \vee \Coprime(x))$. By Theorem~\ref{thm: CLNP} $\B P(n)$ has a least element $\mu$ i.e., $\mu \in P^1(n)$ and $\forall_{x \in P^1(n) \cup P^0(n)}\big(x < \mu \To x \in P^0(n)\big)$. Since $\Coprime(\mu)$, there is 
$y \in \Nat$ with $1 < y < \mu$ and $y \mid \mu$. As $\mu \mid n$, we also have that $y \mid n$. By $(D)$ we have that $y \in P^1(n) \cup P^0(n)$. As $y < \mu$, we get $y \in P^0(n)$ i.e., $\Prime(y)$ and $y \mid n$. 










\section{$\exists$-well-founded sets}
\label{sec: wfs}


In this section we generalise the $\exists$-well-foundedness of $\Nat$. As constructively every $\forall$-well-founded set in $\Nat$ is also $\exists$-well-founded, but not necessarily the converse,
it is meaningful to elaborate this coinductive notion of well foundedness independently from the standard inductive one.

%WE NEED TO FIND CAN WE ???? a set which is exists well founded but not forall? May be we cannot exhibit such a set. ?????????? 

\begin{definition}\label{def: rel}
A set with an extensional inequality and relation is a structure $\C X := (X, =_X, \neq_X, <_X)$, where $(X, =_X, \neq_X) \in \SetExtIneq$ and $x <_X x{'}$ is an extensional binary relation on $X$. We call $\C X$ dichotomous if $\forall_{x, x{'} \in X}\big(x \neq_X x{'} \To (x <_X x{'} \vee x{'} <_X x)\big)$, and we call $\C X$ strong if $\forall_{x, x{'} \in X}\big(x <_X x{'} \To x \neq_X x{'}\big)$. Let $(\SetExtIneqRel, \StrExtFunRel)$ be the category of sets with an extensional inequality and relation and of strongly extensional functions that preserve the corresponding relations i.e., if $\C Y := (Y, =_Y, \neq_Y, <_Y)$ is in $\SetExtIneqRel$ and $f \colon X \to Y$ is in $\StrExtFun$, we also have that $\forall_{x, x{'} \in X}\big(x <_X x{'} \To f(x) <_Y f(x{'})\big)$.
\end{definition}

By definition, $(\SetExtIneqRel, \StrExtFunRel) \leq (\SetExtIneq, \StrExtFun)$. By properties (I3, I4) in section~\ref{sec: nat} $\C N := (\Nat, =_{\Nat}, \neq_{\Nat}, <_{\Nat})$ is in $\SetExtIneqRel$ that is also strong and dichotomous. 

%Some remarks on the relation ....




\begin{definition}[$\exists$-well-founded sets]\label{def: ewfs}
Let $\C X := (X, =_X, \neq_X, <_X)$ be in $\SetExtIneqRel$. We say that $\C X$ is an $\exists$-well-founded set $(\exists$-$\wfs)$ if it satisfies the scheme $\exists \PWF_X:$ for every extensional\footnote{The hypothesis of extensionality on $Q(x)$ and $P(x)$ is crucial in the proof of Proposition~\ref{prp: sigmaset}.} formulas $Q(x), P(x)$ on $X$ with 
$$Q(x) \stackrel{\mathsmaller{<_X}} \To P(x) :\TOT \forall_{x \in X}\big(Q(x) \To [P(x) \vee \exists_{x{'} \in X}(x{'} <_X x \ \& \ Q(x{'})]\big),$$
then 
$$\exists_{x \in X}Q(x) \To \exists_{x \in X}P(x).$$
Let $(\exists \WFSet, \StrExtFunRel)$ be the category of $\exists$-$\wfs$ and of strongly extensional functions that preserve the given extensional relations. We call $\C X$ a $\forall$-well-founded set $(\forall$-$\wfs)$ if it satisfies the scheme of $\forall$-well-founded induction $\forall \PWF_X$. 
% instead of $\exists \PWF_X$.
\end{definition}


By $\exists \PWF_{\Nat}$  the above structure of naturals $\C N$ is an $\exists$-$\wfs$. Recall that $\C N$ is a $\forall$-$\wfs$ within $\INT$. Next, we prove some fundamental results on $\exists$-well-founded sets that also hold constructively for $\forall$-well-founded sets (see~\cite{MRR88, RS93}). Our proofs are interesting because they show that our notion of well-foundedness is sufficient and they provide a new algorithmic content of these results.
A subset $A$ of $X$, where $\C X \in \SetExtIneqRel$ \textit{has no minimal elements} if $\forall_{x \in A}\exists{y \in A}(y <_X x)$. As expected, we define the non-existence of minimal elements in a positive way, in order to avoid weak negation. All basic set-theoretic definitions on $\Nat$ that are included in section~\ref{sec: nat} are extended to arbitrary sets. For example, $A$ is strongly empty if $A \subseteq \emptys_X := \{x \in X \mid x \neq_X x\}$.



\begin{proposition}\label{prp: basic1}
Let $\C X := (X, =_X, <_X)$ be an $\exists$-$\wfs$, and let $A \subseteq X$.\\[1mm]
\normalfont (i)
\itshape $\forall_{x \in X}\big(\neg_{\Nat}(x <_X x)\big)$.\\[1mm]
\normalfont (ii)
\itshape If $A$ has no minimal elements, then $A$ is strongly empty.\\[1mm]
\normalfont (iii)
\itshape If $(x_n)_{n \in \Nat}$ is an infinite descending sequence in $X$, then $A := \{x_n \mid n \in \Nat\}$ is strongly empty.
\end{proposition}


\begin{proof}
(i) Let the extensional relations $Q(x) :\TOT x <_X x$ and $P(x) :\TOT \bot_{\Nat}$ on $X$. We show that
$Q(x) \stackrel{\mathsmaller{<_X}} \To P(x)$. If $x \in X$, such that $x <_X x$, then $\exists_{x{'} < x}(Q(x{'}))$, since we can take $x$ again. By $\exists \PWF_X$, if we suppose that there is $x_0 \in X$ with $x_0 <_X x_0$, then we get $\exists_{x \in X}\bot_{\Nat}$, and hence we get $\bot_{\Nat}$.\\
(ii) If $x_0 \in A$, let the extensional relations $Q_A(x)$, where $A := \{x \in X \mid Q_A(x)\}$  and $P(x) :\TOT x =_X x_0 \ \& \ x \neq_X x$ on $X$. We show that
$Q_A(x) \stackrel{\mathsmaller{<_X}} \To P_A(x)$. If $x \in X$, such that $x \in A$, since $A$ has no minimal elements there is $y < A$ with $y <_X x$ i.e., $\exists_{y <_X x}Q_A(y)$. By $\exists \PWF_X$ we get $\exists_{x \in X}(x =_X x_0 \ \& \ x \neq_X x)$. Hence by the extensionality of $\neq_X$ we conclude that $x_0 \neq_X x_0$ i.e., $x_0 \in \emptys_X$.\\
(iii) It follows immediately from case s (ii).
\end{proof}






If $\C X := (X, =_X, \neq_X, <_X) \in \SetExtIneqRel$ and $P(x)$ is an extensional formula on $X$, let the standard $\forall$-formulation of the well-foundedness of $\C X$:
$$(\forall \PWF_X) \ \ \ \ \ \ \ \ \ \ \ \ \ \ \ \ \ \ \ \ \ \ \ 
\forall_{x \in X}\big(\forall_{x{'} <_X x}P(x{'}) \To P(x)\big) \To \forall_{x \in X}P(x), \ \ \ \ \ \ \ \ \ \ \ \ \ \ \ \ \ \ \ \ \ \ \ \ \ \ \ \ \ \ \  \ \ \ \ \ \ \ \ \ \ \ \ \ \ \ \ \ \ \ $$
In~\cite{MRR88}, pp.~28-29, the following $(\forall, \vee)$-well-foundedness is given:
$$(\forall,\vee)-(\PWF_X) \ \ \ \ \ \ \ \ \ \ \ \ \ \ \ \ \ \ \ \ \ \ \ \forall_{x \in X}\big(P(x) \vee \exists_{x{'} <_X x}(P(x{'}) \To P(x)\big) \To \forall_{x \in X}P(x). \ \ \ \ \ \ \ \ \ \ \  \ \ \ \ \ \ \ \ \ \ \ \ \ \ \ \ \ \ $$



\begin{proposition}\label{prp: basic2}
	Let $\C X := (X, =_X, <_X)$, $\C Y := (Y, =_Y, <_Y)$ be in $\exists$-$\WFSet$, and let $A \subseteq X$.\\[1mm]
	\normalfont (i)
	If $\C Z := (Z, =_Z, \neq_Z,<_Z) \in\SetExtIneqRel$ and $f \colon Z \to X \in \StrExtFunRel$, then $\C Z$ is an $\exists$-$\wfs$. If $\C X$ is strong, then $\C Z$ is strong.\\[1mm]
	\normalfont (ii)
	\itshape If $=_A$ and $<_A$ are the restrictions of $=_X$ and $<_X$, respectively, then $\C A := (A =_A, <_A)$ is an $\exists$-$\wfs$.\\[1mm]
	\normalfont (iii)
	\itshape The product $\C X \times \C Y := (X \times Y, =_{X \times Y},\neq_{X \times Y}, <_{X \times Y})$, where 
	$$(x, y) \neq_{X \times Y} (x{'}, y{'}) :\TOT x \neq_X x{'} \vee y <_Y y{'},$$
	$$(x, y) <_{X \times Y} (x{'}, y{'}) :\TOT x <_X x{'} \ \& \ y <_Y y{'},$$
	is an $\exists$-$\wfs$. If $\C X$, or $\C Y$, is strong, then  $\C X \times \C Y$ is strong.\\[1mm]
	\normalfont (iv) 
	\itshape The sum $\C X + \C Y := (X + Y, =_{X + Y}, \neq_{X + Y}, <_{X + Y})$, where
	$$w \in X + Y :\TOT \exists_{x \in X}\big(w := (0, x)\big) \vee \exists_{y \in Y}\big(w := (1, y)\big),$$
	$$(i, z) =_{X + Y} (j, u) :\TOT (i =_{\D 2} j =_{\D 2} 0 \ \wedge \ z =_{X} u) \vee (i =_{\D 2} j =_{\D 2} 1 \ \wedge \ z =_{Y} u),$$
	$$(i, z) \neq_{X + Y} (j, u) :\TOT i \neq_{\D 2} j \vee (i =_{\D 2} j =_{\D 2} 0 \ \& \ z \neq_X u) \vee (i =_{\D 2} j =_{\D 2} 1 \ \& \ z \neq_Y u),$$
	$$(i, z) <_{X + Y} (j, u) :\TOT i <_{\D 2} j \vee (i =_{\D 2} j =_{\D 2} 0 \ \& \ z <_X u) \vee (i =_{\D 2} j =_{\D 2} 1 \ \& \ z <_Y u),$$
	is an $\exists$-$\wfs$.  If $\C X$ and $\C Y$ are strong $($dichotomous$)$, then  $\C X + \C Y$ is strong $($dichotomous$)$.

\end{proposition}


\begin{proof}
(i) Let $Q_Z(z)$ and $P_Z(z)$ be extensional formulas on $Z$, such that 
$$Q_Z(z) \stackrel{\mathsmaller{\mathsmaller{\mathsmaller{<_{Z}}}}} \Rightarrow P_Z(z) :\TOT \forall_{z \in Z}\big(Q_Z(z) \To \big[P_Z(z) \vee  \exists_{z{'} <_Z z}Q_Z(z{'})\big]\big).$$
We define the following extensional relations on $X$:
$$Q_{f, X}(x) :\TOT \exists_{z \in Z}\big(f(z) =_X x \ \& \ Q_Z(z)\big),$$
$$P_{f, X}(x) :\TOT \exists_{z \in Z}\big(f(z) =_X x \ \& \ P_Z(z)\big),$$
and we show that 
$$Q_{f,X}(x) \stackrel{\mathsmaller{\mathsmaller{\mathsmaller{<_{X}}}}} \Rightarrow P_{f,X}(x) :\TOT \forall_{x \in X}\big(Q_{f,X}(x) \To \big[P_{f,X}(x) \vee  \exists_{x{'} <_X x}Q_{f,X}(x{'})\big]\big).$$
Let $x \in X$ and $z \in Z$, such that $f(z) =_X x$ and $Q_Z(z)$. If $P_Z(z)$, then we get $P_{f,X}(x)$. If $z{'} <_Z z$ with $Q_Z(z{'})$, let $x{'} := f(z{'}) \in X$. Since $f$ respects the relations, we get $x{'} := f(z{'}) <_X f(z) =_X x$ and $Q_{f,X}(x{'})$. Next we suppose that $\exists_{z \in Z}Q_Z(z)$, hence $\exists_{x \in X}Q_{f,X}(x)$. By $\exists$-$\PWF_X$ we get $\exists_{x \in X}P_{f,X}(x)$, hence $\exists_{z \in Z}P_Z(z)$. Moreover, if $z <_Z z{'}$, then $f(z) <_X f(z{'})$, and since $\C X$ is strong, we get $f(z) \neq_X f(z{'})$. Since $f$ is strongly extensional, we get $z \neq_Z z{'}$, and hence $\C Z$ is strong.\\
(ii) It follows from case (i), since the embedding of $A$ into $X$ is in $\StrExtFunRel$.\\
(iii)  It follows from case (i), since the projection function\footnote{Notice that in the case of the product it suffices one of the two sets to be an $\exists$-$\wfs$.} $\pr_X \colon X \times Y \to X$ is in $\StrExtFunRel$.\\
(iv) We only prove that $\exists \PWF_{X + Y}$. Let $Q(w)$ and $P(w)$ be extensional formulas on $X + Y$, such that 
$Q(w) \stackrel{\mathsmaller{\mathsmaller{\mathsmaller{<_{X+Y}}}}} \Longrightarrow P(w)$. Suppose first that there is $x_0 \in X$ with $Q((0, x_0))$. Let $P_X(x) :\TOT P((0,x))$ and $Q_X(x) :\TOT Q((0,x))$ formulas on $X$. Clearly, the extensionality of $P$ and $Q$ implies the extensionality of $P_X$ and $Q_X$, respectively. We show that $Q_X(x) \stackrel{\mathsmaller{\mathsmaller{\mathsmaller{<_{X}}}}} \To P_X(x)$. Let $x \in X$ with $Q_X(x)$. By the hypothesis $Q(w) \stackrel{\mathsmaller{\mathsmaller{\mathsmaller{<_{X+Y}}}}} \Longrightarrow P(w)$ we get
$$P((0, x)) \TOT: P_X(x) \ \vee \ \exists_{(j, u) \in X+Y}\big((j, u) <_{\mathsmaller{X+Y}} (0, x) \ \& \ Q((j, u))\big).$$
If the right disjunct holds, then $j =_{\D 2} 0$, as $j <_{\D 2} 0 \To \bot_{\Nat}$, and $u <_X x$ with $Q((0, u))$. Hence, $Q_X(x) \stackrel{\mathsmaller{\mathsmaller{\mathsmaller{<_{X}}}}} \To P_X(x)$ is shown. As $Q((0, x_0)) \To \exists_{x \in X}Q_X(x)$, by $\exists \PWF_X$ we get $\exists_{x \in X}P_X(x)$, thus $\exists_{w \in X+Y}Q(w)$. Next we suppose that there is $y_0 \in Y$ with $Q(1, y_0)$. Let the following extensional formulas on $Y$:
$$P_Y(y) :\TOT P((1,y)) \vee \exists_{x \in X}Q((0, x)), \ \ \ \ Q_y(y) :\TOT Q((1,y)).$$ 
%	formulas on $Y$. 
	%Clearly, the extensionality of $P$ and $Q$ implies the extensionality of $P_Y$ and $Q_Y$, respectively. 
We show that $Q_Y(y) \stackrel{\mathsmaller{\mathsmaller{\mathsmaller{<_{Y}}}}} \To P_Y(y)$. 
Let $y \in Y$ with $Q_Y(y)$. By the hypothesis $Q(w) \stackrel{\mathsmaller{\mathsmaller{\mathsmaller{<_{X+Y}}}}} \Longrightarrow P(w)$ we get
$$P((1, y)) \ \vee \ \exists_{(j, u) \in X+Y}\big((j, u) <_{\mathsmaller{X+Y}} (1, y) \ \& \ Q((j, u))\big).$$
Trivially, $P((1, y)) \To P_Y(y)$. If the right disjunct holds, then let first the case $j =_{\D 2} 0$ and $u \in X$, such that $Q((0, u))$. Hence, $\exists_{x \in X}Q((0, x))$, and trivially $\exists_{x \in X}Q((0, x)) \To P_Y(y)$. The other case is that $j =_{\D 2} 1$ and $u \in Y$, such that $u <_Y y$ and $Q((1, u)) \TOT: Q_Y(u)$. Hence, $Q_Y(y) \stackrel{\mathsmaller{\mathsmaller{\mathsmaller{<_{Y}}}}} \To P_Y(y)$ is shown. As $Q((1, y_0)) \To \exists_{y \in Y}Q_Y(y)$, by $\exists \PWF_Y$ we get $\exists_{y \in Y}P_Y(y)$. Thus either there is $y \in Y$ with $P((1,y))$, hence $\exists_{w \in X+Y}P(w)$, or $\exists_{x \in X}Q((0, x))$. In the latter case we work as in the first part of the proof. The last part of case (iv) is straightforward to show.
% :\TOT \forall_{x \in X}\big(Q(x) \To [P(x) \vee \exists_{x{'} \in X}(x{'} <_X x \ \& \ Q(x{'})]\big),$$
\end{proof}


By Proposition~\ref{prp: basic2}(ii) the structure of booleans $\C B := (\D 2, =_{\D 2}, \neq_{\D 2}, <_{\D 2})$ is in $\exists \WFSet$. Clearly, the projections $\pr_X \colon X \times Y \to X$ and $\pr_Y \colon X \times Y \to Y$ are in $\StrExtFunRel$ and $\C X \times \C Y$ is a product of 
$\C X$ and $\C Y$ in $(\exists \WFSet, \StrExtFunRel)$. Similarly, the injections $\inj_X \colon X \to X + Y$ and $\inj_Y \colon Y \to X + Y$ are in $\StrExtFunRel$ and $\C X + \C Y$ is a coproduct of 
$\C X$ and $\C Y$ in $(\exists \WFSet, \StrExtFunRel)$. Next, we show that the product of two $\exists$-$\wfs$ with the lexicographic order is an $\exists$-$\wfs$.

\begin{proposition}\label{prp: lex}
Let $\C X := (X, =_X, <_X)$, $\C Y := (Y, =_Y, <_Y)$ be in $\exists$-$\WFSet$, and let
$$(x, y) <_{\mathsmaller{\lex}} (x{'}, y{'}) :\TOT x <_X x{'} \vee (x =_X x{'} \ \& \ y <_Y y{'}).$$
\normalfont (i)
\itshape $\C X \times_{\lex} \C Y := (X \times Y, =_{X \times Y}, \neq_{X \times Y}, <_{\mathsmaller{\lex}})$ is an $\exists$-$\wfs$.\\[1mm]
 \normalfont (ii)
 \itshape If $\C X$ and $\C Y$ are strong, then $\C X \times_{\mathsmaller{\lex}} \C Y$ is strong.\\[1mm]
  \normalfont (iii)
 \itshape If $\C X \times_{\mathsmaller{\lex}} \C Y$ is strong and $X, Y$ are inhabited, then $\C X$ and $\C Y$ are strong.\\[1mm]
   \normalfont (iv)
 \itshape If $\C X \times_{\mathsmaller{\lex}} \C Y$ is dichotomous and $X, Y$ are inhabited, then $\C X$ and $\C Y$ are dichotomous.
\end{proposition}


\begin{proof}
(i) Clearly, the extensionality of $<_X$ and $<_Y$ imply the extensionality of $<_{\mathsmaller{\lex}}$. Let $Q((x, y))$ and $P((x,y))$ extensional formulas on $X \times Y$, such that
$$Q((x,y)) \stackrel{\mathsmaller{\mathsmaller{\mathsmaller{<_{\lex}}}}} \Rightarrow P(x,y) :\TOT \forall_{(x,y) \in X \times Y}\big(Q((x,y)) \To \big[P((x,y)) \vee  \exists_{(x{'}, y{'}) <_{\mathsmaller{\lex}} (x,y)}Q((x{'}, y{'}))\big]\big).$$
We suppose that $\exists_{(x, y) \in X \times Y}Q((x,y))$, and we show that $\exists_{(x, y) \in X \times Y}P((x,y))$. Let $(x_0, y_0) \in X \times Y$, such that $Q((x_0,y_0))$. Let the following extensional formulas on $Y$:
$$Q_Y(y) :\TOT Q((x_0, y)),$$
$$P_Y(y) :\TOT P((x_0, y)) \vee \exists_{x <_X x_0}\exists_{z \in Y}Q((x, z)).$$
Since $Q((x_0, y_0))$, we have that $\exists_{y \in Y}Q_Y(y)$ holds. Next we show that 
$$Q_Y(y) \stackrel{\mathsmaller{\mathsmaller{\mathsmaller{<_{Y}}}}} \Rightarrow P_Y(y) :\TOT \forall_{y \in Y}\big(Q_Y(y) \To \big[P_Y(y) \vee \exists_{y{'} <_Y y}Q_Y(y{'})\big]\big).$$
Let $y \in Y$, such that $Q(x_0, y)$. By the hypothesis $Q((x,y)) \stackrel{\mathsmaller{\mathsmaller{\mathsmaller{<_{\lex}}}}} \Rightarrow P(x,y)$ we get
$$P((x_0,y))  \vee \exists_{(x{'}, y{'}) \in X \times Y}(x{'} <_X x_0 \ \& \ Q(x{'}, y{'})) \vee \exists_{(x{'}, y{'}) \in X \times Y}(x{'} =_X x_0 \ \& \ y{'} <_Y y \ \& \ Q(x{'}, y{'})).$$
The first two disjuncts trivially imply $P_Y(y)$, while the last disjunct, together with the extensionality of $Q$ imply $ \exists_{y{'} <_Y y}Q((x_0, y{'}))$ i.e.,  $\exists_{y{'} <_Y y}Q_Y(y{'})$. Since $\C Y$ is an $\exists$-$\wfs$, we get 
$$\exists_{y \in Y}P_Y(y) :\TOT \exists_{y \in Y}\big(P((x_0, y)) \vee \exists_{x <_X x_0}\exists_{z \in Y}Q((x, z))\big),$$
and hence
$$\exists_{y \in Y}P((x_0, y)) \vee \exists_{x <_X x_0}\exists_{y \in Y}Q((x, y)).$$
If $\exists_{y \in Y}P((x_0, y))$, then $\exists_{(x, y) \in X \times Y}P((x,y))$ holds. If $\exists_{x <_X x_0}\exists_{y \in Y}Q((x, y))$, we use $\exists \PWF_X$ as follows. Let the following extensional formulas on $X$:
$$Q_X(x) :\TOT \exists_{y \in Y}Q((x, y)),$$
$$P_X(x) :\TOT \exists_{y \in Y}P((x, y)).$$
We show that
$$Q_X(x) \stackrel{\mathsmaller{\mathsmaller{\mathsmaller{<_{X}}}}} \Rightarrow P_X(x) :\TOT \forall_{x \in X}\big(Q_X(x) \To \big[P_X(x) \vee \exists_{x{'} <_X x}Q_X(x{'})\big]\big).$$
I.e., if $x \in X$, we show that 
$$\exists_{y \in Y}Q((x, y)) \To \big[\exists_{y \in Y}P((x, y)) \vee \exists_{x{'} <_X x}\exists_{y \in Y}Q((x{'}, y))\big].$$
But what we showed in the first part of our proof was the implication
$$\exists_{y \in Y}Q((x_0, y)) \To \big[\exists_{y \in Y}P((x_0, y)) \vee \exists_{x{'} <_X x_0}\exists_{y \in Y}Q((x{'}, y))\big].$$
Since $x_0$ is arbitrary, the required implication follows in the same way. As $\exists_{x \in X}Q_X(x)$ holds by our intitial hypothesis on $Q((x,y))$, by $\exists \PWF_X$ we get $\exists_{x \in X}P_X(x)$, and hence $\exists_{(x, y) \in X \times Y}P((x,y))$.\\
Cases (i)-(iv) follow in a straightforward manner.
\end{proof}

Notice that the projections on $\C X \times_{\mathsmaller{\lex}} \C Y$ are not in $\StrExtFunRel$. 
%We do not see how one can prove Proposition~\ref{prp: lex}(i) starting with $\exists \PWF_X$. 
%In~\cite{RS93}, p.~149,  $\forall \PWF_Y$ is also used first.
It is also immediate to see that the converse to Proposition~\ref{prp: lex}(iv) does not hold, in general.

Proposition~\ref{prp: basic2}(iv) is generalised to the exterior union, or the Sigma-set of a family of $\exists$-$\wfs$ over an index set which is also an $\exists$-$\wfs$. We include both proofs, because they are instructive. First we give the fundamental definition of an indexed family of sets in $(\SetIneq, \StrExtFun)$. A family of sets  indexed by some set $(I, =_I)$ is an
%non-dependent
assignment routine $\chi_0 : I \sto \D V_0$ that 
behaves like a function, that is if $i =_I j$, then $\chi_0(i) =_{\D V_0} \chi_0 (j)$.
A more explicit definition, which is due to Richman, is included in~\cite{BB85},
p.~78 (Problem 2), which is made precise in~\cite{Pe20} by highlighting 
the role of dependent assignment routines in its formulation. In accordance to the second
attitude described in the Introduction, 
this is a proof-relevant definition revealing the witnesses of the 
equality $\chi_0(i) =_{\D V_0} \chi_0 (j)$. In the following definition $\D V_0^{\neq, <}$ is the universe of sets with an extensional inequality and relation, and $\D F^{\neq, <}$ is the set of functions in $\StrExtFunRel$ from $\C X$ to $\C Y$ in $\SetExtIneqRel$. For the notion of a (non-dependent, or dependent) assignment routine, we refer to~\cite{Pe20}.



\begin{definition}\label{def: famofsets}
	If $\C I := (I, =_I, \neq_I, <_I)$ is in $\SetExtIneqRel$, let the \textit{diagonal} $D(I) := \{(i,j) \in I \times I \mid i =_I j\}$ of $I$.
	A \textit{family of sets} in $(\SetExtIneqRel, \StrExtFunRel)$ indexed by $\C I$
	is a pair $\C X := (\chi_0, \chi_1)$, where
	$\chi_0 \colon I \sto \D V_0^{\neq, <}$ and
	$$\C X (i) := \big(\chi_0(i), =_{\chi_0(i)}, \neq_{\chi_0(i)}, <_{\chi_0(i)}\big),$$
	for every $i \in I$,
	and\index{$\chi_1$} $\chi_1$, a
	\textit{modulus of function-likeness for}\index{modulus of function-likeness} $\chi_0$, is 
	a dependent operation
	\[ \chi_1 \colon \bigcurlywedge_{(i, j) \in D(I)}\D F^{\neq, <}\big(\chi_0(i), \chi_0(j)\big), 
	\ \ \ \chi_1(i, j) =: \chi_{ij} \colon \chi_0(i) \to \chi_0(j), \ \ \ (i, j) \in D(I), \]
	such that the \textit{transport maps}\index{transport map of a family of sets} $\chi_{ij}$
	\index{transport map of a family of sets}\index{$\chi_{ij}$}
	of $\boldmath \chi$ satisfy the following conditions:\\[1mm]
	\normalfont (a) 
	\itshape For every $i \in I$, we have that $\chi_{ii} = \id_{\chi_0(i)}$.\\[1mm]
	\normalfont (b) 
	\itshape If $i =_I j$ and $j =_I k$, the following triangle commutes
	\begin{center}
		\begin{tikzpicture}

			\node (E) at (0,0) {$\chi_0(j)$};
			\node[right=of E] (F) {$\chi_0(k).$};
			%\node[above=of F] (A) {$B$};
			\node [above=of E] (D) {$\chi_0(i)$};
			%\node [below=of D] (G) {$V$};


			\draw[->] (E)--(F) node [midway,below] {$\chi_{jk}$};
			%\draw[->] (D)--(A) node [midway,above] {$f $};
			\draw[->] (D)--(E) node [midway,left] {$\chi_{ij}$};
			\draw[->] (D)--(F) node [midway,right] {$\ \chi_{ik}$};
			%\draw[->] (D)--(E) node [midway,left] {$f$};


		\end{tikzpicture}
	\end{center}
	%$I$ is the \textit{index-set}\index{index-set} of the family $\Lambda$.
	%$i =_I j$, we call $\lambda_{ij}$\index{$\lambda_{ij}$} the 
	%\textit{transport map}\index{transport map} from $\lambda_0 (i)$ to $\chi_0 (j)$. 
	If $\C X, \C Y$ are in $\SetExtIneqRel$, the \textit{constant} $\C I$-\textit{family of sets}
	$\C X$is the pair 
	$(\chi_0^X, \chi_1^X)$, where $\chi_0 (i) := X$, for every 
	$i \in I$, and $\chi_1 (i, j) := \id_X$, for every $(i, j) \in D(I)$. 
	% If $\B 2 := \big(\D 2 := \{0, 1\},
	% =_{\D 2}, \neq_{\D 2}\big)$,
	%equipped with the obvious equality and inequality,
	The $\D 2$-family of $\C X$ and $\C Y$ in $\SetExtIneqRel$ is defined by $\chi_0 (0) := \C X$, 
	$\chi_0 (1) := \C Y$, $\chi_{00} := \id_X$ and $\chi_{11} := \id_Y$.
\end{definition}


If $i =_I j$, then $(\chi_{ij}, \chi_{ji}) \colon \chi_0(i) =_{\D V_0^{\neq, <}} \chi_0(j)$.
Next we describe the Sigma-set (or the exterior union, or the disjoint union) of a given family of sets 
in $(\SetExtIneqRel, \StrExtFunRel)$.



\begin{proposition}\label{prp: sigmaset}
	Let $\C X := (\chi_0, \chi_1)$ be an $\C I$-family of sets in $(\SetExtIneqRel, \StrExtFunRel)$. Its Sigma-set is the structure 
	$$\sum_{i \in I}\C X_i := \bigg(\sum_{i \in I}\chi_0 (i), =_{\mathsmaller{\sum_{i \in I}\chi_0 (i)}}, 
	\neq_{\mathsmaller{\sum_{i \in I}\chi_0 (i)}}, <_{\mathsmaller{\sum_{i \in I}\chi_0 (i)}}\bigg),$$
	%of $\boldmath \Lambda$
	%and its canonical equality
	where
	\[ w \in \sum_{i \in I}\chi_0 (i) : 
	\TOT \exists_{i \in I}\exists_{x \in \chi_0 (i)}\big(w := (i, x)\big), \]
	\[ (i, x) =_{\mathsmaller{\sum_{i \in I}\chi_0 (i)}} (j, y) : \TOT i =_I j \ \& \ \chi_{ij} (x) 
	=_{\chi_0 (j)} y,\]
	\[(i,x) \neq_{\mathsmaller{\sum_{i \in I}\chi_0 (i)}} (j, y) :\TOT i \neq_I j  \vee  \big(i =_I j \ \& \ 
	\chi_{ij}(x) \neq_{\chi_0(j)} y \big), \]
		\[(i,x) <_{\mathsmaller{\sum_{i \in I}\chi_0 (i)}} (j, y) :\TOT i <_I j  \vee  \big(i =_I j \ \& \ 
	\chi_{ij}(x) <_{\chi_0(j)} y \big). \]
	\normalfont (i)
	\itshape Then $\sum_{i \in I}\C X_i$ is in $\SetExtIneqRel$ and its first projection $\pr_1^{\C X} \colon \sum_{i \in I}\chi_0 (i) \sto I,$ defined by the rule\footnote{The global projection operations $\prb_1$ and $\prb_2$ are primitive operations in $\BST$.}
	$\pr_1^{\C X} (i, x) : = \prb_1 (i, x) := i$, is in $\StrExtFun$, but not in $\StrExtFunRel$. \\[1mm]
	\normalfont (ii)
\itshape If $\C I$ and every $\C X_i$ are strong $($dichotomous$)$, then $\sum_{i \in I}\C X_i$ is strong $($dichotomous$)$. \\[1mm]
	\normalfont (iii)
\itshape If $\C I$ and every $\C X_i$ are in $\exists \WFSet$, then $\sum_{i \in I}\C X_i$ is in $\exists \WFSet$.
\end{proposition}



\begin{proof}
(i) We show that $<_{\mathsmaller{\sum_{i \in I}\chi_0 (i)}}$ is extensional. If
	\[ (i, x) =_{\mathsmaller{\sum_{i \in I}\chi_0 (i)}} (i{'}, x{'}) : \TOT i =_I i{'} \ \& \ \chi_{ii{'}} (x) 
=_{\chi_0 (i{'})} x{'},\]
	\[ (j, y) =_{\mathsmaller{\sum_{i \in I}\chi_0 (i)}} (j{'}, y{'}) : \TOT j =_I j{'} \ \& \ \chi_{jj{'}} (y) 
=_{\chi_0 (j{'})} y{'},\]
\[(i,x) <_{\mathsmaller{\sum_{i \in I}\chi_0 (i)}} (j, y) :\TOT i <_I j  \vee  \big(i =_I j \ \& \ 
\chi_{ij}(x) <_{\chi_0(j)} y \big),\]
then we show that
\[(i{'},x{'}) <_{\mathsmaller{\sum_{i \in I}\chi_0 (i)}} (j{'}, y{'}) :\TOT i{'} <_I j{'} \vee  \big(i{'} =_I j{'} \ \& \ 
\chi_{i{'}j{'}}(x{'}) <_{\chi_0(j{'})} y{'} \big).\]
If $i <_I j$, then we get $i{'} <_I j{'}$ by the extensionality of $<_I$. If $i =_I j \ \& \ 
\chi_{ij}(x) <_{\chi_0(j)} y$, then we get trivially that $i{'} =_I j{'}$. To show $\chi_{i{'}j{'}}(x{'}) <_{\chi_0(j{'})} y{'}$, we 
first
observe that by Definition~\ref{def: famofsets} we have that
$$\chi_{i{'}j{'}}(x{'}) =_{\chi_0 (j{'})} \chi_{i{'}j{'}}\big(\chi_{ii{'}} (x)\big) =_{\chi_0 (j{'})} \chi_{ij{'}} (x).$$
Since the transport maps preserve the corresponding relations, we have that
$$\chi_{ij}(x) <_{\chi_0(j)} y \To \chi_{jj{'}}\big(\chi_{ij}(x)\big) <_{\chi_0(j{'})} \chi_{jj{'}}(y) \TOT 
\chi_{ij{'}} (x) <_{\chi_0(j{'})} y \TOT \chi_{i{'}j{'}}(x{'}) <_{\chi_0(j{'})} y{'}.$$
The extensionality of $\neq_{\mathsmaller{\sum_{i \in I}\chi_0 (i)}}$ is shown similarly. The assignment routine $\pr_1^{\C X}$ is trivially a strongly extensional function, but it does not preserve, in general, the corresponding relations. If $(i,x) <_{\mathsmaller{\sum_{i \in I}\chi_0 (i)}} (j, y)$ because $i =_I j \ \& \ 
\chi_{ij}(x) <_{\chi_0(j)} y$, then by the extensionality of $<_I$ and Proposition~\ref{prp: basic1}(i) we get
$$\pr_1^{\C X}((i, x)) <_I \pr_1^{\C X}((y, w)) :\TOT i <_I j \To i <_I i \To \bot_{\Nat}.$$
(ii) We only show that $\sum_{i \in I}\C X_i$ is dichotomous. Let $(i,x) \neq_{\mathsmaller{\sum_{i \in I}\chi_0 (i)}} (j, y)$. If $i \neq_i j$, then, since $\C I$ is dichotomous, we get $i <_I j$ or $j <_I i$, and hence $(i,x) <_{\mathsmaller{\sum_{i \in I}\chi_0 (i)}} (j, y)$ or $(j,y) <_{\mathsmaller{\sum_{i \in I}\chi_0 (i)}} (i, x)$. If $i =_I j$ and $\chi_{ij}(x) \neq_{\chi_0(j)} y$, then, since $\C X_j$ is dichotomous, we get $\chi_{ij}(x) <_{\chi_0(j)} y$, and hence $(i,x) <_{\mathsmaller{\sum_{i \in I}\chi_0 (i)}} (j, y)$ or $y <_{\chi_0(j)} \chi_{ij}(x)$, and hence $(j,y) <_{\mathsmaller{\sum_{i \in I}\chi_0 (i)}} (i, x)$, since.
$$y <_{\chi_0(j)} \chi_{ij}(x) \To \chi_{ji}(y) <_{\chi_0(i)}  \chi_{ji}\big(\chi_{ij}(x)\big) \TOT \chi_{ji}(y) <_{\chi_0(i)} \chi_{ii}(x) \TOT \chi_{ji}(y) <_{\chi_0(i)} x.$$
(iii) Let extensional formulas $Q(w)$ and $P(w)$ on $\sum_{i \in I}\chi_0 (i)$, such that $Q(w) \stackrel{\mathsmaller{\mathsmaller{\mathsmaller{<_{\sum_{i \in I}\chi_0(i)}}}}} \Longrightarrow P(w)$. Let also $(i_0, x_0) \in \sum_{i \in I}\chi_0(i)$, such that $Q((i, x_0))$. Let the extensional formulas $Q_{i_0}(x) :\TOT Q((i_0, x))$ and 
$$P_{i_0}(x) :\TOT P((i_0, x)) \vee \exists_{i <_I i_{0}}\exists_{x{'} \in \chi_0(i)}Q((i, x{'}))$$
 on $\chi_0(i_0)$. We show that $Q_{i_0}(x) \stackrel{\mathsmaller{\mathsmaller{\mathsmaller{<_{\chi_0(i_0)}}}}} \Longrightarrow P_{i_0}(x)$. If $x \in \chi_0(i_0)$, such that $Q((i_0, x))$, then by our hypothesis $Q(w) \stackrel{\mathsmaller{\mathsmaller{\mathsmaller{<_{\sum_{i \in I}\chi_0(i)}}}}} \Longrightarrow P(w)$ we get $P((i_0, x))$ or there is $(i, x{'}) \in \sum_{i \in I}\chi_0(i)$ with $(i, x{'}) <_{\mathsmaller{\sum_{i \in I}\chi_0(i)}} (i_0, x)$ and $Q((i, x{'}))$. In the latter case, either $i <_I i_0$ with $Q((i, x{'}))$ or $i =_I i_0$ and $\chi_{ii_0}(x{'}) <_{\mathsmaller{\chi_0(i_0)}} x$ with $Q((i, x{'}))$. The first two cases trivially imply $P_{i_0}(x)$. By the extensionality of $Q(w)$ we have that
 $$\big[(i, x{'}) =_{\mathsmaller{\sum_{i \in I}\chi_0(i)}} \big(i_0, \chi_{ii_0}(x{'}\big) \ \& \ Q((i, x{'}))\big] \To Q\big(\big(i_0, \chi_{ii_0}(x{'})\big)\big),$$
and hence $Q_{i_0}(\chi_{ii_0}(x{'}))$. Since $\C X_{i_0}$ is an $\exists$-$\wfs$, we get that 
$$\exists_{x \in \chi_0(i)}\big(P((i_0, x)) \vee \exists_{i <_I i_{0}}\exists_{x{'} \in \chi_0(i)}Q((i, x{'}))\big),$$
hence $\exists_{x \in \chi_0(i)}P((i, x_0))$, which implies trivially that $\exists_{w \in \sum_{i \in I}\chi_0(i)}Q(w)$, or 
$\exists_{i <_I i_{0}}\exists_{x{'} \in \chi_0(i)}Q((i, x{'})).$
In the latter case we define the following extensional formulas on $I$:
$$Q_I(i) :\TOT \exists_{x \in \chi_0(i)}Q((i, x)), \ \ \ \ P_I(i) :\TOT \exists_{x \in \chi_0(i)}P((i, x)).$$
We show that 
$$Q_I(i) \stackrel{\mathsmaller{\mathsmaller{\mathsmaller{<_{I}}}}} \Rightarrow P_I(i) :\TOT \forall_{i \in I}\big(Q_I(i) \To \big[P_I(i) \vee \exists_{i{'} <_I i}Q_I(i{'})\big]\big).$$
If we fix $i \in I$ with $Q_I(i)$, then by repeating the previous proof of $Q_{i_0}(x) \stackrel{\mathsmaller{\mathsmaller{\mathsmaller{<_{\chi_0(i_0)}}}}} \Longrightarrow P_{i_0}(x)$ in the case of $\C X_i$, we get exactly the required disjumction $P_I(i) \ \vee \ \exists_{i{'} <_I i}Q_I(i{'})$. Since 
$\exists_{i \in I}Q_I(i)$ by the conclusion of the last third case, we get by $\exists \PWF_I$ that $\exists_{i \in I}P_I(i)$, hence $\exists_{w \in \sum_{i \in I}\chi_0(i)}P(w)$.
\end{proof}


Clearly, the Sigma-set of the $\D 2$-family of $\C X$ and $\C Y$ is their coproduct $\C X + \C Y$, and Proposition~\ref{prp: basic2}(iv) is a special case of Proposition~\ref{prp: sigmaset}. By Proposition~\ref{prp: sigmaset}(i) in the category $(\exists \WFSet, \StrExtFunRel)$ the Sigma-sets of families in it are not Sigma-objects in the sense of Pitts~\cite{Pi00} (see also~\cite{Pe23}). Notice that the fact that $\pr_1^{\C X}$ is not in $\StrExtFunRel$ explains why we cannot use Proposition~\ref{prp: basic2}(i) in order to show that the Sigma-set of a family in $\exists \WFSet$ is also in $\exists \WFSet$. 























